Object.assign(window.__TXT,{"2500": "（案4）霍乱转筋，肢厥脉伏。防厥脱。", "2501": "（案5）寒邪痧秽，格拒中枢，上吐下泻，脘格腹痛肢厥，脉细，治以温运。高年局势未定。", "2502": "（案6）寒邪痧秽，格拒中枢，致清浊升降不调，上吐下泻，四肢厥冷，额汗脘闷，脉细近伏，舌尖绛根苔黄腻。局势非轻，有厥脱之险。", "2503": "（案7）寒邪痧秽，引动暑湿，肢麻呕吐，形寒发热，舌白糙，脉弦濡数。成疟乃佳。", "2504": "二诊痧秽已止，暑湿未消，口渴里热，舌根黄腻，脉弦而数。再以芳香渗湿。", "2505": "三诊痧后复泻，是暑邪下注，身热口渴，舌白糙，脉弦滑数。余邪未澈，尚虑转疟。", "2506": "四诊痧后暑邪尚盛，转为脾胃湿疟，发必吐泻交作，间日而发已经两度，脉弦滑而数。治以疏和。", "2507": "（案8）寒邪痧秽，格拒中枢，霍乱转筋，肢厥脉伏，上吐下泻，舌白糙。法以温运。", "2508": "（案9）寒邪痧秽，格拒中焦，脉濡弦。防成急惊。", "2509": "（案2）姚初诊体本阴虚木旺，脾失健运，便溏身热，肝失疏泄，腹痛疝气，脉濡弦。法当疏运。", "2510": "（案3）中气不足，溲便为之变。便溏溲涩，脉濡小弦。法当疏渗", "2511": "（案7）寒湿阻中，肠胃乃伤，腹痛便泻，身热肢酸，脉弦滑。法当疏渗。", "2512": "复方湿止而上焦湿热未清，脉弦滑。尚须清渗。", "2513": "（案8）体素阴虚里热，气无依附，腹痛气滞，食积便溏，脉弦数，舌黄腻。阴虚而兼阳亢也，先治其标。", "2514": "姚复方便溏已止，疝气渐消，惟厥阴疏运失司，时觉腹胀矢气，脉濡弦。再以疏气渗湿。", "2515": "复方，前方先录便泻已缓，胃钝神疲，夜寐欠安，腹痛且胀，舌糙，脉弦小数。当治脾胃。", "2516": "（案1）暑湿下迫大肠，痢下赤白，夜寐欠安，饮食式微，脉濡弦。恐成噤口痢。", "2517": "复方痢次已减，腹痛后重未已，脉濡弦。肠胃积湿未清，治以疏渗。", "2518": "（案3）咳呛身热，热迫便积，腹痛后重，脉弦滑数。局势非轻。", "2519": "（案4）由泻变痢，痢下赤白，是暑湿热挟食滞，蒸伤肠腑气血所致，腹痛后重，脘满辄嗳，舌黄腻，脉濡弦。法当疏导肠胃。", "2520": "艺成诊下痢伤脾，土虚木贼，脾失运行之职，肝先乏疏泄之权，遂致遍体虚浮，腹笥䐜胀。饮啖入胃，胀甚难消，矢气乃舒，便通较适。形消神惫，溲少口干，膀胱气化失司，津液不能敷布，苔浮白质光，脉右弦左细，气随血竭，脾土败坏。调治法程，当养营培气，崇土泄肝，佐益肾治水，预防水溢高源，变生喘厥，拟仿景岳一贯煎加减之。", "2521": "（案5）由疟转痢，是经邪入腑，脉小弦。再以疏和。", "2522": "（案6）痢久脾伤及肾，关闸大开，肾败胃阴亦败，已见谢谷不纳，痢次颇多，舌苔剥尖绛，脉小弦而数。治以参苓白术散。", "2523": "（案7）赤痢已经两月，腹痛后重依然，痢次渐减，舌绛苔糙，脉濡数。防成休息痢。", "2524": "（案8）阴虚之体感受暑湿，蒸伤肠腑为赤白下痢，痢经两旬，腹痛后重，胃阴受劫火升，鼻衄喉颡起糜，里热自汗，舌绛苔薄，脉细而数。姑以酸甘化阴，仿生脉大意。", "2525": "（案9）休息痢经年，是脾虚有湿，右臂麻木不仁，脉濡弦。姑先疏运。", "2526": "（案2）黄疸，脉濡，治以疏和。", "2527": "（案4）湿郁留而不澈，太阴受困，纯热无汗，脉小弦。再以清渗。", "2528": "（案1）湿阻中焦，阳明通降失司，脉小弦。法以疏和。", "2529": "（案3）湿著不化，痰气交阻，脉濡弦。治以疏渗。", "2530": "（案4）湿阻气滞，腹痛便赤，脉濡弦。治以疏渗。", "2531": "（案5）便血已止，阳明余湿未清，小溲短赤，脉小数。再以清渗", "2532": "（案8）阳明被灼，湿热熏蒸，目糊微热，舌糙脉数。尚须清渗。", "2533": "湿著不化，痰浊上扰，舌垢，脉小数。治先分利三焦。", "2534": "（案9）气虚湿胜，健运失职，以致消化不良，得食易滞，脾胃受湿所困，神疲力懈，自汗盗汗，舌黄腻，脉濡数。治先疏运中枢，渗湿涤痰。", "2535": "（案1）年近花甲，中阳衰馁，肝木乘间，横克脾胃，因斯受困。脾受之则输运失职，胃受之则通降无权，素胜痰饮，易聚难化，呕恶嗳满，类似呃逆。营卫不和，寒热往来，杳不思纳，夜寐欠安。按脉沉弦小软，舌绛苔剥。证脉合参，病在脾胃，后天生生之气日渐摧残。论治当以补土生金，佐以通降阳明，希冀得谷则昌，附方莅裁。", "2536": "二诊投补土生金，佐以通降阳明，与病机若合符节。据述呕恶渐平，寒热渐退，饮啖式微，寤寐稍安，此皆转危为安之兆，惟高年中虚，痰饮泛滥，阳明容纳无权，贲门窄小，吞咽时或作梗。顷诊脉象沉弦，重按稍振，舌绛苔糜，种种见证不外乎脾胃两经。脾宜升则健，胃宜降则和，脾胃升降调和，气机自然活动。治法当从此著想，无使胃败脾伤，如无他变，录方仍请高明主政。", "2537": "三诊肾为先天，脾为后天，脾胃少元阳之助，脾不能为胃行其津液，水谷精微徒酿痰浊，以致浊饮上泛，呕逆频仍，营卫不和，寒热往来，舌绛苔糜，脉沉弦，较前略振。治法仍以脾胃两顾，扶过春分，自有消息。", "2538": "（案2）血后阴伤木旺，金被火刑，脉虚弦。已经延入损途。", "2539": "（案6）湿蒸热郁，肺金受灼，络道被蒙，咳呛肋痛，脉右数。久咳阴虚，延成损怯。", "2540": "（案10）病后复感，津液受劫，时交湿令，湿郁化热，神疲纳懈，舌中剥，脉小弦。当治阳明。", "2541": "二诊病伤不复，复劳复感，发热形寒，脘闷泛呕，脉弦数。先治其标，后顾生本。", "2542": "三诊感邪已化，里热未澈，胃气似有来复，夜寐稍安，舌仍中剥，脉濡而弦。再以通降阳明。", "2543": "病伤不复，已经数月，内风暗动，夹感风邪，颈项强痛，肢厥类痉，自汗滂沱，脉左弦大。是积虚成损，厥变堪虞。", "2544": "四诊余热渐清，胃气渐复，惟神疲力懈，便难腰酸，脉小弦。由病后气阴未复所致，尚须清渗。", "2545": "（案11）病后元气未复，里热未澈，交阴微寒，脉小弦。首先清养，徐图恢复。", "2546": "复方肺胃痰热殊甚，大肠湿火留连，脉右小滑而数。是属阴虚火旺，以滋清互施。", "2547": "（案13）失血咳呛，肺元自虚，肺火偏旺，喉疼气粗，舌绛，脉芤弦。劳损之基，切宜怡养。", "2548": "（案14）脾肺气虚，饮痰内凝，曾经失血。近复面浮腹膨，脉弦滑数，舌绛。防延入损途。", "2549": "复方咳缓喘平，腹膨渐消，脉弦小数。仍宗原议增删。", "2550": "阳明胃火有余，上干清道而为鼻衄，脉弦数。当清营热。", "2551": "（案2）湿郁化火，蒸烁肺金，咳呛痰红，身热盗汗，脉弦数。姑先清燥救肺法。", "2552": "（案3）咳呛失血，木火刑金，烁络使然，脉右数。法当平木清金。", "2553": "复方投平木清金法，气促较平，咳呛依然，脉右数。再以清降。", "2554": "（案4）失血咳呛，身热气粗，脉右数。法当和络清金。", "2555": "（案5）木火刑金烁络，络破血溢，咳呛痰红，脉小数。法当平木清金，兼调气火。", "2556": "二诊热灼阳络，血从上溢，咳呛痰红，脉芤弦。以和络清金法。", "2557": "（案6）久热伤络，络破血溢，咳呛气促，脉芤弦。法当和络清金。", "2558": "（案7）咳逆伤络，血从上溢，咳痰腥臭，脉弦小数。恐成肺痿。", "2559": "（案9）久咳伤络，络破血溢，血随气载，咯血盈盏，身热气粗，脉芤弦。劳损之基。", "2560": "二诊失血咳呛，肺胃火炽，脉芤弦。以喻氏法。", "2561": "（案10）木火刑金，失血咳呛，脉右数。以平木清金法。", "2562": "（案11）木火刑金，失血咳呛，脉芤弦。以平木清金法。", "2563": "（案12）血随气载，咯血盈盏，脉芤弦。切宜怡养。", "2564": "（案14）木火刑金，失血咳呛，脉左弦。以平木清金法。", "2565": "（案17）血后余热未清，肺金失肃，咳呛痰少，身热便难，舌糙，脉芤弦。再以清泄。", "2566": "（案18）阴虚肺热，肃降失司，脉细数。治以清泄。", "2567": "（案19）咳呛痰红，是木火刑金，脉滑数。法当和络清金。", "2568": "（案20）热伤阳络，血从上溢，脉芤弦。当清阳明，以和阳络。", "2569": "（案21）劳倦阳弛，络伤血溢，咯血盈盆盈盏，胃络抽疼，气逆脘闷里热，脉左芤弦。当和阳络以清营热，惟怡养功夫尤当加意于药饵之预。", "2570": "复方咯血初止，阳络未和，咳痰薄白，脉沉芤弦。再以清营和络。", "2571": "（案22）湿郁化火，熏灼胃络，络破则血从上溢。喉癣则吞咽作梗，脉濡弦。舌黄腻。由阴分不足所致，调养为上。", "2572": "（案23）失血咳呛，肺胃火炽，出痰薄白，脉右濡数。是热灼阳络所致，切宜怡养。", "2573": "复方血止咳缓，热炽于里，出痰仍薄，脉弦数。仍治肺胃。", "2574": "（案24）久咳不已，肺元自虚，木火闪烁，咳呛失血，脉弦。以平木清金。", "2575": "复方血止咳呛未已，脉小弦。再以肝肺同治。", "2576": "（案25）湿热伤络，络血上溢，咳血屡发，脉芤弦。劳损之基。", "2577": "（案26）阳络受伤，血从上溢，咯血脘闷，微觉咳逆，舌尖绛苔腻，脉弦芤而数。以和络清金法。", "2578": "复方咯血未止，木火偏旺，气冲咳逆，火升头眩，嘈杂心悸，脉仍芤弦带数。再以和络清金，佐平木火。", "2579": "三诊咯血已止，阳络未和，虚里穴呼吸抽疼，是血去气无依附所致。脉右小数。法以和络调气，佐平木火。", "2580": "（案27）顿呛不已，挟感屡发，咳甚则痰中带红，脉右数。体素阴虚内热，由热留痰恋所致。以喻氏西昌法。", "2581": "（案28）肺胃火炽，阳明受灼，失血咳呛，脉芤弦。以和络清金法。", "2582": "（案29）久咳不已，阳络震伤，失血气促，脉芤弦。切宜怡养。", "2583": "（案30）痰火烁络，咳呛失血，脉小弦。以和络清金法。", "2584": "前方先录二诊自投疏运中室，便溏渐减，咯痰带红，胃络受灼，脉小弦。当治脾胃。", "2585": "复方三诊湿气渐化，阳明热灼，大便由溏转结，痰中时或带红，脉弦小数。当治阳明，佐和阳络。", "2586": "（案31）热灼阳明，血从上溢，咯血咳呛，脉芤弦。以和络清金法。", "2587": "（案32）迭感咳呛宿恙，失血复萌，脉芤弦而数。治以和络清金。", "2588": "（案33）屏伤阳络，失血咳呛，脉芤弦。以和络清金。", "2589": "（案34）阳络受伤，血从上溢，咯血盈盏，脉芤弦。以和络清金法。", "2590": "（案35）久咳伤络，络破血溢，脉芤弦。以和络清金法。", "2591": "复方失血咳呛，肺火自旺，肺元自虚，脉芤弦。以西昌法。", "2592": "（案36）热灼阳络，血从上溢，咯血盈盏，咳呛痰多，脉芤弦。切宜怡养。", "2593": "（案37）阴虚生热，热灼阳络，络破血溢，鼻衄咯血俱至，脉弦数，舌黄腻。以和络清金。", "2594": "（案1）便血虽止，阴络渐和，惟阳明生气受戕，饮啖式微，少寐神疲，眩晕盗汗，脉虚芤弦。正气已伤，汗脱堪虞。", "2595": "心孚诊阴虚则生内热，脾不统血，交阴身热盗汗，便溏肠红，脉小数。药难速效。", "2596": "（案2）湿火下趋蒸伤肠，肠红腑时红，便积溲涩，脉细弦。势颇纠缠。", "2597": "（案3）赤痢经久不已，腹痛后重，肠风气陷，脉濡弦。肠红是忧。", "2598": "（案4）肠红腹痛，后重气陷，脉濡弦。病在肠胃，难许速效。", "2599": "（案5）宿恙肠红，历久年数，幸胃纳尚可，力能支持，脉濡弦。以驻车丸、脏连丸两种早晚频服，断根极难。驻车丸早晨开水送，二钱五分；脏连丸晚卧开水送，八分。", "2600": "（案1）阴分不足，湿火下趋，为痔血漏卮，脉弦数。以滋清法。", "2601": "复方投滋清法，诸恙较减，脉濡弦。再宗原议增删。", "2602": "（案2）湿火下灼阴络，而为痔漏便血，脉濡弦。以滋清法。", "2603": "（案2）湿火下注膀胱，蒸伤气血为赤淋，脉濡数。治以通利。", "2604": "（案3）劳倦挟湿，蒸精化浊，肢酸头疼，鼻衄身热，脉濡数。当治湿火，兼清阳明。", "2605": "（案4）湿火下注，蒸精化浊，脉濡弦。以刘松石法。", "2606": "（案5）气虚湿胜，湿火下趋，膀胱溲浊尿血，脉濡弦。治以清渗。", "2607": "（案6）湿火下趋，君相火炽，遗泄淋浊并至，脉弦数。治先清泄。", "2608": "（案8）湿火下趋，灼伤阴络，溲血并不刺痛，脉左弦。治以清泄。", "2609": "（案1）水亏木旺，火烁肺金，身热盗汗，肢酸眩旋，脉弦小数。阴虚之体，法宜清熄。", "2610": "二诊自投清熄厥阴之热，以潜阳敛汗，诸恙依然，脉小数。再从血虚生热治。", "2611": "复方胃气得降，厥阳未平，有时眩旋，脉小弦。以钩麻温胆。", "2612": "（案3）肝阴不足，气火风阳上僭，以致嘈杂眩旋，脉左弦。当治厥阴。", "2613": "复方痰蒙肝胆，心肾失交，气火风阳乘间升扰，脉左弦。切宜怡养。", "2614": "三诊心肝神魂不藏，厥阳易僭，少寐惕怵，脉小弦。当治厥阴少阴。", "2615": "（案4）无痰不作眩，由木郁不达，内风暗动所致，脉左弦。以桑麻温胆汤。", "2616": "（案7）无痰不作眩，肝家气火挟痰浊上升，劳倦后眩旋屡作，时有遗泄，脉左弦右部小数。当治厥阴少阴。", "2617": "（案9）惊怖动心，以致眩旋惊惕，脘闷纳减，脉来弦动不和，是心肝之阳失以潜藏也。姑以半夏泻心汤主之。", "2618": "（案10）气虚饮聚，风阳逆举，肢酸流涎，脉沉小弦。是中风之渐。", "2619": "（案2）血虚肝旺，阳明被劫，脘满辄胀，甚则作痛，脉左弦。当治肝胃。", "2620": "（案4）中阳不足，肠为之苦鸣。湿阻气滞，脘满则嗳，脉濡弦。当治肝胃。", "2621": "感寒食滞，肝胃乘扰，腹痛呕吐，舌糙，脉左小数右弦。法当疏和。", "2622": "（案8）胃脘当心而痛，痛及少腹，肢厥汗多出，脉小弦。法当温运。", "2623": "复方阳虚胃寒，肝木上扰，得食运迟，甚则泛呕辄痛，脉左弦。防成关格。", "2624": "（案10）胃脘当心而痛，痛甚肢厥，脉左弦。以仲景法。", "2625": "（案11）湿阻气滞，健运失司，腹痛喜按，脉弦小数。治以辛通。", "2626": "（案12）疟母聚于左腹，气失疏泄，输运无权，得食易滞，以致胃脘辄痛，舌黄腻尖绛，脉弦小数。是阴虚而兼阳亢也，治先疏和。", "2627": "复方形寒甚，胃痛未已，脘满辄嗳，纳食渐增，舌仍黄腻，脉右弦数。再以疏清互施。", "2628": "（案1）气滞血郁，络道失宣，左胁抽疼，脉濡弦。通络调气法。", "2629": "（案2）湿阻气滞，腹痛辄嗳，脉左弦，舌黄糙，足跗浮肿，湿注于下。治当疏渗互施。", "2630": "（案2）湿阻中焦，肝脾不运，脘痛腹胀，面目俱黄，脉濡弦。法当疏运。", "2631": "（案3）湿阻中焦，肝脾疏运失司，腹膨且胀，脉濡弦。肿胀是忧。", "2632": "（案4）湿阻于中，气滞于下，腹胀跗肿，脉濡小弦。再治疏渗。", "2633": "（案5）风湿相抟，面浮跗肿，脉濡弦。肿胀是忧。", "2634": "（案6）血阻气滞，腹膨如鼓，近复阴阳两络俱伤，血从上下溢出，腹笥消而复大，较前尤甚，脉濡弦。从肿胀治。", "2635": "（案7）湿阻中焦，肝脾疏运失司，得食辄胀，肢节酸楚，脉濡弦。当治太阴阳明。", "2636": "（案8）肿胀势减而少腹䐜胀，肝脾疏运失司也，脉小弦。再以疏运。", "2637": "复方姚湿著肝脾，疏运失职，足跗浮肿，渐入少阴。曾投五皮饮，肿势渐消，脉小弦，仍宗原议增删。", "2638": "三诊肝失疏泄，脾失运行，跗肿腹胀，脉濡弦。当治厥阴太阴。", "2639": "（案9）湿阻中焦，肝脾疏运失司，腹胀跗肿，脉濡弦。防成肿胀。", "2640": "投五皮饮肿势稍退，腹胀依然，脉濡弦。仍宗原议。", "2641": "三诊湿阻中焦，肝脾失运，得食辄胀，跗肿便溏，脉濡弦。防成中满。", "2642": "三诊姚肿势渐消，肝脾疏运依然失职，得食辄胀，脉濡小弦。是湿阻气滞，切宜调养。", "2643": "（案12）湿阻气滞，腹膨如鼓，脉濡弦。恐成中满。", "2644": "湿阻中焦，肝脾疏运失司，跗肿腹胀，色㿠形寒，脉濡弦，腰圆脐凸，调治不易。", "2645": "（案15）肝脾疏运失司，腹膨且胀，脉左弦。法当健运。", "2646": "（案16）疟发连枝，身热痞聚，腹膨且胀，脉濡软。防成单臌。", "2647": "复方疟止痞聚，腹膨稍软，脉沉濡弦。再以疏导法。", "2648": "（案17）寒凉伤中，中阳虚馁，肝脾失运，腹胀如鼓，舌光绛，脉弦数。单胀是忧。", "2649": "（案21）阳虚饮胜，聚痰湿内留，脾失运行，腹膨跗肿，脉沉弦，腰部酸楚，病在脾肾，以仲景法。", "2650": "（案23）伤于湿者，下先受之。由足跗浮肿渐及一身，脉濡弦。病名风水，以开鬼门洁净府法。", "2651": "复方前方先录湿阻中焦，肝脾疏运失司，自投疏运中室，肿势渐消，脉濡弦。再以温中利湿。", "2652": "三诊湿郁不达，肝脾失运，叠投疏气渗湿，胀势渐消，脉濡弦。仍宗原议。", "2653": "（案24）湿阻气滞，瘕聚肠鸣，脉濡弦。恐成中满。", "2654": "（案25）湿阻中焦，肝脾失运，腹膨且胀，脉濡弦。单胀是忧。", "2655": "河白证输运未复，脉濡弦，当疏运。", "2656": "（案28）宿恙肝胃，近复湿困太阴，腹膨如鼓，脉小弦。难许完善。", "2657": "（案29）湿阻气滞，肝脾失调，脘满辄胀，神疲力懈，脉濡弦。治先疏渗。", "2658": "（案30）失血后肝气被痰湿所阻，腹膨且胀，脉弦滑，防成中满。", "2659": "（案31）体肥多湿多痰，嗜酒伤阳伤气，阳虚不能通调水道，下输膀胱。气虚之处即湿浊灌塞之所，以致脾不运行，由足跗浮肿渐及面部。曾经便血血泄，肿势稍退。顷诊脉象，右寸关小弦而数，左关尚弦，两尺微见数象。症脉相参，脾胃之湿浊尚盛，肝家气火多升少降。论治当淡渗太阴阳明之伏湿，佐以调气疏肝，惟年逾花甲，气血难免受亏，至怡养功夫尤当加意于药饵之预，附方呈请裁改。", "2660": "复方水肿一候，大都属于太阴，脾经主四肢而司健运。脾弱湿生，湿阻中室，真阳不运，寒气乘之，浊阴凝聚而为哕为肿也。夫脾与胃为表里，胃不和则水饮泛滥，上泛为口涌，下注为便溏。前投黄连半夏汤加减，适值肿势消退之际，仅渗脾胃之伏湿，热潮起伏，是肝家气火上升。按脉右寸关小数，左关尚弦，舌苔黄腻，是肝升太过，胃降不及也。治先和胃平肝，以顾水饮，使阴平阳秘，精神乃治。", "2661": "（案32）湿阻中焦，肝脾不运，宿恙臌胀时起时伏，已历年数，近复湿注膀胱，下部遍肿，脉濡数。调治不易。", "2662": "（案33）投疏运肝脾，腹部肿胀依然，脘满食减，脉仍濡数。是湿阻气滞，臌胀是忧。", "2663": "（案2）湿阻中焦，肝脾疏运失司，下灼阴络，腹膨便血，脉濡弦。蛊胀是忧。", "2664": "（案5）血阻气滞，肝脾失运，瘕攻腹胀，舌白糙，脉弦数。防成蛊疾。", "2665": "（案1）品珠诊咳痰如桃胶，是热伤膈络所致。眩旋而心悸，乃营阴亏乏使然。脉小弦而滑。先宜治肺为急，拟千金方。", "2666": "（案2）病伤不复，咳呛痰稠，气粗身热，舌绛苔剥，脉弦滑数。防入损途。", "2667": "（案3）咳逆伤络，血从上溢，咳痰腥臭，脉弦小数。恐成肺痿。", "2668": "（案4）肺热叶焦，咳痰臭秽，脉右滑数。恐成肺痿。", "2669": "（案5）失血咳呛，肺热叶焦，出痰腥秽，脉弦。防成痿躄。", "2670": "（案1）风湿相抟，肢节脉络酸楚，神疲力懈，胃钝纳减，脉濡弦。以仲景法。", "2671": "（案2）年逾花甲，中阳渐衰，肝木犯胃为脘痛，痰阻络道则络痹。脉小弦，苔根腻中剥。姑先疏理肝胃，佐以和络。", "2672": "（案3）体肥多湿多痰，气虚饮胜风胜，痰饮凝聚，内风暗动，偶受感触，语塞神糊，脉沉弦，舌腻。花甲年迈，怡养为宜。", "2673": "震泽汪子敬诊便前血病经半载，营阴内耗，致大腑燥结，腹踹浮肿，眩晕耳鸣。火升心悸少寐，脉弦舌绛。治宗柔养。", "2674": "复方肠痹腹胀，胃纳尚振，腰酸带淋，心惕耳鸣，脉弦，舌淡绛。嗌非跗肿，脾脏伤矣。", "2675": "（案5）风湿窜经筋入络，右臂及膝红肿酸疼，脉濡弦。兼有寒热，属流火一类，以木防己汤。", "2676": "（案1）惊怖动心，心悸目直，脉迟弦。是心肝神魂不藏，防成怔忡。", "2677": "又初诊无痰不作眩，眩旋心悸，脉濡弦。以桑麻温胆汤。", "2678": "（案2）操劳过度，营阴受耗，心肝之阳偏亢，以致语言错乱，神识时糊，脉左弦。是怔忡之渐，切须怡养。", "2679": "（案1）病后元虚，气无依附，痞聚腹痛，痛甚肢厥，汗出舌糙，脉弦滑数。以三甲饮子。", "2680": "（案2）形寒身热，痞聚腹胀，脉濡弦。由寒湿气滞，以仲景法。", "2681": "（案2）阴虚湿郁化热，热迫大肠，营卫迭偏，身热便溏，鼻衄盗汗，脉弦小滑。以清骨散。", "2682": "复方投清骨散热势较减，疟退便溏亦止，脉小数。仍宗原议增删。", "2683": "三诊疟久阴虚，身热盗汗，脉小弦。法当清养。", "2684": "（案3）阴分不足，骨蒸劳热，盗汗咳呛，痞聚腹痛，脉小弦。以清骨散。", "2685": "壹诊阴分不足，肺失清肃，咳呛盗汗，身热纳减，脉右数。法当清泄肺胃。", "2686": "复方投泻白法，身热渐退，咳呛亦缓，脉右小数。仍宗原议增删。", "2687": "（案4）阴虚生热，火烁肺金，咳呛盗汗，脉右数。法当清泄。", "2688": "（案5）阴虚生热，脾弱便溏，脉数。以清骨散大意。", "2689": "（案6）阴虚骨蒸内热，痞聚腹胀，鼻衄肢酸，脉小数。调治不易，以清骨散。", "2690": "复方投清骨散，寒热已止，痞聚渐消，脉仍小数。再以毓阴泄热。", "2691": "（案7）阴虚里热，外感易侵，脉右数。以清骨散佐玉屏风散主之。", "2692": "（案8）酸疟后阴分延虚，里热盗汗，脉小数。以清骨散。", "2693": "投清骨散，里热减而未澈，盗汗痞聚，脉小数。仍宗原议增删。", "2694": "（案9）阴虚火旺，喉疼且肿，脉小弦。当治太阴阳明。", "2695": "（案10）阴分不足，热自内生，痞聚盗汗，脉小数。以清骨散。童痨是忧。", "2696": "二诊投清骨散，里热稍减，痞聚腹痛，脉小数。治以疏运。", "2697": "（案1）阴分不足，热自内生，饮食不节，物腐生虫，腹膨如鼓，脉细数。童痨是忧。", "2698": "（案2）阴虚生热，得食易滞，物腐生虫，腹膨且胀，脉小弦。治以疏化。", "2699": "复方腹膨且胀，筋露脐凸，腹痛泻蛔，身热食滞，脉小数。恐成疳瘵。", "2700": "三诊投冯氏法，下蛔不多，腹膨稍减，身热依然，脉小数。调治不易。", "2701": "湿郁化热，上熏阳明，鼻塞流涕，脉濡弦。由阴分不足所致，从九窍不和咸推胃病治。", "2702": "（案1）阴分不足，热自内生，失血咳呛，串疬盗汗，脉小弦。切宜怡养。", "2703": "（案2）阴分不足，热自内生，颈项串疬，脉右数。以咸以软坚。", "2704": "痰热病已经一月，肺郁不宣，肝热不退，日必痉厥数次，脉弦数。疾急变恐厥而不返，久延防成痫疾。", "2705": "湿热熏灼，耳鸣作胀，身热胃钝，脉濡弦。从九窍不和咸推胃病治。", "2706": "（案1）瘄后余毒未清，熏灼阳络，身热胃钝，脉小数。治宜清解。", "2707": "（案3）时令温痘已露三朝，点粒稀朗，咳呛鼻衄，脉弦数。治以清透。", "2708": "初诊风温外袭，肺胃先受，寒热脘闷，气粗咳逆，舌黄糙，脉弦数。尚防发瘄。", "2709": "三诊复诊先录温痘初露，面部繁密，四肢稀朗，壮热烦躁，便溏口渴，微咳神糊，舌尖绛，苔糙罩垢，脉弦数。疾俾得以浆充满，粒点放白，方是邪化之机，否防昏喘。", "2710": "（案4）瘄后毒火尚留肺胃，咳呛鼻衄，脉右数。治以清解。", "2711": "（案2）腹痛映及少腹，痛甚拒按，身热畏寒，脉小数。久痛不已，恐成肠痈。", "2712": "二诊少腹痛势稍缓，脉弦未和。仍宗原议增删。", "2713": "（案1）诸气𪱥郁，皆属于肺。咳呛喉疼，呕吐痰涎，脉右数。从三焦咳状，咳而呕逆治。", "2714": "复方咳呛依然，呕逆稍缓，火升喉疼，脉右数。当治肺胃。", "2715": "（案2）痰火留肺，肺气𪱥郁，咳呛气促，脉右数。治以降气涤痰。", "2716": "（案4）周。血虚生热，火烁肺金，形寒身热，咳呛痰稠，舌白糙，脉右弦数。是木火刑金使然，人咳恐见痰红。", "2717": "（案5）胎前咳呛，继以产后，肺元自虚，音嘶面浮，脉弦小数。是木火刑金，以西昌法。", "2718": "（案6）体本血虚肝旺，近挟暑风，咳呛身热，脉小数，先治其标。", "2719": "（案7）寒热咳呛，得之产后，脉右小数。防成蓐劳。", "2720": "（案8）产后咳呛，肺虚火盛，脉右数。当养肺阴，以清肺火。", "2721": "（案10）子嗽居经七月，胎火上冲，肺金咳呛气逆，脉右数。治以宣泄。", "2722": "（案12）暑风袭肺，肺气𪱥郁，近复饮食不节，痰阻络道，右胁肋抽痛，发热形寒，舌糙，脉弦滑数。法当通络导痰，兼疏气滞。", "2723": "（案13）血虚生热，痰火蒙肺，音嘶咳逆，脉右数。以清燥救肺。", "2724": "（案14）病伤不复，咳呛不已，脉小弦。以喻氏法。", "2725": "（案16）卫阳薄弱，外感易侵，身热咳呛，脉右数。以玉屏风散。", "2726": "（案17）木火刑金，气粗咳逆，痰出薄白，脉左弦。以平木清金。", "2727": "复方肺阴延虚，木火偏旺，入夜身热尤甚，是不耐炎暑蒸逼，脉小弦，痨损之渐。", "2728": "（案18）失血咳呛，里热形寒，月事愆期，时觉腹痛，脉右数。治先和络清金。", "2729": "复方癸停三月，失血已止，咳呛未已，时觉形寒，脉右数。似属孕象，姑以紫苏饮。", "2730": "（案19）临产遭感，形寒发热，热甚即产，产后热势不退，兼有咳呛脘满，腹胀便结口渴，舌绛苔剥，脉右小滑而数。亟以清魂之属。", "2731": "复方产后感邪渐化，余热未澈，腰部酸痛，饮食式微，脉小数。再以疏泄。", "2732": "（案20）流行性感冒，肺胃吸受，咳呛头疼，脘闷肢酸，舌糙根腻，脉弦而数。以银翘散。", "2733": "气虚饮胜，哮嗽气促，身热痰稠，脉沉弦。以《金匮》方。", "2734": "（案1）春温乘劳倦而发，化热酿痰，邪郁气分，白㾦层出，咳呛痰稠，汗多气促，便难食懈，舌剥尖绛，脉弦而滑。是正虚邪恋，亟以甘凉承津，佐以清养。", "2735": "前方先录投轻清透达法，寒热如疟，㾦点微露，胸脘略爽，汗出颇多，舌糙黄腻罩灰，脉弦滑数。病是湿温胎气，尚在险途。", "2736": "（案2）春温袭肺，化热酿痰，头疼形寒，身热咳呛，舌黄糙，脉右弦滑。姑以宣豁。", "2737": "（案3）秋温失表，病经两旬，邪郁不达，既不成疟，也不发㾦，顷则汗出滂沱，肢厥烦渴，神识昏迷，胸次红疹隐约未露。据述病起天癸适至，邪入血室无疑。舌干绛苔少，脉细而沉。虚弱之体，厥脱堪虞。", "2738": "二诊红疹隐而未露，厥潮起伏无常，汗出滂沱，脉沉虚细。脱象已萌，难图万一。", "2739": "三诊自投桂枝白虎合龙、蛎、复脉，四肢得温，厥潮已止，自汗未至，止形神稍振，脉仍虚细，重按稍有神韵，左关微弦。虽逾险岭，未入坦途。", "2740": "（案4）劳倦阳弛，秋温乘袭，咳呛痰稠，气促脘闷，少腹䐜胀，大便不通，形寒身热，舌黄腻，脉右滑大。高年逆象。法当宣肺涤痰，佐和肝胃。", "2741": "复方高年以右脉滑大为逆，肺胃痰热依然蒙蔽，寤醒时轰热懊𢙐，便溏不爽，舌光苔浮。有昏喘之虞。", "2742": "（案5）痰阻络道，咳痰抽疼，身热烦渴，便通且溏，脉弦数，舌黄糙。再以清解。", "2743": "（案6）冬温痰热上蒙肺胃，宿饮泛滥，咳痰气促，脉滑数。防昏喘。", "2744": "（案1）伏暑旬日，先从膜原外腾为疟，复又转出气分为白㾦，壮热多汗，脘闷气粗，舌灰，脉弦滑数。居经六月，胃府司胎，亟以甘凉。", "2745": "（案2）体素肝胃不和，近复劳倦感寒，挟时令暑湿，由脘痛而致呕吐，胸次白㾦微露，瞀闷神疲，额汗烦渴，舌黄糙，脉细而软。是正虚邪恋，虚弱之体，汗脱堪虞。", "2746": "复方红白㾦沛露，胸项潮热起伏，肝胃不和，呕逆频仍，脘闷神倦，口渴躁烦，舌糙罩灰，脉右小数。邪未尽澈，正气先虚。论治当以肝胃立法。", "2747": "三诊红㾦渐隐，白㾦透露，暑湿由气分外泄。潮热起伏，汗出不多，惟肝胃通降失调，时有呕恶，舌绛灰色已退，脉小弦而数。治以甘凉，佐以芳香，希图转机。", "2748": "（案3）素来体虚，挟感秋温，引动伏暑，病经两旬，红白㾦遍体沛露。厥阳风木乘间升扰，热迫便溏，呕恶频仍，潮热起伏，汗出滂沱。舌黄腻尖绛，脉弦滑数，时觉腹痛，恐瘀凝气滞也。有风动痉厥之险。", "2749": "复方便泻已止，腹痛依然，红白㾦沛露胸项，连及四肢，厥潮起伏，汗出滂沱，舌黄腻尖绛，脉小数。势颇凶险。", "2750": "（案4）伏暑一症，大抵受病于夏，发病于秋。《己任编》名之曰晚发。道远气深，往往不克，迳从膜原外腾。病起天癸适至，加以悲郁伤肝，惊怖动心，伏邪不自外达，逆入血室。一候成潮热起伏，汗出不衰，㾦点微露，气分之邪虽从外泄，营阴之热盘踞不澈，症见彻夜不寐，惊惕抽掣，烦渴恣饮，神识乍清乍糊，舌黄腻罩垢，脉右小数，左关微弦，体肥多湿多痰，症属湿重于热，每易化燥伤津，有液涸风动昏愦之变。姑以芳香宣窍，清营泄热，俾得疹㾦沛露，方是邪化之机，附方候裁。", "2751": "（案5）风寒外袭，先起喉痛，继则颈项两臂风痧沛露，热甚有汗，并不咳呛，舌尖起刺，脉右滑数。天癸适至，尚防邪入血室。", "2752": "（案1）湿伏三阴，发为痎疟，头疼泛恶，肢酸腰痛，脉濡弦。法当搜剔络邪。", "2753": "（案2）疟发不畅，邪留不澈，潮热起伏，汗出不衰，脉弦数。治以清透。", "2754": "（案3）疟发不畅，湿留胆胃，扰动肝邪，脘格泛恶，脉弦数。仍以和解少阳阳明。", "2755": "（案4）疟发太多，气阴延虚，眩旋耳鸣，神疲力懈，脉虚弦。高年尚防热象。", "2756": "复方疟止气阴未复，精神委顿，脉濡弦。徐图恢复。", "2757": "（案5）怀珍足月，偶感寒邪，腰酸腹胀，形寒发热，舌糙，脉弦滑。以紫苏饮。", "2758": "（案6）外感风寒，内停食滞，引动伏湿，形寒发热，脘格泛恶，舌干绛尖糙，脉弦滑数。法以辛散。", "2759": "（案7）疟后震伤胎元，腰酸带下，脉弦小滑。防半产。", "2760": "（案8）平素嗜茶，阳气久耗，近复感寒，引动伏暑，湿从膜原外腾为疟。疟发连枝，肝邪上扰，盖疟必动肝也。大便时结时溏，是中气不足也。半月来疟魔退舍，厥阳未平，有限津液已受劫夺，渴喜热饮，烦躁脘满，潮热起伏无常。舌绛苔剥尖浮白，脉右小弦而数，左关弦象尤甚。症脉合参，病在肝胃，最虑液涸风动变幻，附方莅商。", "2761": "（案9）疟后余湿未澈，肝木偏旺，右胁抽痛，形寒脘满，脉濡弦。治以辛酸。", "2762": "（案10）湿著胆胃，寒热继于间疟，是邪从膜原外腾，脉弦数。治以和解。", "2763": "耀庭诊产后月余，营气不充，八脉、太冲亦惫，致恶露久停。痎疟十发无汗，寒热并甚，肢节酸楚，脉细弦数搏指，苔薄糙，拟充三阴之营气，兼固八脉之太冲。", "2764": "（案12）胎前寒热，炽伤胎元，不足月而产，产后寒热复来，反增咳呛便泄，瘀凝少腹攻痛，脉弦数，汗多，势非轻藐。", "2765": "复方疟退，小有寒热，是营卫迭偏，泻止瘕散，惟咳呛，少腹抽痛，卧醒时轰热，舌腻，脉小弦。再以通络导痰，佐和营卫。", "2766": "（案1）劳倦引动伏暑，但热不凉，咳呛少痰，热迫便溏，舌黄腻，脉弦数。法当清解。", "2767": "复方热势转剧，白㾦隐约，咳呛痰少，热迫便泻，舌黄垢罩灰，脉弦滑数。有昏喘之险。", "2768": "（案2）寒邪外袭，湿热内留，舌垢脉濡。以栀豉汤。", "2769": "宿饮哮喘，挟感秽痧，痰饮泛滥，喘促不相接续，吐泻腹痛未已，肢厥汗出，脉沉弦。喘脱堪虞。", "2770": "（案1）食滞不化，消导过度，脾胃受戕，便泻腹痛。刻下虽便泻已止，脾胃生气未醒，脉小弦。高年切宜调养。", "2771": "复方泻后转为便结，浊饮泛滥，气促咳痰不爽，夜寐欠安，舌白腻，脉弦滑数。治以降气涤痰。", "2772": "前方先录自投理中汤合生化、失笑之属，恶露已通，呕逆得止，腹痛便泻依然，脉虚弦。局势非轻。", "2773": "复方产后泄泻，自胎前得来，已经月余，腹痛已缓，夜寐不安，交阴身热口渴，舌光绛苔剥，脉来弦滑而数。当顾脾胃。", "2774": "（案2）产后挟感，初起呕吐，继则身热便溏，恶露少通，少腹攻痛，神疲少寐，舌白腻，脉弦小数。亟以健脾逐瘀，徐图转机。", "2775": "复方便泻已止，形寒身热，脘闷气粗，少腹作痛，恶露少通，舌糙尖绛，脉弦小数。得之产后，调治不易。", "2776": "（案3）土不生金，咳呛便溏，寅早尤甚，脉小弦。当治脾肺。", "2777": "（案4）居经五月，迭感寒邪，腹痛便溏，脉弦滑。治以疏和。", "2778": "（案5）胎前咳呛，继于产后，是木火刑金。近复脾土受侮，腹痛便溏，脉小弦。恐成蓐劳。", "2779": "（案6）产后肝脾失运，腹痛便溏，跗肿面浮，脉濡弦。治以疏和。", "2780": "（案1）前方先录痢次稍缓，腹痛后重，脘满辄胀，眩旋腰酸，脉濡小弦。再以疏渗。", "2781": "（案3）痢下赤白，腹痛后重，身热脱肛，烦渴泛呕，舌干绛，苔起糜点，脉弦小。痢久脾伤，胃阴劫夺，治难速效。", "2782": "复方痢次渐减，腹痛后重，气陷脱肛，舌剥干绛少津，脉小弦。再以补中益气之属。", "2783": "（案4）居经六月，腹胀且痛，便积后重，脉弦小滑。治以疏和，防胎坠。", "2784": "（案6）暑湿热挟食滞，蒸伤肠腑气血，为赤白下痢，腹痛后重，脉濡弦。治以疏和。", "2785": "复方复感食滞，赤痢复作，腹痛后重，脉濡弦。恐成肠红。", "2786": "（案1）前方先录二诊泻止，恶露亦停，脘满嗳酸，得食辄胀，脉濡弦。胃失通降，肝失疏泄，防延中满。", "2787": "复方三诊投疏运中室，腹胀渐消，便泻复作，寅卯尤剧，脉小弦。当培土抑木治法。", "2788": "（案2）湿阻中焦，疏运失司，腹膨且胀，面浮肢肿，脉濡小弦，苔黄腻。肿胀已成，调治极难。", "2789": "（案3）咳呛肢肿，身热气粗，脉濡弦。当治脾肺。", "2790": "（案4）居经七月，阳明司胎。脘痛辄胀，脉弦滑，肝邪乘扰也。治以疏和，佐安胎元。", "2791": "（案5）湿著不化，肝脾不运，面浮肤肿，脉濡弦。当治肝脾。", "2792": "（案7）血不养肝，肝横辄胀，腹膨如鼓，脉濡数。恐成单胀。", "2793": "复方投疏泄肝脾，腹胀依然，热炽于里，脉弦小数。再治厥阴、太阴。", "2794": "（案1）木郁不达，肺金失肃，肢肿腹胀，咳呛失血，脉小弦。从经旨金郁泄之，木郁达之治法。", "2795": "（案2）年已二七，天癸未至。阴虚夜热，汗从盗泄，近且白带时下，苔白腻，脉细数。取效非易，虑成童痨。", "2796": "（案4）木火刑金，咳呛气促，时或痰红，脉小数。防成损怯。", "2797": "癸停载余，血液枯涸，身热咳呛，脉右小数，恐成痨损。", "2798": "复方寒热已止，月事未通，咳呛有痰，脉小数。防延入损途。", "2799": "（案5）产多伤血，烦劳伤气，气血两耗，营血迭偏，心悸眩旋，瘕攻腹胀，肉𥆧惊惕，形寒轰热，厥阳时僭，四肢麻木，舌糙，脉细虚带软。是虚损之末，似非草木所能获效。", "2800": "（案6）胎前咳呛，继于产后，是木火刑金，近复脾土受侮，腹痛便泄，脉细弦，恐出蓐劳。", "2801": "复方咳缓便溏，后重腹痛肠鸣，舌剥脉细。是产后蓐劳，调治极难。", "2802": "（案7）产后营虚，气无依附，腹笥臌膨胀，神惫里热，脉小弦。久防延成蓐劳。", "2803": "（案8）居经四月，身热形消，有时腹痛，脉细，左右部小数。是血虚气滞，难凭孕象。", "2804": "复方血虚肝旺，木乘土位，营卫迭偏，致脘痛便溏，跗肿寒热，脉小数。调治不易。", "2805": "腹胀且痛，便溏后重，纳减胃钝，里热跗肿，脉小数。当治扶土抑木法。", "2806": "四诊病由血虚癸停而起，继则肝旺腹胀，胀甚则痛，克脾为便溏肢肿，面㿠带浮。历经数月，病势有增无减，顷又痛甚，汗出不已，时觉形寒，舌变光剥，脉来右软，左部小弦而数，是为阳虚自汗无疑。论治当疏肝之气以敛阳，养胃之阴以健脾，希冀汗止纳增，以图苟延。", "2807": "五诊前投生脉散合龙牡救逆，自汗已止，胃纳渐增。节届处暑，重复汗出不已，形神愈见疲惫，四肢有时厥冷，幸痛势不举，泻次渐减，厥潮不致举发。顷诊脉象左右上部俱见沉细而数，舌苔光剥，尖刺以将起糜，是胃阴日渐败坏，肝家气火升腾无制，太阴输运无权，致一身尽肿。据色脉而商治法，仍以急则治标，敛浮阳以顾胃阴。奈脱象已萌，难图万一。", "2808": "（案9）热灼肺胃，失血咳呛，脉右数。防延入损途。", "2809": "（案10）产后营虚，阳不潜藏，脉小弦而软。恐成蓐劳。", "2810": "（案11）平昔勤事内政，不但心营肺卫迭交损，而肝家气火升逆莫制。夫肝与肺为左右升降之道，肝之左升太过，肺之右降不及，以致木叩金鸣，咳呛痰红，历有年数。近年来失血屡发，加以操劳过度，心肝之阳偏亢，时有心悸少寐，自汗盗汗。营卫迭偏，寒热往来，舌苔剥根腻尖绛，脉得左右六部俱见细数。症脉合参，是气血两虚，厥阳气火偏旺，当遵经旨金郁泄之，木郁达之，佐宁心神治法，而怡养功夫尤当加意药饵之预，莅商。", "2811": "（案12）由疟致产后复疟，咳呛面浮气促，脉右滑小数。防成蓐劳。", "2812": "（案13）病伤不复，迭感咳呛，脉右数。久延防损。", "2813": "（案14）去秋产后里热，咳呛迄今，形神日渐消瘦，脉弦滑。恐延成蓐劳。", "2814": "（案1）失血咳呛，已历三载，肺火盛也，脉右数。以和络清金法。", "2815": "复方肺虚火盛，咳呛身热。曾经失血，天癸延期，脉右小数。切宜怡养。", "2816": "（案2）失血咳呛，身热脘闷，脉芤弦。当以和络清金法。", "2817": "（案3）阴虚湿郁化热，肺金受灼，咳呛失血，月事先期，腰酸带下，舌黄糙，脉右数。当以和络清金，兼调八脉。", "2818": "（案4）咳呛经久不已，肺火自旺，痰火尚留，身热痰红，脉右数。治以清渗降。", "2819": "（案5）失血咳呛，形寒发热，脉右滑数。是劳损之基，调治不易。", "2820": "（案6）木火刑金烁络，络破血溢，咳呛痰红，形寒身热，脉弦滑数，舌尖绛苔糙。以喻氏西昌法。", "2821": "复方投喻氏法，咳呛依然，热炽于里，形瘦气促，脉芤弦而数，舌黄中剥。似属劳损之基，切宜怡养。", "2822": "热灼阴络，血从下溢为便血，瘀衃肛门酸痛。热炽于里，兼有咳呛少寐口渴，舌尖绛苔糙，脉弦而数。当和阴络以清营热。", "2823": "复方便血渐止，咳呛未已，脉右数。再以清解。", "2824": "（案1）湿火下趋，热结膀胱，气化窒碍，脉濡数。治以疏泄厥阴。", "2825": "（案2）经来后期，崩漏尿血，是奇经冲任少贮，脉小弦。切宜调养。", "2826": "复方小溲涓滴，兼有尿血，脉小弦。谅系热迫膀胱，冲海受灼。", "2827": "怀孕四月，二便倏闭，脉弦数。以葵子汤主之。", "2828": "血液不足，肝木偏旺，乳旁结核并不红肿酸疼，脉右弦。是肝郁不达，气失疏泄所致生。惟怡养功夫尤当加意药饵之先。", "2829": "（案1）血不养肝，肝旺辄胀，脘痛胀及肩背，甚则呕吐，脉左弦。治以辛酸。", "2830": "（案2）中阳不足，肝木犯胃，晨起呕吐，得食尤甚，甚则脘痛彻背，脉左弦右部小滑。病在肝胃，切宜怡养。", "2831": "（案3）血虚肝旺，中气虚馁，瘕攻脘痛，腹胀气滞，脉小弦。治以辛酸，仿仲景法。", "2832": "（案4）寒热互滞，引动肝气，脘痛肢厥，鼻衄便结，舌糙，脉细弦。当先散寒疏气，得能痛定乃吉。", "2833": "（案5）中阳不足，肝木犯胃，脘痛呕酸，腹胀且痛，脉左弦。由血虚所致，以仲景辛酸法。", "2834": "（案8）胃脘痛，痛伤胆汁，面目俱黄，痛甚肢厥汗出，便闭咳逆，脉左弦。治以苦辛。", "2835": "（案9）血不养肝，肝木犯胃，脘痛彻背，肢节酸楚，脉小弦。以仲景法。", "2836": "复方脘痛缓而未止，血不荣筋，肩背腰疼，脉左弦。治肝首先养血。", "2837": "（案1）中阳不足，肝胃失调，耳鸣眩旋，脉濡弦。当治厥阴阳明。", "2838": "（案2）新产血去太多，虚厥眩晕，不省人事，脉细类伏，防脱。", "2839": "（案1）惊怖动心，心悸眩旋，得食则胀，脘痛彻背，脉左弦。是心肝之阳偏亢也，切宜怡养。", "2840": "（案2）血不养肝，气火风阳上僭，以致眩旋心悸，脘满辄胀，舌糙，脉右弦。当养血润肝，兼和营卫。", "2841": "（案1）少腹积聚攻痛，痛甚肢厥汗出，上嗳下矢乃快，舌干绛中剥，脉虚弦而数。是属肾积，难许完善。", "2842": "（案2）从肾积奔豚治，攻痛积稍缓，少腹辄胀，大便不通，脉小弦。仍宗原议增删。", "2843": "血不荣筋，风淫热郁，四肢酸楚，脉濡弦。治先养血舒筋，再商补调。", "2844": "（案1）血液不足，周行失度，月事愆期，经来悉紫，脉小弦。从后期属寒例治。", "2845": "（案2）张初诊血虚肝旺，冲任失调，月事先后无序，脉小弦。当治奇经。", "2846": "（案3）桂肝肾下虚，经迟带多，湿阻气滞，脘痛辄胀，脉濡弦。法当养血润肝，兼疏气滞。", "2847": "张二诊木郁不达，肺金失肃，咳呛身热，腹痛腰酸，脉小弦。当金郁泄之，木郁达之治法。", "2848": "（案5）血液不足，热自内生，瘕攻腹胀，交阴寒热，脉小弦而数。当治奇经。", "2849": "（案6）血液不足，热自内生，冲任失调，月事两三月一至，腰栙腹痛，脉迟弦。当治奇经。", "2850": "（案7）血虚生热，临期腹痛，腰酸带下，脉小数。当治奇经。", "2851": "复方自投养阴润肝，兼以通经，月事依然不至，并不腹痛，脉濡弦。是血虚气滞，难凭孕象。", "2852": "（案8）半产后冲带少贮，形寒身热，脉小弦。当治八脉。", "2853": "（案10）血液不足，热自内生，心悸眩旋，倏寒倏热，脉小数，舌白糙。以加味逍遥散主之。", "2854": "（案11）血液不足，热自内生，营卫不和，寒热往来，月事愆期，经来腹痛，脉濡弦数。当治奇经。", "2855": "复方投逍遥散，寒热止而复来，腹痛依然，脉小数。仍和营卫，兼顾奇经。", "2856": "（案12）血液不足，木失润养，癸停气滞，腰酸腹疼，脉小数。法当养血润肝。", "2857": "（案13）血虚肝旺，冲任失调，月事先期，身热形寒，脉小数。当治八脉。", "2858": "（案14）产后营虚，肝脾失运，冲带无隶，腹痛便难，月事不调，脉右弦。治以疏肝调冲。", "2859": "复方腹痛未已，脘胀气滞，舌腻，脉濡弦。治再疏和。", "2860": "（案15）体本骨蒸里热，二九天癸未至。近复热灼阳络，咯血脘闷，脉右数。防成倒经。", "2861": "（案17）血虚有热，冲任失调，气滞腹痛，脉小数。当气血两调。", "2862": "（案18）产后崩漏，营阴不足，热自内生，月事不调，脉细数。法当养血调冲。", "2863": "（案19）去岁崩漏，近复癸停两月，里热咳呛，脉小弦而数。防其复萌。", "2864": "（案20）血不养肝，肝失疏泄，腹痛带下，脉小弦，当调肝肾。", "2865": "（案1）产后营阴不足，奇经冲带失调，月事不以时下，脉小弦。当治八脉。", "2866": "（案2）血虚生热，冲带少贮，月事先期，腹痛腰酸，脉小弦。当治奇经。", "2867": "（案3）营虚生热，迫血妄行，经漏脉弦。当调八脉。", "2868": "（案4）血虚生热，气不摄血，上升则齿血咳逆，下注则崩漏带下。舌白腻，脉细弦。切宜怡养。", "2869": "艺成诊烦劳动血，血热妄行，经讯淋漓，腹笥䐜胀，脉右小滑。兼挟外感也，当标本兼顾。", "2870": "复方冲血因热妄行，营阴虚耗，带脉不固，气机失展，脉沉小。当养营阴，以调八脉。", "2871": "（案5）居经四月，屏伤胎元，致令半产，胎留匝月始落。下部及冲任难免受伤，瘀下如崩，月余不断，带多有汗，兼挟感邪咳呛逆，寒热，舌腻罩灰，脉右小滑而数。血去过多，气阴俱伤，最虑汗脱变端。", "2872": "复方投四物汤合龙蛎救逆，瘀露白带俱止，自汗亦敛。惟营卫迭偏，寒热往来，神疲善卧，脉右虚弦而数，舌薄糙尖淡绛，灰苔已退。惟逾险岭，未入坦途。", "2873": "（案1）营不足，气有余，肝脾失运。腹有瘕气，或留著为痛，或逆行为胀，妨碍饮食，阻滞隧道，便艰脘闷，皆由来也。而冲任禀丽不当，任脉又不约束，是以经讯常迟，色紫而淡，白带绵绵，腰脊时楚。近来时有小疟，从中夹杂湿邪。治法宜宗逍遥，以调和肝脾之气营，参入固涩，以收摄八脉之漏卮。", "2874": "复方血虚生热，冲带失贮，气无依附，瘕聚腹胀，月事愆期，色紫带多，时或寒热，脉小弦。以养血润肝，兼顾奇经。", "2875": "前方先录心学诊任脉为病，女子带下瘕聚。溯其源乃营虚血亏以致，木火涵养治法，仍宗原议，略为增删。", "2876": "（案2）居经五月，里热带下，脉弦而滑，曾经两次半产。亟以千金保孕之属，防踏覆辙。", "2877": "（案1）经停两月，瘕攻腹痛，腰酸带下，脉小弦，预防孕象。", "2878": "（案2）疟后气阴两虚，肝木偏旺，瘕攻腹胀，甚则脘痛，营卫不和，倏寒倏热，脉小弦。治以辛酸。", "2879": "（案3）血虚肝旺，冲任失调，瘕攻腹痛，癸停身热，兼有咳呛，脉小弦。切宜怡养。", "2880": "（案4）寒邪伤中，瘕攻腹痛，脉左弦。以仲景方。", "2881": "居经七月，少腹作痛，气滞辄胀，身热口渴，舌淡绛，脉弦滑。是胎气上逼，厥阴气滞也。以紫苏饮子佐安胎元。", "2882": "（案1）居经三月，脘满泛呕，得食辄胀，身热形寒，舌糙，脉弦小滑。似属孕象，以紫苏饮子大意，还祈裁酌。", "2883": "（案4）居经四月，挟感寒邪，脉弦数。治以疏和。", "2884": "（案5）经停呕吐，肝胃升降不调，脉弦小滑。似属恶阻。", "2885": "（案1）产后八朝，恶露少通，复感寒邪，寒热俱甚，腹痛呕逆，头疼汗多，脉弦小数。治以辛散，两和营卫，兼通恶露。", "2886": "（案2）初产两朝，恶露稀少，腹大不收，瘕攻作痛，脉小弦。以生化汤加失笑散，防血瘀上冲。", "2887": "（案3）新产三朝，瘀凝少通，少腹瘕攻作痛，脉小弦。以生化、失笑之属。", "2888": "（案4）胎前便泻，继于产后。新产恶露少通，腹痛胀及少腹，舌糙苔腻，脉弦小数。法当健运中室，兼以逐瘀。", "2889": "（案5）产后百日，恶露少通，少腹攻痛，腰酸带下，眩旋脘闷，舌糙，脉弦小数。瘀聚于内，尚防崩漏。", "2890": "（案6）产后瘀凝不通，月事五月不下，少腹攻痛，聚块形似症瘕，脉小弦。并无弦滑之象，难凭孕象征。", "2891": "（案7）新产五朝，偶感风寒，身热脘闷，腹痛汗多，舌黄腻，脉小弦。以清魂、失笑之属。", "2892": "（案8）产后瘀月余，恶露早断，少腹攻痛，脉弦数。恐成肠痈。", "2893": "一卷末所附独立老人用药方。乃吾翁所受于老人者也。脉论精当。可以为医则矣。故附之。独立者。闽人也。从某禅师东来。寓于长崎。通素灵及本草。善医术。", "2894": "【气郁食滞】一武官江马氏直番江都。忽闻在乡老母病笃。焦虑太甚。夜不成眠。饮食减少。面色惨然。官暇不打话只打瞌睡。乞诊于予。诊之。左沉滑右沉紧时一止。予问曰。曾调理乎。答曰。已服友菊拙斋二医商榷之归脾汤将百帖矣。服之不验。更请太医见教。太医亦劝我多服前药。只令加半夏陈皮二种耳。予曰。此正是严用和治思虑过制变生诸症之妙剂。后薛立斋加远志当归以充肾气。与心血也。且胃气不和。加半夏陈皮之良法也。然以脉论之。良因遥忆令堂病笃。心脾郁结不畅。官事犹冗。不免强飡而应役。早晚不自觉加飡。以故胃有食滞。气不畅达。而不能化也。法曰。伤食恶食。是以恶食而食减少矣。且下经曰。胃不和则卧不安。右脉沉紧。亦是食滞于胃也。法当先以香砂平胃散倍加母姜煎成。日饮数次。以至不恶食气乃停服。晬时然后须以归脾六君子辈补益庶可也。渠中心病快然从之。遂用前法。不月告瘳。或禀上某侯。侯召愚问曰。下药相同。治病有此大异何也。愚对曰。歧伯曰。治病先其藏府。诛其小过后调其气。盛者写之。虚者补之。必先明知其形志之苦乐。定乃取之。侯曰善。", "2895": "【卒中险症】隐士彦阪一竿夏四月。陪大阪布政司某侯于天王寺僧坊午斋。斋罢。回到税官平九郎第中。乃觉心腹不佳。吐出痰涎及所飡斋蔬。忽尔手足战亸。昏不知人。命医工谷村昌安治药越重召青木老医辞不下药。夜将二更。请予至第诊之。十二经脉并绝。四末稍厥。唯脐间动气应手而已。税官请治。予曰。此险症也。虽有治法。不知应否。税官云。子固辞而不药。再敲他门移时也。医及至。病人必绝矣。且自午后用药。至今重病变危。危而至险。唯待尽之命乎。予是其言。乃曰。汝家藏有人参一根。重五七钱者么。税官曰。吾从来未蓄珍药。由医士不我教也。于是催簥回家。择人参重六钱许者。命徒玄三子截去芦梢。只存五钱强。乃撮三生饮计重一钱五分一贴。亲付使者。面嘱云。这人参一根。要全切片。加炮姜五分。与药一并用河水二钟煎一钟。缓缓灌之。口中药尽。再报消息可也。使应诺跑云。翌朝使至再请云。病人服药将尽。天明回生矣。予赴而诊之。十二经脉都应手沉弱。其冲阳太谿应指如蛛丝矣。税官曰。夜来子后灌药三五口。就有生意。丑后四末稍温。寅后脉应手而能应诺也。再劳下药。予回寓复撮前药及人参一根以付于使。第三日复请诊视。视之则六脉机神动荡。唯足脉尚微焉。病者自能言谢灵药苏命之德。税官复请药。予曰。治下名医陪侍者多。今元阳既复。宜命侍医。调理为便矣。税官曰。然则何如。予曰。愚意只将东垣调中益气汤加附子可也。言讫而归。日后差手下高原氏来谢活命之德。次高原氏低声云。前者先生所附人参。一医恐多云。减去一半用之。试一半有效。则再用其余可也。予愀然曰。翌日之人参亦减乎。曰然也。今见先生。闻医减药不怒而反皱眉者何也。予日可惜。许一竿子之命。被庸医暗杀也。怪得十二经脉全复之际。足脉比手脉微甚。吾故教你主人于益气汤中加附子者是也。期三年之内。必卒死矣。曰何以然。予曰明医葛可久善武艺。一日见獏猺。桑弓挽之而彀。归而下血。亟命其子。煎大黄四两饮之。其子恐多。减其半服之。不下问故。其子以实对。可久曰。少耳。今则未也。来年当死也。再服二两愈明年果卒。由是言之。用泻药消瘀。不及其病且死。何况于补药接命乎。谚云。有是病服是药。药不瞑眩。厥疾弗瘳是也。庸医原来弗达这等大义。外假小心而惑人。内装暗毒以妒能。掩其不善。自著其善。欺人欺己。其咎当自执矣。前诊脉时。足脉微甚者。想庸医只用人参上半截。而不全用之过欤。前者吾用全参一根者。欲达表里上下。追复元阳。补接正气之设也。方有生附雄壮下行。安得见此脉候乎。但事既败矣。既往不可咎。子可记取吾言。时至便见也。高原唯然而去。高原者。小徒道因子乃父也。故言及焉。后闻一竿次年四月卒死于尼崎客舍矣。吁嗟。此非庸医暗杀乎。", "2896": "【气中卒倒】河州佃户宗。是年七十三。因赴佛会于大阪婿家信宿。早饭后。忽尔卒倒。不省人事。牙关紧急。身冷。脉沉滑。急请予诊。便以苏合香丸。姜汁调灌之。稍醒而能饮药。时见一妇手捧煎成汤药将使饮之。予问婿曰何物也。曰乃某医使服三生饮也。予急止之云。此乃七情气逆。且因食滞而然。不可妄用急剂以伐无过矣。病者于今人事醒矣。药能啜矣。药病投机。可立待其痊矣。为其生平居乡。不以酒为浆。不以妄为常。守己乐业。安分养性。故年虽七十。比市井放肆之徒。犹未艾也。何必浪投急剂乎。婿曰。是何病耶。予曰凭脉与症。乃似中气。而实食滞也。夫中气症。大略与中风。亦自难辨矣。法曰。风中身温。气中身冷。风中多痰涎。气中无痰涎。风中多有汗。气中则无汗。风中脉浮。气中脉沉。又曰以气药治风则或可。以风药治气则不可也。今夫不论气中食中。一药双治也。将藿香正气散。去白芷。加香附。每一贴重五分。生姜一分。水一钟半。煎八分。作数次服之。何如。婿曰。唯命是从。予撮与服至五贴。诸症平复。改用钱氏异功散收功。撮药时。一僧医常德寺者。见其药之小贴。问曰。世医有议先生之药一贴大则五钱。小则二钱。与今医之药。大小悬隔矣。今此老人。重病小剂。只得五分许者。莫非致疑病候而然乎。予曰。窘哉问也。凡人少壮老其气有弱壮衰三等。故岐伯曰。少火之气壮。壮火之气衰。盖少火生气。壮火散气。况于衰火乎。故治法亦当分三等。其少壮老之人。皆当别处也。示从容论亦曰。夫年长则求之于府。年少则求之于经。年壮则求之于藏云云。此亦分少壮长三等求治之治也。子既是医。何不知乎此。而与世医唯疑议乎药哉。常德曰。某甲今日知成医之道矣。予曰何也。对曰。熟读内经。暗记本草而已。予曰贤者易言。良马易御。子之谓也。", "2897": "【痰喘癍疹】北滨宇和岛氏。年甫十三。患吼喘。声闻阃外。且发癍疹。搔之加痒。使婢数辈。隔生绢按之摩之。其母舅志源翁请予诊之云。外甥生未满月。发小疮如疿如痤。一哑科云。是胎毒也。服以摆药。敷以末药。其毒起伏不已。至于孩笑才痊八九。又变痰喘。而请阪阳儿医殆尽。又访京师出名孺师。莫不求治。治之一旦似痊。过时又作。凡出京者七。赴堺者三。近乡草医。遍请诊视。或针或灸。自孩至于舞象并不脱体矣。未审日后能成人乎。予细视之。精神虽固。身体矮小。年至十三。恍如髫龄。诊之浮弦而促。予曰。经曰夫五藏之有疾也。譬犹刺也。犹污也。犹结也。犹闭也。刺虽久。犹可拔也。污虽久。犹可雪也。结虽久。犹可解也。闭虽久。犹可决也。或言久疾之未可治者。未得其术也。由此论之。令甥未在死症。设得明眼医师下手。安有弗痊之理乎。翁低首以手加额曰。欲烦先生留神调治。痼疾愈日。报恩有地也。予笑曰。报恩且置。只图试药耳。因与大全千金丹三分。磨水食远服一次。喘减十之二。临卧再进一服。又减十之五。次日又进。又减十之七。临卧复进。其夜吼喘定而熟睡不觉至日出矣。翁与父母大喜曰。小儿得病尔来。未有如昨夜之安眠也。请求煎药杜后。予曰。癍疹未痊。须臾服之。以至疹退则停药。晬日然后以汤药荡之。未为晚矣。翁曰。一药能治二疾。甚奇事也。予曰。证变二三。良由外科敷药逼毒入于肌里膜外。溜于胸膈。变成痰涎。因天之阴晦。时之寒暄。食之增损。是皆能令发喘。又发疹也。其标似异。其本一也。所以一药之兼治二疾也。后遂与阎氏和中散去黄耆加陈皮。每贴一钱许加姜枣各三分。煎成日服一贴。至五百余日。脉和而不促。乃止药。或问小儿用药。将及一年有半。无乃过多乎。予曰。三部九候论曰。先去后调。无问其病。以平为期。由斯言之。更服百日。未为多也。此儿盖因屡服退疹驱痰止喘杂霸之药多年。故体亦不能长。费调理也。如此焉停药。后身长体胖。日愈一日。一年间。裁缝衣著者三。以至施加首服之时焉。", "2898": "【疟疾伤胃断食】一大夫加纳氏。王牛秋杪于江府患虐。某府侍医酒井三伯与冈本友菊商治。或清或攻。或用独参出入。五十日余。寒热似退。四体羸尪。不能起于眠褥。大小便时令侍士数辈舁出于圊室。又虑风湿再袭。用纸屏围之。劳神也多矣。且恶食气。不食完谷。口舌烦燥。而又吐涎。只饮汤水者十日余矣。其亲友中川氏素知医事。乃问于三伯曰。加纳氏沉疾将两月矣。日重一日。且又断食。未知安否。其脉色何如。三伯曰。外候乃众士目击。其疾沉笃不在言也。论其脉弱甚。盖脾胃绝症也。中川氏错愕日。胃气绝难再生也。易他医如何。伯曰。一任加纳氏之意矣。于是与在府亲戚诸士商议。别请他医。众士一齐原请予下手。中川氏曰。此举是也。吾欲再举一医为之副何如。众亲士曰。敢问其举。中川氏曰。吾所举者。只园顺庵也。顺庵常以师长待北山氏。而北山氏亦以友弟视顺庵也。今大夫病危。非日夜诊视。临时处置。则失机宜。若再一变。则无起日矣。且二人之见。或胜一人之识。未可料也。使顺庵把匕副之。北山氏直言正之。乃一举两得之谋也。众从其言。乃禀某侯临危换医之事。侯然之。遂命召二人同诊。临夜至邸诊之。左微弱。右弦弱。予曰。今夜只用参汤补接。待来晨再诊。而后相议药方可也。众从之。于是翌早天光时候。再到而诊视。时顺庵侍某侯夫人直邸。路遥来晏。适予有某邸之行。日㽷回寓。顺庵乃待予回于寓。曰向诊大夫之脉。与昨无异。乃因日夜阙服。朝来大夫请药甚急。亲士议曰。暂撮一贴先煎。待先生回时领教未迟。以故从众撮一贴。而付之也。予曰是何药剂欤。曰六君子汤加麦门白豆蔻耳。予良久大笑曰。吾由子能解内经。能辨本草。将谓良材矣。临病必也能干。元来只如此耶。曰请大教。曰吾为子述子之臆度可乎。曰诺。曰脾胃怯弱。不能起居。主用四君。吐涎似痰。主用二陈。口舌干燥。润以麦门。恶闻贪气。醒以豆蔻。且夫六君豆蔻。薛己以后。名医借此补益脾胃。医案多多。故效颦也。顺庵曰。实如先生之说。未审有何不是。曰子于端午见俗绘纸旗上的桥辨度乎。顺庵罔措。予笑曰。牛若子右手扬刀。左手举扇。脚穿木履。且踏栏杆。未审都能成功乎。顺庵颇解其事。曰。每闻先生戏论。使小子通身流汗也。其过且置。望先生垂教而改之。予曰。钱氏白术散何如。曰。中有木香未审可乎。曰。此正是张易水教李东垣调中益气方中橘皮之下有云。如腹中气不转运。加木香一分者是也。大夫于今恶食气。唯饮汤者。由腹中气不运也。藉藿香之芬芳。与木香干旋同功。则思食而不恶也。曰若气转而思食。则不用木香而加陈皮何如。予嘉之曰。举一反三者。子之谓也。然方中人参须倍用之才当矣。所以然者。曾闻前医调治。或用柴平。或小柴胡。或截疟饮。或养胃汤。各有人参在乎方中矣。且又别煎独参汤。而间服矣。然则不倍黄参。恐保中气之力弱矣。顺庵然其言。即撮白术散加倍人参。其木香只用一分许怀之。至病家而易自摄之前药云。服三贴。粥饮进。五贴后。颇知谷味。至第三夜有少烦热。次晨又请予议药。顺庵曰。夜来之烦。莫非木香之咎乎。予曰。脉无变易。非药之为也。但多日不食。恐一时喜食。食气浃洽而致然乎。东垣所谓若喜食。一二日不可过食。恐损胃气。而生热也。须薄味之食。或美食助其药力。益升浮之气。而滋其胃气也。然论虽如是。退烦之物。不可不备也。子将加酒芩乎。抑加黑栀乎。顺庵拟议。予解颐曰。子平日强记本草。何不应此期会乎。顺庵默然。予曰。久病未复。脾气未充。苦寒之物。绝不可饵。唯一味竹叶甘寒可充。五七叶清其胃气可也。顺庵大悦。手搭席曰。利名共得者。谓斯事也。如前法出入。谓养五十余日。诸见症平复。六脉和顺。而右关弦脉尚在。予曰须加芍药可也。顺庵曰。当归芍药。曾用数回矣。予曰。何不用酒以砂锅炒香。曰。何也。曰用酒炒香而用土器。则理脾而伐肝。能退土中之木也。曰唯然。他日加纳氏令椿一游翁特差使致谢云。嗣子此番沉痼。遥闻先生用意居多。所以百死之中。而得一生。所谓绝后更苏者也。此恩此德。难以补报者。由先生赐嗣子于老夫。而为送老之乐也云。", "2899": "【飧泄】癸丑春仲小徒元贞报曰。有一野夫。年三十岁许。自天明至门。自诉亲父为患泄泻。五十余日。先发寒热。不食。日夜泄五七度。因请医士调治二十日许。热虽退。而进些粒食。则完谷不化。泄出原物。日将十次。或带血丝。或如泔浆。因求一医。又加腹痛。四体消瘦。不能起坐。又请一老医诊视。医曰痢疾也。泄泻变痢。在法难治。固辞而云。举乡期之必死。兹因母氏痛哭云。尝闻纪州伯父僧某极言门下起死回生之盛德多多。以故母氏流涕云。你为人子。岂无请医救亲之念乎。某云苟有可为。舍身何惜。母云。你忘却伯师常举当时明医乎。某闻之。魂不附体。放下诸事。连夜飞跑。既至潭府。又无申诉之缘。坐以待旦。直至门开而已。且自因由乞怜于小子辈耳。予闻之。出厅呼入相见。见其手足龌龊。粗衣褴褛。著麻裤。舍短刀。膝行俯首而进。徐徐诉自如此如此。予闻之日。就你之言。病乃重耳。吾当拨暇便去。渠大喜。随簥先导。直至岛饲新家村也。父母闻之。含涕欢喜。亲眷莫不踊跃焉。茶罢为之诊视。一如其子之说。然其泄虽久。精明未坏。脉之浮弦而小。脉要精微论曰。病成而变者。风成为寒热。又曰。久风为飧泄。盖风从木化。久风不已。则脾土受伤而下利清谷。病名飧泄也。阴阳应象大论亦曰春伤于风。夏生飧泄。亦此类也。且其乡。四至水田。一带大河。常流不断。其卑湿不待言也。因撮人参败毒散二钱五分一贴。内人参焙用五分。加陈粳米五分。生姜五分。水二钟。煎八分。作三次温服。云良久间其内人哭至吾前云。丈夫不幸将绝。而灵药亦难救济也。予曰。何故乃尔。内人云。即今药成病夫如教服之。一口辄大吐逆。颜变足冷。唯待毙耳。予忆药病投机。安有急变之理。毕竟煎法有弊。乃问曰。水洁净乎。曰净也。曰持药罐来看。其子携至座前。予啜药一口。药极淡而有臭气。揭而视之。乃用旧小袋煎之也。袋小药多。筑而装之。又不先沸其汤。就生水急煎。故其恶臭也。如此耳。予打开药囊。取出一新绢袋而与之。令将前药装于亲囊之中。用苇薪煮之。命子伺候药成。令病人再服数口。病人服之曰。我胸开矣。更服之。曰我心快矣。其妻子新族大服予之定虑。乃叹曰。非神医。岂能知吾辈之误事乎。予回时再撮五贴而与之。曰三日后再通好消息也。三日后。其子来报喜曰。愚父蒙台下神药。病痊十之八矣。予详问始末。而后改用东垣清暑益气汤。每贴二钱五分。仍用人参五分。或去麦门当归。或加粳米粟米。出入增损。六十余贴告瘳焉。至今时馈尝新物色不绝。谓报德也。斯民也。身居野外。义胜士子者多矣。", "2900": "【泄泻】河州佐藤善性年七旬。舁病来寓求治于予。医士善龙相随。详言得药始末云。三年前。中元后。伤于冷面。吐泻交作。用香砂六君辈。吐止而泻未止。法眼山田元真以胃苓汤而泻止。厥后凡食冷食。或多食辄泻。元真以为脾胃虚弱。以补中益气汤。加砂仁木香之类。凡五阅月。或止或泻。改用参苓白术散。以枣汤调下。泻未止而恶食。故停药月余。去秋请青木玄知老医。用六君木香升麻柴胡服至八十贴许。昼间之泻虽止。夜来依旧泻二三次。腹胁作声漉漉。溏泄如冷水焉。乃去升柴。加干姜。调理半年。颇不恶食。肠鸣虽已。夜泄自若。今春再请法眼元真主药。真曰。老人久病。不宜强责效验。须多服补养中气之药。自有平安之时。又为之灸肺脾肾三俞各五十壮。待灸疮愈再报。前日壮数愈了。复报谓此二俞不可断灸疮也。所以然者。三脏虚甚。非特参术补药所能作效。而除其病根矣。善性然之。孟春始灸。孟夏报之。孟秋又报其泻仍作。甚则夜三昼一。缓则夜行二次。自始至今。经三年所。其泄每夜无间断。故心甚疲困。面色青惨。年且七十。未知老病可能生乎。予诊视其精明未陷。气息自若。言虽轻微。语有收摄。脉之左手关尺弦微。右手三部沉中带弦。予问之曰。素有疝气乎。否乎。曰无。又问耐夏不耐冬乎。曰然。予微笑曰。吾药能生。不死病也。于是撮正传附余当归厚朴汤二贴。以与之。限今旦服至明旦尽二贴。再来诊视焉。次早复来求诊。其脉大抵相似于昨。其面有喜色焉。曰。每夜行圊二三。昨服贵剂。昨夜只通一度。且不觉冷。而只溏耳。自得病以来。饵药不缺人参矣。即今蒙赐之药。甚辣不可于口也。予厉声曰。善性汝能酒乎。曰否。予曰。汝既不饮。则沙糖与𥻓何如。善性自知失言。唯唯而已。予曰。医者诊病撮药。与老吏据案结款相似。故临机会难容一针之私。岂可因口之好恶而失治病之机。乃丧百年之命乎。性曰三年之疾。一旦将痊。喜而不胜。其所以错言者在乎是也。望先生亮之。予遂与前剂二贴。照昨夜服之。次日脉色柔顺。因连与十五贴。泄泻止。面色润。饮食甘。起居便矣。后教善龙调剂黄耆建中汤。百十贴。而得全愈。原方用良姜五两。官桂三两。当归厚朴各二两。上锉每三钱水煎食前服。余应奎云。治肝经受寒而色青。惨厥而泄利者用之。经曰。肾司闭藏。肝司疏泄。肝肾气虚为病泄泻何也。盖肾者。所处在下。大小二便之门户。而肝者。又为门户约束之具。肝肾气壮。则能闭能束。故不泄泻。肝肾气虚。则闭束失职。故泄泻也。又肝者。脾之贼。肝经正虚邪。盛未能制土。亦作泄泻。此当归厚朴汤所以实肝而止泻也。", "2901": "再按前方乃治心腹绞痛如刺。两胁支满烦闷。不可忍之高良姜汤也。四味中只当归用三两。余药数相同也。出千全心藏方中矣。予得余先生之教。凡有腹内久冷肠鸣泄痢。服补脾胃诸药不应。脉之沉弦缓小。症属肝经虚寒者。投之必见其效。因查本草诸说。唯张元素有入足太阴阳明经之言。无入足厥阴之说矣。大明氏有主治转筋泻痢之言者。盖兼入肝脾肾之谓乎。待明者辨之。", "2902": "【痔疾下血】布施氏。年六十余。素患痔疾。庚申秋月。燥令大行。大便结硬。数至圊而不能便。日久下迫广肠。僻裂努出。其痔如榴花然。外科敷药。虽收复发。后用针灸涂抹油膏。因大便时。清血随滴。而痔依旧翻出。肛边生疮。痒而复痛。一医内服外敷。亦不见效。一日登圊。忽下清血不止。事急请予诊视。予至则倒于寝矣。诊之两手俱绝。不及问候来历。令急煎人参五钱许。煎成缓缓灌入口中。少顷。其脉应指如蛛丝然。再三灌之。乃省人事。而能认得人矣。又撮补中益气汤。如脾胃论之方之数复升当归。如黄耆之目人参同之。再加酒芍药。充当归之数。九味共作一贴。水二钟。煎一钟。作三次温服。仍间服独参汤。次早诊之。脉洪而软弱。予告其妻子仆从曰。久痔失血。脉当小缓。今反之者。难复其本欤。别请良医可也。妻子苦求曰。家翁识先生久矣。一旦闻辞药之言。势必再绝。望先生怜之。予不得已再与前法调理三日。病者言行如常。只苦下疾临圊翻出。血丝点滴不绝。且素好清洁。每圊后以温水净洗。而水为之色变。使婢拭干。一任外科敷贴焉。不知外科妄贪速效。以砒矾硝乌枯痔杂药搽擦月余。临圊虽宽。肛门腐坏。肌肉难生。每敷药之时。其气臭如屁者。从魄门冲出。恍如燃薪吹火之势焉。予闻之。谓其妻孥曰。令家翁日飡之谷肉果菜有数。魄门冲泄之气无限。魄门即肛门也。大肠与肺为表里。肺藏魄而主气。肛门失守。则气陷而神去。故曰魄门矣。此虽出外科之妄。或由天命之尽耶。未可知也。吾欲使翁预知何如。妻子闻之失色。含悲而已。他日因收官债而有喜色时。予论及石崇豪富。范丹穷苦。甘罗早贵。吕望晚荣。颜子短命。老彭高寿。六人总归天乎命乎人乎。渠笑云儒不云乎。死生有命。富贵在天。予带笑曰。翁若天命有尽何如。翁笑曰全身葬在某寺足矣。其尝与寺僧有约矣。良久曰。但官债未白。使某过冬收拾官债。付与儿傮。则世事亦足矣。岂贪老耄之限乎。予于是褒。其有超人之见。微笑而别。时十月望也。后易外科付贴稠黏膏药欲保下吹之气之泄少矣。于是每日撮人参养荣汤三钱半。外增新罗参一钱为一贴。其或见他症。如伤食。如感冒。如劳心。如劳动。则易药处治。别煎人参膏以参末调和为丸。每服一钱许。日三。前后计用人参九斤许。及过残腊。朔风匝地。严寒逼人。一如常时。饮啖自若。应酬礼宜。不知怠倦。其收放结算。有家人管理焉。新正启贺停药三日。自觉起居不便。四体无力。口失滋味。目不欲开。言不欲发。心神懒惰。乃云先生尝云人参开胃消食。久服延年。谅不虚也。我停服人参三日。便成死态也如此。惜乎不早知此神草。临死服之。亦能延我百日之残喘耳。予闻之曰。为神农氏左袒者。其在翁乎。病者欢喜。依前服之。数日后。其神气又复常耳。延至仲春之望。忽尔小便不通。自觉便道内无急胀之苦。外无点滴之水。唯溜入广肠随大便而出焉。此乃外科毒药急攻。蓄毒于内。蚀于溺道而致然也。后又腐坏及臀。以至不救焉。前是冬初。与翁谈及生死有分之事。翁愿过冬收债为足焉。故藉大力神草。而补难补下脱之气。假摇光紫气。而延莫延有限之时者。实缘不期然而然之奇物也。详记之。以遗子弟作榜样云。", "2903": "【怒气郁结浮肿】今桥定休年过古稀。精神不迈。收放官债为业。蓄积甚厚。近年来放多收少。忤情逆意。郁滞有日。使抑郁之气留滞不散。停于胸膈。不能流畅。致腹胁虚胀。大肠虚閟。小便涩少。面目四肢浮肿。请后藤益庵调治三月余日。其症弗瘳。更加口舌干苦。饮食减少。或荐予为治。脉之左右沉中带弦。予谓怒气结聚。不得发越。升降失常。遂用古方八味逍遥散。白术易苍术。倍柴胡茯苓。加越桃鞠芎香附醋制每贴二钱。灯芯生姜各二分。流水煎服。五贴许。小水通利。浮肿全退。口舌知味矣。于是改投薛氏归脾汤。仍加越桃鞠芎香附。服五十贴后。脉得动荡。然而弦形尚在。因加酒炒白芍。又使服五十贴。脉症俱和。再去所加三品。及白芍。乃用原方五十贴而停药。时壬申秋月也。癸酉初秋。因追荐亡侄于法华寺。请僧顿写佛经。于老心有所感慨。适僧请小食。强飡数口。自觉心胸不快。急舁归家。忽吐所飡之食。及痰涎黄水。口不能言。眼不识人。昏倒于席焉。幸手下有人。知用人参急煎三钱许灌之。及予诊视。口眼定动。颇能认得亲疏耳。于是再煎人参五钱。炮姜一钱六分。强使缓啜之。又撮香砂六君子汤相间服之。次日六脉俱应。只沉弱矣。再煎参姜如昨。六君子汤少加木香以进。第三日亦照于前调养。厥后或单用归脾汤。或二方合和。直至穷腊停药。前后用人参四斤云。", "2904": "【纵饮冷酒吐血】伊丹性有年四十许。性嗜冷饮醇酒。闻一月前。吐出紫血。倭量三升许。其为人也。勇健而不求医。而乃云我平生所饮冷酒。何翅三升而已哉。若不吐去瘀血。日后生变未可料也。吐去酒瘀。正好多饮。恬不挂怀。任意饮啜不已。一朝又多饮而酒器在手未放。忽又吐出鲜血盈盆。若量之。亦不下壹升矣。命仆将酒来洗我胸膈。言犹未了。又吐鲜血数口。眼黑头旋。忽尔昏倒。时仆从急请青木玄知老医父子齐到其家。议药。其仆有颇学医药名目者云。家主素嫌芳药之气。不待到口。嗅鼻亦呕。望名手察之。老医遂调五味异功散去人参而与之。煎成服之。元气弥弱。手足不能举动。有一世家与渠近邻。又与之雅好。时适予过门。就拉予同往看病。予诊其脉甚微。闻其呼吸不紊。乃大声曰。性有性有。子平素喜饮冷酒不悟。有今日之事乎。渠脉脉不言。予于是用茅花一钱五分。拣参一钱五分。以河水二钟。煎一钟。徐徐服之。即日服一贴。次日又服二贴。进些稀粥。第三日脉色稍和。又教服二贴。与淡粥鲞鱼。如此补养十日许而安。本当多养数日。填补血气。因渠素恶药气故已之。而择谷果肉莱。充其仓廪而已。良由年壮气行而自愈也。或问失血过多。奈何不令多服补气养血之剂。而只服人参不及三两。即便止药。无乃阿顺人情乎。曰。经曰。临病人问所便。渠既不便服药。岂宜强之乎。予所以择其谷果肉菜者。正为此也。藏气法时论有曰。五谷为养者。养生气也。五果为助者。助其养也。五畜为益者。益精血也。五菜为充者。实藏府也。经所谓气味合而服之。以补精益气。此五者各有所利。此圣言可师也。又闻之先师云。药之治病。因毒为能。毒也者。以气味之有偏也。盖气味之正者。谷食之属是也。所以养人之正气。气味之偏者。药饵之属是也。所以治人之疾病也。五常政大论曰。大毒治病。十去其六。常毒治病。十去其七。小毒治病。十去其八。无毒治病。十去其九。谷肉果菜。食养尽之。无使过之。伤其正也。不尽行复如法云云。由是言之。用治之法。在医者眼力定夺。或有未尽。再行前法。以渐平之。宁从乎小心之谓也。", "2905": "【疮疡】泉州藤井法桥道安老母七十三岁。庚戌仲春。发疡在京门带脉之分。大五寸许。法桥昆仲四位。俱显医名于时也。昆仲相议。先用吕洞宾仙传化毒汤。次用托里消毒散。再用精要十宣散。一外科为之敷贴。溃后脓汁清稀。疮口干燥不赤而黯。咽膈不利。咳嗽黏痰。其仲子北村救斋与予邻居于阪阳。请求赴泉。为母诊视。脉之虚弦。予谓诸昆仲曰。令寿堂年过古稀。发疡至今。溃脓多日。血气必亏。须进独参汤。大补元气。间用十全散。或增温中托里之物。或投消痰化毒品。缓缓图之。且元阳未至败绝。饮食不减常日。治不失法。回生可期矣。脉之虚弦。老者之常例。溃疡之当然也。但发于少阳多气。少血之地。似为可虑于收合之际。然而疮口虽阔。根盘似浅。可以动摇。得补托之内服药。灸之外施。或可移于太阳背部。未可料也。法桥昆仲眼眼相觑。唯唯低首而已。予曰。外科书。所谓疮疡灸法。有回生之功。若未溃则拔引郁毒。已溃则补接阳气。祛散其邪。疮口易合。其功甚大。东垣亦云。毒气沉伏者。或年高气弱。若服克伐之剂。气血愈虚。脓因不溃。必假火力以成全功也。遂教以附子为末。唾津和作饼。厚三分。安疮上。以艾炷灸之。使微热不可令痛。干则易之。如困则止。日灸三度。夜以太乙膏每一两加石菖蒲末硫黄末各一钱。牛油五钱。木蜡三钱。一处溶和作油膏。摊在旧绵布。贴于疮上。次日又灸三度。次夜又贴油膏。第三日赤处渐见。至七日夜黯处全消。赤肉渐生矣。于是改用东垣通气防风汤一贴。每二钱许。一日与二贴。仍进人参汤一贴。至三日后。令捣万捶绿云膏摊贴太阳经旨门志室之分。以至疡之小半以吮引之。又制象皮膏敷贴大横腹结及章门。以至疡之大半。以追推之。其上总以加味太乙膏封之。待二日后。剥而视之。其疡将移于太阳经分之势成矣。再如前法敷贴七日。内服补中益气汤。加芍药桂。增胡柴陈皮至十五贴。乃少阳之疡移于太阳之分矣。猗欤药中肯綮。有如是之奇妙哉。其法虽似怪诞。其实远迩共知。故录之以俟好事君子为榜样矣。医中微妙。书不尽言。言不尽意焉。后用生肌膏药贴之。至三月余。疡平而收口矣。寿至八旬余而终矣。", "2906": "【背俞发疡】住吉社僧北之坊年六十余。疡发于背之上下二处。上乃风门。肺俞。厥阴俞。魄户。膏肓之际。下乃胞肓。居窌之次。大四寸余。摄泉二州名医。邀之殆遍。补以参耆。则妨碍饮食。托以十宣。则疮口作痛。艾灸桑烙。其病越笃。因请予求治。脉之左沉弦有神。右沉滑流利。闻其为人。性直确。少言笑。常患气滞。或腹胁痞满。或大便秘难等候云。记得陈鹤溪云。凡痈疽不问虚实寒热。皆由气郁而成。经云。气宿于经络。与血俱涩而不行。壅结为痈疽。不言热之所作而后成。痈者。乃因七情有所郁而成也。治之以远志酒。独胜散云云。闻其性格。察其脉色。遂投和剂三和散。全用原方分目。每贴二钱。加香附五分。水一盏煎六分。去滓温服。不拘时候焉。或问前医累用参耆补托。亦未见功。师用此药。当得甚事。予曰。正由是也。此僧乃如陈鹤溪所言之候。而医不先用行气解郁。乃用补托太早。所以壅结于上下二处。虽用艾灼。疮色不活。用补便作痛耳。和剂谓此方。主治五藏不调。三焦不和。心腹痞闷。胁肋䐜胀。诸气壅滞。肢节烦痛。背痛胁痛。有妨饮食。手足微肿。肠胃燥涩。大便秘难等症。故试数贴。观其可不矣。服五贴二便通顺。次服五贴。饮食有味。再服五贴。疮色红活。而不疼痛。再服五贴。痞满渐宽。更服五贴。胸胁大通畅矣。僧喜曰。自服先生灵药。不特今患得痊。乃觉旧疾亦脱体耳。因渠年老。恐香燥过剂。消耗阴血。改用参归耆术等物。便觉举动不安。复用三和散。加当归加川芎之数连服二十余贴。稠脓滚出。而疡口自平满焉。记得丹溪先生云。独胜散。治气郁血滞。而诸疡愈后常服半年尤妙。此皆施于体实气郁之人。予见吴兄厚味气郁。而形实性重。年近六十。患背疽。医与他药。皆不行。唯香附末饮之甚快。始终只此一味。肿溃恃此而安。然此等体实。而又病实乃瘥。千百而一见者也。今此老僧与吴氏元气大同。孰不谓其脓既泄。气血乃虚。只宜纯补哉。", "2907": "【背疡痈毒】阪阳粜米小仓店年六旬许。患背痈。其疡初发时。先于七椎之傍。重著而痒。使婢爬之。其痒不已。因取艾灸之而不觉痛。因求外科处治。外科艾灸贴敷。初如豆大。三两日如掌大。五七日小盆大。至十余日乃发肿。上自三椎。下至一二椎。其阔六七寸许。其肿不高。亦不光泽。法眼元真疑是疽。初用化毒。次内托复兼用独参汤五七钱许。病者胸腹䐜胀。妨碍饮食。且手背足趺微肿。其子恐生变症。冀请予诊。脉之轻缓重紧。予投和剂熟料五积散去麻黄加人参。每服三钱。生姜大枣各三分。羌活黄柏各二分。水一盏半。煎一盏去滓温服。或问其所以。予曰。东垣先生曰。生气通天论云。营气不从。逆于肉里。乃生痈肿。阳阳应象论云。地之湿气。感则害人皮肉筋脉。是言湿气外伤。则营气不行。营卫者。皆营气之所经营也。营气者。胃气也。运气也。营气为本。本逆不行。为湿气所坏。而为疮疡也。此邪不在表。亦不在里。唯在其经中道病也。已上内经所说。俱言因营气逆而作也。遍看疮疡论中。只言热化为脓者也。盖有言湿气生疮。寒化为热。而为脓者。此疮疡之源也。宜于所见部分。用引经药。并兼见证中分阴证阳证。先行营气。是其本也。标本不得。则邪气不伏。言一而知百者。可以为上工矣。由是言之。肿发不高。亦不光泽。虽多服参耆补托。其脉仍缓或紧者。乃湿气所坏。而为疮疡。寒化为热。而为脓者也。经所谓治病必求其本。吾故用之。欲成其事也。或唯然。于是使服三十余贴。其疡将愈时。加黄耆倍人参。又三十余贴收功。", "2908": "晚脉六部俱四动半和。而带弦如条条然。动气或动冲。或升沉如阻饮食。食物不爽快者数日矣。侯觉不容上下。皮厚而气不畅矣。", "2909": "脉两手微弦。两尺微弦而滑。（久拙）上养胃丸。三十不应。", "2910": "十九日卯初脉弦而似长。贵症同前。命众医进药。或拟上香砂平胃。及不换金正气等剂。予正色曰。吾居客位。岂敢妄主药方。冀诸位察其症候。省其平常。用其对症之药可也。虽然。有浅见在。若动气冲不收。则白术一味。断不可轻用。待其动气收。然后随症而用之。则无妨碍于动气也。（年高且气易闭而肾气之动恶燥故）医议已定。遂上正气散。予曰。严寒伤冷。不拘于何方药中。加以姜桂何如。（盖有所思而发不特谓之必先岁气勿代天和之诫）众不允。纷纷议之。乃加木香干姜。予亦不言。（二味虽温治病霄壤）上一贴。（一钱加姜一分半）进小半服。鸠尾下冲动。再进小半服。又加疼痛。侯曰。是药何如此之不快耶。医议欲再进养胃丸。予拒之曰不可。是丸多主攻击消导。前上三十不应。今又再进。此后再进。且侯年高气弱。又无食滞。恐不胜其药力矣。侯然之。命众停服再议。自卯后足膝冷。察听浊。", "2911": "午末医议拟上治中汤。（人参白术干姜陈皮青皮甘草）予曰。是药近于治者也。宜去白术。（前言重出乎此耳治症论在节庵六书入门医鉴书）盖肾间动气冲鼓不息。要急治。不然。则成奔豚矣。（谓动气筑筑然不息冲动如豕之奔耳）加肉桂一种。引火归宗。则动气自收。足膝温暖矣。亥时初进加减治中汤。（一钱姜一分半）一贴三分之二。动气收过半。足膝回暖。脉浮细数六动有奇矣。医疑其脉数。予曰。温药中病。动气将收。寒气将散。脉当如是。然胃欠谷气。脉色不润耳。劝侯强粥数百颗。至子时末脉和五动矣。", "2912": "寅时末。微热至。脉又浮细数。医又疑。各各主意不定。又以前言宽解及乎诸子。", "2913": "二十日。辰时前药进二贴。动气收。足膝温。脉和五动而带弦滑。侯又索药。众曰。药力胜病。恐生别症。劝停药强食。侯以为然。", "2914": "申时末。脉六动许。尺似弦带滑。面瘦倦睡。肌体弱。侯自觉胸胁下似有物相碍腹牵强。医议欲进药选人参养胃汤。（人参草果茯苓苍术半夏厚朴藿香陈皮甘草）予固拒之。考其方曰。草果辛温。厚朴苦温。不宜济乎脉数肌热困倦之候。苍术甘燥。藿香芬燥。未卜用于面瘦体燥牵强之症。半夏之辛燥。茯苓之淡渗。得其助则能理脾气而不偏。失其助则反燥胃液以成伐。参陈甘草。虽能调中州。若佐使不得其正。反增其病。势使然也。吾不言乎此。牵强而痛。动气再冲。还有何手段之治术耶。唯患其后患。不得已而呈其万一矣。医拱手曰。然则奈何。予曰。中侯之病者。温补脾胃。调养气血不滞不偏之品也。虽然。今日药力偏胜恐生变症之际。宜暂进行气香苏散。（去麻黄减甘草）一贴五分。生姜二分。从容服之。待药行气周。风寒及夹饮牵强些宽。再以温平之剂调理如何。医然其说。至夜戌初进小半服。气惕胸宽。而痛不减。微喜按摩。至亥时气行吐留饮一盏许。亥末泄二次。", "2915": "子时初命疹。（加藤氏诊脉五动六部和利贴肉而有力一斋摩腹谓中气想弱腹间弱无碍手者）", "2916": "二十一日。卯末脉五动有奇。似滑而润。侯觉胸满。候之腹间。少有动气。众强药言后自宽矣。", "2917": "午前泄一次。午后吐留饮五盏余。申时又泄一次。（似饮者三五盏）侯问如此吐泄。属甚病因。去冬之患。亦犹是耶。（仙斋有伤湿之语）晚上前方。至夜熟睡。（是日食饮少进）亥时脉和。", "2918": "二十二日。辰初诊脉五动有奇。而和带滑神气和。（巳时尿少清）", "2919": "戌时脉五动余。而和带滑。有动气。在中下二脘。是日食饮少进。言语声清。侯言上脘如有物碍耳。然按之。肌肉间。并无著手者。想留饮之余耶。（是日夜医言上前方二贴）", "2920": "二十三日。卯时脉左和利而滑。有弦势。右三部和利之中。有动荡之形。侯言觉胸膈不快然矣。", "2921": "予谓二十一夜。六君干姜倍母姜作三分。以进者。一以利参气。一以散寒饮之设也。又且本因动气未收。经曰肾恶燥以辛润之。开腠理致津液通其气也。（观乎此古圣之格言焉可不从而自慕耶）不测医不倍母姜。窃添木香。妄自是。及乎察脉审候。疑其药之添病而吐露矣。（药之技至如此）因再劝谕曰。前木香之加。且置勿言。六君之中。去白术加（干姜等分母姜三分）者。药之应病。大有意存焉。白术性燥而闭。闭则气不通。气不通。则痰饮聚而声浊也。燥则胃失液。胃失液则口燥咽干也。脉既利。宜以此方调之。无失治其中也。然滑形之脉。示痰饮之将聚也。当是时也。不可强用治术。宜理正气。补中州为主。间服以参术膏。每二分许。子午二时。津下。或谓既去白术之燥闭。又用参术膏。亦有理耶。予曰然。去之者汤剂也。用之者膏剂也。汤剂性猛而闭气。膏剂性缓而润土。古圣用药之得力者。在于斯也。（上药后一钱贴）", "2922": "晚脉左右五动有奇带滑。（亥后更衣泄止矣）", "2923": "二十四日。辰时初。脉左右六部平静。而流利。大有复元之机。肾间动脉亦静。然而更有邪之余动。侯言夜来顺睡。五体调和。胸胁爽快矣。察听亦清。（日进前药一贴及参术膏三分）", "2924": "晚脉五动静带滑形。心脉躁。想思虑所役耶。或痰将聚耶。（或疝气耶）侯曰。适间小用心耳。（是夜进前方乃参术膏）", "2925": "二十五日。辰时脉左右宁静五动少躁。有上下去来之势。冲阳太谿脉俱和。动气依前未全收。言清色润矣。侯曰。夜间好睡耳。", "2926": "午前命进药。予怀一纸。再待明授。医议欲加减前方乃出愚按曰。连日进二陈参姜。痰气稍不滞矣。尊年容平失调。冬发飧泄。幸今少止。然则养阴之法。不可忽也。经曰。阴者藏精。阳者卫外。阴不胜其阳。则脉流薄疾。阳不胜其阴。则五藏气争。是故调养之法。不可偏胜者。有明训在。考诸二陈善治痰。过则燥血。参姜善调气。多则亏阴。况脉过息尊容瘦燥乎。宜加养血之品于方中。一以润脉息。一以复瘦燥。一以养其阴。则免患来春之痿厥。抑又不失其中矣。脉息润。则阴阳和。瘦燥复。则内外调。养其阴则气血从。不失其中。则气立如故矣。未知众位以为何如。医然之。遂加当归于前方。（进一贴一钱加姜）", "2927": "二十六日。卯时末左五动流利。关带弦滑。右和。关有弦形。左腹有气。自五枢上循天枢左旁直至期门而动。小水自昨不清。食饮如前。虽进不爽矣。愚按左关弦滑。肝邪使然也。腹左气动。木气独专也。小水不清净。腑不洁也。右关脉弦。且食饮不爽。乃木气干乎土而胃气未周也。原有疝症。乘其势衰。左之右之。变其症也。虽然尊年积病不可猛攻。待其势退。肝气复正。脾不受克。自然饮食爽快矣。古曰穷寇勿追是也。（是午停参术膏）", "2928": "申时脉五动和。然而六部中尚在弦势。且停汤药。以饮食调理中气。", "2929": "二十七日。辰时脉左关带弦滑形。余部和。（是夜熟睡）侯问曰。据众医诊候脉既自昨和顺。何其饮食不爽耶。曰言尊诊和者。就其症因而谓也。肝部弦滑。乃知余邪未尽也。虽然有说焉。难经曰。少阳之至。乍大乍小。乍短乍长。难经曰。少阳之气。王于冬至。后六十日。阳气尚微。阴气未退。故长数为阳。疏短为阴。而进退未定也。（察病指南曰独左手关脉如此则谓之少阳胆脉）脉既见少阳生发之机。内养其精气。外调其饮食。则可以指日复元耳。（午上参术膏一分半生姜五分煎汤下）", "2930": "夜酉时脉六部和五动。左关少有弦形。", "2931": "二十八日。辰时脉六部机荡有弦形。左关弦滑。右尺有力。侯曰。清晨漱口误吞熟水。因欲和其水。就食稀粥而使然耶。", "2932": "加藤氏曰。昨晡进膳少许。至更深不消。滞于胃口而胀。命一斋按摩少顷。侯曰。胃口宽矣。可菊诊脉数。至丑时寒热作。少顷寝汗。遂进稀饮少许。而睡矣。予曰昨若进药补养。不至于此也。", "2933": "二十九日。诊得脉五动浮。左似和而滑。右似和而微滑。医佥曰。脉和。予曰不及六部。少机神而上下去来之势微矣。按腹左右宽阔。唯中脘有滞气。似碍指而响碌碌。甫元曰。朝来按腹欠上下之气脉耳。予曰。指哉乎。泉庵曰。痰之聚气之滞也。痰聚则滑。气滞则欠神矣。予颔之。医议进药。予曰。就前方治中汤。（人参干姜陈皮青皮甘草茯苓母姜三分）医曰去白术加茯苓何谓也。予考其方曰。", "2934": "参苓甘草四君之纯良。古人以之调气弱。陈皮国老二味之甘平。局方以之消痰聚。青皮之用何。一以平左气之专。一以安脾下食。干姜之佐焉。一以退虚热与寒。一以调养天和。析而论之。数日食阻。赖以二皮。乃丹溪良法。半夜寒热。用以二姜。亦本草明训。脉欠机神。参甘以补之。腹有碍滞。青陈以平之。茯苓之加。宁其神志。导其丙丁。消其聚饮。清其水也。白术之去。解在前篇。（上药一贴一钱三分之二）", "2935": "二十九日。晚脉五动和利似滑。腹间动气微。肾间动气浮。左腹冲者缓。侯曰。晡后觉鸠尾下宽畅。不日能进食耳。（是午后养庵诊候附耳良久）", "2936": "十二月朔旦。脉六部机神荡动。按之似滑。举之和缓五动许矣。可菊曰。五更巨阙下微痛。瞬间宁定耳。按腹间动气少许。在中脘建里间。（一斋子曰子果不谙常法调理也侯意若是予何敢进曰岂然哉予走笔以答既有降邪手焉无复正才五湖烟景好容我问陶来）", "2937": "晚脉左五动。右五动半。按之有力。举之似涩。（疑何事耶问诸左右不言）按之腹间建里有块。碌碌而响。期门不容水分。俱有动气。独中脘建里最甚。（未时泄而少）", "2938": "二日。辰时脉五动余。按之肌肉。而得似静。佥曰脉和。予谓少气。", "2939": "晚脉五动似静。佥曰和比之数日脉候。今晚大好。独加藤氏为最。予出谓人曰。脉数减动。莫因便后肠胃无物而然欤。明理论曰。病之虚实也。出者为虚。入者为实。自达和十余日。进膳甚少。胃乏水谷精气耳。前泄四次。昨行一次。晡又大通质粕。唯恐仓廪受盛传导数官失职。而不能留水谷矣。经曰。胃满则肠虚。肠满则胃虚。更虚更满。故气得上下。五脏安定。血脉和利。精神乃居。", "2940": "晚诊似和。由欠谷气。使血脉虚而然耶。加藤氏曰。动气静矣。予曰。精气少。中气将惫耳。", "2941": "三日。脉五动余。细滑。动气自丹田起脐旁。中脘不容俱动。左期门尤盛。足趺阳脉浮弱。太谿微。（足趺少浮）", "2942": "晚脉五动零。细滑。佥曰。幸脉如常矣。侯曰。脉既和。膳焉不爽。佥曰。天寒雪冻。因之不顺也。予曰。言脉宽者稍与病相称也。脉似沉和乃少膳。及更衣之多。因之如是耳。自朔晚大同小异。动数未减矣。", "2943": "四日。辰时脉五动。似和静。少上下去来机神。佥曰。大好动气不息。", "2944": "晚脉五动似辰脉。佥曰和。予出谓众议论不一。动气如晨。侯曰。食物则胀。未知何理。予曰非小人之所知。（养庵独主药方无所考也）侯曰然。", "2945": "五日。午后脉五动。冲阳太谿脉有力。（对元伯论症与田井氏看脚及肢瘦等）", "2946": "六日。午脉左右五动。机神流利。自朔晚脉失调未诊如今之机神矣。冲阳太谿有力。动气在中脘建里宗气脉应手弱。予谓药必去其攻剂欤。且某次君回乡因兹使然耶。", "2947": "晚脉五动无力。气口涩。次君细问症候。予曰。虽曰自十八日未逾两旬。闻初冬中浣外感以后。将及五旬日矣。尊年气弱。药草更治。中气必也劳倦。膳微多日不及半斤。自初三日。足趺虚浮。肢体困倦。先朔日后不闻神方。唯诊其脉。脉色甚变。症候参差。不知其所自矣。按难经曰。虚为不欲食。评林曰。但食与不食。系乎虚与不虚耳。夫脾者。为胃行其津液。磨胃中之谷。主五味也。脾既虚。则转输失职。而饮食不磨。食不磨。则胃必因而病。故有必腹痞满。脐腹作痛。或恶食。或飧泄。口不知味。四肢倦怠。发热憎寒。可见脾伤胃亦伤也。此古人之格言。今侯之违和。与夫前言。初则小异。今则大同。过于斯者。足趺虚肿。动气不息。乳房干燥。体瘦声低之数症矣。其可以反其治。以用其消食止痛燥土之剂哉。此数端君莫嫌过于惧耶。程氏有云。圣人临事而惧。儒曰一则以惧。况愚而自是不远虑乎。次君曰。足趺之肿。或曰湿。曰气。未知孰是。曰高年缠病。饮食不爽。乃脾土之气虚。不能藏太阴之湿。夫饮食入胃。无非湿土之化。脾弱不能克制。则变邪泛滥妄行。故先注足趺四末而浮肿矣。口不大渴。二便皆顺。明非外邪所袭。乃土中真气不实。而假邪使然也。易曰。至哉坤元。万物资生。此古圣补养中气。以土为万物之母者也。若土一亏。则五藏百骸。皆无以受气。日增羸弱。而趺肿。乃脾气不能运行矣。曰。既若是。当用何法。曰新病久疴。治法不同。先圣明训。载于方册。焉用赘为。", "2948": "七日。卯时脉左右四动半有奇。", "2949": "晚脉左四动半有奇。似滑。右四动有奇。似涩。予曰。动气上乎左。谷食碍乎胃。及问候不差。", "2950": "八日。晨脉四动沉静。动气在中脘下而静。", "2951": "晚脉四动半似滑。动气在中脘而静。", "2952": "九日。晨脉五动。左躁右似滑。侯曰。夜来心动矣。足脉静。右趺肿退些。午四动半弱。晚同。", "2953": "十日。巳末脉五动弱。趺肿进太谿脉微。侯曰。此二日食物如嚼砂。胃口不快矣。想邪气似退。唯脾胃不和耳。医诊如何。予曰诚哉明哉。", "2954": "晚脉四动半有奇。弱似涩。侯曰。服参苓白术散可乎。予曰可。侯曰。异功散加升麻柴胡苡仁可乎。予曰不知其可不可也。侯曰。参术膏𫆏。予曰不可阙也。", "2955": "十一日。脉五动弱。中有上下之神。动气降于脐之上下四围。足冲阳太谿无力。宗气应手。气冲和。趺肿退三之二。按前一日。侯曰。吾病不似常例。口不渴。头不眩。心不怔。二便无碍。唯觉四肢无力。食物不味。乃病在脾胃也。众宜细察云云。昨夕又曰。吾服参苓白术散也。朝又曰。此症服归脾汤之候也。（众医枉措予大叹服）少顷。加藤氏传命曰。异功散。虽能补土。胃口觉燥。加陈米何如。众感服。予走笔书曰。（几句病因出自然始知高杰拔群仙延龄岂假俗人力方信壶中别有天）", "2956": "晚脉左右五动。气口似有生发之机。人迎以下。似有疾在。", "2957": "十二日。辰脉四动余。不流利。按之浑浑然。侯脉从来天晴则清。天阴则浑。予尝试之。果验。不知所以然而然也。", "2958": "午天霁。脉色清。五动弱。", "2959": "十三日。早脉五动半有奇。浮弱。两尺极无根。", "2960": "晚脉五动半有奇。浮弱数而散无根。尊侯大疲。众医不及言候而退。欲进方药。并无一草之上试。唯皱其眉。糊其口耳。", "2961": "夜深。次君及家宰并诸武卫数十员。迫予撮药上进。予何医哉。敢尝关系大任耶。固辞而退。前是午诸武卫请次君上厅召众医相议调治。或俯首。或默口。一无启齿者。又召针医元伯者。伯曰。今日动气止耳。腹虽软弱。是药力将应而然耶。予曰。尔言动气者。盖陶节庵所论之动气欤。谓其人本有痞积。被庸医误试攻击之剂。以致痞块冲动奔走。筑筑然不息。如豚之奔。得其治则安。失其治则危之说也。方侯之动气。不似前论新症。乃二十年旧疴。升浮降沉不时。况此番未有止治之法。何动气一止如是耶。莫正气内亏。气血不能守卫。而邪气亦无力以动。因此外候假似宁静乎。伯曰。未可知也。予因言于诸医曰。侯之违和。虽曰唯脉是诊。由乎数变其候。或弦数浮滑。或微涩迟弱。或失上下机神。或无去来动荡。因药攻补。因食多寡。随早随晚。并无一定之候者。想病势之使然。及其精微。匪吾傮所明察。必也待其圣于医。神于脉者出。而后决矣。阁是勿言。且论外候数端。与众共议焉。侯之尊庚八旬。一也。动止常弱。动辄感伤。二也。容平肃燥。大失调理。三也。食饮减少。四也。日渐羸瘦。四肢骨立。五也。动气不息。因时系动。六也。脚趺虚肿。七也。痞疝牵痛。痛则疲倦。八也。数成溏泄。九也。痰饮时。作十也。天寒气冷。时令不顺。十一也。山野感伤。日经五旬。未有确治。变成数症。绵缠不脱。十二也。不得明医。病由何痊。十三也。此数者。乃众人目击。不特医者。虽樵牧亦知之为重病矣。其营卫气血经脉脏腑之虚实。及乎气运往复。土地异宜。标本得失。亢承害制。阁之勿论。待明眼而辨焉。众位侍医。年深必有妙剂。局套愿出国手。而为焉。若再失正治。日甚一日。日疲一日。将颠困之际。安可柱投试剂。而束手坐视乎。众罔答而散。（养庵日待吾诊而进剂耳后闻上四君柴芍而溏再上四君木姜不止）及更深。侯命诊焉。脉左六动余。而浮。机神不调。右浮弱散。侯曰。吾病笃也。尔何袖手耶。不妨为吾调治焉。予不敢答。唯鞠躬而退。次君强撮药上试者数。予不能数辞。同幸庵子泉庵子议曰。据侯数症。原失其调理。变症各出。而成其利害耳。不可以小方单剂所能为也。宜急上人参汤。间上汤药。或上丸丹。察其变而正。看其虚而补。务要活泼。或阴或阳。或正或邪。待其机而应之。则可。若言常套局守。则不可也。二子同其说焉。", "2962": "十四日。脉五动有奇弱。（是日卯午酉三时泄下其色青）", "2963": "午脉五动零弱。（方同前各上一贴）脉不似昨之浮散。至是而敛。且将静耳。", "2964": "晚脉五动弱。趺肿退十之八。动气浮动矣。", "2965": "按侯脉常带弦形。自月初失其常候。脉神混矣。且侯素有疝症。及患肝气。待医以疏肝抑木为主治。昨之溏泄。面候惨寒。其脉浮弱。其色甚青。其发寒热。其痛弦急。共属肝部之症。故用方中当归补肝血。肉桂行肝气。良姜以温肝。干姜以理肝。则疏泄止矣。", "2966": "十五日。脉四动半有奇。似弦形。（左关应之）一斋按摩曰。胃之上口。痰将聚矣。（加藤氏曰制半夏如何予颔之）", "2967": "晚脉四动有奇。左右似弦而缓。", "2968": "十六日。辰脉左似滑。形欠流利。又有神在。（午里见保庵诊）", "2969": "按脉似滑而不利。欠升降不至五动。一斋按摩巨阙间似碌碌之声。侯自觉有物碍于胃口。如阻饮食。此无他焉。食饱入胃。化其精微。上输于肺。脾气虚弱。不能薰蒸。以致精微滞于胃口。似痰非痰。似胀非胀。久则变饮变浊。变溏变肿。或碍于胃口作痛。或阻阑门而响动。可见每经二候。先碍次痛。而后溏则肌如削矣。治以辛温升之剂。辛以分其清浊。温以调其津液。升以提其精微。则胃口宽而碌碌息。碍痛止而饮食进。溏泄和而肌肉泽矣。或曰。前品半良泽粳。既有应机之功。去之如何。予曰不。曰药之成而退。为其品多。反成混杂。姑暂置之。仍加防升梗。借其轻扬升浮舟楫。以就固真之能也。少加砂仁。引其苄梫归宿丹田。调其枢也。", "2970": "十七日。脉四动有奇。有上下之势。无涩弱之形者。药应之耶。病将复耶。（是午前小水清而多内带浊者以谓清者升乎上浊者降乎下耶）", "2971": "晚脉四动有奇。大抵同辰诊。", "2972": "十八日。脉四动有奇。大抵同前。（上人参粳米汤）", "2973": "或问用前方得验良多。固赖杜苄脂耆蓣粳五味之力。何故去而不用。唯剂气药之十种欤。予曰然。吾闻之耳。用药如用兵。方其陈势也。譬之全方多品。犹若八阵大军。左击右击。奇正相应。则不失其队矣。侯之违和数症往复。前者全军以平之。及乎今也。阴阳虽未全周。趺肿退。动气止。肌体泽。脉色正。察听清。唯其食艰进。痞难畅。胸不宽。泄未止耳。暂憩补阴之剂者。若兵之柔也。特遣调阳之品者。如兵之刚也。故用兵者。察其所当击。或强兵突之。或轻骑劫之。所谓攻其不备者也。用药者。明其虚与实。或甘温补之。厚味养之。所谓临机活泼者也。十种之用人参。为主帅以树中营之帜。白术为户部以充仓廪之富。良姜肉桂当归补将军血气。以固其疏泄。陈皮茯苓缩砂辅中军以防痞胀。炮干二姜为先锋。开其道路。则胸膈宽而水饮不滞。甘草者谁。当用武之际。可无国老以辅政。相缓其势乎。待明日刚者柔。逆者顺。合总军以簪貂有何不可。", "2974": "晚脉四动半。上下去来有机。", "2975": "十九日。辰脉四动半有奇。大抵相若。（上前方固真饮人参汤一钱）", "2976": "二十日。辰脉四动半有奇。大抵相若。右气口似躁。而满指下。", "2977": "午鸠尾下疼痛。按之张弦。脉五动半有奇而躁。", "2978": "按侯常嗜鲫。因数症往复。终不敢进。此三日病势似弱。药力似应。脉色不杂。然膳不进为患。因此特上鲫羹以为进膳之设。不意鲫羹滞于胃口而发痛。故用橄榄芦根以解其毒。香砂藿梗以通其气。（通则不痛）橘朴以消其物。（消则不滞）苏梗之用。下其气也。（气下则畅）又曰。香苏之设。一以治其疝。一以通其数贴之药力。一以消其内蓄之腥气耳。（上上一贴停服）", "2979": "晚诊六动躁。痛虽渐止。体倦食减。予又上丸药五十丸。（作三次而进）或曰。是丸性温。不宜上于脉躁体倦之际。未知有见识焉。予曰。侯之违和。每与常异。自一月以来。痛则寒热发。疝气强。溏泄频。以致危急者。有前辙矣。故用是丸。一以固其溏。一以调其疝。虽有寒热。由乎疝溏而发也明矣。又曰。温能除大热。温能调大寒。用之有何不可。体倦食少。乃正气虚耳。待明日宁静。暂留煎成固真饮以进之。未为晚矣。", "2980": "夜子后脉五动余。侯曰倦耳。", "2981": "二十一日。卯时脉五动。尚有昨夜之余气。侯索药。遂上昨午煎成固真饮。或曰。今朝焉不合药。予曰。昨曰之药可也。曰过气耶。曰不妨勉进之。令诸侍官。及诸医知吾用方有理。不为偶中也。侍医士遂温之上。侯觉畅快。体倦自和。", "2982": "午脉五动势似和。保翁曰。归脾料不可忽也。予曰然。晚脉大抵相若。（上人参汤固真饮）夜丑后更衣。湿而不多。", "2983": "二十二日。辰脉四动半有奇。", "2984": "晚脉大抵相若。当日腹和。然舌燥胸满。足趺余肿。", "2985": "二十三日。脉四动有奇。大抵相若。医按胸腹良久。予出曰。今日侯当腹痛矣。及午。侯觉恶心欲吐。医佥曰。何前症之累发耶。予曰不。乃早间按摩良久。寒气所袭耳。进二姜丸二粒。姜汤下。须臾即已。", "2986": "二十四日辰脉大同。（上加味归脾汤人参汤减半）侯曰。舌润耳。", "2987": "二十五日辰脉四动半有奇宁。前方。（加味归脾汤人参汤三分）", "2988": "二十六日脉左尺弦滑而流利。右尺弦而和。可菊曰。右脉好。予曰。立春在迩。宜乎左部之弦得。今日始诊其生发耳。侯曰。五更进粥数口。滞于胃口。服丸蕴含可乎。予曰。似滞而非滞也。侯曰。胀是痞耶。予曰。脉色和流。非其痞也。乃正气聚于气海耳。何用汤丸为。侯曰。试焉。一斋曰。虚里应肋痞降矣。唯带脉为患也。是日舌润言清。胸快肚宽。进膳常之倍。", "2989": "明脉四动半宁。", "2990": "二十七日。脉大抵与昨晨同。", "2991": "二十八日立春。是早脉四动半有奇。有上下之神。无涩弱之形。两尺有神而荡。观察和悦。听之不清。趺肿愈退。冲阳太谿脉和。唯其阴阳气血未周。瘦弱未复耳。", "2992": "按云林龚氏曰。大凡大病后谷消水去精散卫亡。多致便利枯渴。治宜补中益气为要。盖脾为中州。浇灌四傍。与胃行其津液者也。况大肠主津。小肠主液。亦皆禀气于胃。胃气一充。津液自行矣。燥甚者别当以辛润之。（故用肉桂）以苦泄之。（故佐酒柏）及做治周侍御患元气虚弱。心神虚损。饮食不思。六脉虚微。倍用参耆加远志枣仁酒芍地黄麦门。连进数剂得效。公案故方中。全用前品。一以体归脾之料。治心苗之燥。一以润肠胃。顺大便之结也。肉桂独活之使引众品。调其下元。酒蘗地黄之用。以救将绝之肾水也。又独活五加。行气于下部。退其虚肿。兼同地参补肾元也。", "2993": "晚脉四动半。有上下去来之神。跗肿将平。饮食顺。言亮声响。", "2994": "二十九日。辰脉四动半有奇。流利尺滑。", "2995": "三十日。卯时脉四动半有奇。清和流利。", "2996": "午诊四动半有奇。流利。机神动矣。（是午永怡子诊曰脉数良久再诊曰动数减半唯五动耳又曰多日不食脾胃脉虚弱也里见保庵诊曰脉和唯心脉未荡）", "2997": "或曰。按侯尊年久病。血气阴阳未复。营卫宗之气未周。食饮未甘口。肌瘦未充。体脉当浮弱而涩。或兼虚似数。何机神荡动。去来和利之见诊也。丹溪曰。瘦人脉浮。戴氏曰。久病脉弱。是其候也。又曰。气虚。脉如病蚕食叶。血虚脉如雨沾沙。中带虚数二者。乃涩脉也。侯诊无上诸脉。何与病相反耶。曰。子知之脉。不察之治。言医者。先明脉病之虚实。而后用药之不忒。则重病就轻。轻病就愈。将复未复之际。脉先荡利耳。自前至今。经两旬日。凡用人参汤三十余贴。日夜不间断者。正虑其高年严冬。久病脉涩。气弱数端矣。譬之世人脉病相失。良医束手之际。单用参汤而复命者间有矣。（标明厥旨全在薛立斋虞恒德龚子才所编书）况进参汤。及峻补药剂多日。今日得机神荡利不言而可知矣。吾将停药两日。温之以食者。正由脉之动荡耳。经曰。人形病。脉不病。曰生。难经推明之曰。人形病。脉不病。非有不病者也。仲景叮咛究之曰。人病脉不病。名曰内虚。以无谷气。神虽困。无苦。是言形体憔悴。精神昏愦。食不忺美。而脉得四时之从也。扩之病后调理。理犹明当。辛丑年正月元旦。精神爽快。食物忺美。声亮色润。脉四动半有奇。上下去来之势利。", "2998": "【风劳】奉诊某君脉数次。或浮而滑。或弦而数。或滑而数。两关前犹甚。闻自秋仲外感鼻塞。或用败毒。正气等剂。发表。延至冬初。晡热痰红。或用滋阴降火。及至腊末。犹患恶寒晡热。头痛额痛。鼻干龈肿。痰嗽声重。或用补中益气。数症还复。百药龃龉。非药草之不灵。计症候之不明也。兹承某君命。不敢隐讳。略窥线道。以陈始末。夫风天之阳气。百病之长也。营卫失调。皮肤不密。阳邪外袭。伤人尤速。一失其治。传入腠理。再失其治。传入骨髓。不能泄越者。内作骨蒸而成风劳矣。论其变。或令人寒热。或嗽吐血。遗精盗汗肌瘦等症作矣。岂曰尽属阴虚而用滋降。再曰。中气虚弱。而用补益。枉投药剂。坐观其效。如众盲摸象者哉。故药分三阴三阳以施。症随各经各脉以断。纵得外邪之伤。乘其邪浅。药不数服而得愈矣。原某君数症。虽经几月。幸年壮气旺。阳邪不为传变。唯滞于一经也。谓一经者。足阳明也。自迎香交入鼻。历承泣起头维。循鼻外入上齿。及走下关颊车数穴云。所患数症。不外斯经。申酉晡时。足少阴表里所主。土一受邪。侮其所胜之水。则晡热作矣。经曰。应于申末发者。谓之潮热。邪在胃也。脉浮滑弦数。阳也表也。乘其脉势。先以表散阳明之邪。候其脉和。后以调理阳明之土。则无实实虚虚之患矣。所用药方考略陈如下。", "2999": "前方上五贴诸症如失。唯鼻塞耳。脉左右关尚弦。再加二味于前方。虑一味之和滞不专。姑置之。", "3000": "上六贴。鼻气通畅。头面爽快。六脉平和。饮食自若。然因岁末年始。出入甚繁。初四日。觉皮肤恶风。今犹平快矣。承某君命。再一制方云。", "3001": "前上升葛数剂。诸症速痊。昨似有风寒之状。然脉既平和。不可过服表剂。亦不可峻补。将前剂宜合友贤之补益。汤料想适中也。特考药品。再验万一。", "3002": "【吐泻】纪州五旬男经霜路十余日。因病后患不服水土。吐痰泻利。觉四肢怠倦。脉左关弦数右弱。", "3003": "【肛痈】中年男常患小腹弦缩。饮食不甘。过则屎结尿数。觉口中粗淡。本年八月肛门肿痛。脓汁不断。脉弦弱数。", "3004": "【淋浊】纪州大井氏。壮年患浊。茎痛发疳。愈后清汁不干梦遗。令服忍冬草一斤余。脉数而弦。兼患淋浊。阴囊左边肿核。", "3005": "【目疾变证】壮岁男前年患眼。上盛下虚。饮食不成肌肉。脉举之似缓。按之全无。", "3006": "【疟后变证】水野氏。前二年患疟。后嗳气。嘈杂。腋汗。腰痛。足弱。遇寒则便结。疝动则溺黄。脐腹痛。睡则身麻。夜不能寐。双眼蒙眛。肌肉𥆧动。右胁筑块。脉弦而少数。", "3007": "【胸痛失眠】十八岁男子身体衰弱。时吐痰。早晚和静。子午劳倦。胸痛上气。不寐。小腹无力。脉细数弱而不调。", "3008": "【喉右结核】白㭴氏内人。壮年右喉结软核。临夜咽干口渴。或身体痛无定所。嗳出气。则胸宽。不嗳则紧。脉上部滑数。下部五动弱。", "3009": "【耳鸣身痛】四旬男。患下疳。愈后耳鸣身痛。一医用药。鸣定呕逆。脉浮细弱。", "3010": "【耳鸣脚弱】石原氏。壮年四月间。遍身发小疮。如麻如斑。服药愈后。伤风吐痰。左手足不便于动。左胁如有物冲气动。耳左鸣不闻。有时脚膝弱。或左腕肿。脉左右上部浮弱数。下部弱而数。", "3011": "【头痛耳聋】冈村氏。壮岁患头痛。不食吞酸上气。或胸痛四肢冷。耳右聋左鸣。目昏足膝麻痹。或舌强咽干。眩晕吐痰。健忘遗精。或小便溷浊。脉上部弱数。下部似滑。", "3012": "【潮热发斑】二旬男。肌腹日晡发热。头面无汗。四肢觉冷。恶闻食气吐逆。遍身将发斑状。头痛脉沉数。或弦数。", "3013": "【疝瘕恶候】高田氏。患气郁。腹围作聚。少食。白浊。脉左右俱涩。五动一止。或三动一止。医为恶候。予曰。是。然医书言疝之变症。恶候百出。", "3014": "〔初用方〕行气香苏散加青皮山楂子木香或去三味加茴香青木香三棱莪术木通〔次用方〕三和散觉脐上下气动。脉三十动一止。二十五动一止。〔终用方〕人参干姜肉桂（各一钱）甘草黄柏知母（各五分）", "3015": "【腹痛肚胀】一男子。因食鱼生腹痛。左甚作泻。脉实。常患腹胀。面赤上气。", "3016": "【疝瘕】五旬男。平素用心太过。仕官朝夕无暇。常犯疝症。小腹冰冷。及腰脊。或觉腹内如转索。或肚腹如絮柔痰支心下。脚腿酸弱。脉沉细无力。或细动似弦。", "3017": "【伤食痞气】一男常患肚弱伤于食。右胁痞气。脐下亦然。或似伤风。肩背紧。或秋末痰支咽喉。或闻鸟羽声。则胸心怔忡不时。口舌或咸。有时便燥。脉滑数。右关无力。", "3018": "【潮热盗汗】安西氏内人二十岁。因产后丧孩。至六月后。发热晡时。或盗汗。不食。医治后。体瘦弱。面赤。或盗汗。不食。脉七动无力。左右项生疬。六七颗。经水或居。", "3019": "【肿泻绝证】一奴。劳役后病泻。面部四末虚肿。色青黄。痰喘不眠。不进饮食。言语呢喃。脉左寸不应。余部浮弱。或弱数五动半。余医治将及半载。病日笃。并无寸验。予曰弱则卫气败。弱数营将夺。不救。其主再三求请曰。服子之药一贴。虽瞑目在九泉之下。亦无怨矣。予不得已用药。七日浮肿退。痰喘止。粥饮进。呢喃定。外症悉平。唯脉不复。予曰无奈矣。其主再求曰。服子之药。得其神验。更乞一治。予曰独参汤大贴。延三日之命也。后果然。", "3020": "【咳嗽】五旬男。患咳嗽。或饮食。或睡卧。身暖愈嗽。脉滑。", "3021": "【棱骨痛】岸本氏患棱骨痛。五六年。或咽干。龈肿。头痛。面目肿。右脉滑。", "3022": "【麻痹不遂】纪州落合氏。前年患疸。愈后右胁筑块。左足麻痹而弱。左半身觉不便。常耳鸣。或梦泄。脉五动。", "3023": "【咳嗽夜剧】六旬男。自去冬。初觉伤风吐痰。咳嗽至夜尤甚。头汗如流。脉弦涩。", "3024": "【痰嗽痹弱】西村氏患痰嗽。脚腿痹弱。腰腹沉重。及秋似伤风状。脉或滑数。或弦数。", "3025": "【鱼口结块】户田氏患鱼口。愈而结块。手足时发红点。脉实。", "3026": "【内障失明】木材氏患内障。左失明。右少光。头重耳鸣。前与补中益气汤。及益气聪明汤。六味丸等剂。右眼复光。今春为官役自纪至武。路途劳神。觉鼻塞。眼暗。上气。等症。脉左浮弦。右弱弦。", "3027": "【头痛目眩】字藤氏性急。左胁冲动攻筑。或头痛目眩。或吐痰鼻塞。夜不安眠。自正月初旬。遍身似伤风。然后吐痰。盗汗。头痛。目眩。晡热。数症往复。脉滑而无力带弦。", "3028": "【泻痢】八旬男。患休息痢二年。及本年正月。伤食泄利愈重。至月初医灸数处。亦作溏泻。或呕吐头痛腹满。脉弦细。", "3029": "【咳血】一男。患咳血。寝汗脉数。", "3030": "【内痔】四旬余男。患内痔。结粪疼痛不已。夜甚。脉左弦尺弦实。右浮弦五动余。", "3031": "【疳疮】一男患疳疮。逾年不愈。状如烛残。脸肿遗脓。脉弱散而似滑。或弱数。", "3032": "【下疳疮毒】林氏患疮毒下疳。愈后肢体弱。两腿紧痛。缺盆肩井左右发数十块。或溃或愈。脉动而弱。", "3033": "【手战舌强】四旬男。常患右手风战。本月初日晨唇缓舌强。不能言语。至巳时渐复。至今二十余日。每早如前。昨今二日口无食味。脉左弦数。右弦数弱。", "3034": "【痘疮】十七岁女子。初九日发热。初十日见痘。是夜经水适行。十一日酉时痘发遍身。满面根窝不润。咽喉干渴。肌体尚热。脉浮滑数。用当归芍药川芎葛根牛蒡子连翘木香生地黄等剂。四物补其血。则红点能润。又理经水。葛根解其肌。则脉自能和。兼行阳明。牛蒡连翘化痘毒。以治十二经之火。香可以去秽。故用木香而净其经水之污。轻可以治实。故佐葛根而治其肌表之壅。又木香能行血药之滞。芍药善敛轻发之气。", "3035": "【脱肛】一富商。年六十余。头项肿痛。不能摇动。一医用人参败毒散数十贴。热退肿如故。又用内托之药不效。请予诊之。脉虚缓。左尺涩。及伸手乞诊。转身之际。皱其两眉。眼看身下。予曰。平素莫犯脱肛么。患者曰。已多年矣。予乃知前用败毒散之非。撮补中益气汤加茯苓酒芍药倍人参黄耆三贴而脓出。七贴而收功。外贴拔脓滋血膏药。", "3036": "【肝郁血瘀】一官家妇人。常患两胁有物冲上亶中。则口中干燥。头痛目眩面热足冷大便常涩少。诸医治十一年矣。或止或发。不能去根。少有思虑则发。又不饮食。命予诊之。两手弦数六动余矣。予曰此肝气有余以致矣。一医曰。某常诊多年矣。此生成脉矣。予曰岂有是哉。人长脉迟。年老脉缓。是其常也。此必前医补之过也。以小柴胡汤去人参加川芎地骨皮槟榔子枳壳青皮七贴。而胸宽上部病减半。仍用香附四制合大黄四制为丸。服二百余丸。用煎汤送下。大便顿解。目眩如忘。通身发斑瘙痒。脉五动矣。予曰。脉动如此。必有十全。虽想前医用调经补血热药峻补多年矣。行年五旬余。经水不断。已前发热。今发斑者。乃血燥而然。有物冲上者。乃瘀血也。用四物汤合小柴胡汤。加牛膝红花桃仁便香附黄柏作大贴。顿饮四贴。下瘀块如碗者数次。连下紫黑臭脓经水。十余日后。诊脉只四动半矣。予知症痊。用川芎当归酒香附黄柏数十贴收功。", "3037": "【卒中痰厥】一男五旬肥白。常用心机。一日会客。忽晕倒不省人事。痰壅喉鸣。鼻鼾脉浮滑。会有客医先灌苏合香丸不应。欲作伤食治。予诊毕曰。气虚而得痰厥症也。宜医林三生饮。加人参。一医曰。何以然。曰虞天氏曰。肥人中风。或口㖞肢麻。不分左右。皆作痰治。又曰。肥人多湿。宜用乌附是也。脉浮而滑。且喉鸣鼻鼾故耳。遂与", "3038": "八月八日脉左寸沉数。关尺沉带细涩。右手三部沉而数。寸犹数大。老人云。热郁于中不上散。胃中火滞而然。脉见乎上。是以上部多见色黄。", "3039": "九日脉同前（但左寸些浮而和）本方去薄荷加当归防风秦艽（各三分）", "3040": "十日脉左尺沉弱而安。右手机神动荡。不似昨朝脉之沉涩矣。尺微弦。", "3041": "前八日云寸脉数大。热郁于中不上散。胃中火滞云云。因用薄荷防风之品。十日夜。郁火升动。肌肤有热。日夜不退。火炎则水干。故阴热将发也。燥万物者。莫甚乎火。故羸瘦不生肌肉。火甚则速于传化。故善谷不宜嗜食热燥。此剂苦寒甘凉方也。苦能泻火。火去而阴自生。阴生则肌肉自长。寒能胜热。热退而燥自润。燥润而黄自退也。", "3042": "十一日脉气渐浮。热郁自得升动。但脉气浮。不无热动。此正治耳。", "3043": "十二日脉（失录）热申时发至亥时。", "3044": "十三日脉（失录）六日夜。大便燥结。因加桔梗。谓其气少升。则大便通矣。", "3045": "十四日脉（失录）前方因数日便结。制通大便方。", "3046": "十五日脉六部些数而和。但两尺沉涩。右寸弱。", "3047": "上剂分二贴。作四次温服。是日晡热又来。饮食少进。气色怡惓。经曰。一水不胜五火。故此剂以泻五脏之火也。燥热之药。久服致脉数虽和。沉而无力。此几而无水。故泻火以存水矣。用陈皮甘草以养胃气。石斛等物。清肺源矣。", "3048": "同晚脉（失录）阴时作热。由邪所至。便通渐能止也。但得脉神旺长。不为涩滞乃佳。是在调其气而和之云云。", "3049": "十六日晨脉六部和带少弱之意。", "3050": "十七日晨脉左和。右寸关涩。恐是胃口闭郁。", "3051": "同晚脉（失录）申时热发。胸膈烦热。咳嗽。", "3052": "立师曰。前方加香附子砂仁者。止下之用也。下止可去矣。今朝速欲去之。恐未尽矣。今晚脉沉而致嗽。宜去香砂耳。", "3053": "十八日晨脉右寸关浮大带涩。", "3054": "黄芩（四分）枳壳白芍药防风柴胡（各三分）黄柏（二分肾无实不可泄今在尺脉沉火不息故暂用矣）甘草（一分）知母贝母（各五分为末）调前汤送下。", "3055": "同晚脉左三部和。右寸浮数。或曰。浮脉应秋。肺金独旺。恐伐和平之气欤。曰然。用枳柴发动右阳。二母以润肺金。是所以也。然药力未行矣。须用二贴而知之。明早脉得和。喘少热微。气色和怡。", "3056": "十九日晨脉六部和而敛。昨脉右寸关浮数减大半而敛。", "3057": "或问症得之燥热。用芍药酸寒收敛。是法也。今去何为。曰芍药虽治土之热。实治左关药也。右关土位脉弦。乃泄土中之木。今脉和故去之。", "3058": "二十日早脉左三部如无力。右上部始得平和。嗽止夜热退。小便些淡。", "3059": "同晚或问燥症发热是常。而反恶寒何也。曰六脉无寒热之至。此因燥见阴血之虚矣。", "3060": "二十一日晨脉六部和而弱。", "3061": "二十二日晨脉左寸发动。关尺沉。右寸关沉涩。其中如有物应指。尺沉数。或问累日下药。热不即退。症得之金燥火郁。倍用润剂何如。曰。虽然今晨之脉。右手俱沉应指。如有物。想是燥屎也。宜推下之。", "3062": "二十三日晨脉右关浮涩。颜色轻和。", "3063": "二十三日晚脉两寸实数。微热而嗽。曰寸热而发于夜。宜降阴耳。", "3064": "二十四日晨脉左三部沉而缓。寸些大。右寸关大。", "3065": "二十四日晚脉左三部沉中些数带弦。右寸关大。而冲上。其中应指如有物。或议用推而下之。曰。左脉不浮泛。所以热不易退。高年病久。不宜重加寒降。重之。则生气不达。愈见其热。宜和之以少甘温之味。则生气生达。而脉浮泛。若胃有遗屎未尽。后再推下之。未为迟也。", "3066": "二十五日晨脉左三部俱平。右上部些数。下部平然。大抵共见缓弱。故用补剂。", "3067": "二十五日晚脉左三部数沉中有生动之机。右寸关数有泛发之气。尺涩。（北政之年太阴司天右尺不应连日不论右尺是不应故也）", "3068": "二十六日脉左上部数有浮泛之气。下部起动似数。右寸平。关平而长。尺似涩。", "3069": "同晚脉左上部和。尺弦数。右寸关和。尺些数。", "3070": "二十七日晨脉左三部平少数。尺有生发之气。右寸缓。关长。尺涩。带缓。", "3071": "同晚脉左寸平。关数些大。尺平。有根起浮之形。右寸平。关长而大。尺平。大约六部虽平。有数脉之形。", "3072": "立师曰。今晚两关脉大。", "3073": "二十八日晨脉同。但右关些长。", "3074": "同晚脉左上部些数。尺沉阔。右寸关大。尺阔大低。六部些数之形。", "3075": "二十九日晨脉左寸关些数。尺数而沉细。右寸些数而些大。关数而大。尺平。大抵六部些数。隐隐有上升之气。", "3076": "同晚脉左寸关些数而和。尺有敛起上行之意。右寸平些数。关大尺平。", "3077": "三十日晨脉左三部平和有圆活之意。右寸和。关尺数中有动动之意。", "3078": "同晚脉左三部平不泛起于上。而中体大。右上部数中冲动少和。", "3079": "九月朔日晨脉左上部平和。尺中有发动圆活之意。右寸关些数而大。尺中少动。", "3080": "同晚脉左上部数。尺有圆活利动之机。右上部些数。关数而些大。尺微。", "3081": "二日晨脉左三部微。右关微数。寸尺微。大抵六部微有些些数意。曰脉微气微。所以气急。由不能上下之意。两尺之微。有以见之补下。则寸关之数自息。", "3082": "同晚脉左三部些数中有圆活升降之意。右寸圆活。开数而虚大。尺平。", "3083": "三日晨脉左三部和平之意。但少力。右三部圆活。关些些数。", "3084": "同晚脉左三部圆活有生气。尺脉自诊二十余日。未尝得如此之机神也。右关些数。寸尺似沉涩而微。", "3085": "四日晨脉左三部和缓。尺些弱。右寸沉而缓。关些大数。尺沉而弱。", "3086": "同晚脉左上部和。右关大些数。两尺活动而和。", "3087": "五日晨脉左三部融和。尺有生气。右寸和。关尺旺。六部有圆活之机。", "3088": "同晚脉和如早脉。但右关长。尺寸和。", "3089": "六日晨脉左三部如绵裹石。隐隐有生活冲动之气。右寸关些大而和。", "3090": "尺沉弱。或诊六脉弱而不旺。补以敛气。而益其神。则旺自得矣。", "3091": "按早脉如绵裹石而生活动。右关既旺。何故□□日晡热至。", "3092": "同晚脉左上部冲动流利。下部旺动。右三部活动。六部动且大而数。", "3093": "七日晨脉左上部旺而有力。尺有活动之机。右寸虽和少定神。关大些数。尺有生活。", "3094": "同晚脉左关些大而数。寸尺和而缓右关大数。寸尺和弱。", "3095": "按前用耆参十余贴。各三钱余。至初六晚。脉神大旺。故停一伏时。脉神又弱。再加之以助脉神矣。", "3096": "八日晨脉左三部和。右寸和。关数。尺沉。", "3097": "同晚脉左关些数。寸尺些数。而和。右关滑数而短。寸尺数中和。", "3098": "九日晨脉左三部缓小而和。右寸小而和。关些数。更有升动之气。尺和。", "3099": "同晚脉左关数。寸尺些数而和。右三部平。但关少数而弱。俱得活动之体。曰左三部沉中见数体。而不见弦。现而平沉。则热在内。所以不伶利也。按先治其数。后补其弱。谓实者先泻之。虚者后补之。是此欤。", "3100": "十日晨脉左三部和中有活动之气。兼弱。右关些数。而往来明白。寸尺和而少数。", "3101": "同晚脉力少而弱。宜大补阴血。以燥自润矣。左三部些数中似弱而少力。右三部平和而些数。", "3102": "十一日晨脉六部沉而无力曰缓。曰老人脉缓。是病之常。但未能亟起矣。", "3103": "后日脉左寸关和有圆活之意。尺弱右寸平。关些数无力。尺弱。", "3104": "嘉善杨向多痰火气逆易咳晨圊痔必翻非揉挦不能收甚或痔血大来此足见肺胃大阳气血虚久矣今卒然神思昏乱并无晕仆而右肢遽不能用舌蹇语涩便间句日才行干少溏多溲频数而涩少且赤嗽痰颇浓息有音少寐易烦不昏瞀而间有错语此属老年气血两虚春夏之交不耐火气升泄虚阳化风挟痰火勃动于中而外阻其络脉内扰其神志也据现证是中络兼腑初时右肢不用今渐能连动而肌肤痛痒无关是不仁也不仁为血虚偏右则气亦虚矣但舌苔白满而厚是气燥津虚脉虚而弦两寸较大是心肺两虚而又有痰心主血肺主气虚则火易上升而气易下滞所以有数圊易怒多烦少寐等弊矣此时欲益气而不滞痰养血而不腻膈庶乎虚责兼到据述愚见宗古人痰火内中者先治其内务使神明不为痰火所扰心君泰然则百体从令矣即或肢体不仁未能遽复不妨缓缓图治况心主血脉心既清则血脉之流行自易", "3105": "右方约服五六剂若得寐渐长舌白稍薄喉间痰气不致有音去枳实半夏加大生地（四钱）杏仁（二钱）大麻仁（二钱）若大便复闭慎勿遂与通利必俟其急迫屡圊不来不得已暂用搜风顺气丸又舌胎已退而舌质胖痰来轻薄气息舒得大便畅行溏而老黄者数次今又七日不更衣溲渐利而色来清胃纳稍和夜未酣睡痔外翻而腐续下痰物或中有痔脓夹杂亦未辨别统观诸症大都痰渐化而火未熄阳明肠胃津液虚耗遽难充和所以寐少而便复闭不独痔翻尤昭著也阳明外主肌肉内主津液津液虚则无以濯输肌肉而束筋骨利机关之权亦弛而不张右肢之不仁盖由于此不仁则不能用矣今欲求其不致成废当先养阳明以存其津液胃和则寐安阳通则便调而痔收治内正所以治外也脉仍虚两寸独大大非心肺之有余乃虚阳之上僭耳故耳鸣舌胖心烦易怒毕露其机缄时当大气升泄宜柔静通养为主久之若得步履稍可亸曳便能扶杖逍遥矣", "3106": "又不仁为气血不通先宜通养阳明前案论之详矣今右肢渐知痛痒足见脉络渐有流通之意但大便艰涩脉象沈滞耳鸣舌蹇神气不振欲望阳明肠胃之充和以期气通血润尚远然此症首重肠胃必须穷究其所以难通之故老年风闭前肾多责诸血液之虚想近年来痔血之去亦复不少血虚则风动欲肠胃之润则养血正不可少今胃气稍较醒似可参人濡润养血之品矣", "3107": "潞党参（一钱五分）麦门冬（一钱五分）杏仁（三钱）柏子仁（三钱）苏子炒（研一钱五分）大生地（四钱）驴皮胶（二钱）川贝母（二钱）酒炒归身（二钱）大麻仁又肢体热痒而疼是血虚风燥所致络脉如此肠胃益可知矣所以便难必越数日也高年中风大都为血液不充内风旋扰之故前贤有侯氏黑散以内填空窍以防风之复袭有地黄饮子以内养血掖以杜风之内生皆笃论也而便难一症尤为血虚的证所有风秘治法亦不一然又须因时制宜今未入秋而先形内燥将来何以御秋燥正令计从先为之图川清燥救肺方绸缪未雨稍参和络养胃法冀其府通然后格和", "3108": "湖州周妇向有偏头风痛甚则或有眩呕今烦劳伤阳阳虚风动旋扰清空络脉弛懈陡觉右肢痛而左肢不用是风中在左也迄今五日呕吐痰饮已止右额微肿而痛食少便结脉虚涩此腑络兼中之症痰为虚痰风为内风宜清养阳明柔息厥阴冀其渐愈曾有便血当此燥令尤须远刚用柔西洋参（二钱）陈皮（一钱五分）胡麻仁（二钱）钩藤钩（二钱）羚羊角（一钱五分）茯苓（二钱）杭茶菊（二钱）霜桑叶（一钱五分）驴皮胶（二钱）丹竺（一钱五分）穞豆衣（三钱）丝瓜络（三钱）", "3109": "嘉兴张七月下旬间疟四作继以泄痢此伏气晚发未必清澈遽因孙受病殇劳忧悲伤动于中风寒迫于外遂感风燥作咳凡忧悲伤肺风燥亦伤肺以致痰虽出而风燥之火迄未化郁极而升陡然舌蹇涎流官骸俱不能自主然现症多在身半以上而足仍能行知非风中肾厥是痰火内扰之类中矣况痰中亦有浅深内外虚实之别此痰火乃外感风燥之火之痰故舌蹇等症能暂退亦能复盛盖痰出即人熄痰不出即火复炽所以越五六日而诸症复作也今身想有汗面红齿燥舌蹇涎流右手指微强自言口燥之极脉得滑而右寸关尤甚显属肺感风燥未清痰火上扰脉络之类中也宜滋肺气存胃津以化痰为主痰出则火风自熄邪去则类中亦平", "3110": "潞仲朱媪烦劳伤阳肺卫疏豁冬温风燥之邪实于肺卫初起即见微寒而盛热咳嗽错语迄今旬日燥热气急呼吸有音痰浓而少嗽甚不爽头痛虽罢耳呜颧红唇燥舌干苔白有裂咳引胸胁隐痛脉寸关俱滑数而促此冬温容肺之重症也八旬高年素有肠痔津液久虚今肺脾喘咳邪无出路最易劫津涸液痰胶气喘益甚头汗最防骤脱慎勿因小有郁怒滞气抛荒主病盖虽小有食滞今已大便一次腹右有块不过肠滞未尽肺与大肠表里也润肺即可通肠故此时以滋气化痰急救肺以存津液为要著西洋参（一钱五分）橘红（一钱五分）鲜生地（四钱）川贝母（二钱）米仁（三钱）杏仁（二钱）地骨皮（一钱五分）桑白皮（二钱）冬瓜子（三钱）炙草（四分）茅草根（五钱）枇杷叶（三片）", "3111": "王泾江陈投清营宣气存津透邪方药脉象仅得濡缓弦虚不致模糊难以寻按濡缓为风为胃神虚则阳为湿遏弦为湿酿痰浊凡春夏之交感症风为春之余气湿为夏之王气故现症每每如此其昏昏如醉蒸热舌黄而灰溺赤便闭㿀疹隐隐现于肌腠欲达不达都属湿温二气薰蒸郁遏似烟似雾清明之气皆为蒙蔽所谓肺气窒痹不能宣化则周身之气皆痹而化解不易耳今虽未有大效所幸安静不致躁扰舌连齿板稍有润泽之意若得一意拯治七八日工夫或有挽回之望", "3112": "濮县吕暑湿阻气郁而为热汗出不解邪迫心包目赤耳袭神昏谵语幸得咳嗽疹出诸症渐退迄今两月稍得安寐纳谷惟气火蒸腾干咳未罢目皆赤脉象濡滞是暑退而湿未化宜甘平淡渗以清气化湿若小心调养不致食复劳复则愈期亦不至迁延也", "3113": "震泽孔痎疟三年近渐作止不常大抵过劳辄发已是劳疟景象疟时溺数不禁是阴不内守烦渴引饮是津不上腾况兼痔漏复溃脓水淋漓气液之消亡甚矣比复当春夏阳气升泄之时陡然凝寒而热渴呕痞攻胁痛神烦此属湿温之气乘虚袭入兼郁于肺胃少阳气络阻痹游行三焦也今热退食进脉象弦数已平惟见虚弱濡消病势似将退舍然口干舌碎苔白神衰气夺汗多食少寐不能安虚体感邪邪既未化而正已告疲深虑汁液过多津气内夺虚脱骤见幸勿以小愈而忽之", "3114": "震泽陆寒热咽痛吐泻肢节肿痛紫斑隐见迄今七日昏沉如故稍有谵语齿燥耳聋舌黄地地扬手掷足喉间痰气有声便下一次甚少溲涩而胞痹身热口渴脉弦数此风寒湿三气难受经腑表里皆痹挽救大难荆芥（一钱九分）牛蒡（二钱五分）石菖蒲（二分）厚朴（八分）小川连（二分）防风（八分）猪苓（一钱五分）丝瓜络（三钱）连乔（二钱）芦根（八寸）山栀（一钱五分）泽泻（一钱五分）木防己（一钱五分）枳壳（八分）", "3115": "嘉兴陈肿见于上颈领尤甚鼻易壅塞痰从上腭来肌肤渐见青紫似㿀非㿀病经两月脉涩此风温上受郁于肺分与风水尚有小别宜轻扬之剂上者上治之法", "3116": "光按肌肤青紫似癍非癍则邪不尽在气分生地荆芥颇与此症相关善连杨前投清肺化邪清心安神方诸恙渐退胃纳亦增复因烦劳伤阳风温乘隙而入微寒而热咳嗽又甚痰多色黄中夹粉红气急头汗溺黄舌白脉濡数弦明属复感所以诸恙皆来急宜清热化邪毋使喘汗复盛", "3117": "又肠腑已通所下宿矢颇多肠通则胃和而肺亦降今寝食俱安热退痰少耳聪目明舌边红苔薄白脉虚小和缓症情已臻安善矣而感症之后食复劳复最宜谨慎治法不宜骤补清养肺胃大肠以通为补俾寝食渐复其常即是不补之补", "3118": "梅里张肠风下血经年至今冬才止阳明腑络皆虚矣初夏寒热发斑亦是风湿为病癍后风湿之邪似未清解风动厥阴则右侧腰胯痛少腹攻胀湿阻少阴则右腿痹痛不能屈伸转侧风湿相合郁蒸为热则身热恶寒汗多溺黄便反结闭舌白不渴胃钝食少矣近复痰涎上壅咳咳不爽亦是湿浊所化脉虚而弦总之皆外邪风湿未清之故然风轻湿重尤宜通阳化湿为主必先退其郁蒸之热务使汗敛便调庶无虚脱之虑至于痹痛不妨缓图生冬术（一钱五分）枳壳（一钱）橘皮（一钱五分）丝瓜络（二钱）滑石（三钱）米仁（三钱）石膏（二钱）芦根（尺许）杏仁（三钱）防己（一钱五分）茯苓（三钱）", "3119": "又蒸热渐止热时仍有汗泄稍寐便亦稍润右胯疝阻与右髀痹痛相连以致转侧屈伸不能皆适舌白口腻胃钝溺少而黄脉又弦迟总之湿蒸热郁腑络皆痹其痹之所以难通者中有疝气横膈升降之气皆为所阻而厥阴既不调畅阳明益加壅塞矣疏厥阴以平疝气通阳明以和腑格幸冀缓缓向安", "3120": "乌镇杨阳虚湿胜之体兼之起居饮食不能慎摄或胸闷或便溏或梦泄面黄形瘦舌白脉滞反复不常何以调理计惟常服丸剂缓以图之若能谨慎自爱庶有康复之期", "3121": "湖州扬长夏右颧发疡原属阳明湿火上蒸不与降而与升则非但阳明腑气不降而厥阴之湿火亦因之上升以致右足大趾痛气逆由足及腹上至脘胁䐜胀皮肤是轰轰如虫行减食消渴口苦舌黄脉弦而数显属胃不降而肝反升宜通宜降勿因高年遽投腻补究宜凭脉症以去病去病即所以顾正也病属易治虽纠缠已久勿忧之", "3122": "又肝阳挟湿循络上行由足大指循腿入腹犯胃过鬲抵咽甚或头面肩背都为气焰所及肝经之循腹本有两路一由中抵鬲一循阴器毛际旁连少腹两胯也汗多少寐烦躁䐜胀舌黄口渴足冷皆由肝气挟湿未能清化以致易升而难降也今脉之弦象稍有柔和之意数象已退大便渐有溏意而尚欠通畅此时总宜调肝化湿主通主降慎勿因寝食未和体气倦怠遽投填补经月工夫当必渐臻安吉", "3123": "又叠投辛温苦渗以通腑化滞非但诸症不退而大便反加燥结者良由时际秋深当王之燥气必胜于长夏湿热之余气以致肺胃大肠之结涩者益形虚燥燥则津气皆涩而不行凡肺胃大阳之主乎通降者既不循职肝脾之主乎升者益升矣今脉得滑大弦搏舌边黄燥而中心光口燥胃钝胁腹胀痛宜滋养肺胃之津气以通润大肠为主肠通则胃和胃和则痰湿驳杂之气皆可顺流而降也", "3124": "九里桥徐寒热参差原属秋深晚发迄今月余余热蒸蒸汗多便溏溺黄脉小弦数胸腹白疹续发未巳此湿热余邪尚未尽化阻痹蒸郁腑阳既未通降则宿痞自然升逆疏腑通阳湿热渐化则痞自渐和矣", "3125": "杭州王平居嗜酒湿凝阳郁为病去秋四肢疼痹两足及左臂为甚乃是湿蒸气滞足太阴阳明脉络不宣也继则鼻衄难经所谓阳络伤则血外溢阴络伤则血内溢热泄气通自然络痹较衰矣今春左乳结核时咳痰稠体疲脉濡舌黄目昏耳钝亦湿邪上蒙耳然络病宜清腑病宜通时值夏令收效难速拟用和阳化湿清气宣络缓图之潞党参（二钱）法半夏（一钱）木防己（一钱五分）赤豆衣（三钱）竹茹（七分）新会皮（一钱五分）生冬术（一钱）川黄柏（一钱五分）粉丹皮（一钱五分）云苓（二钱炙）甘草（四钱）米仁（三钱）建泽泻（一钱五分）", "3126": "洞庭山蔡阳虚嗜酒之体屡为湿困以致腰重不耐久坐左屑臂痛疮痍时发不能尽泄经隧之湿由阳明深入厥阴为便难肛痔为囊风腿癣滋蔓无已皆湿病也脉濡涩不宜用刚药燥劫议养阳明以清厥阴冀其缓效", "3127": "光按此症生地首乌太觉腻滞可加银花丝瓜络桑叶等以靖厥阴之湿热比麻李身热已退七人大便逐日一度干而尚顺耳聪神清食进溺淡黄舌薄白脉濡滑缓论症情喜已退舍此时宜清养阳明冀其肠胃通和则未尽之湿热便可渐次清化矣西洋参（一钱五分）陈皮（一钱五分）米仁（三钱）竹叶（念片煨）石羔（三钱）赤苓（四钱）通草（七分）芦根（八寸）益元散（三钱）知母（一钱五分）杏仁（二钱）", "3128": "吴娑顾两耳鸣次第失聪皆因外风内袭而来据述胸腹气火上升为鼻渊齿衄胸痹痰多下迫为痔疡便难或溏今脉得细弦迟全属少阳阳明风火痰三者为病矣", "3129": "杭州裘五内如焚起灭无定时易怒多疑舌腻口甜脉弦左尤甚肝热由于胆寒脾瘅由于胃滞所谓五志火动神明内扰也隆冬蛰藏之时宜用育阴潜阳法", "3130": "光按柔育心肝似已周到唯于痞胀妨贪似未顾及绿萼梅砂仁亦可加入杭州裘服育阴潜阳药以来春时竟不梦遗是可喜也然晨易心悸悸即易怒多疑懊𢙐此肝胆包络尚有郁热凡郁热之冲原无定时而心胃独当其冲所以目泪鼻血齿痛口干舌黄便溺不能了了脉弦实相因而来也宜清肝之用养肝之体以调疏泄之职则胆与包络皆和矣", "3131": "桐乡曾八月初寒热似疟是新凉外迫伏暑内动之感证奈挟食挟怒而脘痛呕逆吐蛔特甚客反胜主治法不免暄宾夺主矣腑病宜通得濡润而痛减得溏泄而痛竟暂止感症之流连肺胃者每每如此纠缠一月病未了了寒热又作顿加咳嗽面浮则又病中体虚复加一层秋燥之邪肺气益痹以致腹痛作而龈齿干燥也脘痛连及胸背动辄气逆肺之𪱥郁极矣耳鸣汗出剂颈而还则病邪伤阳也腹痛便瘀溺色似血病邪伤阴也体之阴阳虽皆受伤而秋燥之邪大队尚聚在胸鬲之间脉右虚凝左小弦数顾正但须养胃存津化邪但宜宣肺化燥眼光但照大局未可偏执一隅枝枝节节为之矣至于病机之危何须再说", "3132": "光按此乃喻氏清燥救肺汤加减惟既有脘痛彻背则辛润之品不可缺少九里汇陆向有跗肿或大小足指痛不能行每发必纠缠累月近因心境动扰先觉脚痛继以齿痛延及左半头额颧颊甚至身热左耳流脓迄今两旬耳脓及额俱痛而彻夜不能成寐烦躁益增咽腭干燥耳鸣口干咯有凝血食少便难脉两关见弦素体操劳尤郁由来久矣心脾营虚是其质近来复感风燥之火上烁肺金金不制木肝阳化风化火上扰清空肺胃津液皆为消烁是以现症种种虚实混淆宜先用甘凉濡润以存津液以化虚燥", "3133": "又连服甘凉濡润之剂以存胃津熄肝风咽腭之燥已减血亦渐止右额浮肿亦退大便虽涩而日行胃纳亦安脉左静小而虚右关稍有弦象以便尚少即寐亦未酣适鼻气窒塞盖燥为虚邪而言以素虚之体易受燥邪也其平素面跗庞然两足易痛原属阳明津虚络脉久失濡润故燥气加临愈觉冲逆今拟滋养肺胃充润津液肺金清肃则肝木自平胃气充和则夜寐自安矣至于节劳戒怒则在自爱者留意焉", "3134": "又脉六部缓小右关之滑形已退大匣稍润渐能假寐然咽腭仍干上及于鼻瘀聚气秽呼吸不和两耳抽掣心中时惕凡鼻息不得卧眠阳明病也显属风燥之火上伤天气清窍窒塞津液不能上承叠投甘凉濡润而迄今不能大效计惟有仿古人风以润之之义取其清阳上达可至病所则存津滋液庶乎有裨", "3135": "又脏燥渐减秋冬之交竟有三月不大发然稍劳怒辄觉火升鼻干心神不能自主而带重腰酸左足易热经来参差腹痛气坠色仍紫黑此八脉郁火尚未清化宜用静剂专清奇经", "3136": "武康钱肌表微寒而热似疟非疟鼻干有血胃钝少纳脉浮弦数阳部为甚此燥火上薄肺金自秋初至今迄不肯已瓜致便溏是肺与大肠两金皆困老年岂是轻症况素有失血则气血俱耗矣", "3137": "嘉兴陈初起寒热头痛咳嗽汗泄明属风伤肺卫为病奈气体素虚向有肝郁今肺既不宣肝必易逆挟饮阻络上干清阳以致咳逆痰薄左胁引痛舌苔厚白干而不渴胸脘痞闷不饥少食溺黄而少便干而坚此饮阻络痹气亦𪱥郁也呃逆频出咽左激痛甚或气冲至巅耳鸣头量此肝阳化风郁而为热也总而言之始则外风引动内饮继则外风引动内风迄今八九日外风将化而痰饮肝风反扰攘不解脉右寸及左三部皆近数急须清金以制木通阳以和饮", "3138": "又诸恙皆退胃纳已增脉象静小舌色润泽惟寐后干咳得汤饮即痰出而嗽已卧时又须倚枕足见风燥之火易劫津气甘凉濡润以滋气存津自是此症要旨拟以前法中再参濡肺胃法", "3139": "平望许初则晨刻咳呕饮浊久则哮嗽上气夜不著枕行艰报息头汗舌腻脉虚凝如毛右部间露弦象既经多年除根不易议和饮通阳平逆定喘法先为御寒之计", "3140": "江宁席易感善咳咳逆痰清此肺气损而卫外之阳弱也既经多年肺阴已虚以致近年来音气易涩矣脉虚濡右手兼有小弦之象宜滋肺气养肺阴时时调理毋使失血失音之流弊", "3141": "塘楼毛肺虚失降肝郁易升胃弱饮聚饮踞于中则外寒一引即动是以咳逆至冬为甚也消渴为肺热今脉左偏弦舌苔黄厚调郁清肝可望肺胃之阳和而热可平饮可涤矣", "3142": "新市郑咳复作痰少不厚时有肝气左升腹痛得呕泄始平脉体本弦长今弦兼滑长兼洪左尤甚饮咳本宜甘温以和之所谓饮家咳不治咳也今既肺降不及肝升有余甚至痰滞凝血宜从湿痰挟火之例矣", "3143": "又咳势较缓痰之厚者仍少脉弦左仍带滑不过洪滑较减耳舌苔白里半犹黄腻饮咳既久挟湿又兼肝气当先为清肝化湿以衰其助况时届湿土亦因时制宜之法", "3144": "又咳逆夜甚晨则痰饮较多近加喉糜音欠爽亮脉右较平左仍弦滑寸部尢甚痰饮既未和肺气失清又挟时令之热而为喉糜人迎脉盛必有外感非必心阳上亢也宜参金水化痰法", "3145": "元参（一钱五分）马兜铃（一钱五分）甘草（四分）桑叶（一钱五分）紫苑（一钱五分）牛蒡子（二钱）天竺黄（二钱）竹茹（七分）杏仁（二钱）川贝母（去心二钱）丹皮（一钱五分）石门陈去夏之陡然吐血当是湿热蒸伤阳络络空则湿热乘虚而入留酿为饮饮咳至今虽有盛衰究未停息饮之所聚虽由血去络空而饮之所生实由阳虚湿胜故夏秋胃纳虽和而体乏无力右腿时痛也比因新寒引动宿饮身热汗多咳而兼呕周身络痛而左胁为甚且至气逆胃钝卧偏著左嗳气失气便溏溺赤口腻舌白脉象沉弦在手兼数沉弦为饮左数为肝胆虚热大抵饮踞于胃则右降不及肝胆风木乘胃之虚则左升有余矣和胃以涤饮平逆以清络胃和则饮咳可缓而谷气可复逆平则络痛可止而血不妄行", "3146": "杭州许咳逆已久的是肺分痰热未清加以秋阳酷烈肺气复伤身热舌干绛苔厚黄形瘦脉弦明属湿郁生热热蒸成痰既在肺家只宜清化表不合理补亦壅邪也", "3147": "又胃知味而渐思食食后亦和脉小弦大便未畅小便又浑自是湿热未曾净尽之症非阳虚之体补壅非宜而湿热之邪又黏腻难化静养缓调自可渐臻安善欲速反有弊他", "3148": "又秋仲伏气发病迄今三月余犹然身热畏风胃钝舌刺苔黄口燥脉弦溺黄便溏不爽总属湿酿为痰痰气与肝气相抟阻遏于胆胃之间所以左膺结肿按之觉有酸疼也积久不清竟能成痈宜清肝胆化湿痰埋气络法", "3149": "又细参脉症不但肝胆火升痰气上阻且有秋燥之邪乘虚而入燥火劫金痰气胶结愈甚所以无形之病渐致有形左膺之肿病异源同前法五剂后即以此方濡润通和", "3150": "杭州张肺胃阳虚饮聚为救八九年来举发无时去春至今竟无虚日痰稠不爽时或呕酸口燥消渴动辄喘急头晕耳鸣心悸便急脉右虚弦左沉涩精气既虚肺咳难化虽根株未易剪除希冀作止有时", "3151": "骥村严女夏季痰中带血血虽不多而干咳至今不止素有便溏呕酸胃纳甚约经行迟而腹痛舌鲜无苔脉数而大此属脾胃素虚气血少资生之本本郁则乘土火炎则烁金久延最易成损调复亦颇难速", "3152": "硖石马自春至今咯血竟无虚月秋仲大吐血血去络空胃脉逆上遂至饮聚咳逆迄今饮浊日以碗计形寒食少便溏上气不得卧脉虚滞右滑数上损及中之候调复极难宜静养缓图之", "3153": "又血后咳逆至三月余自然胃脉虚易以逆举今饮浊虽少而痰浓难出咳逆不得卧便溏脉数而促损症及中本难挽回姑拟静药养胃以阖阳明", "3154": "杭州吴春初咯血不多越数日咳嗽即作迄今不止右胁背时痛蒸热舌胖苔黄脉濡左小弦数此属肺胃湿热蒸郁伤络则失血阻气则作咳也体固气血两虚然兴利必先除害宜急清养肺胃以和络止嗽为光毋使久嗽成损", "3155": "石门颜自幼阳弱腠疏易感善咳去秋至今咳嗽不止遂致失血屡发血症初起原为惊悸尤郁而来至于咳久则阳络勃动所以仲冬及仰秋两次所吐较多也血屡去则阴亦虚身热晡盛口燥咽痛侧左则胁痛侧右则气逆此肝升太过肺降不及自然之理也凡失血家最忌咳况咳久至半年有余耶今脉象芤虚弦迟尚无燥扰动数之弊然气血两虚已有明证惟宜耐心却虑善自调养期其缓缓热退嗽止不致延成损性为宰", "3156": "杭州周嗜酒之体大便必溏本无足虑过投辛燥热药动营壅腑以致鼻血腹胀因胀又进肾气丸百日腹笥未敛咳嗽反作失血失音脉象弦数气血乖远大失冲和矣", "3157": "平望吴素有咳嗽失血发作无时去冬至今已逾两旬痰清兼呕时或带血左眦赤两额痛不饥不食食即呕逆脉弦搏肝阳郁勃化风化火挠金侮土急宜清息", "3158": "光按既有咳呕则此种脉症当用清镇如旋覆代赭等似不可少", "3159": "盛泽赵去夏疟后用力劳伤肝胆之络络血上溢因形瘦色苍居平常有头晕体本阴虚火盛故肝胆易动若是今交初秋屡此复发愈吐愈多浓厚重著将吐之时必先脘下气聚有形上冲干咳头额觉胀迨至血止气降则嗳而矢气显属肝胆郁勃之火过升无制扰动阳络之血遂沸腾而出也鬲中作痒大便干艰气逆不敢平卧脉象六部皆弦木火内燃有升无降此时自当以平逆镇肝降气安络为要毋使狂澜不靖致成虚损", "3160": "又血止后诸恙已平惟脘有瘀痞气逆辄咳便溏不畅舌鲜口燥脉象虚弦肝胃血虚而气易逆也宜柔剂通养", "3161": "安吉潘去夏少寐多饮酒热引动心胃之火以致阳络血溢秋冬屡发愈发愈多胃络既空饮食水谷之精微不能游溢精气留酿痰浊阻遏升降冲和之气脉濡如弦弦为饮濡为气虚而矢所附丽也时当初夏宜和阳治饮为先偏寒偏热皆非治法", "3162": "平望张失血起于前年原属因伤动络去冬复发较多今夏五月初咳嗽痰少至秋初寒热似疟是先受湿而后受暑暑湿之邪纠缠至四阅月之久自然络气不免震动而血复涌溢也今身热舌黄胸闷便溏喉痒时咳右胁之痛虽止而脉象弦数左甚于右显属湿邪由气分伤及血分肺胃失降则肝阳易升也宜急为通络化瘀以清人邪俟血止后再商止嗽要法", "3163": "又血止后咳势亦稀稍觉喉痒则咳作而痰为凝夜寐安适胃气亦和惟潮热蒸蒸面黄舌黄涡色浑浊脉右三部虚涩和静左三部数象亦已退小弦未尽调畅究属肝郁不调挟内蕴之湿蒸为热上熏则食少而咳逆也此时咯血已将安静可无翻覆涌越之虞但咳嗽已经四月之久必须通腑清湿调肝肃肺务期渐渐热退咳减为要", "3164": "又投甘凉淡渗苦降之剂以清养肺胃厥阴之气以渗湿化热已二旬余虽热减食增咳稀寐安然舌苔后半犹有凝黄小溲犹带黄色阴囊甚至湿痒淋漓频转矢气蒸蒸凝热易以汗泄足见其湿热之郁蒸于肺胃者非伊朝夕矣今脉得左部迟濡右关尺同惟右寸尚见濡滑晨刻痰咳尚较多且厚喉痒宜滋润肺胃三焦以理气化存津气务使湿热痰浊渐就清澈则胃纳充而体气复阳虚湿胜之体不可遽进呆补", "3165": "西鸡河沈酒客吐血每发必多已经数年血去既多自然疲惫今秋以来渐增咳逆入夜著枕即咳是胃脉上逆而阳不恋阴也脉右细促数左细弦数论症颇非轻浅矣", "3166": "斜桥程肺胃素有郁热加以烟酒辛泄耗气肋热是以咳久未止又复咯血血虽不多而热势夜甚脉右浮滑数头晕舌黄此属胃湿因时而蒸动也议清气络以消痰化湿除热为先", "3167": "双林穆妇经行太早阳明便属不充去春咯血之后或郁怒或烦劳辄易举发今年热咳时作于今为甚脉弦数舌黄而刺咳呕便溏又属肝胆木火挟湿上扰肺胃宜先清气熄热莫作揖症用补", "3168": "泗安赵失血屡发已三四年今夏独多近更咳逆痰稠带血加以额胀耳鸣头晕口渴胸闷溺黄脉象芤弦此由肝郁而致胃热血虚而复受凝暑也先清暑化气以理其标徐止其咳以治其本舒郁却虑尤为静养之要图", "3169": "桐乡曹吐血起于去夏至今屡发而多多为胃络之血然不能左卧咳而兼呕且有滑泄是胃兼肝矣今胃钝舌白脉右细弦左反虚小而静脉左静是血症之佳兆然细弦是肝邪阴脉今偏见于右当是木乘中土胃不降而肝过升以致阳络之血上溢不止也肝胃皆宜降议以静药降之", "3170": "又血止后咳逆未罢仍难左卧畏寒是阳虚胃弱偏卧是气竭肝伤脉微弱神虚怯根蒂未固风浪难经血之暂止不足恃再发深为可尤宜乘平时急为补养", "3171": "湖州杨颜上年五月咯血不多即有胁痛咳逆迁延至今内热脉数咳既不止左胁复痛自然络血复动矣若咳久不止最易成损急宜养阴滋气先期热退胁和然后力图咳止", "3172": "太湖杨烦劳嗜酒阳虚久矣饮咳年余冬夏两次失血先伤气后动营病势骎骎入里今气息短促脉象虚数不免有成损之虑非息心静养何能充复", "3173": "周渡曹素有嗳气原属肝郁去冬劳冗伤肝适当春木发动之初咯血左膺痛止而复作是肝阳未靖时冲其络脉右虚而静左弦而大弦为肝阳勃动大则为虚宜柔静之剂育阴潜阳", "3174": "又去秋咯血后微咳下发脏毒肺火下移大阳咳势顿止近复吐血经旬所去过多寒热盗汗口腻舌滑脉芤弦虚数阳络空洞痰涎蒸聚阳明虚耗极矣急宜充养阳明以为峻补肝肾之先导息心静养节劳戒怒毋使久延成损", "3175": "嘉兴陈前年冬陡然咳嗽吐血过多遂致两年来咳嗽竟不肯止内热时寒痰多食少舌光口燥肉削神疲脉象沉细虚数胃肾两虚虚则成损若能屏弃一切恬神静养成尚有挽回之望然治法先宜养胃不可紊也", "3176": "又去冬咳嗽而失血血虽不多屡发无已迄今仍有凝血痰薄头胀消渴汗多时或脘腹痞胀脉弦右甚此胃湿内蒸肝阳上逆因之肺不清肃络血时动宜清肝胃以理肺务使喘止", "3177": "吴江许吐血发过两次止后体无大异今复发每日碗许已旬余不止微寒而不大热胸闷能食溺黄肺芤弦虚迟此暑湿蒸郁胃脉逆上络血随溢急宜清胃理气化邪以和络止血为先", "3178": "光按此似阳虚证而认为暑湿蒸郁者其得窍在胸闷能食溺黄若脉之芤弦虚迟尚未足为凭也", "3179": "盛泽汪烦劳多恩虑体本阳虚当此酷暑不耐大气之发泄加以暑热外逼肝阳内动以致胃脉逆上阳络之血骤然涌溢连吐三次去血颇多且易此属胃血为多与向有失血微有区别迄今半月余咳逆渐止夜寐尚和其不便左卧及头量耳鸣等状皆失血肝虚微有上扰茸诊得脉虚濡而静左手按之良久稍见弦象舌苔滑腻口淡便泻忽作忽止溺尤短数足见血后阳明空洞厥阴风木易动难熄宜用血脱益气法和胃熄肝并进", "3180": "胥塘陈妇数年来咳呕曾无虚日达节必吐血其所以咳呕吐血者皆属气逆之故甚或不能平卧食少内热经候愆期脉虚涩此冲任不足易致逆举非仅肺胃为病积年虚症调复不易", "3181": "余杭费咳嗽三四年时或失血去秋以来更加便血溏则不多溺浑脉弦大肺胃大肠湿热蒸郁久而不化阴阳之络皆伤矣然治咳难而治血易宜先戒酒", "3182": "嘉善许向有干咳气逆之症每发必咳甚不能平卧向发于冬时为盛此心火凌金之咳既经多年肺胃阳络受其冲击久矣当此流火烁金之令络血妄动烦渴内炽须进甘凉所由至矣今脉芤虚而静小论症情尚可无碍但肺金素虚心火易炽静养善调究不可忽", "3183": "桐乡孙秋冬咳逆少痰匝月复继以吐血血后咳逆无故反加胸次隐痛此属阳虚痰饮内踞久则胃络血涌血去之后烦劳不能静养以致痰饮瘀血𪱥郁中宫今喘咳短气舌黄脉弦凡胃脉逆上血家大忌论症颇非轻浅", "3184": "马窑陈痰饮为咳起于秋季虽经屡次失血甚少至春叉复稍来是春木隐隐勃动上扰阳络故复连吐三日血去过多凡咳而兼呕痰薄而稠本属胃家痰饮为咳咳久则胃脉逆上血热沸涌所以上越过多今虽脉象静小而咳引胸痛便难口燥多梦纷纭尚属阳明气火上壅未能通降犹恐络血复动急宜清肺疏腑以化热安络为要", "3185": "上柏李上年夏秋寒热往来继以吐血过多痔疡遂致咳嗽右腹时痛近进附桂等剂咳逆益炽咽痛皆发脉数最防络血大来深为可虑", "3186": "小生地（三钱）西洋参（二钱）杏仁（二钱）炙草（四分）金石斛（二钱）川贝母（二钱）陈皮（一钱五分）白芍（一钱五分）青皮（八分）元胡索（一钱五分）荔子核（两枚）嘉兴缪每日午后必觉脘痛已十数年矣去春咳嗽起至今吐血后咳逆蒸热舌白溺黄胃钝脉虚素来酒多谷少中阳大虚慎勿轻视", "3187": "潞党参（三钱）陈皮（一钱五分）泽泻（一钱五分）炒扁豆（三钱）怀山药（二钱）茯苓（二钱）蛤壳（三钱）榧子肉（冰糖炒十粒）制半夏（一钱）麦冬（一钱五分）炙草（四分）竹茹（一钱）屠镇朱滑泄舌心光苔腻此属心胃虚热湿火下注冬来交节辄见咯血蒸热溺黄脉濡弦亦属湿热蒸郁之象未可遽进壅补反助相火", "3188": "面论孙平叔宫保病案大人体丰胃强饮啖有兼人之量加以节性褆躬诚为松柏贞固矣两年来肿症屡发其发也肿自下起由足及腹上至头面手臂甚则痰多食少动辄气逆不能平卧茎囊俱肿小溲淋漓其退也大都专科以草药为丸为醴峻剂逐水或从两足旁溢或从大肠直泻所用之药虽秘不肯泄然投剂少而见效速其峻利可知矣且尝其味辛涩刺喉所当仅似黍米而味留舌本逾时不去则其峻利又可知矣自前年秋冬至今翻覆再四其情状大略如斯今诊得脉象右三部弦而虚其弦见于浮中两候为多在手因偏倚支撑气滞益甚皮肤肿厚按之至骨关位微细寸尺尤甚神色痿瘁气机促逆项以代头尻以代踵痰稠色黑咯略难出溺少欠利其色黄赤日食不过四五盖而饭仅得其一虽唇黑缺盆平脐突足心漏背平等恶候俱尚未见且幸神色不衰音吐洪亮然亦疲惫矣夫水肿之为病不一而其为状亦不一初则日积月盛久必泛滥盈溢来去聚散莫可端倪倏起倏灭与身中之元气相为倚伏消长屡攻屡退屡退屡复其复也病者咎医者之治理未明医者咎病者之调养失宜不知水肿之为病本如是其反复无常也夫治水之逆行所无事耳疏凿决排堤防导引皆宜就水之性以顺其流源流既须明辨次第尤当详察稍不如法鲜秦肤功今承明问究厥指归将正其名则支饮为本皮水为标将究其流则思虑伤脾劳怒伤肝盖脾不能为胃行其津液则水谷酒醴肥甘不能输精布气连中枢以达于四末留酿淫溢皆为痰饮水浊加以肝风鼓荡涌越则所众之阴浊排驱壳廓胸胁遏经隧壅肤胶以致便溺皆涩寝食俱废无所不至害有难以尽言者故愚谓蓄而聚者为饮盈而溢者为水饮为水之源水为饮之流非徒逐水可以奏功又必究极其饮非徒涤饮可以了事又必探讨其所以聚饮之源况此症又有风木之邪乘间窃发或推或挽乎况又贤劳如此倚毗爱戴如此以六旬之高年困两载之积患末学浅陋而欲借箸代筹计出万全不啻如鳖戴之重矣竭思殚力以图报称必将和肝脾开鬼门洁净府三者虽有主客轻重先后缓急然可遍废乎脾复其输运之职肝复其疏泄之常则泛滥者或可循途归壑涌溢者庶几风息浪恬今专科投剂逾旬似获小效而克期又不迂旷且窃观其用法亦似小有操纵者敬遵钧谕徐俟其成效而乐与安澜之庆再容退而静思博攻医籍以备万一驰驱之用谨论列如左光按抑扬宛转说理透而论治明非大手笔不能", "3189": "次日又陈诸药皆停缘由昨日晋谒窃观大人色脉神气皆似惫不可支肿既复盛溺又渐少而钧谕谆谆与左右侍奉之人似皆以为舍利水之外更无紧要之著而不知水之为病在肾为本在肺为标脾土既无堤防肝风又加鼓汤愈壅愈逐愈逐愈壅驯至中州陆沈水泉下竭犹复断除食味屡进疏凿天下岂有粮饷不继转战无前尚可望其收功末路者乎此盖由于专科之医草泽无知守一已之口传图侥幸于万一以治药藿劳形之法概施之君民倚顿之身效则国之福也不效则虽食其肉犹可逭乎此愚之所以痛心疾首而进停药之说也夫药犹兵也不得已则用之以去病耳表散攻逐所以去病也温清和解所以补偏救弊以适于中也然犹有补益培养之法在即或病未尽去而正已先虚尚有攻补兼施补泻间进等法参互错综驯至于利而无弊从未有病经两年发已数次不辨病之浅深体之虚实只以峻下一法为可屡投而屡效也差此症之起由饮啖兼人胃强脾弱继则尤劳过皮气竭肝伤饮食所入脾不能为胃行其津液上轮于肺下利膀胱通调水道流之壅由于源之塞不探其本而从逐其流岂止邻国为壑哉将必竭一身之津液血气尽付沃宜漏卮无当涸可立待故愚以为此时之肿非水也气也此时之溲涩非水道之不通水泉之已竭也若再守饮食之厉禁进暴戾之刻剂初何异剿寇用兵而无节制则兵反为寇济师无饷而专驱迫则民尽为雠大人何忍以千金之躯轻供孤注之一掷也然专科之攻伐既不可用矣而补养之剂何以又不亟进差草药悍烈之性留于中者未必尽化遽以补养之药接踵而进不但虑其反兵为斗且恐助其虐而滋其戾夫借寇兵资盗粮诚不如安堵休兵待时而动之为万全也扰攘之后相与休息古人有糜粥充养之法伏望大人放下万缘静养数日返观内听与病相忘频进糜粥以养其胃侯其胃中冲和之气稍稍来复灌溉周易濡养百脉充满然后流动将必有不期肿之退而自退不期溲之利而自利者苟或不然然后审机度势计出万全大人之师定能贞吉又或不然则专科草药仍在也更进而谋之或不虑饥兵之噪矣敬疏诸药皆停缘由以答明问惟鉴纳是幸", "3190": "湖州王六月初肿自面起渐及腹肢茎囊渐致食减便泄迄今两月舌黄有刺脉浮而濡经谓肿自上起者当开鬼门肿盛于下者当先治其上盖言水肿之挟风者必先发汗也今面肿于身是病之主症未退而食减便池则脾胃之土德已薄何以防堤泛滥时已秋矣肿盛必喘若咳逆喉作水鸡声倚息不能卧则肺之通调水道下输膀胱之权益弛窃恐尤占灭顶既形之肿固难退退亦易复而未形之喘必将至至更难御急须消患于未萌后图祟土御水之计", "3191": "泗安李前年冬陡觉面浮气急延至肢体皆肿此因风水为病奈体素湿胜肺既上痹腑亦下滞以致迁延反复迄今仍然偏体皆肿便溺赤涩不能平卧舌光干燥脉沉郁欲疏府必先理气欲理气必先宣肺恙肿极最虑喘也", "3192": "又肿喘俱减七八微咳便溏气易上逆脉右濡左弦大凡水肿之症最易翻覆暂效未足全恃此时宜和阳调中为御水之本熄风养肝为因时之制冀其无推波助澜之弊", "3193": "德清沈咳嗽音窒气逆数年来易发难已是肺气之虚痹久矣虚痹则治节不行而通调水道下输膀胱之职弛而水气泛滥中土卑湿不能枢连矣况肿喘并盛脉濡舌鲜理宜先理中上慎勿欲速遽投温热滋腻有碍脾胃", "3194": "金家□张素体平弱阳虚湿胜营耗肝滞左胁下旧有肝积兼之便溏下血时作时止自十余岁至今矣其脾胃之不和如此则上既无以资肺之气下亦无以御肝之侮故入春少寐盗汗是脾阴不充也春抄之能食不为肌肤是脾阳之不用也中枢无健运之权无怪其当湿土之交而骤见腹满也今脉象濡弱舌干齿燥肉削肌嬴咳嗽痰气有音饥不能食便数溺少总之皆脾胃肺气虚已极健运之权弛而气化之机废此臌症之极重者若喘泻一见便难措手补既壅滞难胜泻又虚羸不合惟有从宣气疏腑一法希冀万一", "3195": "石门赵喘虽不盛痰气尚逆脉濡舌白先咳而后肿先治其肺况肿势盛于下半明属湿蒸府痹治腑以理气为先故专理痰气之逆", "3196": "南浔王妇去年痎疟原属暑湿郁于气分阻遏营卫运行之常故时有闰余之疟参错其间至春血阻而经不行自气痹而肿肿先于头面及至阴之地至阴厥阴也厥阴为肝肝本与胆为表里此疟肿之所由迭起也肝本为风脏交春则风木内动风鼓湿动则头面先肿也迁延至今湿热薰蒸于内风阳鼓动于外加以情志或有不调饮食或有不节则清阳升降之机益形窒滞而肿及周身胀至于废食也顷喉间呼吸有音而领下如垂疟状反轻而微时或便干而数圊溺少而气秽齿燥口干舌质砂白脉象左弦数而右沉弦数实脐突背平是又脾肺大失通降之权而肝气益横逆矣急须缓剂以理气平逆为先必得喘汗不至庶乎可望迁延而开生机之一线", "3197": "关王庙吴咳嗽四五月才止春木司令即两胁走注作痛入秋渐增腹满足肿筋见青色食少䐜胀脉弦沈附骨此属郁怒伤肝痰阻气痹中满已成难许见效", "3198": "又上呕痰饮下泻瘀血阳明似有通运之机虽饮食稍进脉象稍起而蕴蒸之湿外达为黄内阻为胀满者岂能易化故论症仍在险途", "3199": "光按此亦肝脾两伤之症□湖李幼有哮嗽近虽不发痰饮内聚阻肺胃升降之气加以肝郁不调顺乘中土以致入夜腹必攻胀而汤饮香燥皆不能受脉象小弦宜用缓调议通阳涤饮条肝法", "3200": "平罗王内有烟辛燥劫外有疮疥浸淫燥湿二气内外交迫脾胃大失通和之序八月初燥令大行大肠燥金气𪱥以致脘腹膨胀疼痛泄利不爽迄今三月脉之关尺犹然弦坚而数取效谅难欲速议通养肠腑以阖阳明为主", "3201": "王店张嗜酒烦劳二者皆伤阳气阳虚者湿必胜况酒易酿湿乎今夏湿土司令之时胃纳骤钝则中阳益虚以致足跗先肿湿盛于下也浸假而至肿势日上渐及腿髀茎囊腰腹则肿盛于下者当先治其下也肿盛必喘是湿浊上于清阳也今溺少而黄肤腠似癍似瘰似痱皆湿火内蕴之的据况舌胖大而鲜赤阳明亦有火矣脉沉迟宜专以扶阳化湿宗古人病在驱壳经隧者毋犯脏腑之训缓以图功", "3202": "又阳虚不复恣啖生冷中阳受伤上逆为呃下壅为肿汗多食减舌鲜苔黄便干溺涩少而赤脉沉微迟涩凡阳虚者湿必胜此物理之自热故水肿之反复皆当责诸阳虚也第此中有区别焉今阳虽虚而湿又甚一味补阳未免助湿宜用通阳法以调中疏腑冀其呃即止肿缓退切宜樽节饮食毋使壅遏其式微之阳", "3203": "又饮食不节骤伤中阳以致呃逆人身之阳宜通运不宜壅遏既阳伤呃作则不能敷布极矣所以水肺旧恙复作凡水肿多门其源不外脾肺肾其治法不外开鬼门洁净府实脾温肾今肿由下渐及于上便涩溺少舌鲜苔白脉沉涩喉间痰气有音啖肥浓有味而杳不思谷其为肺失治节胃不致布显然此时宜宣肺养胃以调气化资谷气为要俾不致水浊上潜清阳日窒而遽增喘逆则可缓冀肿退", "3204": "武康方晓帆秋间泄痢时作时止而脾胃蕴结之湿热究未清化入冬燥邪搏肺肺气不能清肃则脾胃之承流宣化者益滞以致咳嗽肿满交作今腹膨妨食夜尤欠运多坐则囊足即肿溺浑便溏不爽脉弦数右甚急宜疏理痰气以润其输运为先", "3205": "长兴俞劳郁太过阳淤肝横顺侮所胜久则饮食不能游溢精气聚而为饮举发无时痛呕交作已经多年脘胁胸背皆为凌□之所驾轻就熟理难骤止舌淡白而黄脉迟弦而虚面黄筋掣主客两虚矣宜平时用丸以养肝和胃发时用煎以温中御侮旷日持久有备无患庶乎有济矣", "3206": "大窖沈妇体丰阳虚饮聚气滞由来久矣交春木气司令肝胆易动顺乘阳明逼动心营以致脘腹攻胀心悸头晕耳鸣舌光少寐多汗火升足清食减不饥虽痰饮吐咯究难清澈痰火胶结津气易夺大气升泄之时尤虑气火妄动汗液易泄也今脉得寸关濡弦滑数总属痰火二者交相为病气即是火平气即所以清火汗多亡阳敛汗即所以和阳再加涤饮以和胃胃和则啖食渐安而心营自不至妄动肝胆自不至僭扰也", "3207": "新胜朱进通阳饮方法寒热之状已退饮咳已减六七然舌苔白腻脉左浮弦右胁隐痛大便仅行一度小便犹然短赤尚属余饮宋尽留踞中州以致便溺未能通行肝阳不免易动议仍通阳和饮为主疏腑润肝为佐", "3208": "新市范髀厌之痛虽由劳伤后因发癍而愈是必有风寒外袭比来肢体畏寒晨起痰饮涌溢食少便坚脘中不和脉来弦滑犹属寒遏卫阳饮踞中脘之象拟和阳涤饮法以通中州", "3209": "钱邱范痰饮之聚原由阳虚高年脾胃运化力迟水谷之湿酿为痰饮每每有之如古人三子养亲等方虽为治标亦有至理今精气饮食已复而脉弦有饮亦当实诸脾胃运化之迟时当湿土宜参和胃益脾以助谷气之运", "3210": "又新凉外束宿饮内动左臂大痛痰饮不多四五十日才得痰少痛缓然身凝热脉尚沈著余邪与饮俱未尽化也", "3211": "德清胡夏末寒热咳嗽右胁动即觉痛时或带血迄今胁和血止而痰多脘痞食少欠连不能平卧脉滑而坚两关尤甚支饮未和肝阳又逆肺胃益难通降矣", "3212": "嘉兴王向有失血频发据述情状自是胃络怒伤之血今春外感咳久肺伤复致吐瘀近来寒热咳嗽皆上而动辄气逆脉坚弦弦为饮坚为肝阴虚阴虚则肝无以养饮聚则气易上逆也", "3213": "海宁封吐血成盆是胃血也胃本多气多血往秋血症复发胃脉逆举血动则气亦动凡胃中蕴结之痰饮湿浊亦无不随气以动痰饮湿浊皆阴之属也故阳为郁而不敷布则晨起恶风病经半年余所投无非温补腻滞则阳益不能通连而痰益聚右胁下漉漉有声厥气上逆或痞聚于中或梗塞于内或浮越于肌肉肤膜则不耐起坐仰息沃沫呕嗳食少大便干溏泄泻不一小便浑赤而少身处重帏畏风如虎种种具在矣阳虚胃弱则宜通和湿浊内蒸则宜淡渗痰饮内聚则宜涤逐病机如此然久病至此才思振理谅难速效也", "3214": "匠人港王癍发数月才退肤腠间尚有𥆧惕麻痹痰饮黏腻舌苔黄滑脉象濡弦右部兼滑总之阳明水谷之湿易酿痰浊以致脾肺之输运难速宜清养肺胃之阴以连脾气远刚用柔从秋令也", "3215": "周渡曹妇晨刻呕沫头运耳鸣由来久矣今年濡泻自春至秋才止左胁痛渐及左背肋舌苔或黄或灰胃钝脉濡此痰饮稽留于肝胆之格而为痛前次之泻亦痰泻也未可竟作血虚肝病论治", "3216": "湖州金本属阳虚之体酷嗜茶酒久而聚饮时苦右胁痛控引胸背短气口干反不渴饮便溏溺涩必吐涎沫肠胃辘转有声始得痛止而凡酒家必易聚饮况平时喜甘味今脉亦沉弦则阳虚饮踞无疑矣宜节饮节劳常服甘药以和之", "3217": "轧村顾两睪丸上控自幼如此则素有筋疝筋疝必易举而善泄力不能及远宜结褵多年而未育也脉得左弦且数宜养肝以治疝若乱投壮阳补肾恐反滋梦泄淋滑之弊且此时断难欲速宜丸以缓调并能节欲尤妙", "3218": "嘉兴曹腹痛无定时亦无定所攻鸣有声而无形得嗳与矢气则稍舒经久不已脉沉而涩此属厥阴气郁而为冲疝也宜柔养其体疏调其用久久自可渐愈", "3219": "又冲气自左上逆俶扰于脘腹胸胁或呕或痛作止不常已经年许脉左弦舌黄时有寒热者即厥阴之为病痛苦寒热也此属肝阳郁结聚为冲疝宜滋养肝阴以调其气", "3220": "洞庭山徐幼患冲疝发则睪丸控引入腹而痛愈后越五六年因疟致鼻衄衄后脘痛屡发发必由右而上妨食便闭必快吐便行而后渐平此仍属疝之上逆脉得弦而近数仍宜从疝冲为病论治丸以缓调差久病根深非能速效耳", "3221": "徽州洪狐疝偏右多年矣疝为任脉之病有所触忤实则下连肝气虚则内连冲逆今年春初即发腹痛攻逆是二者兼有之矣然治法仍以疝为主", "3222": "上海杨初冬疝攻腹痛此属劳倦伤阳饮食阻腑厥阴之气挟任脉逆行而为痛冬底复感温邪咳嗽咽干今口渴舌鲜脉濡弦宜清养肺胃兼调任脉法", "3223": "平望李症情错杂历久迭发不已多属寒疝宿饮二者为病据述自幼有症疝攻于下必致饮聚于中盖疝为厥阴之气频扰于胃则水谷皆易酿为痰浊二者迭为宾主冲逆于上则眩晕耳鸣咳呕络脉阻痹等症皆至矣脉弦滑搏指且曾失血刚药难投则取效不免难速", "3224": "南浔李妇阳虚之体素多痰湿加以操劳悲郁肝风失调乘阳明挟化风以致脘痛彻背旁及胸胁䐜胀痞嗳作止不常然肢面浮脘腹肿是饮溢于外也耳鸣痉搐心悬如饥得食稍缓是风动于中也凡肝升太过必致胃降不及所以大便艰涩而脘痛数月不已也今脉右虚滞左弦数舌苔白腻近燥宜急急通阳涤饮泄肝和胃", "3225": "荻江吴妇腰脊痛自下及于中椎甚则转侧不便肢体渐惰舌黄口燥胃钝心悸头眩耳鸣火升汗泄患经半年余脉象濡弦右关沉滑此属肝郁气滞挟痰阻络由少阳渐及太阳阳明络病宜通腻补益滞矣", "3226": "荻江倪胸背络痛由夏秋外感发热而来则为痰气阻络明矣至今然后咳逆是痰气郁极而欲达也然气痹久则津燥津燥则痰凝痰凝则络益痛舌白口干脉沉全属气机壅塞矣", "3227": "钱家潭厉当脐时痛耎而喜按食难用饱大便燥结得嗳与矢气则快然痛起上春前年屡经下血而音窒不扬喉粗气促脉右虚左弦肺胃大肠津气大虚加以木来乘之宜用柔药通和不可沾沾治痛", "3228": "王泾江陈妇脘腹痞满不能纳食食与动辄痛甚拒按便溏脉沉郁而虚涩投以宣气通痹宋见大效宜柔剂养肝和胃仿塞因塞用法", "3229": "新市范妇气滞痰凝肝胆脾胃失和久矣迩来脘腹膨痛寝食俱废便结气逆脘右症瘕有形痛作则疟止是气扰于中也今痛虽止而脉犹滞舌白腻黄溺未清澈宜通调升降以和之", "3230": "嘉兴莫初因便坚下血血燥生风风阳内扰左胁痛连肩背数发不已蒸痰酿浊弥漫清空堵塞隧络是以有呕逆痞满头重肢痹也脉沉郁右甚舌心黄宜滋液息风清气化痰法缓调久病不可以峻剂劫之", "3231": "南浔汪少腹痛子后午前较甚三月不止加以咳嗽胃钝舌黄少寐亦已月余脉右沉小弦左弦大坚肝脾营虚气郁故腹痛宜以丸缓治肺胃阳虚饮聚故咳而寝食皆乖宜以汤液和之", "3232": "又腹痛少减咳倦如故脉两手皆弦而左尤甚右弦为饮左弦为肝之郁乘脾则环脐痛痛甚于暮是肝胆旺时也肝阳扰肺则咳逆气急胃不和则疲倦少食也", "3233": "石门陈起初便坚后下血痔坠原是阳明大肠金燥为病此痔血也迁延至三年余竟无虚日去血过度多阴络大伤血无统摄有似漏卮肝脾肾三阴俱已枯燥所谓上燥在气下燥在血气竭则肝伤血竭则胃涸水谷所入不能敷布粗者凝滞于上酿为痰浊精者渗泄于下迸迫大肠其心悸气逆近更咳逆是痰将为喘也其便溏日四五度每圊必失血数升脉右芤弦左寸关牢急面黄唇燥舌白如腐是津液气血皆已告匮矣然痔血肠风究属阳明本病此时惟宜急急存养津气以养胃化痰敛涩阴络以安营止血", "3234": "蒋褛吴多痰多湿之体湿热下迫大肠痔血五年肠枯血燥大便艰涩异常肠既传导失职胃之受盛益滞水谷精微半酿痰浊以致中脘结块有形凡中枢不连则周身脉络气机皆阻虽吐痰不少而气逆足软心荡肠鸣神疲等症皆作矣今舌苔黄腻脉右滑数欲和胃化痰必先润肠养血取效虽难耐心调之可也", "3235": "又肠枯血燥胃滞痰凝以致阳明络脉皆为阻遏今左膝肿痛肩项肘背皆痹急宣润燥化痰通络宣痹虽难速效尚不致废", "3236": "王泾江王素体肝阴不足易郁多火所谓木火之质故平日喜进甘凉九秋便溏遽用姜辣烧酒矫枉过正大反其常则大肠既受其燥劫厥阴又助其郁火以致肠血杂下血色紫黯粪色苍黄腹中气聚攻逆亘塞嗳与矢气中仍不快稍有郁怒则寝食皆乖左眦倏红唇燥口干此皆肠血去多风燥火炽之象也凡肠风为病前贤皆主燥论况又挟肝经郁火而发于秋冬之交其为大肠燥金之病明矣不待论及便干唇口燥而可决也且本火偏旺之质阳明肠胃津液易被消烁今病几五旬肠不润则胃亦虚自然痰饮上溢故口燥而恶汤饮饮反喜温也此属久病之兼症又当分别观之今脉得右虚小而静左三部皆小弦见数急当养阳明以止血为要血止则肝得养而不致横逆胃不逆而渐就通和庶乎不至纠缠", "3237": "杭州许烦劳饥饱阳气久虚便血百日营阴又耗以致肝阳挟冲气上逆手指冷懊𢙐呕吐或竟晕厥今诊得脉弦关尺欠柔议通阳平逆为主酸甘化阴为佐", "3238": "海盐吴惊气通于肝肝热则胆寒而胃不和痰涎沃胆风木内震以致心悸头眩耳鸣心神不能自主甚或运仆搐搦此皆内风与痰涎搏击之故也脉象弦小滑宜温胆以熄风和胃以涤浊病经多年恐难全愈", "3239": "塘西劳妇去冬猝发痫症迄今月必数发发在夜昏痉口角血沫必吐痰涎而后醒居平经事不调头运耳鸣心悸食少脉右芤弦近数此属肝郁生风胆虚聚涎猝犯胞络神明遽蒙宜戒尤郁恚恼缓为图治", "3240": "又肝郁生风胆寒聚液夜寐每发痫状痰涎潮流昏不知人甚或失溲平时脉虚而静头痛脊酸耳鸣心悸经事不调前投熄风化痰宋见大效拟养血液以治其本", "3241": "宫衖口宋前年夏怒气伤肝肝胆风木挟痰火内扰致发痫症迄今二年余其神呆善怒默处寡言多吐干呕等症虽皆灭而未净尽近月来神思困倦饮食少进大异常时脉迟弱虚涩惟右寸独大舌苔滑白边白胖中心黑腻微寒而热干咳耳鸣心虚少寐手臂动即振掉此又有风燥之火上刑肺金中劫肠胃宜暂进滋肺养胃泄风化燥方法以化客感", "3242": "善连孙素有痰火风发痫厥居平眩悸耳鸣消渴便难肺胃津气既虚则痰湿愈益凝聚今湿令气蒸胸次欠舒知饥不运足酸脉滑干咳音涩宜滋养肺胃津气以化痰湿", "3243": "双林冯先觉寒热模糊呕吐殊甚继则疟伏分明先参差后间日总计已旬有余日昨疟来寒战而热甚竟日始平汗多消渴额胀胸闷胁痞烦冤疲惫大便越数日一更衣坚硬色黑小溲赤热而不多舌质红而苔凝白脉濡长而数此属暑热之邪由少阳直迫阳明阴痹三焦幸得战汗畅达虽痞闷烦冤而不致十分纠缠宜辛凉清解阳明可望渐愈也", "3244": "嘉兴宋中年以后不免劳郁则形气易虚今秋因感作疟所感者湿故胃易钝气易滞舌黄脉濡阳事不充皆阳明湿困宜先和阳明以祛弊后商培补以复元", "3245": "归安吴伯埙上年秋季发疲疟纠缠至今虽去年间有参差然内蕴之湿迄不能解甚至肿满且发疮痍盖阳虚之体阳益虚则湿热益不能化况疟为经邪留连而暑湿之疟又属阳明多而少阳少阳明属腑每多经邪传腑内阻气化外遏肌肉隧络浸淫漫衍无处不到为肿为胀皆势力之必至也今脉得虚涩似弦舌质光红不但阳为湿困兼之津液亦渐消耗急须存津液和气以为自强之本佐以开太阳阖阳明以止疟消肿必得病魔渐退不致拖延到长夏湿土之时方可免陈陈困积之弊", "3246": "乌镇周念九日竟得寒战而热则暑邪已有外达之机盖战则邪与正相持而可毕达况间日又作疟状则暑当无不达矣其热甚时之昏沉谵语是暑中夹湿之浊邪碍清也暑欲去则湿亦不能独留而其湿流连于肠胃之间者既久且未免夹食夹痧所以肠腑之气奔迫而下夹溏夹痰夹血或多或少腹痛滞下且有干黑之宿垢亦渐错杂而来则湿亦有下泄之机矣暑湿之为疟为痢皆三焦主病脉得左迟濡右较大而见流利舌黄燥纥而不渴胸脘宽舒而纳食无味甚少频转矢气论舌与脉则大肠犹有宿垢留滞宜疏腑化滞专与理气俾宿垢去而气化调则胃当渐醒", "3247": "又昨日仍有疟状神气尚为清净大便连下黑溏数次甚多后虽似痢非痢而腹痛从重亦微稍能纳粥脉得濡而微弦非必疟邪在少阳之弦非必乘土之弦不过涩滞去而渐有流利之机也然舌心苔犹老黄且厚口渴溺少上嗳下转矢气显属肠腑宿滞与湿浊尚未净尽阻其气机故耳疏滞化湿是为要图", "3248": "三诊感症初平遽尔啖饮衣单且思出房未免欲速太甚当此大气升泄湿热蒸腾之际即强壮无病亦须加意调护以防客气之侵况体虚病后乎五六日来忽寒忽热热时烦冤呕恶消渴喜凉两额筋掣耳鸣面赤汗出涔涔甚至神昏错语热退则肢冷引衣自覆此皆湿热之邪郁蒸未化阻遏气腑充斥三焦故唇燥齿干舌苔或干或润而黄苔究未肯退嗳闷䐜胀寝食俱废脉得弦大而数分观之似乎肝胆肠胃者病且似虚实混淆其实三焦湿热为病如是耳虚弱之体平时极宜小心既病不可躁急则病不易受而重者轻矣", "3249": "归安徐初起寒热不常而咳嗽较盛继以间日疟状四作寒热俱甚呕逆汁多便溏或泻咳痰浓而黄舌苔白腻粗厚脉象弦滑之中反似有力可见初起原是新凉引动伏饮因素体多痰聚饮蓄之既久则出之必多阻遏肺胃则寒热交战即所谓无痰不成疟也今据脉象痰饮之留于中者尚多必须缓为清化毋任逗遛致生他变", "3250": "双林刘阳虚积湿体肥多痰湿热内酿则大筋软短小筋弛长而痿躄矣其所由来非伊朝夕酒容便燥即是见端即须通养阳明腑络并调脉濡右滑慎勿杂投热补表散之剂", "3251": "吴楼于素体阳虚湿胜湿酿成痰易汗畏风又有肠痔可见阳虚者阴亦不足也今夏软脚而肿满而赤便涩湿当渗导使之下趋得温之运得补之壅则湿反随气蒸腾而上脉症参看不但虑其成痿且虑其成肿急宜疏通阳明腑络", "3252": "光按此乃湿热壅滞将成痿象与上痿症截然两途比而观之可益人智乌镇李足肿而软步履维艰两手大指亦皆微痹溺涩而黄时有气逆脉浮濡滑此阳明湿痰蒸热气络皆弛而为痿躄也去夏会发今又三月矣急清阳明以化通之", "3253": "嘉兴汪先觉左足中指斜外侧之筋酸疼驯致两足皆痿軃曳不良于行者已两年除脉沉迟便难舌微白此湿热郁于肺胃而成痿躄也肺病则治节不行故痰多而不耐右卧胃病则大筋软短小筋弛长日久病深难望全愈若得扶杖徐行庶可逍遥晚岁矣", "3254": "大河施谦山痹痛起于长夏愈而复作今又月余初起手足关节等痛而且肿此固痹也湿甚于风则兼肿前贤谓风寒湿三气台而为痹又有行著痛三痹之别可知痹症中必当细辨也今诸处皆愈惟左膝犹肿挛而难伸腘外侧之筋时或掣痛闻木声亦痛此痹在阳明而兼少阳也舌黄不渴胃钝少纳易汗脉濡涩湿盛于风显然矣宜专治阳明以通络化湿兼治少阳以养络熄风冀其速效不致纠缠成疾", "3255": "新市高烦劳伤阳阳虚气痹升降不和脉络滞痛痛自左肩下至右腰及尻且作止不常呕逆头疼舌黄便结是病在气络矣和阳平肝通络化痰未可专用太阳之药", "3256": "新塍卜湿热之邪混杂三阳迄今旬日虽壮热神昏身痛等症俱退而邪势留经入腑膀胱气痹少腹高突拒按小溲淋沥大便闭结所谓邪犯太阳之本已成胞痹矣脉来弦滑宜急急宣通少腑以防湿浊阴邪上逆喘脱", "3257": "又大小便虽俱通然宿矢未尽胞痹未平舌黄脉右弦实仍宜通利犹在险途", "3258": "嘉兴陆妇在脘右膝痛肿甚于他处痛属风肿属湿属热未可执定前贤风寒湿三至成痹论治也体肥必多湿必畏热当此湿热郁蒸之时稍感风邪则痹痛作矣迄今两旬投羌桂辄作咽痛而胃钝便溏身动则痛剧驯致头痛肢体发热口干舌燥有裂纹苔黄气虫惊惕少寐兼有错语自觉神思不清脉右滑大而数左弦数其为阳明热痹痹在脉络不在筋骨明矣痹既在络脉则躯壳之病虽重无碍今热的阳明内偪心胃则高年岂可轻视右滑大显属湿酿成痰胃热及肺急宜滋肺胃养心营以化热化痰为要因症施治不致痰热内蒙则吉", "3259": "湖州汪左臂痛止后右手脘及左足肿痛此名流火乃湿热阻遏阳明之络非伤科病也湿热阻腑所以舌黄便干胃钝今脉弦数急宜疏腑以化湿热", "3260": "吴家兜张胃气稍醒声音略爽脉左部弦数右部尺同而寸关皆见虚弱前方通补脾胃肾服之颇投绝无饱胀腻鬲之弊惟药饮到咽辄觉刺痛且咽痛左右不同而隆冬不喜暖帽卧喜著左涎沫时溢寐则口涎自流身凝热口燥便难似乎津液之虚燥火之炎不独阳明且多太阴症矣合观脉象则竟属秋燥之气劫为多肺热痿躄固亦足虑也议清燥救肺为主养胃存津为佐再图缓效", "3261": "双林王喉癣初发时原属太阴肺金气燥津伤迁延半年肺既虚耗子必救母未免少阴之火上炎矣痰涎涌溢食物梗涩吐纳大坚饷这先绝脉弦而数势颇可尤惟宜返视内听屏除一切再以静药滋养金水希冀获效", "3262": "长兴周喉癣紫筋牵络蒂丁赤痿食后少腹胀厨后溺孔有精茎中掣痛肾脏风脉搏数阴液不足肝肾虚火游行上下有失血溺血之虑尚敢以火济火急急加数月静养功夫以涵养之", "3263": "神墩僧先喉中介介继以咳嗽音哑而痛痰来日以碗许近更吐血喉间臭气啧溢迄今年余脉浮大数右手为甚此内喉痈也病不在咽故纳食无大碍然高年肺气大耗岂能无虑", "3264": "乌镇潘初起恶寒咳引左胁痛痰蒲原是寒郁肺卫气络阻痹即是伤风重症苇茎汤等可解也奈邪郁不解而为肺瘫吐脓至今已经月余犹然气秽色浊周身汁泄阵嗽或呕胃纳颇少脉象虚小而弦凡肺痈咳吐脓血每症如是犹不足怪所虑者久不得寝汗多食少耳此时以咳嗽爽利为要且须汗敛食增庶乎无虑", "3265": "乌镇郑肝胃郁火上扰左上龈齿痛数月不止致成牙痈溃逾两旬肿痛虽减脓从鼻腭来尚未尽甚至顿车不舒脉弦且劲咽梗便燥急当息虑戒怒以静养肝胃法调之", "3266": "泗安许素来体肥多痰上年春夏痰出遽少此非生痰之源遽清乃气化之郁也郁极则生火所以季秋先觉咽痛左耳前后痛继见上腭肿后且左颈颏亦肿此必郁怒劳心之故故少阴心手少阳足厥阴肝胆之火勃动于中上炎清空则内郁之痰亦因火之势上壅络脉而致内外皆肿至于此极也迄今已阅四月然正其名则咽腭之肿是上腭痈也蔓延于外左侧颈颌之肿上至额颅右及愿颊坚硬不痛是马刀侠缨也病之源虽一而症之象有二此姑不俱论但近来吞吐日艰饮食日少肿势日盛精气日削投治之要首重饷道议补议清皆属迂图然脉得小弦数而沉滑夫小为气虚气虚则痰益难化数为血虚血虚则火益难清况弦为木火沉滑为痰伏在里故上腭色红舌根肿强舌苔滑白清涎黏腻咯之欠利便结溺赤都属无形之火与有形之痰胶固煎灼加城狐社鼠之盘踞矣症情既已如此而斡旋之法自必择其要且急者而先图之其先则莫要于先通饷道欲吞吐得利则势不出乎上腭之溃脓或胶固之痰火出外舍此二者转机虽有恐缓不及时耳谨拟煎散并进法庶几治痰不偏乎燥峻清火不致乎腻滞然恐轾材不能胜此观巨", "3267": "澉浦陈初因痰气凝聚腹右有块隐见不常或微痛阅半年余而竟溃脓似腹皮痈迄今又复半年末敛脉小弦近数总之不治痰气因循至此耳", "3268": "长兴朱肝脾肾三阴皆亏之体故居常有梦泄痰多左膺跳痛等症盖虚则痰火易生近来颈疬串发咽干蒂丁下垂脉濡弦数宜清理浮游之痰火以消颈疬为先", "3269": "又鼻衄脉濡此肺脾络伤瘀阻饮聚防成内痈慎勿轻视", "3270": "一治病所凭在脉。故叙证而兼叙脉者始选之。若不载脉象。但侈治验。入选奚益。盖治病之难。难于识病。识病之难。难于识脉也。然集中间收不载脉者。必辨证详明。或治法新奇。或立论高超。不得以不载脉象而弃之。略备数条。以扩识见。", "3271": "一前人案中。或涉鄙俚矜夸之语概削去。只存其脉证方论。以为后人认病之法。偶有文繁及词晦者。僭为修饰之。不敢窜改其意。亦仅条达其辞以便观览而已。知我者谅不我罪。", "3272": "一诸案所载有妙义者。议论精详方药切当者。以及叙脉病因证候紧要关键处均加密点。若震自为按断之语。概不敢置密点。以俟高贤之教正。", "3273": "唐书载许允宗初仕陈。为新蔡王外兵参军。时柳太后感风不能言。脉沉而口噤。允宗曰。口不下药。宜以汤气蒸之。令药入腠理。周时可瘥。遂造黄耆防风汤。煮数十斛。置床下。气如烟雾。熏蒸之而得语。遂超拜义兴太守。", "3274": "震按书称允宗医术若神。曾曰医者意也。在人思虑。即此条思虑巧矣。然仅可治真中风。内经所谓其有邪者渍形以为汗也。邪从汗解故得语。若概试诸不能言者决无效。又按罗谦甫治史太尉。冬月坐火炉左侧。觉面热。左颊微汗。旋出外。因左颊疏缓。被风寒客之。右颊急。口㖞于右。脉浮紧。按之洪缓。罗用升麻汤加桂枝、白芷、艽、防。兼灸地仓颊车穴。此治风中阳明经之表证也。赵僧判半身不遂。语言不出。神昏面红。耳聋鼻塞。六脉弦数。罗谓中藏者多滞九窍。中府者多著四肢。今脏腑俱受邪。先用三化汤行之。通其壅滞。使清气上升。充实四肢。次与至宝丹。安心养神。通利九窍。五日。音声出。语言稍利。惟行步艰难。又刺十二经之井穴以接经络。随四时脉症加减用药。百日方愈。此治中腑兼中脏之里证也。皆风邪实证也。张安抚半身不遂。语言謇涩。自汗恶风。痰嗽不寐。罗谓风寒伤形。忧恐忿怒伤气。经云。形乐志苦。病生于脉。神先病也。邪风加之。动无常处。治病必求其本。邪气乃服。用加减冲和汤。汗加黄耆。嗽加五味。其昼夜不睡。因心事烦冗。心火上乘阳分。卫气不得入于阴。用朱砂安神丸。遂得寐。诸证渐减。惟右肩臂痛。经云。虚与实邻。决而通之。又云。下陷者灸之。为阳气下陷入阴中。故肩膊痛不能动。宜以火导之补之。乃于右肩臂上肩井穴。先针后灸。隔一月。再灸肩井。次于尺泽穴。各灸二十八壮。引气下行。与正气相接。遂能运动。仲夏用清肺饮子。秋分用益气调营汤。全愈。此治中经兼中腑。本虚标实之症也。许允宗所治亦系本虚标实者。但病起于暴。故用蒸法。亦如通关散之取嚏。稀涎散之探痰也。", "3275": "丹溪治浦江郑君。年近六旬。奉养膏粱。仲夏久患滞下。又犯房劳。一夕如厕。忽然昏仆。撒手。遗尿。目上视。汗大出。喉如拽锯。呼吸甚微。其脉大而无伦次部位。可畏之甚。此阴虚而阳暴绝也。急令煎人参膏。且与灸气海穴。艾壮如小指。至十八壮。右手能动。又三壮。唇微动。参膏成。与一盏。至半夜后。尽三盏。眼能动。尽二斤。方能言而索粥。尽五斤而利止。十数斤全安。", "3276": "赵以德云。余尝治陈学士敬初。因醮事跪拜间。就倒仆。汗如雨。诊之脉大而空虚。年当五十。新娶少妇。今又从跪拜之劳役。故阳气暴散。正若丹溪治郑义士之病同。急煎独参浓汤。连饮半日。汗止。神气稍定。手足俱纵。喑而无声。遂于独参汤中加竹沥。开上涌之痰。次早悲哭。一日不已。以言慰之。遂笑。复笑五七日。无已时。此哭笑者。为阴虚而劳。火动其精神魂魄之藏。气相并故耳。正内经所谓五精相并者。心火并于肺则喜。肺火并于肝则悲是也。加连柏之属泻其火。更增荆沥开其闭。八日笑止手动。一月能步矣。", "3277": "丹溪治一妇人。年六十余。手足左瘫。不言而健。有痰。以麻黄。羌活、荆、防、南星、全蝎、乳香、没药、木通、茯苓、桔、朴、甘草、红花为末。酒下。未效。时春。脉伏而微。又以淡盐汤入韭汁。每早一碗吐之。至五日。仍以茯苓、白术、陈皮、甘草、厚朴、菖蒲。日进二服。又以川芎、豆豉、山栀、瓜蒂、韭汁、盐汤。吐甚快。后以四君子汤服之。另以川归、酒芩、红花、木通、厚朴、黏子、苍术、南星、牛膝、茯苓为末。酒糊丸服。十日后。微汗。手足微动而言。", "3278": "震按前条脱症。脉大无伦。此条闭症。脉伏而微。非有确见。敢用此两路重药乎。须知症与脉宜合参。如此条左瘫不言矣。而健又有痰。其得间在此。与浦江洪宅妇病疟无脉条相似。", "3279": "又按丹溪治肥人中风。口㖞。手足麻废。左右俱作痰治。以蒌、贝、南星、橘、夏、二术、芩、连、柏、荆、防、羌活、桂枝、威灵仙、甘草、花粉等。好吃面。加附子煎。入竹沥、姜汁。更加少酒行经。此大法也。故治中风二十六案。用此加减者甚多。其余以四君、六君。或合四物。或再加连、柏、耆、防、天麻、僵蚕、竹沥等。或合风药。更有加全蝎、地龙者。又有用小续命汤、搜风汤、羌活愈风汤、乌药顺气散、苏合香丸者。皆不载脉象若何。何以效法。故不并录。", "3280": "虞恒德治一妇年五十七。身肥白。春初得中风。暴仆不知人事。身僵直。口噤不语。喉如拽锯。水饮不能入。六脉浮大弦滑。右甚于左。以藜芦末一钱。加麝香少许。灌入鼻窍。吐痰升许。始知人事。身体略能举动。急煎小续命汤倍麻黄。连进二服。覆以衣被。得汗渐苏醒。能转侧。但右手足不遂。语言謇涩。复以二陈汤加芎、归、芍药、羌、防等。合竹沥、姜汁。日进二三服。若三四日大便不利。则不能言语。即以东垣导滞丸。或润肠丸微利之。则言语复正。如此调理。至六十余。得他病而卒。", "3281": "震按此条与上丹溪案。俱以实邪治而效。可见辨证宜真。不得专守景岳非风之论。先有成见在胸也。如薛立斋善于用补。而治艾郭武牙关紧。不能言。左体瘫。口眼牵动。神昏欲绝。六脉沉细而涩。谓此中寒湿。非中风也。亦用吐痰药及至宝丹。继以五积散加木香、南星、附子而人苏。后大便洞利痰积而全愈。临斯证者。治虚寒。治风痰。固宜对勘。", "3282": "秀才刘允功。形体魁伟。不慎酒色。因劳怒头晕仆地。痰涎上涌。手足麻痹。口干引饮。六脉洪数而虚。薛以为肾经亏损。不能纳气归源而头晕。不能摄水归源而为痰。阳气虚热而麻痹。虚火上炎而作渴。用补中益气合六味丸。治之而愈。其后或劳役。或入房。其病即作。用前药随愈。", "3283": "宪幕顾斐斋左半身并手不遂。汗出神昏。痰涎上涌。王竹西用参耆大补之剂。汗止而神思渐清。颇能步履。后不守禁。左腿自膝至足肿胀甚大。重坠如石。痛不能忍。其痰甚多。肝脾肾脉洪大而数。重按则软涩。立斋朝用补中益气汤加黄柏、知母、麦冬、五味。煎送地黄丸。晚用地黄丸料加知、柏。数剂诸证悉退。但自弛禁。不能全愈耳。", "3284": "车驾王用之。卒中昏愦。口眼㖞斜。痰气上涌。咽喉有声。六脉沉伏。此真气虚而风邪所乘。以三生饮一两。加人参一两。煎服即苏。立斋曰。若遗尿撒手。口开鼾睡为不治。用前药亦有得生者。夫前饮乃行经络治寒痰之药。有斩关夺旗之功。每服必用人参两许。驾驭其邪而补助真气。否则不惟无益。适足以取败矣。", "3285": "震按此治中寒寒痰壅塞气道之药。肥人脉沉伏。无火象者。可用之。若脉微细者。必加人参。实非中风药也。折肱漫录云。三生饮施于中风之寒症。妙矣。或有虚火冲逆。热痰壅塞。以致昏愦颠仆者。状类中风。恐乌附非所宜服。立斋治王进士失于调养。忽然昏愦。谓是元气虚。火妄发。挟痰而作。急灌童便。神思渐爽。更用参、耆各五钱。芎、归各三钱。元参、柴胡、山栀、炙草各一钱。服之少定。察其形倦甚。又以十全大补汤加麦冬、五味治之而安。予从弟履中。年方强壮。以劳心忧郁而得斯证。痰升遗溺。眼斜视。逾时不醒。竟类中风。亦灌以童便而苏。此等证候。皆火挟痰而作。断非三生饮所可治者。并姜汤亦不相宜也。同一卒然昏愦。而所因不同。须细审之。", "3286": "孙东宿治程晓山。年四十。诞辰庆贺。宴乐月余。忽谓孙曰。近觉两手小指及无名指。掉硬不舒。亦不为用。口角一边常牵扯引动。幸为诊之。六脉皆滑大而数。浮而不敛。其体肥。其面色苍紫。乃曰。据脉滑大为痰。数为热。浮为风。盖湿生痰。痰生热。热生风也。君善饮。故多湿。近又荒于色。故真阴竭而脉浮。此手指不舒。口角牵扯。中风之兆也。所喜面色苍紫。其神藏。虽病犹可治。切宜戒酒色以自保爱。立方用二陈汤加滑石为君。芩连为臣。健脾消痰。撤湿使从小便出。加胆星、天麻以定其风。将竹沥、姜汁三拌三晒。仍以竹沥糊丸。取竹沥引诸药入经络化痰。外又以天麻丸滋补其筋骨。标本两治。服二料。几半年。不惟病痊。且至十年无恙。迨五十岁。贺寿如旧。召妓宴乐亦如旧。甘酒嗜饮。荒淫而忘其旧之致疾也。手指掉硬。口角牵引尤甚。月余中风。右体瘫痪矣。再邀孙诊之。脉皆洪大不敛。汗多不收。呼吸迫促。孙曰。此下虚上竭之候。盖肾虚不能纳气归元。故汗出如油。喘而不休。虽和缓无能为矣。阅二十日而卒。", "3287": "东宿曰。潘见所年四十七。微觉阳痿。其脉上盛下虚。上盛为痰与火。下虚为精元弱。宜戒色慎怒。恐痰生热而热生风。将有中风之患。次年中秋。连宵酒色。渠于色后。惯用鹿角胶三钱。人参一钱。酒送下。至是加倍服之。十七日。左手陡然颤动。重不能举。十八日。左边半体手足皆不用矣。予始观面色赤。口微㖞向右。唇麻。左瘫。诊之左弦大。右滑大。先用乌药顺气散一帖。服后昏睡半日。醒觉面更加赤。㖞亦稍加。知痰盛使然。即以二陈汤加全蝎、僵蚕。天麻。黄芩、石菖蒲、红花、秦艽。煎冲竹沥、姜汁。一日两进。晚更与活络丹。服至第六日。手指稍能运动。足可依棹而立。予喜曰。机动矣。改用归芍六君子汤加红花、钩藤、天麻、竹沥、姜汁。服二十帖。行可二十步矣。手指先麻木不知痛痒。至是能执物。继用天麻丸、五子全鹿丸调理。幸其断酒绝欲。百日全愈。此证予历治历效者。良由先为疏通经络。活血调气。然后以补剂收功。惟经络疏通。宿痰磨去。补之必效。此治类中风之法也。", "3288": "震按此条先散后补。亦缘病初无卒仆昏愦之症。且脉滑大。故可从容施治耳。若云必先疏通经络。磨去宿痰。然后补之得效。又属呆板方法矣。", "3289": "杨季衡禀丰躯伟。年近七旬。得半身不遂证二年矣。病发左半。口往右㖞。昏厥遗溺。云间施笠泽以参附疗之。稍安。喻嘉言曰。其脉软滑中时带劲疾。是痰与风杂合之症。又内热与外寒杂合之症。房帏不节。精气内虚。膏粱蕴热。久蒸脾湿为痰。痰阻窍隧。而卫气不周。外风易入。是以杂合而成是症。及今大理右半脾胃之气。以运出左半之热痰虚风。此其间有微细曲折。非只温补一端所能尽也。或曰。痰热先宜中右。何以反中左。既已中左。何以反治右耶。喻曰。此正病机之最要者。向为丹溪等说病在左血多。病在右气多。教人如此认症。不知内经但言左右者。阴阳之道路。夫左右既为阴阳往还之道路。何尝可偏执哉。况左半虽血为主。非气以统之则不流。右半虽气为主。非血以丽之则易散。故病在一偏者。治宜从阴引阳。从阳引阴。从左引右。从右引左。譬之树木有偏枯者。将溉其枯者乎。抑溉其未枯者。使荣茂而因以条畅其枯者乎。此证之脉。软为虚。滑为痰。劲疾为风。病因杂合。必须用杂合之药。而随时令以尽无穷之变。参、术是主药。冬月佐干姜、附子。以暂撤外寒而内热反得宣泄。春夏秋则佐以羚羊角、柴胡、知母、石膏。使内蕴之热不与时令之热相蒸灼。再刺手足四末以泄荣血而通气。恐热痰虚风。久而成疠也。", "3290": "有一妇人。先胸胁胀痛。后四肢不收。自汗如雨。小便自遗。大便不实。口紧目𥆧。或以为中脏。甚忧。请薛立斋视之。曰。非也。若风既中脏。真气既脱。恶证既见。祸在反掌。安能延至十日。乃候其色。面目俱赤而或青。诊其脉。左三部洪数。惟关尤甚。乃知胸乳胀痛。肝经血虚。肝气痞塞也。四肢不收。肝经血虚。不能养筋也。自汗不止。肝经血热。津液妄泄也。小便自遗。肝经热甚。阴挺失职也。大便不实。肝木炽盛。克脾土也。遂用犀角散四剂。诸证顿减。又用加味逍遥散调理而安。", "3291": "给谏晏怀泉夫人。先患胸腹痛。次日卒然晕倒。手足厥逆。时有医者。以牛黄丸磨就将服矣。士材诊之。六脉皆伏。惟气口稍动。此食满胸中。阴阳痞隔。升降不通。故脉伏而气口独见也。取陈皮、砂仁各一两。姜八钱。盐三钱。煎汤灌之。以指探吐。得宿食五六碗。六脉尽见矣。左关弦大。胸腹痛甚。知为大怒所伤也。以木香、青皮、橘红、香附、白术煎服。两剂痛止。更以四君子加木香、乌药。调理十余日方瘥。此是食中兼气中。", "3292": "章仲舆令爱在阁时。昏晕不知人。苏合香丸灌醒后。狂言妄语。喃喃不休。士材诊之。左脉七至。大而无伦。右脉三至。微而难见。正所谓两手脉如出两人。此祟凭之脉也。线带系定二大拇指。以艾炷灸两介甲。至七壮。鬼即哀词求去。服调气平胃散加桃奴。数日而祟绝。此即恶中也。", "3293": "易思兰治瑞昌王孙毅斋。年五十二。素乐酒色。九月初。夜起小解。忽倒地。昏不知人。目闭气粗。手足厥冷。身体强硬。牙关紧闭。诸医有以为中风者。有以为中气中痰者。用乌药顺气散等药。俱不效。又有用附子理中汤者。愈加痰响。五日后。易诊之。六脉沉细紧滑。愈按愈有力。乃曰。此寒湿相搏。痓症也。痓属膀胱。当用羌活胜湿汤。其兄宏道问曰。病无掉眩。知非中风。然与中气中痰夹阴三者相似。先生独云痓病。但吾宗室之家过于厚暧者有之。何由得寒湿而成痓病耶。易曰。运气所为。体虚者得之。本年癸酉。岁火不及。寒水侮之。季夏土旺。土为火子。即能制水。七月八月。主气是湿。客气是水。寒水得令。不伏土制。是以寒湿相搏。太阳气郁而不行。其证主项背强直。卒难回顾。腰似折。项似拔。乃膀胱经痓病也。其脉沉细紧滑。沉为病在里。细为湿。紧为寒。中又有力而滑。此寒湿有余而相搏也。若虚证之脉。但紧细而不滑。若风脉当浮。今脉不浮而沉。且无掉眩等证。何为中风。若痰气之脉不紧。今脉紧而体强直。何言中气中痰。痓病诗云。强直反如弓。神昏似中风。痰流唇口动。瘛疭与痫同。乃先以稀涎散吐痰一二碗。昏愦即醒。随进胜湿汤。六剂全愈。以八味丸调理一月。精气复常。", "3294": "江少微治黄三辅。年逾四旬。醉饮青楼。夜卧当风。患头痛发热。自汗盗汗。饮食不进。医治十余日罔效。诊得六脉浮洪。重按豁然。此饮酒当风。名曰漏风。投以白术、泽泻。酒煎服而热退。汗仍不止。心口如水。此思虑所致。与归脾汤加麻黄根、桂枝。十服而愈。头痛不已。用白萝卜汁吹入鼻中。立止。", "3295": "〔附伤风戴阳症〕石开晓病伤风咳嗽。未尝发热。自觉急迫欲死。呼吸不能相续。西昌诊之。见其头面赤红。躁扰不歇。脉亦豁大而空。谓曰。此证颇奇。全似伤寒戴阳症。何以伤风小恙亦有之。急宜用人参附子等药。温补下元。收回阳气。不然。子丑时一身大汗。脱阳而死矣。渠不信。及日落。阳不用事。愈慌乱不能少支。忙服前药。服后。稍宁片刻。又为床侧添同寝一人。逼出其汗如雨。再用一剂。汗止身安。咳嗽俱不作。询其所由。云连服麻黄药四剂。遂尔躁急欲死。然后知伤风亦有戴阳证。与伤寒无别。总因其人平素下虚。是以真阳易于上越耳。", "3296": "吴球治一人。暑月远行。渴饮泉水。至晚以单席阴地上睡。顷间。寒热。吐泻不得。身痛如刀刮。医曰。此中暑也。进黄连香薷饮及六和汤。随服随厥。吴诊其脉细紧而伏。曰。此中寒也。众皆笑曰。六月中寒。有是事乎。吴曰。人肥白。素畏热。好服黄连及益元散等凉剂。况途中饮水既多。又单席卧地。寒邪深入。当以附子理中汤。大服乃济。用之果效。", "3297": "许学士治乡人邱生者。病伤寒发热。头痛烦渴。脉虽浮数而无力。尺以下迟而弱。许曰。虽麻黄证。而尺迟弱。仲景曰。尺中迟者。营气不足。未可发汗。用建中汤加当归、黄耆。翌日脉尚尔。其家索发汗药。言几不逊。许忍之。只用建中调营而已。至五日。尺部方应。遂投麻黄汤二服。发狂须臾。稍定略睡。已得汗矣。信乎医者当察其表里虚实。待其时日。若不循次第。取效暂时。亏损五脏。以促寿限。何足贵也。", "3298": "一人病伤寒。大便不利。日晡潮热。两手撮空。直视喘急。更数医矣。许曰。此诚恶候。见之者九死一生。仲景虽有证而无治法。况已经吐下。难于用药。勉强救之。若大便得通而脉弦。则可生。乃与小承气一服。大便利。诸疾渐退。脉且微弦。半月愈。或问曰。下之而脉弦者生。此何谓也。许曰。仲景云。循衣妄撮。怵惕不安。微喘直视。脉弦者生。涩者死。微者但发热谵语者。承气汤主之。予观钱氏直诀云。手循衣领及捻物者。肝热也。此症在仲景列于阳明部。盖阳明者胃也。肝有热邪。淫于胃经。故以承气汤泻之。且得弦脉。则肝平而胃不受克。所以有生之理也。", "3299": "〔附〕楼全善曰。尝治寻衣撮空。得愈者数人。皆用大补气血之剂。惟一人兼𥆧振脉代。遂于补剂中加桂二分。亦振止脉和而愈。", "3300": "一人病伤寒。初呕吐。俄为医下之。已八九日。而内外发热。许诊之。曰。当用白虎加人参汤。或曰。既吐复下。宜重虚矣。白虎可用乎。许曰。仲景云。若吐下后。七八日不解。热结在里。表里俱热者。白虎加人参汤。盖始吐者。热在胃脘。今脉洪滑。口大渴。欲饮水。舌干燥而烦。非人参白虎不可也。", "3301": "一人病伤寒。心烦喜呕。往来寒热。医以小柴胡与之。不除。许曰。脉洪大而实。热结在里。小柴胡安能去之。仲景云。伤寒十余日。热结在里。复往来寒热者。与大柴胡汤。三服而病除。", "3302": "一人太阳症。因发汗不止。恶风。小便数。足挛急。屈而不伸。脉浮而大。许曰。此证在仲景方中有两条。大同小异。一则太阳病。发汗。遂漏不止。恶风。小便难。四肢微急。难以屈伸。一则伤寒脉浮。自汗出。小便数。心烦。微恶寒。脚挛急。一属漏风小便难。一属有汗小便数。不可混治。此当用桂枝加附子汤。三啜而汗止。佐以芍药甘草汤。足便得伸。", "3303": "一武官为寇执。置舟中𦪗板。数日得脱。乘饥恣食。良久解衣扪虱。次日遂伤寒。自汗而鬲不利。一医作伤食而下之。一医作解衣中邪而汗之。杂治数日。渐觉昏困。上喘息高。许诊之。曰。太阳下之。表未解。微喘者。桂枝加厚朴杏仁汤。此仲景法也。指令医者治此药。一啜喘定。再啜热缓微汗。至晚身凉而脉已和矣。医曰。某平生未尝用仲景方。不知其神捷如此。", "3304": "项彦章治一人。病发热。恶风自汗。气奄奄勿属。医作伤寒治。发表退热而益剧。项诊其脉。阴阳俱沉细。且微数。以补中益气进之。医曰。表有邪而以参耆补之。邪得补而愈甚。必死此药矣。项曰。脉沉。里病也。微数者。五性之火内煽也。气不属者。中气虚也。是名内伤。经云。劳者温之。损者益之。饮以前药而验。", "3305": "震按名医类案有内伤一门。此条亦在其内。但予细观诸案所叙病证。皆与伤寒仿佛。则其病之为伤寒为内伤。惟在医者之能辨耳。非另有一种情形也。东垣内外伤辨。殊不足凭。诸案皆以脉为辨。大抵内伤之脉。皆虚大无力。或微数无力。其药不外补中益气汤甘温为主。有风寒加入表药。有停滞加入消导。有火亦加一二味凉药。无他奇巧。故今采取数条。编入伤寒温暑各门。删去内伤。免滋眩惑。外感风寒者伤其形。故曰伤寒。劳役过度饮食失节者伤其气。故曰内伤。此言受病之原也。及其为病。一般发热头疼恶风恶寒。甚则痞闷谵妄。岂可就其述病原而作凭据。医者见得真。乃能分晰之曰。彼是伤寒。此是内伤。亦如伤寒一门为虚为实。为热为寒。头绪纷纭。听人审辨。故区而别之。不若汇而参之之有所得也。", "3306": "李东垣治西台椽葛君瑞。二月中病伤寒发热。医以白虎汤投之。病者面黑如墨。本证遂不复见。脉沉细。小便不禁。东垣初不知也。及诊之。曰。此立夏前误用白虎之故。白虎大寒。非行经之药。不善用之。则伤寒本病。曲隐于经络之间。或更以大热之药求以去阴邪。则他证必起。非所以救白虎也。宜用温药之升阳行经者。或难曰。误用大寒。若非大热。何以救乎。李曰。本病隐于经络间。阳不升则经不行。经行而本证见矣。果如其言而愈。", "3307": "冯内翰之侄栎。年十六。病伤寒。目赤而烦渴。脉七八至。医欲以承气下之。东垣诊之。脉虽七八至。按之不鼓击。内经所谓脉至而从。按之不鼓。诸阳皆然。此阴盛格阳于外。非热也。与姜附之剂。汗出而愈。", "3308": "〔附〕刘宗厚曰。此与王海藏治狂言发斑。身热。脉沉细。阴症例同。东垣又有治脚膝痿弱。下尻臀皆冷。阴汗臊臭。精滑不固。脉沉数有力。为火郁于内。逼阴内外。名阳盛拒阴。用苦寒下之者。此水火征兆之微。脉证治例之妙也。", "3309": "王海藏治侯辅之病。脉极沉细。内寒外热。肩背胸胁斑出十数点。语言狂乱。或曰。发斑谵语。非热乎。王曰。非也。阳为阴逼。上入于肺。传之皮毛。故斑出。神不守舍。故错语如狂。非谵语也。肌表虽热。以手按执须臾。冷透如冰。与姜附等药二十余两。乃大汗而愈。后因再发。脉又沉迟。三四日不大便。与理中丸。三日内约半斤。其疾全愈。侯公之狂。非阳狂之狂。乃失神之狂。即阴也。", "3310": "〔附〕准绳载一人。伤寒七八日。服凉药太过。遂变身凉。手足厥冷。通身黑斑。惟心头温暖。诊其六脉沉细。昏沉不知人事。亦不能语言。状似尸厥。遂用人参三白汤。加熟附子半枚。干姜二钱。服下一时许。斑色渐红。手足渐暖而苏醒。然黑斑有因余热不清者。又当以黄连解毒。竹叶石膏汤调之而愈。", "3311": "罗谦甫治南省参议官常德甫。至元甲戌三月间。赴大都。路感伤寒证。邀罗治之。两手脉皆沉数。外证却身凉。四肢厥逆。发斑微紫。见于皮肤。唇及齿龈破裂无色。咽干声哑。默默欲眠。目不能闭。反侧不安。大便闭结。此证乃热深厥亦深。变成狐惑。其证最急。询之从者。曰。自初病感冒至今。服发汗药。汗出极多。渐至于此。罗曰。平昔膏粱。积热于内。已燥津液。又兼发汗过多。津液重竭。因转属阳明。故大便难也。急以大承气下之。得更衣。再用黄连解毒汤。病减大半。复与黄连犀角汤。数日而愈。", "3312": "〔附〕准绳载一妇人。狐惑声哑。多眠。目不闭。恶闻食臭。不省人事。半月后。又手足拘强。脉数而微细。先与竹沥、姜汁一盏服之。忽胸中有汗。肠鸣。即目闭省人事。遂用参、术、归、陈。入竹沥、姜汁饮之。五六帖而愈。", "3313": "浙东宪使曲公病。召沧洲翁吕元膺往视。翁察色切脉。则面带阳气。寸口皆长而弦。盖伤寒三阳合病也。以方涉海。为风涛所惊。遂血菀而神慑。血为热所搏。吐血一升许。且胁痛烦渴谵语。适是年岁运。左尺当不应。其辅行京医。泣告其左右曰。监司脉病皆逆。不禄在旦夕。家人皆惶惑无措。翁曰。此天和脉。无忧也。为投小柴胡汤。减参加生地黄。俟其胃实。以承气汤下之愈。", "3314": "震按许学士以尺脉迟弱为营气不足。吕沧洲以左尺不应为天和脉。二义亦皆古书所载。非二公新得。而引证恰当。各奏功效。由于诊候熟而心思灵也。", "3315": "赵氏子病伤寒十余日。身热而人静。六脉尽伏。俚医以为死人也。弗与药。吕元膺诊之。三部举按皆无。其舌胎滑。而两颧赤如火。语言不乱。因告之曰。此子必大发赤斑。周身如锦纹。夫脉血之波澜也。今血为热邪所搏。淖而为斑。外见于皮肤。呼吸之气。无形可依。犹沟渎之水。虽有风。不能成波澜。斑消则脉出矣。及揭其衾。而赤斑烂然。即用白虎加人参汤化其斑。脉乃复常。继投承气下之愈。发斑无脉。长沙所未论。元膺盖以意消息耳。", "3316": "全本然伤寒旬日。邪入于阳明。俚医以津液外出。脉虚自汗。进真武汤实之。遂致神昏如熟睡。其家邀元膺问死期。切其脉。皆伏不见。而肌热灼指。告其家曰。此必荣热致斑而脉伏。非阳病见阴脉比也。见斑则应候。否则蓄血耳。乃视其隐处及小腹。果见赤斑。脐下石坚。且痛拒按。为进化斑汤。半剂即斑消脉出。复用韩氏生地黄汤逐其血。是夕下黑血。后三日。腹又痛。遂用桃仁承气以攻之。所下如前。乃愈。", "3317": "震阅二案而知发斑蓄血。有脉伏之一候。然窃思斑未出而脉伏。理或有之。斑既透矣。何以必待化斑脉始复耶。吴又可有脉厥之说。用承气微下则脉出。与此用白虎仿佛。但发斑脉伏。势亦可畏。上条妙在语言不乱。次条虽神昏如睡。由于误服真武。故皆凭证以医之。翁云见斑则应候。思及蓄血。已勉强矣。", "3318": "云间怀抱奇治一妇。夏月饮火酒。烦热面赤发斑。诊其脉绝无。怀曰。此火郁而热极。用栀豉汤加葛根、厚朴、黄连清之。斑大出而脉遂见。恰与此条大同小异。又一人伤寒过经不解。遍体黑斑。唇口焦枯。脉大便结。以三黄石膏汤饮之痊。此可与准绳所载黑斑一条合观之。又一妇热入血室后。发斑点。以小柴胡汤加生地、丹皮获愈。又一人身热发斑。胃有停滞。胀闷不堪。用枳、朴、消导药而斑出热退。因信朱奉议所谓凡见斑不可专以斑治。须察脉之浮沉。病之虚实。而分别用药。真至言也。忆昔年娄县小港叶念劬兄。身热发斑不透。群用提斑药无效。予见其吐涎不止。手足软不能动。脉大无力。正合内伤发斑例。用补中益气汤而愈。故友孝廉张素安兄尊壶身热足冷。目肿溏泄。发斑不透。其脉沉细无力。正合阴症发斑例。用真武汤加人参而愈。此实效法海藏及准绳之治法也。然舌不燥。神不昏。故可用温补耳。若夏秋时行疫病。又多有以大黄黄连下之而斑出者。盖内邪之壅塞。得通而斑出。与虚寒之得温补以鼓舞而斑出。同一理也。又生平见蓝斑二人。一则脉细神昏。辞不治。其蓝斑之大者如棋子。发烂而死。一女人蓝斑。色如翠羽。咯血齿衄。舌红不干。神不昏。犹可扶行登圊。用犀角地黄汤。间以大黄微下之。后竟愈。又按龚云林治一人。夏月因劳倦。饮食不节。又伤冷饮得疾。医以时证治之不愈。至十日。苦身体沉重。四肢逆冷。自利清谷。引衣自盖。气难布息。懒言语。此脾受寒湿。中气不足之病也。口干但欲水不欲咽。早晨身凉而生粟。午后烦躁。不欲去衣。昏昏睡而面赤。隐隐红斑见于皮肤。此表实里虚。故内虚则外证随时而变。遂用钱氏白术散加升麻。合本方之干葛、甘草以解其斑。少加白术、茯苓以除湿而利小便。人参、藿香、木香以安脾胃。进饮食。两服而斑退身温利止。次服五味异功散、治中汤一二服。五日得平。此仿完颜小将军暑月内伤发斑治法也。", "3319": "副枢张息轩伤寒逾月。既下而内热不已。胁及小腹偏左满。肌肉色不变。俚医以为风所中。膏其手摩之。浃旬。其毒循宗筋流入于睪丸。赤肿若匏。刺溃之。而左胁肿痛如故。召吕诊。吕以关及尺中皆滑数而且芤。因告之曰。脉数不时。则生恶疮。关内逢芤则内痈作。胁之肿。痈作脓也。下之勿晚。乃用保生膏作丸。衣之以乳香。而用硝黄作汤下之。下脓五升许。明日再圊下余脓。立痊。", "3320": "震按此条以伤寒而变肠痈。虽不多见。亦不可不知。观其所告之言。两句出仲景伤寒论。两句出高阳生脉诀。因思自明以前。皆用此诀。何近贤之痛诋不堪耶。", "3321": "震按此为阴盛隔阳。亦曰下寒上热。沧州翁以寒药裹热药。与热药冷服义同。其理精矣。然阅各家医案。能识此证者亦不少。至如阴中伏阳。则惟有许学士一案。其治乡人李信道头疼身温烦躁。指末皆冷。胸中满。恶心。六脉沉伏不见。深按至骨则若有力。更两医矣。皆不识。止用调气药。许诊之。曰。此阴中伏阳也。仲景法中无此证。世人患此者多。若用热药以助之。则为阴所隔绝。不能导引真阳。反生客热。用冷药则所伏真火愈见澌灭。非其治也。须用破散阴气导达真火之药。使水升火降。然后得汗而解矣。乃授破阴丹二百粒。作一服。冷盐汤下。不时烦躁狂热。手足躁扰。其家大惊。许曰。俗所谓换阳也。须臾稍定。略睡。身已得汗。自昏达旦方止。热退而病除矣。今考破阴丹方。乃硫黄、水银等分。熔结成砂。加陈皮、青皮分两减半。各为细末。面糊丸如桐子大。而用至二百丸。非许学士其谁能之。此与阴隔阳用参附者似是而非。从古无人论及。可不谓发仲景之所未发哉。", "3322": "孙兆治一人。伤寒五六日。头汗出。自颈以下无汗。手足冷。心下痞闷。大便秘。脉沉紧。或者以为阴结。孙曰。此即仲景所谓半在表。半在里。脉虽沉紧。不得为少阴病也。投以小柴胡汤而愈。盖四肢冷。脉沉紧。似乎少阴。然少阴多自利。不当大便硬。况头者三阳同聚。若三阴经则至胸而还。今有头汗出。似乎阳虚。故曰汗出为阳微。然少阴额上冷汗。同为阴毒矣。故曰阴不得有汗。今头汗出。知非少阴也。与小柴胡汤。设不了了者。得屎而解。仲景虽不立方。可知其为大柴胡汤矣。此亦阳症似阴之一种也。", "3323": "一道者患伤寒。发热。汗出多。惊悸目眩身战掉。众医有欲发汗者。有作风治者。有欲以冷药解者。延孙兆至。兆曰。太阳经病得汗而不解。若欲解。必复作汗。肾气不足。汗不来。所以心悸目眩身战。遂与真武汤。三服。微汗自出。即解。盖真武汤附子、白术和其肾气。肾气得行。故汗得来。仲景云。尺脉弱者。营气不足。不可发汗。以此知肾气怯则难汗也。", "3324": "滑伯仁治一人。病伤寒。已经汗下。病去而背独恶寒。脉细如线。汤熨不应。伯仁以理中汤加姜、桂、附子大作服。外以荜茇、良姜、吴茱、桂、椒诸品大辛热药为末。姜汁调敷满背。以纸覆之。稍干即易。如是半月。竟平复不寒矣。此治法之变者也。", "3325": "一人七月内。病发热。多服小柴胡汤。恶寒甚。肉𥆧筋惕。滑伯仁诊之。脉细欲绝。曰。此升发太过。多汗亡阳。表虚极而恶寒甚也。肉𥆧筋惕者。里虚极而阳不复也。以真武汤。进七八服而愈。", "3326": "吴绶治一人。伤寒未经发汗。七八日。经脉动惕。潮热来尤甚。其肉不𥆧。大便秘结不行。小便赤涩。以手按脐旁硬痛。此有燥屎也。用加味大柴胡汤下之而愈。", "3327": "又一人伤寒十余日。曾三四次发汗过多。遂变肉𥆧身振摇。筋脉动惕。此汗多气血俱虚故也。用加味人参养营汤二剂而愈。", "3328": "震按肉𥆧筋惕四条治法不同。首条载脉。三条不载脉。须看其病因病形之不同。分别得清。故用药恰当。", "3329": "朱丹溪治一人。素嗜酒。因暴风寒。衣薄。遂觉倦怠。不思饮食。至夜大发热。遍身疼痛如被杖。微恶寒。天明诊之。六脉浮大。按之豁然。左为甚。因作极虚受风寒治之。人参为君。黄耆、白术、归身为臣。苍术、甘草、木通、干葛为佐。使大剂与之。至五帖后。通身汗如雨。凡三易被。得睡。觉来诸证悉除。", "3330": "卢兄年四十九岁。自来大便下血。脉沉迟涩。面黄神倦者。二年矣。九月间。因劳倦发热。自服参苏饮二帖。热退。早起小劳遇寒。两手背与面紫黑。昏仆。少时却醒。身大热。妄语口干。身痛至不可眠。丹溪脉之。三部不调。微带数。重取虚豁。左手大于右手。以人参二钱半。带节麻黄、黄耆各一钱。白术二钱。当归五分。与三五帖。得睡。醒来大汗如雨。即安。两日后。再发胁痛咳嗽。若睡时。嗽不作而妄语。且微恶寒。诊其脉似前。而左略带紧。丹溪曰。此体虚再感寒也。仍以前药加半夏、茯苓。至十余帖。再得大汗而安。后身倦不可久坐。不思饮食。用补中益气去凉药。加神曲、半夏、砂仁。五七十帖而安。", "3331": "一人五月内。大发热而谵语。肢体不能举。喜冷饮。丹溪诊其脉洪大而数。用黄耆、茯苓浓煎如膏。却用凉水调与之。三四服后。病者昏愦如死状。但颜色不改。气息如常。至次早方醒。诸证悉退而安。", "3332": "又治一老人。饥寒作劳。患头疼恶寒发热。骨节疼。无汗。妄语时作时止。自服参苏饮取汗。汗大出而热不退。至第四日。诊其脉洪数而左甚。朱曰。此内伤证因饥而胃虚。加以作劳。阳明虽受寒气。不可攻击。当大补其虚。俟胃气充实。必自汗而解。遂以参、耆、归、术、陈皮、甘草。加附子二片。一昼夜尽五帖。至三日。口稍干。言有次序。诸证虽解。热尚未退。乃去附加芍药。又两日。渐思食。颇清爽。间与肉羹。又三日。汗自出。热退。脉虽不散。洪数尚存。朱谓此脉洪。当作大论。年高而误汗。以后必有虚证见。又与前药。至次日。自言病以来。不更衣十三日矣。今谷道虚坐努责。迸痛如痢状不堪。自欲用大黄等物。朱曰。大便非实闭。乃气因误汗而虚。不得充腹。无力可努。仍用前药。间以肉汁粥及苁蓉粥与之。翌日。浓煎椒葱汤浸下体。方大便。诊其脉。仍未敛。此气血仍未复。又与前药。两日小便不通。小腹满闷。但仰卧则点滴而出。朱曰。补药未至。与前方倍加参、耆。两日小便方利。又服补药半月而安。", "3333": "震按此四案。向列于内伤门。以其皆作虚证治也。然外证与伤寒一般。且前二条原因受寒而起。自非明眼。岂敢用参耆大补少加表药乎。盖所凭者在脉虚豁耳。后二条脉洪数不虚豁。而亦用补者。一凭于肢体不能举。一凭于老年饥寒作劳致病。其审证精细。非粗人所能及。而一用耆苓煎膏。凉水调服。一用参、耆、归、术佐附子。一周时进五帖。轻重缓急。各臻其妙。至谓脉洪当作大论。可见洪与大原有分别。非通用字义。", "3334": "丹溪治一人。年二十。于四月。病发热。脉浮沉皆有不足意。其间得洪数一种。随热进退不时。知非伤寒也。因问必是过饮。酒毒在内。今为房劳。气血虚乏而病作耶。曰。饮烧酒。吃犬肉。近一月矣。遂用补气血药。加干葛以解酒毒。服一帖。微汗。反懈怠。热如故。因思是病气血皆虚。不禁葛根之散。乃换枳椇子入前药内。一帖而愈。", "3335": "震按脉浮沉皆有不足意。大象是虚矣。间见洪数。随热进退不时。此非片刻所能得。故遇疑难证。必须久诊。及一日二三次诊之。斯病无遁情。下条又是问而知之。知其素有下疳疮。则脉之弦数为疮毒矣。诚哉四诊不可缺一也。", "3336": "一人素有下疳疮。忽头痛发热自汗。众作伤寒治。反剧。脉弦甚。七至。重取则涩。丹溪曰。此病在厥阴。而与证不对。以小柴胡加龙胆草、黄连。热服。四帖而安。", "3337": "陶节庵治一人。伤寒四五日。吐血不止。医以犀角地黄汤、茅花汤。治而反剧。陶切其脉。浮紧而数。曰。若不汗出。邪何由解。进麻黄汤一服。汗出而愈。或曰。仲景言衄家不可汗。亡血家不可汗。而此用麻黄。何也。曰。久衄之家。亡血已多。故不可汗。今缘当汗不汗。热毒蕴结而成吐血。当分其津液。乃愈。故仲景又曰。伤寒脉浮紧。不发汗。因致衄者。麻黄汤主之。盖发其汗。则热越而出。血自止也。", "3338": "〔附〕抱奇一友。积劳后感寒发热。医者好用古方。竟以麻黄汤进。目赤血衄。痰中带血。继以小柴胡汤。舌干乏津。怀诊之。脉来虚数无力。乃劳倦而兼阴虚候也。误投热药。能不动血而竭其液耶。连进地黄汤三剂。血止。神尚未清。用生脉散加当归、枣仁、茯神、远志。神虽安。舌仍不生津。乃曰。肾主五液。而肺为生化之源。滋阴益气。两不见效。何也。细思之。因悟麻黄性不内守。服之而竟无汗。徒伤其阴。口鼻虽见血。药性终未发泄。故津液不行。仍以生脉散加葛根、陈皮引之。遂得微汗。舌果津生。后以归脾汤、六味丸而痊。", "3339": "节庵治一壮年。夏间劳役后食冷物。夜卧遗精。遂发热痞闷。至晚。头额时痛。两足不温。医不知头痛为火热上乘。足冷为脾气不下。误认外感夹阴。而与五积散汗之。则烦躁口干。目赤便秘。明日。便与承气下之。但有黄水。身强如痉。烦躁转剧。腹胀喘急。舌胎黄黑。已六七日矣。诊其脉。六七至而弦劲。急以黄龙汤。下黑物甚多。下后腹胀顿宽。躁热顿减。但夜间仍热。舌胎未尽。更与解毒汤合生脉散加生地。二剂热除。平调月余而安。", "3340": "震按吴又可温疫论。以承气合白虎。于数日内连服连下。今人多有宗其法以救危病者。观花溪此案。先开其端。然愚者奉为捷径。卤莽灭裂。亦不少矣。试读仲景阳明少阴篇中。急下、可下、微和、更与等义。缓急轻重。法详且密。吴又可连下之法。亦不过仲景法中之一法耳。未可以一法废诸法也。即如许学士治一家而病两人。皆旬日矣。一则身热无汗。大便不通。小便短涩。神昏而睡。诊其脉长大而实。用承气下之而愈。一则阳明自汗。大便不通。小便利。津液少。口干燥。其脉大而虚。作蜜煎导之。下燥粪得溏利而解。其家曰。皆阳明不通。何以治之异。许曰。二证虽相似。然自汗小便利者。不可荡涤五脏。为无津液也。然则伤寒脉证大同小异之间。即宜分别斟酌。奈何以温疫论为捷径哉。", "3341": "一人年四十五。正月间。路途跋涉劳倦。发热。身体略痛而头不痛。自以为外感。而用九味羌活汤三帖。汗出热不退。前后又服小柴胡汤五六帖。热愈甚。经八日。延虞诊视。至卧榻前。见煎成汤饮一盏在案。问之。乃大承气汤。将欲饮。切其脉。右三部浮洪。略弦而无力。左三部略小。亦浮软不足。虞曰。汝几自杀。此内伤虚证。服此药大下。必死。伊曰。我平生元气颇实。素无虚损证。明是外感无疑也。虞曰。将欲作阳明内实治而下之欤。脉既不沉实。又无舌干潮热谵语等证。将欲作太阳表实治而汗之欤。脉虽浮洪而且虚。又无头痛脊强等证。今经八日。非表非里。汝欲作何经治之乎。伊无以答。乃用补中益气汤加附子。大剂与之。是夜连进二服。天明往诊。脉略平和。伊犹疑属前效。欲易外感退热之药。虞曰。前药再饮二服。不效当罪我。又如前二服。脉证俱减半。伊始曰。我几误矣。去附子。再煎二帖与之。热退气和而愈。但体犹困倦如前。服前药二十余帖。始得强健。", "3342": "薛院使已治一人。年七十九。仲冬将出行。少妾入房。致头痛发热。眩晕喘急。痰涎壅盛。小便烦数。口干引饮。遍舌生刺。缩敛如荔枝然。下唇黑裂。面目俱赤。烦躁不寝。或时喉间如烟火上冲。急饮凉茶少解。已滨于死。脉洪大而无伦。且有力。扪其身烙手。此肾经虚火游行于外。投以十全大补合六味地黄汤、生脉散。再加附子。服一剂。熟寝良久。脉证各减三四。再与八味丸服之。诸证悉退。后忌冷物而痊。", "3343": "震按少妾入房。病者之隐事。头痛发热。必自疑感冒外邪。观其口渴舌刺等证。及脉洪大有力。医者必以温疫论伤寒直格一致思矣。白虎泻心。死复何疑。此惟张景岳可与谈心。", "3344": "张景岳曰。余在燕都。治一王生。患阴虚伤寒。年出三旬。而舌黑之甚。其芒刺干裂。焦黑如炭。身热便结。大渴喜冷。而脉则无力。神则昏沉。群医谓阳证阴脉。必死无疑。余察其形气未脱。遂以甘温壮水等药。大剂进之以救其本。仍间用凉水以滋其标。盖水为天一之精。凉能解热。甘可助阴。非若苦寒伤气者之比。故于津液干燥。阴虚便结。而热渴火盛之证。亦所不忌。由是水药并进。前后凡用人参、熟地辈各一二斤。附子、肉桂各数两。冷水亦一二斗。然后诸证渐退。饮食渐进。神气俱复矣。但察其舌黑则分毫不减。余甚疑之。莫得其解。再后数日。忽舌上脱一黑壳。而内则新肉灿然。始知其肤腠焦枯。死而复活。使非大为滋补。安望再生。若此一证。特举其甚者纪之。此外凡舌黑用补而得以保全者。盖不可枚举矣。所以凡诊伤寒者。当以舌色辨表里。以舌色辨寒热。皆不可不知也。若以舌色辨虚实。则不能无误。盖实固能黑。以火盛而焦也。虚亦能黑。以水亏而枯也。若以舌黄舌黑。悉认为实热。则阴虚之证。万无一生矣。", "3345": "杨乘六治吴长人。于三月初。身大热。口大渴。唇焦裂。目赤色。两颧娇红。语妄神昏。手冷过肘。足冷过膝。其舌黑滑而胖。其脉洪大而空。一医欲用白虎。杨曰。身虽壮热如烙。而不离覆盖。口虽大渴引饮。而不耐寒凉。面色虽红却娇嫩。而游移不定。舌胎虽黑。却浮胖而滋润不枯。如果属白虎。则更未有四肢厥冷而上过乎肘下过乎膝。六脉洪大。而浮取无伦。沉取无根者也。此为格阳戴阳。若用白虎。必立毙矣。遂以大剂八味加人参。浓煎数碗。冷饮。诸证乃退。继以理中加附子。六君加归、芍。各数剂调理而愈。", "3346": "又治归安医者张学海。疲于临证。微寒壮热。头痛昏沉。服发散药数剂。目直耳聋。口渴便闭。改用泻火解毒等剂。热势尤炽。油汗如珠。谵语撮空。恶候悉具。云峰观之。其脉洪大躁疾而空。其舌干燥焦黄而胖。杨曰。证有真假凭诸脉。脉有真假凭诸舌。果系实证。则脉必洪大躁疾而重按愈有力者也。果系实火。则舌必干燥焦黄而敛束且坚卓者也。岂有重按全无脉者。而尚得谓之实证。满舌俱胖壮者。而尚得谓之实火哉。用养营汤。参、附各三钱。服后得睡。热退。舌变红润而愈。", "3347": "李士材治韩茂远。伤寒九日以来。口不能言。目不能视。体不能动。四肢俱冷。皆曰阴证。士材诊之。六脉皆无。以手按腹。两手护之。眉皱作楚。按其趺阳。大而有力。乃知腹有燥屎也。与大承气汤。得燥屎六七枚。口能言。体能动矣。故按手不及足者。何以救此垂绝之证耶。", "3348": "震按六脉无而诊趺阳。鉴于仲景之自叙。读书诚有用也。", "3349": "王月怀伤寒至五日。下利不止。懊𢙐腹胀。诸药不效。有以山药茯苓与之。虑其泻脱也。士材诊之。六脉沉数。按其脐则痛。此协热自利。中有结粪。小承气倍大黄服之。果得结粪数枚。利遂止。懊𢙐遂安。", "3350": "儒者吴君明。伤寒六日。谵语狂笑。头痛有汗。大便不通。小便自利。众议承气汤下之。士材诊其脉浮而大。因思仲景曰。伤寒不大便六七日。头痛有热。小便清者。知不在里。仍在表也。方今仲冬。宜与桂枝汤。众皆咋舌。以谵狂为阳盛。桂枝入口必毙矣。李曰。汗多神昏。故发谵妄。虽不大便。腹无所苦。和其荣卫。必自愈耳。遂违众用之。及夜而笑语皆止。明日大便自通。故病变多端。不可胶执。向使狐疑而用下药。其可活乎。", "3351": "卢子由治梁秀才。于三月间。作文受寒。服发散药十余帖。热盛汗多。蒸蒸如云雾。高一二尺。湿透衣被。日易十数番。十四日昏不识人。舌短眼瞀。脉浮大无伦。乃先以温粉扑周身。使汗孔收敛。次用人参五钱。生附三钱。煎服。便能识人。惟言语谵妄。七日始苏。有客问曰。浮表脉也。热盛神昏。舌短眼瞀。邪盛也。何竟以温补收功。子由曰。凡治病先求其本。不可泥其形证。如寒水为邪。必然心火受病。此病原从思虑受寒。政为心火不及。而受水侮。是谓之本。况多行发散。重虚其心。心液既已散漫。精神便无主宰。故用黑附顺从水色。而横助火力。人参转回阳气。而保定精神。然非先固其外。则内无旋理。此予治法先后之旨也。", "3352": "缪仲淳治铨部章衡阳。患热病。头痛壮热。渴甚且呕。鼻干燥不得眠。其脉洪大而实。一医曰。阳明症也。当用葛根汤。仲淳曰。阳明之药。表剂有二。一为葛根汤。一为白虎汤。不呕吐而解表。用葛根汤。今吐甚。是阳明之气逆升也。葛根升散。用之非宜。乃与大剂白虎汤加麦冬、竹叶。医骇药太重。仲淳曰。虏荆非六十万人不可。李信二十万则奔还矣。别后进药。天明遂瘥。", "3353": "王肯堂治太史余云衢。向来形气充壮。饮啖兼人。忽于六月患热病。肢体不甚热。而间扬掷手足。如躁扰状。昏愦不知人事。时发一二语不可了。而非谵也。脉微细欲绝。有谓是阴证宜温者。有谓当下者。皆取决于王。王曰。若阳病见阴脉。在法为不治。然素禀如此。又值酷暑外烁。酒炙内炎。宜狂热如焚。脉洪数有力。而此何为者。岂热气怫郁不得伸而然耶。且不大便七日矣。姑以大柴胡汤下之。时大黄止用二钱。又熟煎。而太医王雷庵力争以为太少。金坛曰。如此脉证。岂宜峻下。待其不应。加重可也。及服药。大便即行。脉已出。手足温矣。继以黄连解毒汤。数服而平。此即刘河间伤寒直格所谓蓄热内甚。而脉道不利。反致脉沉细欲绝者。通宜解毒合承气下之。俗医不知。认为阴寒。多致危殆者是也。", "3354": "喻嘉言治徐国珍。伤寒六七日。身寒目赤。索水到前。复置不饮。异常大躁。门牖洞启。身卧地上。展转不快。更求入井。一医急治承气将服。喻诊其脉。洪大无伦。重按无力。乃曰。是为阳虚欲脱。外显假热。内有真寒。观其得水不欲咽。而尚可咽大黄、芒硝乎。天气燠蒸。必有大雨。此证顷刻一身大汗。不可救矣。即以附子、干姜各五钱。人参三钱。甘草二钱。煎成冷服。服后寒战戛齿有声。以重绵和头覆之。缩手不肯与诊。阳微之状始著。再与前药一剂。微汗。热退而安。", "3355": "震按此条脉大无伦。重按无力。与李士材治吴文哉案同。较之金坛之案何以别之。须看王案脉微细欲绝。喻李二案脉浮大沉小也。喻案有漱水不欲咽一证可据。王案则壮盛人病于暑月醉饱之后可疑也。若薛院使案脉大无伦且有力。舌刺唇黑。频饮凉茶。全似阳证阳脉。其可据者。高年御女。气喘溺频也。", "3356": "喻嘉言治陆平叔。平素体虚气怯。面色痿黄。药宜温补。不宜寒凉。秋月偶患三疟。孟冬复受外寒。遂寒热频作。医者以为疟后虚邪。不知其为新受实邪也。投以参术补剂。转致奄奄一息。迁延两月。昏昏嘿嘿。家已治木。漫延西昌诊之。脉弦浮大而短气。鼻干不得汗。嗜卧。一身及面目悉黄。与阳明中风条。过经二十余日不解。悉同此例。但未至于不尿腹满加哕耳。西昌以为脉未大坏。九分可治。但筋脉牵掣不停。只恐手足痿废。吾今用法。治则兼治。然仲景止有大柴胡汤。两解表里之法。而无治痿之法。因以防风通圣散成方。减白术。取荆、防、麻、薄、桔梗为表药。硝、黄、芩、翘、栀、膏、滑石为里药。原与大柴胡之制相仿。内有芎、归、芍药。正可领诸药深入血分而通经脉。减白术者。以前既用之贻误。不可再误耳。当晚连服二剂。第一剂即觉相安。第二剂大便始通。少顷睡去。体间津津有汗。次早再诊。筋脉不为牵掣。但阳明胃脉。洪大反加。随用大剂白虎汤。加柴胡、花粉、芩、柏、连翘、栀子一派苦寒。连进十余剂。其舌始不向唇外吮咂。神识始渐清。粥饮始渐加。经半月。始起坐于床。经一月。始散步于地。略一过啖。即腹痛便泄。俨似虚证。西昌全不反顾。但于行滞药中。加用柴胡、桂枝升散余邪。不使下溜而变痢以取惫。然后改用萎蕤、二冬。略和胃气。间用人参。不过五分。缘此证所受外邪。不在太阳而在阳明。故不但不恶寒。且并无传经之壮热。有时略显潮热。又与内伤发热相仿。误用参术补之。邪无出路。久久遂与元气混合为一。所以神识昏嘿。又阳明者十二经脉之长。能束筋骨而利机关。阳明不治。故筋脉失养而动惕不宁耳。外邪锢于阳明。则其土为火燔之焦土。灰砂之燥土矣。非藉北方之水。何以润泽枯槁。故初用苦寒。继用甘寒。正如灵雨霡霂。方得复其稼穑之恒也。", "3357": "慎柔和尚治薛理还仆。远行忍饥。又相殴脱力。时五月初。遂发热谵语。服过补中益气及五苓数剂。不效。慎柔诊之。六脉俱无。乍有则甚细。其外证则面赤谵语口碎。一医曰。阳病见阴脉。证在死例。慎柔曰。当以阳虚从脉舍证治之。用附子理中汤。冷服二帖。脉稍见。四帖则脉有神而口碎愈矣。六帖则脉如常。但谵语未已。慎柔曰。脉气已完复而谵语不休者。胃有燥粪。以猪胆汁导之。果下燥结。谵语遂平。", "3358": "张路玉治范求先。患伤寒恶寒三日不止。已服过发散药二剂。至第七日躁扰不宁。六脉不至。手足厥逆。张诊之。独左寸厥厥动摇。知是欲作战汗之候。令勿服药。但与热姜汤助其作汗。若误服药。必热不止。果如其言而愈。", "3359": "震按慎柔案与海藏治侯辅之同一例。与金坛治余云衢大相反。必须细玩体贴。因忆准绳叙丹溪诸案而志之曰。卢兄汗后。再发热妄言。吕仲修汗后热不退。亦妄言。陶明节热退后。不识人。言谬妄。皆用参、耆、术、归、附子等补剂而愈。信哉。谵语属虚者十居八九。今观此案以温补得口碎愈。脉如常而谵语不休。仍责之胃有燥矢。与伤寒论中证象阳旦篇末云。以承气汤微溏则止其谵语大旨相同。是虚寒证之谵语。与不因虚寒而谵语。其辨诚难矣。汇而计之。盖有三路焉。一系邪传阳明。热邪与燥矢抟结而谵语。三承气、承气合白虎之一路也。一系内是虚寒。外象实热而谵语。丹溪所治、金坛所述之一路也。一系病本虚寒。恰挟宿食。因身热熯为燥矢而谵语。此案及阳旦证之一路也。医者孰有燃犀之照乎。投药一差。死生反掌。故伤寒及温热病。均为大病。有今日许以无害。明日忽然溘逝者。有操券断其必死。淹延竟得全生者。不比风痨臌膈。病虽危笃。尚可从容商其缓急。所以仲景自序云。若能寻予所集。思过半矣。明示天下后世以伤寒难治。伤寒论难读也。苟非难读。何待寻乎。张案亦六脉不至。病情又别难乎。难乎可不寻乎。", "3360": "震按伤寒为大病。治法为最繁。言之不胜言也。必熟读仲景书。再遍读后贤诸书。临证方有把握。仲景书为叔和编次。或有差误。而聊摄注解。殊觉稳当。续注者张卿子、王三阳、唐不严、沈亮宸、张兼善、张隐庵、林北海诸人。总不越其范围。自方程喻三家。各以己意布置。而仲景原文。从此遂无定局。三注互有短长。大约程不及方。方不及喻。然喻注太阳经分三大纲。以误汗误下结胸蓄血发黄等证分隶两门。似乎界限井然。谁知以之治病。全用不著。盖病初起时。必将营卫分别。过半月后。殊难追溯。何以指其此由中风传变。此由伤寒传变。此由风寒两伤传变哉。传变之证。虚实寒热。犹恐模糊。又要恰合三纲。此能言而不能行者也。魏柏乡、周禹载、沈自南等俱宗之。亦徒悦服于空言。而未尝以之试验耳。卢子由疏钞金錍。不派三纲。添出气化、形层、标本、四大等说。愈觉支离。愈入迷网。其脏结诸案。几如牛鬼蛇神。柯韵伯将两家并讥。不亦宜乎。韵伯伤寒论翼。固属出奇高论。所谓读书具只眼。不蹈前人窠臼者。微嫌其论六经尽翻前案。欲立异以惊人。究属纸上谈兵也。从来注伤寒论者。俱是顺文注释。若遇不可通处。或敷衍混过。或穿凿文饰。既不明道理之是非。何以为临证之运用。惟程扶生经注。颇明白易晓。然亦不敢直指原文之差误。至柯氏来苏集。始放胆删改。虽觉僭妄。颇堪嘉惠后学。而以方名编次。又是一局。徐灵胎伤寒类方。实宗其式。简洁明净。以少许胜人多许。较之程郊倩之繁词。一可当百。沈尧封伤寒论。亦以少胜多者。用六气为提纲。将平脉辨脉。编入其中。别开生面。其论大青龙汤。发前人所未发。一洗风寒两伤营卫之陋说。左传云。拔戟自成一队。此书似之。而删改本文。非其志也。予细绎柯氏删改处。万不及钦定医宗金鉴伤寒论之精当。先刊仲景原文。另立正误存疑二篇。应改者注小字于旁。可删者摘诸条于后。是非判然。智愚皆晓。真苦海之慈航。昏衢之巨烛也。江西舒诏伤寒集注。大半斥为伪撰。并取数方。痛加诋毁。别拟方以换之。此亦救世婆心。特未免于狂妄。以视汪琥将阴阳二候分为二编。各补后贤之方。其意均欲使初学者。不泥古方以害人。而汪犹拘谨。舒则放纵矣。此外注家尚多。如钱氏溯源集。陈明伯集注。尚有发明处。其余碌碌因人。殊不足道。兹举夫各立格局。各竖议论者。叙述于右。以便同志之诵习焉。要之读书与治病。时合时离。古法与今方。有因有革。善读书斯善治病。非读死书之谓也。用古法须用今方。非执板方之谓也。专读仲景书。不读后贤书。譬之井田封建。周礼周官。不可以治汉唐之天下也。仅读后贤书。不读仲景书。譬之五言七律。昆体宫词。不可以代三百之雅颂也。故吴绶蕴要。节庵六书。王宇泰伤寒准绳。张路玉伤寒绪论。俱有裨于后人。即有功于仲景。学者诚能以所引诸书。广为探索。则所选诸案。皆堪尚友矣。", "3361": "许学士云。记有人伤寒得汗。病退数日。忽身热自汗。脉弦数。心不得宁。真劳复也。予诊之。曰。劳心之所致。神之所舍。未复其初。而又劳伤其神。营卫失度。当补脾以解其劳。庶几得愈。授以补脾汤合入小柴胡。或者难曰。虚则补其母。今补其子。何也。予曰。子不知虚劳之异乎。难经曰。虚则补其母。实则泻其子。此虚当补母。人所共知也。千金曰。心劳甚者。补脾气以益之。脾王则感之于心矣。此劳则当补子。人所未闻也。盖母。生我者也。子。继我而助我者也。方治其虚。则补其生我者。与锦囊所谓本骸得气。遗体受荫同义。方治其劳。则补其助我者。与荀子言未有子富而父贫同义。此治虚与劳所以异也。", "3362": "滑伯仁治潘子庸。得感冒证已汗而愈。数日。复大发热恶寒。头痛眩晕。呕吐却食。烦满。咳而多汗。滑诊其脉。两手皆浮而紧。在仲景法。劳复证浮以汗解。沉以下解。为作麻黄葛根汤。三进。更汗。旋调理数日愈。其时众医以病后虚惫。且图温补。伯仁曰。法当如是。因违众用之。", "3363": "王海藏治李良佐子病太阳证。尺寸脉俱浮数。按之无力。谓其内阴虚。与神术加干姜汤。愈后再病。海藏视之。见神不舒。垂头不欲语。疑其有房过。问之犯房过乎。必头重目暗。曰然。因与大建中三四服。外阳内收。脉反沉小。始见阴候。又与已寒加芍药茴香等丸五六服。三日内。约服六七百丸。脉复生。又用大建中接之。大汗作而解。", "3364": "侯国华病伤寒四五日。身微斑。渴饮。海藏诊之。沉弦欲绝。厥阴脉也。服温药数日。不已。又以姜附等药。阳回脉生。因渴。私饮水一杯。脉复退。但头不举。目不开。问之则犯阴易。若只与烧裩散。恐寒而不济。遂煎吴茱萸汤一大碗。调烧裩散。连进二服。作大汗两昼夜而愈。", "3365": "张路玉治冯茂之。夏月阴阳易。而腰痛少腹急。烦躁谵妄。舌色青紫。而中有黄胎肿裂。虽渴欲冷饮。而舌却不甚干。心下按之硬痛。嗳而失气。此挟宿食也。所可虑者。六脉虚大。而两尺则弦。按之皆无根耳。遂以逍遥汤加大黄一剂。下黑秽甚多。下后诸证悉除。但少腹微冷作痛。又与烧裩散一服。煎五苓散送下而安。", "3366": "〔附〕范汪方云。故督邮顾子献。得病已瘥未健。诣华旉视脉。旉曰。虽瘥。尚虚。未平复。阳气不足。勿为劳事也。诸劳尚可。女劳即死。当吐舌数寸。献妇闻其瘥。从百余里来省之。住数宿。因与交接。一二日死。巢氏病源论曰。妇人伤寒虽瘥。未满百日。气血骨髓未牢实。而合阴阳。当时虽未觉恶。经日则令百节解离。经络缓弱。气血虚。骨髓空。恍恍吸吸。起居仰人。饮食如故。是其证也。丈夫亦然。", "3367": "千金方云。妇人温病虽瘥。未平复。血脉未和。尚有热毒。而与之交接得病者。为阴阳易。医者张苗。说有婢得病瘥后数日。有六人奸之。皆死。", "3368": "朱氏全生集曰。自霜降后至春分前。天令严寒。水冰地冻。其杀属之气。人触犯之。即时病者。为正伤寒。若虽冬月而天令温暖。感之则为冬温。如至春分节后。天令温暖。感之而病者。为温病。若虽至春分而天令尚寒。人有感寒而病者。亦伤寒也。若夏至后。天道壮热。人感邪而病。其脉洪大。为热病。若四五六七八月之间。天道忽有暴寒。人感之而为病者。乃时行寒疫也。若四时天令不正。感而为病。长幼相似。复能传染者。此名时气。即时疫也。非伤寒比也。又云。冬时感受寒邪而不即病。伏于身中。至春变为温病。至夏变为热病。夫温热二病。乃冬月伏寒之所变。既变之后。不得复言寒矣。此外又有风温、湿温。一皆发热。状类伤寒。故医家通以伤寒称之。其通称伤寒者。因发热传变。皆相类也。至于用药。则不同矣。此数种乃仲景所未论。又在痉湿暍三项之外。必须辨之。", "3369": "又治郑墨林室。素有便红。怀妊七月。正肺气养胎时。而患冬温。咳嗽咽痛如刺。下血如崩。脉较平时反觉小弱而数。此热伤手太阴血分也。与黄连阿胶汤二剂。血止后。去黄连。加葳蕤、桔梗、人中黄。四剂而安。", "3370": "又治黄以宽。风温十余日。壮热神昏。语言难出。自利溏黑。舌胎黑燥。唇焦鼻煤。先前误用发散消导药数剂。烦渴弥甚。张石顽曰。此本伏气郁发。更遇于风。遂成风温。风温脉气本浮。以热邪久伏少阴。从火化。发出太阳。即是两感。变患最速。今幸年壮质强。已逾三日六日之期。证虽危殆。良由风药性升。鼓激周身元气。皆化为火。伤耗真阴。少阴之脉。不能内藏。所以反浮。考诸南阳先师。元无治法。而少阴例中。则有救热存阴。承气下之一证。可借此以迅扫久伏之邪。审其鼻息不鼾。知肾水之上源未绝。无虑其直视失溲也。时歙医胡晨敷在坐。同议凉膈散加人中黄、生地黄。服后下溏粪三次。舌胎未润。烦渴不减。此杯水不能救车薪之火也。更与大剂凉膈。大黄加至二两。兼黄连、犀角。三下方能热除。于是专用生津止渴。多服而愈。", "3371": "又治陆中行室。年二十余。腊月中旬。患咳嗽。挨过半月。病热少减。新正五日。复咳倍前。自汗体倦。咽喉干痛。至元夕。忽微恶寒发热。明日转为腹痛自利。手足逆冷。咽痛异常。又三日则咳唾脓血。张诊其脉。轻取微数。寻之则仍不数。寸口似动而软。尺部略重则无。审其脉证。寒热难分。颇似仲景厥阴例中麻黄升麻汤证。盖始本冬温。所伤原不为重。故咳至半月渐减。乃勉力支持岁事。过于劳役。伤其脾肺之气。故咳复甚于前。至望夜忽憎寒发热。来日遂自利厥逆者。当是病中体疏。复感寒邪之故。热邪既伤于内。寒邪复加于外。寒闭热邪。不得外散。势必内奔而为自利。致邪传少阴厥阴。而为咽喉不利。唾脓血也。虽伤寒大下后。与伤热后自利不同。而寒热错杂则一。遂与麻黄升麻汤。一剂。肢体微汗。手足温暖。自利即止。明日诊之。脉亦向和。嗣后与异功生脉合服。数剂而安。", "3372": "许学士云。故人王彦龙。作毗陵仓官。季夏时。病胸项多汗。两足逆冷。谵语。医者不晓。杂进药。已经旬日。予诊之。其脉关前濡。关后数。予曰。当作湿温治之。盖先受暑后受湿也。难经曰。湿温之脉。阳濡而弱。阴小而急。濡弱见于阳部。湿气搏暑也。小急见于阴部。暑气蒸湿也。暑湿相搏。是名湿温。先以白虎加人参汤。次白虎加苍术汤。头痛渐退。足渐温。汗渐止。三日愈。此证属贼邪。误用药。有死之理。有人难曰。何名贼邪。予曰。难经云五邪。有实邪、虚邪、正邪、微邪、贼邪。从后来者为虚邪。从前来者为实邪。从所不胜来者为贼邪。从所胜来者为微邪。自病者为正邪。又曰。假令心病。中暑得之为正邪。中湿得之为贼邪。今心先受暑而湿邪乘之。水克火。从所不胜。斯谓之贼邪。五邪中之最逆也。", "3373": "张路玉治范振麟。大暑中。患厥冷自利。六脉弦细芤迟。按之欲绝。舌色淡白。中心黑润无胎。口鼻气息微冷。阳缩入腹。而精滑如冰。问其所起之由。因卧地昼寝受寒。是夜连走精二度。忽觉颅胀如山。坐起晕倒。便四肢厥逆。腹痛自利。胸中兀兀欲吐。口中喃喃妄言。与湿温之证不殊。医者误为停食感冒。与发散消导药。服后胸前头项汗出如漉。背上愈加畏寒。而下体如冰。一日昏愦数次。此阴寒挟暑。入中手足少阴之候。缘肾中真阳虚极。所以不能发热。遂拟四逆加人参汤。用人参一两。熟附三钱。炮姜二钱。炙甘草二钱。昼夜兼进。三日中进六剂。决定第四日寅刻回阳。是日悉屏姜、附。改用保丸。人参五钱。黄耆三钱。炙甘草二钱。加麦门冬二钱。五味子一钱。清肃膈上之虚阳。四剂食进。改用生料六味加麦冬、五味。每服用熟地八钱。以救下焦将竭之水。使阴平阳秘。精神乃治。", "3374": "震按此条立法甚巧。惜不载脉象若何。然读嘉言春温论。自述收功反掌。并笑人见热烦枯燥之证而不敢用附子者之愚。则脉不必论耶。又云。冬不藏精之春温。初发时未必脉微数。惟不用麻附细辛、麻附甘草二方。驯至脉微且数。而汗下温皆不能救。见解独辟。又周禹载曰。温疫大法。以证为则。毋专以脉为据。亦必有所见而云然也。", "3375": "一人夏月远行劳倦。归感热证。下痢脓血。身如燔炙。舌黑而燥。夜多谵语。林北海视之曰。此阳明病也。不当作痢治。但脉已散乱。忽有忽无。状类虾游。殆不可治。其家固请用药。林曰。阳明热甚。当速解其毒。在古人亦必急下之以存真阴之气。然是证之源。由于劳倦。阳邪内灼。脉已无阴。若骤下之。则毒留而阴绝。死不治矣。勉与养阴。以冀万一。用熟地一两。生地、麦冬、归、芍、甘草、枸杞佐之。戒其家曰。汗至乃活。服后热不减。而谵语益狂悖。但血痢不下。身有微汗。略出即止。林诊之。则脉已接续分明。洪数鼓指。喜曰。今生矣。仍用前方。去生地加萸肉、丹皮、山药、枣仁。连服六帖。谵妄昏热不减。其家欲求更方。林执不可。又二日。诊其脉始敛而圆。乃用四顺清凉饮子加熟地一两。大黄五钱。下黑矢而诸证顿愈。越二日。忽复狂谵发热。喘急口渴。举家惶惑。谓今必死矣。林笑曰。岂忘吾言乎。得汗即活矣。此缘下后阴气已至。而无以鼓动之。则营卫不洽。汗无从生。不汗则虚邪不得外达。故内沸而复也。病从阳入。必从阳解。遂投白术一两。干姜三钱。甘草一钱。归、芍各三钱。尽剂。汗如注。酣卧至晓。病良已。", "3376": "震按此证疑难在于初末。初期脉类虾游。若援张景岳证实脉虚之说而用参、术、姜、附则必死。末后狂热复发。若引吴又可余邪注胃之说而用白虎承气亦必危。此案见解用药俱佳。然其得生处。在于养阴而血痢顿止。脉即应指耳。中间连服六帖。谵妄昏热不减。幸不见手足厥冷。尤幸不至声喑不语。绝谷不食也。则以脉之敛而圆故也。但白术一两干姜三钱以治狂热喘渴。殊难轻试。", "3377": "徽人江仲琏。冒寒发热。两项臃肿如升大。臂膊磊块无数。不食不便。狂躁发渴。诊其脉浮数无序。医作伤寒发毒治。高鼓峰曰。误矣。此燥逐风生也。用大剂疏肝益肾汤。熟地加至二两许。五剂而肿退便解。十剂而热除食进。再用补中益气汤加麦冬、五味。调理而愈。", "3378": "震按今之所谓伤寒者。大概皆温热病耳。仲景云。太阳病发热而渴不恶寒者为温病。在太阳已现热象。则麻桂二汤必不可用。与伤寒迥别。内经云。热病者皆伤寒之类也。是指诸凡骤热之病。皆当从伤寒例观。二说似乎不同。因审其义。盖不同者在太阳。其余则无不同也。温热病只究三焦。不讲六经。此是妄言。仲景之六经。百病不出其范围。岂以伤寒之类。反与伤寒截然两途乎。叶案云。温邪吸自口鼻。此亦未确。仲景明云。伏气之发。李明之、王安道俱言冬伤于寒。伏邪自内而发。奈何以吴又可温疫论牵混耶。惟伤寒则足经为主。温热则手经病多。如风温之咳嗽息鼾。热病之神昏谵语。或溏泻黏垢。皆手太阴肺手厥阴心胞络手阳明大肠现证。甚者喉肿肢掣。昏蒙如醉。躁扰不宁。齿焦舌燥。发斑发颐等证。其邪分布充斥。无复六经可考。故不以六经法治耳。就予生平所验。初时兼挟表邪者最多。仍宜发散。如防、葛、豉、薄、牛蒡、杏仁、滑石、连翘等。以得汗为病轻。无汗为病重。如有斑。则参入蝉蜕、桔梗、芦根、西河柳之类。如有痰。则参入土贝、天虫、栝蒌、橘红之类。如现阳明证。则白虎承气。少阳证则小柴胡去参、半。加花粉、知母。少阴证则黄连阿胶汤、猪苓汤、猪肤汤。俱宗仲景六经成法有效。但温热病之三阴证多死。不比伤寒。盖冬不藏精者。东垣所谓肾水内竭。孰为滋养也。惟大剂养阴。佐以清热。或可救之。养阴如二地、二冬、阿胶、丹皮、元参、人乳、蔗浆、梨汁。清热如三黄、石膏、犀角、大青、知母、芦根、茅根、金汁、雪水、西瓜、银花露、丝瓜汁。随其对证者选用。若三阴经之温药。与温热病非宜。亦间有用真武理中者。百中之一二而已。大抵温热病。最怕发热不退。及痉厥昏蒙。更有无端而发晕。及神清而忽间以狂言者。往往变生不测。遇此等证。最能惑人。不比阳证阴脉。阳缩舌卷撮空见鬼者。易烛其危也。要诀在辨明虚实。辨得真方可下手。然必非刘河间吴又可之法所能救。平素精研仲景伤寒论者。庶有妙旨。至如叶案之论温热。有邪传心胞。震动君主。神明欲迷。弥漫之邪。攻之不解。清窍既蒙。络内亦痹。豁痰降火无效者。用局方至宝丹。或紫雪。或牛黄丸。宗喻氏芳香逐秽宜窍之说。真足超越前贤。且不蹈用重药者。一匙偶误。覆水难收之弊也。此翁聪明诚不可及。今所选之案虽少。而诸法毕备。亦足为学者导夫先路矣。", "3379": "卫生宝鉴曰。总帅相公。年近七旬。南征过扬州。俘虏万余口。内选美色室女近笄者四。置于左右。予曰。新虏之人。其惊忧之气蓄于内。加以饮食失节。多致疾病。近之则邪气传染。为害最大。况年高气弱。尤宜慎也。总帅不听。至腊月班师。大雪。新虏人冻馁。皆病头疼咳嗽。自利腹痛。多致死亡。正月至汴。相公因赴贺宴。痛饮数次。遂病。脉沉细而弦。三四动一止。现证与新虏人病无异。三日而卒。内经云。乘年之虚。遇月之空。失时之和。因而感邪。其气至骨。可不畏哉。", "3380": "震按喻嘉言疫病论。引仲景平脉篇中寸口脉阴阳俱紧者一节。阐发奥理。谓清邪中上。从鼻而入于阳。浊邪中下。从口而入于阴。在阳则发热头痛项强颈挛。在阴则足膝逆冷。便溺妄出。大凡伤寒之邪。由外廓而入。故递传六经。瘟疫之邪。由口鼻而入。故直达三焦。三焦相溷。内外不通。致有口烂舌断。声嗢咽塞。痈脓下血。脐筑湫痛等变。治法。未病前预饮芳香正气药。使邪不能入。若邪既入。则以逐秽为第一义。此与吴又可之论暗合。较之李罗二家所述劳役忧惊冻馁致病者迥别。惟云因病致死。病气尸气。混合不正之气。种种恶秽。交结互蒸。人在其中。无隙可避。斯无人不病。是诚诸疫所同。然向来辟疫方法。或以雄黄塞鼻。或吃蒜头烧酒。或于发中簪霹雳木。然有验有不验。相传崇正十六年。自八月至十月。京城大疫。猝然而死。医祷不及。后有外省人员到京。能识此病。看膝湾后有筋肿起。紫色无救。红色速刺出血。可无患。人争就看。死者已二十余万。", "3381": "汪石山治一少年。房劳后。忽洒洒恶寒。自汗发热。头背胃脘皆痛。唇赤舌强。呕吐。眼胞青色。医投补中益气。午后谵语恶热。小便长。初日脉皆细弱而数。次日脉浮弦而数。医以手按脐下痛。议欲下之。汪曰。此疫也。疫兼两感。内伤重。外感轻耳。脐下痛者。肾水亏也。若用利药。是杀之也。兹宜合补降二法以治。用清暑益气汤。去苍术、泽泻、五味。加生地、黄芩、石膏。服十余帖而安。", "3382": "壶仙翁治张文学。病时疫。他医诊其脉。两手俱伏。曰。阳证见阴不治。欲用阳毒升麻汤升提之。壶曰。此风热之极。火盛则伏。非阴脉也。升之则死矣。卒用连翘凉膈之剂。一服而解。", "3383": "震按此条是温疫病以证为则。勿专以脉为凭之一据。", "3384": "虞恒德治一妇。三月间。患瘟疫证三日。经水适来。发热愈甚。至七八日。病剧。胸中气筑作痛。不能卧。众医技穷。入夜迎翁。病者令婢磨胸不已。六脉俱微数。极无伦次。又若虾游状。翁问曰。恐下早成结胸耳。主人曰。未也。翁曰。三日而经水行。则里虚与下同。乃用四物汤、黄龙汤、小陷胸汤共为一剂。加姜、枣。主人曰。此药何名。翁曰。三合汤也。一服而诸证悉减。震按此以大黄、黄连、生地、人参同用。亦近日治热病之常法。吴又可曰。朱海畴者。年四十五岁。患疫。得下症。四肢不举。身卧如塑。目闭口张。舌上胎刺。问其所苦不能答。因问其子。两三日所服何药。云进承气汤三剂。每剂投大黄两许不效。更无他策。求决死期。余诊得脉尚有神。下症悉具。药浅病深也。先投大黄一两五钱。目有时而少动。再投。舌刺无芒。口渐开。能言。三剂。舌胎少去。神思少爽。四日。服柴服清燥汤。五日。复生芒刺。烦热又加。再下之。七日又投承气养荣汤。热少退。八日仍用大承气。肢体自能少动。计半月。共服大黄十二两而愈。又数日。始进糜粥。调理两月半平复。凡治千人。所遇此等。不过三四人而已震按此条结句云。千人中不过三四人。自言其不可以为法也。案中不载神昏谵语。可见昏谵之至者多不能救。此人原非绝证也。惜不载脉象虚实若何。然云脉尚有神。想即陶氏所谓有力为有神也。辍耕录载元伯颜平宋后。搜取大黄数十车。满载而去。班师过淮。俘掠之民。及降卒与北来大兵咸病疫。以大黄疗之。全活甚众。宋元通鉴载作耶律楚材灭夏之事。则大黄洵治疫之妙品也。吴又可瘟疫论赞大黄为起死神丹。原非杜撰。然与东垣所论则迥别矣。要之两家各有至理。惟明乎运气。熟于脉证者。两家之说俱可救人也。孙东宿有仆孙安。远行途次食面三碗。劳倦感疫。又加面伤。表里皆热。昏闷谵语。头痛身痛腹痛。医以遇仙丹下之。大便泻三四十行。邪因陷下而为挟热下利之候。舌沉香色。额疼口干。燥渴烦闷。昏昏愦愦。脉左弦数。右洪数。但不充指。知为误下坏证。以柴胡。石膏各三钱。白芍、黄芩、竹茹、葛根各一钱。花粉、甘草各五分。山栀、枳实各七分。葱白五茎。煎服后。斗夜吐蛔一条。稍得睡。次早。大便犹泻二次。呕吐酸水。腹仍痛。改用小柴胡加滑石、竹茹。夜热甚。与丝瓜汁一碗。饮既。神顿清爽。少顷。药力过时。烦热如前。再以丝瓜汁一大碗进之。即大发战。东宿谓此非寒战。乃作汗下之征耳。不移时。汗果出而热依然。因忆活人书云。再三汗下热不退。以人参白虎汤加苍术一钱如神。迹此再加元参、升麻、柴胡、白芍、黄连。饮后。身上发斑。先发者紫。后发者红。中夜后。乃得睡而热散。斑寻退去。腹中微疼。肠鸣口渴。右脉尚滑。左脉已和。再与竹叶石膏汤加白芍、苍术。服后睡安。腹仍微痛。用柴胡、白芍各一钱。人参、酒芩、陈皮、半夏各六分。甘草三分。乌梅一个。腹痛渐减而愈。惟两胯痛不能转动。此大病后汗多而筋失养之故。用参、耆、白芍、枸杞、苡仁、木瓜、熟地、归身、川柏、牛膝、桑寄生。调养全安。震按战汗后热不退。势亦危矣。引用活人书治法佳极。再看其石膏、人参之去取。并不执著。两胯疼痛之调养方更周到。的是高手。", "3385": "程家内眷。其夫殁于疫疠。新寡七日。疫即及之。大热。头疼口渴。胸胁迸痛。医与小柴胡汤。夜忽梦夫交。泄而觉。冷汗淫淫。四肢如解。略不能动。神昏谵语。面如土色。舌黑干硬。迓孙东宿诊之。六脉沉弦而数。大小便俱秘。乃曰。此亦阴阳易类也。疫后有是。危已极矣。以生脉散加柴、芩、桂枝、甘草。水煎。将伊夫昔穿旧袴裆烧灰调下。两剂而神醒。体温汗敛。舌焦渐退。次日。仍以前方加枣仁、竹茹。四肢始能运动。徐进粥汤而愈。震按梦中之阴阳易大奇。故夫之烧裩散更巧。", "3386": "张路玉曰。瘟有虾蟆瘟、鸬鹚瘟、疙瘩瘟、瓜瓤瘟。形证各别。庞安常又有玳瑁瘟之说。余治洪德敷女初冬发热头痛。胸满不食。已服过发散消导药四剂。至第六日。周身痛楚。腹中疼痛。不时奔响。屡欲圊而不可得。口鼻上唇忽起黑色成片。光亮如漆。与玳瑁无异。见者大骇。余诊之。喘汗脉促。神气昏愦。虽脉证俱危。喜其四围有红晕鲜泽。若痘疮之根脚。紧附如线。他处肉色不变。许以可治。先与葛根黄芩黄连汤。加犀角、连翘、荆、防、紫荆皮、人中黄。解其肌表毒邪。俟其黑色发透。乃以凉膈散加人中黄、紫荆、犀角、微下二次。又与犀角地黄汤加人中黄之类。调理半月而安。", "3387": "罗谦甫治中书右丞姚公茂。六旬有七。宿有时毒。至元戊辰春。因酒再发。头面皆肿而痛。耳前后肿尤甚。胸中烦闷。咽嗌不利。身半以下皆寒。足胫尤甚。由是以床接火炕。身半以上卧于床。身半以下卧于炕。饮食减少。精神困倦而体弱。命罗治之。诊得脉浮数。按之弦细。上热下寒明矣。内经云。热胜则肿。又云。春气者病在头。难经云。蓄则肿热。砭射之也。遂于肿上约五十余刺。其血紫墨如露珠之状。顷时肿痛消散。又于气海中。大艾炷灸百壮。以助下焦阳虚。退其阴寒。次于三里二穴。灸三七壮。治足胻冷。亦引导热气下行故也。复处一方。名曰既济解毒汤。芩、连苦寒。酒制炒为因用。泻其上热以为君。桔梗、甘草。辛甘温上升。佐诸苦药以治热。柴胡、升麻。苦平。味之薄者。阴中之阳。发散上热以为臣。连翘苦辛平以散结消肿。当归辛温。和血止痛。酒煨大黄苦寒。引苦性上行至巅。驱热而下以为使。投剂之后。肿消痛减。大便利。再服减大黄。不旬日良愈。", "3388": "〔附〕故友丁汉奇兄。素嗜酒。十二月初。醉中夜行二里许。次日咳嗽身微热两目肿。自用羌、芷、芎、芩等药。颐皆肿。又进一剂。肿至喉肩胸膛。咳声频而不爽。气息微急。喉有痰声。其肿如匏。按之热痛。目赤如血。而便泻足冷。六脉细数。右手尤细软。略一重按即无。有用普济消毒饮子者。予疑其脉之虚。恐非芩、连、升麻所宜。劝邀沈尧封先生诊之。曰。此虚阳上攻。断勿作大头天行治。病者曰。内子归宁。绝欲两月矣。何虚之有。沈曰。唇上黑痕一条。如干焦状。舌白如敷粉。舌尖亦白不赤。乃虚寒之确据。况泄泻足冷。右脉濡微。断非风火之象。若有风火。必现痞闷烦热。燥渴不安。岂有外肿如此。而内里安贴如平人者乎。遂用菟丝、枸杞、牛膝、茯苓、益智、龙骨。一剂而肿定。二剂而肿渐退。右脉稍起。唇上黑痕亦退。但舌仍白厚。伸舌即颤掉。手亦微振。乃用六君加沉香。而肿大退。目赤亦减。嗽缓痰稀。舌上白胎去大半矣。又次日再诊。右脉应指不微细。重按仍觉空豁。肝气时动。两颧常赤。口反微渴。复用参、苓、杞、芍、橘红、龙骨、沙蒺。补元益肾敛肝而全愈。", "3389": "孙东宿治张孝廉患疫。头大如斗。不见项。唇垂及乳。色如猪肝。昏愦不知人事。见者骇而走。孙诊其脉。皆浮弦而数。初以柴胡一两。黄芩、元参各三钱。薄荷、连翘、葛根各二钱。甘草一钱。服三剂。寒热退。弦脉减。但洪大。知其传于阳明也。改以贯众一两。葛根、花粉各三钱。甘草一钱。黑豆四十九粒。三剂而愈。", "3390": "孙兆治一姜姓酒家。病久将绝。腹满。不省人事。遍身皆润。两足冷至膝下。诊之。六脉皆小弱而急。问其所服药。皆阴病药也。孙曰。此非受病重。药能重病耳。遂用五苓散利小便而腹减。白虎汤解邪热而病愈。盖病本伤暑。始则阳微厥而脉小无力。众医遽以阴证治。其病愈厥。不知阴证胫冷。两臂亦冷。今胫冷臂不冷。则非下厥上行。所以知是阳微厥也。", "3391": "滑伯仁治临安沈君彰。自汗如雨不止。面赤身热。口燥心烦。居楼中。当盛暑。帷幕周密。自云至虚亡阳。服术、附药已数剂。伯仁诊其脉。虚而洪数。视其舌上胎黄。曰。前药误矣。轻病重治。医者死之。素问曰。必先岁气。毋伐天和。术附之热。其可轻用以犯时令耶。又曰。脉虚身热。得之伤暑。暑家本多汗。加以刚剂。脉洪数则病益甚。悉令撤幔开窗。初亦难之。少顷。渐觉清爽。为制黄连人参白虎等汤。三进而汗止大半。诸证稍解。又兼以既济汤。渴用冰水调天水散。服七日而病悉去。后遍身发疡疹。更服防风通圣散。乃已。", "3392": "朱丹溪治徐三官人。年五十余。六月间。发热大汗。恶寒战栗。不自禁持。且烦渴。朱曰。此暑病。脉之。皆虚微细弱而数。其人好赌。致劳而虚。遂以人参竹叶汤调四苓散。八帖而安。", "3393": "震合三案参之。知暑脉必虚必数。虚者暑伤气也。数者暑为热也。但有细与洪之不同。孙案之小弱而急。急亦数也。数主热。又主虚。故暑病宜凉宜补者多。宜温者诚少。下条之脉细数而实。指为热药伤血。见解更上一层。", "3394": "项彦章治一人病甚。医皆以为瘵。束手矣。项诊之。脉细数而实。细数者暑也。暑伤气。脉宜虚。今不虚而反实。乃热伤血。药为之也。以白虎饮之。即瘥。", "3395": "吴茭山治一妇。冬月洒洒恶寒。翕翕发热。恶食干呕。大便欲去不去。诸医皆以虚弱痰饮治之。用二神补心等药不效。延及半月。吴诊其脉。虚而无力。类乎伤暑。众不然之。究问病因。妇曰。因天寒换著绵衣。取绵套一床盖之。须臾烦渴。寒热呕吐。绵延至今耳。吴曰。诚哉伤暑也。盖绵套晒之盛暑。夹热收入笥中。必有暑气尚未开泄。体虚者得之易入。故病如是。妇曰然。遂制黄连香薷饮。连进二服而愈。", "3396": "震按此说殊未可信。绵套久收笥中。暑气能有几何。顿令寒热呕吐。烦渴绵延不愈耶。但脉虚无力。用黄连香薷饮而愈。则诚暑矣。留之作疑案以待试。", "3397": "汪石山治一儿。年十余岁。色白神怯。七月间。发热连日。父令就学。内外俱劳。循至热炽。头痛吐泻食少。其父知医。乃进理中汤。吐泻少止。渐次眼合。咽哑不言。昏昧不省人事。粥饮有碍。手常揾住阴囊。为灸百会尾骶。不应。其父来问。汪曰。儿本气怯。又兼暑月过劳。经云。劳则气耗。又云。劳倦伤脾。虽在暑月。乃内伤证耳。身热者。经云阳气者。烦劳则张。盖为气本阳和。劳则阳和之气变为邪热矣。头痛者。经云诸阳皆会于头。今阳气亢极。则邪热熏蒸于头而作痛也。吐泻者。脾胃之清气不升。浊气不降也。目闭者。盖诸脉皆属于目。而眼眶又脾所主。脾伤不能荣养诸脉。故眼闭而不开也。咽哑者。盖脾之络。连舌本。散舌下。脾伤则络失养。故不能言也。经云。脾胃者。水谷之海。五脏皆禀气于脾。脾虚则五脏皆失所养。故肺之咽嗌为之不利而食难咽。心之神明为之昏瞀而不知人。常欲手揾阴囊者。盖无病之人。阴升阳降。一有所伤。则升者降。降者升。经云。阴阳反作是也。是以阴升者反降。从其类而入厥阴之囊。阴多阳少。故手欲揾之也。此皆脾胃之病。经谓土极似木。亢则害。承乃制也。证似风木。乃虚象耳。不治脾胃之虚。而治肝木之风。欲求活难矣。且用参、耆三钱。附子一钱。灌半杯。病无进退。连服三日。神稍清。目稍开。如有生意。食仍难咽。汪诊之。脉皆浮缓。不及四至。汪曰。药病相宜。可去附子再服。渐渐稍苏。初医或作风热。而用荆、防、芩、连之类。或作惊证。而用牛黄、朱砂之类。此皆损胃之物。岂可轻投。儿今得生幸耳。实赖其父之知医也。", "3398": "江应宿治其岳母。年六十余。六月中旬。劳倦中暑。身热如火。口渴饮冷。头痛如破。脉虚豁。二三至一止。投人参白虎汤三帖。渴止热退。惟头痛。用白萝卜汁吹入鼻中。良愈。", "3399": "又治孙子华赴试南都。六月初旬。梦遗。畏寒惊惧。重裘厚被。取汗过多。身热。六脉滑数无力。与清暑益气汤。次日舌强。语言不清如癫。目瞪不识人。江曰。此为暑风。与人参白虎汤加胆星、僵蚕、秦艽、天麻、竹沥、姜汁、渐愈。数日后。舌心黑如墨。与黄连解毒汤、凉膈散。不退。与犀角地黄汤而愈。", "3400": "又一人瘦长而脆。暑月过劳。饥饮烧酒。遂身热汗出。昏懵语乱。江视之。脉皆浮小而缓。按之虚豁。曰。暑伤心。劳伤脾也。盖心藏神。脾藏意。二脏俱伤。宜有是证。法宜清暑益脾。用八物汤加麦冬、山栀、陈皮。十余帖而愈。", "3401": "张路玉治金鲁公。触热劳形。醉饱不谨后受凉。遂发热头痛。胀满喘逆。大汗如蒸。面赤戴阳。足冷阳缩。脉弦数无力。曰。此伤暑夹食而复夹阴也。与大顺散一服。不应。转胀急不安。因与枳实理中加厚朴、大黄。是夜更衣二次。身凉足暖而痊。", "3402": "又按张洁古云。动而得之者。为中暍。为阳证。静而得之者。为中暑。为阴证。以暑暍二字析作两项。殊属不然。夫夏之暑暍。犹冬之寒冷也。指暍为阳。指暑为阴。亦将派冷作阳。派寒作阴耶。内经曰。先夏至日者为病温。后夏至日者为病暑。明以时令别其病名耳。病暑之有阴有阳。一如伤寒之有阴有阳。大顺散、冷香饮子之类。实为纳凉食冷。因避暑而受寒。固暑月之阴证也。非中暑也。所以罗谦甫治参政商公泄泻、完颜小将军斑衄二案。俱用热药。俱不名之曰中暑。吴球治暑月远行之人。直曰中寒。恐后世误以热药治暑。乃举病因以称之。诚为名正而言顺。故以动静分阴阳则可。以暑暍分阴阳则不可。惟以脉证辨阴阳。斯可矣。近阅临证指南。每用滑石、芦根、通草、白蔻、杏仁等药。以暑气从鼻吸入。必先犯肺。故用轻清之药。专治上焦。其西瓜翠衣、鲜荷叶、及荷叶边汁、鲜莲子、绿豆皮、丝瓜叶、银花露、竹叶心等。皆取轻清以解暑邪之上蒙空窍。不犯中下二焦。殊有巧思。盖暑病必究三焦。非比伤寒温病矣。若来复丹、大顺散。案中偶一见之。又足征暑天阳证居多。阴证原少耳。", "3403": "中山王知府次子薛里。年十三岁。六月暴雨。池水泛溢。因而戏水。衣服尽湿。其母责之。至晚觉精神昏愦。怠惰嗜卧。次日病头痛身热。腿脚沉重。一医用发散药。闭户覆衾。以致苦热不禁。遂发狂言。欲去其衾而不得去。是夜汗至四更。湿透其衾。明日寻衣撮空。又以承气汤下之。后语言渐不出。四肢不能收持。有时项强。手足瘛疭搐急而挛。目左视而白睛多。口唇肌肉蠕动。饮食减少。形体顿瘦。延罗谦甫视之。具说前由。盖伤湿而失于过汗也。夫人之元气。起于脐下肾间动气。周流一身。通行百脉。今盛暑之时。大发其汗。汗多则亡阳。百脉行涩。故三焦之气不能上荣心肺。心火旺而肺气焦。况因惊恐内蓄。内经曰。恐则气下。阳主声。阳既亡而声不出也。阳气者。精则养神。柔则养筋。今发汗过多。气血俱衰。筋无所养。其病为痓。则项强手足瘛疭搐急而挛。目通于肝。肝者筋之合也。筋既燥而无润。故目左视而白睛多。肌肉者脾也。脾热则肌肉蠕动。故唇蠕动有时而作。经云。肉痿者。得之湿地也。脾热者。肌肉不仁。发为肉痿。痿者。痿弱无力。今气欲竭。热留于脾。故四肢不用。此伤湿过汗而成坏证明矣。当治时之热。益水之源。救其逆。补其上升生发之气。内经曰。热淫所胜。治以甘寒。以酸收之。人参、黄耆之甘温。补其不足之气而缓其急搐。故以为君。肾恶燥。急食辛以润之。生甘草甘微寒。黄柏苦辛寒。以救肾水而生津液。故以为臣。当归辛温和血脉。橘皮苦辛。白术苦甘。炙甘草甘温。以益脾胃。进饮食。肺欲收。急食酸以收之。白芍药之酸微寒。以收耗散之气而补肺金。故以为佐。升麻、柴胡苦平。上升生发不足之气。故以为使。乃从阴引阳之谓也。早晚各投一服。三日后。语声渐出。少能行步。四肢柔和。食饮渐进。因志其方曰人参益气汤。", "3404": "震按古人治湿病案。殊无高论奇方。故仅选此条以为辨证处方之模范。今临证指南佳案甚多。良足私淑。其除气分之湿。用滑石、白蔻、杏仁、半夏、厚朴、栝蒌皮为主。有热则加竹叶、连翘、芦根等。全取轻清之品。走气道以除湿。若湿热甚而舌白目黄。口渴溺赤。用桂枝木、猪苓、泽泻、滑石、茯苓皮、寒水石、生白术、茵陈。此从桂苓甘露饮加减。湿热作痞。神识如蒙。用人参、芩、连、枳实、生干姜、生白芍。此从泻心汤加减。若脘中阻痛。大便不爽。用豆豉、枳实、川连、姜汁、苓、半。热轻则去川连。加郁金、橘红、苡仁、杏仁。此湿伤气痹治法。热甚则用川连、生术、厚朴、橘白、淡生姜渣、酒煨大黄。水法丸服。此治气阻不爽。治腑宜通法。湿伤脾阳腹膨。用五苓散、二术膏。湿热横渍。脉腠腹满。用小温中丸。以及脘痞便溏之用苓桂术甘汤。吞酸形寒之用苓姜术桂汤。虽皆古人成法。而信手拈来。无不吻合。湿温身热神昏。用犀角、元参、连翘心、石菖蒲、银花、野赤豆皮。煎送至宝丹。乃清热通窍芳香逐秽法。更奇者湿温之头胀耳聋。呃忒鼻衄。舌色带白。咽喉欲闭。谓邪阻上窍空虚之所。非苦寒直入胃中可治。而用连翘、牛蒡、银花、马勃、射干、金汁。此俗人梦想不到者也。不食不寐。腹痛便窒。脉迟小涩。谓由平素嗜酒少谷。湿结伤阳。寒湿浊阴。鸠聚为痛。而用炒黑生附子、炒黑川椒、生淡干姜、葱白。调入猪胆汁。此加味白通汤。亦神奇不可思议者也。更有嗜酒人。胸满不饥。三焦皆闭。二便不通。用半硫丸。又有病中啖厚味者。肠胃滞。虽下。而留湿未解。肛门坠痛。胃不喜食。舌上白腐。用平胃散去甘草加人参、炮姜、炒黑生附。此二条不因酒肉认作湿热。竟以苦辛温药通阳劫湿。尤觉高超。至如阳伤痿弱。有湿麻痹。虽痔血而用姜、附、茯苓、生术。舌白身痛。足跗浮肿。太谿穴水流如注。谓湿邪伏于足少阴。而用鹿茸、淡附子、草果、茯苓、菟丝。以温蒸阳气。均非浅识所能步武。湿久脾阳消乏。肾真亦惫。中年未育子。用茯、菟、苍术、韭子、大茴、鹿茸、附子、胡卢、补骨、赤石脂。仿安肾丸法。治病调元化为合璧。益有观止之叹。湿门附此诸案。方法斯为全备。", "3405": "东坡集载眉山揭颖臣。长七尺。素健饮啖。忽得渴疾。日饮水数斗。饭亦倍进。小便频数。服消渴药逾年。病日甚。自度必死。蜀医张𬭎。取麝香当门子。以酒濡湿。作十余丸。用枳椇子煎汤。服之遂愈。问其故。张曰。消渴消中。皆脾衰而肾败。土不胜水。肾液不上溯。乃成此疾。今诊颖臣脾脉极热。肾脉不衰。当由酒果过度。积热在脾。所以多食多饮。饮多溺不得不多。非消渴也。麝香坏酒果。枳椇能化酒为水。故假二物。去其酒果之毒也。", "3406": "汪石山治一妇年逾三十。常患消渴善饥。脚弱。冬亦不寒。小便白浊。浮于上者如油。脉皆细弱而缓。右脉尤弱。曰。此脾瘅也。宜用甘温助脾。甘寒润燥。以参、耆各钱半。麦冬、白术各一钱。白芍、花粉各八分。黄柏、知母各七分。煎服病除。", "3407": "张景岳治周公。年逾四旬。因案牍积劳。神困食减。时多恐惧。自冬春达夏。通宵不寐者。半年有余。而上焦无渴。不嗜汤水。或有少饮。则沃而不行。然每夜必去溺二三升。莫知其所从来。且半皆如膏浊液。尫羸至极。自分必死。岂意诊之。脉犹带缓。肉亦未脱。知其胃气尚存。慰以无虑。乃用归脾汤去木香。及大补丸煎之属。一以养阳。一以养阴。出入间用。至三百余剂。计人参二十斤。乃得全愈。此神消于上精消于下之证。可见消有阴阳。不得尽言火。", "3408": "孙东宿治一书办。年过五十。酒色无惮。忽患下消症。一日夜小便二十余度。清白而长。味且甜。少顷凝结如脂。色有油光。他医治半年不验。腰膝以下皆软弱。载身不起。饮食减半。神色大瘁。孙诊之。六部大而无力。经云。脉至而从。按之不鼓。诸阳皆然。法当温补下焦。以熟地六两为君。鹿角霜、山茱萸各四两。桑螵蛸、鹿角胶、人参、茯苓、枸杞、远志、菟丝、山药各三两为臣。益智仁一两为佐。桂、附各七钱为使。蜜丸。早晚盐汤送四五钱。不终剂而愈。此证由下元不足。无气升腾于上。故渴而多饮。以饮多小便亦多也。今大补下元。使阳气充盛。熏蒸于上。则津生而渴止矣。", "3409": "虞恒德治一妇。年四十余。夜间发热。早晨退。五心烦热无休止时。半年后。虞诊六脉皆数。伏而且牢。浮取全不应。与东垣升阳散火汤四服。热减大半。胸中觉清快胜前。再与二帖。热悉退。后以四物加知母、黄柏。少佐炒干姜。服二十余帖愈。", "3410": "震按夜热脉数。的系阴虚。因其脉伏且牢。浮取不应。故用升阳散火得效。仍以阴药收功。然阴药用六味地黄及二地二冬必不效。妙在芎、归合知、柏。及从治之炒干姜也。", "3411": "王仲阳治一妇。壮年。每患头痛腹痛。十指酸痛。心志纷纭。鼻息粗甚。其脉甚大。盖欲近男子不可得也。俗谓之花风。王以凉膈散、青木香丸。互换疏导三五次。更服三黄丸。泻三焦之火。数日而愈。曾有火旺遗精者。亦用前丸散而愈。", "3412": "薛立斋治沈大尹不时发热。日饮冰水数碗。寒药二剂。热渴益甚。形体日瘦。尺脉洪而数。时或无力。王太仆曰。热之不热。责其无火。寒之不寒。责其无水。又云。倏热往来。是无火也。时作时止。是无水也。法当补肾。用加减八味丸。不月而愈。", "3413": "汪石山治一人。年逾三十。神色怯弱。七月患热淋。诸药不效。至十一月行房方愈。正月复作。亦行房而愈。三月伤寒。咳嗽有痰。兼事烦恼。延至十月少愈。后复作。服芦吸散而愈。但身热不解。因服小便。腹内膨胀。小腹作痛。后又因晚卧。左胁有气触上。痛不能睡。饮食减半。四肢无力。食则腹胀痛或泻。兼胸膈饱闷。口舌干燥。夜卧盗汗。从腰以下常冷。久坐腰痛脚软。手心常热。诊左手心脉浮数而滑。肾肝二脉沉弱颇缓。右手肺脉虚浮而快。脾脉偏弦而快。命门散弱而快。次日再诊。心肝二脉细软。稍不见快矣。肾脉过于弱。肺脉浮软。亦不见快。脾脉颇软。命门过浮。略坚。汪曰。膀胱者。津液之府。气化出焉。淋者由气馁不能运化。故津液郁结为热而然也。房后而愈者。郁结流利而热自解矣。三月天日和煦。何得伤寒。多由肺气不足。莫能护卫皮毛。故为风邪所袭。郁热而动其肺。以致痰嗽也。得芦吸散而愈者。以辛温豁散痰与热也。嗽止身热不退者。由嗽久肺虚。虚则脾弱。脾肺之气不能荣养皮毛。故热作也。经曰。形寒饮冷则伤肺。又曰。脾胃喜温而恶寒。今服小便之寒凉。宁不愈伤其脾肺耶。是以腹胀作痛。胁气触上。或泻或汗。种种诸病。皆由损其脾肺也。时或变易不常者。亦由气血两虚。虚而为盈。难乎有常矣。遂用参、耆各二钱。茯苓、白术一钱。归身、牛膝七分。厚朴、陈皮、木香、甘草各五分。薄桂三分。煎服二十余帖。诸证悉退。后因梳头劳倦。诸证复作。汪诊脉与前颇同。但不数不驶耳。仍用参、耆各三钱。麦冬、归身、厚朴、枳实、甘草等剂。愈。", "3414": "一人七月病上辰昏晕。下午不言。昏睡一日不醒。人叫不应。身凉不食。不寒不热。皆曰阴证。议用理中四逆。周慎斋诊其脉。沉小带伏。曰。内有火邪也。故小便一二日不解。延至夜不醒。周曰。此真火也。其妻曰。前日房事。如何是火。周曰。夜有房事。内虚又劳。热甚。夫干热从虚入。则阴气将绝。以水救之则可。取冷水一桶。饮至五碗。病者曰渴。饮至七碗。大汗如雨。病者曰饿。吃粥一碗。用补中益气汤加炮姜、泽泻。温中泻冷水而愈。", "3415": "慎斋又治一妇。五月间身凉。自言内热。水泻二月。一日数次。小水绝无。大便俱水。自言上热极。下冻死。腰腿足俱冷。腹痛如冰。或一时发热。不欲近衣。或一时怕冷。遍身尽热。夜至天明。面目红肿。药之不愈。六脉洪大。此伏火也。火性炎上。故上热下冷耳。用四物汤加柴胡、葛根、升麻、甘草、栀子、黄芩、黄柏。二帖。小水行。泻止。复发牙疼。三日不愈。用黄耆建中汤加附子。一服。", "3416": "一妇六月卒死。遍体俱冷。无汗。六脉俱伏。三日不醒。但气未绝耳。众用四逆理中。亦不能纳。四日后。慎斋诊之。仍无脉。念人一二日无脉立死。今三日不死。此脉伏也。热极似寒耳。用水湿青布放身上。一时身热。遂饮冷水五六碗。反言渴。又一碗。大汗出。后用补中益气加黄柏。十帖愈。", "3417": "石顽治太史张宏蘧。精气下脱。虚火上逆。怔忡失血证。诊其右关独弦。左尺微数。余皆微细搏指。明系阴火内伏之象。诊后详述去冬劳心太过。精气滑脱。加以怵惕恐惧。怔忡惊悸不宁。都门之医。峻用人参、桂、附。至岁底稍可。交春复剧如前。遂乞假归吴。吴门诸医。亦用参、附导火归源。固敛精气之药。略无一验。转觉委顿。稍稍用心。则心系牵引掣痛。痛连脊骨对心处。或时痛引膺胁。或时巅顶如掀。或时臂股手足指甲皆隐隐作痛。怔忡状如碓杵。控引头中。如失脑髓之状。梦中尝自作文。觉时成篇可记。达旦倦怠睡去。便欲失精。精去则神魂如飞越之状。观其气色鲜泽。言谈亹亹。总属真元下脱。虚阳上扰之候。细推脉证。始先虽属阳气虚脱。过饵辛温峻补。致阳暴亢而反耗真阴。当此急宜转关。以救垂绝之阴。为疏二方。煎用保丸合四君。丸用六味合生脉。服及两月后。诸证稍平。但倦怠力微。因自检方书。得补中益气汤。为夏月当用之剂。于中加入桂、附二味。一啜即喉痛声喑。复邀诊候。见其面颜精采。而声音忽喑。莫解其故。询之乃尊。知为升麻桂附升动虚阳所致。即以前方倍生脉服之。半月后。声音渐复。日渐向安。但起居调摄。殊费周折。衣被过暖。便咽喉痰结。稍凉则背微畏寒。或啜热饮。则周身大汗。怔忡走精。此皆宿昔过用桂、附。余热内伏而寻出路也。适有石门董载臣。谓其伏火未清。非芩、连不能解散。时值嘉平。不敢轻用苦寒。仲春载臣复至。坐俟进药。服数剂。形神爽朗。是后坚心服之。至初夏。反觉精神散乱。气不收摄。乃复就正于予。予谓桂、附汤药。火毒之性。方能上升。得参以濡之。故可久伏下焦。与龙潜水底不异。若究其源。惟滋肾丸一方为正治。但既经芩、连折之于上。岂堪复受知、柏侵伐于下乎。况自春徂夏不离苦寒。苦先入心。必从火化。何敢兼用肉桂。引动虚阳。发其潜伏之性哉。端本澄源。仍不出六味合生脉。经岁常服。不特壮水制阳。兼得金水相生之妙用。何惮桂、附之余毒不化耶。", "3418": "罗谦甫治一人。年近八十。六月。中暑霍乱。吐泻昏冒。终日不省人事。时夜半。请罗治。脉七八至。洪大有力。头热如火。足冷如冰。半身不遂。牙关紧急。盖年高气弱。当暑气极盛。阳明得令之际。中暑明矣。用桂苓甘露饮。甘辛大寒。泻热补气。加茯苓以分阴阳。约一两。水调灌之。渐渐省事。三日后。诸证悉去。换人参补中汤。以意增减。十日后平复。", "3419": "又治蒙古百户昔良海。于戊午春。攻襄阳回。住夏曹州界。因食酒肉。多饮潼乳。得霍乱吐泻证。从朝至午。精神昏愦。已困急。来告。罗视之。脉皆浮数。按之无力。所伤之物已出矣。即以新汲水。调桂苓白术散。徐徐服之。稍得安静。又于墙阴掘地约二尺许。贮新水在内。搅动。待一时。澄定。用清者一杯。再调服之。吐泻渐止。至夜安卧。翌日微烦渴。遂煎钱氏白术散。时时服。良愈。或问用地浆者。何也。曰。坤属土。土平曰静顺。感至阴之气。又于墙阴贮新汲水。以收重阴之气。阴中之阴。能泻诸阳中之阳。霍乱由暑热内伤所得。故用地浆而愈。", "3420": "汪石山治一人。年三十余。形瘦弱。忽病上吐下泻。水浆不入口者七日。自分死矣。汪诊脉八至。曰。当夏而得是脉。暑邪深入也。用人参白虎汤进一杯。稍安。后减去知母、石膏。加人参至四五钱。以黄柏、陈皮、麦冬等。随所兼病而佐使。一月平复。", "3421": "江篁南治一人。于七月间得霍乱证。吐泻转筋。足冷多汗。囊缩。医以伤寒治之。增剧。江诊之。左右寸关皆伏不应。尺极微。口渴欲饮冷水。乃以五苓散与之。觉稍定。向午犹渴。以五苓加麦冬、五味、滑石投之。更以黄连香薷饮。冷进一服。次早脉稍出。按之无根。人形脱。且呃。手足厥逆。饮食不入。入则吐。大便稍不禁。为灸丹田八九壮。囊缩稍舒。手足稍温。继以理中汤。渴犹甚。咽疼热不解。时或昏沉。饮以竹叶石膏汤而愈。", "3422": "江应宿治一妇人。六月中旬。病霍乱吐泻转筋。医投霍香正气散。加烦躁面赤。揭衣卧地。江诊之。脉虚无力。身热引饮。此得之伤暑。宜辛甘大寒之剂泻其火热。以五苓散。加石膏、滑石。吐泻定。再与桂苓甘露饮而愈。", "3423": "震按霍乱乃最轻之病。何以仲景于伤寒后列为一门。岂北五省之霍乱重于江浙耶。就江浙论。则霍乱因暑湿者多。香薷饮加苓、半、霍香、苍术、木瓜等即效。黄连、石膏不可轻用。人参尤不可轻用。石山篁南二案。不得不用人参。然汪案纯是寒证。一用理中。即热渴咽疼。可知暑月难投温补也。若冬月霍乱。固有因寒者。香薷又在所戒。予生平于盛暑时。曾以真武汤治霍乱。其人吐泻腹痛。四肢冷。脉微细。恶寒不渴。故敢用之。取效甚速。亦未尝用人参也。", "3424": "东垣曰。予病脾胃久衰。视听半失。此阴盛乘阳。加之气短。精神不足。此由弦脉令虚多言之故。阳气衰弱。不能舒伸。伏匿于阴中耳。癸卯六七月间。霖雨阴寒。逾月不止。时人多病泄利。乃湿多成五泄故也。一日体重肢痛。大便泄泻。小便秘涩。默思内经云。在下者。引而竭之。是利小便也。故经又云。治湿不利小便。非其治也。当用淡渗之剂以利之为正法。但圣人之法。虽布在方策。其不尽者。可以意求。今客邪寒湿之淫。自外入里而甚暴。若以淡渗之剂利之。病虽即已。是降之又降。复益其阴而重竭其阳。则阳气愈削而精神愈短矣。唯以升阳之药为宜。用羌、独、升麻各一钱。防风、炙甘草各五分。水煎热服。大法云。寒湿之胜。助风以平之。又云。下者举之。此得阳气升腾故愈。是因曲而为之直也。", "3425": "张子和治赵明之。米谷不消。腹作雷鸣。自五月至六月不愈。诸医以为脾受大寒。屡用圣散子、豆蔻丸等。俱不效。戴人曰。春伤于风。夏必飧泄。飧泄者。米谷不化而直出也。又曰。久风入中。则为肠风飧泄。中者脾胃也。风属甲乙。脾胃属戊己。甲乙能克戊己。肠中有风故鸣。经又曰。岁木太过。风气流行。脾土受邪。民病飧泄。诊其两手脉皆浮数。为病在表也。可汗之。风随汗出泄当愈。以火二盆。暗置床下。给之入室。使服涌剂。以麻黄投之。乃闭其户。待一时许。汗出如洗。开户。减火一半。须臾。汗止泄亦止。", "3426": "〔附〕神秘名医录载庞从善治著作王公苹泄利。诊之。曰。两手三部中得脾脉浮而弦。浮主风。弦主湿。又弦为肝脉。病因风湿外伤。致肝木刑于脾土而为洞泄。又名飧泄也。内经云。春伤于风。邪气留连。乃为洞泄。又云。春伤于风。夏生飧泄。其利下物。主浑白而完出是也。遂以五泄丸煎服之。数服而瘥。王公曰。从善年未四十。亦医之妙进。曾撰脉法鍖源论一部。共二十篇。示愚观之。诚得叔和未尽之趣者也。", "3427": "震按庞公此条。已为张戴人导其先路矣。又郝允治夏英公病泄。太医皆为中虚。郝曰。风客于胃则泄。殆藁本汤证也。夏骇曰。吾服金石等药无数。泄不止。其敢饮藁本乎。郝强进之。泄止。此皆以风药治泄之模范也。然考仓公诊阳虚侯相赵章病。曰。其脉滑。是内风气也。饮食下咽。而辄出不留者。名曰迵风。法五日死。犹能嗜粥。后十日乃死。所谓安谷者。过期也。即予所阅历。凡直肠泻者多死。不可概许以风药能治也。", "3428": "又治一人泻利不止。腹鸣如雷。不敢冷坐。坐则下注如倾。诸医例断为寒证。姜、桂、丁香、豆蔻。及枯矾、龙骨之类。靡不遍服。兼以燔针灼艾。迁延将二十载。戴人诊之。曰。两寸脉皆滑。余不以为寒。然其所以寒者水也。以茶调散涌寒水五七升。无忧散泄积水数十行。乃通因通用之法也。次以五苓散淡剂渗利之。又以甘露散止渴。不数日而全愈。", "3429": "震按久泻治以吐法尚可学。吐后复用大下。不敢学。及观项彦章治南台治书郭公。久患泄泻。恶寒。日卧密室。以毡蒙首。炽炭助之。皆作沉寒痼冷治。不效。项曰。公之六脉。浮濡且微数。濡者湿也。数者脾有伏火也。病由湿热。而且加之以热剂。非苦寒逐之不可。乃先用羌活、升、柴、泽泻以升阳散火。继以神芎丸下之。即去毡及炭而愈。此正善学子和者。", "3430": "罗谦甫随征南副元帅大忒木儿。驻扬州。时年六十八。仲冬病自利。完谷不化。脐腹冷疼。足䟰寒。以手搔之。不知痛痒。烧石以温之。亦不得暖。罗诊之。脉沉细而微。乃曰。年高气弱。深入敌境。军事烦冗。朝暮形寒。饮食失节。多饮乳酪。履于卑湿。阳不能外固。由是清湿袭虚。病起于下。故䟰寒而逆。内经云。感于寒而受病。微则为咳。盛则为泻为痛。此寒湿相合而为病也。法当急退寒湿之邪。峻补其阳。非灸不能已其病。先以大艾炷于气海。灸百壮。补下焦阳虚。次灸三里二穴。各三七壮。治形寒而逆。且接引阳气下行。又灸三阴交二穴。以散足受寒湿之邪。遂处方云。寒淫所胜。治以辛热。湿淫于外。治以苦热。以苦发之。以附子大辛热。助阳退阴。温经散寒。故以为君。干姜、官桂。大热辛甘。亦除寒湿。白术、半夏。苦辛温而燥脾湿。故以为臣。人参、草豆蔻、炙甘草。甘辛大温。温中益气。生姜大辛温。能散清湿之邪。葱白辛温。以通上焦阳气。故以为佐。又云。补下治下制以急。急则气味厚。故作大剂服之。不数服。泻止痛减。足䟰渐温。调其饮食。逾十日平复。明年秋过襄阳。值霖雨旬余。前证复作。依前灸。添阳辅各灸三七壮。再以前药投之。数服良愈。方名加减白通汤。", "3431": "白云集曰。黄子厚者。江西人也。精医术。邻郡一富翁。病泄泻弥年。礼致子厚诊疗。浃旬莫效。子厚曰。予未得其说。求归。一日读易。至乾卦天行健。朱子有曰。天之气运转不息。故阁得地在中间。如人弄碗珠。只运动不住。故在空中不坠。少有息则坠矣。因悟向者富翁之病。乃气不能举。为下脱也。又作字持水滴吸水。初以大指按滴上窍。则水满筒。放其按则水下溜无余。乃豁悟曰。吾可治翁证矣。即治装往。以艾灸百会穴三四十壮。泄泻止矣。医说会编注曰。百会属督脉。居顶巅。为天之中。是主一身之气者。元气下脱。脾胃无凭。所以泄泻。是谓阁不得地。经云。下者上之。所以灸百会愈者。使天之气复健行。而脾土得以凭之耳。铜人经谓百会灸脱肛。其义一也。", "3432": "震按仲景伤寒论曰。少阴病。下利。脉微涩。呕而汗出。必数更衣。反少者。当温其上。灸之。上字即指百会穴也。何待黄子厚始悟耶。及读资生经曰。旧传有人年老而颜如童子者。盖每岁以鼠粪灸脐中神阙穴一壮故也。予尝久患溏利。一夕灸三七壮。则次日不如厕。连数夕灸。则数日不如厕。足见经言主泄利不止之验。是又与灸百会穴同一捷法。又张子和云。山东杨先生者。治府主洞泄不已。杨虽对病人。却与众人谈日月星辰缠度。及风云雷雨之变。自辰至未。病者听之而忘其圊。杨尝曰。治洞泄不已之人。先问其所慧之事。好棋者与之棋。好乐者与之笙笛。勿辍。是又于服药灸火之外。添一巧法。盖脾主信。泻久则以泻为信。使忘其圊。则失其泻之信而泻可止矣。", "3433": "丹溪云。叔祖年七十。禀甚壮。形甚瘦。夏末患泻利。至秋深。百方不效。病虽久而神不悴。小便涩少而不赤。两手脉俱涩而颇弦。自言膈微闷。食亦减。此必多年沉积。僻在肠胃。询其平生喜食何物。曰。我喜食鲤鱼。三年无一日缺。予曰。积痰在肺。肺为大肠之藏。宜大肠之不固也。当与澄其源则流自清。以茱萸、青葱、陈皮、苜蓿根、生姜煎浓汤。和以沙糖。饮一碗许。自以指探喉中。至半时。吐痰半升许如胶。是夜减半。次早又饮。又吐痰半升而利止。又与平胃散加白术、黄连。旬日十余帖而安。", "3434": "又治一老人。右手风挛多年。九月内泄泻。百药不效。右手脉浮大洪数。此太阴经有积痰。肺气壅遏。不能下降。则大肠虚而作泻。当治上焦。用萝卜子擂和为浆水探之。吐大块胶痰碗许。随安。", "3435": "一富儿面黄。善啖易饥。非肉不食。泄泻一月。脉大。以为湿热。当困而食少。今反形健而食多。不渴。此必疳虫也。验其大便果有蛔。治虫而愈。次年夏初。复泻。不痛而口干。朱曰。昔治虫而不治甜故也。以去疳热之药。白术汤下。三日而愈。后用白术为君。芍药为臣。川芎、陈皮、黄连、胡黄连。佐芦荟为丸。白术汤下。禁肉与甜。防其再举。", "3436": "一人性狡躁。素患下疳疮。或作或止。夏初患自利。膈微闷。医与理中汤。闷厥而苏。脉涩。重取略弦数。朱曰。此下疳之深重者。与当归龙荟丸去麝。四帖而利减。又与小柴胡去半夏。加黄连、白芍、川芎、生姜。数帖而愈。", "3437": "震按丹溪四案。其吐法犹为子和所常用。而一究其嗜食之何物。一凭其右脉之洪数。灼见为积痰在肺。然后用吐。吐药亦复不同。较之子和不辨寒热虚实。总与吐下者。谁圣谁狂。至于治虫疳治下疳。其巧更难及。吕沧洲治帅府从事帖木失尔。病下利完谷。众医咸谓洞泄寒中。日服四逆理中辈。弥剧。吕诊其脉。两尺寸俱弦大。右关浮于左关一倍。其目外眦如草滋。盖知肝风传脾。因成飧泄。非藏寒所致。饮以小续命汤。损麻黄加术三五升。利止。续命非止利药。饮不终剂而利止者。以从本治故也。", "3438": "震按此条与张子和治赵明之条似同而不同。彼为外风所伤。此则内风相传。治虽仿佛。义有分别也。又沧洲治御史王彦芳内飧泄弥年。当秋半。脉双弦而浮。乃曰。夫人之病。盖由惊风。非饮食劳倦所致也。以肝主惊。故虚风自甚。因乘脾而成泻。当金气正隆尚尔。至明春则病将益加。夫人自述因失铜符而惊惧。由是疾作。乃用黄犉牛肝。和以攻风健脾之剂。逾月泻止。是又内风一种也。", "3439": "滑伯仁治一人。暑月泄泻。小便赤。四肢疲困不欲举。自汗。微热口渴。且素羸瘠。医以虚劳。将峻补之。伯仁诊视六脉虚微。曰。此东垣所谓夏月中暑。饮食劳倦。法宜服清暑益气汤。投二剂而病如失。", "3440": "汪石山治一人。于幼时误服毒药。泄痢。复伤食。大泻不止。后虽能食。不作肌肤。每至六七月。遇服毒之时。痛泻复作。善饥多食。胸膈似冷。夜间发热。嗜卧懒语。闻淫欲言。阳举心动。惊悸盗汗。喉中有痰。小便不利。大便或结或溏。过食则呕吐泄泻。脉皆濡弱而缓。右脉略大。犹觉弱也。次日左脉三五不调。或二三至缓。三五至快。右脉如旧缓弱。其左脉不调者。必动欲以摇其精也。其右脉缓弱者。由于毒药损其脾也。理宜固肾养脾。遂以参、术、茯苓、芍药、黄耆、麦冬各一钱。归身、泽泻各七分。知、柏、山楂各六分。煎服而安。", "3441": "震按此条脉甚奇。论脉亦奇。可以广学者之见。", "3442": "程明佑治一人。下泄。勺水粒米不纳。服汤药即呕。程诊之曰。病得之饮酒。脾恶湿。汤药滋湿矣。以参、苓、白术和粳米为糕食之。病旋已。所以知其病得之饮酒过多者。切其脉濡缓而弱。脾伤于湿也。", "3443": "震按濡缓而弱是虚脉。亦是湿脉。参、苓、术作糕代汤。补虚不助湿。与后之晚食前进热药。同一巧思。", "3444": "一人久患泄泻。以暖药补脾。及分利小水诸法。不应。一医诊之。心脉独弱。乃以益心气药。兼补脾药服之。遂愈。盖心火能生脾土。又于命门火生脾土之外。另伸一义也。", "3445": "李士材治闽人张仲辉。素纵饮。又喜啖瓜果。忽患大泻。诸用分利燥湿者俱不效。李诊其六脉皆浮。乃引经言春伤于风。夏生飧泄。用麻黄三钱。参、术各二钱。甘草、升麻各一钱。取大汗而愈。", "3446": "缪仲淳曰。金坛庄敛之。素壮实。善啖。仲夏忽患泄泻。一应药粥蔬菜入喉。觉如针刺。下咽即辣。因而满腹绞辣。随觉腹中有气。先从左升。次即右升。氤氲遍腹。即欲如厕。弹响大泄。肛门恍如火灼。一阵甫毕。一阵继之。更番转厕。逾时方得离厕。所泻俱清水盈器。白脂上浮。药粥及蔬菜。俱不化而出。甚至梦中大遗。了不收摄。诸医或云停滞。或云受暑。或云中寒。百药杂投。竟如沃石。约月余。大肉尽脱。束手待毙。予往诊之。脉洪大且数。知其为火热所生病。用川黄连三钱。白芍五钱。茯苓、扁豆、石斛、车前各三钱。橘红二钱。炙甘草一钱。煎成。将井水澄冷。加童便一杯。药甫入喉。恍如饮薄荷汁。隐隐沁入心脾。腹中别成一清凉世界。遂卧达旦。洞泻顿止。连服三剂。大便已实。前泄时药粥等物。凡温者下咽。腹中遂觉气升。即欲大解。一切俱以冷进方快。至是觉恶心畏冷。旋易以温。始相安。余曰。此火退之征也。前方加人参二钱五分。黄耆三钱。莲肉四十粒。红曲一钱五分。升麻五分。黄连减半。五六剂后。去升麻。又服三十余剂。泻已久止。而脾气困顿。不知饥饱。且稍饮茶汤。觉肠满急胀。如欲寸裂。余曰。大泻之后。是下多亡阴也。法宜用补。倘此时轻听盲师。以香燥取快暂时。元气受伤。必致变成膨胀而不救矣。为定丸方。熟地黄八两。萸肉、山药、人参、黄耆各五两。牛膝、五味子、白芍各六两。炙甘草一两。紫河车二具。蜜丸。空心饥时各一服。而日令进前煎方。敛之相信甚力。坚守二方。服几三年。脾胃始知饥而嗜食。四体亦渐丰矣。其病初平后。予劝其绝欲年余。敛之因出妾。得尽发家人阴谋。乃知向之暴泻。由中巴豆毒。本草中巴豆毒者。黄连冷水解之。余方恰与暗合。向使如俗医所疑停滞受寒中暑法治之。何啻千里。即信为是火。而时师所投黄连。不过七八分至钱许止矣。况一月之泻。未有不疑为虚寒者。敢用黄连至四钱乎。始知察脉施治。贵在神而明之也。", "3447": "孙一奎治溧水令君吴涌澜夫人。每五更倒饱。必泻一次。腹常作胀。间亦痛。脉两手寸关洪滑。两尺沉伏。孙曰。此肠胃中有食积痰饮也。乃与总管丸三钱。生姜汤送下。大便虽行。不甚顺利。又以神授香连丸和之。外用滑石、甘草、木香、枳壳、山楂、陈皮、白芍、酒连。调理而安。", "3448": "吴九宜每早晨腹痛泄泻者半年。粪色青。腹膨朜。人皆认为脾肾泄也。为灸关元三十壮。服补脾肾之药。皆不效。自亦知医。谓其尺寸俱无脉。惟两关沉滑。大以为忧。恐泻久而六脉将绝也。东宿诊之。曰君无忧。此中焦食积痰泄也。积胶于中。故尺寸脉隐伏不见。法当下去其积。诸公用补。谬矣。渠谓敢下耶。孙曰。何伤。素问云。有故无殒。亦无殒也。若不乘时。久则元气愈弱。再下难矣。以丹溪保和丸二钱。加备急丸三粒。五更服之。巳刻下稠积半桶。胀痛随愈。次日六脉齐见。再以东垣木香化滞丸调理而安。", "3449": "喻嘉言治陈彦质下利证。因旧患肠风下血。近三十年。体肥身健。不以为意。一冬忽然下血数斗。盖谋虑忧郁。过伤肝脾耳。延至春月。血尽而下尘水。水尽而去肠垢。纳食不化。直出如箭。肛脱三五寸。昼夜下利二十余行。面色浮肿。唇焦口干鼻煤。咸云不治。喻独以为有五可治。乃曰。若果阴血脱尽。当目盲无所视。今双眸尚炯。是所脱者。下焦之阴。而上焦之阴犹存也。一也。若果阳气脱尽。当魄汗淋漓。目前无非鬼像。今汗出不过偶有。而见鬼亦止二次。是所脱者。脾中之阳。而他脏之阳犹存也。二也。胃中尚能容谷些少。未显呕吐哕逆之证。则相连脏腑。未至交绝。三也。夜间虽艰于睡。然交睫时亦多。更不见有发热之候。四也。脉已虚软无力。而激之间亦鼓指。是禀受原丰。不易摧朽。五也。但脾脏大伤。阳陷入阴。故大股热气从肛门泄出。如火之烙。则阳气去绝不远耳。生死大关。全于脾中之阳气复与不复定之。阳气渐复。则食可渐化。而肛亦渐收。泄亦渐止矣。用药惟参、术之无陂。复气即寓生血。祗嫌才入胃中。即从肠出。乃先以人参汤调赤石脂末服之。稍安。次以人参、白术、赤石脂、禹余粮为丸。服之全愈。", "3450": "少司马李萍槎。食饮素约。三日始更一衣。偶因大便后。寒热发作有时。颇似外感。其实内伤。非感也。缘素艰大便。努挣伤气。故便出则阴乘于阳而寒。顷之少定。则阳复胜阴而热也。若果外感之寒热。何必大便后始然耶。医者先治外感不应。谓为湿热。而用滑利之药驱导之。致向来燥结者。转变肠澼。便出急如箭。肛门热如烙。又用滑石、木通、苓、泻等。冀分利小水以止泄。不知阴虚。自致泉竭。小便从何得来。于是食入不能停留。即从下注。将肠中之垢。暗行驱下、其臭甚腥。色白如脓。虽大服人参。而下空反致上壅。胸膈不舒。喉间顽痰窒塞。口燥咽干。彻夜不寐。一切食物。惟味薄质轻者。胃中始爱而受之。久久阴从泻伤。阳从汗伤。两寸脉浮而空。阳气越于上也。关尺脉微而细。阴气越于下也。阴阳不相维。附势趋不返矣。议用四君子汤为补脾胃之正药。去茯苓以其淡渗恐伤阴也。加山茱萸以收肝气之散。五味子以收肾气之散。宣木瓜以收胃气之散。白芍药以收脾气及脏气之散。合之参、术之补。甘草之缓。再佐升麻之升。俾元气下者上而上者下。团聚于中不散。斯脉不至上盛。腹不至雷鸣。污不至淋漓。肛不至火热。庶饮食可加。便泄渐止。是收气之散。为吃紧关头。故取四味重复。藉其专力。又须大剂药料煎浓膏。调余粮、赤石脂二末频服。缓咽为佳。古云。下焦有病人难会。须用余粮赤石脂。盖肠胃之空。非二味不填。肠垢已去。非二味不复其黏著之性。又况误以石之滑者伤之。必以石之涩者救之。尤有同气相求之义耶。", "3451": "罗谦甫治博儿赤马刺。因猎得兔以火炙食过多。抵暮困倦。渴饮潼乳斗余。是夜腹胀如鼓。疼痛闷乱。吐泻不得。躁扰欲死。其脉气口大二倍于人迎。右关尤有力。盖炙肉干燥。多食以致发渴。畅饮潼乳。肉得湿而胀滂。肠胃俱填塞。无更虚更实传化之理。内经云。阴气者。静则神藏。躁则消亡。饮食自倍。肠胃乃伤。今因饮食太过。使阴气躁乱。神不能藏。死在旦夕矣。若非峻急之剂。岂能斩关夺门。遂以备急丸十粒。分二次服。又与无忧散五钱。须臾大吐大下。约去二斗余。腹中渐空快。次日以粥饮调理而愈。", "3452": "茶商李。富人也。啖马肉过伤。腹胀。医以大黄巴豆治之。转剧。抱一翁项彦章后至诊之。寸口脉促。而两尺将绝。彦章曰。胸有新邪。故脉促。宜引之上达。今反夺之。误矣。饮以涌剂。且置李中座。使人环旋。顿吐宿肉。仍进神芎丸大下之。病去。众咸服。", "3453": "孙东宿治大宗伯董浔老。年六十七。向有脾胃疾。暑月以过啖瓜果而胸膈胀痛。诊其脉。寸关弦紧。观其色。神藏气固。考其所服药。不过二陈平胃加查、芽等。不知此伤于瓜果。寒湿淫胜也。经云。寒淫所胜。治以辛温。而瓜果非麝香肉桂不能消。前方所以无效耳。乃用高良姜、香附各一两。肉桂五钱。麝香一钱。为末。每服二钱。酒调下之。两三日。则胸膈宽而知饿矣。", "3454": "龚云林治一人。腊月赌食羊肉数斤。被羊肉冷油冻住。堵塞在胸膈不下。胀闷欲死。诸医掣肘。龚见其六脉俱有。用黄酒一大坛。温热。入大缸内。令患人坐于中。众手轻轻乱拍胸腹背心。令二人吹其耳。又将热烧酒灌之。次服万亿丸。得吐泻而愈。", "3455": "石顽治幼科汪五符。夏月伤食。呕吐。发热颅胀。自利黄水。遍体肌肉。扪之如刺。六脉模糊。指下寻之。似有如无。足胫不温。自认阴寒而服五积散一服。其热愈炽。昏卧不省。第三日。自利不止。时常谵语。至夜尤甚。乃舅叶阳生以为伤暑。而与香薷饮。遂头面污出如蒸。喘促不宁。足冷下逆。歙医程郊倩以其证大热而脉息模糊。按之殊不可得。以为阳欲脱亡之候。欲猛进人参、附子。云间沈明生以为阴证断无汗出如蒸之理。脉虽虚而证大热。当用人参白虎。争持未决。取证于石顽。诊其六脉。虽皆涩弱模糊。而心下按之大痛。舌上灰刺如芒。乃食填中宫。不能鼓运其脉。往往多此。当与凉膈散下之。诸医正欲借此脱手。听其用药。一下而神思大清。脉息顿起。当知伤食之脉。虽当气口滑盛。若屡伤不已。每致涩数模糊。乃脾不消运之兆也。此证设非下夺而与参附助其壮热。顷刻立毙。可不详慎而妄为施治乎。", "3456": "叶新宇停食感冒。而两寸关皆涩数模糊。两尺皆沉弦。而按之益坚。虽其人尚能行走。而脉少冲和。此必向有陈气在少腹。询之。果患寒疝数年。因缓辞不便用药。是夜即腹暴满而逝。门人问曰。叶子偶抱小恙。何以知其必死而辞之。曰。凡人胃满则肠虚。肠满则胃虚。更实更虚。其气乃居。今胸有食而腹有积。上下俱困。能保其不交攻为患乎。当知厥疝入腹。脚气冲心等疾。皆是阴邪搏结。郁积既久。则挟阴火之势而上升。若胸中阳气有权。则阴邪仍归阴位而止。今胸中先为宿食填塞。腹中陈气。不逆则已。逆则上下俱满。正气无容身之地。往往有暴绝之虞。所以不便用药。实未知其即死也。故凡诊六部中。病脉有不相应处。即当审其有无宿病。不可轻忽以招诽谤也。", "3457": "又治一少妇。年十九。因不如意。遂膈满。不食累月。惫甚。不能起坐。巳午间发热面赤。酉戌方退。夜间小便数而点滴。月经极少。脉沉涩短小。重取皆有。此气不遂而郁于胃口。内有瘀血。却因病久。元气已虚。中宫又以勉强进食。郁而生痰。法宜补泻兼施。以参、术各二钱。茯苓、橘皮各一钱。红花六分。食前煎服。少顷。与神佑丸减轻粉牵牛为细丸。如芝麻大。唾津咽十五丸。日夜二药各四服。次日食进。三日热退而愈。", "3458": "震按不食之因甚多。而因郁因怒。其大端也。所载三案。可以为式。至因他病而不食者。不在此例。夫人身以胃气为本。经年累月。粥饭全废。似无不死者。然予曾见两家闺女。皆十余岁。皆无病。渐渐厌恶粥饭。每日略啖菱栗枣橘落花生芝麻薄脆豆腐干之类。或饮酒一二杯。或腐浆数口而止。其父母甚忧之。予视其形色不变。起居如常。六脉匀平。乃许以无事。亦不处方。后皆婚嫁生子。盖谷肉蔬果。均以养生。去谷而犹存三项。与绝食者原不同耳。但女与男又别有说。阳动阴静。阳开阴阁。若童男不食粥饭。究非所宜。", "3459": "罗谦甫治书吏高士谦。年逾四十。至元戊寅七月间。因官事出外劳役。又因过饮。午后大发热而渴。冰水不能解。早晨稍轻减。服药不效。罗诊其脉弦数。金匮要略云。疟脉自弦。弦数者多热。内经云。瘅疟者。肺素有热。气盛于身。厥逆上冲。中气实而不外泄。因有所用力。腠理开。风寒舍于皮肤之内。分肉之间而发。发则阳气盛而不衰。则病矣。其气不及于阴。故但热而不寒。气内藏于心。而外舍于分肉之间。令人消烁肌肉。故名曰瘅疟。士谦远行劳役。又暑气有伤。酒热相搏。午后时助。故大热而渴。如在甑中。先以柴胡饮子下之。后以白虎加栀子汤。数服而愈。", "3460": "丹溪治一妇人久痢。因哭子变疟。医与四兽饮之类。一日五六作。汗如雨不止。凡两月。朱诊之。脉微数。食少疲甚。盖痢后无阴。悲哀伤气。又进湿热之药。助起旺火。正气愈虚。今汗已大出。无邪可治。阴虚阳散。死在旦夕。岂小剂之所能补。遂用参、术各二两。白芍一两。黄耆五钱。炙甘草二钱。浓煎频服。两日。寒热即止而愈。", "3461": "又治一少妇。身小味厚。痎疟月余。间日发于申酉。头痛身热。寒多。口干。喜饮极热辣汤。脉伏。面色惨晦。作实热痰治之。以十枣汤为末。粥丸如黍米大。津咽十粒。日三次。令淡饮食。半月后大汗而愈。", "3462": "一富人年壮病疟。自卯时寒至酉时方热。至寅初方休。一日一夜。止苏一时。因思必为入房感寒所致。及问之。九月暴寒。夜半有盗。急起。不著中衣。当时足即冷。十日后疟作。盖足阳明与冲脉合宗筋会于气街。入房太甚。则足阳明冲脉之气皆夺于所用。其寒乘虚入中。舍于二经所过胫所会足胕上。于是二经之阳气益衰。不能渗荣其经络。故病作卒不能休。乃用人参、白术大补。附子行经。加散寒之药以取汗。数日不得汗。病如前。因悟足胕道远。药力难及。用苍术、川芎、桃枝煎汤。以器盛之。浸足至膝。一食顷。以前所服药饮之。其汗通身大出。病即已。", "3463": "一老人患疟嗽半载。脉之。两手尺数而有力。色稍枯。余料之。必服四兽饮等剂。中焦湿热下流。伏结于肾。以致心火上连于肺。故疟嗽俱作。用参、术、升、柴、黄芩、黄连。二三日与黄柏丸服之。两夜梦交通。来告急。余语之曰。此肾中热解。乃从前阴精窍而散走。故为是梦。勿忧。次日疟嗽顿止。", "3464": "浦江洪宅一妇。病疟三日一发。食甚少。经不行已三月。丹溪诊之。两手脉俱无。时当腊月。议作虚寒治。以四物加附子、吴茱、神曲为丸。心疑误。次早再诊。见其梳妆无异平时。言语行步。并无怠倦。知果误矣。乃曰。经不行者。非无血也。为痰所碍而不行也。无脉者。非气血衰而脉绝。乃积痰生热。结伏其脉而不见尔。以三花神佑丸与之。旬日后。食稍进。脉渐出。但带微弦。疟尚未愈。因谓胃气既全。春深经血自旺。便自可愈。不必服药。教以淡滋味节饮食之法。半月而疟愈。经亦行。", "3465": "薛立斋治一产妇。患疟久不愈。百病蜂起。其脉或洪大。或微细。或弦紧。或沉伏。难以名状。用六君子加炮姜。二十余剂。脉证稍得。又用参术煎膏。佐以归脾汤。百余剂而痊。", "3466": "汪石山治一人。形瘦色脆。年三十余。八月因劳病疟。寒少热多。自汗体倦。头痛胸痞。略咳而渴。恶食。大便或秘或溏。发于寅申巳亥夜。医欲从丹溪用血药引出阳分治之。汪诊其脉濡弱。近快稍弦。日观色察脉。乃属气血两虚。疟已深入厥阴矣。专用血药。不免损胃又损肺。淹延岁月。恐久疟成劳也。盖嗽渴固宜养阴。自汗恶食胸痞。岂血药所能独理。古人用药立例。指引迷途耳。因例达变。须后人推广之。遂以补中益气汤加川芎、黄柏、枳实、神曲、麦冬。倍用参、耆、术煎服。三十余帖。诸证稍除。疟犹未止。乃证之曰。今当冬气沉潜。疟气亦因之以沉潜。难使浮达。况冬月汗孔宜乎闭固。而疟则必须汗解。当此蛰藏之令。安得违天时以汗之乎。且以参、术、枳实、陈皮、归身、黄芩丸服。胃气既壮。来年二月。疟当随春气而发泄矣。果如期而安。", "3467": "一人年三十。六月因劳取凉梦遗。遂觉恶寒。连日惨惨不爽。三日后。头痛躁闷。家人诊之。惊曰。脉绝矣。议作阴证。欲进附子汤。未沃。请汪治。汪曰。阴证无头痛。今病如是。恐风暑乘虚入于阴分。故脉犬耳。非绝也。若进附子汤。误则莫解。姑待以观其变。然后议药。次日未末申初。果病寒少热多。头痛躁渴。痞闷呕食。自汗。大便或泻或结。脉皆濡小而驶。脾部兼弦。此非寻常祛疟燥烈之剂所能治。遂用清暑益气汤去苍术、升麻。加柴胡、知母、厚朴、川芎。以人参加作二钱。黄耆钱半。白术、当归各一钱。煎服二十余帖而愈。", "3468": "震按脉证有可疑处。猛浪投以重药。脱有所误。噬脐何及。姑待以观其变。真老医之老到处也。", "3469": "一人年二十余。八月。因劳病疟。汪诊之。脉数。皆六至而无力。曰。古人云。形瘦色黑者。气实血虚也。间日发于午后。亦血分之病也。以色脉论之。当从血治。但今汗多。乃阳虚表失所卫。消谷善饥。乃胃虚火乘其土。俱为气虚之证。仲景法有凭证不凭脉者。兹当凭证作气虚治。以参、耆各三钱。白术、白芍、麦冬各一钱。归身、生地、甘草各七分。知母、陈皮各五分。煎服二十余帖而安。", "3470": "震阅石山治疟案二十二条。所载脉象。或曰浮濡无力。或曰浮而欲绝。或曰濡小而缓。或曰浮大而濡。或曰濡弱近驶稍弦。或曰数而无力。是分明参耆术草之病。无甚疑难。少分寒热。自易取效。故仅登三条。余可类推。", "3471": "李士材治相国沈铭缜。患疟。吐蛔。闷不思食。六脉沉细。李曰。疟伤太阴。中寒蛔动也。用理中汤加乌梅三个。黄连五分。四剂后。胸中豁然。寒热亦减。蛔亦不吐。去黄连。加黄耆二钱。生姜五钱。五剂而疟止。", "3472": "僧慎柔治淮安客。年三旬外。季夏患瘅疟。但热不寒。连日发于午后。热躁谵语。至次日天明才退。数日后。忽腹痛。昼夜无间。勺水不进。呼号欲绝。遇疟发时即厥去。医治不效。求慎柔诊之。脉弦细而濡。乃谓弦细为虚为暑。而濡为湿。盖暑邪成疟。湿热乘虚内陷而腹痛。用酒炒白芍一两。炙甘草一钱五分。水煎。调下天水散五钱。服后腹痛如失。次日疟亦不发。", "3473": "高果哉治张习可。五月间。受微雨及风冷。逐患三疟。疟发于暮。热甚于夜。至九月中。诊得六脉虚数。此阴虚而暑入阴分。最难治。当先升举其阳。用生地、当归、川芎、白芍、炙草、知母、干姜、干葛、升麻、柴胡、姜、枣煎服。四剂后。加首乌、人参。又定丸方。首乌四两。生地三两。参、术、当归、龟版、猪苓、知母、黄芩、山楂各二两。柴胡一两六钱。牛膝一两五钱。干姜、穿山甲各一两。甘草五钱。活鳖一个。入砂仁末二两。煮取鳖肉。同药捣匀烘干。其骨亦炙为末。加入荷叶汤法丸。服完全愈。", "3474": "喻嘉言治袁继明。素有房劳内伤。偶因小感。自煎姜葱汤表汗。因而发热三日。变成疟疾。喻诊其脉。豁大空虚。且寒不成寒。热不成热。气急神扬。知为元阳衰脱之候。因谓其父曰。令郎光景。窃虑来日疟至。大汗不止。难于救药。今晚宜用人参二两。煎浓汤。预服防危。渠父不以为意。次日五鼓时。病者便觉精神恍惚。觉得参至。疟已先发矣。喻甚彷徨。恐以人参补住疟邪。虽救急。无益也。只得姑俟疟热稍退。方与服之。服时已汗出沾濡。顷之。果然大汗不止。昏不知人。口流白沫。灌药难入。直至日暮。白沫转从大孔遗出。喻喜曰。白沫下行。可无恐矣。但内虚肠滑。独参不能胜任。急以附子理中汤。连进四小剂。人事方苏。能言。但对面谈事不清。门外有探病客至。渠忽先知。家人惊以为祟。喻曰。此正神魂之离舍耳。吾以独参及附子理中驷马之力追之。尚在半返未返之界。以故能知宅外之事。再与前药二剂而安。", "3475": "张路玉治张怡泉。年七十五。居恒常服参、附、鹿角胶等阳药。秋间病疟。误用常山止截药一剂。遂致人事不省。六脉止歇。按之则二至一止。举指则三五至一止。惟在寒热之际诊之则不止歇。热退则止歇如前。此真气衰微。不能贯通于脉。所以止歇不前。在寒热之时。邪气冲激经脉。所以反得开通。此虚中伏邪之象。乃用常山一钱酒拌。同人参五钱焙干。去常山。但用人参以助胸中大气而祛逐之。当知因常山伤犯中气而变剧。故仍用常山为向导耳。连进二服。遂得安寝。但寒热不止。脉如前。乃日进人参一两。分二次进。并与稀糜助其胃气。数日寒热渐减。脉微续而安。", "3476": "震按此条论歇止脉最有见。其用常山法。与杨介以冰煎药。皆为巧作。然寒热不止。脉止如前。巧且无益。惟日进人参一两。不兼他药。真大巧若拙也。", "3477": "震按内经论瘅疟。纯是实热证。故推其未病。则曰中气实而不外泄。溯其受病。则曰用力出汗。风寒舍于皮肤分肉。究其病发。则曰阳气盛而不衰。经文虽不言脉。谅脉之洪实有力可知也。此条系瘅疟。故谵语遗尿不死。然八旬之外有此证。死者甚多。勿轻以此案作榜样也。", "3478": "中翰金淳还乃郎。八月间患疟。发于辰戌丑未。而子午卯酉每增小寒热。直至初夏。石顽诊其六脉如丝。面青唇白。乃与六君子加桂、附。四服不应。每服加人参至一两。桂、附各三钱。又四服而辰戌丑未之寒热顿止。子午卯酉之寒热更甚。此中土有权而邪并至阴也。仍与前药四服。而色荣。食进寒热悉除。后与独参汤送八味丸。调理而安。", "3479": "飞畴治沈子嘉平。向来每至夏间。脐一著扇风则腹痛。且不时作泻。六脉但微数。无他异。此肾脏本寒。闭藏不密。易于招风也。下寒则虚火上僭。故脉数耳。曾与六味去泽泻。加肉桂、肉果、五味、白蒺。作丸服。因是脐不畏风。脾胃亦实。明秋患疟。医用白虎、竹叶、石膏等。疟寒甚而不甚热。面青足冷。脉亦弦细而数。用八味地黄。三倍桂附作汤。更以四君合保丸。早暮间进。二日疟止。调理而愈。", "3480": "震按腹之部位。当脐属肾。脐著扇风即痛泻。自宜温肾。但不以六脉带数而畏投温药。可取也。蒺藜一味。加得更好。至如治疟。不以脉之细数而不倍加桂、附。更可取也。", "3481": "马元仪治工部那公太夫人。年七十外。恶寒发热如疟。迁延月余。神昏食少。舌胎兼刺。小腹肿痛。上连胸胁。诸医莫效。马诊两手脉弦涩而结。尺中倍弱。知为内伤重而外感轻。得之劳倦且郁。病在肝脾两经也。劳则伤脾。郁能伤肝。肝脾气血两伤。邪气独从内结。治之者责其实而忘其虚。以致加重。今须大顾元气。微兼治邪。始克有济。用人参三钱。扶其元气。桂枝七分。散其虚邪。黄连、肉桂。使上下交通。炮姜、半夏。以开痞散结。一剂而脉渐透。再剂而神气颇清。右关转见滑实。元仪方以脉有转机为庆。前医疑热药太过。欲投白虎汤。马曰。此津液元气两亏之证。服药后两脉透起。神气清爽。业已养正而透邪。但今津液尚枯。虚热内甚。当进以滋燥清热之品。其与阳明实热证可峻行肃杀者。奚啻天壤也。仍用人参为主。加生首乌以养津润燥。佐黄连、枳实、杏仁、半曲。以除热散结而化痰。三日。大便已行。后加芦根汁、蔗浆。甘寒养阴之品。六七日。右关脉和。舌刺亦平。微见利下。前医又疑寒药所致。欲用理中。马曰。数日以来。纯用甘寒清燥之剂。三四日而始大便通。六七日而始舌刺平。今津液方回。虽见利下。继必自止。何得喜功生事。且今胸腹间尚有结气未释。正宜疏畅肝脾。以通和气道。且气道通和。虽不治利。利亦自止。所谓一举而两得也。仍用人参、半、曲、广皮、茯苓、郁金、佛手等剂。六七日后。气和而利止。周身浮肿。下体不能转移。此久病后元气大亏。脾虚不运。如盗去而舍空之比。复与大剂参、术、苓、草、附、桂。至二十剂而肿平。乃得全愈。", "3482": "震按印机草中所载寒热痞闷中州结痛者。每用人参、桂枝、肉桂、黄连、炮姜、半夏。或合枳、朴。或合枳、桔。继见燥象。即以人参、生首乌、栝蒌实、蔗浆、梨汁、芦根汁等。或合黄连、知母。或合橘、半。若见虚寒象。多用理中加桂汤。或白通加人尿猪胆汁汤。其用人参有一二两至五六两作一剂者。亦可谓大手笔。但雷同之案太多。故此集所选独少。又见其治身热胸满喘嗽多痰者。必重用栝蒌实、紫菀。佐以半曲、贝母、杏仁、苏子、枳、结。或合柴胡、秦艽。或合前胡、干葛。大约相同。惟治汪生咳嗽梦泄。面白畏风。两寸浮大而虚。关尺虚小。用玉屏风散。多加人参。为不同。及治朱千秩喘嗽。寒热自汗。食减身重。自夏至秋。脉象浮涩。亦用玉屏风加贝、杏、苏子、桔梗。云一剂而脉症和。此不敢信也。继以六味加参。颇妥当。至如栝蒌实合炮姜及桂枝、生首乌者。不一而足。虽其运用纯熟。未免数见不鲜。因并舍之。", "3483": "〔附〕嘉善一张姓少年。春间患寒热如疟。始用发散。继用养阴。已愈矣。越数日。疟又作。且兼白浊不止。用小柴加首乌、生地、丹皮、萆薢等。不应。又数日。寒热渐重。不能起坐。口渴烦躁。舌赤唇焦。一老医用白虎汤。而热益甚。发晕。昏沉几死。热气冲开二三尺。两目赤肿。目眵胶闭。舌红且干。唇焦面赤。两足如烙。惟大便泄泻。脉虚而软。余友沈尧封兄用人参二钱。熟附子三钱。茯苓五钱。白芍一钱五分。一剂而热少定。遂连服十余日。惟以牡蛎、牛膝、枸杞、生地出入加减。粥进热退。诸证去其六七矣。忽然腹痛大作。连泻二三十次。烦渴又作。懊𢙐迷闷不安。举家骇泣。沈曰。无恐。此久积之寒饮。因脾得参附之力以运动之。欲乃大下也。复用附子五钱。干姜二钱。苓、芍、炙草。数剂而安。又用参术平补全愈。", "3484": "震选疟疾诸案虽不多。然皆精深高妙。可以启发后学。若浅近之法未载。略为补之。古云。日作者轻。间日者重。此不可拘。若日作而寒热之时短。势又不甚。则诚轻。倘势甚。而时又长。反不如间日者尚有休息之一日也。何可云轻。惟疟发渐早为易痊。渐晏为未止。乃一定之局。间有不一定者。如发渐早而热退之时如旧。则其寒热加长矣。愈长则正气愈虚而加剧。不得引内经其气上行九日出于缺盆之中为证也。又有发渐晏而热退之时如旧。则其寒热渐短矣。愈短则邪气愈衰而自止。不得引昔贤自阳之阴者难愈为证也。隔二日曰三阴疟。较诸疟为最重。有二三年未愈者。亦有二三月即愈者。只看其寒热之轻重短长。以辨其病之浅深。然三阴疟无骤死之理。反不比日作与间日者。有骤死之人也。此皆就予生平所验而言之。大抵疟疾因风寒者。多初起无汗。必该发散。羌、苏、防、葛之类。若有汗。则用桂枝、白芍。兼见热象。则桂枝柴胡各半汤。深秋初冬。寒重无汗。口不渴。脉不数者。麻黄汤小剂用之。兼见热象。则加石膏。即越婢法也。表证而挟里证。有痰食者。加入朴、半、麦芽之类。向有无痰不成疟。无食不成疟二说。未可全废。疟疾因于暑者。必热多寒少。有汗口渴。桂枝白虎汤、竹叶石膏汤酌用。暑兼湿。则苍术白虎汤、桂苓甘露饮酌用。以上皆疟疾之表证药。而疟发每多呕逆痞闷。又须以草果、知母、藿香、枳、朴、白蔻、姜汁、干姜、竹茹、芦根等。审其寒热加入。亦统属疟疾之实证药也。若素虚人。或病后疮后产后。不可一例论。古云。无汗要有汗。散邪为主。有汗要无汗。扶正为先。汗之一端。尚且严为分别。岂以虚证虚脉而可虚其虚乎。补中益气汤、人参养营汤、参茸归桂饮、理中、八味、真武等方。择其脉证相合者用之。盖温补温通补脾补肾。方义微别耳。惟是大虚必挟寒。昔肾谓治久疟用补者。少加附子。其效如神。故虚疟之用桂、附。与三阴疟之用丁香。俱有奇功可据也。然或虚疟不见寒证。却有热象。脉弦数或洪数者。势难投以温药。则甘寒生津如蔗浆、秋露水、梨藕汁。壮水制火如二地、二冬、阿胶。以及生脉散、何人饮。又堪供我驱策矣。复有虚实参半之热证。则小柴胡原方、人参白虎汤、半夏泻心汤、黄连汤。可以奏功。若虚实参半而寒者。较易治。毋庸再赘。但寒热二字。全在凭之以脉。纵使热多。甚至但热无寒而脉细软者。当以虚治。不得轻用白虎。寒多。甚至但寒无热而脉洪实者。当以热治。不得便用姜、桂。此妙诀也。夜疟皆云邪入血分。当用血药以提其邪。说固可通。景岳归柴饮、鼓峰香红饮二方俱佳。然初起在夜。嗣后不早不晏。始终发于夜者是也。设趱前渐定日昃。缩后已至日出。皆不得谓之夜疟矣。禁法与截法不同。禁是外为镇厌。其法甚多。效者亦多。即祝由之一类。然轻者效。重者不效。三疟全不效。比之打仗。掠其残兵耳。设用药中綮。何借此乎。截是服药以截止。常山截三疟有奇效。截止后须谨慎调摄。否则复发增重。用砒者亦然。然砒必大吐。恐至伤人。其间日与日作者。原不须截。欲截则露姜饮最佳。虚加人参尤妙。缪仲淳谓疟由于暑。暑得露而解也。予考古法。要冷饮以存露性。今怕冷饮。隔汤炖温犹可。若著火则露性全失矣。临证指南以秋露煎药。非也。外有胆汁二姜丸、蒜烧醨、草果蒸参、常山炒参诸方。以及景岳云。小柴胡汤加常山二钱。截疟如神。皆在乎人之善用耳。疟母必用鳖甲煎丸。丸中除去人参为大谬。或以参汤送之。汤力已过。丸力才行。譬如悍卒无良将统驭。步伐岂能整齐。又按此丸偏于寒削。若阳虚者不宜。惟仲淳疟母丸重用参、桂为宜。三疟虽属三阴。亦只要辨明寒热虚实。而应以温凉补泻。若谓阳经轻浅之方。治之无益。必以仲景治三阴之法为根蒂。似属高谈。实门外汉也。总之。医者多读书。多阅历。病者能调摄。能谨慎。斯四难并。二美合矣。", "3485": "叶先生名仪。尝与丹溪俱从白云许先生学。其记病云。岁癸酉秋八月。予病滞下。痛作。绝不食饮。既而困惫不能起床。乃以衽席及荐。阙其中而听其自下焉。时朱彦修氏客城中。以友生之好。日过视予。饮予药。但日服而病日增。朋游哗然议之。彦修弗顾也。浃旬病益甚。痰窒咽如絮。呻吟亘昼夜。私自虞。与二子诀。二子哭。道路相传谓予死矣。彦修闻之曰。吁。此必传者之妄也。翌日天甫明。来视予脉。煮小承气汤饮予。药下咽。觉所苦者自上下。凡一再行。意冷然。越日遂进粥。渐愈。朋游因问彦修治法。答曰。前诊气口脉虚。形虽实而面黄稍白。此由平素与人接言多。多言者中气虚。又其人务竟已事。恒失之饿而伤于饱。伤于饱其流为积。积之久。为此证。夫滞下之病。谓宜去其旧而新是图。而我顾投以参、术、陈皮、芍药等补剂十余帖。安得不日以剧。然非浃旬之补。岂能当此两帖承气哉。故先补完胃气之伤。而后去其积。则一旦霍然矣。众乃敛衽而服。", "3486": "震按此与许学士治伤寒太阳病因尺脉不应用黄耆建中同法。彼先补而后散。此先补而后攻。但二公把握得定。故嫌疑不避。设麻黄承气之用于后者不能愈病。则人之归咎难辞。而医之用药无路矣。", "3487": "一人患痢久不愈。脉沉细弦促。右为甚。日夜数十行。下清涕。有紫黑血丝。食少。丹溪曰。此瘀血痢也。凡饱食后疾走。或极力叫号殴跌。多受疼痛。大怒不泄。补塞太过。火酒火肉。皆致此病。此人以非罪受责故也。乃以乳香、没药、桃仁、滑石。佐以木香、槟榔、大黄。神曲糊丸。米饮下百丸。再服。大下秽物而愈。", "3488": "一老人年七十。面白。脉弦数。独胃脉沉滑。因饮白酒作痢。下淡水脓血。腹痛。小便不利。里急后重。丹溪以参、术为君。甘草、滑石、槟榔、木香、苍术为佐使。煎汤下保和丸三十粒。次日前证俱减。惟小便未利。以六一散服之而愈。", "3489": "丹溪从叔。年逾五十。夏间患滞下病。腹微痛。所下褐色。后重食减。时有微热。察其脉皆弦而涩。似数而稍长。喜不甚浮大。两手相等。视其神气大减。朱曰。此忧虑所致。心血亏。脾气弱耳。以参、术为君。归身、陈皮为臣。川芎、白芍、茯苓为佐使。时暄热甚。少加黄连。两月而安。此等证。若因其逼迫而用峻剂。误矣。", "3490": "梅长官年三十余。奉养厚者。夏秋息痢。腹大痛。或令单煮干姜。与一帖。痛定。少顷又作。又与之。又定。八日服干姜三斤。左脉弦而稍大。似数。右脉弦而大稍减。亦似数。重取似紧。朱曰。此必醉饱后食寒凉太多。当作虚寒治之。因服干姜多。以四物去地黄。加参、术、陈皮、酒红花、茯苓、桃仁煎。入姜汁饮之。一月而安。", "3491": "丹溪云。赵立道年近五十。质弱而多怒。七月炎暑。大饥索饭。其家不能急具。因大怒。两日后。得滞下病。口渴。自以冷水调生蜜饮之。甚快。滞下亦渐缓。如此者五七日。召予视。脉稍大不数。遂令止蜜水。渴时但煎人参白术汤。调益元散与之。滞下又渐收。七八日后觉倦甚。发呃。予知其久下而阴虚也。令守前药。然滞下尚未止。又以炼蜜饮之。如此者三日。呃犹未止。众皆尤药之未当。将用姜、附。予曰。补药效迟。附子非补阴者。服之必死。众曰。冷水饮多。得无寒乎。予曰。炎暑如此。饮凉非寒。勿多疑。待药力到。当自止。又四日而呃与滞下皆止。", "3492": "陈宅仁年近七十。厚味人也。有久喘病而作止不常。新秋患痢。食大减。五七日。呕逆发呃。丹溪视脉皆大豁。众以为难。朱曰。形瘦者尚可为。以黄柏炒燥研末。陈米饭丸。小豌豆大。每服三十丸。人参、白术、茯苓三味煎浓汤下。连服三剂即愈。切不可下丁香等热药。", "3493": "壶仙翁治一命妇。病滞下。腹痛腰胀。翁诊其脉。曰。此气血滞郁而然。当调血和气。则痢自止。所以知其病者。切其脉。沉而滞。循其尺。尺涩。沉滞则气不和。涩则精血伤。病由积郁而强食。故气血俱伤。乃投以四物、五苓、木香。痛少止。倍当归。经通而滞下已。", "3494": "汪石山云。予兄年逾六十。色苍素健。九月患滞下。予适出外。自用利药三帖。病减。延至十月。后重未除。滞下未止。诊之。脉皆濡散。颇缓。初用人参二钱。归、芍、黄芩、升麻、桃仁各一钱。槟榔五分。煎服。后重已除。再减桃仁、槟榔。加白术一钱五分。滞下亦定。惟粪门深入寸许。近后尾闾穴傍。内生一核如梅。颇觉胀痛不爽。予曰。此因努责气血下滞于此。耐烦数日。脓溃自安。果如所言。后服槐角丸。痔痛如故。仍用人参三钱。归、耆、升麻等剂而愈。", "3495": "一妇年逾五十。病痢半载余。医用四物凉血之剂。及香连丸。愈增。脘腹痛甚。里急后重。下痢频并。嗳气。亦或咳嗽。遍身烦热。石山诊之。脉皆细弱而数。曰。此肠胃下久而虚也。医用寒凉。愈助降下之令。病何由安。经曰。下者举之。虚者补之。其治此病之法欤。遂以参、术为君。苓、芍为臣。陈皮、甘草、升麻为佐使。研末。每服二钱。清米饮调下。日二次。或三次。遂安。", "3496": "吴茭山治一妇。长夏患痢。痛而急迫。其下黄黑色。诸医以薷苓汤。倍用枳壳、黄连。其患愈剧。吴诊之。两尺脉紧而涩。知寒伤荣也。问其病由。乃行经之时。因渴饮冷水一碗。遂得此证。盖血被冷水所凝。瘀血归于大肠。热气所以坠下。遂用桃仁承气汤。加马鞭草、延胡索。一服。次早下黑血升许。痛止脏清。次用调脾活血之剂。遂痊。此乃经凝作痢。不可不察也。", "3497": "震按此条先用薷、连。其患愈剧。再合以尺脉之紧涩。明知为寒伤营矣。乃不用温药佐消瘀。仍以承气加逐瘀药。岂因后重急迫。宜下不宜温耶。", "3498": "薛立斋治少宗伯顾东江。停食患痢。腹痛下坠。或用疏导之剂。两足浮肿。食少倦怠。烦热作渴。脉洪数。按之微细。以六君子。加姜、桂各二钱。吴茱萸、五味子各一钱。煎成冷饮。即睡。觉而诸证顿减。此假热而治以假寒也。", "3499": "立斋又云。先母年八十。仲夏患痢。腹痛。作呕不食。热渴引汤。手按腹痛稍止。脉鼓指而有力。真气虚而邪气实也。急用人参五钱。白术、茯苓各三钱。陈皮、升麻、附子、炙草各一钱。服之睡。觉索食。脉证顿退。再剂而安。此取证不取脉也。凡暴病毋论其脉。当从其证。时石阁老太夫人。其年岁脉证皆同。彼乃专治其痢。遂致不起。", "3500": "震按立斋云。暴病毋论其脉。当从其证。想先生只从虚寒之证为据。若证现实热。而脉微细。或按之空豁者。又从脉不从证矣。多阅薛氏医案自知。", "3501": "张三锡治一人。病痢。发寒热。左脉浮紧。右脉滑大。乃内伤挟外感也。先用败毒散加姜葱一服。表证悉退。但中脘作胀闷。后重不已。以平胃散加枳壳、木香、槟榔、山楂。又二服。胀闷移于小腹。投木香槟榔丸三钱。下黏硬物而愈。", "3502": "又一妇病痢。自投承气汤二服。不愈。张诊之。左脉浮而带弦。右三部俱沉。关脉略滑。必郁闷中食物所致。病家云。素恼怒。遂以厚朴、苍术、香附、抚芎舒郁。山楂、槟、橘、木香理气。芍药调中。三服愈。龚云林治大司寇刘春冈。年近古稀。患痢。脓血腹痛。诸医弗效。龚诊六脉微数。此肥甘太过。内有积热。当服酒蒸大黄一两清利之。司寇曰。吾衰老。恐不胜。惟滋补平和之剂可也。龚再四宽释。遂服之。逾日而愈。", "3503": "又治通府何竹峰赤白痢。昼夜无度。遍身瘙痒。心中烦躁。龚诊六脉大数。人迎偏盛。此风邪热毒也。以人参败毒散。去人参加荆、防、黄连。二服即愈。而六脉仍前大数。龚曰。数则烦心。大为病进。将来必有痰喘之患。不起。后逾月。果如其言。", "3504": "震按此二条一以年近古稀。而用大黄至一两。不可为训。一以病退脉不退。决其变证。诚有先见之明。然何不用补阴药。以治其脉之数大也。", "3505": "李士材治屯院孙潇湘夫人。下痢四十日。口干发热。饮食不进。腹中胀闷。完谷不化。尚有谓其邪热不杀谷者。计服香、连、枳、朴、豆蔻等。三十余剂。绝谷五日。命在须臾。李诊之。脉大而数。按之豁然。询得腹痛而喜手按。小便清利。此火衰不能生土。内真寒而外假热也。亟煎附子理中汤。冷服一剂而痛止。六剂而热退食进。兼服八味丸。二十余日而安。", "3506": "兵尊张䌹庵秋间患痢。凡香、连、枳、朴等剂。用之两月而病不衰。士材诊之。滑而有力。失下之故也。用香、连、归、芍、陈皮、枳壳。加大黄三钱。下秽物颇多。诊其脉尚有力。仍用前方。出积滞如鱼肠者约数碗。调理十余日而痊。", "3507": "震按此案比前案更高。其得手处总在于能审脉也。", "3508": "祝茹穹治部堂祖泽远。夏得痢疾。昼夜七八十次。疼不可言。便出仅血脓数点。饮食不进。已月余。瘦弱已极。诸医咸虑之。以为此毒气熏蒸清道。致胃口遏塞。闻食即吐。凶兆也。祝视之。面热身凉。脉大而滑。夫病久则邪气日盛。当身热。而今身凉。身凉不宜脉大。而今脉大。细视胃脉。乍大乍小。茹穹豁然曰。此非噤口证也。因感寒不发散。故胃以上有积寒。冒暑不清凉。故胃以下有积热。宜以温药开胃口之寒。以凉药通谷道之热。久病虚甚。补之。四五日即可愈耳。闻者大惊。乃以吴茱萸制黄连。姜汁炒黄芩。煨干姜、白豆蔻各一钱。陈壁土炒白术八分。南枣包煨人参八分。煎服。是夜即减病之半。五六服而神气渐旺。饮食渐进矣。", "3509": "孙东宿治温巽桥子妇。发热恶心。小腹痛。原为怒后进食。因而成积。左脚酸痛。已十日矣。有南浔女科。始作瘟疫治。呕哕益加。又作疟治。粒米不能进。变为滞下。里急后重。一日夜三十余行。女科技穷。乃曰。病犯逆矣。下痢身凉者生。身热者死。脉沉细者生。洪大者死。今身热脉大而又噤口。何可为哉。因请东宿诊。两手皆滑大。尺部尤搏指。孙曰。证非逆。误认为疫为疟治者逆也。虽多日不食。而尺脉搏指。经云。在下者引而竭之。法从下。可生也。即与当归龙荟丸一钱五分。服下。去稠积半盆。痛减大半。不食已十四日。至此始进粥一瓯。但胸膈仍饱闷。不如饥。又与红六神丸二钱。胸膈舒而小腹软。惟两胯痛。小腹觉冷。用热砖熨之。子户中白物绵绵下。小水短涩。改用五苓散加白芷、小茴香、白鸡冠花、柴胡服之。至夜满腹作疼。亟以五灵脂醋炒为末。酒糊丸。白汤送下三钱。通宵安寝。次日精神清健。饮食大进。小水通利矣。而独白物仍下。再用香附炒黑存性。枯矾各一两。面糊丸。空心。益母草煎汤送下二钱。不终剂而白物无。病全愈矣。", "3510": "孙东宿治侄从明。夏初。由客邸患痢。昼夜三四十度。里急后重。口渴汗出。胸膈焦辣。手心热。腹微痛。小水少。干哕呕恶。其脉左沉弦。右滑数。孙以病人原禀薄弱。今远归。途次多劳。不敢疏下。姑以胃风汤加黄连。与二帖不效。腹稍加胀。渠嘱孙曰。古云无积不成痢。今积势胶固。切勿用补。无以体素弱为疑。孙即改用黄芩芍药汤。三剂无进退。乃曰。此证实实虚虚。热热寒寒。殊属难治。且谷食禁口不入。干哕可虑。须再觅高明参酌。无知病人信任益坚。孙因图欲先开胃口。使新谷食将宿秽压出。或补或攻。视缓急以为方略。乃背嘱伊侄曰。令伯非人参不可。幸且勿露。俾予得以尽技。因仿丹溪法。用人参、黄连各二钱。煎浓。细细呷之。哕恶果止。连与两日。觉胸腹胀。即以保和丸应之。觉小水不利。又以清六丸应之。里急后重。以参、术加芩、连、木香、槟榔、滑石、桃仁应之。人参皆背加。病人不知也。每诊脉。必曰疾已渐平。幸勿遽补。恐废前功。讵知人参已服十日。计二两许矣。此后脉仅四至。软而无力。忆丹溪云。虚回而痢自止。又云。气虚甚者。非附子不能行参耆。乃以胃风汤加耆、附、炮姜。四剂而血止。后重亦止。再用菟丝、萸肉、故纸、杜仲、参、附。全安。", "3511": "慎柔和尚云。余四弟年二十七。于甲辰闰九月。患痢。先来取药。付以芍药汤一帖。香连丸二服。数日不止。反增心口如刀割。脐腹痛。肛门痛。声撼四邻。自分必死。因往乡视之。昼夜不得卧。日下红血一桶。痛不可忍。发热流汗。不食。脉之六部俱豁大。浮中沉无力。四至。虽痛虽发热。脉无力。已虚寒矣。古人云。脱血益气。此证正宜。遂用六君子一帖。次投异功散。加升麻三分。木香五分。炒干姜五分。一剂。去后觉可。痛亦少减。至五更。腹痛如前。予曰。此药力尽也。急煎一剂与之。比前更可。痛又减七八。即酣睡至日中方醒。曰。不甚好过。予曰。此药止能支持一觉。再煎与之。遂安寝至晓。心腹痛止。后重亦轻。再服前剂而愈。二日后。吃鸡肉。仍前腹痛肛肿。下秽不止。又三日。病势笃极。予复往诊之。脉三至余。浮取无。沉按之则大。脾命脉微。与补中益气汤。不应。此虚脱之甚。加御米壳一钱。亦不应。下如洞泄。流汗发躁。尺脉渐欲收短。危甚。急于补中益气汤加人参二钱。服之。下咽觉愦。此正气欲复。邪气欲退也。顷之。精神顿增。痢稍缓。恐再作。又一剂。下注昏愦热躁诸证渐缓。脉有神。短脉退。思古人云。久泻久痢。汤剂不如丸散。即合参苓白术散与服。觉减可。至下午复躁。予亦无奈。再诊左尺洪如火射状。此阴虚火动之象。与加减八味丸五六十丸。精神觉爽。顷之。又下八九十丸。睡至天明。病去十七。方信立斋谓加减八味丸治水涸之证。即令朝暮服此丸。间以参苓白术散。渐愈。复劳。觉小便痛。想动色欲之故。服逍遥散、麦冬、五味子而平。", "3512": "高果哉治丁清惠公。予告在籍。患痢。里急后重。白积兼鲜血。昼夜十余次。饮食减少。两尺脉似有似无。两寸关弦数。小便短少。众医皆以望八高龄。当凭尺脉而投温补。高独谓禀赋素厚。宜从寸关而用清理。遂进黄芩、白芍、厚朴、槟榔、陈皮、甘草、阿胶、滑石、槐花、木香。四五剂全愈。", "3513": "喻嘉言治周信川。年七十三岁。平素体坚。不觉其老。秋月病痢。久而不愈。至冬月成休息痢。昼夜十余行。面目浮肿。肌肤晦黑。喻诊其脉。沉数有力。谓曰。此阳邪陷入于阴之证也。当用逆流挽舟法。提其邪转从表出。则趋下之势止而病可愈。于是以人参败毒散本方煎好。用厚被围椅上坐定。置火其下。更以布条卷成鹅蛋状。置椅褥上殿定肛门。使内气不得下走。方以前药热服。良久又进前药。遂觉皮间津津微润。再溉以滚汤。教令努力忍便。不得移身。如此约二时之久。病者心躁畏热。忍不可忍。始令连被带汗。卧于床上。是晚止下痢二次。以后改用补中益气汤。不旬日而全愈。", "3514": "朱孔阳年二十五岁。形瘦。素安逸。夏月因构讼。奔走日中。致痢。昼夜一二百次。不能起床。但饮水而不进食。其痛甚厉。肛门如火烙。扬手掷足。躁扰无奈。喻诊其脉弦紧劲急。不为指挠。谓曰。此证一团毒火。蕴结在肠胃之内。其势如焚。救焚须在顷刻。若二三日外。肠胃朽腐矣。于是以大黄四两。黄连、甘草各二两。入大沙锅内煎。随滚随服。服下。人事稍宁片刻。少顷。仍前躁扰。一昼夜服至二十余次。大黄俱已煎化。黄连、甘草俱煎至无汁。次日病者再求前药。喻又诊之。见脉势和柔。知病可愈。但用急法。不用急药。改以生地、麦冬各四两。另研生汁。而以花粉、丹皮、赤芍、甘草各一两。煎成和汁。大碗咽之。以其来势暴烈。一身津液从之奔竭。待下痢止。然后生津养血。则枯槁一时难回。令脉势既减。则火邪俱退。不治痢而痢自止。岂可泥润滞之药而不急用乎。服后。痢渐止。粥饮渐进。调理旬余。方能消谷。", "3515": "陈汝明病痢。发热如蒸。昏沉不食。重不可言。至第三日。危急将绝。乃诣嘉言。其脉数大空虚。尺脉倍加洪盛。喻曰。此两病而凑于一时之证也。内有湿热。与时令外热相合。欲成痢症。尚不自觉。又犯房劳而为骤寒所乘。以致发热身重。不食昏沉。皆属少阴肾经外感。少阴受邪。原要下利清白。此因肠中湿热已蒸成猪肝鱼脑之形。故色虽变而下利则同也。再用痢疾门药一剂。即刻不救矣。遂忙以麻黄附子细辛汤一剂。与之表散外邪。得汗后。热即微减。再以附子理中汤。连进二剂。热退身轻能食。改用连理汤丸服。至旬日全安。", "3516": "张路玉治春榜陈颖雍。暑月自都门归。抵家即患痢疾。半月以来。攻克不效。遂噤口。粒米不入。且因在京久食煤火。肩背发毒。不赤不疼。陷伏不起。发呃神昏。势日濒危。内外医科。互相推委。乃延石顽诊之。六脉弦细欲绝。面有戴阳之色。所下瘀晦如烂鱼肠脑。证虽危殆。幸脉无旺气。气无喘促。体无躁扰。可进温补。但得补而痈肿焮发。便可无虞。遂疏保元汤。每服人参三钱。生耆二钱。甘草、肉桂各一钱。伏龙肝汤代水煎服。一服粥饮稍进。二服后重稍轻。三服痈毒贲起。另延疡科敷治其外。确守前方。又十余服而安。前后未尝更易一味也。", "3517": "又阅儒门事亲载一男子恶痢。痛不可忍。忽见水浸甜瓜。连皮食数枚。脓血皆已。而本草却有贫人多食甜瓜。深秋下痢难治之戒。可见下痢无正形。治痢亦无正形也。刘宗厚曰。夏月食冰水瓜果太过。致令脾胃伤冷。血不行于四肢八脉。渗入肠胃间而下痢。是诚至言。然其咎在太过耳。若偶食之。未必为害。惟饱餐饭肉浓鲜之后。即偶食亦不可。盖凡空腹吃井水西瓜。颇能消涤无形之暑气。使从小便出。倘胃中先有食物填实在内。而加以生冷。则脾不运行。必成积滞矣。予少年时。赴一友人招。其家长幼俱患痢疾。窃骇之。意此岂杨子建所谓疫毒痢耶。何独疫于其家也。及设中饭。荤腥海鲜盛备。而以冷酒偏斟。独予不饮。反以为怪。予曰。君家之所以致痢者。由于此也。盘中诸品。正藉极热之好酒以疏通之。则胃气方畅。乃与冷酒为伍。古语为得冷则凝。如油黏碗。虽洗难脱。滞气泣血。痢能免乎。其家豁然省悟改焉。迄今二十余年无痢疾。又有人曰。都中土著士民。夏月饭上置冰一片。凡鱼肉多悬井内。瓜果安放冰边。却不见其患痢。不知北方生长者。禀气刚厚。且食煤火之食。内有蕴热。故尔相宜。若吴地人。断不可效也。", "3518": "孙见心治一人秋间下痢脓血。昼夜百余次。里急后重。前医见脉歇止。谓因积滞所致。用槟、朴、青皮、枳壳、木香等。孙诊之。脉洪弱而数。或一二至。或三四至。或五六至。辄一止。曰。毒及少阴矣。当急顾其阳明。用生熟地各一两。归、芍、丹皮、黄连各三钱。甘草五分。群疑阴药太重。恐饱闷增剧。然服二帖。次数尚频。急重已除。脉之洪数亦减。至数相续。仍用前方。病去大半。又次日。去生地、黄连。加参、术、茯苓、山药。饮食大进。午后弦脉亦减。而至数复有止状。或骇曰。病退而脉复变。防其加重。孙曰。无妨也。歇至者。即古代结促之俗名耳。若冲气中绝。脏脉自见者危。今此证歇至。本以毒盛拥遏隧道。阴精不承。故一二至。或三四至。或五六至而至也。经曰。数动一代者。病在阳之脉也。泄及便脓血。今予去阴药之过甚。进阳药太骤。中脏得补。则木土和而胃气安。故饮食进而毒尚未尽者。亦随壮气而旺。故复有止状也。于方中仍加生地、黄连。即平矣。果验。", "3519": "震按此条与西昌治朱孔阳案相似。而此以生地换大黄。则因脉之促止。与弦动不为指挠者。有别也。此从炙甘草汤得之。然幸洪数而歇止。若细涩无神而歇止。断不可治。亦必其人身不发热。尚能饮食而腹痛者。观案中云。饮食大进可见矣。总之。痢以能食为吉。腹痛亦吉。不能食而不腹痛者大不吉。", "3520": "〔附〕嘉善一妪常便血。时发时止。至五旬外。夏月便鲜血。里急后重。时或不禁。脉软不数。用五苓建中转甚。因向宜凉血药。仍用四物加槐、榆、楂、曲。亦无效。叶天士先生以生苍术、生厚朴、炒陈皮、炙甘草、鸡内金、砂仁壳、丁香柄丸服。全愈。又有一童子患久痢。叶亦用此方全愈。人不解其故。震读徐春甫医统。因见此方名醉乡玉屑。治小儿食瓜果致痢久不愈者。乃服先生之典博也。至如临证指南所载。都属古人常用方法。惟以温药下之。乃江氏类案所未有。而附子、大黄为君。参入苓、朴及草果、益智、木香、大茴等。谅系对证择加。总不外举散温通之义。又有用大黄、芩、连、肉桂、丹皮、归、芍者。是从芍药汤化出。有用人参、芩、连、干姜、生姜、枳实者。是从泻心汤化出。以及二妙散加地榆、苓、泻。白头翁汤加黄芩、白芍。亦世俗所通晓。至如附子粳米汤、脾肾双补丸、理阴煎、四神丸、桃花汤、余粮丸。或养阴。或发表。均非创立。独有肾气丸之炒焦。及姚颐真之用大剂苁蓉为创立。但炒焦者不过熟地炭、桂、附炭之侣。苁蓉配参、归、姜、附。即以温药下之。化为温药滑之耳。然同温药则可。同阴药则不可。予曾试之矣。其痢久伤肾。下焦沉坠。刚药不效者。用人参、鹿茸、大茴、茯、菟、故纸。痢久伤阴。唇燥舌干。胃气又弱。戒投阴腻柔药者。用人参、炙草、茯神、炒麦冬、炒白芍、炒乌梅肉。一系温柔补固。一系酸甘化阴。仍是率由旧章也。至谓治痢大法。无过通塞二义。乃先生略举大端。比如读云汉之诗。勿以辞害志可矣。", "3521": "罗谦甫于至元己亥。治廉台王千户。年四十五。领兵镇涟水。此地卑湿。因劳役过度。饮食失节。至深秋。疟痢并作。月余不愈。饮食全减。形羸瘦。仲冬舆疾归。罗诊得脉弦而微如蛛丝。身体沉重。手足寒逆。时复麻木。皮肤痂疥如疠之状。无力以动。心腹痞满。呕逆不止。此皆寒湿为病。久淹。真气衰弱。形气不足。病气亦不足。针经云。阴阳皆不足。针所不为。灸之则宜。内经曰。损者益之。劳者温之。十剂曰。补可去弱。先以理中汤加附子。温养脾胃。散寒湿。涩可去脱。养脏汤加附子。固肠胃。止泻痢。仍灸诸穴以并除之。经云。府会太仓。即中脘也。先灸五七壮。以温养脾胃之气。进美饮食。次灸气海百壮。生发元气以荣百脉。充实肌肉。复灸足三里。胃之合也。三七壮。引阳气下交阴分。亦助胃气。后灸阳辅二七壮。接阳气。令足胫温暖。散清湿之邪。迨月余。病气去。神完如初。", "3522": "滑伯仁治一妇。年五十余。患疟。寒热涌呕。中满而痛。下利不食。殊困顿。医药不效。伯仁诊其脉。沉而迟。曰。是积暑与食。伏痰在中。当下之。或曰。人疲倦若是。且下利不食。焉可下。方拟进参、附。滑曰。脉虽沉迟。按之有力。虽利而后重下迫。不下则积不能去。病必不已。乃以消滞丸。微得通利。觉少快。明日再服之。宿积肠垢尽去。向午即思食。旋以姜、橘、参、苓。淡渗和平饮子调之。旬余乃复。", "3523": "震按此条疟痢兼呕。竟以消导药愈。较之专以发散药愈者。可作两大局。但须著眼中满而痛。脉沉有力。知其病在里不在表也。", "3524": "南浔董宗伯。门下有马厨者。七月初旬病。病二十余日。愈剧。其证大发寒热。寒至不惮入灶。热至不惮下井。痢兼红白。日夜八十余行。腹痛恶心。神气倦甚。时孙东宿在宗伯家。问向来医者言脉何如。有客曰脉不吉。下痢脉洪大者死。细微者生。今洪大。逆也。东宿曰。痢固忌洪大。寒热亦非细微所宜。其中必有故。试往视之。见面色微红。汗淋淋下。因究病所由起。渠谓过客众。厨门燥热。食瓜果菱藕过多。晚又过饮御内。而寝于楼檐之下。次日即寒热腹痛。因而下痢。病情虽述。治法难谐。因沉思之。告宗伯曰。偶有一得。乃背水阵也。人参、白术、石膏、滑石各五钱。知母、炮姜各三钱。大附子、炙甘草各二钱。作一大剂煎之。服后倘得一睡。则阴阳始和。和则汗可敛。而寒热呕恶可止也。至夜。痢减其半。汗吐全无。脉亦敛矣。再用参、术、白芍、石膏、滑石各三钱。炮姜、肉桂、知母各二钱。炙甘草、附子各一钱。服后疟止。痢又减半。饮食渐进。神气渐转。改用酒炒白芍五钱。去石膏、附子。余药各减一钱。三剂全愈。客问曰。公寒热均投。此为何证。而剂何名耶。东宿曰。此滑公所谓混沌汤也。经云。夏伤于暑。秋必疟痢。白虎汤、益元散。皆解暑之剂。瓜果寒凉。伤其中气。酒后御色。损其下元。故合附子理中汤温中补下。若以寒热均用为疑。则仲景附子泻心汤、大黄、芩、连与附子并用。此何说哉。盖假对假。真对真也。", "3525": "孙公原案又云。实者邪气实也。故以白虎汤、益元散应之。虚者正气虚也。故以理中汤应之。今考此方分两。纯是少阴经阴盛格阳治法。若果有暑邪。岂五钱之石膏、滑石。能与大剂参、术、姜、附并取其效哉。案载脉洪大。不载有力无力。亦不载口渴与否。舌胎及小便若何。何以放胆用温补。若痢兼红白。腹痛恶心。面红汗多。寒热大作诸证。确系暑邪为病。温补殊属反背。若果能取效。则的系虚寒。其细微之知母、石膏。正如白通加人尿猪胆汁汤耳。不得牵扯暑邪二字以混之也。然病经二十余日。虚寒证早已亡阳矣。能待孙公用药耶。", "3526": "又治金达泉疟兼痢。日夜四十余度。小腹痛甚。每登厕。汗出如雨。下迫后重。小水涩痛。头疼口渴。下午发热。天明始退。左脉浮弦而数。右软弱。中部稍滑。此内伤饮食。外感风邪所致。先与柴苓汤一剂。小便即清。不痛。疟发时寒多热少。晚与人参败毒散。去羌、独。加葛根、防风、桂枝、白芍。次日头痛痢疾俱减。夜才起三次。改与补中益气汤加酒芩、桂枝、白芍。其夜疟止。但微热。再改胃风汤。人参、白术、桂皮各二钱。白芍四钱。酒炒芩连各一钱。当归、茯苓、川芎佐之。炮姜、地榆为使。服后寒热殄迹。夜起一次是粪。前方减去桂枝。再三剂而巾栉出户矣。", "3527": "震按此案用方妥当出色。可以效法。若王金坛治邑令刘蓉川深秋患疟而洞泄不止。欲先去其一为快。乃用局方双解饮子。一服而二病俱愈。更觉神妙。是得法于澹寮所谓用药多一冷一热半熟半生分利阴阳之义也。然窃思疟痢并作。初起者专用发散如羌、防、柴、葛等。佐以赤苓、神曲。见血痢参入归身、川芎。右关脉大可加厚朴。使在腑之邪提并于经而外解。最为捷法。倘或不应。审其挟热挟寒而用表里分散之法。热者去羌、防。加芩、连、香薷、滑石。寒者去柴、葛。加桂枝、干姜。若热甚者多实证。风药不宜矣。大柴胡汤加黄连、滑石。寒甚者多虚证。风药当戒矣。真武汤加桂枝、人参。此仍表里双解之法。至如人参败毒散、补中益气汤。虚证之表药也。理中汤、八味丸。虚证之里药也。表证之虚而挟热者。小柴胡汤。里证之虚而挟热者。连理汤。表证之虚而挟寒者。麻黄附子细辛汤。里证之实而挟寒者。温脾汤。以此诸法。将脉证配合审用。无不手到成功。如此条右脉耎弱为虚。疟发寒多热少亦为虚。故第二剂即用人参。但汗出如雨。而于败毒散去羌、独。加桂枝、白芍是矣。又加葛根、防风。尚觉太过。", "3528": "壶仙翁治乡进士许崇志病呃逆。医以雄黄烟熏其鼻。倏然目暗。热剧甚。翁诊之曰。此由恼怒伤肝。肝气上逆而呃。经云。木郁达之。投以涌剂。更为之疏肝平气。数服而愈。所以知崇志病者。其脉左关沉而弦。右寸微而数。沉弦为郁。微数为热。郁不行。故指为怒气致呃也。", "3529": "朱丹溪治一女子。年逾笄。性躁味厚。暑月因大怒而呃逆。每作一声。则举身跳动。神昏。凡三五息一作。脉不可诊。视其形气实。以人参芦二两煎饮。大吐顽痰数碗。大汗。昏睡一日而安。", "3530": "又一老人。素厚味。有久喘病。作止不常。新秋患痢。食大减。数日呃作。脉豁大。朱以其形瘦可治。用参术汤下大补丸。至七日而安。", "3531": "虞天民治一人伤寒。前医以补药治之而发呃逆。十日后。邀虞诊之。其脉长而实大。此阳明内实。误补所致。与大承气下之。热退而呃止。", "3532": "震按此条呃已十日。脉长实大。犹易辨也。前条之脉豁大。而用参、术。何又以黄柏佐之。岂因其形瘦素厚味为有郁热耶。至如女子因怒至呃。脉不可诊。止凭形气之实以施治。何不用他涌剂。而用参芦至二两。又岂因其脉未得。而用涌剂中之补剂。为稳著耶。", "3533": "又一人得伤寒证。七日热退而呃大作。举家彷徨。虞诊其脉。皆沉细无力。人倦甚。以补中益气汤大剂加姜、附。一日三帖。兼灸气海乳根。当日呃止。脉亦充而平安。", "3534": "吕元膺治余姚州守郭文煜呃十余日。医以丁、附等疗之。益甚。吕切其脉。阳明大而长。右口之阳数而躁。乃曰。此由胃热致呃。又以热药助其热。误矣。用竹茹汤。旋愈。", "3535": "震按上条之宜用温补及灸法。人所共能。次条之服热药而益甚。合以脉之长大数躁。宜用大剂白虎。有下证者。宜佐以承气。若竹茹汤。恐不济事。", "3536": "丹溪治一妇。病不知人。稍苏即号叫数四而复昏。朱诊之。肝脉弦数且滑。曰。此怒火所为。盖得之怒而饮酒也。诘之。以不得于夫。每夜必引满自酌解其怀。朱治之以流痰降火之剂。而加香附以散肝分之郁。立愈。", "3537": "戴原礼治方氏子妇。疟后多汗。呼媵人易衣不至。怒形于色。遂昏厥若死状。灌以苏合香丸而苏。自后闻人步之重。鸡犬之声。辄厥逆如初。原礼曰。脉虚甚。重取则散。是谓汗多亡阳。以参、耆日补之。其惊渐减。至浃旬而安。", "3538": "汪石山治一人年逾七十。忽病瞀昧。但其目系渐急。即合眼昏懵。如瞌睡者。头面有所触。皆不避。少顷而苏。问之。曰不知也。一日或发二三次。医作风治。病转剧。汪诊其脉结止。苏则如常。但浮虚耳。曰。此虚病也。盖病发而脉结者。血少气劣耳。苏则气血流通。心志皆得所养。故脉又如常也。遂以十全大补汤去桂。加麦冬、陈皮而安。三子皆庠生。时欲应试而惧。注曰。三年之内。可保无恙。越此非予之所知也。果验。", "3539": "江篁南治一妇。忽如人将冰水泼之。则手足厥冷。不知人。少顷发热则渐省。一日二三次。江诊六脉俱微。若有若无。欲绝非绝。此气虚极之证也。用人参三钱。陈皮一钱。枳壳二分。人参渐加。服至六两。而愈。", "3540": "孙东宿治徐中宇之妇。汗出如雨。昏昏愦愦。两手无所著落。胸要人足踹之不少放。少放即昏愦益甚。气促不能以息。少近风则呕恶晕厥。与九龙镇心丹一丸。服下即稍定。少间则又发。始知胸喉中有物作梗而痛。汤水难入。即药仅能吞一口。多则弗能咽下。乃以苏合香丸与之。晕厥寻止。心痛始萌。昨日六脉俱伏。今早六部俱见。惟左寸短涩。知其痛为瘀血也。用延胡、桃仁、丹参、丹皮、青皮、当归、香附。其夜仍晕厥一次。由其痛极而然。再与前方加乌梅、桂枝、赤芍、贝母、人参。而痛减大半。乃自云心虚有热。头眩。加山栀仁。居常多梦交之证。近更甚。以其心虚故也。人参、丹参、归、芍、枣仁、酒连、香附、贝母、石斛。调理全安。", "3541": "喻嘉言治黄我兼令正。痰厥。频发不痊。有欲用涌剂及下法者。喻曰。惊痰堵塞窍隧。昏迷不过片向耳。设以涌药投之。痰才一动。人即晕去。探之指不能入。咽之气不能下。药势与病势相扼。转致连日不苏。将若之何。丹溪云。惧吐者。宜消息下之。是或一道也。但窍隧之痰。岂能搜导下行。徒伤脾气。痰愈窒塞。此法亦不可用。今三部脉象虚软无力。邪盛正衰。不易开散。用药贵有节次矩矱。盖惊痰之来始于肝胆。冬月木气归根。不敢攻治。但当理脾清肺。使脾能健运。肺能肃降。痰乃下行耳。今四末肿麻。气壅已甚。须药饵与饮食相参。白饭香蔬苦茗。便为佳珍。不但厚味当禁。即粥亦不宜食。以粥饮之。结为痰饮。易易耳。不但杂食当禁。即饮食亦宜少减。以脾气不用以消谷。转用之消痰。较药力更捷耳。其辛辣酒脯及煎爆日曝之物。俱能伤肺。并不宜食。依此调理。至春月木旺。才用四君子汤加龙胆草、芦荟、代赭石、黄连、青黛等药。为丸服之。痰迷之症。果获全瘳。后遂不发。", "3542": "震按子和论痉。最为妙解。而法惟汗下。终嫌粗厉。如丹溪治少年痘后发痉。腹痛冷汗。痛定汗止。时止时作。脉弦紧而急。如真弦状。知其极勤苦。劳倦伤血。疮后血愈虚。风寒乘虚而入。法当养血散风。以芎、归、芍、青皮、钩藤、陈皮、本草。再佐桂枝、黄连、木香。加红花少许。此正治也。予乡文选司莘之金公劳倦而伤寒发斑。斑出迎风遽阴。遂发痉。手足搐掉。不时跳跃。浑身震动。神欲晕去。予用牛蒡、天虫、土贝、荆、防、钩藤。不应。其脉细而弦劲带数。乃用虎、膝、归、芍、生地、钩钩、秦艽、荆芥、桑枝。痉跳减半。未能全愈。因思病属厥阴。当寒热并用。乃以桂枝、羚羊角为君。仍佐血药。加竹沥、姜汁。一服而愈。此实效颦于丹溪。幸不至学步于邯郸耳。", "3543": "一人身热至六七日。医用地黄汤。遂致身体强硬。六脉沉伏。目定口呆。气喘不能吸入。周慎斋曰。此能呼不能吸。病在中焦实也。中焦实。脾不运耳。方用远志、白茯神各一钱。附子四分。去白广皮六钱。磁石、苏梗各一钱五分。沉香二分。一帖身和。六帖而安。盖脾者为胃行其津液者也。脾不运则胃阳不行于肌肉。肌肉无阳。所以强耳。醒其脾。则胃阳通而身和矣。", "3544": "罗谦甫治赵运使夫人。年近六十。三月间。病脐腹冷痛。相引胁下。痛不可忍。反复闷乱。不得安卧。乃先灸中庭穴。在膻中下寸六分陷者中。任脉气所发。灸五壮或二七三七壮。次以当归四逆汤。归尾七分。桂、附、茴香、柴胡各五分。芍药四分。茯苓、延胡、川楝各三分。泽泻一分。数服愈。", "3545": "又治火儿赤怜歹疝气。脐腹阵痛。搐撮不可忍。腰曲不能伸。热物熨之稍缓。脉得沉小而急。难经云。任之为病。男子内结七疝。皆积寒于小肠间所致也。非大热之剂。则不能愈。遂以沉香、附子、川乌、炮姜、良姜、茴香、肉桂、吴茱萸各一两。醋丸。米饮汤下。名沉香桂附丸。一日二服。又间以天台乌药散。每服一钱。热酒泡生姜汤下。服此二药。旬日良愈。", "3546": "滑伯仁治一妇。寒疝。自脐下上至心。皆胀满攻痛。而胁疼尤甚。呕吐烦懑。不进饮食。脉两手沉结不调。此由寒在下焦。宜亟攻其下。毋攻其上。为灸章门气海中脘。服延胡、桂、椒。佐以茴、木诸香。茯苓、青皮等。十日一服温利丸药。聚而散之也。果效。", "3547": "震按首案虽云任脉为病。然脐腹痛引胁下。实兼厥阴。其灸中庭穴以治任脉。当归四逆汤则治肝病也。次案脉证俱寒。自当纯用大热之剂。但脉沉小而急。与沉微细软不同。是寒实。非寒虚。妙在天台乌药散以逐其寒积也。只服一钱而送药引子更佳。第三案痛且胀。脉又沉结不调。亦是积寒实证。而不进饮食。元气亦虚。故灸法妙极。艾火能逐寒能壮气也。佐以温通药。间以温利药。步伐整齐。洵为必胜之师。所谓温利丸药。想即天台乌药散。以方中木香、茴香、乌药、良姜、青皮各五钱。槟榔两个。巴豆七十粒同川楝十个。以麸炒。去豆用楝。取其性而弃其质。如用火攻仍不延燎也。", "3548": "震按此条向因名医类案脱落两行。以致文理不贯。看不明白。今从原本全录。始服其议论大有妙理。其法注神使气至下焦走肋下。较之子和用药以吐者。险夷殊别矣。及读景岳全书。记其尊人寿峰公吐法。每于五鼓睡醒时。徐徐咽气。因作嗳以提之。气有不充。则咽气为嗳。随咽随提。痰涎必随气而至。吐后或至唇肿咽痛。但以凉水一二口漱咽解之。吐毕。早膳悉屏五味。但用淡粥一二碗。以养胃中清气。自四旬之外。绝不用酒。每月行吐法二三次。六旬之外。则一月或半月必吐一次。用此法四十余年。愈老愈健。若遇疾病。无论表里虚实。绝不服药。但一行吐法。无不即日尽却。寿至八旬之外。犹能登山。及灯下抄录古书读之。不禁跃然。彼子和之独圣茶调。逊此和平多矣。然窃思阳明胃脉。下行为顺。若吐则上逆。频吐理当损寿。何反益寿。殊未敢信。", "3549": "汪石山治一人。年二十余。因水中久立过劳。病疝痛。痛时腹中有磊块。起落如滚浪。其痛尤甚。诊之脉皆细弦而缓。按之似涩。曰。此血病也。考之方书。疝有七。皆不宜下。所治多是温散之药。以气言也。兹宜变法治之。乃用小承气加桃仁下之。其痛如失。三日复作。比前加甚。脉之轻则弦大。重则散涩。思之莫得其说。问曾食何物。曰。食鸡蛋二枚而已。曰。得之矣。令以指探吐。出令尽。痛解矣。", "3550": "一儿六岁。阴囊胀大如盏。茎皮光肿如泡。一医为之渗湿行气。不效。汪诊视。脉皆濡缓。曰。脉缓无力者。气虚也。经云。膀胱者。津液之府。气化则能出焉。气虚不足。无能运化而使之出矣。宜升阳补气可也。遂以补中益气汤。去当归、柴胡。加茯苓、牛膝。二帖囊皱肿消。三帖全愈。", "3551": "震按此二条乃凭脉断病之正法。前案以弦涩断为瘀血。后案以濡缓断为气虚。应手取效。皆得力于指下也。前案变温散为寒下。后案去归、柴。加苓、膝。是其学问高处。但前案三日复作。而归咎于鸡蛋二枚。恐未确也。其痛解之功。又在吐法耳。", "3552": "祠部黄新阳公夙有脾泄。便血。脚痛。六脉滑数。曾用酒煮黄连为君。佐以参、术等。而泄血止。越年余。患狐疝。昼出囊中。夜卧入腹。不时疼痛。吴心所投以虎潜丸、还少丹而愈。此始为热中。久为寒中。药物寒热迥别而俱效。久病从虚治也。", "3553": "卢不远治陈孟杼之父。六月自山东邸中受寒起。尚淹淹未王也。至次年二月。忽小腹与腰急痛。即令人紧挽外肾。稍松便欲死。卢曰。此小肠府病也。经云。小肠病者。腰脊控睪而痛。乃以羌活入太阳小肠。佐黄柏、茯苓、肉桂等。并刮委中穴。痛立止。但足软。卢曰。病因六月伤寒。太阳有所未尽。故入府而痛作。原以寒邪郁火。仍需夏时则火力全而血脉通。邪始去也。果至五月天热。身发紫斑。有汗至足而始健。", "3554": "汪石山治萧师训。年逾五十。形肥色紫。气从脐下逆冲而上。睡卧不安。饮食少。精神倦。汪诊之。脉皆浮濡而缓。曰。气虚也。问曰。丹溪云气从脐下起者。阴火也。何谓气虚。汪曰。难执定论。丹溪又云。肥人气虚。脉缓亦气虚。今据形与脉。当作气虚论治。遂以参、耆为君。白术、白芍为臣。归身、熟地为佐。黄柏、甘、陈为使。煎服十余帖。稍安。彼以胸膈不利。陈皮加作七分。气冲上。仍守前方。月余而愈。", "3555": "震按此条仍合丹溪二说同用之。非专主气虚也。惟汪公于濡缓脉。多以参、耆加麦冬、黄柏。不加附子。想系一生得手处。至如陈皮加作七分。气即冲上。此尤气虚之显然者。前方可操券取效也。窃忆生平治气冲证。用熟地、归、杞、牛膝、紫石英、胡桃肉、坎气、青铅等药而愈者。不计其数。又有用肾气丸而愈者。用大补阴丸、三才丸而愈者。总不出丹溪之训。惟一陆姓书生。形瘦。饮食如常。别无他病。而气自脐下上冲。始仅抵胸。后渐至喉。又渐达巅顶。又渐从脑后由督脉及夹脊两傍而下。又渐至腿踝足心。仍入少腹。再复上冲。其冲甚慢。约一年而上下周到。谷食递减。肌肉愈削。共两年半而其人方死。凡温凉补泻。靡药不尝。针灸祝由。无法不试。震固不能愈之。而就医于吴门叶薛两先生。亦无寸效。此种病。恨不遇张戴人喻西昌周慎斋诸公。听其议论以开茅塞也。又按魏志华佗传。载一士大夫不快。佗曰。君病深。当破腹取。然君寿亦不过十年。病不能杀君。忍病十岁。寿俱当尽。不足故自刳裂。士大夫不耐痛痒。必欲除之。佗遂下手。所患寻瘥。十年竟死。震读此益慨然于术之疏也。设华公遇此陆生。即早知其十年后以气冲证寿当尽矣。何药之能为。", "3556": "马元仪治袁玉行。小腹厥气上冲。即吐。得饮则吐愈甚。诸药不效。马诊之。两脉虚涩。右尺独见弦急。此下焦浊气上胜。则胸中阳气不布。故饮入于胃。上壅而不下达。宜通其地道。用调胃承气汤。下宿秽甚多。继渐培中气而愈。", "3557": "震按凡病皆有虚实。勿谓气冲证皆系阴虚气虚也。故选此条。别开一例。然必是暴病或便秘。乃从右尺脉印其机耳。昔年曾与杜良一先生治下焦肾虚。上焦气冲者。杜用六味地黄汤。合五磨饮子去木香。以汁和服而效。又一新翻式样也。", "3558": "喻嘉言诊金道宾之脉。左尺和平。右尺如控弦。如贯索。上冲甚锐。喻曰。是病枝叶未有害。本实已先拨。必得之醉而使内也。曰诚有之。但已绝欲二年。服人参斤许。迄今诸无所苦。惟闭目转盼。则身非己有。恍若离魂者然。不识可治与否。喻曰。夫人生之阴阳。相抱而不脱。故阳欲上脱。阴下吸之则不脱。阴欲下脱。阳上吸之则不脱。惟大醉后大犯房劳。五脏翻覆。百脉动摇。二气乘之脱离。有顷刻殒于女身者。病之得有今日。犹幸也。但真阳不能潜藏。常欲飞腾泄越耳。治之之法有三。以涩固脱。以重镇怯。以补理虚。更佐以介类沉重下伏之物。引之潜降。使真阳复返其宅。凝然与真阴相恋。再用大封大固之法。可以收功。经云。阳者亲上者也。阴者亲下者也。故凡上脱者。妄见妄闻。有如神灵。下脱者。不见不闻。有如聋瞆。上脱者。身轻快而汗多淋漓。下脱者。身重著而肉多青紫。昔有新贵人。马上扬扬得意。未及回寓。一笑而逝者。此上脱也。又有人寝而遭魇。身如被杖。九窍出血者。此下脱也。是病始于溺情。继以纵欲。必须大夺其情。永积其精。再加千日之把特。乃不为倏然之上脱矣。", "3559": "松陵贡士吴友良。年逾古稀。头目眩晕。服补中益气汤。始用人参一钱。加至三钱。遂痞满不食。坐不得卧。三昼夜喃喃不休。石顽往候。见其面赤。进退不常。左颊聂聂𥆧动。诊其六脉皆促。或七八至一歇。或三四至一歇。询其平昔起居。云是知命之年。便绝欲自保。饮啖自强。此壮火烁阴。而兼肝风上扰之兆。与生料六味。除去茱萸。易入钩藤。大剂煎服。是夜即得酣寝。其后或加鳖甲。或加龙齿。或加枣仁。有时忘动怒火。达旦不宁。连宵不已。则以秋石汤送灵砂丹。应如桴鼓。盛夏酷暑。则以小剂生脉散代茶。后与六味全料。调理至秋而安。", "3560": "震按眩晕有实有虚。如壮盛人实痰实火脉滑大有力者。二陈、芩、栀。不恶心者。用酒制大黄二三钱。或加入。或为末茶调下。如肥白人痰多气虚脉濡大或细软者。六君加耆、附。又内经谓诸风掉眩。皆属肝木。故因于外风者。二陈加荆、防、钩藤、天麻。因于内风者。即类中之渐。宜虎、膝、牡蛎、枸杞、首乌、桑叶、菊花、生地、人参。戴复庵曰。头脑挟风。眩晕之甚。抬头则屋转。眼常黑花。如见有物飞动。或见物为两。宜大追风散。或秘旨正元散加鹿茸。不效。一味鹿茸。每服五钱。酒煎去渣。入麝少许。盖鹿之阳气钟于头。故以类相从也。此即就风之一端而有虚实之分也。若在夏月有冒暑而眩晕者。又不得概从风治。夫肝为风木之脏。故内经以眩晕专责之肝。若肾水亏少。肝枯木动。复挟相火。上踞高巅而眩晕者。近时最多。董载臣曰。妇人患此更多。宜逍遥散为主。轻则合四物。重则合六味加黄连。极有效验。他如晨晕属阳虚。昏晕属阴虚。亦辨证之大旨。未可据以为准。今所选三案。原不越乎诸法。而议论卓荦。方药巧妙。实能驾乎诸法。原本类案所载者不及也。", "3561": "罗谦甫治建康道周卿子。年二十三。至元戊寅春间。病发热肌肉消瘦。四肢困倦。嗜卧。盗汗。大便溏多。肠鸣。不思饮食。舌不知味。懒言。时来时去。约半载余。罗诊脉浮数。按之无力。正应浮脉歌云。脏中积冷营中热。欲得生津要补虚。先灸中脘。乃胃之纪也。使引清气上行。肥腠理。又灸气海。使生发元气。滋荣百脉。长养肌肉。又灸三里。乃胃之合穴。亦助胃气。撤上热使下于阴分。以甘寒之剂泻火热。佐以甘温养其中气。又食粳米羊肉之类。固其胃气。戒以慎言语。节饮食。惩忿窒欲。病日减。数月后。气得平复。逮二年。肥甚倍常。或曰。世医治虚劳病。多用苦寒之剂。君用甘寒。羊肉助发热。人皆忌之。而君反令食。何也。罗曰。内经云。火位之主。其泻以甘。藏气法时论云。心苦缓。急食酸以收之。以甘泻之。泻热补气。非甘寒不可。若以苦寒泻其土。使脾土愈虚。火邪愈甚矣。又云。形不足者。温之以气。精不足者。补之以味。劳者温之。损者益之。补可去弱。人参、羊肉之类是也。人参能补气虚。羊肉能补血虚。食羊肉何疑耶。", "3562": "丹溪治一老人。七十九岁。头目昏眩而重。手足无力。吐痰相续。左脉散大而缓。右脉缓大不及左。重按皆无力。饮食略减而微渴。大便四日始一行。医投风药。朱曰。若用风药。至春必死。此大虚证。宜大补之。以参、耆、归、芍、白术、陈皮浓煎。下连柏丸三十粒。服一年后。精力如丁年。连柏丸用姜汁炒。姜汁糊丸。", "3563": "震按脉缓大。重按无力。参、耆、术是矣。连柏丸何耶。岂以其微渴大便四日一行耶。或以脉缓大为热耶。", "3564": "又治一人。肥大苍厚。因厚味致消渴。投寒凉药。愈后。吃黄雌鸡滋补。约至千只。患膈满呕吐。医投丁、沉、附子之剂。百帖而愈。值大热中。尚恶风。怕地气。乃堆糠铺簟蔽风而处。动止呼吸言语皆不能。丹溪诊之。脉四至。浮大而虚。此内有湿痰。以多服燥热药。致气散血耗。当夏令。去当死。赖色苍厚。胃气尚在。以参、耆、术熬膏。煎淡五味子汤。入竹沥调服。三日诸证悉除。令其绝肉味。月余平复。因多啖鸡卵。患胸腹膨胀。自用二陈汤加香附、白豆蔻。其满顿除。乃令绝肉味。勿药自安。", "3565": "震按动止呼吸言语皆不能。其虚象尚易视。热天畏风怕地气。脉又四至。人必仍视为寒矣。丹溪断为湿痰者。盖推前因之食鸡千只膈满呕吐而悟之。至谓虚寒之象。以多服燥热药气散血耗所致。见识高人百倍。用参、耆、术煎膏。与脉浮大而虚恰合。其消痰药只用一味。妙绝。淡五味子汤送者。五味以收其气之散。淡则味薄。兼濡其血之耗也。且用于暑月为更宜。究因选药。巧不可及。令绝肉味善后。尤佳。", "3566": "吴球治一贵宦。年七十。少患虚损。好服补剂。一日事不遂意。头目眩晕。精神短少。遂告医以居常多服人参。其效甚速。乃竞用人参熟地汤药。及固本丸并进。反加气急。吴诊其脉大力薄。兼问病情。因得之曰。先生归休意切。当道苦留。抑郁而致病耳。医者不审同病异名同脉异经之说。气郁而概行补药。所以病日加也。宦者曰。斯言深中予病。竟用四七汤数剂宽快而愈。", "3567": "震按此老原系虚证。后之加剧者。由于郁耳。用补而病转增。自当寻其别因。只缘脉大力薄。仍属虚脉。故须问而知之也。", "3568": "虞恒德治一人。年三十岁。三月间。房事后乘马渡河。遇深渊沉没。幸马健无事。连湿衣行十五里抵家。次日憎寒壮热。肢节烦疼。似疟非疟之状。医作虚证治而补气血。月余不效。更医作瘵治。用四物加知、柏、地骨皮之类。及大补阴丸倍加紫河车。服至九月。反加满闷不食。顾乳妪日饮乳汁四五杯。粒米不食。虞诊视六脉皆洪缓。重按若牢。右手为甚。虞作湿郁治。用平胃散倍加苍术、白术、苓、半、川芎、香附、木通、砂仁、羌、防。加姜煎服。黄昏一帖。一更时又一帖。至半夜。遍身发红丹如瘾疹。片时遂没而大汗。即食稀粥二碗。由是诸病皆减。能食。仍与前方服三帖。后以茯苓渗湿汤倍加白术。服二十帖而安。", "3569": "震按溺水不换湿衣。又值远途。次日即病。何至遂以虚损治。盖庸医著眼在房事后耳。延至半年。病势益重。而其脉仍非虚损脉。故以湿郁治即愈。合上二案并观之。可见病因亦不得不讲。", "3570": "汪石山治一人。年逾三十。神色清减。初以伤寒过汗。嗣后两足时冷。身常恶寒。能食易饥。日见消瘦。频频梦遗。筋骨疼痛。久卧枕榻。医用滋阴降火罔效。汪视左脉浮虚而缓。右脉浮弦而缓。乃曰。足冷身寒。是阳虚之验。又汗多亡阳。奈何以阴虚治。食则易饥者。非阴虚火动也。盖脾胃以气为主。气属阳。脾胃之阳已虚。又泻以苦寒属阴之药。故阳愈虚而内空竭。须假谷气以扶助之。是以易饥而欲食。虽食亦不生肌肉也。经曰。饮食自倍。肠胃乃伤。又曰。饮食不为肌肤。其此之谓欤。梦遗亦非特阴虚。经曰。阳气者。精则养神。柔则养筋。今养气虚不能养神。则梦寐弗宁而神弗藏于心。不能养筋。则筋骨疼痛而魂弗藏于肝。神魂失所。安得不遗乎。经曰。气固形实。阳虚则不能固。而精门失守。此遗之所以频而不禁也。经曰。肾者胃之关也。今若助阳以使其固。养胃以守其关。何虑遗之不止。乃以参、耆各二钱。白术一钱。甘草五分。枳实、香附、山楂、韭子各五分。煎服半载。随时令寒暄升降。而易其佐使。遂全安。", "3571": "江应宿治祁门人周三。年近三十。潮热咳嗽咽哑。诊之。六脉弦数。周故以酒豪。先年以醉后呕血数升。遂咳不止。百治不应。肌食递减。烦躁喘满。江与四物换生地。加贝母、丹皮、麦冬、五味、阿胶煎服。加蔗浆一小杯。姜汁少许。嗽渐止。食少。再加白术、茯苓、人参。食渐进。夜噙太平丸。晨服六味合生脉。加枸杞为丸。两月嗽止。半年肥白如初。", "3572": "李士材治福建何金阳令郎。患虚损梦遗盗汗。羸顿已极。检其所服。以四物、知、柏为主。芩、连、二冬为加减。诊其脉大而数。按之极软。李曰。中气大寒。反为药苦矣。乃以归脾汤。入肉桂一钱。人参五钱。当晚得熟寐。居十日而汗止精藏。更以还少丹兼进。补中益气间服。一月而瘥。", "3573": "震按脉大而数。按之极软。诚宜温补矣。然用温补。得数脉退则愈。数脉不退则仍不愈也。亦惟大而数。按之极软。故可温补。若细而数。按之极软。死期已近。温补何益也。", "3574": "又治刑部主政唐名必。劳心太过。因食海鲜吐血。有痰。喉间如鲠。日晡烦热。喜其六脉不数。惟左寸涩而细。右关大而软。思虑伤心脾也。以归脾汤大料。加丹皮、麦冬、生地。二十剂而证减六七。兼服六味丸三月。遂不复发。", "3575": "吴门张饮光发热干咳。呼吸喘急。服苏子降气。不应。服八味丸。喘益急。迎士材视之。两颊俱赤。六脉数大。曰。此肺肝蕴热也。以逍遥散用牡丹皮一两。苡仁五钱。兰叶三钱。连进二剂而喘顿止。以地黄丸料用麦冬、五味煎膏。及龟胶为丸。至十斤而康。", "3576": "震按上条于左寸右关。得其病因。此条以服温纳不应。悟其病因。上条喜脉之不数。此条喜脉之数大。盖二人俱系新病。一虚一实。尚易辨耳。", "3577": "又曰。南都许轮所孙女。吐血痰嗽。六月诊之。两尺如烂绵。两寸大而数。余谓金以火为仇。肺不浮涩。反得洪大。贼脉见矣。秋令可忧。八月初五复诊之。肺之洪者变为细数。肾之软者变为疾劲。余曰。岁在戊午。少阴司天。两尺不应。今尺当不应而反大。寸当浮大而反沉细。尺寸反者死。肺至悬绝。十二日死。计其期。当死于十六日。然能食者过期。况十六十七二日。皆金未遽绝也。十八日交寒露。又值火日。经曰。手太阴气绝。丙日笃。丁日死。言火日也。寅时乃气血注肺之时。不能注则绝。必死于十八日寅时矣。轮所以其能食。未深信也。至十八。果未晓而终。", "3578": "侍御冯五玉令爱。发热咳嗽。已及半载。十月间。吐鲜血甚多。每日只食稀粥一盏。大肉消陷。大便溏泄。沉困著床。脉来七至。李曰。法在不救。人所共知。若能惟余是听。不为旁挠。可救十中之一。每帖用人参五钱。桂、附各一钱。耆、术三钱。归、芍二钱。陈皮一钱。日投三帖。约进七十剂。及壮水丸三斤。而后起于床。又三月而饮食如旧矣。", "3579": "孙东宿治张子心弱冠病瘵。其证咳嗽。下午热从两足心起。渐至头面。夜半乃退。面色青。形羸气促。交睫即梦遗。奄奄一息。孙诊其脉。左寸短弱。右关略弦。余皆洪大。因许可治。病者曰。医皆谓火起九泉者死。大肉尽削者死。咳嗽加汗者死。脉不为汗衰者死。况当夏令。肺金将绝。先生独言可治。何也。孙曰。证虽危。色声脉三者尚有生意。两颧不赤。心火未焚也。声音不哑。肺金未痿也。耳轮不焦。肾水未涸也。据面青者忧疑不决。左寸短者心神不足。关略弦者谋为不遂。必因志愿高而不称其心。谋为而不遂其欲。殆心病。非肾病也。经曰。色脉相得者生。故许可治。病者恍然曰。是矣。予因星士决上科必售。予仍落第。而同窗者中。故怏怏至此。今亦忘其病源矣。乃为定方。以人参、枣仁、龙骨为君。丹参、石斛、贝母、麦冬、五味子为臣。山栀、香附为佐。二十帖而病起。丸方则人参、麦冬、五味、熟地、枸杞、龟板、茯苓。蜜丸。服三月而精神健。肌肉充矣。", "3580": "震按此条辨证甚佳。所谓是心病非肾病者。亦缘脉洪大不细数耳。", "3581": "东宿云。金良美年十八。患咳嗽吐红。下午潮热。梦遗。市医进四物汤加二冬、知、柏等。治半年。反加左胁胀疼。不时侧卧。声音渐哑。饮食辄恶心。肌肉大削。六脉俱数。医告技穷。因就予治。观其面色白。又隐隐有清气夹之。两足痿弱无力。予曰。此证气虚血热。而肝脉甚弦。弦则木气太旺。脾土受亏。不能统血。始殆怒气所触。继为寒凉之剂所伤。以致饮食恶心。肌肉瘦削。书云。脾胃一虚。肺气先绝。以肺金不足。则肝木愈无所制。浊痰瘀血凝于肺窍。故咳嗽声哑。滞于肝叶。故左胁不能贴席而卧。病势危矣。喜在青年。犹可措手。因急用人参二钱。鳖甲五钱。白术、白芍、陈皮、茯苓、通草、贝母各一钱。甘草、丹皮各七分。桔梗五分。计三十帖而咳嗽潮热俱减。声音清。左胁可卧。后以大造丸调理。全安矣。因嘱之曰。病愈虽可喜。而弦脉未退。切忌恼怒及劳心劳力之事。若劳怒相触。血来必不能御也。此后精神日旺。肌体丰肥。六年无事。一日因结算劳心。加以大怒。则血如泉涌。顷刻盈盆。上唇黑肿。汗出淋漓。急请予诊。脉乱无伦。渠语近侍欲大解。予曰。此死征也。阴阳乖离矣。即辞出。未离门而气绝。", "3582": "周慎斋治一女。吐血发热。热甚而喘。用生脉散。热更甚。脉或大或小。或紧或数。或浮或涩。改变不常。知其脾阴虚而脉失信也。脉者血之府。脾统血。血枯故改变不常耳。用保元汤。加北味、山药、枸杞、白茯。人参重用至五钱。二帖效。二十帖愈。", "3583": "震按脾阴虚而脉失信。亦为脉之不常寻一别解耳。所难者吐血发热且喘。服生脉散热更甚。几与张饮光之服八味而喘益急。贵宦之服参地固本丸而反加气急。病情相类矣。慎斋指为脾血枯故脉改变。乃不用补血而重用人参。其不因热之更甚致疑生脉之误。非识力兼到者能乎。", "3584": "僧慎柔云。丹徒王盛之。年三十余。六脉俱九至。外证则咳嗽面赤。懒言怕闹。时病已年半。从前苦寒之剂。不记数矣。此真气已虚而脉数也。经云。数则元气虚。数则脾气虚。又云。数则有热而属虚。是皆不足之证。六脉中独脾肾二脉洪大。此金虚不能生肾水也。理宜补肺金。生肾水。水旺则制火。金旺则生水平木。木平则脾土盛。又生金矣。此正治也。乃与约云。兹证服药十四五帖。或二十帖外。当有汗出。此阳气升而经络通矣。汗后即当倦八九日。或半月。此邪退而正虚也。或十日半月。元气渐复。精神开爽。自后服温补脾胃之剂。又当痰动血动。或发肿毒。或作泻。此数者听其自来。乃脏腑邪气欲出。发动流行之象也。倘不预言。恐变证多端。患者惊骇耳。因与以补脾生肺滋肾水之剂。五六帖数脉不减。此真元虚而燥也。即以前剂去头煎。服二煎三煎。不十剂而脉数退去。此时虚火一退。中气便寒。以六君子加姜、桂。五六帖脾气运动。痰饮便行。归于腰胁。肝肾部分大痛。邪之所凑。其气必虚。益见肝肾虚矣。令外以盐熨。内服二陈加桃仁、延胡、苡仁。二帖。大肠见痰血而痛止。复用六君加白芍、五味而愈。倘不预明此理。变出腰胁痛时。便没主张矣。", "3585": "〔附〕叶天士治一人。年二十岁。夏月咳嗽。时带血出。常发寒热。饮食减。身渐瘦。口不渴。行动时或仆地。有日轻。有日重。牙宣龈肿。晨起则血胶厚于齿龈上。脉细带数。群以弱证治。二地二冬等滋阴药。遍尝不效。叶用芦根、滑石、杏仁、苡仁、通草、钩藤、白豆蔻。嘱云服二十帖。全愈矣。若不满二十帖。后当疟也。其人服十帖。已霍然。即停药。十月中。果发疟。仍服前药而疟愈。", "3586": "〔附〕天翁治黄公子痨病案。曰。大凡精血内夺为虚。虚不能自复为损。但须分晰自上自下。从阴从阳。起见为调理。是病始于饮酒劳心。营气先伤。心阳下溜。肾阴不主涵蓄。素多梦遗。上年夏月。先有泄泻。继发痎疟。虽暑湿热六淫相浸。然邪之所凑。本气先虚。血附于络。络凡十五。络伤血溢。莫能堵御。皆是阳气动极无制。譬诸飓风波涛矣。阳和风熄。势必渐缓。但既去难追。所谓血脱益气。以无形能生有形也。必须静形体。宁神志。令阴平阳秘。以收全功。用药亦本四时生气。间有客邪标恙。惟投轻剂一二即止。冬春两季按法。入夏色脉颇安。然里真未复。长夏阳泄地升。深抱复发之忧。果以霉湿潮蒸。骤暖郁勃。遂令诸脉中之气皆泄。络中之血大沸。一损再损。脏真少藏。奇经八脉。乏气支持。冲任由前而升。咳逆烘热。跷维失护。督脉无权。炎熇日炽。脂液日消。急急固护大气以包举。渐引渐收。冀其根蒂之把握。次则调和中土。以安谷知味。百日安静。再为斟酌。其清凉治嗽。热燥刚补。一概屏弃。天暑。午后服生脉散。若便溏泄泻。则停之。每晨。服一炁丹丸。遗证。必用桑螵蛸散。若饮食不和。用异功散加炒黑神曲、炒黑麦芽。四君子汤兼参苓白术散间服。", "3587": "喻嘉言治杨季登长女。病经闭年余。发热食少。肌削多汗。而成痨怯。医见汗多。误谓虚也。投以参、术转剧。喻诊时。见汗出如蒸笼气水。谓曰。此证可疗处。全在有汗。盖经血内闭。止有从皮毛间透出一路。以汗亦血也。设无汗而血不流。则皮毛干槁而死矣。宜用极苦之药。以敛其血入内。而下通于冲脉。则热退经行而汗自止。非补药所能效也。乃以龙荟丸日进三次。月余。忽觉经血略至。汗热稍轻。姑减前丸。只日进一次。又一月。经血大至。淋漓五日。而诸病全瘳。", "3588": "震按此条见识最高。用药甚巧。然幸不咳嗽。想其饮食虽少。未必大减。故以苦寒取效。但不知脉之数乎。大乎。有力乎。设脉象细数无力。兼见便溏食减。此方其可用乎。因思生平所见损怯证。大抵真阴亏损居多。如此案之可用大料苦寒。及李士材治何姓男。冯姓女。可用大剂热补者殊少。即临证指南所载填阴者有大半。以参耆合阴药平补者亦相等。填阴而入血肉有情之品。如河车胶、阿胶、龟鹿胶、海参、淡菜等胶。猪羊脊髓。牛腿骨髓。及秋石、血余、乳粉、鹿鞭、鹿尾之类。皆竹破竹补法也。温柔。如苁蓉、枸杞、覆盆、麋鹿茸。凉润。如生地、二冬、沙参、丹皮、女贞、梨膏、枇杷叶膏。亦皆人所能用。参合妥协。即可成方。然而得效者。恐亦尠矣。盖阳虚易治。阴竭难医。譬之盆花。泥干根槁。日以一匙之水浇之。岂能望活。惟灵雨霡霂。庶可复生。夫雨从何来。惟地气上而为云。斯天气降而为雨。地天交泰。所以生长万物。人身之地。脾胃是也。但得脾胃健旺。嗜食善化。则水谷之精华。上供于肺。可拟诸云。而肺以其精华下溉百脉。可拟诸雨。此虽老生常谈。实系养阴要旨。而欲使脾胃之健旺。固首推人参。却又非尽仗人参。此中之机缄。更一言难罄矣。", "3589": "震按传尸痨古有其名。今实未见。即一家之内。父子兄弟递以痨病死者。亦由其人禀赋虚弱。气血衰损而致。并非痨虫为害也。徐氏医统王氏准绳详载之。并绘虫形。而慎柔五书。更侈张其说。有五凤丸、雷公丸、紫河车丸、天灵盖散等方。及纸糊病人所住之屋。服侍者以安息香涂身。雄黄涂口耳目鼻等法。多属附会。不可深泥也。此亦如稽神志载一家以痨死者数人。因取继起之病者置棺中钉之。弃于水。期绝传染之患。流至金山。有人闻棺中啼哭。开视之。见一女子犹活。因取置鱼舍。多得鳗鱼食之。病遂愈。为渔人之妻焉。自此说出而世人竞为鳗能治痨。今亦何曾见其效耶。再丹方有石膏一味。或桃仁一味。神授散之川椒二斤。及童便酒煨猪腰子亦可。备临证者之参考。俱难必其效也。惟朱丹溪治临海刘兄久嗽吐红。发热消瘦。众以为瘵。百方不应。朱视之。脉弦数。日轻夜重。用倒仓法而愈。次年生子。此则圣于医者矣。何必崔氏之灸四花穴及癸亥夜二更之灸腰眼哉。", "3590": "孙东宿治程道吾令眷。夜为梦魇所惊。时常晕厥。精神恍惚。一日三五发。咳嗽。面色青。不思谷食。日惟啖牛肉脯数块而已。时师屡治无功。吴渤海认为寒痰作厥。投以附、桂。而厥尤加。孙诊之。左脉弦。右脉滑。两寸稍短。道吾先令眷二。皆卒于瘵。知其为传尸瘵证也。不易治之。乃权以壮神补养之剂。消息调理。俟饮食进。胃气转。始可用正治之法。姑用参、苓、柏子仁、石菖蒲、远志、丹参、当归、石斛。以补养神气。加陈皮、贝母、甘草、紫菀。化痰治嗽。服半月而无进退。乃制太上混元丹。用紫河车一具。辰砂、鳖甲、犀角各一两。鹿角胶、紫石英、石斛各八钱。沉香、乳香、安息香、茯苓、紫菀、牛膝、人参各五钱。麝香五分。蜜丸赤豆大。每早晚。盐汤或酒下三十六丸。又制霹雳出腊丹。用牛黄、狗宝、阿魏、安息各一钱。虎头骨五钱。啄木鸟一只。獭爪一枚。败鼓心破皮三钱。麝香五分。天灵盖一个。酥炙。炼蜜丸。雄黄三钱为衣。每五更。空心。葱白汤送下五分。三五日服一次。与太上浑元丹相兼服。才服半月。精神顿异。不似前时恍惚矣。但小腹左边一点疼。前煎药中。加白芍一钱。服之一月。精神大好。晕厥再不发矣。次年生一女。其宅瘵疾。从此亦不再传。", "3591": "又熊仲纾幼男。髫龄得一奇证。食饮如常。但脉细神呆。气夺色夭。仲纾问嘉言曰。此何病也。喻曰。病名殗殜。左传所谓近女室晦。即是此病。彼因近女。又遭室晦。故不可为。令郎受室晦之邪而未近女。是可为也。即前方少加牛黄丸服而安。", "3592": "震按此不载脉。何从取法。况痰裹米团在腹。似当如痞块状。或痛。或胀。或攻冲。乃并不言及。将何所凭据而云然耶。想良工治病。亦如伯乐相马得之于牝牡骊黄之外邪。", "3593": "丹溪治一壮年。恶寒。多服附子。病甚。脉弦而似缓。以江茶入姜汁、香油些少。吐痰一升。减绵衣大半。又与防风通圣散。去麻黄、硝、黄。加地黄。百帖而安。知其燥热已多。血伤亦深。须淡食以养胃。内观以养神。则水可升。火可降。必多服补血凉血药乃可。否则内外不静。肾水不生。附毒必发。彼以为迂。果疽发背死。", "3594": "又治一妇人。年五十余。形瘦面黑。喜热恶寒。六月。两手脉沉而涩。重取似数。三黄丸下以姜汤。每三十粒。服三十次。微汗而安。", "3595": "一老妇形肥肌厚。夏恶寒战栗。喜啖热。御绵。多汗。已服附子三十余。浑身痒甚。脉沉涩。重取稍大。知其热甚而血虚也。以四物汤去芎。倍地黄。加白术、黄耆、炒黄柏、生甘草、人参。每帖二两重。方与一帖。腹大泄。目无视。口无言。知其病热深而药无反佐之过也。以前药炒热即煎。盖借火力为向导。与一帖。利止。四帖精神回。十帖全愈。一人形瘦色黑。素多酒不困。年半百。有别馆。一日大恶寒。发战。自言渴。却不饮。脉大而弱。右关稍实。略数。重取则涩。此酒热内郁。不得外泄。由表热而下虚也。黄耆二两。干葛一两。煎饮之。大汗而愈。", "3596": "滑伯仁治一人。七月。病发热。或令服小柴胡汤。升发太过。多汗亡阳。恶寒甚。筋惕肉𥆧。视其脉。微欲绝。以真武汤。七八服稍愈。服附子八枚。而痊。", "3597": "戴原礼治朱仲文。长夏畏寒。身挟重纩。食饮必热如火。方下咽。微温即呕。他医授以胡椒制硫。日令啖鸡三。病愈亟。原礼曰。脉数而大。且不弱。刘守真云。火极似水。此之谓矣。椒发阴经之火。鸡能助痰。只以益其病耳。以大承气汤下之。昼夜行二十余。顿减纩之半。复以黄连导痰汤加竹沥。饮之竟瘳。", "3598": "震按古云。伤寒则恶寒。又云。恶寒多属阳虚卫弱。故参、附、耆、术是正药。诸案或清或下。或治痰。又古语所谓恶寒非寒也。要知丹溪原礼之防风通圣、四物、黄柏、大承气、黄连导痰等方。皆因其人多服热药而病益甚。且脉不微弱也。此与东垣治目赤。烦渴引饮。脉七八至。按之则散。为无根之火。用姜、附、人参而愈者。假寒假热。正可互参。至如南史载直阁将军房伯玉。服五石散十许剂。更患冷疾。夏月常复衣。徐嗣伯诊之曰。卿伏热。应须以水发之。非冬月不可。至十一月。寒甚。令二人挟捉伯玉。解衣坐石上。取冷水从头浇之。彭彭有气。伯玉曰。热不可忍。乞冷饮。嗣伯以水与之。一饮一斗。遂瘥。此与华元化治一妇人长病经年。于十一月令坐石槽中。平且汲冷水灌之。云当满百。至七八灌。战欲死。灌者惧。欲止。华不可。至八十灌。热气乃蒸出。百灌全。方令温床厚覆。汗浃出。敷以粉。而愈。二人治法相同。而华案不载恶寒。但云世谓寒热注病。想如今之痨瘵。日发寒热。所谓尸疰虫疰鬼疰等类耳。今人百治不效。若无华公法。安能起白骨而肉之耶。", "3599": "罗谦甫治王侍郎之婿。年二十五。十一月间。因劳役忧思烦恼。饮食失节而病。时发燥热。困倦盗汗。湿透其衾。不思饮食。气不足以息。面色青黄不泽。罗诊其脉浮数而短涩。两寸极小。告之曰。此危证也。治虽粗安。至春必死。当令亲家知之。夫人不以为然。遂易医。至正月。果躁热而卒。异日侍郎谓罗曰。吾婿果如君言。愿闻其理。罗曰。此非难知也。内经曰。主胜逆。客胜从。天之道也。盖时令为客。人身为主。冬三月人皆惧寒。独渠躁热盗汗。是令不固其阳。时不胜其热。天地时令。尚不能制。药何能为。冬乃闭藏之月。阳气当伏于九泉之下。至春发为雷。动为风鼓拆万物。此奉生之道也。如冬藏不固。则春生不茂。且有疫疠之灾。故人身阴气。亦当伏潜于内。不敢妄扰。毋泄皮肤。使气亟夺。此冬藏之应也。令婿汗出于闭藏之月。肾水已涸。至春何以生木。阳气内绝。无所滋荣。不死何侍。因叹息而去。", "3600": "震按此论可为损怯病之秦镜。何以类案不收。又罗君治韩子玉父。六十。病消渴。至冬添躁热。须裸袒。以冰置胸腋乃快。其脉沉细而疾。罗亦曰。人身为主。时令为客。大寒之令。其热更甚。经谓当所胜之令。而不能制。名曰真强。乃孤阳绝阴。必死之证也。与此条义同。", "3601": "薛立斋治州同韩用之。年四十六。仲夏色欲过度。烦热作渴。饮水不绝。小便淋涩。大便秘结。唾痰如涌。面目俱赤。满舌生刺。两唇燥裂。遍身发热。或时如芒刺而无定处。两足心如烙。以水折之作痛。脉洪而无伦。此肾阴虚阳无所附而发于外。非火也。盖大热而甚。寒之不寒。是无水也。当峻补其阴。遂以加减八味丸料一斤。内肉桂一两。以水顿煎六碗。冰冷与饮。半向已饮大半。睡觉而食温粥一碗。复睡至晚。又以前药温饮一碗。乃睡至晓。食热粥二碗。诸证悉退。翌日畏寒。足冷至膝。诸证仍至。或以为伤寒。薛曰。非也。大寒而甚。热之不热。是无火也。阳气亦虚矣。急以八味一剂。服之稍缓。四剂诸证复退。大便至十三日不通。以猪胆导之。诸证复作。急用十全大补汤四剂。方应。", "3602": "震按此条与伤寒门顾大有父七十九岁证脉颇同。而此不列之伤寒者。以所叙证。先述烦渴引饮。溺淋唾痰。面赤舌燥。而后继之以遍身发热云云。其情形殊不似伤寒之先发热。而渐见烦渴溺淋舌燥也。顾姓证叙起即首载头痛发热。细看自有分晓。立斋治法诚奇。然曰阴虚而用肉桂一两。似难矜式。况前云无水。以加减八味料一斤。所谓加减者不过去附子加五味耳。后云无火。以八味丸一剂。则较之前用一斤。桂一两。仅得十分之一矣。何先后轻重如此耶。且存其说。质之高明。", "3603": "立斋又治府庠王以道。元气素弱。复以考试积劳。于冬月大发热。泪出随凝。目赤露胸。气息沉沉欲绝。脉洪大鼓指。按之如无。舌干如刺。此内真寒而外假热也。令服十全大补汤。嘱曰。服此药其脉当收敛为善。少顷熟睡。觉而恶寒增衣。脉顿微细如丝。此虚寒之真象也。以人参一两。熟附三钱。水煎顿服而安。夜间脉复脱。乃以参二两。熟附五钱。仍愈。后以大剂参、术、归身、炙草等药。调理而愈。", "3604": "震按壮热露胸。目赤泪凝。舌干如刺。纯是火象。惟气息沉沉欲绝。是虚象。脉洪大鼓指。按之如无。则可决其内虚寒而外假热矣。服温补药后。脉当收敛为善。此是格言。所当熟记。又立斋治七十九岁老人。于少妾入房后。头痛发热。见诸火象。脉洪大无伦。按之有力。较之此案证同脉异。更宜细参。", "3605": "李时珍自记年二十时。因感冒。咳嗽既久。且犯戒。遂病骨蒸发热。肤如火燎。每日吐痰碗许。暑月烦渴。寝食几发。六脉微洪。遍服柴胡、麦冬、荆沥诸药。月余益剧。其尊君偶思李东垣治肺热如火燎。烦躁引饮而昼盛者。气分热也。宜一味黄芩汤。以泻肺经气分之火。乃按方用片芩一两。水煎顿服。次日身热尽退。而痰嗽皆愈。药中肯綮。如鼓应桴如此。", "3606": "高果哉治陈几亭。病身热。自卯辰以后。上半身热。申酉时。中半身热。亥子时。下半身热。热至足底更甚。周而复始。一日一夜。循环无间。服药久而不效。展转沉重。高诊之。脉微无力。右尺脉伏而不起。因思尺脉沉伏者。肾虚也。日夜之热。上下循环者。肾火之浮游也。至子时而足底大热。则肾火之归就于下也。若当归下之时。而能摄住其性。不使上走。则热自无矣。须效烧丹法治之。夫丹家用二个阳城罐。一盛水银丹药。填塞其中。一则空而无物。以两罐对合两口。扎住。盐泥封固。然后煅炼。其上之空罐。当烧红时。必用湿纸搭于罐底。频以冷水润之。盖下罐丹药。为火久逼。则渐渐望空罐中来矣。如升药之望上而飞也。但水银甚活。虽上入空罐。又能复入旧罐。必得凉冷之处。方能摄住其质。故用湿纸搭于罐底。丹必稳贴矣。今仿此法以制方。用童便炙龟板一两。熟地、枸杞各七钱。麦冬五钱。萸肉四钱。此五味皆补肾滋阴之药。犹水银与丹药也。附子二钱。以从治而导火归元。犹炼丹之火也。又用黄柏七钱以降其火。犹罐底之湿纸与水也。黄昏煎好。子时方服。从前服药。皆积于胸中而难下。服此药。觉胸中易下。三剂而热除病愈。", "3607": "震按此案认为肾虚火不归原。大剂补肾。寒因热用。与证极合。与脉似乎未合。然其讲理取医。真堪贻后训则。", "3608": "孙东宿治徐三泉令郎。每下午发热。直至天明。夜热更甚。右胁胀痛。咳嗽吊疼。以疟治罔效。延及二十余日。热不退。后医谓为虚热。投以参、术。痛益增。孙诊之。左弦大。右滑大搏指。乃曰。内经云。左右者。阴阳之道路。据脉肝胆之火为痰所凝。必勉强作文。过思不决。木火之性。不得通达。郁而致疼。夜甚者。肝邪实也。初治只当通调肝气。一剂可瘳。误以为疟。燥动其火。补以参、术。闭塞其气。致汗不出而舌胎如沉香色。热之极矣。乃以小陷胸汤。用大栝蒌一两。黄连三钱。半夏二钱。加前胡、青皮各一钱。煎服。夜以当归龙荟丸微下之。遂痛止热退。两帖全安。", "3609": "丹溪治一壮年。患嗽而咯血。发热肌瘦。医用补药数年而病甚。脉涩。此因好色而多怒。精神耗少。又补塞药多。荣卫不行。瘀血内积。肺气壅遏。不能下降。治肺壅。非吐不可。精血耗。非补不可。唯倒仓法二者兼备。但使吐多于泻耳。兼灸肺俞二穴。在三椎骨下横过各一寸半。灸五次而愈。", "3610": "滑伯仁治一人。盛暑出门。途中吐血数口。亟还则吐甚。胸拒痛。体热头眩。病且殆。或以为劳心焦思所致。与茯苓补心汤。仁至。诊其脉洪而滑。曰。是大醉饱。胃血壅遏。为暑迫血上行。先与犀角地黄汤。继以桃仁承气汤去瘀血宿积。后治暑即安。", "3611": "陈斗严治薛上舍。高沙人。素无恙。骤吐血半缶。陈诊之曰。脉弦急。此薄厥也。病得之大怒。气逆。阴阳奔并。饮六郁汤而愈。", "3612": "汪石山治一人。形实而黑。病咳。痰少声嘶。间或咯血。诊之。右脉大无伦。时复促而中止。左比右略小而软。亦时中止。曰。此脾肺肾三经之病也。盖秋阳燥烈。热则伤肺。加之以劳倦伤脾。脾为肺母。母病而子失其所养。女色伤肾。肾为肺子。子伤必盗母气以自奉。而肺愈虚矣。法当从清暑益气汤例而增减之。以人参二钱或三钱。白术、白芍、麦门冬、茯苓各一钱。生地、当归身各八分。黄柏、知母、陈皮、神曲各七分。甘草五分。煎服。月余而安。", "3613": "一人形瘦而苍。年逾二十。忽病咳嗽咯血。兼吐黑痰。医用参、术之剂。病愈甚。汪诊之。两手寸关浮软。两尺独洪而滑。此肾虚火旺而然也。遂以四物汤加黄柏、知母、白术、陈皮、麦冬之类。治之月余。尺脉稍平。肾热亦减。依前方再加人参一钱。兼服枳术丸加人参、山栀以助其脾。六味地黄丸加黄柏以滋其肾。半年而愈。", "3614": "震按四物加知、柏合两尺之洪滑。白术、麦冬合寸关之浮软。妙极。至于前用参、术而病甚。后以尺脉稍平仍加人参。苟非石山之高明。岂敢复蹈前辙。其收功于枳术丸加人参、山栀。及地黄丸加黄柏。尤见工巧。", "3615": "一人年逾四十。面色苍白。平素内外过劳。或为食伤。则咯硬痰而带血丝。因服寒凉清肺药消痰药至五六十帖。声渐不清而至于哑。夜卧不寐。醒来口苦舌干而常白胎。或时喉中觉痛。或胸膈痛。或嗳气夜食难消。或手靠物久则麻。常畏寒。不怕热。前有𤻊疝。后有内痔。遇劳则发。初诊左脉沉弱而缓。右脉浮软无力。续后三五日一诊。心肺二脉浮虚。按不应指。或时脾脉轻按阁指。重按不足。又时或快或缓。或浮或沉。或大或小。变动无常。夫脉不常。血气虚也。譬之虚伪之人。朝更夕改。全无定准。以脉参证。其虚无疑。虚属气虚为重也。盖劳则气耗而肺伤。肺伤则声哑。又劳则伤脾。脾伤则食易积。前疝后痔。遇劳而发者。皆因劳耗其气。气虚下陷。不能升降故也。且脾喜温恶寒。而肺亦恶寒。故曰。形寒饮冷则伤肺。以已伤之脾肺。复伤于药之寒凉。则声安得不哑。舌安得不胎。胎者。仲景谓胃中有寒。丹田有热也。夜不寐者。由子盗母气。心虚而神不安也。痰中血丝者。由脾伤不能裹血也。胸痛嗳气者。气虚不能健运。故郁于中而嗳气。或滞于上则胸痛也。遂用参、耆各四钱。麦冬、归身、贝母各一钱。远志、酸枣仁、牡丹皮、茯神各八分。石菖蒲、甘草各五分。其他山楂、麦芽、杜仲。随病出入。煎服年余而复。益以宁志丸药。前病渐愈矣。且此病属于燥热。故白术尚不敢用。况他燥剂乎。一人年五十。形色苍白。性急。语不合。则叫号气喘呕吐。一日左乳下忽一点痛。后有过劳恼怒。腹中觉有秽气。冲上即嗽。极吐。亦或干咳无痰。甚则呕血。时发时疟。或以疟治。或从痰治。皆不效。汪诊之。脉皆浮细。略弦而快。曰。此土虚木旺也。性急多怒。肝火时动。故左乳下痛者。肝气郁也。秽气冲者。肝火凌脾而逆上也。呕血者。肝被火扰不能藏其血也。咳嗽者。金失所养。又受火克而然也。呕吐者。脾虚不能运化。食郁为痰也。寒热者。水火交战也。兹宜泄肝木之实。补脾土之虚。清肺金之燥。庶几可安。以青皮、山栀各七分。白芍、黄耆、麦冬各一钱。归身、阿胶各七分。甘草、五味各五分。白术一钱五分。人参三钱。煎服月余。诸证悉平。", "3616": "震按上条声哑喉痛。口苦舌胎。而用参、耆各四钱。此条左乳下痛。秽气冲上即嗽。而用人参三钱。耆、术次之。非石山岂能辨此。且上条脉软无力。变动不常。尚可认为气虚。此条脉浮细弦数。不以滋肾清肝。治更难及。", "3617": "村庄一妇。年五十余。久嗽咯脓血。日轻夜重。汪诊之。脉皆细濡而滑。曰。此肺痿也。平日所服人参清肺饮、知母茯苓汤等剂。皆犯人参、半夏。一助肺中伏火。一燥肺之津液。故病益加。乃以天麦门冬、阿胶、贝母为君。知母、生地、紫菀、山栀为臣。桑白皮、马兜铃为佐。款冬花、归身、甜葶苈、桔梗、甘草为使。五剂而安。", "3618": "震按石山治血证。多用参、术。而此条及下条前半段治法。如出两人。可见其原非执守一法。但下条用滋阴凉药。竟得脉缓不数。殆有天幸焉。近来此种病极多。此种药效者殊少。", "3619": "一人形色苍白。年三十余。咳嗽咯血声哑。夜热自汗。汪诊之。脉濡细而近快。曰。此得之色欲也。遂以四物加麦冬、紫菀、阿胶、黄柏、知母。三十余帖。诸证悉减。又觉胸腹痞满。恶心畏食。或时粪溏。诊之脉皆缓弱。无复快矣。曰。今阴虚之病已退。再用甘温养其脾胃。则病根去矣。遂以四君子汤加神曲、陈皮、麦冬。服十余帖而安。", "3620": "江篁南治其弟患嗽血。初一二剂用知、贝、二冬、归、芍清肺之剂。夜加胁疼。继用人参一钱五分。胁疼减。后知参至二钱。左脉近大而快。右略敛。少带弦而快。每嗽则有血。大便溏。一日三更衣。以人参三钱。白术、紫菀各一钱五分。茯苓、白芍各一钱。甘草九分。牡丹皮八分。加茅根、小溲。脉弦快稍减。加黄耆二钱。百部六分。是日嗽止。血渐少。既而血亦止。然便溏。乃倍参、耆、术、山药、陈皮、甘草、苡仁、白芍等药。兼与健脾丸而愈。", "3621": "孙东宿治臧六老。上吐血。下泻血。胸膈背心皆胀。原从怒触。又犬肉所伤。故发热而渴。医者用滋阴降火药。胸背愈胀。血来更多。孙诊之两关俱洪滑有力。曰。此肝脾二经有余证也。作阴虚治。左矣。阴虚者脉数无力。今之脉既不同。午后潮热。夜半而退。与今之昼夜常热者。亦不同也。经云。怒伤肝。甚则呕血并下泄。胸背胀痛。瘀血使然。脾为犬肉所伤。故不能统血。误用地黄、知、柏等剂。是以脾益伤。而上焦瘀血愈滞也。即与山楂、香附、枳实。调气消导为君。丹参、丹皮、桃仁、滑石、茅根。化瘀血为臣。黄连、芦根。解犬肉之热为佐。四帖胸背宽。吐血止。惟腹中不舒。仍以前药同保和丸与之。大下臭黑粪而全安。", "3622": "族侄明之。作文过劳。痰火上逆。大吐痰沫。因而呕血。一涌数碗。昏晕汗出。奄奄而卧。略不敢动。稍动即呕吐而血随出。色鲜红。饮食汤水皆不敢入。入即吐而眩晕。血即随之。医者皆曰。血如涌泉。体热脉大。眩晕而药食难入。似无佳兆。孙诊之曰。无妨。凡看证要圆活。勿拘泥。经云。心主血。肝藏血。又云。怒则气上。又云。脉虚身热。得之伤暑。今左脉弦大。右脉虚大。是不独作文劳心动火。且亦被怒伤肝。抑又为暑所逼。以致木火上升。眩晕作吐。经云。诸风掉眩。皆属于肝。诸呕吐逆。皆属于火。又诸动属火。内为木火上冲。外为暑气所迫。故吐而汗多。血随吐出也。先以白丸子三钱解其暑气。清其痰饮。抑其冲逆。则吐可止。吐止气平。血自归经。服后果嗒然而睡。醒则吐止食进。眩晕寻已。继用滑石、香薷各三钱。黄连、扁豆各一钱五分。竹茹一钱。甘草五分。四帖全安。震按上条胸背皆胀。服阴药胀更甚。合以两关脉之洪滑有力。尚易辨其非阴虚。况恼怒食犬。亦可问而知之。此条因作文过劳。呕血数碗。昏晕汗出。稍动即吐。而血随至。势殊危矣。况右脉虚大。不认为虚而认为暑。竟合左脉之弦大。大剂清暑清汗。真妙手也。", "3623": "李士材曰。尚宝卿须日华。林下多郁。且有暴怒。吐血甚多。倦怠异常。余以六君子纳参一两。干姜一钱。木香八分。四日而血止。后因怒。血复大作。余曰。先与平肝。继当大补。然夏得秋脉。所谓早见非时之脉。当其时不能再见矣。果如期而殁。", "3624": "震按两尺沉实。决其少腹有瘀。因瘀而蒸热。因蒸热而吐血。盖从脉象认得病根。故大下而病根去。去后峻补。不用养阴。更妙。景岳治倪孝廉。素以攻苦。思虑伤脾。时有呕吐之证。过劳即发。用理阴煎、温胃饮之属。随饮即愈。一日于暑末时。因连日交际。致劳心脾。遂上为吐血。下为泄血。俱大如手片。或紫或红。甚多可畏。医云。此因劳而火起心脾。兼之暑令。二火相济。所以致此。与犀角、地黄、童便、知母之属。药及两剂。其吐愈甚。脉益紧数。困惫垂危。迨景岳往视。形势俱剧。乃以人参、熟地、干姜、甘草四味。大剂与之。初服毫不为动。次服觉呕恶少止。而脉中微有生意。乃复加附子、炮姜各二钱。人参、熟地各一两。白术四钱。炙甘草一钱。茯苓二钱。黄昏与服。竟得大睡。直至四鼓。复进之。而呕止血亦止。又服此方数日。而健如故。盖此人以劳倦伤脾。脾胃阳虚。气有不摄。所以动血。时当二火。而证非二火。再用寒凉。脾必败而死矣。", "3625": "震按此与生生子族侄之病病因同。现证及时令又同。而一用寒凉。一用温补。水火之别。皆得收功。自非神手不能。但孙脉左弦大右虚大。与紧脉不同。孙案未曾以药尝试。张案用寒凉而病益甚。亦有不同也。临证者在乎细心体察也。喻嘉言治一人。素有失血病。晨起陡暴一口。倾血一盆。喉间气壅。神思飘荡。壮热如蒸。颈筋粗贲。诊其脉尺中甚乱。曰。此昨晚大犯房劳也。因出验血。色如太阳之红。再之寝所。谓曰。少阴之脉系舌本。少阴者肾也。今肾家之血。汹涌而出。舌本已硬。无法可救。不得已用丸药一服。镇安元气。若得气转丹田。尚可缓图。内浓煎人参汤。下黑锡丹三十粒。喉间汩汩有声。渐入少腹。顷之舌柔能言。但声不出。急用润下之剂以继前药。遂与阿胶一两溶化。分三次热服。半日服尽。身热渐退。颈筋渐消。进粥。与补肾药。多加秋石。服之遂愈。", "3626": "又治顾枚先。年二十余岁。体肥嗜酒。孟夏患失血证。每晚去血一二盏。延至季夏。去血无算。然色不憔悴。身不消瘦。脉不洪盛。亦无寒热。但苦上气喘促。夜多咳嗽。喉间窒塞。胸前紧逼。背后刺胀。躁急多怒。医以人参、阿胶。治失血成法。用之月余。逾增其势。更医用滋阴膏子润上。牛膝、黄柏导下。总不见效。及服酒研三七。则血止咳定。但未久。血复至。咳复增。喻曰。是病为饮醇伤胃。胃家多气多血。故内虽渐亏。而外犹未觉。揆其致此之繇。又必以醉饱入房而得之。盖人身气动则血动。而媾精时之气。有乾坤鼓铸之象。其血大动。精者。血之所化也。灌输原不止胃之一经。独此一经所动之血。为醉饱所阻。不能与他经缉续于不息之途。是以开此脱血一实。今者竟成熟路矣。夫胃之脉从头走足。本下行也。以呕血之故。逆而上行。则呼吸必致喘急。胃之气。传入大小肠膀胱等处。亦本下行也。以屡呕之故。上逆而不下达。则胸腹必致痛闷。胃气上奔。呕逆横决。则胸中之气必乱。所以紧逼痛楚。甚至攻入于背。以背为胸之府也。其心烦多怒者。以胃之上为膈。内经所谓血迸于膈之上。气迸于膈之下。气血倒而使然。且胃之大络。贯膈络肺。其膈间紧逼肺间。气胀痰胶。何莫非胃病之所传哉。当此长夏土旺。母邪尽传于子。至三秋燥金司令。咳嗽喘满之患必增。肺痈胃痈之变必来矣。今岁少阴司天。运气热也。炎夏酷暑。时令热也。而与胃中积热。合煽其虐。不治其热。血必不止。惟遵内经热淫血溢。治以咸寒之旨。用元明粉化水煮黄柏。秋石化水煮知母。少加甘草以调其苦。四剂而血止。惜病家不终其用。八月中。果生肺痈而死。", "3627": "周慎斋治陈姓人。年三十五岁。性嗜酒色。忽患吐血。一日三五次。不思饮食。每日食粥一碗。反饮滚酒数杯。次日清晨再食粥。前粥尽行吐出。吐后反腹胀。时时作痛作酸。昼夜不眠。饮滚酒数杯略可。来日亦如此。近七月矣。医人并无言及是积血者。俱言不可治。周诊之。六脉短数。曰。吐后宜宽反胀。饮滚酒略可。此积血之证也。盖酒是邪阳。色亦邪阳。邪阳胜则正阳衰。又兼怒气伤肝。肝不纳血。思虑伤脾。脾不统血。中气大虚。血不归络。积血中焦无疑。宜吐宜利。但脾胃大虚。不使阳气升发。阴寒何由而消。先用六君子汤。白术以苍术制之。加丁香温胃。草蔻治中脘痛。三十余帖。再用良姜一两。百年陈壁土四两同煎。待土化切片。陈皮去白。草蔻、人参、白术、茯苓、甘草、胡椒、丁香各五钱。细辛四钱。共末。空心。清盐汤或酒送下二钱。此药专在扶阳。积血因阴寒凝结。阳旺而阴自化。服药后。血从下行者吉。乃血从上吐。约六七碗。胸中闷乱。手足逆冷。不省人事。急煎人参五钱。炮姜八分。遂静定。后胸中闷乱。脐下火起而昏。用茯苓补心汤。一剂而安。后用六味加人参、炮姜而痊。", "3628": "石顽治牙行陶震涵子。伤劳咳嗽。失血势如泉涌。服生地汁墨汁不止。门人周子。用热童便二升而止。石顽诊其脉弦大而虚。自汗喘乏。至夜则烦扰不宁。与当归补血汤。四帖而热除。时觉左胁刺痛。按之漉漉有声。此少年喜酒负气。尝与人斗狠所致。与泽术麋衔汤加生藕汁调服。大便即下累累紫黑血块。数日乃尽。后与四乌鲗骨一藘茹为末。分四服。入黄牝鸡腹中煮啖。留药蜜丸。尽剂而血不复来矣。", "3629": "震按自汗喘乏。脉弦大而虚。不混投地黄汤、生脉散。高矣。用补血汤者。以其夜间烦扰不宁耳。至因胁痛想及斗狠。则此人形色必壮实。故消瘀不补益。最为得法。", "3630": "高士宗曰。友孙子度侄女。适张氏。病半产。咳嗽吐血。脉数而涩。色白。胃满脾泄。医用理气降火止血药。益甚。予投理中汤加木香、当归。倍用参、术而血止。继用归脾汤。及加减八味饮子。诸证渐愈。时鼓峰适从湖上来。视之曰。大虚证得平至此。非参、术之力不能。今尚有微嗽。夜热时作。急宜温补以防将来。因定朝进加减八味丸。晡进加减归脾汤。未几。遇粗工。诧曰。血病从火发。岂可用热药。遂更进清肺凉血之剂。病者觉胃脘愈烦惋。饮食不进。而迫于外论。强服之。逾月病大发。血至如涌。或紫或黑。或鲜红。病者怨恨。复来招。予往视之。曰。败矣。脏腑为寒凉所逼。荣卫既伤。水火俱竭。脉有出而无入。病有进而无退。事不可为也。未几果殁。仁斋直指云。荣气虚散。血乃错行。所谓阳虚阴必走也。曹氏必用方云。若服生地、藕汁、竹茹等药。去生便远。故古人误解滋阴二字。便能杀人。况粗工并不识此。随手撮药。漫以清火为辞。不知此何火也。而可清乎。所用药味。视之若甚平稳。讵知其入人肠胃。利如刀锯。如此可畏哉。夫血脱益气。犹是粗浅之理。此尚不知。而欲明夫气从何生。血从何化。不亦难乎。操刀使割。百无一生。有仁人之心者。愿于此姑少留意也欤。", "3631": "震又按缪仲淳治吐血三诀。举世奉为明训。实未细绎其义。首条云。宜行血。不宜止血。固是。然行血之药。惟有大黄。所谓血以下行为顺也。又须看其血证之新久。与失血之多少而去取之。盖宜下于妄行之初。不宜下于脱血之后也。今本文不注明行血者何药。但云行血则血循经络。致近日有多服山羊血而死者。安知不误于此句。至如血来汹涌。必须止之。古方花蕊石散、十灰散。及童便、墨汁等。皆欲其止也。止之后。或消或补。尚可缓商。任其吐而不思所以止之。何从求活。特是止血之法。贵于虚实寒热辨得明。斯于补泻温清拿得稳耳。本文云。止之则血凝。血凝则发热恶食而病日痼。抑思今之吐血者。每多发热恶食。何尝由于血凝耶。果系血凝。则仲景大黄䗪虫丸尚可救之。只虑血去无算。阴虚则病。阴竭则死。无可奈何也。次条宜补肝不宜伐肝。注谓养肝则肝气平。而血有所归。伐之则肝虚不能藏血。血愈不止。此说诚妙。然亦要看脉象若何。肝阴固宜养。肝阳亦宜制。设遇木火两亢。血随气逆者。则抑青丸、龙胆泻肝汤。醋制大黄、桃仁、枳壳、青铅、铁锈水等。何尝禁用。盖得其道。则伐之即所以补之。不得其道。而徒奉熟地、当归、萸肉、枸杞等为补肝之药。则谬矣。末条宜降气。夫气有虚实。亦分寒热。血证之气。虚者多。实者少。热者多。寒者少。惟恃强善怒之人。肝气实而吐血。往往有之。抑肝清肝。宜降气又宜降火矣。他如肺气虚而不降。则生脉散、观音应梦散。中气虚而不降。则四君子、参橘煎。肾阳虚不能纳气而不降。则八味丸、黑锡丹。肾阴虚不能纳气而不降。则大补阴丸、三才封髓丹。必求其所以不降之故而治之。斯为降。乌可恃韭汁、苏子、番降香。为下气药耶。至不宜降火之句。医中狡狯者。藉为口实。辄称吐血服生地、麦冬。必成痨病。随将假阿胶售人以代二物。不知世之一见血证。概用生地、麦冬。诚应诃责。若将二物屏弃。岂非因噎废食。况予生平所见。血溢上窍之人。合乎丹溪所谓阳盛阴虚有升无降者。十居八九。合乎仁斋所谓阳虚阴必走。及曹氏必用方之甘草干姜汤。赵氏绛雪丹书之桂附者。百中一二而已。惟虚而有火者。清补并用。虚而无火者。气血兼补。或宜降火。或不宜降火。总无一定之法也。若谓服苦寒药必死。则仲景金匮之泻心汤。不几为罪之魁哉。", "3632": "滑伯仁治一妇。体肥而气盛。自以无子。尝多服暖宫药。积久火盛。迫血上行为衄。衄必数升余。面赤。脉躁疾。神恍恍如痴。医者犹以上盛下虚。丹剂镇坠之。伯仁曰。经云。上者下之。今血气俱盛。溢而上行。法当下导。奈何实实耶。即与桃仁承气汤三四下。积瘀去。继服既济汤。二十剂而愈。", "3633": "项彦章治一妇。患衄三年许。医以血得热则淖溢。服泻心凉血之剂。益困。衄才数滴。辄昏。六脉微弱。寸为甚。曰。肝藏血而心主之。今寸口脉微。知心虚也。心虚则不能司其血。故逆而妄行。法当养心。仍补脾。实其子。子实则心不虚矣。以琥珀诸补心药。遂安。", "3634": "许学士云。一人膏粱嗜饮。常病衄。医曰。诸见血者为热。以清凉饮子投之。即止。越数日。其疾复作。医又曰。药不胜病故也。遂投黄连解毒汤。或止或作。易数医。皆用寒苦之剂。俱欲胜其热而已。饮食起居。浸不及初。肌寒而时躁。言语无声。口气臭秽。恶吸冷风。其衄之余波。则未绝也。或曰。诸见血者热。衄、热也。热而寒之。理也。今不愈而反害之。何耶。内经曰。以平为期。又言下工不可不慎也。彼惟知见血为热。而以苦寒攻之。抑不知苦泻土。土、脾胃也。脾胃人之所以为本者。今火为病而泻其土。火未尝除而土已病矣。土病则胃虚。虚则荣气不能滋荣百脉。元气不循天度。气随阴化而无声肌寒也。噫。粗工嘻嘻。以为可治。热病未已。寒病复起。此之谓也。", "3635": "汪石山治一人。形魁伟。色黑善饮。年五十余。病衄如注。喘嗽。喘不能伏枕。医以四物汤加麦冬、阿胶、桑白皮、黄柏、知母进之。愈甚。诊之脉大如指。脉诀云。鼻衄失血沉细宜。设见浮大即倾危。据此。法不救。所幸者色黑耳。脉大非热。乃肺气虚也。此金极似火之病。若补其肺气之虚。则火自退矣。医用寒凉降火之剂。是不知亢则害。承乃制之旨。遂用人参三钱。黄耆二钱。甘草、白术、茯苓、陈皮、神曲、麦冬、归身甘温之药进之。一帖病减。十帖病愈。", "3636": "震按以上四案。首条是实热。次条为心脾两虚。三条病因是热。而过用苦寒。四条脉形是热。而实由气虚。不同如此。临证者可不细辨乎。", "3637": "又一人形近肥而脆。年三十余。内有宠妻。三月间。因劳感热。鼻衄久而流涕不休。鼻秽难近。渐至目昏耳重。食少体倦。医用四物凉血。或用参耆补气。罔有效者。诊之脉濡而滑。按皆无力。曰。病不起矣。初因水不制火。肺为火扰。流涕不休。经云。肺热甚则出涕是也。金体本燥。津液日泄。则燥者枯矣。久则头面诸阳之液。因以走泄。经云。枯涩不能流通。逆于肉里。乃生痈肿是也。月余。面目耳旁。果作痈疮而卒。后见流涕者数人。多不救。", "3638": "震按流涕鼻秽。即鼻渊之属。何以断其必死。要之脉濡滑而无力。昔贤谓滑脉类数。仲景所云数脉不时。则生恶疮也。脉无力者。石山必用参、耆。今参、耆罔效。无路可寻矣。况流涕不休。定然枯涩。故以营气不从。逆于肉里。为是病之指归。魏注云。用滋水生肝养肺药诚佳。然以治流涕不休者。恐亦难效。", "3639": "朱圣卿鼻衄如崩。三日不止。较之向来所发之势。最剧。服犀角、地黄、芩、连、知、柏、石膏、山栀之属。转盛。第四日。邀石顽诊之。脉弦急。如循刀刃。此阴火上乘。载血于上。得寒凉之药。转伤胃中清阳之气。所以脉变弦紧。与生料六味加五味子作汤。另用肉桂末三钱。飞罗面糊。分三丸。用煎药调下。甫入喉。其血顿止。少顷。口鼻去血块数枚而愈。自此数年之患。绝不再发。", "3640": "〔附〕一人衄血不已。医皆以为热。沈宗常投以参附而愈。人骇问之。曰。脉小而衰。非补之不可。", "3641": "罗谦甫治真定总管史侯男。年四十余。肢体本瘦弱。于至元辛巳。因秋收租。佃人致酒味酸。不欲饮。勉饮数杯。少时腹痛。次传泄泻无度。日十余行。越旬。便后见血红紫。肠鸣腹痛。医曰。诸见血者为热。用芍药柏皮丸治之。不愈。仍不欲食。食则呕酸。形体愈瘦。面色青黄不泽。心下痞。恶冷物。口干。时有烦躁。不得安卧。罗诊之。脉弦细而微迟。手足稍冷。内经曰。结阴者。便血一升。再结二升。三结三升。又云。邪在五脏。则阴脉不和。而血留之。结阴之病。阴气内结。不得外行。无所禀。渗肠间。故便血也。以苍术、升麻、熟附子各一钱。地榆七分。陈皮、厚朴、白术、干姜、白茯苓、干葛各五分。甘草、益智仁、人参、当归、神曲、炒白芍药各三分。上十六味作一服。加姜、枣煎。温服食前。名曰平胃地榆汤。此药温中散寒。除湿和胃。数服。病减大半。仍灸中脘三七壮。乃胃募穴。引胃上升。滋荣百脉。次灸气海百余壮。生发元气。灸则强食羊肉。又以还少丹服之。则喜饮食。添肌肉。至春再灸三里二七壮。壮脾温胃。生发元气。此穴乃胃之合穴也。改服芳香之剂良愈。", "3642": "震按此条证因易辨。脉又可凭。无甚疑难。妙在制方。升温通补分量轻重合宜。的属东垣高弟。", "3643": "丹溪治一老妇。性沉多怒。大便下血十余年。食减形困。心摇动。或如烟熏。早起面微浮。血或暂止。则神思清。忤意则复作。百法不治。脉左浮大虚甚。久取滞涩而不匀。右沉涩细弱。寸沉欲绝。此气郁生涎。涎郁胸中。心气不升。经脉壅遏不降。心血绝。不能自养故也。非开涎不足以行气。非气升则血不归隧道。以壮脾药为君。二陈汤加红花、升麻、归身、酒黄连、青皮、贝母、泽泻、黄耆、酒芍药。每帖加附子一片。煎服。四帖后血止。去附。加干葛、丹皮、栀子。而烟熏除。乃去所加药。再加砂仁、炒曲、熟地黄、木香。倍参、耆、术。服半月愈。", "3644": "震按此条脉证。似虚似实。非寒非热。较之罗案。难辨多矣。及观其讲病源与用药法。及药之轻重去取。俱有精义。又极平和。十年之病。半月而愈。仙乎仙乎。", "3645": "李士材治学宪黄贞父。患肠风。久用四物汤芩、连、槐花之属。屡发不止。面色颇黄。诊其脉。惟脾部浮而缓。此土虚而风湿交乘也。遂用苍术三钱。茯苓、人参、黄耆、升麻、柴胡、防风各一钱。四剂而血止。改服十全大补汤。调养而愈。", "3646": "孙东宿治新市陈鹿塘。有肠风脏毒之证。大便燥结。数日不能一行。痛苦殊甚。百医不效。其脉两寸皆数。两关皆弦而无力。两尺洪滑而左尤甚。孙曰。东垣谓大肠喜清而恶热。脾胃喜温而恶寒。以胃属土而大肠属金也。今此乃胃寒肠热之证。当以肠风脏毒之药为君主。外以养血之剂裹之。使不伤胃气。盖药先入胃。而后传入大肠。入胃时裹药未化。及入大肠。则裹药化而君药始见。亦假途灭虢之策也。因以大黄酒浸九蒸九晒二两。木耳二两。槐花三两。郁李仁、皂角子、象牙屑、条芩各一两。血余灰、升麻、荆芥各五钱。为末。炼蜜丸。外以四物汤加蒲黄各一两为衣。空心午后。各以米汤下二钱。果血止而大便不燥。饮食日加矣。", "3647": "又治董宗伯公子龙山夫人。即宪副茅鹿门公女。年三十五。病便血。日二三下。腹不疼。医治三年不效。孙诊之。左脉沉涩。右脉漏出关外。诊不应病。因血既久下。且用补中益气汤加阿胶、地榆、侧柏叶服八剂。血不下者半月。彼自喜病愈矣。偶因劳而血复下。又索煎药。孙曰。夫人之病。必有瘀血积于经隧。前因右脉漏关难凭。故以升提兼补兼涩。以探虚实耳。今得病情。法当下而除其根也。龙山曰。三年间便血。虽一日二三下。而月汛之期不爽。每行且五日。何尚有瘀血停蓄耶。孙曰。此予因其日下月至。而知其必有瘀血停蓄也。经云。不塞不流。不行不止。今之瘀。实由塞之行也。不可再涩。古人治痢。必先下之。亦此意也。即用桃仁承气汤加丹参、五灵脂、荷叶蒂。水煎夜服。五更下黑瘀血半桶。其日血竟不来。乃以理脾药养之。过五日。复用下剂。又下黑瘀如前者半。乃以补中益气汤、参苓白术散。调理全愈。", "3648": "周慎斋治一人。患肠风。血大下不止。头晕倒地。三四年不愈。皆曰不可治。周诊脉。左手沉细。右手豁大。此因内伤寒凉太过。致阳不鼓。故右脉沉细。血不归络。火浮于中。故尺脉豁大。用补中益气汤十帖。再用荆芥四两。川乌一两。醋面糊丸。空心服愈。", "3649": "〔附〕嘉兴府尊王竺庐公祖办事勤敏。凡案牍书禀。靡不亲阅手裁。积劳而得便血证。初用天王补心丹及玉女煎、知柏地黄丸等方。屡愈屡发。至丙申三月渐剧。食减面黄形瘦。精神衰弱。无锡龚商年兄用补中益气汤。以醋炒升麻、归身而血止。半月后。偶食青菜腐汤。血复下。龚谓寒湿伤脾。用苍术理中汤。遂愈。十月中。值府考阅卷过劳。血又大发。龚诊其脉。弦劲带数。腹胀不思食。易怒。进加味逍遥散。不应。改用桃花散、归脾汤。转加口干咳嗽。佐以阿胶、熟地。又溏泻肠鸣不食。困惫难支。值抚宪荐胡灏轩先生来。毅然曰。归脾须合右归。重用人参则效。定方人参五钱。山药三钱。枸杞、菟丝、枣仁各四钱。茯神、白芍、文蛤炒各钱半。炙草、炮姜各七分。地榆炭八分。乌梅、大枣各二枚。一剂而血止。递加耆、术、熟地。再去地榆、文蛤。佐以附子。而谷纳渐增。病遂全愈。斯真得力于景岳者。", "3650": "震按内经谓胞移热于膀胱则溺血。故溺血证属热者多。实热则脉洪数有力。宜导赤散加栀、芩、淡竹叶、鲜小蓟。调滑石末。冲生藕汁。虚热则脉洪数无力。宜生地、归、芍、栀、芩、牛膝、麦冬、黄连等。调发灰。或茅根汁。若夏月有感暑热者。六一散加黄连、生地。若少年有血虚挟瘀者。阿胶、三七二味多服。若阻塞不通。并可加冬葵子、生蒲黄以化之。若多怒人有肝家郁火者。龙胆泻肝汤。甚则当归龙荟丸。惟久而不止则为虚。归脾、补中益气酌用。或老年及久病人。始虽热证。久变虚寒。并可用八味地黄丸、四味鹿茸丸等方。然用至此种药小愈仍复发者。多不救。予选二案。又恐人止狃于属热治法。故取立斋以疗庸浅之通病。", "3651": "慎斋治一人。自汗。足冷不能行动。尺脉沉大。此脾气下陷也。故肺失养而汗出。足乃脾肾经行之地。脾阳不舒。肾气亦郁。所以冷也。以启脾养肺为本。温肾为标。用参、耆、山药。补脾阴固表扶肺。稍加桂温之而愈。", "3652": "震按自汗而足冷不能行动。显系下焦虚寒矣。尺脉当沉细。何反沉大。粗工舍脉凭证。必将温补肝肾而用熟地、枸杞、苁蓉、鹿茸、桂、附等药。缪工凭脉论证。或认下焦湿热而用二妙散、防己、黄耆等方。俱与脾气下陷隔一层也。慎斋善用温补。此案只稍加肉桂。亦以尺脉之沉大也。", "3653": "戴人曰。昔庄先生治一人。以喜乐之极而病者。庄切其脉。为之失声。佯曰。吾取药去。数日更不来。病者悲泣。辞其亲友曰。吾不久矣。庄知其将愈。慰之。诘其故。庄引素问曰。惧胜喜。可谓得元关者也。然华元化以怒郡守而几见杀。文挚以怒齐王而竟杀之。欲活他人。反戕厥躬。悲夫。", "3654": "徐书记有室女。病似劳。医僧法靖诊曰。二寸脉微伏。是忧思致病。请示病因。徐曰。女子梦吞蛇。渐成此病。靖谓有蛇在腹。用药专下小蛇。其疾遂愈。靖密言非蛇病也。因梦蛇过忧成疾。当治意而不治病耳。", "3655": "一富家妇。伤思虑过甚。二年不寐。无药可疗。其夫求戴人诊之。曰。两手脉俱缓。此脾受之也。脾主思故也。乃与其夫以怒激之。多取其财。饮酒数日。不处一方而去。其妇大怒。汗出。是夜困眠。如此八九日不寤。自是食进。脉得其平。", "3656": "一女新嫁后。其夫经商二年不归。因不食。困卧如痴。无他病。多向里床坐。丹溪诊之。肝脉弦出寸口。曰。此思男子不得。气结于脾。药难独治。得喜可解。不然。令其怒。脾主思。过思则脾气结而不食。怒属肝木。木能克土。怒则气升发而冲。开脾气矣。其父掌其面。呵责之。号泣大怒。至三时许。令慰解之。与药一服。即索粥食矣。朱曰。思气虽解。必得喜。庶不再结。乃诈以夫有书。旦夕且归。后三月。夫果归而愈。", "3657": "丹溪曰。一蜀僧出家时。其母在堂。及游浙右。经七年。忽一日。念母之心甚切。欲归无腰缠。徒尔朝夕西望而泣。以是得病。黄瘦倦怠。时僧年二十五岁。太无罗先生见之。令其隔壁泊宿。每日以牛肉猪肚甘肥等。煮糜烂与之。凡经半月余。且时以慰谕之言劳之。又许钞十锭作路费。曰不望报。但欲救汝之命耳。察其形稍苏。脉稍充。与桃仁承气。一日三帖下之。皆是血块痰积。方止。次日只与熟菜稀粥将息。又半月。其僧遂如故。又半月有余。与钞十锭。遂行。", "3658": "王中阳治江东富商。自奉颇厚。忽患心惊。如畏人捕之。闻脂粉气即遗泄。昼夜坐卧。常欲人拥护方安。甫交睫。即阳动精滑。遍身红晕紫斑。两腿连足浸淫湿烂。脓下不绝。饮食倍常。酬应不倦。累医不效。王诊得六脉俱长。三部九候往来有力。两手寸尺特盛。猝难断证。因问之。商告曰。某但觉虚弱无力。多惊悸。及苦于下元不固。两腿风疮。侍奉皆赖妇人。而又多欲不能自禁。奈何治之。王曰。时医必作三种治。一者治惊悸。二者治虚脱。三者治风疮。以余观之。只服滚痰丸。然后调理。满座愕然。王曰。此系太过之脉。总是湿痰为病。与火炎水涸。神怯精伤者。本异标同也。逐去痰毒。不必缕治。服丸三日。脉稍平。曰。君连年医药不效。反增剧者。不识虚实。认假为真故也。再令服三次。越五日。脉已和。不言惊悸之苦。但求遗泄之药。王用豁痰汤加茯苓煎服。月余诸证悉减。乃用泥金膏。以新汲水调敷两腿。干则再上。周时洗去。则热气已衰。皮肉宽皱。然后用杖毒活血方。调敷全愈。", "3659": "震阅洞虚子原案。曰。此系太过之脉。心肾不变。又曰。水火亢行。心不摄血。运于下不能上升。凝于肌肤。日久湿烂。与火炎水滥。神不宁阳频泄者。本同标异也。其词涩而义晦。不如曰湿热生痰。上壅下注。反觉径捷。故僭改之。再查豁痰汤。亦逸人自定。乃以小柴胡汤去姜、枣。加紫苏、薄荷、羌活、陈皮、厚朴、枳壳、南星。云治一切痰疾。与滚痰丸相副。或以前胡易柴胡。其泥金膏。则用阴地上蚯蚓粪三分。熟皮朴硝二分。同研细。水调敷。杖毒活血方。则用蛇床子、光草乌、火煅炉甘石、枯矾、槟榔、花粉、绿豆粉、凌霄花、赤石脂、白石脂、大蓟根叶、小蓟根叶为末。另煎大黄汁调敷。云治杖疮奇妙。", "3660": "张路玉治河南督学汪缄庵媳。产后病虚无气。洒洒然如惊。常时咳青黑结痰。欲咳则心中憺憺大动。咳则浑身麻木。心神不知所之。偶闻一声响。则头面哄热。微汗。神魂如飞越状。专事妇科者。屡用补养心血之剂。罔效。虚羸转剧。邀张诊之。脉浮。微弦而芤。独左寸厥厥动摇。此必胎前先伤风热。坐草时迸力过甚。痰血随气上逆。冲过膈膜而流入心包也。朝用异功散加童便煅淬蛤粉。以清理痰气。大剂独参汤下来复丹。以搜涤瘀积。盖痰在膈膜之上。非焰硝无以透之。血在膈膜之上。非五灵无以浚之。然非藉人参相反之性。不能激之使出也。服数日。神识渐宁。形神渐旺。改用归脾汤加龙齿、沉香。调理而康。", "3661": "吴昭如室。年壮体丰。有素而呕血。腹胀。脾约便难之恙。两遭回禄。忧恚频仍。近于失血之后。忽然神气愦乱。口噤目瞠。石顽诊之。气口数盛而促。人迎弦大而芤。形神不能自主。似有撮空之状。一医以为证犯条款。不出五日当毙。张谓不然。若是撮空。必然手势散漫。今拈著衣被。尽力扯摘。定为挟惊挟怒无疑。爪者筋之余。非惊怒而何。况脉来见促。当是痰气中结。殊非代脉之比。询其病因。惊怒俱有。遂用钩藤钩一两。煎成。入竹沥半盏。姜汁五匙。连夜服药。即得安寐。次日六脉稍平。但促未退。仍用前方减半。调牛黄末一分。其夕大解三度。共去结粪五六十枚。腹胀顿减。脉静人安。稀糜渐进。数日之间。平复如常。", "3662": "易思兰治一妇。浑身倦怠。呵欠口干。经月不食。强之。不过数粒而已。有以血虚治之者。有以气弱治之者。有知为火而不知火之源者。用药杂乱。愈治愈病。至冬微瘥。次年夏间。诸病复作。肌消骨露。三焦脉洪大侵上。脾肺二脉微沉。余部皆平和。此肺火病也。以栀子仁姜汁浸一宿。炒黑研细。用人参、麦冬、乌梅煎汤调下。进二服。即知饥喜食。旬日肢体充实如常。后因久病不孕。众皆以为血虚而用参耆之品。半月胸膈饱胀。饮食顿减。至三月余而经始通。下黑秽不堪。或行或止。不得通利。其苦万状。复以四乌汤。换生地。加陈皮、苏梗、黄芩、山栀、青皮、枳壳十数剂。一月内即有孕。", "3663": "周慎斋治一人。六脉涩滞。胁痛吐臭痰。恶心食不下。盖胁者。少阳之分也。清气不升。浊气郁于少阳之络。故痛。浊气上逆。故吐臭痰而恶心。浊气。故臭也。食不下者。少阳清阳之气不升。则肝不能散精也。用柴胡、白蔻各二分。黑山栀、甘草各五分。白芍、丹皮各一钱。白茯苓、广皮各一钱五分。归身八分。麦冬二钱。十帖全愈。", "3664": "张景岳曰。予向同数友。游寓榆关客邸。内一友素耽风月。忽于仲冬一日。夜叩予户。张皇求救。云所狎之妓。忽得急证。势在垂危。倘遭其厄。祸不可解。予往视之。见其口吐白沫。僵仆于地。以手摸之。则口鼻四肢俱冷。气息如绝。陡见其状。殊为惊骇。因拽手诊之。则气口和平。脉不应证。予意其脉和如此。而何以证危如是。沉思久之。岂即仲景所云诈病耶。复诊其脉。安然如故。遂大声于病妓之旁曰。此病危矣。须用极大艾丸。连灸眉心人中小腹数处。方可活。惜花容损坏耳。余寓有艾。宜速取来灸之。然火灸尚迟。姑先与一药。使其能咽之后。倘有声息。则生意已复。即不灸亦可。若口不能咽。或咽后不苏。当速灸可也。病妓闻予之言。窃已惊怖。惟恐大艾著身。药到即咽。咽后少顷。即哼声出而徐动徐起矣。次日问之。乃知为吃醋而发也。", "3665": "震按此条乃人病脉不病。尚易揣度。次条所载金吾公二妾相竞。一系燕姬。其母助恶叫喊撒泼。遂致气厥若死。自暮及旦不苏。景岳初诊之。见其肉厚色黑。面青目瞑。手撒息微。脉又伏。渺若脱。意其真危也。欲施温补。恐大怒之后。逆气未散。欲用开导。恐脉之似绝。虚不能胜。请再诊之。则前此撒手。今忽十指交叉于腹。因而动疑。及著手再诊。似有相嫌不容之意。卒然猛扯之。力强且劲。益疑将死之人。岂犹有力如是。乃思其脉若此者。或因肉厚气滞。北人禀赋使然。或因两腋夹紧。奸人猝诈所致。遂用前法。以恐胜之。药甫到咽即活。此比前案更难辨识也。", "3666": "丹溪治一室女。素强健。六月发烦闷。困惫不食。时欲入井。脉沉细数弱。口渐渴。医作暑病治不效。又加呕而瘦。手心热。喜在暗处。脉渐伏而妄语。朱制局方妙香丸。如芡实大。井水下一丸。半日大便。药已出矣。病不减。遂以麝香水洗药。以针穿三孔。凉水吞。半日下稠痰数升。得睡渐愈。因记金匮云。昔肥而今瘦者痰也。", "3667": "阁老梁厚斋。气短有痰。小便赤涩。足跟作痛。尺脉浮大。按之则涩。此肾虚而痰饮也。用四物送六味丸。不月而康。仲景云。气虚有饮。用肾气丸补而逐之。诚开后学之蒙瞆。济无穷之夭枉。肾气丸。即六味丸。", "3668": "震按四物汤送六味丸。专补肾阴也。若仲景所谓肾气丸。必以六味加桂附为是。况气短足跟痛尺脉涩。仅用六味。恐不效。此案与治孟都宪案同法。梁则小便赤涩。孟则遗尿。梁则尺浮大而按之涩。孟则尺浮大按之如无。孟加眩晕。尤易辨也。", "3669": "李士材曰。翰林李集虚。劳而无度。醉而使内。汗出多痰。服宽膈化痰之药。转觉滞闷。诊其脉沉而涩。两尺尤甚。余谓其婿曰。痰得涩脉。一时难愈。况尺中涩甚。精伤之象也。在法不治。勉用补中益气加半夏、茯苓。二剂有小效。众皆喜。余曰。涩象不减。脉法无根。死期近矣。果十余日而殁。", "3670": "震按此与梁厚斋案同一涩脉而死生不同者。彼惟尺脉浮大。按之则涩。此是六部沉涩。两尺尤甚。轻重自别也。况又云脉法无根。想是沉而细涩。按之欲绝耳。不然。哮嗽门中顾明华案。亦系涩脉。何以先补养而继吐下。仍能愈之耶。", "3671": "滑伯仁治一人。苦胸中痞满。愦愦若怔忡状。头目昏痛。欲吐不吐。忽忽善忘。时一臂偏痹。脉之。关以上溜而滑。按之沉而有力。曰。积饮滞痰。横于胸膈。盖得之厚味醇酒。肥腻炙爆。蓄热而生湿。湿聚而痰涎宿饮皆上甚也。王冰云。上甚不已。吐而夺之。但冬月降沉之令。未可行此法。乃候至春日晴朗。以药探吐之。大吐异色痰如胶饴者三四升。一二日更吐之。三四次则胸中洞爽矣。", "3672": "李古愚每食后即大便。腹皮稍胀急。胸膈饱闷。医与参、术。则痞闷愈甚。小水清而长。孙脉之。左寸涩。右寸滑。按之如黄豆大。且鼓指。关尺之脉皆弦小。左尺脉迢迢有神气。据脉。乃积痰郁滞于肺莫能出。以致大肠之气不固也。法当效丹溪治乃叔用吐。吐去上焦痰积。而大便自实矣。先用苦梗、莱菔子各三钱。白蔻仁、橘红、山栀仁各一钱。川芎五分。生姜三片。葱三根。煎服探吐。不能尽出。又以莱菔子一合擂浆水。加蜂蜜。与半碗饮之。始吐胶痰二碗。平日每小水则大便并行。吐后小水始能独利。连行三四次而胸腹宽舒。初亦以吐为惧。至是豁然称快。大便亦不频下矣。再以二陈汤加白术、旋覆花、麦芽。调理而全安。", "3673": "陈武塘曰。余长子揆。向患遗精。于天启丁卯冬。遗证大作。肾窍漏气。出如烟雾。时作时止。眠食渐减。形瘁骨痿。大便艰涩。其色颇黑。用猪胆汁入大黄、皂角末导之。初用甚快利。并上部诸火亦觉清息。延至戊辰六月。则愈导愈秘。因思胆汁、大黄苦寒。皂角刮削脂膏。故求润而弥燥。乃以猪胆去汁。入蜜同温水满之以为导。导久而便始不艰。然至戊辰八月后。不能起床。又至己巳五月。肌肉愈瘦。眠食愈减。胸膈如有物踞之。腹则空虚。上则痞闷。每食少许。辄停留不下。隔六七时犹嗳。呼吸之气。亦碍而不畅。以为因虚致滞。则服人参必增懑。以为稠痰蓄血。用疏快之剂又全无功。身常畏寒。夏令犹掩重帏。惟身不热。口不渴。声音虽轻而不变。面色白而不赤不黑。每日仅用粥饵二盏。或终日不食。旁人疑在旦暮。却又绵延两载。时名医高果哉、孙见心辰夕诊治无功。又延姑苏柯生。柯、大言人也。乍闻其论。不胜喜。及治罕效。乃追忆从前。大肠气数不禁。遂觉胸膈痞闷。继因过防衄证。日饮童便及滋清药太多。大便渐顺。然大便后即觉腹中虚怯。而胸膈分毫不宽。若大便所下甚多。则胸膈痞闷愈甚。于是疏上补下。茫无措手。远延镇江张承溪至。张诊二次。而曰男子久病。以太谿冲阳脉决其死生。今六部无险。太谿冲阳有根。必不死之脉也。其证名为下脱。凡阳气上绝。阴气不得上交于阳。则为下脱。阴窍漏气是也。阴气下绝。阳气不得下交于阴。则为上脱。耳中出气是也。方家以失血之证。为错经妄行。而不知气证亦有错经妄行者。盖肾纳气。过泻成虚。则肾气不能自纳。遂错行而妄漏。经云。醉饱入房。五脏反复。五脏部位。宁有反复之理。正谓其气错乱也。今未能提其气。复使归经。所以时漏不止。漏则气虚。气虚于下。则痰结于上。故饮食难化。而成郁结痞闷之证。今用药宜疏导郁滞。不宜误用滋阴。宜有提有降合成疏通。不宜专用顺气。若认此为阴亏之证。遂谓虚劳不受补者不治。则大误也。阴虚生内热。岂有阴分大虚。卧床一年有半。而不发骨蒸潮热者乎。滋阴之药。不惟无功。且于开胸膈。进饮食。有大碍。今但使膈间日宽一日。谷气日增一日。则阴不补而自补矣。气色可指日而待。煎方用苏子、山楂各二钱。橘红、半夏曲各一钱五分。茯苓、乌药、香附、五谷虫各一钱。升麻八分。柴胡四分。临服入韭汁二匙。此方疏郁为主。而升降互用。其旨颇精。服二十剂。虽不大效。然视向之服一药。增一病。则霄壤矣。秋初张别去。余因其疏郁大旨。为之推广通变。自定噙化丸。用人参六钱。醋制香附、橘红各四钱。贝母、桔梗各三钱。松罗茶二钱。白硼砂、西牛黄、干蟾炙存性各一钱。薄荷叶三分。以乌梅肉二钱蒸烂。同竹沥、梨膏为丸。每丸一钱。余因胸中结块。原起于午食后即卧。用噙化丸。使睡中常有药气疏通肺胃之间。彼将欲结。药往疏之。新结不增。旧结渐解。卧时成病。亦治以卧时。且病在膈上。不用汤之荡涤。丸之沉下。而用噙化。徐徐沁入。日计不足。月计有余也。服六七十丸后。膈间渐宽。尔时医家疑气坠之证。恐深秋逾剧。以秋金主降也。余谓肺主气。气得其令。则降者自降。升者自升。各得本职。非谓有降而无升也。能使清升浊降。则气坠之病。正宜愈于深秋。至八月。病人偶伤麦粉。下以沉香丸。忽去胶痰数升。胸膈顿爽。殆药力渐到。元气渐回。邪无所容。而乘势自下也。然气弱形羸。长卧不起如故。冬底。医家又防春来木旺。脾病转剧。余曰无忧。凡脾受肝克。则畏木气来侵。今乃脾困。而非脾弱。冬气闭塞。脾困所畏。幸喜及春。方藉木气以疏通之。已而食果稍增。肌亦渐泽。五脏之情。变化如此。第执生克之常。几何而不误人。庚午夏四月。张公复至。曰。胶痰去。病本拔矣。骨痿不能自行立者。湿气留伏脾经故也。投以白术煎。用白术一斤。苍术四两。作膏服之。未终剂立起。此病奇而久。约费千日之医治。竟得全生。故备志之。", "3674": "孙东宿治叶润斋。年近四十。心鬲嘈杂。好啖肉。尤好鸡。一日不能缺。缺即身浮力倦。神魂无措。必急得肉。见则大嚼。及入腹。腹又大痛。痛极则吐酸水稠涎然后定。稍定又思肉啖也。人疑为祟。孙诊之。六脉大小不等。观其色唇红脸黄。问之。则曰痛虽苦。尚能熬。若嘈杂则遍身淫淫苏苏。左右无可奈何。手足无所把捉。有近于死。急需肉以救命。孙曰。据色脉。乃虫证。非祟也。先予雄黄丸一服。不瘳。改以腻粉五分。使君子末一钱。用鸡子打饼。五更空心饲之。辰刻下长蛲十条。内有二大者。长尺余。下午又下小虫百余。自此不喜肉。而嘈杂良愈。", "3675": "薛立斋见一人呕吐痰涎。发热作渴。胸膈痞满。或用清气化痰降火。前证益甚。痰涎自出。薛曰。呕吐痰涎。胃气虚寒也。发热作渴。胃不生津也。胸膈痞满。脾气虚弱也。须用参、耆、归、术之类。温补脾胃。生发阳气。诸病自退。不信。仍服前药。虚证悉至。复请治。薛曰。饮食不入。呃逆不绝。泄泻腹痛。手足逆冷。是谓五虚。烦热作渴。虚阳发于外也。脉洪大。脉欲绝也。死期迫矣。或曰。若然。殒于日乎。殒于夜乎。薛曰。脉洪大。当殒于昼。果然。", "3676": "王中阳治一宦家妇人。忽患心腹冷痛。遂呕吐。去尽宿汁不已。而又吐清涎。如鸡子清之状。一呕一二升许。少顷再呕。百药不纳。咽唾亦不能顺下。已经三日。但聪明不昧。吩咐家事以待就木。王诊其脉。六部弦细而长。令服滚痰丸三十丸。并不转逆。须臾坐寐。移时索粥食之。次日再进三十丸。兼服局方茯苓半夏汤。再服钱氏白术散。饮食如旧。", "3677": "震按千金方载粥食汤药皆吐不停者。灸手间使穴三十壮。若四肢厥。脉沉绝不至者。灸之便通。查手间使穴。乃手厥阴穴。在掌后三寸。此如今人遇呕而不能纳药者。以手紧捻病人两手脉息。即可咽下。其法暗合。又宋人小说载。史载之治朱思古。闻荤腥即呕。惟以汤沃淡饭些少。时时食之。医莫能治。史曰。此证内经有之。名曰食挂。凡人之肺。六叶舒张。盖覆于脾。子母气和则进食。一或有戾。则肺不能舒。脾为之蔽。故不嗜食。遂用清气润肺药。服三日。病者鼻闻肉味觉香。取啖之甚美。此系邪说。江篁南谓非记者假托。即史公之妄言欺世。诚然。", "3678": "又一人不能顿食。喜频食。一日忽咽膈壅塞。大便燥结。脉涩。似真脏脉。喜其形瘦而色紫黑。病见乎冬。却有生意。以四物加白术、陈皮浓煎。入桃仁十二粒研。再沸饮之。更多食诸般血以助药力。四十余帖而便润。七十帖而食进。百帖而安。", "3679": "震按丹溪治噎膈反胃数条。皆以瘀血治而效。如一人因跌仆后。中脘即痛而起。一人食入必屈曲下膈。梗涩微痛。由腊月常饮点剁酒而起。其脉皆涩。皆以韭汁冷饮得愈。然系噎膈之渐。未成真病也。又如一人。勤劳而有艾妻。且喜酒。病反胃半年。脉涩不匀。重取大而无力。用新温牛乳细饮之。日夜八九盏。以滋精血。佐甘蔗汁以解酒毒。而安。一人多服金石房中药。病噎膈。得吐则快。脉涩。重取弦大。用竹沥御米煮为粥。频频少与之。遂不吐。继以米粥入竹沥。又继以四物加陈皮。月余而安。此皆病重药轻。不知何以奏捷如此。及考汪石山治噎膈案。一曰面青性急。肝木盛也。脉缓而弱。脾土虚也。用异功加神曲。少佐黄连。一曰脉皆浮洪弦虚。得之酒与劳。年逾六十。大虚证也。用人参三钱。白术、归身、麦冬各一钱。陈皮七分。香附六分。黄芩五分。白芍八分。干姜四分。黄连三分。煎服五帖。而脉敛膈宽。饮食能进。方为堂堂之阵。正正之旗。后当仰则于此。", "3680": "汪石山见一人。形瘦而苍。年逾五十。诊其脉皆弦涩而缓。尺脉浮而无根。曰。尺脉当沉反浮。病主肾水亏乏。其余脉皆弦涩而缓者。弦脉属木。涩为血少。缓。脾脉也。以脉论之。乃肝木凌脾而血液枯槁。当成噎膈证也。问之。胸膈微有碍。曰。不久膈病成矣。病成非药可济。后果病膈而卒。", "3681": "震按石山论脉。最为精细。若今人诊得弦涩而缓。必谓缓为有胃气。则生也。至如尺脉之浮而无根。或匆匆不及致群矣。", "3682": "李士材治邑宰张孟端夫人。忧怒之余。得食辄噎。膈中隐隐痛。李曰。脉紧且滑。痰在上脘。用二陈加姜汁、竹沥。曰半夏燥乎。李曰。湿痰满中。非此不治。遂用四剂。病尚不减。改大半夏汤。服四帖。胸痛乃止。又四帖而噎亦减。服二十剂而安。", "3683": "又治江右太学方春和。年近五旬。多欲善怒。患噎三月。日进粉饮一钟。腐浆半钟。且吐其半。六脉细软。此虚寒之候也。用理中汤加人乳、姜汁、白蜜、半夏。一剂便减。十剂而日进糜粥。更以十全大补加竹沥、姜汁四十帖。诸证皆愈。嘉定钱远之。二十五岁。以鼓盆之戚。悲哀过度。不能食饮。又十余日。粥亦不能食。随食随吐。二便闭涩。自谓必死。求诊于李。李曰。脉按有力。非死证也。以酒蒸大黄加桃仁、当归、砂仁、陈皮。蜜丸与服。凡五服而下燥屎干血甚多。病若失矣。数日之间。能食倍常。", "3684": "震按此非噎膈。不过忧忿而气闭血瘀。暂时关格耳。其所以易愈者。病暴起而脉有力也。若前二案。未必见效。", "3685": "易思兰治一人。胸膈胃脘饱闷。腹仍饥而不能食。腰腿酸疼。坐立战摇。日夜卧榻。大便燥结。每日虽进清粥一二钟。食下即呕吐酸水。醋心。众作膈治。不效。易诊左右寸关俱沉大有力。两尺浮中沉三候俱紧。按之无力。乃曰。此气膈病也。两寸居上。其脉当浮。今却沉大。左寸沉者。神之郁也。右寸沉者。气之郁也。大者火也。气有余即是火。火郁在上。故胸膈饱闷。凡汤水入咽。逆而不下。停于胃口。为火熏蒸。而成酸水矣。两尺俱紧者。此又寒邪从虚而入。主腰腿酸疼。坐立战摇而不能起矣。法当开导其上。滋补其下。乃以越鞠丸加苏梗、桔梗、木香、沙参、贝母作汤服。以畅卫舒中。火郁发之之义也。另用八味丸以补下焦。又塞因塞用之法也。服数日。上则嗳气。下转失气。可以纳谷而自立矣。", "3686": "周慎斋治一人。年五十五。胸前微痛。无休息时。六脉俱无胃气。惟胃脉略缓。盖胸中受气于丹田。时时心下微痛。乃丹田阳气不到胸中。膈气无疑。脾脉微缓。调理脾胃。犹可迁延。保元汤加山药、沉香。", "3687": "沈锡蕃平昔大便燥结。近患噎膈月余。虽素禀丰腴。日来面色皎白。大非昔比。时方谷雨。正此证危殆之际。始求治于石顽。诊得六脉沉涩。按久则衰。幸举指即应。为疏六君子汤下一味狗宝作散调服。甫十剂而呕止食进。再二十剂而谷肉渐安。起居如故。惟大便尚觉艰难。乃以六味丸去泽泻。加归、芍、首乌作汤。服至月余。便溺自如。秋深更服八味丸。三月而康。大抵噎膈之人。体肥痰逆者可治。枯癯津衰者多不可治。同时有同道王公峻患此。禀气病气。与沈相类。误信方士。专力委之。而致不起。顾人月亦患此证。自谓胀急。不当用参。日服仙人对坐草而毙。郭孝闻八月间噎食艰进。六脉弦劲搏指。延至来春三月。告殂。然瘦人间有可疗者。昔秦伯源噎膈。形神枯槁。神志郁抑。且不能胜汤药之费。予门人邹恒友。令其用啄木鸟入麝熬膏。时嗅其气以通其结。内服逍遥散加香、砂以散其郁。不数剂。所患顿除。厥后海货行陈君用噎膈。亦用此法而愈。两君至今。色力尚强。又一农人噎膈不食。时呕清涎如赤豆沙水。此属血瘀于内可知矣。庸师不审。误用消克破气药。而致绝粒不食。其邻叟怜之。述伊病苦。求救于予。遥拟一方。用桂苓饮加当归、桃仁、丹皮、牛膝。以熬枯黑糖和䗪虫浆调服。下溏黑如污泥者甚多。当知农人戮力受伤。血郁于内而致呕逆。但当攻其积血。呕逆自已。孰谓治病不求其本。而可轻议其药哉。", "3688": "吕元膺治一僧病。诊其脉。独右关浮滑。余部无恙。曰。右关属脾络胃。挟舌本。盖风中廉泉。得之醉卧当风而成喑。问之而信。乃取荆沥化至宝丹饮之。翌日遂解语。", "3689": "丹溪治一中年男子。伤寒身热。医与伤寒药。五七日。变神昏而喑。遂作本体虚有痰治之。人参五钱。黄耆、白术、当归、陈皮各一钱。煎汤。入竹沥姜汁饮之。十二日。其舌始能语一字。又服之半月。舌渐能转运言语。热除而痊。盖足少阴脉挟舌本。脾足太阴之脉连舌本。手少阴别脉系舌本。故此三脉虚。则痰涎乘虚闭塞其脉道。而舌不能转运言语也。若此三脉无血。则舌无血营养亦喑。经曰。刺足少阴脉。重虚出血。为舌难以言。又言刺舌下中脉太过。血出不止为喑。治当以前方加补血药也。一男子五十余岁。嗜酒。吐血后。不食。舌不能言。但渴饮水。脉略数。与归身、芍、地各一两。参、术二两。陈皮一两五钱。甘草二钱。入竹沥、童便、姜汁少许。二十余帖。能言。若此三脉。风热中之。则其脉弛纵。故舌亦弛纵。不能转运而喑。风寒客之。则其脉缩急。故舌卷而喑。在中风半身不收求之也。", "3690": "震按此三条皆治舌喑。非喉喑也。首条化痰通窍。是实证。次条伤寒五七日神昏而喑。岂无实热证。用大黄、黄连、石膏者耶。而猥云作体虚有痰治也。魏注云。恐热传少阴心经。此案不可为训。极是。但细读之。案中不载舌干胎黑便秘烦躁等证。则所谓神昏者。身热人静而嘿嘿耳。且必有欲言不能言之状也。其脉亦必濡滑无力也。参、耆、术服之数日病无进退。即可知其对证。观于十二日舌始语得一字。又半月而舌能言。热乃退。全绘一虚证情形矣。凡遇伤寒舌喑者。宜以此条寻绎之。勿竟以陶氏热传手少阴心经句笼统为治。第三条吐血后不食。舌不能言。是虚证无疑矣。渴饮水。脉带数。不与滋阴而与参、术。翁之见识高哉。", "3691": "王惟一数年前虽有血证。而年壮力强。四月间。忽患咳嗽。服发散药后。痰中见血数口。继服滋阴药过多。遂声飒而哑。时觉胸中气塞。迁延月余。邀张路玉诊之。脉虽沉涩。而按之益力。举之应指。且体丰色泽。绝非阴虚之候。张曰。台翁之声哑。是金实不鸣。非金破不鸣之比。因疏导痰汤。加人中黄、泽泻。专一涤痰为务。四剂后。痰中见紫黑血数块。其声渐出而飒未除。更以秋石兼人中黄、枣肉丸服。经月而声音清朗。始终未尝用清理肺气。调养营血药也。", "3692": "丹溪治一男子。三十五岁。因连夜劳倦不得睡。感嗽疾。痰如黄白脓。嗽声不出。时初春大寒。医与小青龙汤四帖。觉咽喉有血腥气上逆。遂吐血线自口中左边出一条。顷遂止。如此每一昼夜十余次。诊其脉弦大散弱。左大为甚。人倦而苦于嗽。丹溪云。此劳倦感寒。因服燥热之剂以动其血。不急治。恐成肺痿。遂与参、耆、术、归、芍、陈皮、炙甘草、生甘草、不去节麻黄。煎成。入藕汁。服两日而病减嗽止。却于前药去麻黄。又与四帖。而血证除。脉之散大未收敛。人亦倦甚。食少。遂于前药去藕汁。加黄芩、砂仁、半夏。至半月而安。", "3693": "丹溪治一人。年五十余。患咳嗽。恶风寒。胸痞满。口稍干。心微痛。脉浮紧而数。左大于右。盖表盛里虚。问其素嗜酒肉。有积。后因接内。涉寒冒雨忍饥。继以饱食酒肉而病。先用人参四钱。麻黄连根节一钱五分。与二三帖。嗽止寒除。改用厚朴、枳实、青陈皮、栝蒌、半夏为丸。参汤送下。痞除。", "3694": "震按咳嗽痰血声不出。今人不过养阴清肺而已。有敢用吐下药者哉。又敢用参、耆、归、术、麻黄者哉。至如暴嗽恶风寒。其脉证皆属表邪。而其因则系里虚。今人不过轻剂散之和之而已。敢以人参、麻黄并用哉。然非麻黄、人参并用。势必淹缠日久。合于伤风不醒积成痨之说矣。可见善医者法门广大无边。不善医者小心与大胆均误也。", "3695": "汪石山治一妇。年三十。质弱。产后咳嗽痰臭。或作肺痈治。愈剧。两脚渐肿至膝。大便溏泄。小腹胀痛。午后发热。面红气促。不能向右卧。汪诊脉虚小而数。曰。凡咳嗽左右向不得眠者。上气促下泄泻者。发热不为泻减者。皆逆候也。按此病原于脾。经曰。脾主诸臭。入肺为腥臭。入心为焦臭。入肝为腐臭。自入为秽臭。盖脾不能运行其湿。湿郁为热。酿成痰之臭也。经曰。左右者。阴阳之道路。脾虚则肺失所养。气劣行迟。壅遏道路。故咳嗽气促。不能右卧也。脾虚必夺母气以自养。故心虚发热而见于午也。脾主湿。湿胜则内渗于肠胃为溏泄。外渗于肌肉为浮肿。今用参、术、甘草补脾为君。茯苓渗湿为臣。麦冬保肺气。枣仁安心神为佐。陈皮、前胡消痰下气为使。东壁土受阳气最多。用之为引。盖土能解诸臭。亦能补土。取钱氏黄土汤之义也。服一帖。前病略减。病者喜。汪曰未也。过时失治。午后发热。真阳脱矣。泄而脚肿。脾气绝矣。必数服后无反复。方是佳兆。", "3696": "一人年十九。面白质弱。因劳思梦遗。遂吐血碗余。自是微咳倦弱。后忽身发大热。出疹。疹愈。阴囊痒甚。搓擦水流。敷以壁土。囊肿如盏大。遂去土。以五倍子涂少蜜。炙燥为末敷之。遂愈。复感风寒。其嗽尤甚。继以左右胁痛。石山诊其脉虚而数。外证畏风寒。呕恶。倦动。粪溏气促。曰。此金极似火也。夫心属火而藏神。肾属水而藏志。二经俱属少阴。而上下相通。今劳思则神不宁而梦。志不宁而遗。遗则水不升而火独亢也。肝属木。主藏血。其象震。震为雷。心火既亢。同类相应。引动龙雷之火。载血而溢出于上窍矣。肝脉环绕阴器。亦因火扰而痛痒肿胀也。火胜金。故肺经虚而干咳。皮毛为肺之合。更因火郁而发疹。大肠为肺之府。故亦传导失宜而粪溏。金虚不能平木。木火愈旺而凌脾。脾虚则呕恶食减。经曰。壮火食气。脾肺之气为壮火所食。故倦于动作。而易感风寒也。经言。两胁者阴阳往来之道路也。为火阻碍。则气不利而痛矣。然火有虚有实。有似火而实非火。故经言有者求之。无者求之。虚者责之。实者责之。此治火大法。前证之火。皆虚火也。非水湿所能折。惟甘温之剂。可以祛除。且经言形寒饮冷则伤肺。又谓脾胃喜温而恶寒。当用甘温健其脾。则肺经不虚。而咳嗽气促自愈。肝木有制。而咳嗽吐血自除。虚妄之火亦自息矣。以参耆各四钱。神曲、山楂各七分。白术、麦冬、贝母各一钱。甘草五分。炒干姜四分。服十余帖。脉数减。嗽渐平。", "3697": "震按此证似宜养阴。其复感风寒。似宜清理。即见识高者。亦必先以轻剂解表。后用养阴健脾。乃汪公竟进参、耆各四钱。佐干姜少许。岂今人所能及哉。脉数减。嗽渐平。信非熟地、阿胶所能胜任。", "3698": "震按此条不载脉象。以意度之。脉必虚数。观前医之用芩、连。脉数可知矣。若脉虚软不数。谁不能用六君、八味哉。汪薛二公高处在此。然又不可奉为秘诀。请阅后述诸案。便知法非一例。", "3699": "李士材治太学史明粦。经年咳嗽。历医无效。自谓必成虚痨。李曰。不然。脉不数不虚。惟右寸浮大而滑。是风痰未解。必多服酸收。故久而弥盛。用麻黄、杏仁、半夏、前胡、桔梗、甘草、橘红、苏子。五剂知。十剂已。", "3700": "孙东宿治许卓峰。多酒多怒人也。上吐血。下溲血。咳嗽声哑。医皆以为瘵。辞不治。孙诊其脉。左关弦大。右寸下半指。累累如薏苡子状。乃曰。此有余证也。作瘵治者非。盖其人好酒。酒属湿热。助火生痰。火性炎上。迫肺不降。积而生痰。壅于肺窍。以致失音。此痰壅之哑。非肺痿之哑也。其性又多怒。怒气伤肝。故血妄行而不归经。以致吐血尿血。法宜清热开郁化痰。导血归原。若二地、二冬辈滋阴之药。反助其塞而益其热。声音何由而开。况血随气行。气不清。血又何得归原哉。乃用滑石、青蒿。解酒热为君。贝母、郁金、山栀仁、香附。开郁为臣。杏仁、桔梗、丹皮、丹参、小蓟、甘草。化痰清血为佐使。服十帖。血果止。又以贝母一两。童便浸一日。为末。柿霜等分。时时抄舌上化下。五日而声音爽矣。", "3701": "张路玉治包山金孟珍。正月间。忽咳吐清痰。咽痛。五六日后。大便下瘀晦血甚多。延至十余日。张诊其脉。六部皆沉弦而细。此水冷金寒之候也。遂与麻黄附子细辛汤。其血顿止。又与麻黄附子甘草汤。咽痛亦可。而觉心下动悸不宁。询其受病之源。乃醉卧渴引冷饮所致。改用小青龙去麻黄加附子。悸即止。咳亦大减。但时吐清痰一二口。乃以桂、酒制白芍。入真武汤中与之。咳吐俱止。尚觉背微恶寒倦怠。更与附子汤二剂而安。", "3702": "震按咽痛下血。不以风火治。而以辛温燥热药始终获效者。由其善于识脉也。", "3703": "又治礼科姜如农长媳。喘咳无痰。灼热自汗。而怀妊七月。先曾服和解清肺药二十余剂。其咳转剧。胎渐不安。邀张诊之。六脉皆濡大无力。右手寸关独盛而涩。曰。此热伤肺气也。反与和解药。逼令汗出。致肺气益燥而咳逆愈甚。不得已。复用苦寒折之。则火转郁伏而不散也。遂用大剂葳蕤。及川芎、杏仁、白薇、甘草。取葳蕤汤之半。更以当归、桔梗、五味、黄耆。益气生津。固肌敛肺。二剂汗止咳减。胎亦向安。更加生诃子皮。四剂而痊。", "3704": "又治吴佩玉次女。伤风咳嗽。先前自用疏风润肺止嗽之药。不应。转加呕渴咽痛。石顽诊之。六脉浮滑应指。因与半夏散三啜而病如失。或问咳嗽咽痛而渴。举世咸禁燥剂。今用半夏辄效。何也。曰。用药之权衡。非一言而喻也。凡治病必求其本。此风邪挟饮上攻之暴嗽。故用半夏、桂枝。开通经络。迅扫痰涎。兼甘草之和脾胃而致津液。风痰散。营卫通。则咽痛燥渴自已。设泥其燥渴而用清润。滋其痰湿。经络愈壅。津液愈结。燥渴咽痛。愈无宁宇矣。不独此也。近世治风寒咳嗽。虽用表药。必兼桑皮、黄芩、花粉。甚则知、柏之类。少年得之。必种吐血虚损之根。中年以后得之。多成痰火喘嗽之患。然此辈之妙用。在于预为地步。诊时泛谓阴虚。防变不足之证。初时元气未衰。服之邪热暂伏。似觉稍可。久之真气渐伤。转服转甚。安虑其不成虚损耶。及见吐血。则不问何经腑脏。属火属伤。血之散结。色之晦鲜。瘀之有无。概以犀角地黄寒凉止截之剂投之。致血蓄成根。向后或二月一月一发。虽日服前药不应矣。凡此之类。未遑枚举。尝见一人患项肿发热。延伤寒家视之。则曰大头伤寒。以表药发之。并头亦胀。确然大头无疑矣。病家以其治之益甚。又延杂证家视之。则曰湿热痰火。以里药攻之。则头与项前左半皆消。但项后右侧偏肿。则又确乎非大头而为杂证矣。病家又以肿在偏旁。疑为痈毒。更延痈疽家视之。则曰对口偏疽。以托里敷外药治之。则气血益滞。热不得泄。郁遏竟成溃疡矣。本一病也。治之迥异。证亦屡迁。可见其病随药变之不诬耳。第末俗所趋。非此不足以入时。何怪乎圣人性命之学。沦胥不返。遂至若是耶。", "3705": "朱丹溪治一人。病喘不得卧。肺脉沉而涩。此外有风凉湿气。遏其内热不得舒。以黄芩、陈皮、木通各一钱五分。苏叶、麻黄、桂枝各一钱。生姜、黄连各五分。甘草二分。煎服数帖而愈。", "3706": "又治吴辉妻孕时足肿。七月初旬。产后二日。因洗浴即气喘。但坐不得卧者五月矣。恶寒。得暖稍宽。两关脉动。尺寸皆虚无。百药不效。朱以丹皮、桃仁、桂枝、茯苓、干姜、五味、枳实、厚朴、桑皮、紫苏、栝蒌实煎服。一服即宽。三服得卧。病如失。盖作污血感寒治之也。", "3707": "震按首案宜用定喘汤。此方尚未妥贴。以黄连与沉涩脉不合也。次案用药似杂。而与病情恰对。毫无可议。丹溪尚有一案。身痛与气喘并作。已收在痛风门。可以同阅。", "3708": "汪石山治一人。体肥色白。年近六十。痰喘声如曳锯。夜不能卧。汪诊之。脉浮洪。六七至中或有一结。曰。喘病脉洪。可治也。脉结者。痰碍经隧耳。宜用生脉汤加竹沥。服之至十余帖。稍定。患者嫌迟。更医用三拗汤、五拗汤。势渐危。于是复以前方。服至三四十帖。病果如失。", "3709": "又治一妇人。年五十余。素有嗽病。忽一日大喘。痰出如泉。身汗如油。脉浮而洪。似命绝之状。令速用生脉散一帖。喘定汗止。三帖后。痰亦渐少。再于前方加栝蒌实、白术、黄芩、当归、芍药。服二十帖而安。", "3710": "又一人年逾六十。病气喘。汪诊之。脉皆萦萦如蛛丝。曰。病不出是夜矣。果如期而逝。", "3711": "震按石山三案。以脉洪为可治。脉微细为不治。所当著眼。", "3712": "又一人形长。色苍瘦。年四十。每秋凉病痰嗽气喘不能卧。春暖即安。病此多年。医用紫苏、薄荷、荆芥等以发表。用桑皮、石膏、半夏等以疏内。虽暂轻可。不久复作。汪诊之。脉颇洪滑。此内有郁热也。秋凉则皮肤致密。内热不能发泄。故病作矣。内热者。病本也。今不治其本。徒用发散以虚其外。则愈不能当风寒。疏内以耗其津。则愈增郁热之势。遂进三补丸加大黄、贝母、栝蒌。丸服。仍令每年立秋。先服滚痰丸四十粒。病渐安。", "3713": "又一妇年五十。形色脆弱。每遇秋冬。痰嗽气喘。自汗体倦。或恶心作呕。汪诊之。脉皆浮缓而濡。曰。表虚不御风寒。激内之郁热而然。遂用参、耆各三钱。麦冬、白术各一钱。黄芩、归身、陈皮各七分。甘草、五味各五分。煎服十余帖而安。次年秋间。滞下。腹痛后重。脉皆濡细稍滑。汪曰。此内之郁热欲下也。体虽素弱。经云。有故无殒。遂以小承气利两三次。腹痛稍除。后重未退。再以补中益气加枳壳、黄芩、芍药煎服。仍用醋浇热砖。布裹。坐之而愈。", "3714": "震按秋凉喘嗽之证。近日甚多。若外寒束其内热。不过此证中之一种耳。然已虚实不同如此。故必辨之以脉。乃无差误。", "3715": "又治孙芳其令嫒。久嗽而喘。凡顺气化痰。清金降火之剂。几于遍尝。绝不取效。一日喘甚烦躁。李视其目则胀出。鼻则鼓扇。脉则浮而且大。肺胀无疑矣。遂以越婢加半夏汤投之。一剂而减。再剂而愈。李曰。今虽愈。未可恃也。当以参术补元。助养金气。使清肃令行。竟因循月许。终不调补。再发而不可救矣。", "3716": "孙东宿治少司空凌绎泉。年已古稀。原有痰火之疾。正月初。因劳感冒。内热咳嗽。痰中大半是血。鼻流清水。舌胎焦黄芒刺。语言强硬不清。大小便不利。喘急不能睡。亦不能仰。以高桌安枕。日惟额伏枕上而已。医治半月不瘳。孙诊之。两手脉浮而洪。两关滑大有力。知其内有积热痰火。为风邪所闭。复为怒气所加。故血上逆。议者以高年见红。脉大发热为惧。孙曰。此有余证。诸公认为阴虚而用滋阴降火。故不瘳。法当先驱中焦痰火积热。后以地黄补血等剂收功。可也。乃以栝蒌、石膏各三钱。半夏曲、橘红、桑皮、前胡、杏仁、酒芩、苏子水煎。冲莱菔汁一小盏。一剂而血止。次日诊之。脉仍浮而洪大。尚恶寒。此因先时不解表。竟用滋阴。又加童便降下太速。以致风寒郁而不散。故热愈甚也。改以定喘汤。一剂而喘减。二剂而热退不恶寒。再诊之。两手浮象已无。惟两关脉鼓指。此中焦痰积胶固。不可不因其时而疏导之。以清中丸同当归龙荟丸共二钱进之。其夜下稠黏秽积甚多。予忆丹溪有云。凡哮喘火盛者。白虎汤加黄连、枳实有功。正此证对腔法也。与十剂。外以清中丸同双玉丸夜服。调理而安。", "3717": "喻嘉言治施眉苍肺痿喘嗽。吐清痰。肢体痿软不能举动。脉来虚数。以蛤蚧二十枚酒浸酥炙。人参、黑参各十两。蜜丸。时时噙化。不终剂而痊。", "3718": "孙起伯肺胀。服耗气药过多。张路玉诊之。脉浮大而重按豁然。饮食不入。幸得溺清便坚。与局方七气。每剂用人参三钱。肉桂、半夏曲、炙甘草各一钱。生姜四片。四剂霍然。盖肺胀实证居多。此脉虚大。不当以寻常论也。", "3719": "又治一尼肺胀。喘鸣肩息。服下气止嗽药不应。渐至胸腹胀满。脉得气口弦细而涩。此必劳力气上。误饮冷水伤肺。肺气不能收敛所致也。遂与越脾汤减麻黄。加细辛、葶苈。大泻肺气而安。", "3720": "震按此方加减最巧。上案用七气汤成方亦巧。观其论脉溯因。而细心体贴之。乃知其巧。予邑有友范君。哮喘已久。向用金匮肾气丸。时效时不效。吴门缪松心先生诊之曰。伏饮内踞有年。明是阳衰浊泛。但绵延日久。五旬外。痰中杂以血点。阴分亦渐损伤。偏刚偏柔。用药两难措置。仿金水六君煎意。用熟地炭四钱。当归炭一钱。茯苓三钱。炙草四分。川贝一钱半。青盐、陈皮一钱。淡菜漂三钱。杏仁三钱去皮尖盐水炒。半月后复诊。晨用金匮肾气丸以治本。晚服苓桂术甘加味以治标。生于术米泔浸切片晒三两。粗桂木晒八钱。炒半夏二两。云苓三两。炙草六钱。杏仁霜一两六钱。鹿脊骨三两。用麻黄四钱煎汤。炙北细辛三钱晒。水泛丸。此证向来背脊畏寒。甚则哮发。服此方而畏寒除。隔三年。忽起淋浊。茎中痛胀。缪曰。此新病。以泻丙出壬为正治。但素有痰饮。滋腻之品。伤阳助湿。究非所宜。当变法治。庶与本证无碍。羊脊骨五钱。小木通一钱。盐水炒黄柏三分。生甘草梢五分。赤白茯苓各半三钱。水飞辰砂五分。调入服。三剂淋浊即愈。半年后改定丸方。曰。饮踞中焦。历年已久。前主温煦太阳寒水之脏。与病机极合。用药可无事更张。第溺管有精淋。由来已非旦夕。虽云肾气不坚所致。其降多而升少。亦非所宜。今造一方以兼顾之。嫩毛鹿角二两镑。羊脊骨三两炙黄打碎。生菟丝子三两晒。北细辛三钱晒。生黄耆皮一两五钱晒。蜜水炙麻黄三钱。桂枝粗木七钱晒。生于术米泔水浸晒干三两。茯苓三两晒。炙黑甘草五钱炒黄。半夏一两五钱。杏霜一两五钱。橘红一两晒。为末。用苡仁煮浆糊丸。后隔数年。已六旬余。换丸方用熟地四两水煮。归身一两五钱。制半夏炒黄一两半。云苓三两。橘红晒一两。炙黑甘草五钱。生台术三两米泔水浸生用。嫩毛鹿角一两五钱。蛤蚧两对去头足炙。熟附子七钱。淮牛膝一两四钱。生左牡蛎二两研细水飞。羊脊骨三两炙黄打碎。杏仁三两去皮尖油。北细辛三钱晒。泽泻一两五钱炒。为末。苡仁煮浆捣丸。以上诸方。摄纳肾阳。温通督脉。疏刷肺气。开豁浊痰。标本悉能照顾。巧更极矣。宜乎服之而宿疾全瘳也。", "3721": "罗谦甫治不潾吉歹元帅夫人。年逾五旬。身体肥盛。值八月中霖雨不止。因饮酒及潼乳过度。遂病腹胀喘满。声闻于外。不得安卧。大小便涩滞。气口脉大。两倍于人迎。关脉沉缓而有力。因思霖雨之湿。饮食之热。湿热大盛。上攻于肺。所谓盛则为喘也。邪气盛则实。实者宜下之。为制平气散。内经曰。肺苦气上逆。急食苦以泻之。白牵牛苦寒。泻气分湿热上攻喘满。故用二两。半生半熟以为君。陈皮苦温。体轻浮理肺气。用五钱。青皮苦辛平。散肺中滞气。用三钱以为臣。槟榔辛温。性沉重。下痰降气。亦用三钱。大黄苦寒。荡涤满实。用七钱以为使。末服三钱。生姜汤调下。两服而喘愈。止有胸膈不利。烦热口干。时时咳嗽。以泻白散加知母、黄芩、桔梗、青皮全愈。", "3722": "程明佑治张丙中满气喘。众医投分心气饮、舟车丸。喘益甚。一医作气虚治。以参、耆补之。喘急濒死。程诊其脉沉而滑。曰。此痰病也。痰滞经络。脏腑痞塞。致生䐜胀。投滚痰丸。初服。腹雷鸣。再服。下如鸡卵者五六枚。三服。喘定气平。继以参苓平胃散出入。三十日而安。", "3723": "沈宗常治卢陵人。胀而喘。三日食不下咽矣。视脉无他。问何食饮。对以近食羊脂。沈曰。得之矣。脂冷则凝。温熨之所及也。温之。得利而愈。", "3724": "震按古人治病多用针灸。今则针灸有专家。凡诊脉处方者。反以卑术视之。不知处方易而针灸难。盖切脉与取穴同一难。而取穴之难。尤难于切脉也。孙真人之言。诚为格言。", "3725": "震按此妄言也。蛇长二尺。重几斤。何以不啮破肠胃耶。子和不过引为偶得吐法耳。然荒唐无证。所谓吐下之神功。大率类此。又阅孙一奎与吴生问答一条。载生之堂嫂。病臌三载。腹大如箕。时或胀痛。四肢瘦削。三吴名医历治不瘳。吴俗死者。多用火葬。烧至腹。忽响声如炮。虫从腹中爆出。高二三丈。烧所之天为昏。俄而坠地。细视之。皆蛔也。不下千万。大者长尺余。虫腹中复生小虫。甚多不可数。而一奎又于万历癸巳至淮阴。有王乡官者。子年十六。新娶后。腹胀大。按之有块。形如削瓜。四肢瘦削。发热昼夜不退。已半年矣。医惟以退热消胀之剂投之。其胀愈甚。其热愈炽。喉中两耳俱疮。诊之。脉滑数。其唇则红。其腹则疼。又多嗜肥甘。因思诸凡腹痛者。唇色必淡。不嗜饮食。今其若此。得非虫乎。遂投以阿魏积块丸。服之果下虫数十。大者二。一红一黑。长尺余。虫身经线自首贯尾。虫腹中复有虫。大者数条。小者亦三四条。虫下则热渐减。胀渐消。三下而愈。始信吴生之言为不虚。", "3726": "震观此二则。较子和之说。稍觉近理。然蛔虫不下千万数。亦属荒唐。第其辨证则佳矣。较之客座新闻载江阴训导治生员腹胀。曰脉洪而大。湿热生虫之象。况饮食如常。非臌胀也。以石榴椿树两项东行根皮。加槟榔各五钱煎服。泻下一长虫而愈者。相似。", "3727": "丹溪曰。杨兄年近五十。性嗜酒。病疟半年。患胀病。自察必死。来求治。诊其脉弦而涩。重则大。疟未愈。手足瘦而腹大如蜘蛛状。予教以参、术为君。归、芍、川芎为臣。黄连、陈皮、茯苓、厚朴为佐。生甘草些少。作浓汤饮之。一日服三次。彼亦严守禁忌。一月后。疟因汗而愈。又半年。小便长而胀愈。中间虽稍有加减。大意只是补气行湿而已。", "3728": "又治一女子。禀厚。患胸腹胀满。自用下药。利十数行。胀满如故。脉皆大。按则散而无力。朱曰。此表证。反攻里。当死。赖质厚。时又在室。可救也。但寿损矣。以四物加参、术、陈皮、炙甘草。煎服。至半月尚未退。自用萝卜种煎浴一度。又虚其表。遂以前方去芍药、地黄。加黄耆。倍白术。大剂浓煎饮之。又以参为丸吞之。十日后。乃得如初病时。然食难化而自利。以参、术为君。肉果、诃子为臣。稍加陈皮、山楂为佐使。粥丸吞之。四五十帖而安。又治陈时叔。年四十余。性嗜酒。大便时见血。于春间患胀。色黑而腹大。其形如鬼。诊其脉数而涩。重似弱。属阴虚。朱以四物汤加芩、连、木通、白术、陈皮、厚朴、生甘草作汤与之。近一年而安。", "3729": "震按丹溪三条。一用参术加血药寒药。一用参术加血药温药。一用血药加寒药。用术去参。切贴脉证以治。井井有条。可为后世师法。但前后两条一嗜酒病疟。一嗜酒便血。营阴先亏。自当参用四物。若女子脉大而散。何以不用附子。而犹用四物耶。总之。丹溪善用补药。慎用热药。其慎处亦极是。如述其友俞仁叔。年近五十。得腹胀。自制禹余粮丸服之。丹溪诊其脉。弦涩而数。曰。此丸新制。煅炼之火邪尚存。温热之药味太多。宜自加减。不可执方。病者曰。此方不可加减。服之一月。口鼻中出黑血。骨立而死。此先几之见。亦难及矣。即此三证。皆以持久得愈。非老手断不能。", "3730": "项彦章治一女。腹痛。胀如鼓。四体骨立。其六脉弦滑而数。项曰。弦为气结。滑为血聚。此气薄血室。实邪也。其父曰。服芎归辈血药多矣。曰。失于顺气也。夫气。道也。血。水也。气一息不运。则血一息不行。故治血必先顺气。俾经隧得通而后血可行。乃投苏合香丸。三日而腰作痛。曰。血欲行矣。以硝黄逐之。下瘀数十块而愈。又二女病同。一脉虚。一脉纯弦。皆辞不治。果死。", "3731": "薛立斋治一男。素不善调摄。唾痰口干。饮食不美。服化痰行气之剂。胸满腹胀。痰涎愈甚。服导痰理脾之剂。肚腹膨胀。二便不利。服分气利水之剂。腹大胁痛。不能睡卧。服破血消导之剂。两足皆肿。脉浮大不及于寸口。朝用金匮肾气丸。夕用补中益气汤。煎送前丸。月余。诸证渐退。饮食渐进。再服月余。自能转侧。又两月而能步履。却服大补汤、还少丹。又半载而康。后稍失调理。其腹仍胀。服前药即愈。", "3732": "汪石山治一妇。年逾四十。瘦长善饮。诊之脉皆洪滑。曰可治。脉诀云。腹胀浮大。是出厄也。此湿热太重。宜远酒色。可保终吉。遂以香连丸。令日吞三次。每服七八十丸。月余良愈。", "3733": "又治一人。年三十余。病水肿。面光如胞。腹大如箕。脚肿如槌。饮食减少。汪诊之。脉浮缓而濡。两尺尤弱。曰。此得之酒色。宜补肾水。家人骇曰。水势如此。视者不曰通利。则曰渗泄。先生乃欲补之。水不益深耶。汪曰。经云。水极似土。正此病也。水极者。本病也。似土者。虚象也。今用通利渗泄。则下多亡阴。肾水益耗。是愈伤其本病。而增湿土之势矣。岂知亢则害。承乃制之旨乎。遂令空腹服地黄丸。再以四物汤加黄柏、木通、厚朴、陈皮、参、术。煎服十余帖。肿遂减半。三十帖而愈。", "3734": "震按汪公论病甚佳。用药非是。就此脉证。宜六君子汤送济生肾气丸。何反用地黄丸、四物汤阴湿柔黏之药。岂以脉之缓濡为湿热。故更佐以黄柏耶。三十帖愈。未敢深信。", "3735": "一妇形弱瘦小。脉细濡近快。一妇身中材颇肥。脉缓弱无力。俱病鼓胀。大如箕。垂如囊。立则遮拦两腿。有碍步履。石山视之。曰。腹皮宽。缒已定。非药可敛也。惟宜安心寡欲。以保命耳。后皆因产而卒。或曰。病鼓胀有孕。何也。汪曰。气病而血未病也。产则血亦病。阴阳两虚。安得不亡。又一妇鼓胀如前。越十余年无恙者。由寡居无所损也。", "3736": "震按准绳及治法汇皆引此条。以其议论高爽。能发内经之精微也。惜不言脉。愚意其脉必细而紧。或沉而涩也。若滑大数实。则此方不可用矣。喻嘉言治刘泰来。年三十二岁。面白体丰。夏月常用冷水灌汗。坐卧巷曲当风。新秋病疟截早。变成胀满。二便俱闭。气喘不食。能坐不能卧。能俯不能仰。势甚危急。医以二便不通。服下药不应。商用大黄二两作一剂。喻曰。伤寒病因发热。致津液枯槁。肠胃干结。乃用下药以开其结。然有不转失气者。不可攻之戒。正恐误治太阴经之腹胀也。此病因腹中之气散乱不收。故津水随气横决四溢而作胀。全是太阴不能统摄。一散一结。相去天渊。再用大黄猛剂。大散其气。若不胀死。定须腹破矣。病者曰。大黄服过二剂。尚未见行。奈何。喻曰。腹中真气渐散。今晚子丑二时。阴阳交剥之界。必大汗晕眩。难为力矣。急投理中汤。用人参至三钱。次日略加黄连。其胀大减。犹以不大便为忧。喻曰。腹中原是大黄推荡之泄粪。其所以不出者。以膀胱胀大。将大肠撑紧。任凭极力努挣。无隙可出耳。吾当以药通膀胱之气。不治大便而大便自至也。用五苓散。药才入喉。小便先出。大便随之。顷刻泄下半桶。", "3737": "震读此案。不禁拍案叫绝。只恨不载脉象若何。难以摩仿。且案末不载胀愈。并有慨叹语气。想未必收功也。但议论高爽。不减赵氏。并录于此。以作胀病之大训天球。", "3738": "赵氏又曰。嘉定沈氏子。年十八。患胸腹身面俱胀。医治半月不效。余诊其脉。六部皆不出也。于是用紫苏、桔梗之类。煎服一盏。胸有微汗。再服。则身尽汗。六部和平之脉皆出。一二日。其证悉平。", "3739": "傅滋治一人。能大餐。但食肉必泄。忽头肿。目不可开。膈如筑。足麻至膝。恶风。阴器挺长。脉左沉。重取不应。右短小。却和滑。令单煮白术汤空心服探吐之。后以白术二钱。麻黄、川芎各五分。防风三分。作汤下保和丸五十丸。吐中得汗。上截居多。肿退眼开。气顺食进。以前方去麻黄、防风。加白术三钱。木通、甘草各五分。下保和丸五十丸。五日而安。", "3740": "太学何宗鲁。夏月好饮水。一日学院发放。自早起候至未申。为炎威所逼。饮水计十余碗。归寓便胀闷不能食。越旬日。胀如抱瓮。气高而喘。士材曰。皮薄而光。水停不化也。且六脉坚实。其病暴成。法当利之。遂以舟车丸。每服三钱。香薷汤送。再剂而二便涌决如泉。复进一钱五分。腹减如故。用六君子十帖。即愈。", "3741": "震按此二案。峻补急攻。如狮子抟象。全副神力。学者要看其病因。观其论脉。即知前贤非蠹心大胆也。", "3742": "又治光禄卿吴伯玉夫人。患腹满而痛。喘急异常。大便不通。饮食不进。医用理气利水药。二十日不效。李诊之。脉大而数。右尺为甚。令人按腹。手不可近。乃曰。此大肠痈也。脉数为脓已成。用黄耆、角刺、白芷、银花、甘草节之类。加葵根一两。煎一碗。顿服之。未申痛甚。至夜半而脓血大下。昏晕不支。即与独参汤稍安。更与十全大补。一月而愈。", "3743": "孙一奎治马二尹。年五十五。过食鳗肉卷饼。心腹胀痛。市医遽用硝黄下之。大便不行。胀痛愈增。继至者。以木香槟榔丸、大小承气汤。连服十日。胀痛益甚。粒米不进。大便并不行。小水亦仅点滴。后医以硝黄不效。杂进备急丸、白饼子、十枣汤、黑白丑之属。服数日。不惟大便不行。并小便点滴亦无矣。胀不可言。众医大叫称怪。一人为灸中脘三十壮。毫不为动。因断三日后当死。孙至。观其色苍黑。神藏不露。声音亮。惟腹大如覆箕。不能反侧。诊其脉。两手皆滑大。两尺尤有力。询其病源。阅其前方。骇然以为未闻未见也。因思一治法。先进香砂六君子汤。参术各用二钱。众医皆惊。谓中满胀痛。二便俱闭。如何用补。况苍黑之人。尤忌参术乎。孙曰。此非鼓胀证。乃内伤证也。当始伤时。犹在上鬲。法当用吐。经所谓在上者因而越之也。不用吐而用下药以伤其脾。脾伤则失运动之职。是以愈下愈伤。愈伤愈胀。脾气全然不动。药亦全然不行矣。故用六君子以醒其脾。香砂以助其运动。再用吐法。吐出前药。始有生机。此方非治病。乃治药也。且予非虑大便不行。独虑行之不止耳。医曰。求其行而不得。何以不止为虑。孙曰。君试思常人能服硝黄几何。巴豆牵牛几何。今幸其未行。药性未动。尚可为计。一行而诸药性动。譬瓶水底漏。其中能蓄点滴哉。危矣。医又问多服下药而大便不行。何也。孙曰。此易知之。始为食伤。继为药伤。所伤在上中二焦。下元未损。故两尺脉尚有神气。难经曰。人之有尺。如树之有根也。内经曰。肾者胃之关。盖肾主大便。观其色苍黑。神藏气固。皆由根本未动。赖此犹可为耳。服药后。腹中大痛。一奎谓其药力已动。改用人参芦、防风芦、升麻、桔梗各三钱。煎服少顷。用鹅翎探吐之。前服药物。一涌而出十数碗。病者喜曰。目前有光矣。此巳时也。孙曰。酉时大便必行。可备人参数斤以备不虞。至午。进至宝丹一帖。以温中气。未申间。腹中汩汩有声。浊气下滚。顷刻腹宽数寸。至晚。大便行一次。小水略通。孙即用人参、白术各五钱。炮姜三钱。茯苓二钱。陈皮一钱。木香、甘草各五分。令急煎服。四鼓又大便一次。小水继至。胀痛渐减。次日大便泻十余次。因以是方。煎丸并进。计泻七十二日。服人参二斤余而收功。", "3744": "〔附〕喻嘉言治袁仲卿之子。仆水救出。大热呻吟。儿科以惊风丸散与服。二日遂昏迷不醒。胸高三寸。颈软息微。喻诊之曰。脉无根。仅如蛛丝。不可为矣。以汤二茶匙。滴入口中。微有吞意。因思病虽因惊而得。其实跌仆水中。感冷湿之气而发热。胃中食物不化。当比夹食伤寒例治。乃以金石寒冷药镇坠其邪。深入脏腑。神识因而不清。其食停胃中者。得寒凉而不运。所进之药。皆在胃口之上。不能透入。转积转多。以致胸高而突。宜以理中药运转前药。或有生机。即煎理中汤一盏。灌入喉中。大爆一口。果然从前二日所受之药。一齐俱出。胸突顿平。颈亦稍硬。但脉仍不出。人亦不醒。喻曰。此为食尚未动。关窍堵塞之故。再灌前药些少。热亦渐退。乃用元明粉一味化水。连灌三次。下黑粪甚多。继以生津药调理而愈。", "3745": "查少川向有哮喘。每发时。以麻黄、石膏、杏仁、枳壳、细茶大剂煎服。立刻见效。屡发屡服。而嗜酒纵欲。不避风寒。渐至腹大如覆箕。两腿光肿如柱。内外廉疥疮中。清水涓涓不绝。腥气逼人。不能伏枕而卧者五月。医者骇辞不治。孙东宿至。见其坐高椅之上。气喘身热。又畏寒甚。周围环火五盆。首戴绒帽。笼以貂套。套外复束一帕。鼻用绒套笼之。诊其脉浮大无力。睇其色。白中隐青。因问恶寒身热。从何时起。答以十日。孙曰。予得之矣。此病是气虚中满。法当温补下元。人徒知利小水。不知小水不利者。由下焦之气不充。不能渗从膀胱故道而行。若利之急。则泛滥而横流肌肤。下于阴囊。甚则胀裂崩塌而出矣。必待下焦元气壮盛。斯能升降变化。水自行而胀自消耳。至如近来之恶寒身热。由寒邪在表而然。合先散之。胸膈焦辣者。乃阴盛格阳。虚阳之火。被寒气驱逼上行。非真热也。亦待下元一温。热自下行。用苏叶、细辛、羌活、防风、苍术、陈皮、白豆蔻、人参、炙草、生姜。一帖而得微汗。遂撤火盆。去首帕。独鼻寒如初。乃用防风、黄耆二两煎汤熏之。一日三熏。鼻套亦除。但呕恶不止。用人参温胆汤加丁香。一帖而止。又谓鲤鱼能利水。一日尽二斤。半夜胀极。复告急于孙。孙曰。病势如是。敢纵恣若此乎。等闲之剂。曷能消释。沉思久之。以平胃散一两。入橄榄肉一两。煎服。两剂而定。独腹胀小水不利。不能伏枕为苦。乃以附子理中汤。加砂仁、补骨脂、赤豆、桂心。连进四帖。小水略长。继以尊重丸。每服五丸。日三服。五日后。小水通利。可贴席而睡矣。", "3746": "又治一女。胀而脉觉。用黄柏、青盐、升麻而愈。门人问其故。慎斋曰。此因命门火郁。使肾之真阳不升。心之真阴不降。故用黄柏以解命门壮火。使水中得升其真阳。用青盐以润心。使无邪火之炽而得下其真水。水火既济。而复以升麻提其青气。青气一升。浊气自降。而脾肺无内郁之弊。胀证愈矣。盖其本在肾而标在心。故三药奏效捷也。", "3747": "张路玉治王庸若。呕逆水肿。溲便涓滴不通。或用五苓八正。不应。六脉沉细如丝。因与金液丹十五丸。溺如泉涌而势顿平。后以济生肾气培养而安。", "3748": "李时珍治一士妻。自腰以下胕肿。面目俱肿。喘急欲死。不能伏枕。大便溏泄。小便短少。脉沉而大。沉主水。大主虚。乃病后冒风所致。是名风水。用千金神秘汤加麻黄。一服。喘定十之五。再以胃苓汤吞深师薷术丸。二日小便长。肿消十之七。调理数日全安。", "3749": "震按金液丹、神秘汤人所罕用。而善用之则各奏奇功。因思古方。具在简册。特患寻不著对头帽子耳。又按神秘汤。乃生脉散合二陈汤。去麦冬、茯苓。加紫苏、桑白皮、桔梗、槟榔。以生姜三片为引。施于此证恰好。加麻黄更好。并非八寸三分通行之帽也。", "3750": "汪石山治一女。年十五。病心悸。常若有人捕之。欲避而无所。其母抱之于怀。数婢护之于外。犹恐恐然不能安寐。医者以为病心。用安神丸、镇心丸、四物汤。不效。汪诊之。脉皆细弱而缓。曰。此胆病也。用温胆汤。服之而安。", "3751": "〔附〕许学士治四明董生。卧则魂飞扬。身虽在床而神魂离体。惊悸多魇。通宵不寐。群皆以为心病。医之无效。许曰。以脉言之。肝经受邪。游魂为变。非心也。以肝有邪。魂不得归于肝。是以卧则飞扬若离体也。肝主怒。必小怒则剧。用真珠母为君。龙齿佐之。因有龙齿安魂虎睛定魄之说。", "3752": "震按此二条。俱凭兼见之证。辨为肝胆之病。若汪案之脉细弱而缓。何以不认作阳气两虚。许案不载脉象。亦难核辨。然肝胆之不寐易治。而心之不寐难瘥。盖心藏神。肾藏精与志。寐虽由心。心赖肾之上交。精以合神。阴能包阳。水火既济。自然熟寐。内经谓阳气满则阳跷盛。不得入于阴。阴虚。故目不瞑。又云。阴跷阳跷。阴阳相交。阳入阴。阴出阳。交于目锐眦。阳气盛则瞋目。阴气盛则瞑目。此是不寐要旨。非肝胆病之不寐也。如人并无外邪侵扰。亦无心事牵挂。而常彻夜不寐者。其神与精必两伤。大病将至。殊非永年之兆。虽投补心补肾之药。取效甚难。即内经秫米半夏汤。亦有效有不效。或初效继不效。而病者辗转床褥。必求其寐。愈不肯寐。更生烦恼。去寐益远。慈山先生老老恒言云。寐有操纵二法。操者如贯想头顶。默数鼻息。返观丹田之类。使心有所著。乃不纷驰。庶可获寐。纵者任其心游思于杳渺无朕之区。亦可渐入朦胧之境。此诚慧心妙悟。可补轩岐所不逮。", "3753": "滑伯仁治一人。病怔忡善忘。口淡舌燥。多汗。四肢疲软。发热。小便白而浊。众医以内伤不足。拟进茸、附等药。未决。脉之虚大而数。曰。是由思虑过度。厥阴之火为害耳。夫君火以明。相火以位。相火代君火行事者也。相火一扰。能为百病。百端之起。皆由心生。越人云。忧愁思虑则伤心。其人平生志大心高。所谋不遂。抑郁积久。致内伤也。服补中益气汤、朱砂安神丸。空心进小坎离丸。月余而安。", "3754": "一人因事恐怖。心常惕惕。如畏人捕之状。诊其脉。豁豁然虚大而浮。体热多汗。曰。凡病得之从高坠下。惊仆击搏。恶血留滞。皆从中风论。终归厥阴。此海藏之说也。盖厥阴多血。其化风木故也。有形当从血论。无形当从风论。今疾是走无形也。从风家治之。兼化痰散结。佐以铁粉朱砂丸。愈。", "3755": "吴茭山治一妇气盛血少。火旺痰多。因事忤意。得怔忡之患。心惕惕然而惊。时发时止。清晨至晚。如此无度。每服镇心金石之药。愈不安。吴诊其脉左弦而大。知血少火旺。右浮滑不匀。气盛痰多也。遂也温胆汤入海粉、苏子。数服而安。次以安神丸。常服全愈。", "3756": "高果哉治钱塞庵相国怔忡不寐。诊得心脉独虚。肝脉独旺。因述上年驿路还乡。寇盗充斥。风声鹤唳。日夜惊惧而致。高用生地、麦冬、枣仁、元参各五钱。人参三钱。龙眼肉十五枚。服数剂。又用夏枯草、羚羊角、远志、茯神、甘草、人参。大效。仍以天王补心丹。常服全愈。", "3757": "丹溪治一妇人。有孕六阅月。发痫。手足扬掷。面紫黑。合眼流涎昏愦。每苏。医与镇灵丹五十帖。时作时止。至产后方自愈。其夫疑丹毒发求治。脉举弦按涩。至骨则沉滞数。朱意其痫必于五月复作。应前旧时。至则果作。皆巳（脾）午（心）时。乃制防风通圣散减甘草。加桃仁、红花。或服或吐。四五剂渐轻。发疥而愈。", "3758": "一少年夏间。因羞怒发昏。手搐如狂。时作时止。发则面紫黑。睪丸能动。左右相过。医与金箔镇心丸、抱龙丸、妙香散、定志丸。不效。脉微弦。六至。轻重有。朱曰。此内素有湿热。因激起厥阴相火。又时令相火。不宜服麝香之药。况肝病先当救脾土。诸药多燥血坏脾者。遂以黄连为君。人参为臣。酒浸芍药和白陈皮为佐。生甘草为使。生姜一片。煎服八帖而安。", "3759": "汪石山治一人。年三十余。久病痫证。多发于晨盥时。或见如黄狗走前。则昏瞀仆地。手足瘛疭。不省人事。良久乃苏。或作痰火治。而用苓、连、二陈汤。或作风痰治。而用全蝎、僵蚕、寿星丸。或作痰迷心窍。而用金箔镇心丸。皆不中病。汪诊之。脉皆缓弱颇弦。曰。此木火乘土之病也。夫早辰阳分。而狗阳物。黄土色。胃属阳土。虚为木火所乘矣。经曰。诸脉皆属于目。故目击异物而病作矣。理宜实胃泻肝而火自息。越人云。泄其肝者缓其中。遂以参、耆、归、术、陈皮、神曲、茯苓、黄芩、麦冬、荆芥穗。煎服十余帖。病减。再服月余而安。", "3760": "滑伯仁治一僧。病发狂谵语。视人皆为鬼。诊其脉累累如薏苡子。且喘且搏。曰。此得之阳明胃实。素问云。阳明主肉。其经血气并盛。甚则弃衣升高。逾垣妄詈。遂以三化汤三四下。复进以火剂乃愈。", "3761": "沧洲治一人。因恐惧遂惊气入心。终日逐逐奔走。不避水火。与人语则自贤自贵。或泣或笑。切其脉。上部皆弦滑。左部劲于右。盖溢膻中。灌心胞。因惊而风经五脏耳。即投以涌剂。涌痰涎一颒器。徐以惊气丸。服之尽一剂。病瘳。", "3762": "〔附〕沧州又治一人。寓僧舍病狂。其脉三部皆弦直上下行。而左寸口尤浮滑。曰。此风痰留心胞证也。以药涌吐痰沫四五升。即熟睡意日。及寤则病尽去。以安神之剂调之。全愈。", "3763": "吴茭山治一女子。瘦弱性急。因思过度。得颠疾。或哭或笑。或裸体而走。或闭户而多言。诸疗罔效。吴诊其脉浮而涩。思虑过伤。神不守舍也。用紫河车二具。漂洗如法。煮烂如猪肚。切片。任意啖之。二次即愈。后服定志丸一料。日煎补心汤一服。调理百日后。乃毕婚。次年生子。身肥壮。", "3764": "〔附〕嘉善朱怀音兄患癫狂。用消痰清火药而愈。越三年复发。消痰清火不应。用天王补心丹而愈。越二年又发。进以前二法。皆不应。用归脾汤而愈。越一年又发。发时口中哼哼叫号。手足牵掣搐掉。如线提傀儡。卧则跳起如鱼跃。或角弓反张。其喊声闻于屋外。而心却明白。但以颤掉之故。口欲语时。已将唇舌嚼坏。如此光景。半刻即止。止则神识昏懂。语言谬妄。又半刻而发如前矣。一吴姓名医。用人参、鹿茸、肉桂、熟地、龙齿、青铅、远、茯等药。服之甚相安。然匝月不见效。乃就正于叶天翁。叶笑曰。渠用贵重之药。必自信为名医。但多费病家之财。与病毫无干涉。即庸医也。吾以轻淡药。二十剂当减半。四十剂当全瘳耳。因叩其掣掉作则心明。掣掉止则神昏之故。曰。操持太过。谋虑不决。肝阴胆汁两耗。阳跷阴跷脉空风动。非虚寒也。用白芍、萸肉各一钱五分。白石英、淮小麦、南枣肉各三钱。炙草五分。病人见其方。殊不信。旁人亦以药太轻淡。并两帖为一帖。服十帖。病减半。二十帖病全瘳矣。", "3765": "倪维德治一妇。狂歌痛哭。裸裎妄骂。问之则瞪视默默。脉沉坚而结。曰。得之忧愤沉郁。痰与血交积胸中。涌之。皆积痰裹血。后与大剂清其上膈。数日如故。", "3766": "又一妇哭笑不常。人以为鬼所凭。倪诊其脉俱沉。胃脘必有所积。有所积。必作疼。遂以二陈汤导之。吐痰升许而愈。所谓积痰类祟也。", "3767": "汪石山治一人。年逾三十。形肥色白。酒中为人所折辱。遂病心恙。或持刀。或逾垣。披头大叫。诊其脉濡缓而虚。按之不足。此阳明虚也。宜变例以实之。庶几可免。先有医者。已用二陈汤加紫苏、枳壳等药。进二三帖矣。闻汪言。即厉声曰。吾治将痊。谁敢夺吾功乎。汪告归。医投牛黄清心丸如弹丸者三枚。初服颇快。再服燥甚。三服狂病倍发。抚膺号曰。吾热奈何。急呼水救命。家人守医戒。禁不与。趋楼见神前供水一盆。一呷而尽。犹未快也。复趋厨下。得水一桶。满意饮之。狂势减半。其不死幸耳。复请汪治之。以参、耆、甘草甘温之药为君。麦冬、片黄芩甘寒之剂为臣。青皮疏肝为佐。竹沥清痰为使。芍药、茯苓。随其兼证而加减之。酸枣仁、山栀子。因其时令而出入。服之月余。病遂轻。然或目系渐急。即瞀昧不知人。良久复苏。汪曰无妨。此气血未复。神志昏乱而然。令其确守前方。夜服安神丸。朝服虎潜丸。年余。熟寝一月而安。", "3768": "震按此人酒中受折辱。必然肝火郁勃。狂至持刀上屋。大渴恣饮。则痰火实证无疑。大胆者将用戴人之吐下。小心者亦必以黄连、石膏、羚羊、胆星、菖蒲、竺黄等药正治之。其人狂必愈甚。狂愈甚则元气脱。奄然以死。未死仍狂。死乃狂止。而医犹未悟也。幸遇石山之能识脉。用参、耆月余始愈。医可轻言哉。变例以实之句。云非常法也。亦当著眼。", "3769": "罗谦甫治入国信副使许可道。到雄州诣罗诊候。罗诊之。脉乍大乍小。乍长乍短。此乃气血不匀。邪气伤正。本官云。在路到邯郸驿中。夜梦一妇人。著青衣。不见面目。用手向胁下打了一拳。遂一点痛。往来不止。兼之寒热不能食。乃鬼击也。罗曰。可服八毒赤丸。本官言尝读明医录中。见李子豫八毒赤丸。为杀鬼杖子。遂与药三粒。临卧服。明旦下清水二斗。立效。", "3770": "李士材治文学朱文哉。遍体如虫螫。口舌糜烂。朝起必见二鬼。自谓不祥将死。李诊其寸脉乍大乍小。意其为鬼祟。细察两关弦滑且大。遂断为痰饮之疴。投滚痰丸三钱。虽微有所下。而病患如旧。更以小胃丹二钱与之。复下痰积及水十余碗。遍体之痛减半。至明早。鬼亦不见矣。更以人参三钱。白术二钱煎汤。服小胃丹三钱。大泻十余行。约有二十碗。病若失矣。乃以六君子为丸。服四斤而瘥。", "3771": "丹溪治一少年。暑月。因大劳而渴。恣饮梅浆。又连大惊。妄言妄见。病似邪鬼。脉虚弦而带沉数。数为有热。虚弦是惊。又梅浆停郁中脘。宜补虚清热。导去淡滞乃可。遂与参、术、陈皮、茯苓、芩、连。并入竹沥、姜汁。旬日未效。乃虚未回。痰未导也。以前药入荆沥。又旬日而安。", "3772": "又治浦江郑姓者。年二十余。秋间大发热。口渴。妄言妄见。病似邪鬼。七八日后。请朱治之。脉之。两手洪数而实。视其形肥。面赤带白。却喜露筋。脉本不实。凉药所致。此因劳倦成病。与温补药自安。曰。柴胡七八帖矣。以黄耆附子汤冷与之。饮三帖后。困倦鼾睡。微汗而解。脉亦稍软。继以黄耆白术汤。至十日。脉渐收敛而小。又与半月而安。", "3773": "虞恒德治一妇。年近三十。有姿色。得一证。如醉如痴。颊赤面青。略有潮热。饮食不美。其脉乍疏乍数而虚。每夜见白衣少年与睡。一医与八物汤。服数十帖不效。虞见其家有白狗。卧枕户阈。虞曰。必此所为。命杀狗取其心血及胆汁。丸安神定志之药。以八物汤舌下。丸药用远志、石菖蒲、川归、黄连、茯神、朱砂、侧柏叶、草龙胆等药。", "3774": "震按此三条甚奇。却难效法。首条若在今日。惟有清热导痰耳。敢用人参耶。丹溪则以脉之虚弦。因之大劳。认得清。故虽旬日未效。仍守前药。设有游移。则前功尽弃。病不痊而谤随之矣。次条脉证。俱似实热。乃云脉本不实。凉药所致。苟非具大本领者。谁敢道此。然用耆、附、术。而不用人参。想其审证处。必另有会心也。第三条诚系邪魅。然以白衣疑及白狗。近于诡幻。倘仍不效。能无雉罹于罗之叹。汇而录之。以备考订。", "3775": "张路玉治文学黄稚洁。谵妄颠仆。数月以来。或六七日一发。或二三日一发。或一日二三发。发则大吐涎水血沫。或一日半日而苏。或二三时而苏。医祷不灵。近于邪祟。术士皆言宿孽所致。昼夜恒见亡婢仆妇二鬼缠绵。或时昏愦不省。或时妄言妄见。精气不时下脱。不能收摄。服二冬、二地、连、柏、金樱、石莲之属无算。反加作泻不食。后延张诊之。脉来寸盛尺微。前大后小。按之忽无。举之忽有。知为神气浮散之候。因与六君子加龙齿、菖蒲、远志。送养正丹。间续而进。前后共三七服。是后谵妄颠仆。绝不复发。邪祟亦不复见。惟梦泄为平时痼疾。不能霍然。更与平补镇心丹。两月而安。其尊人及昆弟亲戚。咸谓金石之药。能镇鬼神。曷知从前谵妄。皆神气浮散之故。得养正镇摄之功。当无神魂飞越之患矣。因识此以破杯影弓蛇之惑。", "3776": "震按鬼祟岂能病人。不过病似鬼祟耳。或痰或虚。从其脉象以施治法。诸案皆先资之助也。", "3777": "一人梦遗白浊。少腹有气耕冲。每日腰热。卯作酉凉。若腰热作则手足冷。前阴无气来耕。腰热退。则前阴气耕。手足温。又旦多下气。暮多噫。一旬二旬必遗。朱诊之。脉旦弦搏而大。午尤洪大。知其有郁滞也。先用滚痰丸大下之。次用加减八物汤。下滋肾丸百粒。若稍与蛤、牡等涩药。则遗与浊滋甚。或一夜二遗。遂改用导赤散大剂。而遗浊皆止。", "3778": "汪石山治一人。年四十余。泄精久之。神不守舍。梦乱心跳。用清心莲子饮罔效。取袖珍方治小便出髓条服之。又服小菟丝子丸。又服四物加黄柏俱罔效。汪诊之。一日间其脉或浮濡而快。或沉弱而缓。曰。脉之不常。虚之故也。其证初因肾水有亏。以致心火亢极乘金。木寡于畏而侮其脾。此心脾肾三经之病。理宜补脾为主。兼之滋胃养心。病可疗也。方用人参为君。白术、茯苓、麦冬、枣仁、栀子、生甘草为佐。莲肉、山楂、黄柏、陈皮为使。其他牡蛎、龙骨、白芍、川芎、熟地之类。随其变证而出入之。且曰。必待人参加至五钱病脱。其人未信。服二十余日。人参每服三钱。溲精减半矣。又月余。加人参至五钱。寻愈。", "3779": "江篁南治一壮年。患遗精。医用滋阴降火罔效。更医。用龙、牡等止涩药。其精愈泄。又服芩、连、知、柏等药甚多。兼服小便。亦罔效。又或作痰火治。作湿热治。盖年余矣。江诊之。左脉浮濡无力。右寸浮散近快。两尺尤弱。不任寻按。其人头晕。腰痛骨酸。畏风。小便黄。腹中时鸣。乃以熟地、远志、人参、归身、桑螵蛸、石莲、茯神、石菖蒲、甘草。十余帖后。精固。惟筋骨犹酸。小便犹黄。腹或至晚犹鸣。前方再加黄柏。兼用补阴丸。加人参、鹿茸、菟丝、桑螵蛸、茯神之类丸服。两月而愈。", "3780": "李士材治武科张宁之。禀质素强。纵饮无度。忽小便毕。有白精数点。自以为有余之疾。不肯医治。经三月以来。虽不小便。时有精出。觉头目眩运。因服固精涩脱之剂。治疗两月。略不见功。李诊之。六脉滑大。此由酒味湿热。不干精藏。遂以白术、茯苓、橘红、甘草、干葛、白蔻。加黄柏少许。两剂即效。不十日而康复如常人。", "3781": "潘见所弱冠患白浊。医治三年不愈。其脉两寸短弱。两关滑。两尺洪滑。孙东宿曰。君疾易愈。第待来春之仲。一剂可瘳。而今时不可。因问何以必待来年。孙曰。经云。升降浮沉必顺之。又云。天时不可伐。君脉为湿痰下流证也。洪大而见于尺部。是阳乘于阴。法当从阴引阳。但今冬令。为闭藏之候。冬之闭藏。实为来春发生根本。天人一理。若不顾天时。而强用升提之法。是伐天和而泄元气。根本既亏。来春何以发生。闻言不信。别寻医药。仍无效。至春分。东宿以白螺蛳壳火煅存性四两。牡蛎二两。半夏、葛根、柴胡、苦参、川柏各一两。曲糊丸。早晚服。名曰端本丸。不终剂而全愈。", "3782": "吴茭山治一妇。患淋数而疼痛。身烦躁。医以热淋治之。用八正散、连子饮。服之愈剧。吴诊脉沉数无力。知气与火转郁于小肠故也。遂与木通、夌藁节、车前子、淡竹叶、麦冬、灯心、甘草梢、腹皮之类。服之而安。盖小肠乃多气少血之经。今病脉系气郁。反用大黄、栀、芩味厚苦寒之药。寒极伤气。病转加矣。不知血中有热者。乃有形之热。为实热也。气中有热。乃无形之热。为虚热也。凡气中有热者。当行清凉薄剂。无不获效。更分气血多少之经。辨温凉厚薄之味。审察病机。斯无失也。", "3783": "中书右丞合剌合孙。病小便数而少。日夜约二十余行。脐腹胀满。腰脚沉重。不得安卧。至元癸未季春。罗谦甫奉旨诊之。脉沉缓。时时带数。常记小便不利者有三。不可一例而论。若津液偏渗于肠胃。大便泄泻而小便涩少。一也。宜分利而已。若热抟下焦津液。则热涩而不行。二也。必渗泄则愈。若脾胃气涩。不能通利水道。下输膀胱而化者。三也。可顺气令施化而出也。今右丞平素膏粱湿热内蓄。不得施化。膀胱窍涩。是以起数而见少也。当须缓之泄之。必以甘淡为主。遂用茯苓为君。滑石甘寒。滑以利窍。猪苓、琥珀之淡。以渗泄而利水道。三味为臣。脾恶湿。湿气内蓄。则脾气不治。益脾胜湿。必用甘为助。故以甘草、白术为佐。咸入肾。咸味下泄为阴。泽泻之咸以泻伏水。肾恶燥。急食辛以润之。津液不行。以辛散之。桂枝味辛。散湿润燥。此为因用。故以二物为使。煎用长流甘澜水。使下助其肾气。大作汤剂。令直达于下而急速也。两服减半。旬日良愈。", "3784": "丹溪治一老人。因疝疼二十年。多服苍术、乌、附等药。疝稍愈。又患淋十余年。其间服硝、黄诸淋药。不效。忽项右边发一大疽。连及缺盆。不能食。淋痛愈甚。叫号困惫。时当六月。脉短涩。左微似弦。皆前乌、附积毒所致。凝积滞血。蓄满膀胱。脉涩为败血。短为血耗。忍痛伤血。叫号伤气。知其溺后有如败脓者。询之果然。遂先治淋。令多取土牛膝根茎叶浓煎汤。并四物汤大剂与之。三日痛与败脓渐减。五七日渐止。疮势亦定。盖四物能生血也。但食少。疮未收敛。用四物加参、耆、白术熬膏。以陈皮、半夏、砂仁、木香煎取清汁。调膏与之。逐渐能食。一月疮安。", "3785": "震按土牛膝汁。治血淋最效。以其能疏通滞血也。脉涩者。更宜之。丹溪合四物同用。因脉兼短耳。即不短。亦宜之。涩为血瘀。亦主血虚也。", "3786": "丹溪又治一男子。患淋久。囊大如球。茎如槌。因服利药多。痛甚。脉微弱如线。以参、耆、归、术加肉桂、元胡各一钱。木通、山栀、赤芍、赤茯苓、甘草梢等药。一服痛稍减。二服不溲利。四服愈。", "3787": "震按服利药既多。脉微弱如线。法必宜补矣。犹兼延胡、赤芍、木通、赤苓、山栀等利血利水药者。以其证仍痛甚也。可见淋证宜利者多。惟薛案所叙病因病情。必该用所用三方。其合滋肾丸者。以小便仍涩滞也。若果阳虚脉微。又当用金匮肾气丸。与知、柏不宜。至如叶氏治淋。有虎杖、麝香、大黄、牵牛、两头尖、威喜丸、连、柏、胆、荟、参、茸、八味等方。较薛氏法多而且备矣。", "3788": "孙东宿治丁耀川令堂。年四十四。常患胃脘痛。孀居茹素十五年。七月中。触于怒。吐血碗许。不数日平矣。九月又怒。吐血如前。加腹痛。至次年二月。忽里急后重。肛门大疼。两胯亦痛。小便短涩。出惟点滴。痛不可言。腰与小腹之热。如滚汤泡。日惟仰卧不能侧。一侧则左胯并腿痛甚。小便疼。则肛门之痛减。肛门疼。则小便之痛减。遇惊恐。则下愈坠而疼。经不行者两月。往常经来时。腰腹必痛。下紫黑血块甚多。今又白带如注。口渴。通宵不寐。不思饮食。多怒。面与手足虚浮。喉中梗梗有痰。肌肉半消。孙诊之。脉仅四至。两寸软弱。右关滑。左关弦。两尺涩。据脉。上焦气血不足。中焦有痰。下焦气凝血滞。郁而为火。盖下焦之疾。肝肾所摄。腰胯乃肝之所经。而二便乃肾之所主也。据证面与手足虚浮。则脾气极弱。饮食不思。则胃气不充。不寐由过于忧愁思虑而心血不足。总为七情所伤故耳。内经云。二阳之病发心脾。女子不月。此病近之。且值火令当权之候。诚可虑也。所幸者脉尚不数。声音清亮耳。因先为开郁清热。条达肝气。保过夏令后。再为骤补阴血。必戒绝怒气。使血得循经。方可获生也。初投当归龙荟丸。以撤下部之热。继以四物汤、胆草、知、柏、柴胡、泽兰煎吞滋肾丸。连服四日。腰与小腹之热始退。后以香薷、石苇、胆草、桃仁、滑石、杜牛膝、甘草梢、柴胡煎吞滋肾丸。大小便痛全减。", "3789": "东宿曰。族侄孙伍仲。三十岁。善饮好内。小便血淋疼痛。予以滑石、甘草梢、海金沙、琥珀、山栀、青蒿。以茅草根煎膏为丸。每晨灯心汤送三钱而愈。后五年。因子迟。服补下元药过多。血淋又发。小便中痛极。立则不能解。必蹲下如妇女状。始能解出。皆大血块。每行一二碗许。诸通利清热药。遍尝不应。脉俱洪数。予以五灵脂、蒲黄、甘草梢各二钱。小蓟、龙牙草各三钱。二帖而痛减半。血仍旧。改用瞿麦、山栀、甘草梢各二钱。茅根、杜牛膝、车前草叶各三钱。生地、柴胡、川柏、木通各一钱。四帖痛全减。血全止。惟小便了而不了。六脉亦和缓不似前矣。后以四君子加葛根、青蒿、白芍、升麻、知、柏。调理万全。", "3790": "震按上条不用补。次条不用养阴。认证最清。设效立斋景岳。狃于归脾汤补中益气六味生脉者。必为二证之戈矛矣。", "3791": "又治李寅斋。患血淋几二年不愈。每发十余日。小水艰涩难出。窍痛不可言。将发。必先面热牙疼。后则血淋。前数日饮汤水。欲温和。再二日欲热。又二日。非冷如冰者不可。烦渴之甚。每连饮井水二三碗。其未发时。大便燥结。四五日一行。发则泻而不实。脉左寸短弱。关弦大。右寸下半指与关皆滑大。两尺俱洪大。据此中焦有痰。肝经有瘀血也。向服滋阴降火。及淡渗利窍之剂。皆无效。且年六十有三。病已久。血去多。何可不兼补治。当去瘀生新。提清降浊。用四物汤加杜牛膝补新血。滑石、桃仁消其瘀血。枳实、贝母以化痰。山栀仁以降火。柴胡升提清气。二十帖而诸证渐减。再以滑石、知母、黄柏各一两。琥珀、小茴、肉桂各一钱五分。元明粉三钱。海金沙。没药各五钱。茅根汁熬膏为丸。每服一钱。空心及晚。茅根汤送下而愈。", "3792": "又治祝芝岗秀才。每喜酒后御女。行三峰采战对景忘情之法。致成血淋。自仲夏至岁杪未愈。便下或红或紫。中有块如筋膜状。或如苏木汁色。间有小黑子。三五日一发。或劳心。或劳力。或久立坐亦发。百治不效。东宿观其色白而清。肌肉削甚。诊其脉左寸沉弱。关尺弦细。右寸略滑。据此。必肺经有浊痰。肝经有瘀血。总由酒后竭力纵欲。淫火交煽。精离故道。不识澄心调气。摄精归源之法。以致凝滞经络。流于溺道。故新血行至。被阻塞而成淋浊也。三五日一至者。盈科则溢耳。先与丹参、茅根浓煎服。小便以瓦器盛之。少顷即成金色黄沙。乃用肾气丸加琥珀、海金沙、黄柏。以杜牛膝连叶捣汁熬膏为丸调理。外以川芎三钱。当归七钱。杜牛膝草根煎服。临发时。用滑石、甘草梢、桃仁、海金沙、麝香为末。以韭菜汁、藕汁调服。去其凝精败血则新血始得归原。而病根可除矣。三月全愈。", "3793": "张路玉治太史沈韩倬。患膏淋。小便频数。昼夜百余次。昼则滴沥不通。时如欲解。痛似火烧。夜虽频迸而所解倍常。溲中如脂如涕者甚多。先曾服清热利水药。半月余。其势转剧。面色痿黄。饮食艰进。张诊之。脉得弦细而数。两尺按之益坚。而右关涩大少力。此肾水素亏。加以劳心思虑。肝木乘脾所致。法当先实中土。使能堤水。则阴火不致下溜。清阳得以上升。气化通而疼涩瘳矣。若用清热利水。则气愈陷而精愈脱。溺愈不通耳。乃定补中益气汤。用人参三钱。服二剂。痛虽少减。而病者求其速效。改进四苓散加知母、门冬、沙参、花粉。甫一服。彻夜痛苦倍甚。于是专服补中益气兼六味丸。用紫河车熬膏代蜜调理。服参尽斤余而安。", "3794": "震按淋证。如孙东宿之治法。经也。此二案之治法。权也。经权合宜。皆审脉以为辨。庄子曰。匠石觉而诊其梦。梦何以诊。诊之为言审也。向来但云诊脉。未达诊字之义。不知善诊。即是善审。审得明白。病自显然。推之望闻问切。素称四诊。可见四件都要细审也。", "3795": "朱丹溪治一人。小便不通。医用利药益甚。脉右寸颇弦滑。此积痰在肺。肺为上焦。膀胱为下焦。上焦闭则下焦塞。如滴水之器。必上窍通而后下窍之水出焉。以药大吐之。病如失。", "3796": "士材曰。先兄念山。谪官浙江按察。郁怒之余。又当盛夏。小便不通。气高而喘。服胃苓汤四帖。不效。余曰。六脉见结。此气滞也。但用枳壳八钱。生姜五片。急火煎服。一剂稍通。四剂霍然矣。", "3797": "丹溪治一妇。患心中如火一烧。便入小肠。急去小便。大便随时亦出。如此三年。求治。脉滑数。此相火送入小肠经。以四物加炒连、柏、小茴、木通。四帖而安。", "3798": "李士材治方伯张七泽夫人饮食不进。小便不禁。李曰。六脉沉迟。水泉不藏。是无火也。投以八味丸料。兼进六君子加益智、肉桂。三剂减。数剂而安。", "3799": "文学俞元倩忧忿经旬。忽然小便不禁。医皆以补脬固肾之剂投之。凡一月而转甚。李曰。六脉举之则软。按之则坚。此肾肝之阴有伏热也。用丹皮、茯苓各二钱。苦参八分。甘草梢六分。黄连一钱。煎成。调黄鸡肠与服。六剂而安。适有医云。既愈当大补之。数日后。仍复不禁。再来求治。曰。肝家素有郁热。得温补而转炽。遂以龙胆泻肝汤加黄鸡肠服之。四剂即止。更以四君子加黄连、山栀。一月而痊。", "3800": "黄元吉年六十余。因丧明蓄妾。而患小便淋涩。春间因颠仆。昏愦遗尿。此后遂不时遗溺。或发或止。至一阳后大剧。昼日溺涩不通。非坐于热汤则涓滴不出。交睫便遗之不禁。张诊其脉。或时虚大。或时细数。而左关尺必显弦象。此肾气大亏而为下脱之兆也。乃与地黄饮子数服。溺涩稍可。遗亦少间。后与八味丸除丹皮、泽泻。加鹿茸、五味、巴戟、远志。调理而痊。", "3801": "陕客亢仁轩。年壮色苍。体丰善啖。患胞痹十余年。其脉软大而涩涩不调。不时蹲踞于地。以手揉其茎囊。则溲从谷道点滴而渗。必以热汤沃之。始得少通。寐则有时而遗。其最者中有结块如橘核之状。外裹红丝。内包黄水。杂于脂腻之中。此因恣饮不禁。酒湿乘虚袭入髓窍。故有是患。因令坚戒烟草、火酒、湿面、椒蒜、糟醋、鸡豕、炙爆等味。与半夏、茯苓、猪苓、泽泻、萆薢、犀角、竹茹作汤。四剂。势减二三。次与肾沥汤加萆薢。数服。水道遂通。溲亦不痛。但觉食不甘美。后以补中益气加车前、木通调之而安。石顽曰。又有胞痹二证。一因挟妓致病。用肾沥汤。加减八味丸收功。一因阴虚多火。用肾沥汤、生脉散。合六味丸收功。若萆薢分清。渗水伤精之味。咸为切禁。此人则肥盛多湿。故先与清胃豁痰之药。然后理肾调脾。治各有宜耳。", "3802": "孙东宿治南都大司马袁洪溪。冲暑理事。致发热燥渴。因食冰浸瓜梨新藕。遂成泄泻。小水短少。医以胃苓汤加滑石、木通、车前子利之而泻止。大便又因之结燥。艰涩不堪。乃用润肠丸。复泻不止。又进以前通利之剂。泻虽止而小水不能流通直遂。脐下胀急。立起解之。则点滴不出。卧则流之不竭。以频取溺器。致通宵不寐。治半月余而精神削。寝食废。诸医俱不识。将认为癃。则立解时点滴不出。认为闭。卧则涓涓而流。谓气虚下陷。心血不足。而补中益气与安神丸服皆无效。孙诊其脉两寸短弱。关缓大。两尺洪大。语之曰。此余暑未解。而司马素善饮。湿热流于下部也。今已下午。恐脉未准。俟明早细察定方。司马曰。望子久矣。姑求一剂。以邀夜间一睡。孙不得已。以益元散三钱。煎香薷汤进之。略无进退。次早复诊。六脉如昨。思之而恍然悟曰。此证尿窍不对也。司马曰。名出何书。孙曰。内经云。膀胱者。脬之室也。脬中湿热下坠。故立解而窍不对。小水因不得出。卧则脬不下坠而尿渗出膀胱。亦以窍不对。虽涓涓而流。终不能通达直遂。故了而不了也。治惟提补上中二焦元气。兼清下焦湿热。斯得矣。又有一法。今气虚下陷已久。一两剂未能取效。安得睡耶。但此不寐。非心血不足。因著心防闲小便而不敢寐也。暂将布袋衬于席上。任其流出而不必防闲。免取便器。自然熟睡矣。方用补中益气汤加黄柏、知母。如法果愈。", "3803": "县令顾荣甫尾闾痒而小便赤涩。左尺脉洪数。属肾经虚热。法当滋补。渠不然其言。服黄柏、知母等药年许。高骨肿痛。小便淋沥。肺肾二脉洪数无伦。薛曰。子母俱败。鲜克济矣。果寻卒。", "3804": "震按二便不通。脉实者。八正散倍大黄。或倒换散亦妙。若形弱及老人。或病后产后有此。悉从虚秘治。润燥养阴为主。下用导引法。若体健神旺。二便秘涩者。必脾胃气滞不转输。加以痰饮食积。阻碍浊道。脉沉实者。升、柴、二陈、二术汤。今所选王案。取其外治之法。及服黄连解毒丸三载为大奇。而李时珍之用甲片、牵牛。走精隧以通淤塞为更奇。直可与东垣滋肾丸并垂天壤。", "3805": "虞恒德治一妇。年五十余。身材瘦小。得大便燥结不通。饮食少进。小腹作痛。虞诊之。六脉皆沉伏而结涩。作血虚治。用四物汤加桃仁、麻仁煨大黄等药。数服不通。反加满闷。与东垣枳实导滞丸及备急丸等药。下咽片时即吐出。盖胃气虚而不能久留性速之药耳。遂以备急丸。外用黄蜡包之。又以细针穿一窍。令服三丸。盖以腊匮者制其不犯胃气。故得出幽门。达大小肠也。明日下燥屎一升许。继以四物汤加减。煎吞润肠丸。如此调理月余。得大便如常。饮食进而安。", "3806": "薛立斋治一妇。年七十三。痰喘内热。大便不通。两月不寐。脉洪大。重按微细。此属肝肺肾亏损。朝用六味丸。夕用逍遥散。各三十余剂。计所进饮食百余碗。腹始痞闷。乃以猪胆汁导而通之。用十全大补调理而安。若间前药。饮食不进。诸证复作。", "3807": "汪石山治一妇。因改醮。乘轿劳倦。加以忧惧。成婚之际。遂病小腹胀痛。大小便秘结不通。医以硝、黄三下之。随通随闭。病增胸膈胃腕胀痛。自汗食少。汪诊之。脉皆濡细近快。心脉颇大。右脉觉弱。汪曰。此劳倦忧惧伤脾也。盖脾失健运之职。故气滞不行。以致秘结。今用硝、黄。但利血而不能利气。遂用人参二钱。归身一钱五分。陈皮、枳壳、黄芩各七分。煎服而愈。", "3808": "高果哉治温相国体仁。初谢政归乌程。患大便燥结不通。胸膈塞闷而不食。肾脉沉小而无神。以枳壳五钱。苁蓉二两。洗净。水煎服即效。后又秘结。以当归、生首乌。大剂煎服。遂全愈。", "3809": "张景岳治朱翰林太夫人。年近七旬。于五月时。偶因一跌。即致寒热。医为之滋阴清火。用生地、芍药、丹皮、黄芩、知母之属。其势日甚。张诊之。见其六脉无力。虽头面上身有热。而口则不渴。且足冷至股。乃曰。此阴虚受邪。非跌之为病。实阴证也。遂以理阴煎加人参、柴胡。二剂而热退。日进粥食二三碗。而大便以半月不通。腹且渐胀。群议燥结为火。复欲用清凉等剂。张谓如此之脉。如此之年。如此之足冷。若再一清火。其原必败。不可为矣。经曰。肾恶燥。急食辛以润之。正此谓也。仍以前药。更加姜、附。倍用人参、当归。数剂而便即通。胀即退。日渐复原矣。", "3810": "石顽曰。交肠证虽见于方书。而世罕见。绿石山詹石匠之妇。产后五六日。恶露不行。腹胀喘满。大便从前阴而出。省其故。缘平昔酷嗜烟酒。所产之儿。身软无骨。因而惊骇。遂患此证。余以芎归汤加莪术、肉桂、炒黑山楂。一服恶露通。而二便如常。又陆圣祥之女。方四岁。新秋患血痢。而稀粪出于前阴。作冷热不调食积治。与五苓散。服香连丸。二剂而愈。又钱吉甫女。年十三。体肥痰盛。因邻居被盗。发热头痛。呕逆面青。六脉弦促。而便溺易位。此因惊气乱。痰袭窍端所致也。与四七汤下礞石滚痰丸。开通痰气而安。", "3811": "石顽治内翰孟端士尊堂。因久不见其子。兼闻有病。遂虚火上升。自汗不止。心神恍惚。欲食不能食。欲卧不能卧。口苦小便难。溺则洒淅头晕。已及一岁。历更诸医。每用一药。辄增一病。用白术则窒塞胀满。用橘皮则喘息怔忡。用远志则烦扰哄热。用木香则腹热咽干。用黄耆则迷闷不食。用枳壳则喘咳气乏。用门冬则小便不禁。用肉桂则颅胀咳逆。用补骨脂则后重燥急。用知、柏则小腹枯瘪。用芩、栀则脐下引急。用香薷则耳鸣目眩。时时欲人扶掖而走。用大黄则脐下筑筑。少腹愈觉收引。遂致畏药如蝎。惟日用人参钱许。入粥饮和服。聊藉支撑。交春虚火倍剧。火气一升。则周身大汗。神气骎骎欲脱。惟倦极少寐。则汗不出而神思稍宁。觉后少顷。火气复升。汗亦随至。较之盗汁迥殊。直至仲春。邀石顽诊之。其脉微数。而左尺与左寸倍于他部。气口按之似有似无。诊后款述从前所患。并用药转剧之由。曾遍省吴下诸名医。无一能识其为何病者。石顽曰。此本平时思虑伤脾。脾阴受困。而厥阳之火。尽归于心。扰其百脉致病。病名百合。此证惟仲景金匮要略言之甚详。本文原云诸药不能治。所以每服一药辄增一病。惟百合地黄汤为之专药。奈病久中气亏乏逮尽。复经药误而成坏病。姑先用生脉散加百合、茯神、龙齿以安其神。稍兼萸、连以折其势。数剂稍安。即令勿药以养胃气。但令日用鲜百合煮汤服之。交秋天气下降。火气渐伏。可保无虞。迨后仲秋。端士请假归省。欣然勿药而康。后因劳心思虑。其火复有升动之意。或令服左金丸而安。嗣后稍觉火炎。即服前丸。第苦燥之性。苦先入心。兼之辛臊入肝。久服不无反从火化之虞。平治权衡之要。可不预为顾虑乎。", "3812": "震按百合病载于金匮。原云百脉一宗。悉致其病。钱塘李珉臣归重心肺二经。以心主血脉。肺朝百脉也。此言与百合地黄汤恰合。今观孟夫人案。实由思子郁结。病在心肝。大半似百合病形。石顽遂附会之耳。然不用金匮成方。可云老手。若日饮百合汤。何关得失耶。", "3813": "汪石山治一人。形长而瘦。色白而脆。年三十余。得奇疾。遍身淫淫循行如虫。或从左脚腿起。渐次而上至头。复下于右脚。自觉虫行有声之状。召医诊视。多不识为何病。汪诊其脉。浮小而濡。按之不足。兼察形视色。知其为虚证矣。伤寒论曰。身如虫行。汗多亡阳也。遂仿此例。而用补中益气汤。多加参、耆。以酒炒黄柏五分佐之。服至三十帖。遂愈。", "3814": "江应宿治一人犯事。自吞黄金二钱。心中愦愦。无可奈何。少顷。其事得释。欲求生。邀江治之。四肢厥冷。六脉沉伏。计无所出。因思银工熔金必用硼砂。硼能制金。急市四钱为末。粥丸。分二次服下。少顷。煎承气汤利下。硼裹金从大便出而安。", "3815": "吴少师忽得疾。数月间。肌肉消瘦。每饮食下咽。少时腹如万虫攒攻。且痒且痛。皆以为劳瘵也。张锐为切脉。戒曰。明日早。且忍饥。勿啖一物。吴如其言。时方剧暑。令取行路黄土一盂。以温酒二升。投土搅匀在内。使吞之。少顷。再以土酒送宣药百粒。随即肠胃掣痛。洞泻秽恶斗许。有马蝗千余。宛转盘结。俱已困死。吴亦惫甚。卧久方餐粥。三日而平。始言去年夏夜出师。中途燥渴。命候兵持孟挹涧水。甫入口。似有物。未暇吐之。则竟入喉矣。自此遂得病。锐曰。虫入肠胃里。势渐滋生。常日遇食时。则聚丹田间。吮咂精血。饱则散而四处。苟惟知杀之而不能扫尽。无益也。故请枵腹以诱之。此虫喜酒。又久不得土味。乘饥毕集。乃可以一药洗空之耳。", "3816": "罗谦甫治柏参谋。六十一岁。初患头昏闷微痛。医作伤寒治。汗后其痛弥笃。再汗之。不堪其痛矣。易医用药。大都相近。甚至痛不能卧。且恶风寒。不喜饮食。罗诊之。六脉弦细而微。气短促。懒言语。内经云。春气者。病在头。今年高气弱。清气不能上升头面。故昏闷耳。且此证本无表邪。汗之过多。则清阳之气愈亏。不能上荣。亦不得外固。所以头痛楚而恶风寒。气短弱而憎饮食。以黄耆一钱五分。人参一钱。炙甘草七分。白术、陈皮、归芍各五分。升、柴各三分。细辛、川芎、蔓荆子各二分。名之曰顺气和中汤。食后进之。一饮而病减。再饮而病却。", "3817": "孙东宿治蔡乐门令眷。头痛如破。发根稍动。则痛延满头。晕倒不省人事。逾半时乃苏。遍身亦作疼。胸膈饱闷。饮汤水。停膈间不下。先一日吐清水数次。蛔虫三条。原为怒起。今或恶风。或恶热。口或渴或不渴。大便秘。脉则六部皆滑大有力。孙曰。此痰厥头痛证也。先以藿香正气散止其吐。继以牛黄丸、黑虎丹清其人事。头仍疼甚。又以天麻、藁本各三钱。半夏二钱。麻黄、薄荷、白芷、陈皮、生姜、葱白煎服。得少汗而头痛少止。至晚再服之。五更痛止大半。而人事未全清。孙谓此中焦痰盛。非下不可。乃用半夏五钱。巴霜一分。面糊丸。每服三十丸。生姜汤送下。午后大便行三次。皆稠黏痰积也。由此饮食少进。余证差可。惟遍身仍略疼。改用二陈汤加前胡、藁本、薄荷、黄芩、石膏、枳壳、石菖蒲。调理而安。", "3818": "僧慎柔治一贵介。年三旬。先因齿痛。用石膏三钱煎服。顷即满头皆肿痛。牙龈上腭。肿势尤甚。天明稍退。盖得阳气故也。诊之右关细涩。左关洪。左尺亦涩。慎柔谓须纳气下达。方得脉和。定方名羌活散火汤。羌活酒炒五分。防风三分。酒连一分。酒芩二分。白茯苓一钱。人参二钱。甘草五分。半夏一钱。破故纸一钱。枸杞子一钱。二剂。其细涩脉即粗大。是阳气下行矣。头痛稍止。可见前头痛是下焦无阳。阴火上冲。服至八剂。头痛全止。齿根肿犹未退。脉则益和。曰。将愈矣。此阳气已至恙所。果四五日后。出脓少许而瘳。", "3819": "震按罗案是气虚头痛。张案是积热头痛。薛案是肝火头痛。李案是肾虚头痛。孙案是痰厥头痛。僧案是阳升不降头痛。六种之外。又有因风痛者。抽掣恶风。鼻塞眼胀。因寒痛者。恶寒战栗。面惨肢冷。因湿痛者。头痛且重。天阴转甚。或四肢疼肿。面目浮肿。此皆外因也。内因则气虚之外。血虚更多。积痰之外。积食亦有。丹溪云。肥人头痛。多是湿痰。瘦人头痛。多是血虚有火。斯诚要言。然因虽数端。靡不兼风。无风人只作眩不作痛也。故古方中川芎茶调散、大追风散。颇亦取效。痛久则成头风。其方更繁。不能缕述。真头痛乃死证。外灸百会穴。内进参附汤、黑锡丹。或冀挽回。实未试验。寻常头痛亦有死者。高阳生云。头痛短涩应须死。生平曾见之矣。头与腹俱痛有五证。臭毒、伤酒、伤湿、不伏水土、疮毒入腹也。有头痛止则腹痛。腹痛止则头痛。此属脾阴虚。胃火随气上下。芎、归、芍药、木香、香附、黄连、葱白。又有头痛诸药不效。其痛更甚者。或因督脉为病。宜用茸朱丹。次则香茸八味丸。复有雷头风。另是一项。乃内郁痰火。外束风热。大头风即大头瘟。或痛或不痛。或溃或自消。死生反掌。至如眉棱骨痛。系足少阳风热与痰。最能伤目。至两耳出脓则危矣。宜以浓茶一碗探吐之。次用清上药。如选奇汤、清空膏之类。妇人注目针绣。往往眉骨酸痛。必须益阴养血。", "3820": "震按萆薢当是土茯苓。广笔记治霉疮头痛方更佳。但治病必以脉为凭。丹方有效有不效。且录之不胜录。上四条虽不载脉。然证颇疑难。法殊整暇。定当入选。他如江篁南治从婶。以补中益气加川芎、细辛、蔓荆子。翟文炳治陆母。先与抑青丸。继以补中益气二条。只叙见证。未可摹仿。且陆母证甚繁杂。抑青丸一服而愈。其然岂其然乎。", "3821": "罗谦甫治江淮漕运使崔君长子。年二十五。体丰肥。奉养膏粱。时有热证。因食凉物。服寒药。至元庚辰秋。久疟不愈。医用砒霜截药。新汲水送下。禁食热物。疟不止。反加吐利。腹痛肠鸣。时复胃脘当心而痛。屡医罔效。延至次年四月。因劳役烦恼。前证大作。罗诊之。脉弦细而微。手足稍冷。面色青黄不泽。情思不乐。恶烦冗。食少。微饱则心下痞闷。呕吐酸水。发作疼痛。冷汗时出。气促。闷乱不安。须人额相抵而坐。内经云。上气不足。头为之苦倾。中气不足。溲便为之变。肠为之苦鸣。下气不足。则为痿厥心悗。又曰。寒气客于肠胃之间。则卒然而痛。得炅乃已。炅者。热也。非甘辛大热之剂则不能愈。为制扶阳助胃汤。炮干姜一钱五分。人参、草豆蔻、炙草、官桂、白芍各一钱。陈皮、白术、吴茱、益智各五分。炮熟附子二钱。姜、枣煎。服三帖。大势皆去。痛减过半。至秋先灸中脘三七壮。以助胃气。次灸气海百余壮。生发元气。滋荣百脉。以还少丸服之。则善饮食。添肌肉。明年春。灸三里二七壮。乃胃之合穴也。亦助胃气。又引气下行。春以芳香助脾。育气汤加白檀香。戒以惩忿窒欲。慎言节食。一年而平复。", "3822": "滑伯仁治一妇人。盛暑洞泄。厥逆恶寒。胃脘当心而痛。自腹引胁。转为滞下。呕哕不食。医以中暑霍乱疗之。益剧。脉三部俱微短沉弱。不应呼吸。曰。此阴寒极矣。不亟温之。则无生理。内经虽曰用热远热。又曰。有假其气。则无禁也。于是以姜、附温药。服之七日。诸证悉去。再以丸药除其滞下。而安。", "3823": "丹溪治一人。以酒饮牛乳。患心疼年久。饮食无碍。虽盛暑饮食身无汗。医多以丁、附治之。羸弱食减。每痛以物拄之。脉迟弱弦而涩。大便或秘结或泄。又苦吞酸。时七月。以二陈汤加芩、连、白术、桃仁、郁李仁、泽泻。每旦服之。屡涌出黑水。若烂木耳者。服之二百余帖。脉涩渐退。至数渐添。纯弦而渐充满。时冬暖。意其欲汗。而血气未充。以参、耆、归、芍、陈皮、半夏、甘草。服之痛缓。每旦夕一二作。乃与麻黄、苍术、芎、归、甘草等药。才下咽。忽晕厥。须臾而苏。大汗。痛止。", "3824": "一妇春末。心脾疼。自言腹胀满。手足寒过肘膝。须绵裹火烘。胸畏热。喜掀露风凉。脉沉细涩。稍重则绝。轻似弦而短。渴喜热饮。不食。以草豆蔻丸。三倍加黄连、滑石。神曲为丸。白术为君。茯苓为佐。陈皮为使。作汤下百丸。服至二斤而愈。", "3825": "震按二条脉象。俱似虚寒。而丹溪以湿热治者。上条屡服热药不效。且年久饮食无碍。大便或秘或泄。知其为停饮也。此条以胸前畏热喜凉。及脉沉细涩为据。所为稍重则绝者。以细涩故也。与阔大而软之为虚寒不同矣。故加黄连、滑石。遍观丹溪案。凡脉弦细涩者。俱不用温药。想其阅历多而认得真也。又一妇心与头互换作痛。用清空膏而愈。亦云瘦弱脉涩。以四物加桃仁、酒芩、陈皮、甘草调理。", "3826": "虞天民治一妇。四月间多食青梅得病。日间胸膈中大痛如刀锥。至晚胸中痛止而膝䯊大痛。盖痰饮随气升降故也。医作胃寒治。与姜、桂、丁、沉、荜茇、乌、附之类。病反剧。加口渴。小水淋漓。虞诊其六脉洪数而滑。知为痰病。令熬竹沥。服三日。口不渴。小水亦不淋沥。但胸中与膝互痛如旧。用萝卜子研汁小半碗。吐痰半升。至夜痛尤甚而厥。此引动其猖狂之势也。再用吐法不效。一日清晨。以藜芦末一钱。麝香少许。酸浆水调服。始大吐。其痛如脱。调理而安。", "3827": "震按此条与丹溪治许文懿公案仿佛。许因中脘有食积痰饮。续冒寒湿。抑遏经络。气血不行。津液不通。痰饮上升则为痹疼。下降则为胯痛。须涌泄之。乃以甘遂末一钱。入猪腰子内煨食之。连泄七行。次日胯痛止而足能步。复又大作呕吐。不食烦躁。气弱不语。朱谓多年郁结。一旦泄之。徒引动其猖狂之势。随连用吐剂大吐之。更以朴硝、滑石、黄芩、石膏、连翘等一斤。浓煎冷饮。四日尽四斤。后又腹微满。二便闭。脉歇至于寅卯时。朱谓卯酉为手足阳明之应。此胃与大肠积滞未尽。二日内令服紫雪至五两。得稍安。又小溲闭痛。饮以萝卜子汁半盂。得吐立通。又小腹满痛不可扪摸。神思不佳。以大黄、牵牛作丸。连下之。得如烂鱼肠、桕油条者。而神思渐安。脉乃不歇。自病半月。不食不语。惟脉皆平常弦大。次年行倒仓法。全愈。朱公此案。宛似戴人。较之花溪。更加险峻。故节录附此。又一童子久疟初愈。心脾疼。六脉伏。痛稍减时。气口紧盛。余皆弦实而细。意其宿食。以小胃丹十余粒。服十二次。药尤狠。恐难学。", "3828": "孙东宿治查良川。怒后食鱼。骨哽喉中。即以馒头粽肉等压之。骨虽下。便觉胸膈不快。又服消骨药两日。胸膈胀痛殊甚。饮食悉从背后而下。恶寒发热。六脉弦数。因思骨哽之后。用硬物压之。伤其胃脘。必有瘀血停蓄膈间。将食管逼在背后。故饮食觉从背后下也。今但消去瘀血。庶使食管复元。以五灵脂为君。山楂、延胡、桃仁、枳壳为臣。赤芍、丹皮、香附、山栀仁、柴胡、石菖蒲为佐使。水煎。入韭菜汁一杯饮之。大便泻一次。即胸膈宽快。痛减大半。饮食乃从右边而下。右边喉胸稍痛。吞物甚艰苦。吐出痰皆血腥气。改以山栀、赤芍、归尾、桃仁、刘寄奴、五灵脂、丹皮、穿山甲煎。入韭菜汁服之。两帖全瘳。", "3829": "歙溪吴入峰之室。胃脘作痛。两胁胀急。痛一阵。则汗出一番。两颧红。唇口亦红。饮食汤水。饮之立吐。不受者三日夜矣。孙东宿诊之。两寸脉洪大。两尺沉微。孙以井水半碗。百滚汤半碗。名曰阴阳汤。用此调元明粉一钱五分。服之不惟不吐。痛减半矣。少顷。大便行三次。因食豆腐及粥太早而痛复作。唇脸皆红。此必有虫。故如是也。与桂枝、白芍、甘草、乌梅、川椒、五灵脂、杏仁。水煎。痛乃定其大半。再与苍术、厚朴、山楂、枳实、茯苓、延胡、香附。一帖全止。但心背皮肤外疼。不能著席而睡。以芎、归、苓、术、橘、半、厚朴、腹皮、香附、甘草。调养全愈。", "3830": "王金坛曰。予读中秘书时。馆师韩敬堂先生常患膈痛。诊其脉洪大而涩。予用山栀仁、赤曲、通草、麦芽、香附、芎、归煎汤。加姜汁、韭汁、童便、竹沥饮之而止。一日。劳倦忍饥。痛大发。亟邀予至卧房。问曰。晨起痛甚。不得待公。服家兄药。药下咽。如刀割。痛益甚不可忍。何也。予曰。得非二陈、平胃、乌药、紫苏之属乎。曰然。曰。是则何怪乎其增病也。夫劳饿而发。饱逸则止。知其虚也。饮以十全大补汤。一剂而痊。", "3831": "震按李公二案。一用峻下。一用大补。皆以脉为凭。王公一案。先用行血通气。后用十全大补。先凭于脉。后凭于因。乃知丹溪以脉因证治名书。扼其要而病无遁情也。", "3832": "震按此种病近来颇多。每从右胁胀痛至中脘。或吞酸。或吐水。或作泻。肢冷不食。予每以二陈汤加香附、白芍、苍术、良姜、草蔻、胡卢巴等。服之颇效。但易于发。发久则渐重。欲其不发。殊苦无策。观此病饮酒少止。得热少止。似有间可寻矣。乃不用温药。而以升、柴、葛、二术、参、耆升阳益胃。实得力于东垣。惜不载脉象为恨。然云每发一服即止。则亦不能不发也。", "3833": "一妇人胃脘痛。勺水不入。寒热往来。或从火治。用芩、连、栀、柏。或从寒治。用姜、桂、茱萸。展转月余。形体羸瘦。六脉弦数。几于毙矣。高鼓峰曰。此肝痛也。非胃脘也。其病起于郁结生火。阴血受伤。肝肾枯干。燥迫成痛。医复投以苦寒辛热之剂。胃脘重伤。其能瘳乎。急以滋肾生肝饮与之。一昼夜。尽三大剂。五鼓熟寐。次日痛定觉饿矣。再用加味归脾汤加麦冬、五味。十余剂而愈。", "3834": "震按江应宿治一男子。心脾痛。六脉弦数。曰。此火郁耳。投姜汁炒黄连、山栀泻火为君。川芎、香附开郁。陈皮、枳壳顺气为臣。反佐以炮姜。从治一服而愈。再与平胃散加姜炒黄连、山栀。神曲糊丸服。永不发。与此案脉同治异。可合参之。", "3835": "丹溪治一人。六月投渊取鱼。至秋深雨凉。半夜小腹痛甚。大汗。脉沉弦细实。重取如循刀责责然。与大承气汤加桂二服。微利痛止。仍连日于申酉时复痛。坚硬不可近。每与前药。得微利。痛暂止。于前药加桃仁泥。下紫黑血升余。痛亦止。脉虽稍减。而责责然犹在。又以前药加川附子。下大便五行。有紫黑血如破絮者二升有余。又伤食。于酉时复痛在脐腹间。脉和。与小建中汤。一服而愈。", "3836": "震按小腹痛甚。大汗。脉如循刀责责。昧者必认为真脏脉矣。否则认其病因是寒。惟用桂、附耳。丹溪连以温药下之。殊不可及。最难者痛止复作。不改前方。陡加桃仁。迨瘀下痛止。仍不改前方。又加附子。至愈后伤食复痛。忽变前方而用建中。总由指下认得真。故攻补毫无疑惑也。下条虞案受寒为重。又误于寒下。故先投温补及艾灸。而后进温下之药。与前案稍别。然皆确切不移。彼此难换。若认脉不清。必至两误。", "3837": "虞天民治一人。壮年寒月。入水网鱼。饥食冷粥。腹大痛。二昼夜不止。医用大黄丸、大承气。下粪水而痛愈甚。诊其六脉沉伏而实。面青黑色。虞曰。此大寒证。及下焦有燥矢作痛。先与丁附治中汤一帖。又灸气海穴二十一壮。痛减半。继以巴豆、沉香、木香作丸如绿豆大。生姜汁送下五粒。下五七次而愈。", "3838": "又一妇年五十余。小腹有块。作痛二月余。一医作死血治。与四物加桃仁等药。不效。又以五灵脂、延胡索、乳香、没药、三棱、莪术等丸服。又不效。其六脉沉伏。两尺脉绝无。虞曰。乃结粪在下焦作痛耳。非死血也。用金城稻藁。烧灰淋浓汁一盏服之。过一时许。与枳实导滞丸一百粒催之。下黑粪如梅核者碗许。痛遂止。后以生血润肠之药十数帖。调理平安。", "3839": "震按尺脉沉实。则为下焦结粪。今两尺绝无而断结粪。又见取脉之巧。非出一途。若死血则脉必涩。前已历载多案矣。", "3840": "汪石山治一人。年五十余。瘦黑理疏。忽腹痛。午后愈甚。医治以快气之药。痛益加。乃曰。午后血行于阴分。加痛者。血滞于阴也。四物加乳、没服之。亦不减。汪诊之。脉浮细而结。或五七至一止。或十四五至一止。经论止。脉渐退者生。渐进者死。今止脉频则反轻。疏则反重。与脉经实相矛盾。汪熟思少顷。曰。得之矣。止脉疏而痛甚者。以热动而脉速。频而反轻者。以热退而脉迟故耳。病属阴虚火动无疑。且察其病起于劳欲。劳则伤心而火动。欲则伤肾而水亏。以参、芍补脾为君。熟地、归身滋肾为臣。黄柏、知母、麦冬清心为佐。山楂、陈皮行滞为使。人乳、童便出入加减。惟人参加至四五钱。遇痛进之则愈。或问诸痛。与瘦黑人。及阴虚火动。参、耆在所当禁。今用之顾效。何取。汪曰。诸痛禁用参、耆者。以暴病形实者言耳。若年高气血衰弱。不用补法。气何由行。痛何由止。经曰。壮者气行则愈是也。", "3841": "一妇人年近五十。病腹痛。初从右手指冷起。渐上至头。头如冷水浇灌而腹大痛。则遍身大热。热退则痛止。或过食。或不食。皆痛。每常或一年一发。近来二三日一发。远不过六七日。医用四物加柴胡、香附。不应。更医用四君、木香、槟榔。亦不应。又用二陈加紫苏、豆蔻。又用七气汤等剂。皆不应。汪诊脉皆微弱。似有似无。或一二至一止。或三五至一止。乃阳气大虚也。独参五钱。陈皮七分。煎服十数帖而愈。夫四肢者诸阳之末。头者诸阳之会。经曰。阳虚则恶寒。又曰。一胜则一负。阳虚阴往乘之则恶寒。阴虚阳往乘之则发热。今指稍逆冷。上至于头。则阴胜阳负可知矣。阳负则不能健运而痛大作。痛作而复热者。物极则反也。及其阴阳气衰。两不相争。则热歇痛亦息矣。仲景曰。血虚气弱。以人参补之。故用独参汤而数年之痛顿愈。", "3842": "震按此条脉象。较上条为易认。然用参不用附。岂以其大冷后发大热。宜补不宜温耶。学者亦当体会之。", "3843": "一人面色苍白。年四十六。素好酒色犬肉。三月间。因酒兼有房事。遂病腹左痛甚。后延腹右。续延小腹。以及满腹皆痛。日夜叫号。足不能伸。卧不能仰。汗出食阻。自用备急丸。利二三行而随止。痛仍不减。汪诊其脉皆细快。右脉颇大于左。独脾脉弦而且滑。扶起诊之。右脉亦皆细数。恐伤酒肉。用二陈加芩、楂、曲糵进之。不效。再用小承气汤。仍不利。蜜煎导之。仍不利。乃以大承气汤。利二三行。痛减未除。令其住药。只煎山楂汤饮之。次日烦躁呕恶。渴饮凉水。则觉恶止爽快。诘朝诊脉。皆隐而不见。四肢逆冷。烦躁不宁。时复汗出。举家惊愕。疑是房后阴证。拟进附子理中汤。汪曰。此治内寒逆冷也。活人书云。四逆无脉。当察证之寒热。今观所患。多属于热。况昨日脉皆细数。面色近赤。又兼酒后而病。六脉虽绝。盖由壮火食气也。四肢者。诸阳之末。气被壮火所食。不能营于四肢。故脉绝而逆冷也。此类伤暑之证。正合仲景所谓热厥者多。寒厥者少。急用大承气汤下之之例。向虽下以大承气。其热尚未尽。难以四逆汤证与比。今用附子热药。宁不助火添病耶。如不得已。可用通脉四逆汤。尚庶几焉。以其内有童便猪胆汁监制附毒。不得以肆其虐也。连进二服。脉仍不应。逆冷不回。渴饮烦躁。小便不通。粪溏反频。腹或时痛。更进人参白虎汤二帖。躁渴如旧。更用参、术各三钱。茯苓、麦冬、车前各一钱。五味、当归各五分。煎一帖。脉渐见如蛛丝。汪曰。有生意矣。仲景论脉绝。服药微续者生。脉暴出者死是也。左手足亦略近和。不致冰人。右足手逆冷如旧。但口尚渴。便尚溏。一日夜约十余度。小便不通。汪曰。渴而小便不利者。当利其小便。遂以天水散冷水调服。三四剂不应。再以四苓散加车前、山栀。煎服二帖。小便颇通。但去大便而小便亦去。不得独利。汪曰。小便未利。烦渴未除。尽由内热耗其津液也。大便尚溏者。亦由内热损其阳气。阳气不固而然也。遂用参、术各三钱。茯苓一钱五分。白芍、车前、门冬各一钱。山栀七分。五味五分。连进数服。至第九日。逆冷回。脉复见。诸证稍减。渐向安。", "3844": "震按此证反复甚多。所用之方。又皆重剂。然寒热互用。而卒能以补收功者。因其身不热。神不昏。与伤寒温疫有别。故可从容挽救也。大抵腹痛由于停食。而房后元气必虚。连下之则虚极。故逆冷脉绝。通脉四逆汤非误。白虎汤殊误。赖有人参。设不用人参。此证早难活也。", "3845": "王中阳治一燕人。久患冷气满腹。上攻下注。大痛不堪。痛阵拥上。即吐冷涎而止。一日一作。饮食不进。遂成骨立。屡用温补不效。王诊之。六脉弦长劲急。两畔别有细脉。沸然而作。状如烂绵。曰。此必胸膈有臭痰在内。病者曰然。众医皆作冷气。因补治下元。日久无效。自觉胸中痞闷。今闻此说。令我大快。遂投滚痰丸。临睡服之。夜半。吐黑绿冷涎败水无数。再服七十丸。其病如脱。以六君子调理而愈。", "3846": "震按王隐君治病。不曰痰。即曰火。可作戴人之法嗣。但腹痛因痰诚有之。此种脉象。更要留心。", "3847": "震按立斋治腹痛。凡兼胸胁作胀。呕吐不食。或吞酸嗳腐。或手足厥冷。皆谓肝木乘脾。多用补中益气及六君子。间有吞左金丸者。或香砂六君子加木香、炮姜、吴茱。其载脉皆曰弦紧。弦长。或弦洪。弦数。何均用参、术。不可易辙耶。", "3848": "孙东宿治吴勉斋。年近五十。有腹痛疾。或作或止。性极急。多躁多怒。今痛在当脐。不间昼夜。市里医者为下之。已五日。大便虽泻。痛则尤甚。饮食不进。手足清冷。形神俱倦。脉仅四至。重按则伏而有力。此由攻克太过。寒凉伤脾。脾虚则中气不运。积反凝滞。以故大便虽泻。而积不行。痛终不减也。治当建立中气为主。中气一回。痛当立止。先与王海藏五神丸二钱。滚水送下。以止其痛。此丸补接元气。安和五脏。升降阴阳。极有神应。故名五神。再用小建中汤。调肝养脾。盖脐下乃肝经部位。惟此汤乃对证剂也。但以桂心换桂枝。加香附。服后痛止。次日进粥太频。且食鸭汁。撼动余积。腹又作痛。且加胀满。面有浮气。里急后重。与四平丸而渐定。外以二陈加香附、砂仁、苍术、山楂。腹中始觉宽快。三日无恙。又纵恣口腹。大啖过饱。腹中大痛。欲吐之则食已下鬲。欲泻之则食未入肠。自喊叫云。可取木香槟榔丸、大承气汤。急与我下之。虽死无撼。孙曰。据痛虽甚。腹则不坚。顾今日适届冬节。礼曰。先王于至日闭关。安静以养微阳。安敢以大寒峻剂而汨天和乎。设不得已。只须桕树东行根上白皮。长流水煎饮之。果泻三五行。痛减大半。再与小建中汤和之。痛又旋减。惟脐下尚不脱然。常常以热手重熨之。大便欲行。及至厕则又不解。知其血少而气不调。用熟地三钱。白芍一钱。杏仁二钱。乌药一钱。木香五分。煎服。下黑粪甚多。十年腹痛沉疴。从此再不复萌。", "3849": "东宿曰。一染匠妇。腹痛两月矣。或以为寒为热。为气为虚。为食积为虫。愈医愈痛。一医与大膏药一个。满腹贴之。痛益剧。乃揭去膏药。即黏牢不可起。火熨油调。百计不能脱分寸。如生在肉上相类。无可奈何。买舟就诊。及抵岸而尽力搀扶。不能动一步。予往视之。见其面色苍黑。手上皮肤燥若老松树皮。六脉皆洪数。叩其不能举步之由。妇曰。非力弱不能行。乃左脚不可动。动即痛应于心。是以一步不能举也。予思色脉皆非死候。胡治而益剧。此必肠痈。左脚莫能举。是其征也。与营卫返魂汤。加金银花为君。酒水各半煎。一帖痛稍减。二帖下黑臭脓半桶。腹上膏药自脱。由热去而膏脱也。痛遂全减。调理而安。", "3850": "缪仲淳曰。包海亭夫人。患腹痛。连少腹上支心。日夜靡间。百药不效。予诊其脉。两寸关俱伏。独两尺实大。按之愈甚。询知其起自暴怒。风木郁于地中。投以川芎、（上）柴胡、（中）升麻。（下）下咽。嗳气数十声。痛立已。已而作喘。予知升之太骤也。以四磨饮与之。遂平。", "3851": "东垣治一人。露宿寒湿之地。腰痛不能转侧。胁搐急。作痛月余。腰痛论云。皆足太阳、足少阴。血络有凝血作痛。间有一二证属少阳胆经。外络脉病。皆去血络之凝。乃愈。经云。冬三月禁针。只宜服药通其经络。破血络中败血。以汉防己、防风各三分。炒曲、独活各五分。川芎、柴胡、肉桂、当归、炙草、苍术各一钱。羌活一钱五分。桃仁五粒。酒煎服愈。", "3852": "丹溪治徐质夫。年六十余。因坠马。腰疼不可转侧。六脉散大。重取则弦小而长。稍坚。朱以为恶血虽有。未可驱逐。且以补接为先。遂令煎苏木、人参、黄耆、芎、归、陈皮、甘草。服至半月后。散大渐敛。食亦进。遂与熟大黄汤调下自然铜等药。一月而安。", "3853": "震按跌伤有瘀。似宜先逐瘀而后补。丹溪则以年之老。脉之散大。反先补而后逐瘀。是其学问之高也。昧者必以为补住恶血。惧不敢补。则尽力逐之。瘀终不去而变端起矣。损伤且然。况内病乎。观此案及治叶先生痢疾案。而知补住邪气。补住恶血之为谬谈也。大抵元气果虚。则补药惟元气受之。而或邪或瘀。不相干涉。若元气不虚。则补药为邪助长。为瘀增痛。诚非所宜。要在能辨其虚与不虚耳。", "3854": "李士材曰。徽州太学方鲁儒。精神困倦。腰膝异痛不可忍。皆曰肾主腰膝而用桂、附。绵延两月。愈觉四肢痿软。腰膝寒冷。遂恣服热药。了无疑惧。比予视之。脉伏于下。极重按之。振指有力。因思阳证似阴。乃火热过极。反兼胜己之化。小便当赤。必畏沸汤。询之果然。乃以黄柏三钱。龙胆草二钱。芩、连、栀子各一钱五分。加生姜七片为向导。乘热顿饮。移时便觉腰间畅快。三剂而痛若失矣。用人参固本丸。日服二两。一月而痊安。", "3855": "震按此与景岳治董翁腰痛相同。但张案则脉洪滑而小水不通。故用大分清饮倍加黄柏、胆草。小水通而腰痛顿止。", "3856": "震按瘀血腰痛。古人原有治法。而想到行房时肾摇血即不瘀。岂非明哲乎。然行瘀多用肉桂。此反用知、柏者。岂于脉中见相火之强耶。", "3857": "孙东宿曰。吴东星冒暑应试。落第而怏怏。因成疟。自中秋延至十月。疟虽止而腰痛甚。且白浊咳嗽。肌肉大削。药剂乱投。如大羌活汤、地黄汤、及连、柏、桂、附、参、茸等皆用过。痛剧欲死。叫撼四邻。予脉之。左弦细。右滑大。俱六至。口渴眼赤。予知其昔患杨梅疮。余毒尚伏经络。适因疟后。气血不足。旧毒感动。故痛而暴也。以归、芍、甘草、牛膝、苡仁、木通、白藓皮、钩藤。用土茯苓四两。煎汤代水煎药。数服而痛止嗽缓。乃以酒后犯房。次日腰如束缚。足面亦疼。左眼赤。小水短。足底有火。从两胯直冲其上。痛不可言。予于方去木通、白藓、土茯苓。加石斛、红花、生地、黄柏。调理三日。证无进退。时值祁寒。因大便燥结。误听人用元明粉。一日夜服至两许。便仍不行。而腰痛愈猛。两足挛缩。气息奄奄。面色青惨。自觉危急。诊之。六脉俱伏。痛使然也。予曰。君证虽热。便虽燥。但病不在肠胃。而在经络筋骨间。徒泻肠胃何益。且闭藏之月。误泻则阳气亏乏。来春无发生根本矣。今四肢拘缩。腰胯痛极者。由天寒而经络凝涩也。寒主收敛。法当温散寒邪之标。使痛定。然后复治其本。乃用桂心、杜仲、炙甘草、苍术、破故纸、五加皮。连与二剂。痛定而四肢柔和。饮食始进。予曰。标病已去。顾今严寒。不可治本。须俟春和。为君拔去病根。渠不信。任他医用滋阴降火。久而无效。至次年三月。予乃以煨肾散进。大泻五六度。四肢冰冷。举家大恐。予曰。病从此去矣。改进理脾药数帖。神气始转。腰胯柔和。可下床举步矣。盖此系杨梅疮余毒伏于经络。岂补剂所能去哉。予故先为疏通湿热。方用补剂收功也。后仍以威灵仙末子二钱。入猪腰子内煨熟食之。又泻一二度。病根尽拔。改用熟地、归、芍、苡仁、牛膝、黄柏、丹参、龟板。调理全安。", "3858": "喻嘉言治张令施之弟。伤寒坏证。两腰偻废。卧床彻夜痛叫。百治不效。喻诊其脉亦平顺。痛则比前大减。乃曰。病非死证。但恐成废人矣。此证之可以转移处。全在痛如刀刺。尚有邪正互争之象。若全然不痛。则邪正混为一家。相安于无事矣。今痛觉大减。实有可忧。因谛思病情。必由热邪深入两腰。血脉久闭。不能复出。止有攻散一法。而邪入既久。正气全虚。攻之必不应。乃以桃仁承气汤。多加肉桂、附子。二大剂与服。服后即能强起。再为丸服。至旬余全安。此仿仲景治结胸证附子泻心汤法。结胸者在上之证。气多。故附子与大黄同用以泻心。腰偻者在下之症。血多。故合桃仁肉桂以散腰间之血结也。后用此法治江生。二剂而愈。", "3859": "汪石山治一人。年逾三十。季夏日午行房。多汗。晚浴又近女色。因患白浊。医用胃苓汤。加右眼作痛。用四物汤入三黄服之。睡醒口愈加苦。又加左膝肿痛。仲冬不药。浊止。渐次延至背痛。不能转侧。日轻夜重。嚏则如绳索撮腰胁。痛楚不堪。呵气亦应背痛。时或梦遗。次年正月。汪诊之。脉皆缓弱无力。脾虚可知。左脉滑者。血热也。遂以参、耆各二钱。苓、术、归身、麦冬各一钱。牛膝、神曲、陈皮、黄柏各七分。甘草、五味各八分。煎服三十余帖。仍以龟板、参、耆、黄柏各二两。熟地、萸肉、枸杞、杜仲、归、茯、牛膝各一两丸服。寻愈。", "3860": "震按汪案养阴益气。卢案补精搜风。祝案汗下以通经。温纳以固肾。俱真实学问。非肤浅伎俩。尚有未备者。背属太阳。若暴痛则审其脉浮紧为伤寒。脉沉缓为寒湿。麻黄汤、羌活胜湿汤。可酌用也。脊系督脉。若久痛。则审其热而痛为阴虚。冷而痛为阳虚。麋茸六味、鹿茸八味。可分用也。若肩背痛则兼肺经。腰背痛则兼肾经。又当各求其因而治之。更有胸与背互换作痛。项与背牵连作痛。背痛彻心。心痛彻背。散在诸书。均宜博览。", "3861": "张戴人治一人病危笃。自述曰。我别无病。三年前。隆暑时出村野。有以煮酒馈予者。冷饮数升。便觉左胁下闷。渐作痛。结硬如石。至今不散。针灸摩药。殊无寸效。张诊之。两手俱沉实而有力。先以独圣散吐之。一涌二三升。气味如酒。其痛即止。后服和脾安胃之剂而愈。震按胁下结硬如石。的系积块。若宗养正积自除之说。而用参、术。何异助纣为虐。幸遇戴人。以涌法起其沉疴。亦赖脉之沉实有力耳。因知善于切脉。则如礼乐与干戈。俱能戡乱致治也。", "3862": "虞天民治一人。年四十余。因骑马跌扑。次年左胁胀痛。医与小柴胡汤加青皮、龙胆草等药。不效。诊其脉。左手寸尺皆弦数而涩。关脉芤而急数。右三部惟数而虚。虞曰。明是死血证。用抵当丸一剂。下黑血二升许。后以四物汤加减。调理而安。", "3863": "震按橘泉翁治一老八十余。左胁大痛。肿起如复杯。手不可近。谓有瘀血在脾中。而立斋治一人右胁胀痛。喜用手按。谓是肝木克脾土。而脾土不能生肺金。若内有瘀血。虽单衣亦不敢著肉。此可以树辨证之洪范矣。又李士材治李明奇。素雄壮。忽左胁痛。手不可近。用左金丸、泻肝汤。至月余。痛处渐大。右胁亦痛。不能行动。神气如痴。惚惚若有所失。面色黄。两关脉促。谓其蓄血已深。非快剂不下。用桃仁承气汤。一服不动。再加干漆、生大黄五钱。下血块十余枚。遂痛止神清。惟见困倦。先与独参汤。再用八珍汤调理。三月而康。此与橘泉之用承气加归、芍、柴胡、黄柏、黄连者。微有不同。但连、柏苦寒。何以瘀血亦下也。", "3864": "薛立斋治一妇人。饮食后因怒患疟。呕吐。用藿香正气散。二剂而愈。后复怒。吐痰甚多。狂言热炽。胸胁胀痛。手按少止。脉洪大无伦。按之微细。此属肝脾二经血虚。以加味逍遥散加熟地、川芎。二剂脉证顿退。再用十全大补而安。此证若用疏通之剂。是犯虚虚之戒矣。", "3865": "石山治一人。客维扬。病胁痛。医以为虚。用人参羊肉补之。其痛愈甚。一医投龙荟丸。痛减。汪诊脉弦濡而弱。曰。脾胃为痛所伤。尚未复。遂以橘皮枳术丸加黄连、当归。服之而安。越五年。腹胁复痛。彼思颇类前病。欲服龙荟丸未决。汪诊之。脉皆濡弱而缓。曰。前病属实。今病属虚。非前药可治也。以人参为君。芎、归、芍药为臣。香附、陈皮为佐。甘草、山栀为使。煎服十余帖。痛止食进。", "3866": "震按此人之脉。先后皆濡弱。惟弦与缓不同。而先用清。后用补者。岂以弦为肝火。缓属脾虚耶。然弦而濡弱。亦宜补不宜清矣。观立斋治马庠生之母。左胛连胁作痛。其脉右关弦长。按之软弱。左关弦洪。按之涩滞。薛曰。郁怒伤肝脾。六君加芎、归而愈。则弦脉又不得尽责之肝火也。", "3867": "一人六月途行。受热。过劳。性又躁暴。忽左胁痛。皮肤上一片红如碗大。发水泡疮三五点。脉七至而弦。夜重于昼。医作肝经郁火治之。以黄连、青皮、香附、川芎、柴胡之类。进一服。其夜痛极。且憎热。次早视之。皮肤上红大如盘。水泡疮又加至三十余粒。医教以水调白矾末敷。仍于前药加青黛、龙胆草进之。夜痛益甚。胁中如钩摘之状。次早视之。红及半身矣。水泡又增至百数。乃求王古潭。为订一方。以大栝蒌一枚。重一二两者。连皮捣烂。加粉草二钱。红花五分。进药少顷。即得睡。比觉已不痛矣。盖痛势已急。而时医执寻常泻肝正治之剂。又多苦寒。愈添其燥。故病转增剧。水泡疮发于外者。肝郁既久。不得发越。乃侮所不胜。故皮腠为之溃也。栝蒌味甘寒。经云。泄其肝者缓其中。且其为物。柔而滑润。于郁不逆。甘缓润下。又如油之洗物。未尝不洁。此其所以奏效之捷也欤。", "3868": "孙东宿治李悦斋夫人。胸胁大腹作痛。谵语如狂。寅卯辰三时少轻。午后及夜。痛剧咬人。昼夜不睡。饮食不进者十八日。究其故。原有痰火与头疼牙疼之疾。又因经行三日后。头疼发寒热。医以疟治。因大恶热。三四人交扇之。而两手浸冷水中。口噙水而不咽。鼻有微衄。又常自悲自哭。目以多哭而肿。小水直下不固。喉梗梗吞药不下。脉则左弦数。右关洪滑。孙曰。此热入血室证也。误服刚燥之剂而动痰火。以致标本交作。诸人犹谓热入血室。惟夜间谵语如见鬼。何至胸胁疼剧咬人耶。孙曰。仲景云。经水适来适止得疾。皆作热入血室治。痛极咬人者。乃胃虚虫行求食而不得。故喉中梗梗然也。即以小柴胡加桃仁、丹皮。而谵语减。次日以安蛔汤与服。而疼止食进。", "3869": "徐可豫治吴兴沈中刚内子。膝肿痛。右先剧。以热熨则攻左。熨左攻右。俱熨则雷鸣上胸。已而背悉若受万棰者。独元首弗及。发则面黛色。脉罔辨。昏作旦辍。日尫弱甚。医望色辄却。谓勿救。徐视脉竟。曰。是湿淫所中。继复惊伤胆。疾虽剧。可治。即令以帛缠胸。少间。探咽喉间。涌青白涎沫几斗许。涌定。徐曰。今兹疾发。至腹则弗上面。面弗青矣。至昏膝痛。仍加熨。鸣果弗及胸止。三鼓已定。皆如徐言。越三昏。不复作。遂痊。", "3870": "项彦章治史佥宪足病。发则两足如柱。溃黄水。逾月乃已。已辄发。六脉沉缓。沉为里有湿。缓为厥为风。此风湿毒。俗名湿脚气是也。以神芎丸、舟车神佑丸。大下浊水而愈。", "3871": "赵良仁云。予至吴中。有徐孟达患两足酸重。不任行动。发则肿痛。一日于不发时诊脉。三部皆大。搏手如葱管无力。身半以上则肥盛。盖其膏粱妾御。嗜欲无穷。精血不足。湿热太盛。因用益精血于其下。清湿热于其上。二方与之。或言脚气无补法。故不肯服。三月后痛作。一医用南方法。治不效。一医用北法泻之。即死于溺器上。吁。业岐黄者。虚实之辨。盖可以忽乎哉。", "3872": "立斋治一妇人。脚患筋挛骨痛。诸药不应。脉紧。用大防风汤。二剂顿退。又二剂而安。", "3873": "施笠泽治少司成张侗初。患足胫痛三年矣。诊之。脉沉细而涩。曰。此下焦元气不足。不能荣养筋骨。当用滋补舒筋之剂。服后微效。因劳旋作。再诊之。脉兼浮数。元气愈耗矣。为制人参膏及河车天乙丸。间服。元气渐壮。独两胫作楚不能忍。因制万灵膏去樟脑。加韶粉、苏合、麝香。以软帛紧系两胫。仍令饮甘草汤。不顷刻而痛若失。此膏良验。方载本草纲目。后用黄耆建中汤加参、归。调理全安。", "3874": "罗谦甫治杨郎中之内。年五十余。体肥盛。春患头目昏闷。面赤热。多服清上药。不效。罗诊其脉洪大而有力。内经云。面热者。足阳明病。脉经云。阳明经气盛有余。则身以前皆热。况其人素膏粱。积热于胃。阳明多血多气。本实则风热上行。诸阳皆会于头。故面热之病生矣。先以调胃承气汤七钱。黄连二钱。犀角一钱。疏利三两行。撤其本热。次以升麻加黄连汤。去经络中风热上行。则标本之病俱退矣。方以升麻、葛根各一钱。白芷七分。甘草、炙白芍各五分。连、芩酒制各四分。川芎、生犀末各三分。荆芥穗、薄荷叶各二分。水半盏。先浸川芎、荆芥穗、薄荷。另以水二盏半煎至一盏半。入先浸三味同煎。至一盏。食后温服。日三服。忌湿面五辛之物。", "3875": "真定府维摩院僧。年六十余。体瘠弱。初冬。头面不耐寒。气弱不敢当风行。诸法不效。罗诊其脉。弦细而微。且年高常食素茶果。此阳明之经本虚。脉经云。气不足。则身以前皆寒栗。又加诵经文损气。由此胃气虚。经络之气亦虚。不能上达头面。故大恶风寒。先以附子理中丸数服。温其中气。次以升麻汤加附子行其经络。方以升麻、葛根各一钱。白芷、黄耆各七分。炙甘草、草豆蔻仁、人参各五分。黑附炮七分。益智三分。连须葱白同煎。数服良愈。或曰。升麻汤加黄连治面热。加附子治面寒。有何依据。答曰。出自仲景。盖诊杨氏脉阳明标本俱实。宜先攻其里。后泻经络中风热。故升麻汤加黄连。以寒治热也。尼僧阳明标本俱虚寒。宜先实其里。次行经络。故升麻汤加附子。以热治寒也。仲景群方之祖。信哉。", "3876": "又治一妇三十余岁。忧思不已。饮食失节。脾胃有伤。面色黧黑不泽。环唇尤甚。心悬如饥。饥不欲食。气短而促。罗曰。人身心肺在上。行营卫而光泽于外。色宜显而不藏。肾肝在下。养筋骨而强壮于内。色当隐而不见。又必赖脾胃在中。传化精微。以灌四旁。冲和而不息。若其气一伤。则四脏失所。今忧思不已。脾胃气结而不行。饮食失节。脾胃气耗而不足。故使阴气上溢于阳中。而黑色见于面。又经云。脾气通于口。其华在唇。今水反侮土。故黑色见于唇。此阴阳相反。病之逆也。上古天真论云。阳明脉衰于上。面始焦。可知阳明之气不足。乃用冲和顺气汤。以葛根一钱五分。升麻、防风各一钱。白芷、黄耆各八分。人参七分。甘草四分。白芍、苍术各三分。以姜、枣煎。已午前服。取天气上升之时。使人之阴气易达也。数服而愈。此阴出乘阳治法也。", "3877": "立斋治一人。年二十。耳内出水作痛。年余矣。脉洪数。尺脉为甚。属肝肾二经虚热。用加减地黄丸料。一剂而愈。", "3878": "震按以上三案。或凭脉。或凭证。亦皆易辨。惟用加减八味丸者。谅其尺脉必微弱。或虚大。故加温药以导纳之。若尺脉洪数。似宜用知柏地黄丸。", "3879": "石山治一人。年近六十。面色苍白。病左耳聋。三十年矣。近年来。或头左边及耳皆肿。溃脓。脓从耳出甚多。时或又肿复脓。今则右耳亦聋。屡服祛风去热逐痰之药。不效。汪诊左手心脉浮小而快。肝肾沉小而快。右脉皆虚散而数。此恐乘舆远来。脉未定耳。来早脉皆稍敛。不及五至。非比日前之甚数也。夫头之左边及耳前后皆属于少阳也。经曰。少阳多气少血。今用风药痰药。类皆燥剂。少血之经。又以燥剂燥之。则血愈虚少矣。血少则涩滞。涩滞则壅肿。且血逢冷则碍。今复以寒剂凝之。愈助其壅肿。久则郁而为热。腐肉成脓。从耳中出矣。渐至右耳亦聋者。脉络相贯。血气相依。未有血病而气不病也。故始则左病。而终至于右亦病矣。是为病久气血两虚。且年六十。气血日涸。而又出外劳伤气血。又多服燥剂以损其气血。脓又大泄以竭其气血。则虚而又虚可知矣。以理论之。当滋养气血。气血健旺。则运行有常而病自去矣。否则不惟病不除。而脑痈耳疽。抑亦有不免矣。人参二钱。黄耆三钱。归身、白术、生姜各一钱。鼠黏子、连翘、柴胡、陈皮各六分。川芎、片芩、白芍各七分。甘草五分。煎服十数帖而愈。", "3880": "震按汪公之议论精微而又显畅。用药亦标本兼赅。真有掉臂游行之乐。即初诊时乘舆远来。脉未定。而不足凭之说。更可为卤莽者鉴戒。", "3881": "江应宿治上舍孙顺吾。患耳鸣重听。人事烦冗。杂治半年不愈。江视之。脉数滑。以二陈加瞿麦、萹蓄、木通、黄柏。一服知。二服已。", "3882": "震按丹铅续录。载王万里患耳痛。魏文靖公谓易之坎为耳痛。恐则伤肾所致。其论与此颇同。而用青盐、鹿茸、雄、附为剂。则药之阴阳各别。要当以脉辨之。", "3883": "江篁南治一壮年。患鼻齄。胸膈不利。医用苦寒驱风败血之剂。服之年余。其人倦怠甚。目不欲开。江诊视。右寸脉浮洪带结。余部皆沉细而软。曰。鼻齄虽是多酒所伤。然苦寒驱风败血之药。岂宜常服。经曰。苦伤气。又曰。苦伤血。况风药多燥。燥胜血。服之积久。安得不倦怠耶。且目得血而能视。目不欲开者。血伤。倦怠者。气伤也。所谓虚其虚。误矣。治宜化滞血。生新血。四物加炒片芩、红花、茯苓、陈皮、甘草、黄耆煎服。兼服固本丸。日就强健。鼻齄亦愈。", "3884": "丹溪治一女子。十七八岁。发尽脱。饮食起居如常。脉微弦而涩。轻重皆同。此厚味成熟。湿痰在膈间。复因多食酸梅。以致湿热之痰。随上升之气至于头。熏蒸发根之血。渐成枯槁。遂一时脱落。治须补血升散。乃用防风通圣散去硝。惟大黄酒炒三次。兼以四物。合作小剂与之。月余。诊其脉。知湿热渐解。乃停药。淡味二年。发长如初。", "3885": "震按发乃血之余。枯焦者血不足也。若忽然脱落。或头皮痒须眉亦落。乃血热生风。风摇木落之象。酒客膏粱多此。脉数者。用通圣散宣泄风热。次用六味地黄丸。如下条治法。又有劳伤精血。及恼怒阴火上炎而致者。宜用此条治法。", "3886": "东垣治一人。因多食猪肉煎饼。同蒜醋食之。后复饮酒大醉。卧于暖炕。翌日。二瞳子散。大于黄睛。视物无的实。以小为大。以短为长。卒然见非常之处。行路踏空。百治不效。曰。经云。五脏六腑之精气。皆上注于目而为之精。精之窠为眼。骨之精为瞳子。又云。筋骨气血之精为脉。并为系。上属于脑。又云。瞳子黑眼法于阴。今瞳子散大者。由食辛热物太甚故也。辛主散。热则助火。上乘于脑中。其精故散。精散则视物亦散大也。夫精明者。所以视万物者也。今视物不真。精且衰矣。盖火之与气。势不两立。经曰。壮火食气。壮火散气。手少阴足厥阴所主。上连目系。邪之中人。各从其类。风与热循此道而来攻。故头目肿闷而瞳子散大。皆由血虚阴弱所致也。当除风热。凉血益血。以收耗散之气。则病愈矣。用滋阴地黄丸。经云。热淫所胜。平以咸寒。佐以苦甘。以酸收之。以黄芩、黄连大苦寒。除热邪之盛为君。当归身辛温。生熟地黄苦甘寒。养血凉血为臣。五味酸寒。体轻浮。上收瞳子之散大。人参、甘草、地骨皮、天门冬、枳壳苦甘寒。泻热补气为佐。柴胡引用为使。忌食辛辣物助火邪。及食寒冷物捐胃气。药不能上行也。", "3887": "魏夫人目翳暴生。从下而起。其色绿。瞳痛不可忍。东垣曰。翳从下而上。病从阳明来也。绿非五色之正。此肾肺合而为病。乃以墨调腻粉合之。却与翳色相同。肾肺为病明矣。乃泻肾肺之邪。入阳明之药为使。既效矣。他日病复作者三。其所从来之经。与医色各异。因悟曰。诸脉皆属于目。脉病则目从之。此必经络未调。则目病未已也。因视所不调者治之。疾遂不作。", "3888": "震按此辨翳色甚巧。后之复发者三。翳色各异。合以诸脉皆属于目之经文。自当恍然。虽不载方药。而云视所不调者治之。亦可以意会矣。", "3889": "省郎中张子敬。年六十七。病眼目昏暗。唇微黑色。皮肤不泽。六脉弦细而无力。一日出示治眼二方。问可服否。罗谦甫曰。此药皆以黄连大苦之药为君。诸风药为使。夫人年五十。胆汁减而目始不明。内经云。土位之主。其泻以苦。诸风药亦皆泻土。年近七十。脾胃虚而皮肉枯。重泻其土。使脾胃之气愈虚。而不能营运荣卫之气。滋养元气。胃气不能上行。膈气吐食。诸病生焉。此药不可服。只宜慎言语。节饮食。惩忿窒欲。此不治之治也。张以为然。明年春。除关西路按察使。三年致仕还。精神清胜。脉亦和平。此不妄服寒药之效也。内经曰。诛伐无过。是谓大惑。岂不信哉。", "3890": "一壮年。忽早起视物不见。就睡片时。略见而不明。食减倦甚。脉缓大四至之上。重则散而无力。意其受湿所致。询之。果卧湿地半月。遂以白术为君。黄耆、茯苓、陈皮为臣。附子为使。十余帖愈。", "3891": "一人形实。好热酒。忽目盲。脉涩。此热酒伤。胃气污浊。血死其中而然也。以苏木作汤。调人参末。服二日。鼻及二掌皆紫黑。朱曰。滞血行矣。以四物加苏木、桃仁、红花、陈皮煎。调人参末服。数日而愈。", "3892": "吕沧洲治一人。病二目视物皆倒植。屡治不效。曰。视一物为二。视直为曲。古人尝言之矣。视物倒植。诚所未喻也。愿闻其因。彼曰。某尝大醉。尽吐所饮酒。熟睡达曙。遂病。吕切其脉左关浮促。余部皆无恙。即告之曰。当伤酒大吐时。上焦反复。致倒其胆府。故视物皆倒植。此不内外因而致内伤者也。法当复吐以正其胆府。遂授藜芦、瓜蒂为粗末。水煎。俾平旦顿服涌之。涌毕。视物不倒植。", "3893": "淮安陈吉老。儒医也。有富翁子。忽病视正物皆以为斜。凡几案书册之类。排设整齐。必更移令斜。自以为正。以至书写尺牍皆然。父母忧之。医者不谙其疾。或以吉老告。遂携子求治。既诊脉后。令其父先归。留其子设乐开宴。酬劝至醉乃罢。扶病者坐轿中。使人舁之。高下其手。常令倾倒辗转。久之方令登榻而卧。达旦酒醒。遣之归家。前日斜视之物。皆理正之。父母跃然而喜。往问治之之方。吉老云。醉中尝闪倒肝之一叶搭于肺上。不能下。故视正物为斜。今复饮之醉则肺胀。展转之间。肺亦垂下矣。药安能治之哉。富翁叹服。", "3894": "钱仲阳治一乳妇。因悸而病。既愈。目张不得瞑。钱曰。煮郁李酒饮之使醉。即愈。所以然者。目系内连肝胆。恐则气结。胆衡不下。郁李能去结。随酒入胆。结去胆下。目能瞑矣。饮之果验。孙真人奉旨治卫才人眼疼。前众医不能疗。或用寒药。或用补药。加之脏腑不和。孙诊之。肝脉弦滑。非壅热也。乃年壮血盛。肝血并不通。遂问宫人。月经已三月不通矣。用通经药经行而愈。", "3895": "震按肝脉弦滑。能不误认为风痰病眼乎。因肝藏血而知其血盛不通。诚切当矣。然犹问宫人始得停经三月之信。并不先言据脉当停经也。真人尚如此。奈何讳疾者每不言以责其断病耶。此正犯东坡所谓我欲困医。而我病亦适为医所困耳。", "3896": "石山治一妇。年逾四十。两眼昏昧。咳嗽头痛。似鸣而痛。若过饥。恶心。医以眼科治之。病甚。翁诊脉皆细弱。脾部尤近弦弱。曰。脾虚也。东垣云。五脏六腑。皆禀受于脾。上贯于目。脾虚则五脏之精气皆失所司。不能归明于目矣。邪逢其身之虚。随眼系入于脑。则脑鸣而头痛。心者。君火也。宜静。相火代行其令。劳役运动。则妄行。侮其所胜。故咳嗽也。医不理脾养血。而以苦寒治眼。是谓治标不治本。乃用参、耆各一钱五分。麦冬、贝母各一钱。归身八分。陈皮、川芎、黄芩各七分。甘草、菊花各五分。麦芽四分。煎服二帖。诸证悉除。", "3897": "薛己治给事张禹功。目赤不明。服祛风散热药。反畏明重听。脉大而虚。此因劳心过度。饮食失节。以补中益气加茯神、枣仁、山药、山茱萸、五味。顿愈。又劳役复甚。用十全大补。兼以前药。渐愈。却用补中益气加前药而痊。东垣云。诸经脉络。皆走于面而行空窍。其清气散于目而为精。走于耳而为听。若心烦事冗。饮食失节。脾胃亏损。心火太甚。百脉沸腾。邪害孔窍而失明矣。况脾为诸阴之首。目为血脉之宗。脾虚则五脏之精气皆失其所。若不理脾胃。不养气血。乃治标而不治本也。", "3898": "震按此二案。专治脾虚。并不治目而目亦愈。盖治脾虚即所以治目。由于诊脉得其要领也。惟同用参、耆。汪案则佐以麦冬、贝母、川芎、黄芩、菊花。因有咳嗽头痛。尚带一二分客邪耳。薛案则纯补。兼佐酸收。因曾服祛风散热药。反畏明重听。迨补之得愈。而劳役复甚。其虚为尤甚耳。", "3899": "孙东宿治孙如亭令正。年过四十。眼偶赤肿。两太阳疼痛。大便不行者三日。平时泛期。一月仅两日。今行四日未止。眼科余云谷医治逾候。肿赤不消。而右眼内眦突生一白泡。垂与鼻齐。大二寸余。余见而骇走。以为奇疾。莫能措剂。又见其呕吐。眩运。伏于枕上。略不敢动。稍动则眩愈极。吐愈急。辞不治。孙诊之。两寸关脉俱滑大有力。两尺沉微。孙曰。此中焦有痰。肝胆有火。必为怒气所触而然。内经云。诸风掉眩。皆属肝木。诸逆冲上。皆属于火。盖无痰不能运也。眼眦白泡。乃火性急速。怒气加之。气乘于络。上而不行。故直胀出眼外也。古壮士一怒而目眦裂。与白泡胀出眦外理同。肝为血海。故血亦来不止。治当抑其肝木。清镇痰火。则诸症自瘳。先用姜汁益元丸压其痰火。以止呕吐。再以二陈汤加酒连、酒芩、天麻、滑石、吴茱萸、竹茹、枳实。一帖眩吐俱定。头稍能动。改用二陈加芩、连、谷精草、夏枯草、香附、吴茱萸、苡仁。四剂目疾全愈。血海亦净。", "3900": "震按两目肿痛。用独参汤奇矣。及讲明其理。始知是正非奇。然亦须审兼见之证。与脉象若何。盖木寡于畏。肝火上逆。目既肿痛而或赤。脉若弦大而且数。口渴内热。投以此方。不虞其痛之丧明乎。", "3901": "报国澄和尚。患眼疾二年。服祛风清热药过多。致耳鸣嘈嘈不止。大便常苦燥结。近来左眼上微翳。见灯火则大如斗。视月光则小如萤。询诸方家。俱莫能解。因以质之石顽。石顽曰。此水亏而阴火用事也。试以格物之理参之。如西洋玻璃眼镜。以十二镜编十二支为一套。无论老少。其间必有一者能察秋毫。则知人眼有十二种偏胜。故造眼镜者。亦以十二等铅料配之。取铅以助阴精。料以助阳气也。若铅料之轻重。与眼之偏胜不相当。则得之反加障碍矣。月乃至阴之精。真水内涸。不能泛滥其光。所以视之甚小。设加之以铅重者。则视月必大矣。灯本燃膏之焰。专扰乎阴。不能胜其灼烁。所以见之甚大。设加之以料重者。灯火必愈大矣。合脉参证。知为平昔劳伤心脾。火土二脏过燥。并伤肾水真阴也。遂疏天王补心丹与之。他如中翰徐燕及。见日光则昏迷如蒙。见灯火则精彩倍常。此平昔恒劳心肾。上盛下虚所致。盖上盛则五志聚于心包。暗侮其君。如权党在位。蒙蔽九重。下虚则相火失职。不能司明察之令。得灯烛相助其力。是以精彩胜于常时。此与婴儿胎寒夜啼。见火则止之义不殊。未识专事眼科者。能悉此义否。", "3902": "罗谦甫治征南元帅不邻吉歹。年七旬。春间东征。南回至楚邱。因过饮。腹痛肠鸣自利。日夜约五十余行。咽嗌疼痛。耳前后赤肿。舌本强。涎唾稠黏。欲吐不能出。以手曳之方出。言语艰难。反侧闷乱。夜不能卧。罗诊得脉浮数。按之沉细而弦。即谓中丞黏公曰。仲景云。下利清谷。身体疼痛。急当救里。后清便自调。急当救表。救里四逆汤。救表桂枝汤。总帅今胃气不守。下利清谷。腹中疼痛。虽宜急治之。比之嗌咽。犹可少缓。公曰。何谓也。答曰。内经云。疮发于咽嗌。名曰猛疽。此病治迟则塞咽。咽塞则气不通。气不通则半日死。故宜急治。于是遂砭刺肿上。紫黑血出。顷时肿势大消。遂用桔梗、甘草、连翘、鼠黏子、酒黄芩、升麻、防风等分。每服约五钱。水煎清。令热漱之。冷吐出之。咽下恐伤脾胃。自利转甚。再服涎清肿散。声出。后以神应丸辛热之剂以散中寒。解化宿食而燥脾湿。丸者。取其不即施行。则不犯其上焦。至其病所而后化。乃治主以缓也。不数服。利止痛定。后胸中闭塞。作阵而痛。复思灵枢有云。上焦如雾。宣五谷味。熏肤充身泽毛。若雾露之溉。是为气也。今公年高气弱。自利无度。致胃中生发之气。不能滋养于心胃。故闭塞而痛。经云。上气不足。推之扬之。脾不足者。以甘补之。用异功散甘辛微温之剂温养脾胃。加升麻、人参。上升以顺正气。不数服而胸快。利痛止。内经云。调气之方。必别阴阳。内者内治。外者外治。微者调之。其次平之。胜者夺之。随其攸利。万举万全。又曰。病有远近。治有缓急。毋越其制度。又曰。急则治其标。缓则治其本。此之谓也。", "3903": "〔附〕杨立之自广府通判归楚州。喉间生痈。既肿溃而脓血流注。日夕不止。寝食俱废。医生束手。适杨吉老赴郡。二子邀之至。熟视良久曰。不须看脉。已知之。然此疾甚异。须先啖生姜片一斤。乃可投药。否则无法也。语毕即出。其子有难色。曰。喉中溃脓痛楚。岂能食生姜。立之曰。吉老医术通神。其言不妄。试取一二片啖我。如不能进。屏去无害。遂食之。初时殊为甘香。稍复加至半斤许。痛处已宽。满一斤。始觉味辛辣。脓血顿尽。粥食入口。了无滞碍。明日。招吉老谢而问之。曰。君官南方。多食鹧鸪。此禽好啖半夏。久而毒发。故以姜制之。今病源已清。无服他药。", "3904": "景岳治一来宅女人。年近三旬。患虚损。更兼喉癣疼痛。多医罔效。张诊其脉。则数而无力。察其证。则大便溏泄。问其治。则皆退热清火之剂。然愈清火而喉愈痛。因知其本非实火。而且多用寒凉。以致肚腹不实。总亦格阳之类也。遂专用理阴煎及大补元煎之类。出入间用。不半月而喉痛减。不半年而病全愈。", "3905": "又治王蓬雀。年出三旬。患喉痹。十余日。头面浮大。喉颈粗极。气急声哑。咽肿口疮。痛楚之甚。一婢倚背。坐而不卧者累日矣。及察其脉。则细数微弱之甚。问其言。则声微似不能振者。询其所服之药。则无非芩、连、知、柏之属。此盖以伤阴而起。而复为寒凉所逼。以致寒盛于下。而格阳于上。即水饮之类俱已难入。而尤畏烦热。张曰危哉。再迟半日。必不救矣。遂与镇阴煎。以冷水顿冷。徐徐使咽之。用毕一煎。过宿而头项肿痛尽消如失。继进五福饮。数剂而起。", "3906": "震按古人喉证案无甚佳者。以上数条。亦取其不同者而选之。王蓬雀案治法最佳。然此人能受温补。故一剂即效。亦有投以温补而不效者。即阳证阴脉之死候也。未可谓景岳之法概能活人。余乡有戚许君。初起外感发热。继则左耳门生小疖。溃腐。认为聤耳。敷以药。溃腐不退。通耳肿赤。延及头面皆肿赤。痛极汗大出。身热反得凉。颇能进食。似觉稍安。越三日。忽又发热。左耳前后连头面肿痛更甚。渐神昏谵语。盖因连日出门登厕。复受风邪所致。内外科皆以脉小而数。按之无力。虑其虚陷。余友李昆阳兄至。曰。是为耳游风。非致命之疮。重复冒风。故现险象。外敷以药。内用大剂风药散之。而肿痛与身热俱退。惟神昏谵语不减。两日后。昏谵更甚。汤粥入口即吐。手足厥冷。呃逆不止。势又危极。李以箸抉其口视之。则咽喉腐烂。悬雍赤紫肿大。如茄子下坠。脉仍细数。右手尤软。乃曰。连日不食。胃气大虚。故呕且呃。命以白米三升。大锅煮粥。取锅面团结之粥油与食。遂纳而不吐。复用药搅洗喉间之腐秽。随以石膏四五两。竹叶一大把。煎汤与漱。且服。服竟夜。神昏稍醒。呃止厥回。又进大剂芩、莲、白虎、栀、翘等药。数日得愈。此与景岳之案冰炭相反。因思凡为医者。读古人书。断不可执其一说。自以为是也。", "3907": "一男子舌下牵强。手大指次指不仁。或大便秘结。或皮肤赤晕。薛曰。大肠之脉散舌下。此大肠血虚风热。当用逍遥散加槐角、秦艽治之。", "3908": "易思兰治一人患齿病。每遇房劳。或恼怒。齿即俱长。痛不可忍。热汤凉水。俱不得入。发必三五日。苦状难述。竟绝欲。服补阴丸、清胃饮。俱不效。易诊其脉。上二部俱得本体。惟二尺洪数有力。愈按愈坚。乃曰。沉濡而滑者肾脉。洪数有力者心脉。今于肾部见心脉。是所不胜者侮其所胜。乃妻入乘夫。肾中火邪盛矣。清胃饮惟胃脉洪数者为宜。今胃脉平和。清之何益。肾主骨。齿乃骨余。火盛而齿长。补之何益。况有干姜。更非所宜。乃用黄柏三钱。以滋水泄火。青盐一钱为引。升麻一钱。升出肾中火邪。药入口。且漱且咽。服后即觉丹田热气上升。自咽而出。再进二帖。病即全愈。", "3909": "震按此案医理讲得最精。由于脉象诊得的真。而更运以巧思。斯发无不中矣。清胃散之庸。诚不足责。即泛用滋阴药。亦难应手。只此三味。铨解甚明。信乎缺一味不可。多一味不必也。余乡有患齿痛数年。诸药不效者。叶天士先生用山萸肉、北五味、女贞子、旱莲草各三钱。淮牛膝、青盐各一钱而全愈。此取酸盐下降。引肾经之火。归宿肾经。可与易公之方。并垂不朽。而其义各别。", "3910": "东垣治一人。年六十二。素有脾胃虚损病。目疾时作。身面目睛俱黄。小便或黄或白。大便不调。饮食减少。气短上气。怠惰嗜卧。四肢不收。至六月中。目疾复作。医以泻肝散。下数行。而前疾增剧。李谓大黄、牵牛。虽除湿热而不能走经络。下咽。不入肝经。先入胃中。大黄苦寒。重虚其胃。牵牛其味至辛。能泻气。重虚肺本。嗽大作。盖标实不去。本愈虚甚。加之适当暑雨之际。素有黄证之人。所以增剧也。此当于脾胃肺之本脏。泻外经中之湿热。制清神益气汤主之。茯苓、升麻各二分。泽泻、苍术、防风各三分。生姜四分。此药能走经。除湿热而不守。故不泻本脏。补肺与脾胃本脏中气之虚弱。青皮一分。橘皮、生甘草、白芍药、白术各二分。人参五分。此药皆能守本而不走经。不走经者。不滋经络中邪。守者。能补脏之元气。黄柏一分。麦冬二分。人参二分。五味子三分。此药去时令浮热湿蒸。上都作一服。水二盏。煎至一盏。去渣。稍热空心服。火炽之极。金伏之际。而寒水绝体于此时也。故急救以生脉散。除其湿热以恶其太甚。肺欲收。心苦缓。皆酸以收之。心火盛。则甘以泻之。故人参之甘。佐以五味子之酸。孙思邈云。夏月常服五味子。以补五脏气是也。麦门冬之微苦寒。能滋水之源于金之位。而清肃肺气。又能除火刑金之嗽。而敛其痰邪。复微加黄柏之苦寒。以为守位。滋水之流。以镇坠其浮气。而除两足之痿弱也。", "3911": "罗谦甫治兀颜正卿。二月间因官事劳役。饮食不节。心火乘脾。脾气虚弱。又以恚怒。气逆伤肝。心下痞满。四肢困倦。身体麻木。次传身目俱黄。微见青色。颜黑。心神烦乱。怔忡不安。兀兀欲吐。口恶生冷。饮食迟化。时下完谷。小便癃闭而赤黑。辰巳间发热。日暮则止。至四月尤盛。罗诊其脉浮而缓。金匮要略云。寸口脉浮为风。缓为痹。痹非中风。四肢苦烦。脾色必黄。瘀热以行。跗阳脉紧为伤脾。风寒相搏。食谷则眩。谷气不消。胃中苦浊。浊气下流。小便不通。阴被其寒。热流膀胱。身体尽黄。名曰谷疸。以茵陈叶一钱。茯苓五分。栀子仁、苍术去皮炒、白术各三钱。生黄芩六分。黄连、枳实、猪苓去皮、泽泻、陈皮、汉防己各二分。青皮去白一分。作一服。以长流水三盏。煎至一盏。名曰茯苓栀子茵陈汤。一服减半。二服良愈。内经云。热淫于内。治以酸寒。佐以苦甘。又湿化于火。热反胜之。治以苦寒。以苦泄之。以淡渗之。栀子、茵陈苦寒。能泻湿热而退其黄。故以为君。难经云。苦主心下满。以黄连、枳实苦寒。泄心下痞满。肺主气。今热伤其气。故身体麻木。以黄芩苦寒。泻火补气。故以为臣。二术苦甘温。青皮苦辛温。能除胃中湿热。泄其壅滞。养其正气。汉防己苦寒。能去十二经留湿。泽泻咸平。茯苓、猪苓甘平。导膀胱中热。利小便而去癃闭也。", "3912": "至元丙寅六月。时雨霖霪。人多病湿温。真定韩君祥。因劳役过度。渴饮凉茶。及食冷物。遂病头痛。肢节亦疼。身体沉重。胸满不食。自以为外感内伤。用通圣散二服。加身体困甚。医以百解散发其汗。越四日。以小柴胡汤二服。复加烦热躁渴。又六日。以三一承气汤下之。躁渴尤甚。又投白虎加人参、柴胡饮子之类。病愈增。又易医用黄连解毒汤、朱砂膏、至宝丹之类。至十七日后。病势转增。传变身目俱黄。肢体沉重。背恶寒。皮肤冷。心下痞硬。按之则痛。眼涩不欲开。目睛不了了。懒言语。自汗。小便利。大便了而不了。罗诊其脉紧细。按之空虚。两寸脉短不及本位。此证得之因时热而多饮冷。加以寒凉寒药过度。助水乘心反来侮土。先囚其母。后薄其子。经云。薄所不胜。乘所胜也。时值霖雨。乃寒湿相合。此为阴证发黄明矣。罗以茵陈附子干姜汤主之。内经云。寒淫于内。治以甘热。佐以苦辛。湿淫所胜。平以苦热。以淡渗之。以苦燥之。附子干姜辛甘大热。散其中寒。故以为主。半夏、草豆蔻辛热。白术、陈皮苦甘温。健脾燥湿。故以为臣。生姜辛温以散之。泽泻甘平以渗之。枳实苦微寒。泄其痞满。茵陈苦微寒。其气轻浮。佐以姜、附。能去肤腠间寒湿而退其黄。故为佐使也。煎服一两。前证减半。再服悉去。又与理中汤服之。数日气得平复。或者难曰。发黄皆以为热。今暑隆盛之时。又以热药治之而愈。何也。罗曰。主乎理耳。成无己云。阴症有二。一得始外伤寒邪。阴经受之。或因食冷物。伤太阳经也。一者始得阳证。以寒治之。寒凉过度。变阳为阴也。今君祥因天令暑热。冷物伤脾。过服寒凉。阴气大胜。阳气欲绝。加以阴雨寒湿相合。发而为黄也。仲景所谓当于寒湿中求之。李思顺云。解之而寒凉过剂。泻之而逐寇伤君。正以此耳。圣贤之制。岂敢越哉。或曰。洁古之学。有自来矣。", "3913": "江篁南治犹子三阳患疸证。皮肤目睛皆黄。小溲赤。左脉弦而数。右三部原不应指。今重按之隐隐然指下。证见午后发热。五更方退。以茵陈五苓散除桂。加当归、栀子、黄柏、柴胡。数服。继用人参养荣汤。乃八物除芎。加耆、陈皮、五味、姜、枣。兼人乳、童溲。热退三日。已而复作。间日发于午后。肌热灼指。脉近弦。乃作疟治之而愈。后数年。复患目睛黄。午饭难克化。则小溲黄。以黄耆建中汤除桂。加白术、陈皮、茯苓、半夏、神曲、麦芽、姜少许而退。", "3914": "缪仲淳曰。太学顾仲恭。遭鼓盆之戚。复患病在床。一医诊视。惊讶而出。谓其旦晚就木。因延予诊之。左手三部俱平和。右手尺寸亦无恙。独关部杳然不见。谛视其形色。虽尫羸。而神气安静。予询之。曾大怒乎。曰然。予曰。此怒则气并于肝。而脾土受邪之证也。经云。大怒则形气绝。而况一部之脉乎。甚不足怪。第脾家有积滞。目中微带黄色。恐成黄疸。两三日后。果遍体发黄。服茵陈利水平肝顺气药。数剂而痊。", "3915": "震按金匮要略云。病疽当以十八日为期。治之十日以上瘥。反剧者为难治。就余生平所验。分毫不爽。有先因他病而后发黄者。有先发黄而后现他病者。必于半月一月之内退尽其黄。则他病亦可治。设或他病先瘥而黄不能退。至一年半载仍黄者。必复现他病以致死。大抵酒伤。及有郁结。与胃脘痛。皆发黄之根基。而泄泻肿胀不食。乃发黄之末路。若时行病发黄亦多死。谚所谓瘟黄也。惟元气实者。审其为瘀血。为湿热。逐之清之。得黄退热亦退。乃可无虞。古人医案。俱未有说及久黄者。可为余言之一证。即如此条。关脉不见。亦云数剂而痊。要知因于大怒。偶然不见耳。若并未动怒。关脉连日不见。目中微带黄色。即为脾绝之征。死无疑矣。", "3916": "倪仲贤治吴陵盛架阁内子。左右肩背上下患痒。至两臂头面皆然。屡以艾灼痒处。暂止复作。如是数年。老人切其脉曰。左关浮盛。右口沉实。此酒食滋味所致也。投以清热化食行滞之剂。其痒遂止。", "3917": "江汝洁治一妇人。患上身至头面俱痒。刺痛起块。众医皆谓大风等证。江诊得左手三部俱细。右手三部皆微实。大都六脉俱数。经曰。微者为虚。弱者为虚。细者气血俱虚。盖心主血。肝藏血。乃血虚无疑。肾藏精属水。其部见微。乃为水不足。水既不足。相火妄行无制。以致此疾。经曰。诸痛疮痒。皆属心火。右手寸脉实。实者阳也。脉经曰。诸阳为热。乃热在肺分。火克金故也。且肺主皮毛。皮毛之疾。肺气主之。胸膈及皮毛之疾。为至高之疾也。右关微实。乃火在土分。土得火则燥。肌肉之间。脾气主之。肌肉及皮毛痛痒。皆火热在上明矣。右尺微实。火居火位。两火合明。阳多阴少。治宜补水以制火。养金以伐木。若作风治。未免以火济火。以燥益燥也。乃以生地、白芍各一钱。参、耆各六分、连翘、丹皮各六分。麦冬八分。柏皮、防风、甘草各四分。五味子九粒。黄连四分。水煎温服。渣内加苦参一两。再煎洗。十数剂而安。", "3918": "东垣治一妇麻木。六脉中俱得弦洪缓相合。按之无力。弦在其上。是风热下陷入阴中。阳道不行。其证闭目则浑身麻木。昼减夜甚。觉而目开。则麻木渐退。久乃止。惧而不睡。身体重。时有痰嗽。觉胸中常有痰而不利。时烦躁。气短促而喘。肌肤充盛。饮食二便如常。惟畏麻木不敢合眼为最苦。李曰。麻木为风。皆以为然。然如久坐而起。亦有麻木。喻如绳缚之人。释之则麻作。良久自已。此非风邪。乃气不行也。经云。阳病瞋目而动轻。阴病闭目而静重。灵枢云。开目则阳道行。阳气遍布周身。闭目则阳道闭而不行。如昼夜之分。以此知其阳衰而阴旺也。时痰嗽者。秋凉在外而湿在上也。身重脉缓者。湿气伏匿于脾也。时烦躁者。经脉中阴火乘其阳分也。法当升阳助气。益血。微泻阴火。去湿。通行经脉。调其阴阳则已。非脏腑之本有邪也。黄耆五分。人参三分。甘草炙四分。生一分。陈皮归身各二分。佛耳草四分。白芍三分。草豆蔻、苍术各一分半。白术二分。黄柏酒洗。苓、泽、升麻各一分。水煎服。八帖而愈。名曰补气升阳和中汤。", "3919": "一人年七旬。病体热麻。股膝无力。饮食有汗。妄喜笑。善饥。痰涎不利。舌强难言。声嗄不鸣。李诊脉。左手洪大而有力。是邪热客于经络之中也。二臂外有数瘢。问其故。对以燃香所致。李曰。君病皆由此也。人身经脉。手之三阳。从手表上行于头。加以火邪。阳并于阳。势甚炽焉。故邪热妄行。流散于周身而为热麻。热伤元气。则沉重无力。热泄卫气则多汗。心火盛则妄喜笑。脾胃热则消谷善饥。肺金衰则声不鸣。仲景所谓因火为邪。焦骨伤筋。血难复也。内经云。热淫所胜。治以苦寒。佐以苦甘。以甘泻之。以酸收之。用黄柏、知母之苦寒为君。以泻火邪。壮筋骨。又肾欲坚。急食苦以坚之。黄耆、生甘草之甘寒。泻热补表。五味子酸。止汗补肺气之不足以为臣。炙草、当归之甘辛。和血润燥。升、柴之苦平。行少阳阳明二经自地升天。以苦发之者也。以为佐。命其方曰清阳补气汤。又缪刺四肢。以泻诸阳之本。使十二经络相接而泄火邪。不旬日而愈。", "3920": "李士材治文学陆文湖。两足麻木。自服活血之剂。不效。改服攻痰之剂。又不效。经半载后。两手亦麻。左胁下有尺许不知痛痒。李曰。此经所谓著痹也。六脉大而无力。气血皆损。用神效黄耆汤。加茯苓、白术、当归、地黄。十剂后。小有效。更用十全大补五十余剂。始安。", "3921": "少宰蒋恬庵手足麻痹。目中睹一成两。服补血药不应。改服脾药。精神困倦。李诊得寸口脉大。两尺独涩。此心肾不交。水泛为痰之故也。乃取地黄丸料作煎剂。倍用泽泻、茯苓。入青盐少许。凡六剂。而岐视遂收。乃兼进参、耆安神之剂。一月而康复如常。", "3922": "震按上条气血兼补。原系古人成法。此条用地黄汤。因两尺脉涩。故先补肾。继以参、耆。仍是治麻成法。后案张公以参汤下紫雪。则别有洞天矣。由其病根在痰火也。开眼则麻。确是东垣对面文章。讲得最好。", "3923": "张路玉治洋客巴慈明妇。产后。眩晕心悸。神魂离散。若失脏腑之状。开眼则遍体麻木。如在云雾中。必紧闭其目。似觉稍可。昼日烦躁。夜则安静。专事女科者。用四物等血药。则呕逆不食。更一医用姜、附等热药。则躁扰不宁。其脉虚大而数。按之则散。举之应指。此心火浮散之象。因艰产受惊。痰饮乘虚袭入心包络中。留伏膈上。有入无出。所以绵延不已。盖目开则诸窍皆开。痰火堵塞心窍。所以神识无主。目闭则诸窍皆闭。痰火潜伏不行。故得稍安。与东垣所言合眼则阳气不行之麻木迥殊。况昼甚夜轻。明是上焦阳位之病。与理痰清火之剂。诸证渐宁。然或因惊恐。或因饮食。不时举发。此伏匿膈上之痰。无从搜涤也。乘发时用独参汤下紫雪。开通膈膜。仍与前药调补。半载而康。", "3924": "震按麻多在于手足者。以四末道远气馁。则卫行迟而难到也。故麻不兼木。必属气虚。否则风痰。凡脉浮而软。或大而弱者。气虚也。脉浮而滑。按之不衰者。风痰也。若麻木兼作。则有寒湿积痰死血之殊。其脉有沉迟滑实与沉涩而芤之分矣。宜详辨之。", "3925": "东垣治一人。冬时忽有风气暴至。六脉弦甚。按之洪大有力。其证手挛急。大便秘涩。面赤热。此风寒始至于身也。四肢者。脾也。以风寒之邪伤之。则搐如挛痹。乃风淫未疾而寒在外也。内经曰。寒则筋挛。正谓此也。素饮酒。内有实热乘于肠胃之间。故大便秘涩而面赤热。内则手足阳明受邪。外则足太阴脾经受风寒之邪。用桂枝二钱。甘草一钱。以却其寒邪而缓其急缩。黄柏二钱苦寒。滑以泻实润燥。急救肾水。升麻、葛根各一钱。以升阳气行手阳明之经。不令遏绝。桂枝辛热。入手阳明之经为引用润燥。复以甘草专补脾气。使不受风寒之邪。而退贼邪。专益肺经也。佐以人参补气。当归和血润燥。作一帖。水煎服。令暖房中摩搓其手。遂安。", "3926": "一人贫劳。秋深浑身发热。手足皆疼如煅。昼轻夜重。服风药愈痛。气药不效。脉涩而数。右甚于左。饮食如常。形瘦如削。盖大痛而瘦。非病致也。用苍术、酒黄柏各一钱五分。生附一片。生甘草三分。麻黄五分。研桃仁九个。煎入姜汁令辣。热服四帖。去附。加牛膝一钱。八帖后气喘促不得眠。痛略减。意其血虚。因多服麻黄。阳虚被发动而上奔。当补血镇坠。以酸收之。遂以四物汤减川芎。倍芍药。加人参二钱。五味子十二粒。与二帖定。三日后。数脉减大半。涩如旧。仍痛。以四物加牛膝、参、术、桃仁、陈皮、甘草、槟榔。生姜三片。五十帖而安。后因负重复痛。再与前药加黄氏三分。又二十帖愈。", "3927": "震按身发热。疼如煅。脉涩而数。右甚于左。应属血虚有热。所谓热痹证也。宜用生地、龟板、天冬、黄柏、丹皮、黑栀、秦艽、防己、牛膝、红花、银花、木通等药可愈。或仲景栀子柏皮汤大剂与之亦佳。若二妙之苍术。已不相宜。附子一片何用。麻黄五分太过。至因多服麻黄。虚阳上升而喘。议与酸收是矣。遽用人参二钱。窃恐痹痛转增。然云喘定数脉大减。异哉。或者脉数无力耶。则前之麻黄已误。后之桃仁、槟榔。义又何居。予素服膺丹溪。此则不敢阿其所好也。再阅下案。讲究病因。传变道理。真不可及矣。", "3928": "一人患背胛缝一线痛。起上胯骨至胸前侧胁而止。昼夜不住。脉弦而数。重取左豁大于右。意其背胛。小肠经。胸胁。胆经也。必思虑伤心。心脏未病。而小肠府先病。故痛从背胛起。及虑不能决。乃归之胆。故痛至胸胁。及小肠火乘胆木。子来乘母。是为实邪。询之果因谋事不遂而病。用人参四分。木通二分。煎汤使吞龙胆丸。数服而愈。", "3929": "一壮年厚味多怒。秋间于髀枢左右发痛一点。延及膝骭。痛处恶寒。昼静夜剧。口或渴。膈或痞。医用补血及风药。至次年春痛甚。食减形瘦。膝肿如碗。脉弦大颇实。寸涩甚。大率皆数。小便数而短。作饮食痰积在太阴阳明治之。以酒炒黄柏一两。生甘草梢、犀角屑、盐炒苍术各三钱。川芎二钱。陈皮、牛膝、木通、芍药各五钱。遇暄热。加黄芩二钱为末。每三钱。与姜汁同研细。煎令带热。食前服之。日夜四次。半月后。脉减病轻。去犀角。加牛膝、龟板、归身尾各五钱。如前服。又半月。肿减食增。不恶寒。惟脚痿软。去苍术、黄芩。夏。加炒柏一两五钱。余依本方。内加牛膝。因中年。加生地黄五钱。冬。加桂枝、茱萸。病遂愈。仍绝酒肉湿面胡椒。", "3930": "一人项强。动则微痛。脉弦而数实。右为甚。作痰热客太阳经治之。以二陈汤加酒洗黄芩、羌活、红花而愈。", "3931": "一村夫背伛偻。足挛。成废疾。脉沉弦而涩。以煨肾散与之。上吐下泻。过一月。又行一次。凡三四帖而愈。", "3932": "一妇人历节作痛。发热作渴。饮食少思。月经过期。诸药不应。脉洪大。按之微细。用附子八物四剂而痛止。用加味逍遥而元气复。六味丸而月经调。", "3933": "一妇体胖。素内热。月经失调。患痛风。下身微肿。痛甚。小便频数。身重脉缓。证属风湿。而血虚有热。先用羌活胜湿汤四剂。肿渐愈。用清燥汤数剂。小便渐清。用加味逍遥十余剂。内热渐愈。为饮食停滞。发热仍痛。面目浮肿。用六君子加柴胡、升麻而愈。又因怒气。小腹痞闷。寒热呕吐。此木侮脾土。用前药加山栀、木香而安。惟小腹下坠。似欲去后。此脾气下陷。用补中益气而愈。后因劳役怒气。作呕吐痰。遍身肿痛。月经忽来。寒热。用六君子加柴胡、山栀以扶元气。清肝火。肿痛呕吐悉退。用补中益气以升阳气。健营气。月经寒热渐瘥。", "3934": "汪石山治一妇。年逾五十。左脚膝挛痛。不能履地。夜甚于昼。小腹亦或作痛。诊其脉浮细缓弱。按之无力。尺脉尤甚。病属血衰。遂以四物汤加牛膝、红花、黄柏、乌药。连进十余帖而安。", "3935": "震按石山亦长于补。如此案之脉。人尽知其宜补矣。投以此方。恐病深药浅。岂能十余剂而安乎。", "3936": "韩飞霞治一都司。因哭弟成疾。饮食全绝。筋骨百节皮肤无处不痛。而腰为甚。一云肾虚宜补。或云风寒宜散。韩曰。此亦危证。其脉涩。正东垣所谓非十二经中正疾。乃经络奇邪也。必多忧愁转抑而成。若痰上。殆矣。补则气滞。散则气耗。乃主以清燥汤。连进三瓯。遂因睡至五鼓。无痰。觉少解。脉之。减十之三。遂专用清燥汤加减与之。十剂而愈。", "3937": "吴茭山治一男子。瘦弱。因卧卑湿之地。遂头目眩晕。畏见日光。寒热时作。四肢历节疼痛。或作风治。或作虚治。将及半年。俱不效。吴诊脉曰。寸口脉沉而滑。两尺弦。此溢饮湿痰也。当汗吐之。虽虚羸。不当用补药。乃以控涎丹一服。却用曝干棉子一斗燃之。以被围之。勿令气泄。使患人坐。熏良久。倏然吐出黑痰升许。大汗如雨。痛止身轻。病遂愈。", "3938": "李士材治盐贾叶作舟。遍体疼痛。尻髀皆肿。足膝挛急。曰。此寒伤荣血。筋脉为之引急。内经所谓痛痹也。用乌药顺气散。七剂而减。更加白术、桂枝。一月而愈。", "3939": "孙东宿治行人孙质庵患痛风。手足节骱。肿痛更甚。痛处热。饮食少。诊之脉皆弦细而数。面青肌瘦。大小腿肉皆削。曰。此病得之禀气弱。下虚多内以伤其阴也。在燕地又多寒。经云。气主煦之。血主濡之。今阴血虚。则筋失养。故营不荣于中。气为寒束。百骸拘挛。故卫不卫于外。荣卫不行。故肢节肿痛而热。病名周痹是也。治当养血舒筋。流湿润燥。俟痛止后。继以大补阴血之剂。实其下元可也。乃以五加皮、苍术、黄柏、苍耳子、当归、红花、苡仁、羌活、防风、秦艽、紫荆皮。二十剂而筋渐舒。肿渐消。痛减大半。更以生地、龟板、牛膝、当归、苍术、黄柏、晚蚕砂、苍耳子、秦艽、苡仁、海桐皮。三十剂而肿痛全减。行人大喜。孙曰。公下元虚惫。非岁月不能充实。须痛戒酒色。则培补乃效。丸方以仙茅为君。人参、鹿角胶、虎胫骨、枸杞、牛膝为臣。熟地、茯苓、黄柏、苍耳子、晚蚕砂为佐。桂心、秦艽、泽泻为使。蜜丸。服百日。腿肉长完。精神复旧。", "3940": "文学闵唇楼令室。躯肥性躁。患痛风。痛处略肿。呻吟喊叫。手足不能举动。医用归、芍、地黄、人参、牛膝之类。其痛愈加。已逾七月。东宿曰。此乃湿痰凝滞经络作痛。须以燥湿流动之剂疏决一番。但初服不效。须十帖见功耳。因用二陈加乌药叶、苍术、僵蚕、海桐皮、南星。至六七帖。痛如故。乃以芫花醋炒过三分。海金砂一分。为末。白汤送下。至晚。泻一次。下稠痰半盆。足痛减大半。稍能动止。更后。腹中大痛而厥。冷汗淋漓。面青息断。举家以为死矣。执而诊之。手冷如冰。但六脉俱在。惟沉伏耳。知其为痛极使然。用生姜汤灌之而苏。语侍女曰。适来腹中痛甚。耳后火光溅出。肛门如焚。大响一声。不知泻下何物。群看之。乃血鳅一条。长六寸。阔半寸余。鳞目俱在。盆中尚能游动。众皆悚骇。此证本由痰作。治者特为行痰。初不知其有虫如是。第药中有芫花。乃杀虫物。故偶中耳。次日手足皆能动。仍以二陈汤加苡仁、红花、五加皮。四帖脱然。", "3941": "祝茹穹治闽闱典试。半月前忽腿疼。两脚筋缩。脚跟缩黏至腿。寸步不能行。将一月。屡药无效。咸以此为痿痹证。祝曰。非也。察其脉。左寸忽洪忽涩。迟数无定栖。因此人好饮冷酒。酒新则性热燥。冷饮又犯寒湿。寒热相搏。遂有此病。乃以川乌二钱去皮脐。麻黄二钱。二股梢。一股根。苍术一钱。以甘草汁拌炒。白蒺藜一钱。去刺。酒蒸熟。焙干同为末。每服一钱二分。用老酒热冲服。盖被出汗。一服即能行动。三服愈。", "3942": "〔附〕叶天士先生治嘉善周姓。体厚色苍。患痛风。膝热而足冷。痛处皆肿。夜间痛甚。发之甚时。巅顶如芒刺。根根发孔觉火炎出。遍身躁热不安。小便赤涩。口不干渴。脉沉细带数。用生黄耆五钱。生于术三钱。熟附子七分。独活五分。北细辛三分。汉防己一钱五分。四剂而诸证皆痊。惟肿痛久不愈。阳痿不举。接用知、柏、虎膝、龟板、苁蓉、牛膝。不应。改用乌头、全蝎各一两。穿山甲、川柏各五钱。汉防己一两五钱。麝香三钱。马料豆生用二两。茵陈汤泛丸。每服一钱。开水下而全愈。", "3943": "张路玉治包山劳俊卿。年高挛废。山中诸医。用木瓜、独活、防己、豨莶、威灵仙之类。将半年余。乃致跬步不能动移。或令服八味丸。亦不应。诊其脉尺中微浮而细。时当九夏。自膝至足。皆寒冷如从水中出。知为肾虚。风雨所犯而成是疾。遂授安肾丸。终剂而能步履。连服二料。绝无痿弱之状矣。", "3944": "东垣治一人。壮年病脚膝痿弱。脐下尻臀皆冷。阴汗臊臭。精滑不固。或以鹿茸丸治。不效。李诊之脉沉数而有力。即以滋肾丸治之。以寒因热用。引入下焦。适其病所。泻命门相火之胜。再服而愈。", "3945": "震按阴汗臊臭。精滑不固。脉沉数有力。显系下焦湿热。东垣自云。泻其相火之胜。所谓肾热则骨痿也。", "3946": "丹溪治一人。形肥味厚。多忧怒。脉常沉涩。春病痰气。医以为虚寒。用燥热香窜之药。至夏两足弱。气上冲。食减。朱曰。此热郁而脾虚。痿厥之证作矣。形肥而脉沉。未是死证。但药邪太盛。当此火旺之令。实难求生。且与竹沥下白术膏。尽二斤。气降食进。至一月后。仍大汗而死。书此为误药之戒。", "3947": "震按气冲即是喘逆。又复食减。病已重矣。况兼两足弱乎。此下虚上盛之候。其谓形肥而脉沉。未是死证。即平脉篇肥人责浮之义。盖指脉非应死之脉。实死于药也。", "3948": "滑伯仁治一妇。始病疟。当夏月。医以脾寒胃弱。久服桂、附等药。后疟虽退。而积火燔炽。致消谷善饥。日数十饭犹不足。终日端坐如常人。第目昏不能视。足弱不能履。腰胯困软。肌肉虚肥。至初冬。伯仁诊之。脉洪大而虚濡。曰。此痿证也。长夏过服热药所致。盖夏令湿当权。刚剂太过。火湿俱甚。肺热叶焦。故两足痿易而不为用也。遂以东垣长夏湿热成痿之法治之。日食益减。目渐能视。至冬末。忽下榻行步如故。", "3949": "石山治一人。因久坐腰痛。渐次痛延右脚。及左脚。又延及左右手。不能行动。或作风治而用药酒。或作血虚而用四物。一咽即痛。盖覆稍热。及用针砭。痛甚。煎服熟地黄。或吞虎潜丸。又加右齿及面痛甚。季秋。汪诊之脉濡缓而弱。左脉比右较小。或涩。尺脉尤弱。曰。此痿证也。彼谓痿证不当痛。汪曰。诸痿皆起于肺热。君善饮。则肺热可知。经云。治痿独取阳明。阳明者胃也。胃主四肢。岂特脚耶。痿兼湿重者。则筋缓而痿软。兼热多者。则筋急而作痛。因检橘泉传示之。始信痿亦有痛。又经云。酒客不喜甘。熟地味甘。而虎潜丸益之以蜜。则甘多助湿而动胃火。故右齿面痛也。遂以人参二钱。黄耆一钱五分。白术、茯苓、生地黄、麦门冬各一钱。归身八分。黄柏、知母各七分。甘草四分。煎服五帖。病除。彼遂弃药。季冬复病。仍服前方而愈。", "3950": "一人形肥色黑。素畏热而好饮。年三十余。忽病自汗如雨。四肢俱痿。且恶寒。小便短赤。大便或溏或结。饮食亦减。医作风治。用独活寄生汤、小续命汤罔效。仲夏。汪视之脉沉细而数。约有七至。曰。此痿证也。丹溪云。断不可作风治。经云。痿有五。皆起于肺热。只此一句。便知其治之法矣。经又云。治痿独取阳明。盖阳明。胃与大肠也。胃属土。肺属金。大肠亦属阳金。金赖土生。土亏金失所养。而不能下生水。肾水涸火盛。肺愈被伤。况胃主四肢。肺主皮毛。今病四肢不举者。胃土亏也。自汗如雨者。肺金伤也。故治痿之法。独取阳明。而兼清肺经之热。正合东垣清燥汤。服百帖。果愈。", "3951": "震按脉沉细而数。约有七至。郁热深矣。何不直清其热。而仅用清燥汤清补兼施之药耶。盖痿本虚证。加之自汗如雨。饮食减少。则肺胃愈虚。故用此方补土以生金。益水以制火。治其本也。连、柏苦寒。苓、泻淡渗。治其标也。古人治病。审慎周到如此。亦知其必中。故能持久以收功。", "3952": "立斋治其师佥宪高如斋。自大同回。谓薛曰。余成风病矣。两腿逸则痿软而无力。劳则作痛如针刺。脉洪数而有力。立斋曰。此肝肾阴虚火盛而致。痿软无力。真病之形。作痛如锥。邪火之象也。用壮水益肾之剂而愈。高曰。向寓宦邸。皆以为风。恨无医药。若服风剂。岂不殆哉。", "3953": "震按此脉洪数而有力。故用壮水益肾之药。若脉数而无力。当用地黄汤合生脉散补血汤矣。下案二证。虚象显然。犹用风药。死复何疑。", "3954": "江应宿北游燕。路过山东。孙上舍长子文学病察。延江诊视。曰。无能为矣。经云。大肉已脱。九候虽调。犹死。而况于不调乎。时夏之半。六脉弦数。既泄且痢。脾传之肾。谓之贼邪。病已极矣。不出八月。水土俱败。至期而逝。敢辞。孙曰。内人请脉之。形容豫顺。语音清亮。不显言何证。诊毕。孙问何病。江曰。寸关洪数。尺微欲绝。足三阳脉逆而上行。上实下虚。此痿证也。病虽久可治。孙曰。何因而得此。江曰。经云。悲哀太过则胞络绝。胞络绝则阳气内动。发则心下崩。数溲血也。大经空虚。发为肌痹。传为脉痿。有所失亡。所求不得。则发肺鸣。鸣则肺热叶焦。发为痿躄。此之谓也。孙曰。果因哭子忧伤。两脚软弱无力。不能起者。七越岁矣。或以风治而投香燥。或认虚寒而与温补。殊无寸效。江曰。湿热成痿。正合东垣清燥汤例。但药力差缓。难图速效。以独味杜仲。空心酒水各半煎服。日进清燥汤。下潜行散。兼旬。出房门。无何。病瘵子死。哀伤复作。", "3955": "震按香为脾臭。何以蚀脾。意者香能开窍。香极则诸窍大开。脉缓筋弛。关键尽撤。故身软目瞪不食也。畀入土坎者。诸毒得土而化。且土为万物之母。四肢百骸。得土气则生气自复也。仍合治痿独取阳明之义。", "3956": "李士材治太学朱修之。八年痿废。累治不效。李诊之。六脉有力。饮食如常。此实热内蒸。心阳独亢。证名脉痿。用承气汤下六七行。左足便能伸缩。再用大承气。又下十余行。手中可以持物。更用黄连、黄芩各一斤。酒蒸大黄八两。蜜丸。日服四钱。以人参汤送。一月之内。去积滞不可胜数。四肢皆能展舒。李曰。今积滞尽矣。煎三才膏十斤与之。服尽而应酬如故。", "3957": "崇明倪君俦。四年不能起于床。日服之药。寒凉十六。补肾肝者十三。李诊其脉。大而无力。此营卫交虚。以十全大补加秦艽、熟附各一钱。朝服之。夕用八味丸加牛膝、杜仲、远志、萆薢、虎骨、龟板、黄柏。温酒送七钱。凡三月而机关利。", "3958": "又治兵尊高悬圃。患两足酸软。神气不足。向服安神壮骨之药。不效。改服滋肾合二妙。加牛膝、苡仁之属。又不效。纯用血药。脾胃不实。李诊之。脉皆冲和。按之亦不甚虚。惟脾部重取之则涩而无力。此土虚下陷。不能制水。则湿气坠于下焦。故膝胫为患耳。进补中益气。倍用升、柴。数日即愈。夫脾虚下陷之证。若用牛膝下行之剂。则愈陷而病愈甚矣。", "3959": "震按此三案。精妙绝伦。以药对脉。确切不移。首案连用承气。继用参汤送寒下药。皆是独取阳明治法。末案补中益气。与大黄补泻不同。总归乎取阳明也。临证指南首列轻清治肺二方。实宗肺热成痿之旨。第恐力薄难效。其用二妙、茵陈、萆薢、茯苓皮、蚕砂、海金砂、防己、胆草、寒水石等。直清湿热。较之清燥汤。反胜一筹。不涉虚者。允宜仿此。又有治下虚上实。而用犀角地黄汤去芍药。加元参、连翘、桑叶、钩藤。似乎专理上实。不顾下虚。然云头目如蒙。入夏阳升为甚。议清营热以熄内风。想其人脉必弦数。有热甚生风之象。未可兼顾下虚。或他日再诊而后滋填下焦。亦未可定。至于滋填下焦方。有用虎潜加减者。有用四斤金刚健步及地黄饮子加减者。有用熟地、苁蓉、巴戟、远志、鹿角霜、桑椹、苍术、小茴。以金毛脊酒蒸熟。水熬膏为丸者。有用苁、戟、杞、膝、青盐、线胶、茯苓、沙苑、鹿筋胶、羊肉胶、牛骨髓、猪脊髓者。却无参、术补阳明法。亦无承气泻阳明法。惟脾肾双补丸有人参。然其案重在晕麻瘕泄。尚未痿厥。非以治痿也。统观之。不外清湿热。益肝肾。岂二种病情偏多耶。或案有遗逸。未能详备耶。", "3960": "史记曰。临菑女子薄吾病甚。众医皆以为寒热笃。当死。臣意诊其病。曰。蛲瘕为病。腹大。上肤黄粗。循之戚戚然。臣意饮以芫花一撮。即出蛲可数升。病已。三十日如故。蛲得之寒湿。寒湿气郁笃不发。化为虫。臣意所以知薄吾病者。切其脉。循其尺。其尺索刺粗而毛美奉发。是虫气也。其色泽者。中藏无邪气及重病。", "3961": "震按此条辨证最佳。上肤黄粗者。腹大而腹上肤黄粗也。循之戚戚然者。如以手摸老松树皮之枯燥也。其尺索刺粗者。亦是枯燥之象。然仓公望毛发润美。面色又光泽。知为虫病也。若齐中尉潘满如病小腹痛。谓之遗积瘕。病由于酒且内。当溲血死一条。不讲证。但讲脉。辞义古奥难明。不敢因其讲脉而录之。", "3962": "〔附〕广异记载一患者。饮食如故。发则如癫。面色青黄。小腹胀满。状如妊孕。医诊其脉。与证皆异。而难明主疗。忽有一山叟曰。闻开皇六年。灞桥人患此病。盖因三月八日。水边食芹菜得之。有识者曰。此蛟龙瘕也。为龙游于芹菜之上。不幸食之而病也。遂以寒食饧每剂五合。服之数剂。吐出一物。形虽小而状似蛟龙。且有两头。获愈。", "3963": "名医录载汾州王氏。得病右胁有声如虾蟆。常欲手按之。不则有声。声相接。群医莫能辨。闻留阳山人赵峦善诊。求之。赵曰。此因惊气入于脏腑。不治而成疾。故常作声。王氏曰。因边水行次。有大虾蟆跃高数尺。蓦作一声。予不觉惊叫。便觉右胁牵痛。自后作声。常似虾蟆也。峦乃引王氏脉诀右关脉伏结。积病也。正当作积病治。用六神丹泄下青涎。类虾蟆之衣。遂瘥。", "3964": "修弓杜匠。其子妇年三十。有孕已岁半矣。每发痛。则召收生妪。以为将产也。一二日复故。凡数次。乃问戴人。戴人诊其脉涩而小。断之曰。块病也。非孕也。脉诀所谓涩脉如刀刮竹行。主丈夫伤精。女人败血。治法。下有病。当泻之。用舟车丸百余粒。后以调胃承气汤加当归、桃仁。三两日又以舟车丸、桃仁承气汤。泻青黄脓血。杂然而下。每更衣。以手向下推之揉之则出后。二三日。又用舟车丸、猪肾散、通经散等。连下数日。俟晴明。当未食时。以针泻三阴交。不再旬。病已失矣。", "3965": "震按子和此种治验。约十余条。其载脉象也。不曰沉细。则曰沉迟。此条则曰小而涩。而其用药也。积在上者。茶调散、三圣散、瓜蒂散为主。积在下者。舟车丸、神祐丸、承气汤、通经散为主。积在中者。兼而用之。凡吐下约数十次。盈五六缶。此种病人。岂非项籍樊哙之流亚耶。然如樊将军鸿门会切生彘肩啖之。又当怒时不见其成积也。故曰。壮盛人无积。虚人则有之。洁古养正积自除之论。最有见识。何麻知几辈侈张其说。以惑世诬民耶。", "3966": "又按子和系睢州人。河南水土厚实。或有此理。后人师其意而用倒仓法。亦以吐泻去积。王金坛极赞之。谓肠胃中得肉液充满。流行如洪水泛涨。浮槎陈朽。皆推逐荡漾而出。沉疴悉去矣。然徐东皋曰。此法惟宜用于元气实者。若虚损劳瘵鼓胀反胃。真病已成。六脉无力者。皆不可用。予见不善用者。往往杀人。观此说益惕然于三圣三花辈之难以轻试矣。", "3967": "又治吕宗信。年六十。素好酒。因行暑途得疾。足冷过膝。上脘有块如拳。牵引胁痛。不可眠。饮食减半。却不渴。已自服生料五积散三帖。朱诊之。六脉俱沉涩而小。按之不为弱。皆数。右甚。大便如常。小便赤色。遂用大承气汤。将大黄炒熟。加黄连、干葛、芎、芍、甘草作汤。以蒌仁、黄连、半夏、贝母为丸。至二十帖。块减半。遂止药。至半月。饮食复进。诸证悉除。", "3968": "丹溪曰。一妇年四十余。面白形瘦。性急。因有大不如意。乳房下帖肋骨间结一块。渐长掩心。微痛。膈闷口苦。饮食减四之三。两手脉微而短涩。予知其月经不来矣。为之甚惧。勿与治。思至半夜。其人尚能出外见医。梳妆言语如旧。料其尚有胃气。遂以人参、白术、当归、川芎。佐以气药。大剂与之。外用琥珀膏贴块上。防其块长。两三月间。约服二百帖。食及平时之半。脉渐充。仍与前药吞润下丸。又百余帖。月经行。不及两日而止。涩脉减三分之二。时天气热。意其经行时。必带紫色。仍与前药加醋炒三棱。吞润下丸。以抑青丸十五粒佐之。又经一月。块消其半。月经及期。尚欠平时半日。饮食甘美如常。但食肉不觉爽快。予令止药。且待来春木旺时区处。至次年六月。忽报块一夜大作。比旧反加指半。脉略弦。左略怯于右。至数日平和。自言饱食后则块微闷。食行却自平。予意其必有动心事激之。问之果然。仍于前药中加炒黄芩、黄连。少以木通、生姜佐之。去三棱。煎汤吞润下丸。外以琥珀膏贴之。半月。经行而块散。此是肺金为火所烁。木邪胜土。土不能运。清浊相干。旧块轮廓尚在。皆因气血未能尽复。故浊气稍留。旧块复起也。补其血气。使肺不受邪。木气平而土气正。浊气行而块自散矣。", "3969": "又一妇人。年三十六。家贫多劳。性褊急。自七月经断。八月小腹下有块偏左。如掌大。块起即痛。至半月后。腹渐肿胀。食减。夜发热。其脉十月间得虚微短涩。左尤甚。初与白术一斤。和白陈皮半斤。作二十帖煎服。外以三圣膏贴块上。经宿则块软。再宿则块小。近下一寸。旬日后。食进热减。又与前药一料。加木香三两。每帖研桃仁九个。尽此剂。病除。", "3970": "丹溪又曰。一婢色紫。稍肥。性沉多忧。年四十。经不行三月矣。小腹当中一块。渐如炊饼。脉皆涩。重按稍和。块按则痛甚。试扪之。高半寸。与千金硝石丸。至四五次。彼忽自言乳头黑。且有汁。恐是孕。予曰。涩脉无孕之理。又与三五帖。脉稍虚豁。予悟曰。药太峻矣。令止前药。用四物汤。倍白术。佐以陈皮、炙甘草。至三十帖。候脉充。再与硝石丸。至四五次。忽自言块消一晕。便令勿与。又半月。经行痛甚。下黑血近半升。内有如椒核者数十粒。而块消一半。又来索药。晓之曰。块已破。勿再攻。但守禁忌。次月经行。当自消尽。已而果然。大凡攻击之药。有病即病受之。邪轻则胃受伤矣。夫胃气清纯中和者也。惟与谷肉果菜相宜。药石皆偏胜之气。虽参、耆性亦偏。况攻击者乎。此妇胃气弱。血亦少。若待块尽而却药。胃气之存者几希矣。", "3971": "又一妇因经水过多。每用涩药。致气痛。胸腹有块十三枚。遇夜痛甚。脉涩而弱。丹溪曰。此因涩药。致败血不行。用蜀葵根煎汤。再煎参、术、青皮、陈皮、甘草梢、牛膝。入元明粉少许。研桃仁调。热服二帖。连下块二枚。以其病久血耗。不敢顿下。乃去葵根明粉服之。块渐消。", "3972": "张三锡曰。曾治一少年。体薄弱。且咳血。左边一块。不时上攻作痛。左金、芦荟俱不应。诊其脉三部虽强。而细涩不流利。因作阴虚治。四物加知、柏、元参、丹皮。不六剂顿愈。此阴虚似肝积也。由此推之。虽因部分名积。诊视之际。犹当详审。惟圆机者。乃不昧此。", "3973": "震按此二条。一系饮积。以证与因断之。一系阴虚似肝积。以脉断之。即圆机也。两家垂训。裨益尤多。", "3974": "喻嘉言治袁聚东。年二十岁。生痞块。日进化坚削痞之药。渐至毛瘁肉脱。面黧发卷。殆无生理。喻视之。少腹脐旁三块。坚硬如石。以手拊之。痛不可忍。其脉两尺洪盛。余俱微细。谓曰。此由见块医块。不究其源而误治也。初起时块必不坚。以峻猛之药攻至。真气内乱。转护邪气为害。如人厮打。纽结一团。迸紧不散。其实全是空气聚成。非如女子月经凝而不行。即成血块之比。观两尺脉洪盛。明是肾气传于膀胱。因服破气药多。膀胱之气不能传前后二便而出。乃结为石块耳。治法须内收肾气。外散膀胱之气。以解其厮结。三剂可愈也。先以理中汤加附子五分。块即减十之三。再用桂、附大剂。腹中气响甚喧。三块一时顿没。然有后虑者。肾气之收藏未固。膀胱之气化未旺。倘犯房室。块必再作。乃用补肾药加桂、附。多加河车为丸。取其以胞补胞而助膀胱之化源也。服之后。方不畏寒。腰围渐大。年余且得子。", "3975": "震按此人克伐太过。换以温补。未足为奇。惟两尺脉洪盛。非此诠解。谁不面涩。至于桂、附、河车。同补肾药为善后计。则与肾气传膀胱之论紧切不泛。非通套治痞成法可比。", "3976": "李士材治郡守于鉴如。每酒后腹痛。渐至坚硬。得食辄痛。李诊之曰。脉浮大而长。脾有大积矣。然两尺按之软。不可峻攻。令服四君子汤七日。投以阴阳攻积丸三钱。但微下。更以四钱服之。下积十余次。皆黑而韧者。察其形不倦。又进四钱。于是腹大痛。所下甚多。仍服四君子汤十日。又进丸药四钱。去积三次。又进二钱。下积至六七碗。脉大而虚。按至关部豁如矣。乃以补中益气调补一月。全愈。", "3977": "震按脉浮大而长。为脾有大积。较之丹溪诸案。或沉涩而小且数。或微而短涩。或虚微短涩。或脉涩而弱者。大不同矣。须于临证时。能以古人各种脉法。俱为我之正鹄。庶期中的。若两尺按之软。不可峻攻。固是正理。然亦要看得灵变。盖两尺软为虚。则喻案之两尺洪盛。宁不认为实而峻攻之耶。故又当以形色及病情参讨也。", "3978": "给谏侯启东腹中嘈痛。士材按其左胁。手不可近。凡饮食到口。喉间若有一物接之者然。李曰。脉大而数。腹痛呕涎。面色痿黄。此虚而有湿。湿热相兼。虫乃生焉。当煎人参汤送槟黄丸以下虫积。虫若不去。虽补何益乎。病者畏不敢用。后竟不起。", "3979": "一人左胁下有块。右关脉豁大。周用乌药一两。以附子五钱浓煎制之。将乌药日磨二三分。酒送下。俟积行动。乃以补中益气汤加附子服之。丸用六君子。", "3980": "震按慎斋书云。凡积不可用下药。徒损真气。病亦不去。当用消积药。使之溶化。则除根矣。积去须大补。诚格言也。即此二案。亦平淡之神奇。又尝考消积之方。如桃仁煎用大黄。虻虫、芒硝。黑神丸用生漆、熟漆。东垣五积丸俱用川乌、巴霜。局方圣散子、三棱煎丸俱用硇砂、干漆。此皆峻厉之药。用而中病。固有神效。若妄尝轻试。鲜不败事矣。千金硝石丸人参、硝黄并用。丹溪犹以为猛剂。治婢一案。每与补药迭进。此真善治病者也。丹溪治积聚案有数十条。轻重曲折。适至病所。惜不能多载。再阅叶氏医案积聚门。只用鸡肫皮、莱菔子、蛤粉、芥子、蜣螂、䗪虫、青、朴等。并无古方狠药。其理尤可想见。予曾亲见叶先生治一妇。产后著恼。左边小腹结一块。每发时。小腹胀痛。从下攻上。膈间乳上皆痛。饮食入胃即吐。遍医不效。先生用炒黑小茴香一钱。桂酒炒当归二钱。自制鹿角霜一钱五分。生楂肉三钱。川芎八分。菟丝子一钱五分。水送阿魏丸七分。八剂而愈。次用乌鸡煎丸原方半料。永不复发。又一人患疟疾补早。左胁成痞。连于胃腕。按之痛甚。用炒桃仁为君。佐以阿魏、穿山甲、鳖甲、麝香。丸服。全消。此二条较之临证指南所载者为更佳。故附于此。予又亲见杭州一富家妇患痞块。用黑神丸大效。每痛作呕胀不堪。服此即愈。数十服后。百苦皆除。然半年外。以他病暴殒。因思漆身为癞之言。脏腑岂堪常漆耶。清纯冲和之气。耗丧于此药而不觉也。再观丹溪治方提领。用参、术、归、芍等煎汤。下保和丸二十五。龙荟丸十五。治冯氏女。先用左金丸、青六丸。后用参橘桃芍丸。治卢子裕疟后食酒肉而成块在左胁。用参、术、柴、苓、枳壳煎汤。下阿魏五。保和二十。抑青十。与点十。攻块五。攻块者。青皮、三棱、桃仁、桂枝、海藻、醋调神曲为丸也。治下邳钱郎。用保和二十。温中二十。抑青十。以白术、木通、三棱汤下。此等方法。皆补药与磨积相半。而必兼清肝之药。大抵因怒成块者居多也。又如陈里长男。饱食牛肉豆腐。成块在右胁。脉弦而数。即明告以此人必性急。块上不可按。按则愈痛。痛则必吐酸黄苦水。而用荔核、山楂、枳实、山栀、茱萸、人参、姜汁以止痛。继用皂角煎汁制半夏。合黄连、石碱。用糖球膏为丸以消块。此仍是治肝为主。磨积为助。学者能逐案细绎之。自有悟处。", "3981": "东垣治一人。前阴臊臭。又因连日饮酒。腹中不和。求治。曰。夫前阴者。足厥阴肝之脉络循阴器出其挺末。凡臭者。心之所主。散入五方为五臭。入肝为臊。当于肝经泻行间。是治其本。后于心经泻少冲。乃治其标。如恶针。当用药除之。酒者气味俱阳。能生里之湿热。是风燥热合于下焦为邪。经云。下焦如渎。又云。在下者引而竭之。酒是湿热之物。亦宜决前阴以去之。治以龙胆泻肝汤。又治阴邪热痒。柴胡梢二钱。泽泻二钱。车前子二钱。木通五分。生地黄、当归梢、草龙胆各三分。作一服水煎。以美膳压之。", "3982": "震按巢氏病源。以肾间动气。为人之根本。故老年而能御女。七十岁至八十岁犹生子者。其动气之禀于生初者独厚也。厚则刚。阳自不痿。生子之时。已是大寿。至不能生子而死。谅必又有数年。岂非耄耋乎。亦有六十岁左右即阳痿者。必不能至大寿。须任其自然。绝意淫欲。尚可延龄。设以兴阳药内服外洗。求为御女之事。不数年而死矣。又如壮年无病而阳痿。其人多夭。少年虚损而阳痿。其死立至。皆由肾间动气早衰也。动气即命门真火。所以生长元气。煦燠元阴。故气曰阳气。精曰阳精。其盈亏俱得于先天。盈者虽斫丧而无伤。亏者虽葆养而不足。并非药石所能扩充。乃扁鹊新书载王超老淫故事而云保命之法。灼艾第一。丹药第二。附子第三。此说荒唐。断不可信。又考宗筋聚于前阴。前阴者足之三阴。及阳明少阳冲任督跷九脉之所会。而九脉之中。阳明为之长。内经云。阳明者。五脏六腑之海。主润宗筋。所以胃强善啖之人。其于欲事必强。反是则痿而不举。或举而不坚。是胃气能为肾气之助。古云。精生于谷。又云。男子精盛则思色。其道理可喻矣。新书之言。不过如宋人揠苗耳。况丹药之害。可胜言哉。", "3983": "震治一人脱肛肿痛出水。尺脉洪数。用樗根白皮、川柏、诃子肉、没石子、鳖头灰而愈。其人好酒形实。乃湿热下注。非气虚下陷也。", "3984": "陆上舍。冬患痔作痛。右寸浮大。左寸口洪数。立斋曰。冬见夏脉。当壮水之主以镇阳光。彼以为迂。别服芩、连之剂。薛谓其侄曰。令舅氏肾水不能生肝木。殁于春。验矣。今令叔肾水不能制心火。当殁于夏。至甲辰六月。薛复视之。痰涎上涌。日夜不寐。脉洪大而数。按之无力。左尺绝无。足膝肩膊逆冷。薛曰。事急矣。彼云。但求少延数日。以待嗣子一见。始用参、耆、归、术、炮姜之类。及六味丸料加肉桂。至本月而殁。五行之理信然。", "3985": "陈三农治制府王姓。感冒瘴气。寒热头疼。胸膈饱闷。眩晕恶心。脉数而洪。用藿香正气散。加厚朴、槟榔、羌、防、苏叶。一剂而寒热退。头不疼。减去羌、苏、防风。加草豆蔻、半夏、枳壳。恶心胀闷皆愈。", "3986": "又治梧州方姓。头疼身痛发热。恶心饱闷。脉弦而数。用羌、防、芎、苏、藿、半、槟榔、苍、朴、橘、草。二服而减。因饱胀未全退。加草果、草豆蔻。方愈。要知恶心饱胀。乃瘴气之异于感冒也。", "3987": "端州李别驾。镶蓝旗人。年四十余。能骑射。署雷州府时。善搏虎。不避风雨寒暑。涉溪陟岭。染瘴已深。其所感风寒暑湿。不一而足矣。又以谢谒上台。到省过劳。积邪所感。猝然皆发。医者略为解散。即用补剂。而邪气大作。寒热神昏谵语。脉空数无根。神气散乱。补泻兼施。毫无一效。三农诊之。脉如水上羹。刻刻欲脱。寒热间作。盖受病既深。精气两虚。邪气正炽。法在不治。勉拟五积散加附子、人参。去麻黄而易羌活。其家见立方有难色。置不用。后医有认阴疟阳虚。而进金匮肾气加参者。有谓虚证似疟。而以补中倍加参附者。三剂而神昏气喘。虚汗如雨。足冷而脱矣。不知此证初实受瘴气。屡感屡深。今则乘虚而发。古云。伤寒偏死下虚人。况瘴气而风寒暑湿备感者乎。", "3988": "两广总制石公子。年甫十龄。六月。感冒风暑。寒热头疼。已用葛根加羌、防解表矣。后复寒热不减。气喘腹胀。再用小柴胡汤加消导。不应。神昏喘急。寒热间作。时或泄泻似痢。腹痛。不知名为何病也。陈往视。已二十余日矣。脉数无力。神气昏乱。举家惊惶。按其腹。时痛时胀。观其神。时静时躁。手足或冷或热。虚汗不已。此外邪初感者。为药而解。久积者。未曾清理。加之以饮食失调。元气欲脱。故虚象显露。细思外邪内陷变病之证。元气已亏。救本为急。且扶住元神。再筹治病之策。因用理中汤加桂、附。腹痛稍缓。泄泻顿减。手足亦暖。然发热不退。小便赤浊不利。因用金匮肾气丸作汤。二服小便方利。寒热愈加。此元气渐回。病证乍现。风寒暑湿食积。种种不清。若欲返本还元。正尔变端不一。仍朝用六君子汤加柴胡、干葛、神曲、干姜。夜用六味汤加参、桂。旬日后。寒冷拘挛。眼目翻白。咬牙呻吟。举家惊恐恸哭。以为无救矣。陈曰。此名寒战。正气将回。积邪欲出。从此一变。反有复生之机。自未至酉。始得大汗如雨。手足软怠。不语熟睡。人情虽少定。而错愕未安也。天明方能言语。然虚证日变。潮热汗多。则用补中合建中加附子。不能安寝则用归脾汤。元气弱则用十全大补汤。腹痛滑泻则用理中六君汤。如是调摄三阅月。方得返本还元而奏功也。", "3989": "正红旗孙公。病已月余。陈诊其脉空豁。恍惚不定。重按无根。神昏谵语。寒热大作。加之咳嗽痰喘。转侧不能。昼夜伏几。呻吟而已。且胸膈饱闷。足冷恶寒。询知夏秋积劳。寒暑皆受。一月以前。初感头疼身痛。憎寒壮热咳嗽。医者用桔梗、杏仁、干葛、羌、苏。汗而不解。复用桑皮、前胡、苏子、橘、半、知、贝、黄芩。亦不应。因寒热更甚。有用小柴胡加栀子、元参、薄荷。清痰退热。而咳嗽更甚。不知此证。夏秋暑湿风寒兼感而发。尚未得汗。何能解散。遂用五积散。二剂而得汗如淋。咳嗽亦减。可以伏枕。惟寒热未退。积久病深。元气已亏。气上喘。小便如油短数。其火从下而上。上盛下虚。肾气虚惫。因用金匮肾气加沉香。二服而气平便顺。然潮热如故。时有呓语。人亦忘识。乃知精神耗散。极宜大补。午后用参附六君汤。朝用肾气丸。次序并进。经月。方思饮食。呓语亦退。虚汗亦止。神气始安。方识平日交往之人。凡用人参、附子。共斤许。精神稍复。然面目黎赤。肌血不华。再用还少丹加桂、附、河车、鹿角胶。月余。又用十全大补汤二十余剂。元气日长而饮食如常矣。", "3990": "一时开山同病而返省者数人。有陈某似疟非疟。以疟治。势渐笃。三农诊之。脉已细紧而数。饮食不进。乃曰。若欲治之。何不于一月以前。虽病笃而元气尚在。今病已深。精神殆尽矣。何药可施乎。旋毙。", "3991": "又同事一人。似痢非痢。寒热间作。医以香、连、硝、黄。消攻清理。日剧。尫羸。因易一医。曰。可以进补。用白术五分。茯苓四分。陈皮二分。病虽不甚。热亦不减。三农诊其脉。恍然不定。重按已绝。虽饮食尚可。所谓行尸耳。邪火浮载。真精告竭矣。辞之。阅二日而死。", "3992": "春夏之交。乍寒乍热。其气忽然蓊郁。忽然发泄。更衣不时。感冒不一。本地人患者不知。医者无书可考。客寓者每曰水土不服。委之于数而已。其证似风寒头痛寒热。而又恶心胀闷。似痢非痢。似疟非疟者是也。宜九味羌活汤加减。平胃散、藿香正气散、二陈汤。此证粤中无时无之。无人觉之。虚弱之体。感而即发。敦厚之人。感不骤发。积久而成。浑浑漠漠。脉证茫然。难治难愈。", "3993": "大凡治病之道。寒证用热药。热证用寒剂。人所共晓。此如举业题之正面易做。而侧取为难。更有外有余而内不足。有内真实而外假虚。阳证似阴。阴证似阳。其中精微深奥之处。差之毫厘。缪以千里。瘴疠虽从山川地气。随时令而得。亦必乘人本虚。方乃受病。其阳虚火衰者。一时受瘴。因轻而不觉。瘴证变为本病。必虚寒而腹胀满。大便泄泻。恶寒手足冷者是也。阴虚火旺者。瘴轻而不觉。瘴后现为本病。必头晕口渴发热。腹胀恶心便赤者是也。再审五脏六腑。各有素常偏患衰弱壮实之分。皆当以此类推。并须消息其夏秋劳逸行役。阴晴暑湿起居所履。庶几有得。至如瘴脉。初感洪数。虚者大而芤。实者弦而滑。久则变迁。亦总以无力为虚。有力为实也。", "3994": "东垣治一妇。年三十余。每洗浴后。必用冷水淋身。又尝大惊。遂患经来时。必先小腹大痛。口吐涎水。经行后。又吐水三日。其痛又倍。至六七日。经水止时方住。百药不效。诊其脉。寸滑大而弦。关尺皆弦大急。尺小于关。关小于寸。所谓前大后小也。遂用香附三两。半夏二两。茯苓、黄芩各一两五钱。枳实、延胡、丹皮、人参、当归、白术、桃仁各一两。黄连七钱。川楝、远志、甘草各五钱。桂三钱。吴茱萸一钱五分。分十五帖。入姜汁两蚬壳。热服之。后用热汤洗浴。得微汗乃已。忌当风坐卧。手足见水。并忌吃生冷。服三十帖全愈。半年后。因惊忧。其病复举。腰腹时痛。小便淋痛。心惕惕惊悸。意其表已解。病独在里。先为灸少冲、劳宫、昆仑、三阴交。止悸定痛。次用桃仁承气汤大下之。下后用醋香附三两。醋蓬术、当归身各一两五钱。醋三棱、延胡索、醋大黄、醋青皮、青木香、茴香、滑石、木通、桃仁各一两。乌药、甘草、砂仁、槟榔、苦楝各五钱。木香、吴茱萸各二钱。分作二十帖。入新取牛膝湿者二钱。生姜五片。用荷叶汤煎服愈。", "3995": "震按初来血黑。后来血淡。是本虚而标热也。来既多。又倦怠食少。虚象显然。何以不用补药。试观第四条女年十五之案。则此案治法似未尽善。或者此妇之脉弦大而数耶。下二案如黄浆。如黑豆汁。制方极当。", "3996": "一女年十五。脉弦而大。不数。形肥。初夏时。倦怠。月经来时多。此禀受弱。气不足摄血也。以白术一钱五分。生耆、陈皮各一钱。人参五钱。炒柏三分。", "3997": "一妇年二十余。形肥。痞塞不食。每日卧至未。饮薄粥一盏。粥后必吐水半碗。仍复卧。经不通三月矣。前番通时黑色。脉辰时寸关滑有力。午后关滑。寸则否。询之因乘怒饮食而然。遂以白术一两五钱。厚朴、黄连、枳实各一两。半夏、茯苓、陈皮、山楂、人参、滑石各八钱。砂仁、香附、桃仁各五钱。红花二钱。分作十帖。每日服一帖。各入姜汁二蚬壳。间三日。以神佑丸、神秘沉香丸微下之。至十二日。吐止食渐进。四十日平复如故。", "3998": "震按饮薄粥一碗。必吐水半碗。卧不能起。将认作大虚证矣。其辨在于痞塞。及经停之前虽通而黑色也。此内火食积。郁成湿热。上则饮停。下则瘀阻。实证似虚耳。辰时寸关脉滑有力者。辰为气血注胃之时。胃满甚而连及上焦。午后惟关滑。独显胃实之象矣。方主消痰消食破气活血。加黄连、滑石以清湿热。仍兼人参以鼓舞胃气。使诸药得行其疏通之力。再佐姜汁之辛以开道路。又治呕吐。此真纪律之师。有胜无败者也。然犹有病深药浅之虑。隔三日。以二丸微下。则直捣贼巢。病根可拔矣。", "3999": "吕沧洲治一女。在室病不月。诸医疗皆不得其状。视之腹大如娠。求其色脉即怪。语之曰。汝病非有异梦。则鬼灵所凭耳。女不答。趋入卧内。密语其侍妪曰。我去夏追凉庙庑下。薄暮过木神心动。是夕梦一男子。如暮间所见者。即我寝亲狎。由是感病。我惭赧不敢以告人。医言是也。妪以告吕。吕曰。女面色乍赤乍白者。愧也。脉乍大乍小者。祟也。病因与色脉符。虽剧无苦。乃以桃仁煎下血类豚肝者六七枚。俱有窍如鱼目。病已。", "4000": "震按此即鬼胎。亦易辨识。惟云。病因与色脉符。虽剧无苦。一秘诀也。桃仁煎颇狠。然非此药。不能去此病。", "4001": "石山治一妇。瘦小。年二十余。经水紫色。或前或后。临行腹痛。恶寒喜热。或时感寒。腹亦作痛。脉皆细濡近滑。两尺重按略洪而滑。汪曰。血热也。或谓恶寒如此。何谓为热。曰。热极似寒也。遂用酒煮黄连四两。香附、归身尾各二两。五灵脂一两。为末粥丸。空腹吞之而愈。", "4002": "震按脉细濡近滑。两尺亦于重按略洪而滑。又不兼数。殊难认为大热。乃重用黄连而愈。汪公指下真有得心应手之乐。", "4003": "一妇年二十一岁。六月。经行腹痛如刮。难忍求死。脉得细软而快。尺则沉弱而近快。汪曰。细软属湿。数则为热。尺沉属郁滞也。以酒煮黄连八两。炒香附六两。五灵脂半炒半生三两。归身尾二两。为末粥丸。空心汤下三四钱。服至五六料。越九年。得一子。又越四年。经行两月不断。腹中微痛。又服前丸而愈。续后经行六七日。经止则流清水。腹中微痛。又服前丸而痛亦止。又经住只有七八日。若至行时。或大行五六日。续则适来适断。或微红。或淡红。红后常流清水。小腹大痛。渐连遍身。胸背腰腿骨里皆痛。自巳至酉乃止。痛则遍身冷热。汗大出。汗止痛减。尚能饮食。自始痛至今。历十五年。前药屡服屡效。今罔效者何也。汪复诊之。脉皆洪滑无力。幸其尚有精神。汪曰。此非旧日比矣。旧乃郁热。今则虚寒。东垣曰。始为热中。终为寒中是也。经曰。脉至而从。按之不鼓。乃阴盛格阳。当作寒治。且始病时形敛小。今则形肥大矣。医书曰。瘦人血热。肥人气虚。岂可同一治耶。所可虑者。汗大泄而脉不为汗衰。血大崩而脉不为血减耳。其痛日重夜轻。知由阳虚不能健运。故亦凝滞而作痛。以证参脉。宜用助阳。若得脉减痛轻。方为佳兆。遂投参、耆、归、术大剂加桂、附。一帖。来早再诊。脉皆稍宁。服至二三十帖。时当二月。至五月病愈。盖病有始终寒热之异。药有前后用舍不同。形有肥瘦壮少不等。岂可以一方而通治哉。", "4004": "震按细软而数。为湿热。洪滑无力。为虚寒。的系辨脉要旨。汪公自跋数语。尤属治病要诀。然前之黄连。终嫌太过。久服不换。亦恐非宜。", "4005": "一妇经行。必泻三日。然后行。诊其脉皆濡弱。曰。此脾虚也。脾属血。属湿。经水将动。脾血已先流注血海。然后下流为经。脾血既亏。则虚而不能运行其湿。令作参苓白术散。每服二钱。一日米饮调下二三次。月余。经行不泻矣。", "4006": "一妇年逾四十。形长色脆。病经不调。右脉浮软而大。左脉虚软而小。近快。常时经前作泄。今年四月。感风咳嗽。用汤洗浴汗多。因泄一月。六月。复因洗浴。发疟六七次。疟虽止而神思不爽。至八月尽。而经水过多。白带时下。泻泄。遂觉右脚疼痛。旧曾闪挫脚跟。今则假此延痛。臀腿腰胁尻骨胫项左边筋皆掣痛。或咳嗽一声。则腰眼痛如刀扎。日轻夜重。叫号不已。幸痛稍止。饮食如常。因思月水过多。白带时下。日轻夜重。泄泻无时。亦属下多亡阴。宜作血虚治。然服四物止痛之剂益甚。九月。汪复诊视。始悟此病乃合仲景所谓阳生则阴长之法矣。夫经水多。白带下。常泄泻。皆由阳虚陷下而然。命曰阳脱是也。日轻夜重。盖日阳旺而得健运之职。故血亦无凝滞之患而日轻也。夜则阴旺而阳不得其任。失其健运之常。血亦随滞。故夜重也。遂以参、术助阳之药。煎服六七帖。痛减。此亦病证之变。治法殊常。故记之。", "4007": "震按前案之理易明。此案之脉亦易认为虚。惟近快而合以足之延痛。颇似湿热耳。然久泻复疟。经水过多。白带时下。显系参、术对证。何云治法殊常耶。", "4008": "一妇人年逾四十。形色颇实。常患产难倒生。经水不调。或时遍身骨节疼痛。食少倦怠。自汗。汪诊之。两手脉皆不应。而右关轻按。隐隐然微觉动也。疑脉出部。以指寻按经渠列缺穴分。亦不应。甚怪之。乃叩其夫。曰。有孕时。医诊亦言无脉。后服八物汤。幸而易产。得一子。汪曰。此由禀赋本来脉不应也。无足怪。可见天下事变无穷。果难一一以常理测也。如脉经所谓。但道其常而已。两手无脉。不伤其生。又不妨于胎孕。岂脉经所能尽耶。", "4009": "震按人有一手无脉者颇多。若两手无脉者则少。此乃母胎中。或襁褓时。蹙锉其经隧。致脉不通。原非病也。石山又诊一妇左手无脉。而动于腕臂外廉阳谿偏历之分。是即今所谓反关脉耳。汪乃曰。左脉离其部位。其病难以脉知。诚然反关脉多洪大。且可推动。果不足以审病情。又按丹溪治一妇久疟。食少经闭。两手无脉。每日与三花神佑丸十余粒。津咽之。月余食进。脉出。又半月脉愈。又一月经行。此则因病而无脉。非向来无脉也。", "4010": "一妇产后。经行不止。或红或白或淡。病逾八月。面色黄白。性躁。头眩脚软。医用参耆补药。病益加。用止涩药不效。汪诊之。右脉濡弱无力。左脉略洪而快。曰。右脉弱者。非病也。左脉偏盛。遂觉右脉弱耳。宜主左脉。治以凉血之剂。遂以生地、白芍、白术各一钱。黄芩、阿胶、归身各八分。陈皮、香附、川芎、椿根皮、茯苓各六分。柴胡、甘草各五分。煎服二十余剂而愈。", "4011": "震按右脉濡弱无力。而汪公乃以左脉偏盛为主。其取舍异矣。且曰。右脉弱非病。则经水之或白或淡。及面色黄白头眩脚软。非右脉弱之为病。汪公盖因曾用参耆而病益加。则右脉不足凭。常以凉血之剂专主左脉为治耳。", "4012": "又治一妇。年逾三十无子。汪诊其脉近和。惟尺部洪滑。曰。子宫有热。血海不固也。其夫曰然。每行人道。经水即来。乃以丹溪大补丸加山茱萸、白龙骨止涩之药以治其内。再以乱发灰、白矾灰、黄连、五倍子为末。以治其隐处。果愈且孕。", "4013": "又一妾证同前。按其脉。两尺沉迟而涩。用补血散寒之剂不愈。偶检千金方。以蛇床子散绵裹纳其中。二次遂愈。", "4014": "震按以上三案。病同而治法各异。可见病以脉为断也。立斋首案不载脉。然敷服皆凉血止痛之剂不效。则舍补无他法矣。此又可以意会也。", "4015": "又一妇人。经候过期。发热倦怠。或用四物、黄连之类。反两月一度。且少而成块。又用峻药通之。两目如帛所蔽。薛曰。脾为诸阴之首。目为血脉之宗。此脾伤五脏皆为失所。不能归于目矣。遂用补中益气、济生归脾二汤。专主脾胃。年余寻愈。", "4016": "一妇人年四十。劳则足跟热痛。薛以阴血虚极。急用圣愈汤而痊。后遍身瘙痒。误服风药。发热抽搐。肝脉洪数。此乃肝家血虚火盛而生风。以天竺胆星为丸。用四物、麦冬、五味、芩、连、炙草、山栀、柴胡煎送而愈。", "4017": "一妇内热作渴。饮食少思。腹内近左。初如鸡卵。渐大四寸许。经水三月一至。肢体消瘦。齿颊似疮。脉洪数而虚。左关尤甚。此肝脾郁结之证。外贴阿魏膏。午前用补中益气汤。午后以加味归脾汤。两月许。肝火少退。脾土少健。仍与前汤送下六味地黄丸。午后又用逍遥散送归脾丸。又月余。日用芦荟丸。以大皂角、青黛、芦荟、朱砂、麝香各一钱。另以干虾蟆用皂角等分烧存性。为末一两。入前项药。同为末。蒸饼丸如麻子大。每日二服。空腹以逍遥散下。日晡以归脾汤下。喜其谨疾。调理年余而愈。", "4018": "震按今人称月事为天癸者。谬也。经云。女子二七而天癸至。任脉通。太冲脉盛。月事以时下。又云。男子二八而肾气盛。天癸至。精气溢泻。若天癸即月事。丈夫有之乎。顾名思义。谓是天一之真水。乃精血之源头也。盖男女皆有精。易云。男妇媾精。可据。然指天癸为精。亦不妥。天癸为精。不该又云。精气溢泻矣。后贤讲受孕之道。有阳精阴血。先至后冲等说。亦谬。夫男女交接。曾见女人有血出耶。交接出血是病。岂能裹精。及为精所裹哉。大约两情欢畅。百脉齐到。天癸与男女之精偕至。斯入任脉而成胎耳。男胎女胎则由夫妇之天癸。有强弱盈虚之不同也。任脉督脉。皆起于前后两阴交之会阴穴。督总诸阳。任总诸阴。任脉隶足少阴。冲脉隶足阳明。所谓冲为血海。任主胞胎也。经云。前阴总宗筋之所会会于气街。而阳明为之长。阳明水谷之精华。变化成血以灌输太冲。太冲脉盛。月事以时下矣。既孕则血聚以养胎。不能输入太冲。故月事不下。由此辨之。任脉通而天癸至。冲脉盛而月事下。明系两项矣。", "4019": "许学士治一尼。恶风倦怠。乍寒乍热。面赤心怔忡。或时自汗。是时疫气大行。医见其寒热。作伤寒治之。用大小柴胡汤杂进。数日病急。许诊视。告之曰。三部无寒邪脉。但厥阴弦长而上鱼际。宜服抑阴等药。乃以生地二两。赤芍一两。柴胡、秦艽、黄芩各五钱。为细末。蜜丸如梧桐子大。每服三十丸。乌梅汤吞下。日三服。良愈。", "4020": "薛立斋治一寡妇因怒。致不时寒热。久而不已。肝脉弦紧。用小柴胡加生地。治之而愈。但见风。寒热仍作。此是脾胃气虚。用加味归脾、补中益气二汤。兼服而止。", "4021": "江篁南治一贵妇寡居。月候不调。常患寒热。手足或时麻木。且心虚惊悸。或心头觉辣。诸治不效。诊其肝脉弦出左寸口。知其郁而有欲心不遂也。乃以乌药、香附二味投之。二服诸证俱减。", "4022": "震按欲男子而不得。则相火内郁。郁久必致气血暗耗。阴阳交争。自生寒热。不皆由精血离位。渍入隧道而变寒热也。故失合之证成痨者。多非药可愈。江氏讲肝脉弦出寸口谓肝主疏泄。今肝火不泄。逆而上行。此说却通。又魏氏云。今人脉上鱼际者。十居其五。或左或右。或左右皆然。阴虚火盛之人。类多见之。不可定为郁病。此说亦是。", "4023": "震按此即血热崩漏治法。然悲哀太过伤肺伤心。致元气暴虚而崩者。当用人参。如归脾汤之类。断不可用凉膈散。须以脉辨之。", "4024": "江汝洁治叶廷杰之内。十月。病眼若合即麻痹。甚至不敢睡。屡易医。渐成崩疾。江诊得左手三部。举之略弦。按之略大而无力。右手三部。举按俱大而无力。经曰。血虚脉大如葱管。又曰。大而无力为血虚。又曰。诸弦为饮。又曰。弦为劳。据脉观证。盖由气血俱虚。以致气不周运而成麻痹。时医不悟而作火治。药用寒凉过多。损伤脾胃。阳气失陷而成崩矣。以岁运言之。今岁天冲主运。风木在泉。两木符合。木盛而脾土受亏。是以土陷而行秋冬之令。以时候言之。小雪至大雪之末。六十日有奇。太阳寒水司令。厥阴风木客气加临其上。水火胜矣。经曰。甚则胜而不复也。其脾大虚。安得血不大下乎。且脾裹血。脾虚则血不归经而妄下矣。法当大补脾经为先。次宜补气祛湿。可得渐愈矣。以人参三钱。黄耆二钱。甘草四分。防风、荆芥、白术各一钱。陈皮八分。水煎。食远服。一剂分作三服。不数剂而安。", "4025": "震按脉大而无力。乃气虚之确据。何可指定为血虚。况麻属气虚。先哲之成言也。气虚不能摄血则崩。参、耆在所必用。惟左手脉举之略弦。似有风邪。少加荆、防。亦是。微嫌议论拖沓。借司天运气以张大其说。反觉宽泛耳。", "4026": "易思兰治一妇患崩。去血极多。用止血药。崩愈甚。卧床月余。羸瘦食少。面青爪黑。气促痰喘。易诊之。心脉平和。肝脉弦大时一结。肺脉沉而大且有力。脾胃脉沉涩。两尺沉而无力。曰。此气郁证也。询之。果因怒而致。乃用香附、乌药、苏梗为君。抚芎、白芷为臣。当归、白术、神曲、甘草为佐使。服药后。顿觉神爽。诸证减半。举家欣跃。易曰未也。明日子时分。指甲变桃红色。方可救。至期甲色果红。又诊之。左三部如前。肺脉微起。脾胃虽沉缓而不涩。两尺照旧。谓其家曰。午时血当大崩。毋得惊惶以骇病者。至期。果下紫黑血块数枚。自此遂止。或问曰。崩。血证也。人用血药不效。公用气药而止者。何也。易曰。崩虽在血。其源在气。气如橐籥。血如波澜。血随气行。欲治其血。先调其气。然有调气而血疾不愈者。有不调气而治血亦愈者。又何也。盖所因有不同耳。有因血而病气者。有因气而病血者。能以脉证辨之。而治法之先后定矣。如人禀来血虚者。血虚气必盛。为咳血潮热咽痛等证。此则以血为主。而用滋阴降火之剂。今此证时值秋令。肺脉宜浮短而反沉大。失其令矣。有云。下手脉沉。便知是气。大者火也。气有余即是火。沉而兼大。是气郁而不运也。况肝木至秋。脉当微弱。兹反弦大而结。肝脉结者。血积于内也。病因肝家怒火郁结。血不归经而妄行。非因气而病血者乎。故以治气为先也。曰。指甲已黑矣。君断子时变红。血已止矣。君断午时复来。何也。易曰。此正阴阳生长之妙也。盖血活则红。血凝则黑。爪甲黑者。血凝而不散也。今用药以行其气。至子时一阳初动。气行则血活。故黑甲变而红矣。至午时一阴复生。肝乃乙木。乙木生于午。肝气得令。其邪不能容。故积血于此时尽出。积出则气运血行。循环经络而病已矣。", "4027": "孙东宿治潘敬斋媳。经水不调。医投安胎之剂。越七月。经水忽大行。内有血块筋膜如手大者一二桶。昏冒困惫。其脉右关洪滑。左寸洪数。两尺皆洪大。病交夜分。咬牙乱语。手心热。口噤。时手足皆冷。心头胀闷不快。面色青。诸医皆谓难治。孙曰无恐。此浊痰流滞血海。以误服安胎之剂。益加其滞。血去多。故神魂无依。痰迷心窍。故神昏语乱。其发于夜半者。乃痰热在心包络与胆经。故每至其时而发。为之调气开痰。安神养血。可生也。即以温胆汤加石菖蒲、酒芩、天麻、枣仁、丹参与服。其夜子丑时。咬牙乱语皆减半。次日仍与前药。每帖加竹茹五钱。临睡又与黑虎丹数粒。诸证悉去而愈。", "4028": "震按此证不用脱血益气之法。其察脉审证高矣。然此时著眼在昏冒胀闷等证。非血去多而犹不止也。温胆汤竹茹用至五钱。终系暴病。病根在痰火。误服补涩药以致崩。非久崩不痊者比。若吾邑钱观察夫人患崩证三年。名医毕集。靡药不尝。迨后用归脾汤几数百帖。服参无算。旋愈旋发。卒致不起。纵遇孙公。亦复何法以治之。", "4029": "施笠泽治祁君万之内。崩中。服地榆、续断等药不效。施诊其脉沉而结。曰。蓄血证也。病得之天癸至而怒。祁曰然。因怒经止。半月后即患崩证。迄今一月矣。乃用桃仁、大黄行血破瘀。或谓失血复下。不导其势耶。施曰。血随气滞。蓄积不散。壅塞隧道。溢而妄行。决壅去滞。则血自归经矣。不然。舍其本而治其末。何异下水塞流乎。服汤二剂。果下衃血。天癸旋至。", "4030": "〔附〕高鼓峰治一产后恶露不尽。至六七日。鲜血奔注。发热口渴。胁痛狂叫。饮食不进。用养血及清肝行血药。无一效。高诊其脉。洪大而数。乃曰。此恶露未尽。留泊血海。凡新化之血。皆迷失故道。不去蓄利瘀。则以妄为常。曷以御之。用醋制大黄一两。生地一两。桃仁泥五钱。干漆三钱。浓煎饮之。或曰。产后大虚。药毋过峻否。高曰。去者自去。生者自生。何虚之有。服后下黑血块数升。诸病如失。再用补中益气调理而痊。", "4031": "震按此二案。若合符节。要皆实证也。实证易治。一攻即愈。虚证难医。屡补无功。经云。不能治其虚。何问其余。以见能治虚者。自无难题矣。夫治虚用补。通套之法也。审其脏腑经络奇经。虚在何处。有无寒热湿风之兼挟。细细分别。尚或效或不效。其效者为能治。不效者仍为不能治也。寒热湿风。古人皆有成方。而风之一字。今多忽略。内经云。卒风暴至。则经水波涌而陇起。原与天暑地热。经水沸溢。对待为言。故古人治风入胞门。有一味防风丸、举卿古拜散等方。若肝风内动。则未之及。肝属风木。主藏血。因怒因郁。皆致斯病。须以逍遥散、虎潜丸、乌梅丸、补肝汤。斟酌加减。盖即肝风动血。又有挟寒、挟热、挟瘀之分。人参、熟地、阿胶、黄连、地榆、桂、附、桃仁、柏子仁、三七、郁金等。可凭脉证参入。总在临机权变。不得只以虚目之也。", "4032": "程明佑治一妇。病带下不止。医投调经剂。血愈下。复投寒凉药。遂下泄。肌肉如削。不能言。四肢厥逆。程诊其脉细如丝。曰。阳气微而不能营阴。法当温补。阳生则阴长而血不下漏。遂以人参二两。附子三片。浓煎。一服手足微温。再服思食。继服八珍四十剂愈。", "4033": "孙东宿治吴太夫人。年六十余。久患白带。历治不效。变为白崩。诊得右寸滑。左寸短弱。两关濡。两尺皆软弱。孙曰。据脉心肾俱不足。而中焦有湿。今白物下多。气血日败。法当燥脾。兼补心肾。乃制既济丹。用鹿角霜、当归、茯苓各二两。石菖蒲、远志各一两五钱。龙骨、白石脂各一两。益智仁五钱。山药糊丸。空心服以补心肾。又制断下丸。用头二蚕沙炒三两。黄荆子炒二两。海螵蛸磨去黑甲、樗根白皮各一两。面糊丸。午后服以燥中宫之湿。不终剂而愈。", "4034": "陈斗岩治叶南洲妻。经闭五月。下白或赤。午后发热。咳嗽呕吐。医以为痨瘵。陈视之曰。两尺脉皆实。此必有孕。外受风邪。搏激故耳。饮清和之剂而安。未半年。生一子。", "4035": "程文彬治孕妇七个月。胸膈饱闷。气喘。忽吐出一物。如小肠寸许。举家惊疑其胎烂。程至。诊得寸口脉洪滑。知其气盛血少。胎气凑上。中焦蓄有湿热。湿生痰。知所吐之物。乃痰结聚。病名子悬。以紫苏饮加芩、连、贝母。十剂获全。", "4036": "孙东宿治一匠妇。怀妊五月而患心痛。究其所由起。谓由失足坠楼也。始教饮韭菜汁一盏。痛止。其夫又从邻医取药煎服。服后心复痛。吐鲜血盈益。胸间冲冲上抵。疼不可言。孙诊之。六脉洪大。汗出如雨。喘息不休。其妇楼居低小。令亟移居楼下。随与益元散五钱。用紫苏汤调服。即熟睡至晓。汗敛喘定。痛亦止。再与固胎饮一帖全安。邻医私询曰。吐血脉忌洪大。加以喘汗。危益甚矣。且妊妇禁汗。禁下。禁利小便。先生之药悉犯之。而反获效。何哉。孙曰。医贵审证。此妇之汗。以楼居低小。当酷暑而热逼故也。汗多血去而胎失养。故忡忡上抵。喘息不续。移楼下以避暑气。益元散为解暑圣药。而紫苏又安胎下气之妙品。气下则血归原而病痊矣。此对证之药。法出五海藏医垒元戎四血饮是也。特诸君检阅不遍。即检阅亦不知为胎产之治。余不过融会前人之法。用而不谬耳。", "4037": "一妇妊已七月。梦见亡故祖母。挥拳打背一下。惊醒。即觉胎动不安。血已下。大小便皆急。腰与小腹胀疼者五日。此亦事之奇也。孙诊其脉。两寸俱短弱。此上焦元气太虚。当骤补之。人参、耆、术、阿胶各二钱。归、芍、条芩、杜仲各一钱。砂仁、香附各五分。苎根嫩皮三钱。葱白六钱。一剂而血止。两剂诸证悉除。四剂后。减去苎根、葱白。调理旬日。足月而产一女。", "4038": "东宿曰。张氏妇年二十一。其夫延予诊。左寸关短弱。尺滑。右寸亦滑。关濡弱。尺沉微。诊毕。问予曰。脉何如。予曰。心神脾志。皆大不足。肺经有痰。夫曰不然。乃有身也。予曰。左寸短弱如此。安得有孕。夫曰。已七十日矣。予俯思久之。问曰。曾经孕育否。夫曰。已经二次。今乃三也。予问二产皆足月否。男耶女耶。夫曰。实不敢讳。始产近九个月。手足面目完全。而水火不分。胬肉一片。生下即死。次亦九个月。产下亦无啼声。看时口中无舌。亦旋死。二胎之异。不知何故。望先生细心察之。予方悟二胎之不完者。由心脾二经不足所致也。今左寸右关之脉可见矣。乃为筹思一方。专以补心血为主。令其多服。以百帖为率。枣仁、远志、茯神各一钱。白术二钱。归、芍、枸杞各一钱五分。甘草五分。生地八分。艾絮二分。龙眼肉五枚。水煎服。足月而产一子。次年又有身。不以前事为意。至九个月产下。形体俱具。外有脂膜一片包其面。耳目口鼻皆见。但不能去此脂膜。因思上年之子。为药之力也。", "4039": "震按两寸短弱为上焦元气大虚。左寸短弱为无孕。皆阅历老到之言。又可见察脉者。必须逐部细诊。但此案既云心脾二经不足。何但补心而不补脾耶。", "4040": "喻嘉言治顾季掖室人。仲夏时。孕已五月。偶尔下血。医以人参、阿胶。勉固其胎。又经一月。身肿气胀。血逆上奔。结聚于会厌胸膈间。食饮才入。触之痛楚。转下甚艰。稍急。即连粒呕出。全如噎证。更医数手。咸以为胎气上逆。脾虚作肿而成膈噎也。用人参之补。五味之收为治。延至白露节。计孕期已八月。而病势危极。呼吸将绝。始邀喻诊。其脉尺部微涩艰推。独肺部洪大无伦。其喘声如曳锯。其手臂青紫肿亮如殴伤色。喻骇曰。似此凶证。何不相商。幸余尚有善药。可以通其下闭上壅。季掖必求病名。喻曰。上壅者。以肺脉之洪大。合于会厌之结塞。知其肺当生痈也。下闭者。以尺脉之微涩。合于肉色之青肿。知其胎已久坏也。善药者。泻白散加芩、桔之苦以开之。不用硝、黄等疠药也。服二大剂。腹即弩痛。下白污如脓者数斗。裹朽胎而出。胸膈即开。连连进粥。但寒热咳嗽未除。旬余白污既尽。忽大肿大喘可畏。一以清肺为主。竟获全痊。", "4041": "丹溪治一妇。孕两月。呕吐头眩。医以参、术、川芎、陈皮、茯苓服之。愈重。脉弦。左为甚。而且弱。此恶阻病。必怒气所激。问之果然。肝气既逆。又挟胎气。参、术之补。大非所宜。以茯苓汤下抑青丸二十四粒。五服稍安。脉略数。口干苦。食则口酸。意其膈间滞气未尽行。以川芎、陈皮、山栀、生姜、茯苓煎汤。下抑青丸十五粒而愈。但口酸易饥。此肝热未平。以热汤下抑青丸二十粒。至二十日而愈。后两手脉平和。而右甚弱。其胎必堕。此时肝气既平。可用参、术。遂以初方参、术等补之。预防堕胎以后之虚。服一月而胎自堕。却得平安矣。", "4042": "震按右脉弱而胎必堕。虽投参、术无功。此必丹溪试验数次。故确信不疑。", "4043": "一妇孕三月吐痰水并饮食。每日寅卯作。作时觉小腹有气冲上。然后膈满而吐。面赤微躁。头眩。卧不能起。肢疼微渴。盖肝火挟冲脉之火冲上也。一日甚。二日轻。脉和。右手寸高。药不效者将二月余。偶用沉香磨水。化抱龙丸。一服膈宽。气不上冲。二三服。吐止眩减。食进而安。", "4044": "震按抱龙丸乃香窜辛散之药。似非孕妇所宜。竟获大效者。此妇必多郁。或多思。故气结而右寸脉高。诸香药能破郁开结。则效也。", "4045": "汪石山治一妇。形质瘦小。面色近紫。产后年余。经水不通。首夏忽病呕吐。手指麻痹挛拳。不能伸展。声音哑小。哕不出声。医皆视为风病。危之。汪诊脉皆细微近滑。曰。此妊娠恶阻病也。众谓经水不通。安有妊理。汪曰。天下之事。有常有变。此乃事之变也。脉虽细微。似近于滑。又尺脉不绝。乃妊娠也。遂以四君子加二陈治之。诸证俱减。尚畏粥汤。惟食干糕香燥之物而有生意。", "4046": "给事游让溪夫人。病新愈。月余经事不行。呕哕眩晕。饮食难进。医以为二阳之病发心脾。女子不月。法在不治。江篁南诊之。尺脉虽小。按之滑而不绝。此妊而恶阻。非凶候也。六君子加砂仁。数服而安。后产一女。", "4047": "丹溪治一妇。年四旬。孕九月。转胞。小便闭三日矣。脚肿形瘁。左脉稍和。而右涩。此必饱食气伤。胎系弱。不能自举而下堕。压膀胱。偏在一边。气急为其所闭。所以水窍不能出也。当补血养气。血气一正。胎系自举。以参、术、归尾、芍药、带白陈皮、炙甘草、半夏、生姜浓煎四帖。任其叫号。次早以四帖渣作一服煎。顿饮探吐之。小便大通。皆黑水。后遂就此方加大腹皮、炒枳壳、青葱叶、砂仁。作二十帖与之。以防产前后之虚。果得平安。产后亦健。", "4048": "一孕妇七月。小便不通。百医不得利。转加急胀。脉细弱。乃气血虚不能乘载其胎。故胎压膀胱下口。所以溺不能出。用补药升起。恐迟。反加急满。遂令稳婆以香油抹手入产户。托起其胎。溺出如注。胀急顿解。却以参、耆、升麻大剂服之。或少有急满。再托如前。", "4049": "丹溪治一妇。有胎至三个月左右即堕。其脉左大无力。重取则涩。乃血少也。以其妙年。只补中气。使血自荣。时正初夏。浓煎白术汤。调黄芩末一钱。服之至三四两。得保全而生。", "4050": "一妇经住三月后。尺脉或涩。或微弱。其妇却无病。知是子宫真气不全。故阳不施。阴不化。精血虽凝。终不成形。至产血块。或产血胞。惟脉洪盛者。胞不堕。", "4051": "震按尺脉或涩或微弱。与尺脉微滑按之不绝者。其是胎非胎。从此分别。必于指下辨得清。方于腹中决得定。下案神色甚困。难与之药。其尺脉必不滑。必按之无根也。后石山案两尺浮弱。不任寻按。几与此案脉同。竟以大补得保其胎。此又事之变者矣。", "4052": "石山治一妇。长瘦。色黄白。性躁急。年三十余。常患堕胎。已七八见矣。诊其脉皆柔软无力。两尺虽浮而弱不任寻按。曰。此因堕胎太多。气血耗甚。胎无滋养。故频堕。譬之水涸而禾枯。土削而木倒也。况三月五月。正属少阳火动之时。加以性躁而激发之。故堕多在三五七月也。宜用大补汤去桂。加黄柏、黄芩煎服。仍用研末。蜜丸服之。庶可保生。服半年。胎固而生二子。", "4053": "陈斗岩治一妇。有胎四月。堕下逾旬。腹肿。发热。气喘。脉洪盛。面赤口臭。舌青黑。陈诊之曰。脉洪盛者。胎未堕也。面赤。心火盛而血干也。舌青口臭。肝既绝而胎死矣。内外皆曰。胎堕久矣。复诊色脉如前。以蛇蜕煎汤下平胃散加芒硝、归尾一倍服之。须臾腹鸣如雷。腰腹阵痛。复一死胎堕下。病亦愈。", "4054": "魏云。产后气喘脉洪。法在不治。此所以得生者。全在逾旬二字。若非胎未堕。决不能至逾旬。", "4055": "陈仁甫治一妇。年近四十。禀气素弱。自去其胎。五日内。渐渐腹胀如鼓。至心前。吐不能食。用补药不效。诊六脉微弱。但只叫胀死。此乃损伤脾气而作胀。虽然当急则治其标也。若泥用丹溪方法。恐缓不及事矣。用桃仁承气加朴、实。倍硝、黄煎。服四分。吐去其一。至次日早。仍不通。事急。又服琥珀丸三钱。至申时大通。胀减。但体倦四肢无力。口不知味。发热。再用参、耆、归、芍、术、陈、楂煎服。八剂而安。", "4056": "一妇素怯弱。四月生女。自乳。患疥疮年余不愈。遂至羸困。五月勉强执姑丧礼旬月。每欲眩卧。一日感气。忽患心脾高肿作痛。手不可按。而呕吐不止。六脉微细之极。医以为脉虽虚而病形则实。误认诸痛不可补气。乃用青皮、香附、吴茱萸等药而愈。继复患疟。且堕胎。又投理气行气之剂。病去。元气转脱。再投参、耆补剂。不应矣。六脉如丝欲绝。薛诊云。皆理气之剂。损真之误也。连投参、耆、归、术、附子、姜、桂六剂。间用八味丸。五日眠食渐甘。六脉全复。薛云。心脾疼痛时。即当服此等药。疟亦不作矣。", "4057": "震按先前之痛已医好。继后患疟半产。亦云病去。乃追咎先前之不用温补。此岂人所能及。余因是言而追思生平所见心脾痛证。有屡治屡愈。屡愈屡发。数年之间发渐频。以至危殆者。安知不犯薛公所责耶。然屡发者。脉必弦小而坚。或更带数。必非微细之极。若至如丝欲绝。亦谁不能温补哉。", "4058": "江应宿治汪镐妻。三十五岁。厌产。服打胎药。下血如崩。旬余不止。或时鼻衄。诸药不效。江诊得六脉数而微弦。乃厥阳之火泛逆。投四物换生地。加阿胶、炒黑山栀、薄黄。一剂而愈。", "4059": "孙东宿曰。侄妇戴氏。孕已五月。忽血大下。午后发战。六脉俱数。左寸滑大。右关搏指。左关软弱。予以白芍二钱。生地、阿胶、人参、蒲黄各一钱。柴胡、香附、地榆、荆芥各七分。甘草五分煎服。午后发寒热。每夜凡三次。头痛恶心。腹中块硬。所下血块甚多。心下怯力。此虚无疑也。以补中益气加阿胶、炮姜、白芍、乌梅。下午。右眼白珠发一白泡。光肿下垂。而面亦肿。此虚火游行无制之证。其夜大发寒热。指爪皆黑。唇白。汗大出。腹中作痛。牵引两乳皆痛。仍以补中益气加阿胶、白芍、桂枝、五味、麦冬。服后热退汗止渴除。神气少定。乃有生意。次日。咳嗽而胎堕。即以独参汤继服。其夜肠鸣。泻二次。以参、术各三钱。炙草一钱五分。炮姜一钱。桂心、茯苓各五分。陈皮七分。莲子、大枣煎服。后因咳嗽。以四君加炮姜、五味、紫菀。调理而愈。", "4060": "张路玉治一妇。怀孕六月。因丧子悲哭动胎。医用芩、术安胎药二服。不应。改用枳壳、香附、紫苏、砂仁理气一服。胎遂上逼心下。胀闷喘急。口鼻出血。第三日薄暮诊之。其脉急疾如狂风骤雨。十余至则不至。顷之复至如前。因谕之曰。此孕本非好胎。安之无益。不若去之以存母命。因思此胎必感震气所结。震属木。惟金可制。令以铁斧。烈火烧红醋淬。乘热调芒硝末一两灌之。夜半。果下异胎。下后脉息微和。神思恍惚。所去恶露甚多。又与安神调血之剂。数服而安。", "4061": "许裕卿治邵涵贞内子。孕十七月不产。不敢执意凭脉。问诸情况。果孕非病。但云孕五月以后不动。心窃讶之。为主丹参一味。令日服七钱。两旬余胎下。已死而枯。其胎之死。料在五月不动时。经十三月在腹。不腐而枯。如果实在树。败则必腐。然亦有不腐者。则枯胎之理可推也。张石顽曰。余昔治马云生妇。孕十三月不产。脉来微结。为处十全大补汤。服至二十余剂。而下枯胎色白。所治虽异。而胎枯则一也。", "4062": "石山治一妇。常患横生逆产。七八胎矣。子皆不育。汪诊脉皆细濡颇弦。曰。此气血两虚兼热也。或曰。气血有余。方成妊娠。气血既亏。安能胎耶。汪曰。观其形长瘦。而脉细濡。属于气血两虚。色青脉弦。属于肝火时炽。而两尺浮滑。似血虚为轻。而气虚为重也。宜以补阴丸。除陈皮。倍加香附、参、耆。蜜丸服之。常令接续。逾年。临产果顺而育一子。", "4063": "陈良甫治一妇。有孕七个月。远归。忽然胎上冲心而痛。坐卧不安。两医治之不效。遂言胎已死矣。已用蓖麻子研烂。加麝香调。贴脐中以下之。甚危急。陈诊视两尺脉绝。他脉平和。陈问医作何证治之。答曰。死胎也。陈曰。何以知之。曰。两尺脉沉绝。陈曰误矣。此子悬也。若在胎死。却有辨处。面赤舌青。子死母活。面青舌赤。母死子活。唇口俱青。母子俱死。今面不赤。舌不青。其子未死。是胎上迫心。宜紫苏饮治之。至十帖。而胎乃近下矣。", "4064": "震按两尺脉绝。易认作子死腹中。若非陈氏辨法。宁不误杀两命。", "4065": "震按胞衣不下。因败血入胞者居多。立斋又有一案。用黑豆二合炒透。铁秤锤一个烧红。同以酒淬之。将酒化下益母丹二丸。胞衣从血而出。又方。芒硝三钱。童便冲服。立下。或以牛膝二两。芒硝三钱煎。冲童便饮。及阅慎斋全书。载一妇胞衣不下。用人参汤送下砂仁末钱许。一日二三次。三四日胞衣烂出。其妇无恙。奇矣。然不知脉证之何如也。继之者有黎姓一案。亦录于左。以助参酌。", "4066": "震按恶露不下。用参、附、术、归等药而下者。生平经手颇多。然必脉象细软。口不燥渴。内不烦热。用之方效。此案不载脉象。只云脾失其职。亦属糊涂。但半产者多系体虚而胎堕。且连服行血催衣之药四剂。宁不反其道以治之耶。", "4067": "立斋治一产妇。腹痛发热。气口脉大。薛以为饮食停滞。不信。乃破血补虚。反发热头痛。呕吐涎沫。又用降火化痰理气。四肢逆冷。泄泻下坠。始悔。问曰。何也。薛曰。此脾胃虚之变证也。法当温补。遂用六君子加炮姜二钱。肉桂、木香各一钱。四剂。诸证悉退。再用补中益气之剂。元气遂复。", "4068": "震按气口脉大。故认停食。后以误药而变四肢逆冷。泄泻下坠。诚变为虚寒证矣。但不知脉象若何。若脉亦变为细软。则温补得效。设脉仍大。则非所宜。或大而软。犹可用温补以望其敛小。倘脉大且数。按之有力。其死可必。温补无益也。", "4069": "震按此证不难于用归脾八珍。而难于用当归六黄。恨不载脉。然留此案以见古人有是病即用是药。勿拘定产后必当大补也。但苦寒之药。中病即止耳。", "4070": "一产妇小腹作痛。有块。脉芤而涩。以四物加延胡、红花、桃仁、牛膝、木香治之而愈。", "4071": "一产妇小腹作痛。服行气破血之药。不效。其脉洪数。此瘀血内溃为脓也。以瓜子仁汤。二剂痛止。更以太乙膏下脓而愈。产后多有此病。纵非痈患。用之亦效。", "4072": "一产妇小腹疼痛。小便不利。用薏苡仁汤。二剂痛止。更以四物加桃仁、红花。下瘀血而愈。大抵此证。皆因荣卫不调。或瘀血停滞所致。若脉洪数。已有脓。脉但数。微有脓。脉迟紧。乃瘀血。下之即愈。若腹胀大。转侧作水声。或脓从脐出。或从大便出。宜用蜡矾丸、太乙膏。及托里药。", "4073": "震按此种治法。惟薛公能之。若今人用参、附至四五钱不应。惟束手待毙耳。但不载脉象若何。想诸虚寒证毕现。其脉之大小迟数不足计耶。", "4074": "丹溪治一产妇。年三十余。正月间。新产十余日。左脚左手发搐。气喘不眠。面起黑色。口臭。脉浮弦而沉涩。右为甚。意其受湿。询之。产前三月。时常喜羹汤茶水。以黄耆、荆芥、木香、滑石、苍白术、槟榔、陈皮、川芎、甘草、芍药。四服后加桃仁。又四服而漉漉有声。大下水晶块。大小如鸡子黄与蝌蚪者数十枚。而愈。乃去荆芥、槟榔、滑石。加当归、茯苓。调理其血。四十帖而安。", "4075": "震按左脚左手发搐。似肝经血燥生风。气喘不眠。面起黑色。口臭。似瘀血入肺死证。脉象浮弦易辨。沉涩难辨。身临其局。彷徨无措者多矣。非丹溪岂能认为湿而用此等药乎。若下条薛案。稍有墙壁可循耳。", "4076": "一妇人发瘛遗尿。自汗面赤。或时面青。饮食如故。肝脉弦紧。立斋曰。此肝经血燥。风热瘛疭也。肝主小便。肝色青。入心则赤。法当滋阴血。清肝火。遂用加味逍遥散。不数剂诸证悉退。", "4077": "孙东宿治潘大司马媳。年二十五。体素弱。语言端谨。因难产伤力。继以生女拂意。后又女死悲戚。即时晕厥。醒而神思眯昧。手足瘛疭。不可诊脉。目上视。细询之。自女落地。恶露绝无。有女医时与人参干嚼。及独参汤并粥乱进。参与粥皆壅塞膈上不下。以故神昏瘛疭不已也。孙教以手于喉中探而吐之。喜其随手吐出痰饮粥药盈盆。瘛疭方定。乃与川芎、山楂、泽兰叶、陈皮、半夏、茯苓、香附进之。稍得睡。不虞女医又私与补药二帖。子丑时陡然狂乱。如降神之状。汉声官话。问答如流。其声壮厉。迥异平时。其家咸谓神附。祈祷百般。孙曰。此恶露不尽。乃蓄血如见鬼之证。非真有神佛相附也。以归尾四钱。川芎一钱五分。泽兰叶、益母草、滑石等。煎冲热童便。连饮二帖。狂乱少定而未除。意其胸中必有余痰作滞。前方中无佐使之品。故药力不行也。大加山楂为引。恶露稍行。神思即静。嗣后稍睡少时。手足微动。或自以手掌其面。或自以手捶其胸。昏乱不息。诊其脉近虚。早间面红而光。申酉时面色白。此血行火退。故脉虚而当补矣。与人参、川芎、泽兰叶各一钱。当归、山楂各二钱。茯苓、陈皮各八分。卷荷叶一片。煎冲琥珀末五分。服后嗳气二声。孙喜曰。此清阳升而浊阴降矣。自兹安静。恶露行。大便通。而索粥饮矣。", "4078": "震按此案前半段治法不难。盖得其参粥杂进之病情。自有消瘀及消痰食之方药。但探吐法尤捷耳。蓄血如见众。知者亦多。难于后半段恶露稍行。神思即静。略睡片时。昏乱不息。仍是蓄血形状。乃于轻剂消瘀之中。复用人参。并不以前曾误用而畏蹈故辙。此为高手。其讲脉与面色极是。但产后谵语昏狂。有纯因于痰者。又不可不知。", "4079": "易思兰治瑞州一妇。产后半月余。胃中有清水作逆而吐。以为胃寒。煎姜椒汤饮之。初觉相宜。至三五日。清水愈多。口气渐冷。四肢发逆。腹中冷气难堪。有时战栗。以四物汤加人参、炮姜。初服少安。久则不应。易诊之。六脉俱无。以三指按至尺后。脉来实数有力。左右皆同。发言壮厉。一气可说四五句。唇焦颊赤。大便五六日一次。小便赤少。此实热症也。询之。其俗产后食胡椒炒鸡为补。此妇日食三次。半月后遂得疾。蓄热明矣。其口冷吐水发厥者。热极似水耳。战栗者。热入血室。热盛生风也。用三黄汤连投之。六脉俱现。清水渐减。姜椒汤不欲食矣。服四日。口中热气上升。口舌发黄小粟疮。大便八日不通。以四苓合凉膈散空心一服。至午不动。又以甘草煎汤。调元明粉五钱。热服一时许。腹中微鸣。吐出酸水一二碗。大便连去二次。仍以四苓散、三黄、山栀、枳壳调理。一月全愈。大凡诊脉。遇极大极微者。最宜斟酌。如极大而无力。须防阳气浮散于外。如极微之脉久久寻而得之于指。稍稍加力。按之至骨愈坚牢者。不可认作虚寒。今此证六部皆无脉。尺后则实数有力。所谓伏匿脉也。阳匿于下。亢之极矣。岂可泥于产后。禁用寒凉者。", "4080": "震按易公之案甚多。此为第一。观其发明脉理。可谓仙传秘诀。", "4081": "滑伯仁治一产妇恶露不行。脐腹痛。头疼身寒热。众皆以为感寒。温以姜、附。益大热。手足搐搦。谵语目窜。诊其脉弦而洪数。面赤目闭。语喃喃不可辨。舌黑如炱。燥无津润。胸腹按之不胜手。盖燥剂搏其血。内热而风生。血蓄而为痛也。曰。此产后热入血室。因而生风。即先为清热降火。治风凉血。两服颇爽。继以琥珀、牛黄等。稍解人事。从以张从政三和散。行血破瘀。三四服。恶露大下如初。时产已十日矣。于是诸证悉平。", "4082": "魏云。投姜、附后始搐搦。由燥剂搏血而风生。故此等案宜细心熟玩。若是虚寒。手足岂不厥冷。况证有舌黑腹不胜按。在三四日者耶。又况面赤洪数之脉耶。", "4083": "一妇产后。时发昏瞀。身热汗多。眩晕口渴。或时头痛恶心。医用四物凉血之剂。病不减。复用小柴胡。病益甚。汪诊之。脉皆浮洪搏指。汪曰。产后而得是脉。又且汗多而脉不为汗衰。法在不治。所幸者气不喘。不作泄耳。其脉如是。恐为凉药所激也。用人参三钱。黄耆二钱。甘草、当归各七分。白术、麦冬各一钱。干姜、陈皮、黄芩各五分。煎服五剂。脉敛而病渐安。", "4084": "震按浮洪搏指之脉。产后所大忌。合以身热口渴。时发昏瞀。头痛恶心。几与伤寒证相似。用小柴胡汤未为大谬。以方中原有人参也。但汗多眩晕。柴胡不宜。汪公之论。明白切当。非大剂人参。岂能挽回。至云其脉如是。恐为凉药所激。后学安知有此道理。服五剂而脉敛。言更验矣。", "4085": "王佥宪公宜人。产后因沐浴。发热呕恶。渴欲饮冷水瓜果。谵语若狂。饮食不进。体素丰厚不受补。医用清凉。热增剧。石山诊之。六脉浮大洪数。曰。产后暴损气血。孤阳外浮。内真寒而外假热。宜大补气血。与八珍汤加炮姜八分。热减大半。病人自知素不宜参、耆。不肯再服。过一日。复大热如火。复与前剂。潜加参、耆、炮姜。连进二三服。热退身凉而愈。", "4086": "震按病由沐浴而发热呕恶。渴欲饮冷。狂谵不食。人必以伤寒视之。及用清凉而热增剧。茫无把握矣。况脉洪数。用滋阴易。用参、姜难也。乃投八珍热减大半。停参、耆一日。复大热如火。则病宜温补。不宜凉散。始得显然耳。", "4087": "孙东宿治武进邑宰孙康宇媳。年十六。初产女艰苦。二日偶感风邪。继食面饼。时师不察。竟以参、术投之。即大热。谵语口渴。汗出如洗。气喘泄泻。泻皆黄水无粪。一日夜不计遍数。小水短少。饮食不进。证甚危恶。时当暑月。女科见热不除。用芩、连等药。证益甚。乃重用参、术、肉果、干姜等止泻。泻不减。热反剧。喘汗转加。谵语不辍。医悉辞去。孙往诊之。六脉乱而无绪。七八至。独右关坚硬。踌躇久之。因思暑月汗出乃常事。但风邪面食瘀血。皆未消熔。补剂太骤。书云。蓄血如见鬼。治当消其瘀食。解其暑气。犹可图生。勿遽弃也。乃用益元散六钱。解暑清热为君。仲景云。渴而小便不利者。当先利其小便。况水泻犹当用之为君也。以楂肉三钱为臣。红曲、泽兰叶各一钱五分。消瘀血。安魂为佐。香附、橘红、半夏、茯苓以统理脾气为使。京三棱五分。消前参、术。决其壅滞为先锋。水煎。服后即稍睡。计两日。连进四剂。热减泻止。恶露略行。脉始有绪。前方去三棱、红曲。加扁豆。而热全退。便亦实。改用四君子汤加益元散、青蒿、香附、扁豆、白芍。调理而平。", "4088": "震按前二案虚证似实。此案实证似虚。病之能惑人也如此。但用芩、连而证益甚。用参、术兼温药而更加剧。亦将束手无策。孙公之得间处。在右关独坚硬。信乎善治病者。必善辨脉也。若粗工见其证极沉重。脉又七八至。乱而无绪。不遑细辨。此女何由得生。今从辨脉得病情。用药自游刃有余。而药之得力处。又在京三棱五分也。", "4089": "别驾沈石山夫人。产三日而腹不宽畅。一女科为下之。大泻五六次。遂发热恶心。又用温胆汤止吐。小柴胡退热。服四日。吐与热不止。粒米不进。又用八珍汤加童便。服后昏愦。耳聋眼合。口渴肠鸣。眼胞及手足背皆虚浮。因逆孙诊。六脉皆数。时五月初二日也。东宿曰。脉书云。数脉所主。其邪为热。其正为虚。以十全大补汤加炮姜进之。夜半稍清爽。进粥一盂。始开目言语。次日以多言语。复昏昧。又以参、术各三钱。炮姜、茯苓、陈皮各一钱。甘草五分。煎服。体微汗。遍身痱痤。热退而神爽。下午药不接。且动怒。昏昧复如前。六脉散乱无伦。状如解索。痱痤没而虚极矣。亟以参、术各五钱。炙草、炮姜、附子各一钱。连进二帖。是夜熟寝。唯呼吸之息尚促。初六日脉又数。下午发热不退。环跳穴边发一毒如碗大。红肿微痛。前医者遂归咎姜、附。拟用寒凉解毒药。孙曰。此乃胃中虚火游行无制。大虚之证。非毒也。内经云。壮者气行则愈。怯者著而成病。惟大补庶可万全。用寒凉。速其死矣。乃煎附子理中汤进之。日夕两帖。参、术皆用七钱。服后痱痤复出。毒散无踪。热亦退矣。再以参苓白术散。调理而全安。皆由产后误下。致变百出。可不畏哉。", "4090": "震按八珍与十全大补。相去不远。乃一则服之而加重。一则服之而遽轻。其义何居。盖得力在肉桂及加炮姜也。而敢于用姜、桂。由于数脉之义。参得透耳。其邪为热。其正为虚二语。与景岳恰合。英雄所见略同也。今人一见数脉。只知为热。断不敢用姜、附、桂。夭枉者多矣。但温补既投。亦须数脉渐退。仲景云。数脉不时。则生恶疮。故后有发毒之变。孙公能认定为虚。故终以大剂温补收功。较之胸无主见。随境游移者。自是仙凡迥别。", "4091": "程石洲乃眷因产难子死。忧闷。小腹有块作痛。下午发热。不思饮食。东宿诊之。脉右大于左者三倍。且数。与芎归汤加山楂、泽兰、肉桂。次日下午。腰腹胀痛。诘之。晌午食圆眼一斤矣。从此小腹渐胀。大便三日未行。早晨鼻衄。夜间极热。口渴。脉大无绪。势甚危急。用芎、归、红花、桃仁、青皮、槟榔、莪术、山楂。水煎。调元明粉二钱。服后。下结粪二枚。安而就寝。醒后。进粥稍多。又复胀痛。腹大如斗。坚如石。气促不安。势危之至。乃与五灵脂、山楂各四钱。凌霄花二钱。赤芍一钱。服后大便通。腹软气定。始可进粥。渐有生气。但脉仍鼓指。此腹中积滞尚多。不可不因其时而驱去也。用山楂、大黄各三钱。桃仁二钱。桂心、红花各五分。炙甘草七分。煎冲元明粉一钱五分。其夜下黑粪四次。热始退。上腹虽消。脐下仍大。仍以桃仁承气加山楂、滑石、红花。煎饮之。五更大便行。脐腹胀又减。后与积块丸调理全消。是役也。女科于初起发热腹痛之时。即以常套十全大补汤投之。讵如圆眼肉入腹。渐渐胀开。故腹亦因之大胀。且其味甘。尤能作滞。复加地黄、参、术。宁不塞其塞哉。由是而成大坚之证。内经谓中满者。泻之于内。良以此夫。彼亦泥乎丹溪产后须大补气血之误也。", "4092": "震按此案与前案截然不同。数脉大脉。均为产后所忌。而彼用温补。此用攻消。俱获全安。自非名手不能。观石山论浮洪搏指之脉曰。恐为凉药所激。此则认为积滞尚多。可见临证者全在圆通活变。断无一定之法可守也。", "4093": "马元仪治苏州藩司王管家之妻。产后一月。神气昏倦。胸满中痛。咳嗽喘促发热。服药反渐加重。势将治木。马诊之。两手脉沉涩兼结。马曰。此证胎前已有伏邪。产后气血既虚。邪益内结。法宜表里两和。使邪从外达。气从内泄。病自愈矣。用桂枝、柴胡、苏梗、枳壳、半曲、菔子、杏仁、广皮透邪达滞之剂。服后病势偏安。脉亦稍舒。前医尚以气血两虚。遽投参、地、归、芍敛滞之品。遂致彻夜靡宁。如丧神守。不知邪结于中。反行补法。如欲盗之出而反闭其门也。急改透邪散结法。用桂枝、炮姜、黄连、枳实、厚朴、广皮等。一剂而胸满中痛之证释。复用栝蒌实、柴胡、桂枝、半夏、枳实、杏仁、苏子、桔梗等。再剂而表热喘嗽之证平。但大便不行。此久病伤津液。肠胃失养之所致也。加生首乌一两。大便得解。余邪尽去。然正气大亏。继进滋补气血之剂而安。盖病有虚邪内结。而正气积亏者。当补正以托邪。而不知者反治邪而伤正。有正气未伤。而邪势方张者。当去邪以安正。而不知者反用补以滞邪。虚实莫辨。多致冤沉无诉。而尚不觉也。岂不谬哉。", "4094": "震按产后病因。果系外邪者。定当祛邪。不可泥于丹溪之说。曾见胎前受暑湿致痢。痢未几而产。产后仍痢。腹痛胸满。后重口渴。脉数大者。竟用芩、连、槟、朴、滑石、木香。甚则加大黄殊效。与此案治法。病异而理同也。", "4095": "吴茭山治一少妇。初产四日。食冷物。觉身分不快。呕逆。饮食少思。心腹满闷。时或腹胁刺痛。晨恶寒。晚潮热。夜则恍惚谵语。昼则抽搐。颇类风状。变异多端。诸医莫测。或作虚风。或云血凝实热。用甘温行血。以寒凉退热。如此半月不效。吴至。见医满座。亦局蹜。诊其脉弦而紧。遂令按之。小腹急痛。知瘀血未尽也。思患者大势恶露已下。未必还有余血。偶因寒凉所伤。瘀血停滞下焦。日久客于经络。所以变生诸证。须得大调经散。倍入琥珀化诸恶血成水。其患方愈。遂合前药服之。五日后。行恶水斗许。臭不可近。患人觉倦。病势渐减。然后以人参养荣汤数十帖。月余如初。", "4096": "一妇产后恶露未尽。因起抹身。寒气客于经络。乍寒乍热。脉紧而弦。以葱白散。二帖而安。", "4097": "立斋治一产妇。恶寒发热。欲以八珍加炮姜治之。其家知医。以为风寒。用小柴胡汤。薛曰。寒热不时。乃气血虚。不信。仍服一剂。汗出不止。谵语不绝。烦热作渴。肢体抽搐。薛用十全大补二剂。益甚。脉洪大。重按如无。仍以前汤加附子数剂。稍缓。再服而安。", "4098": "震按前二案。以脉弦而紧知为瘀血。此案以脉洪大。重按如无。知为气血两虚。是真临证指南也。但首案必须大调经散。次案必须葱白散。决非通套行血消瘀所能治。此案必须桂、附。亦非平补气血所能治。", "4099": "乐元忠妻。产后病惊。身飘飘如在浮云中。举目则旋转。持身不定。四肢酸软。皆以安神补虚治之。前证转甚。载原礼独曰。左脉芤且涩。神色不变。是因惊致心胞络积血耳。乃下血如漆者一斗。遂愈。古人云。大实似羸者此也。", "4100": "震按此证必共认为虚矣。苟不辨其左脉之芤涩。岂能测其心胞之积血耶。人只知惊是病。不知因惊而又致病。则治惊无益也。可举此案以例其余。", "4101": "汪石山治一妇。产后未经满月。怒气。血流如水。三日方止。随又劳苦。四肢无力。睡而汗出。日晡潮热。口干。五心如炙。诸医皆用柴、芩、薄荷之类。其热愈炽。诊其脉弦大无力。此蓐劳也。以四物汤一两。入胡黄连、秦艽、青蒿各五分。数服热退身凉。后以黄连八珍丸一料而安。", "4102": "立斋治大尹俞君之内。产后发热晡热。吐血便血。兼盗汗。小便频数。胸胁胀痛。肚腹痞闷。薛曰。此诸脏虚损也。治当固本为善。自恃知医。用降火之剂。更加泻痢肠鸣。呕吐不食。腹痛足冷。始信薛言求诊。其脉或浮洪。或沉细。或如无。其面或青黄。或赤白。此虚寒假热之状。时值仲夏。当舍时从证。先用六君子汤加炮姜、肉桂。数剂胃气渐复。诸证渐退。更佐以十全大补汤。半载全愈。", "4103": "震按此条脉法。可为大虚之据。", "4104": "一产妇泻痢年余。形体骨立。内热晡热。自汗盗汗。口舌糜烂。曰吐痰三碗许。脉洪大。重按全无。此命门火衰。脾土虚寒而假热。吐痰者。乃脾虚不能统摄归源也。用八味丸补火以生土。用补中益气兼补肺金而脾胃健。", "4105": "汪石山治一妇。产后滑泄。勺水粒米弗容。即时泄下。如此半月余。众皆危之。或用五苓散、平胃散。病益甚。汪诊之。脉皆濡缓而弱。曰。此产中劳力以伤其胃也。若用汤药。愈滋胃湿。非所宜也。令以参苓白术散。除砂仁。加陈皮、肉豆蔻。煎姜枣汤调服。旬余而泻止。", "4106": "金大文先生治一妇。产后三日发疹。细而成粒。不稀不密。用荆芥、蝉蜕、黏子等药一剂。头面俱透。越一日。渐有回意。忽大便溏泄数次。觉神气不宁。问其所苦。曰热曰渴。语言皆如抖出。脉来微细。数有七至。外露但欲寐少阴证据。金曰。此阳脱证也。属少阴。用生附子三钱。水洗。暵如炒米。干姜炒八分。甘草炒一钱。白芍炒一钱半。水煎。冲人尿一调羹。猪胆汁四小茶匙。时已黄昏。无猪胆。以青鱼胆汁代之。服毕即睡。觉来热渴俱除。续用黄耆建中汤加丹参、苏木。二剂而安。", "4107": "震按此二案。有大见识。大力量。故能起死回生。较之汪案。高逾十倍。但汪案勺水粒米弗容。即时泄下。亦诚危矣。然处方平淡。不过以散换汤之巧。亦即效者。盖脉濡缓而弱。与脉微细而数有七至者。其平险各别也。", "4108": "震按此证甚危。此方甚巧。若用六君而不加犀角失笑散。则不应。用犀角失笑散而不合六君。亦不应。但以意度之。不凭脉象。固由汪公熟能生巧。而其病机。在乎痰与血交涌而上。才侧身。便壅绝。显系败血随痰上升。然非血气脾胃之大虚。败血何由随痰上升耶。此方所以恰对也。闭门造车。出门合辙。先生之谓欤。", "4109": "一产妇因收生者不谨。损破尿胞。而致淋沥不禁。丹溪曰。肌肉破伤。在外者。尚可完补。胞虽在腹。恐亦可治。诊其脉虚甚。盖难产。因气血虚。故产后尤虚。试与峻补。以参、术为君。芎、归为臣。桃仁、陈皮、黄耆、茯苓为佐。以猪羊胞煎汤熬药汁。极饥饮之。一月而安。盖气而骤长。其脬即完。恐稍迟即难成功也。", "4110": "立斋治一男子。年十六。夏作渴发热。吐痰唇燥。遍身生疥。两腿尤多。色黯作痒。日晡愈炽。仲冬腿患疮。尺脉洪数。薛曰。疥。肾疳也。疮。骨疽也。皆肾经虚证。针之脓出。其气氤氲。薛谓火旺之际。必患瘵证。遂用六味地黄、十全大补。不二旬。诸证愈而瘵证具。仍用前药而愈。抵冬娶妻。至春诸证复作。父母忧之。令其外寝。幸年少谨疾。亦服地黄丸数斤。煎药三百余剂而愈。", "4111": "孙东宿治查景川。遍身痱痤。红而掀痒。诸人以蒺藜、荆芥、升麻、葛根、元参、甘草、石斛、酒芩与之。不愈。又谓为风热。以元参、蝉蜕、羌、防、赤芍、甘草、生地、当归、升麻、连翘、苍耳子服之。饮食顿减。遍身发疮。痛痒不可言。孙诊之。两手脉俱缓弱。以六君子汤去半夏。加扁豆、砂仁、苡仁、山药、藿香、黄耆。一服而饮食进。四帖而痛痒除。十帖疮疥如脱。", "4112": "一儒生左腿近环跳患瘤。状如大桃。按之濡软。恪服除湿流气化痰之剂。恶寒发热。食少体倦。形气俱虚。脉洪大而虚。气瘤也。肺主之。盖胆属木。肺属金。此发于胆经部分。乃肺金侮肝木。元气亏损。而其脓已内溃矣。遂用十全大补汤数剂。出清白稀脓甚多。顿加寒热。烦渴头痛。殊类伤寒。薛谓此因脓泄而血气益虚耳。仍用前汤。其势益甚。脉洪数大。按之如无。乃加附子一钱。其势愈甚。而脉复如前。此虚甚而药未能及也。更加附子二钱。三剂诸证顿退。乃朝用补中益气汤。夕用十全大补汤。各三十余剂。出腐骨五块。疮口将完。后因不慎起居。患处复溃。诸证更发。咽间如焚。口舌无皮。用十全大补加附子一钱服之。诸证悉愈。二日不服。内病悉至。患处复溃。二年后又患。服前药不应。诊其尺脉。微细如丝。此属命门火衰。用八味丸为主。佐以十全大补汤。稍愈。又二年。仍患虚寒之证而殁。", "4113": "一妇瘰疬后。遍身作痒。脉大。按之虚。以十全大补加香附治之而愈。大凡溃后。午前痒作气虚。午后痒作血虚。若作风证治之。必死。", "4114": "杨乘六治下昂俞文遇患瘰疬。左右大小十余枚。坚硬如石。颈项肿大。不能转侧。兼吐血咳嗽梦遗泄精等证。服药半年。皆滋阴泻火。固精伐肝之剂。遂致痰咳不绝。梦泄不止。竟成弱证。邀杨视之。见其性情慷慨。有豪爽气。且操心精细。多思虑。刚果躁直。知其致病之原。由于肝胆用事。恼怒居多。以致肝胆先病。而延及心脾者也。其痰咳不绝者。肝气虚逆。痰随气上也。梦泄不止者。肝经气血亏损。疏泄失职也。瘰疬肿大。坚硬不能消散者。肝经气血虚滞。郁结不舒也。诊其脉。弦劲中兼见躁动。而左手关尺独紧细如刀。口舌青色。嫩而胖且滑。乃以养营汤倍肉桂主之。服至月余。内外各证。俱有痊意。遂以前方作丸。佐归脾养心两方。随证消息。守服三月。诸证悉除。而左右瘰疬俱消。", "4115": "石山治一妇。年近三十。形色瘦白。素时或咳嗽一二声。月水或前或后。夏月取凉。遂咳甚。不能伏枕者月余。嗽痰中或带血。或兼脓。嗽急则吐食。医用芩、连、二陈。不效。复用参、耆等补药。病重。汪视左脉浮滑。右脉稍弱而滑。幼伤手腕。掌不能伸。右脉似难凭矣。乃以左脉验之。恐妊兼肺痈也。遂以清肺泄肺之剂进之。三服而能著枕。痰不吐。脓不咯。惟时或恶阻。汪曰。此妊之常病也。教用苡仁、白术、茯苓、麦冬、黄芩、阿胶煎服。病减。月余复为诊脉。皆稍缓而浮。曰。热已减矣。但吐红太多。未免伤胃。教用四君子加陈皮、黄芩、枳壳煎服调理。妊至六月。食鸡病作。却鸡而愈。至九月。病又复作。声哑。令服童便获安。汪曰。产后病除。乃是佳兆。病若复作。非吾所知。月足而产。脾胃病作。加泄。竟不救。", "4116": "一男子面赤吐脓。发热作渴。烦躁引饮。脉洪数而无伦次。此肾火伤肝。先用加减八味丸加麦冬大剂一钟。热渴顿止。久睡觉而神爽索食。再剂。诸证又减六七。仍用前药。更以人参五钱、麦冬二钱五分。五味二钱。水煎代茶。日饮一剂。月余而安。此证面赤者当补脾肾。面白者当补脾肺。故用此药。", "4117": "江应宿治贡士汪宾篁。患滞下赤白。月余。江诊视。投药数剂而愈。六脉洪数不减。即告之曰。公年高。足三阴虚损不能相生。当滋化源。否则恐生他病。与六味地黄丸加生脉散。因循半月。未及修制。遂觉右乳旁牵痛。面赤。吐痰腥臭。脉洪大浮数。按之无力。江曰。脉数不时见。此肺痈也。次日。吐脓血甚多。投以桔梗汤加羚羊角。未应。再与升麻汤十余剂。更以前丸滋其化源而愈。", "4118": "王宇泰治一妇。感冒风寒。或用发表之剂。反咳嗽喘急。饮食少思。胸膈不利。大便不通。右寸关脉浮数。欲用通利之剂。王曰。此因脾土亏损。不能生肺金。若更利之。复耗津液。必患肺痈矣。不信。仍利之。虚证悉至。果吐脓。乃朝用益气汤。夕用桔梗汤。各数帖。又朝用益气汤。夕用十全大补汤。各五十帖。全愈。", "4119": "一男子用射干汤之类。乍愈。但气喘体倦。发热作渴。小便频数。用补中益气加山药、山茱、麦冬、五味。时仲夏。更以生脉散代茶饮而愈。", "4120": "石顽治谈仲安。体肥善饮。初夏患壮热呕逆。胸膈左畔隐痛。手不可拊。便溺涩数。舌上胎滑。食后痛呕稠痰。渐见血水。脉来涩涩不调。与凉膈散加石斛、连翘。下稠腻颇多。先是疡医作肺痈治。不效。张曰。肺痈必咳嗽。吐腥秽痰。此但呕不嗽。洵为胃病无疑。下后四五日。复呕如前。再以小剂调之。三下而势甫平。后以保元、苓、橘。平调二十日而痊。先时有李姓者患此。专以清热豁痰解毒为务。直至膈畔溃腐。脓水淋漓。缠绵匝月而毙。良因见机不早。直至败坏。悔无及矣。", "4121": "丹溪治一女子腹痛。百方不治。脉滑数。时作热。腹微急。曰。痛病脉当沉细。今滑数。此肠痈也。以云母膏一两。丸梧子大。以牛皮胶溶入酒中。并水下之。饷时服尽。下脓血一盆而愈。", "4122": "一妇以毒药去胎后。当脐右结块。块痛甚则寒热。块与脐高一寸。痛不可按。脉洪数。谓曰。此瘀血流溢于肠外肓膜之间。聚结为痈也。遂用补气血行结滞排脓之剂。三日决一锋针。脓血大出。内如粪状者臭甚。病妇恐。因谓气血生肌。则内外之窍自合。不旬日而愈。", "4123": "虞恒德治一人。得潮热。微似疟状。小腹右边有一块。大如鸡卵。作痛。右脚不能伸缩。一医作奔豚气治。十余日不验。虞诊其脉。左寸芤而带涩。右寸芤而洪实。两尺两关俱洪数。曰。此大小肠之间欲作痈耳。幸脓未成。犹可治。与五香连翘汤加减与之。间以蜈蚣炙黄。酒调服之。三日愈。", "4124": "儒医李生治一富家妇有疾。诊之曰。肠胃间有所苦耶。妇曰。肠中痛不可忍。而大便从小便出。医皆谓古无此证。不可治。李曰。试为筹之。若服我之药。三日当瘳。下小丸子数十粒。煎黄耆汤下之。下脓血数升而愈。其家喜。问治法。李曰。始切脉时。觉芤脉见于肠部。脉诀云。寸芤积血在胸中。关内逢芤肠里痈。此痈在内。所以致然。所服者。乃云母膏为丸耳。切脉至此。可以言医矣。", "4125": "一妇人小腹胀痛而有块。脉芤而涩。此瘀血为患。以四物加元胡索、红花、桃仁、牛膝、木香。二剂血下而愈。", "4126": "一妇人小腹胀痛。大便秘涩。转侧有水声。脉洪数。以梅仁汤一剂。下瘀血。诸证悉退。再以薏苡仁汤而愈。", "4127": "一妇人脓成胀痛。小便不利。脉洪数。服太乙膏三钱。下脓甚多。胀痛顿止。以栝蒌散、蜡矾丸及托里而安。", "4128": "江应宿治汪上舍之内。当脐结痛。发热恶寒。脉洪数。此肠痈也。投以仙方活命饮、五香连翘汤、栝蒌散。俱不应。过七日。小便间有脓血。乃制云母膏为丸。十数服而愈。可见药之对病。其验如此。", "4129": "一男子腹内作痛。腹外微肿。或欲药汗之。薛曰。肉色如故。脉数无力。此元气虚损。毒不能外发。遂与参、耆、归、术之类数剂。渐发于外。又数剂。脓成而欲针之。彼惑于人言。用大黄、白芷、穿山甲之类。引脓从便出。以致水泻不止。患处平陷。自汗盗汗。热渴不食。仍用前剂加半夏、陈皮、姜、桂。四剂。形气渐复。又数剂。针去其脓。仍用补剂。幸幼未婚。故得痊也。", "4130": "鸿胪苏龙溪。小腹内肿胀作痛。大小便秘结。作渴欲饮冷。脉洪数而实。用黄连解毒散。二剂热痛顿止。二便调和。用活命饮而愈。", "4131": "进士边云庄。腹痛恶寒。作湿痰食积治之。益甚。脉浮数。薛曰。浮数之脉更恶寒。疽疮之证也。彼不信。旬余复请视之。左尺洪数。知内有脓矣。仍不信。至小腹肿胀。连及两臀。始悟。薛曰。脓溃臀矣。气血俱虚。何以收敛。服活命饮一钟。臀溃一孔。出脓斗许。气息奄奄。势成可畏。用大补药一剂。神思方醒。每去后。粪从疮出。且出血甚多。痛不可忍。欲求死而不得。小腹间若觉有物上拄。即发痉。牙关紧。不省人事。发热烦躁。此时脉洪大。举按皆实。苏而诊之。脉仍洪大。按之如无。此气血虚极。以十全大补汤用参耆至四斤余。加附子二枚而痉止。共用此方五十余剂而疮敛。", "4132": "一妇形脉稍实。性躁。难于后姑。乳生隐核。以本草单味青皮汤。间以加减四物汤。加行经络之剂。治两月而安。", "4133": "一后生作劳。风寒夜热。左乳痛。有核如掌。脉细涩而数。此阴滞于阳也。询之。已得酒。遂以栝蒌子、石膏、干葛、台芎、白芷、蜂房、生姜同研。入酒服之。四帖而安。", "4134": "封君袁阳泾。左乳内结一核。月余赤肿。此足三阴虚兼怒气所致。用八味加柴、栀、丹皮。四剂。赤肿渐退。内核渐消。又用清肝解郁汤而愈。时当仲秋。两目连札。肝脉微弦。此肝经火盛而风动也。更加龙胆草五分。并六味地黄丸而愈。若用清热败毒。化痰行气。鲜不误者。", "4135": "一妇人内热胁胀。两乳不时作痛。口内不时辛辣。若卧而起急。则脐下牵痛。此带脉为患。用小柴胡汤加青皮、黄连、山栀。二剂而愈。", "4136": "一妇人发热作渴。至夜尤甚。两乳忽肿。肝脉洪数。乃热入血室也。用加味小柴胡汤。热止肿消。", "4137": "一产妇因乳少。服药通之。致乳房肿胀。发热作渴。以玉露散补之而愈。夫乳汁乃气血所化。在上为乳。在下为经。若冲任之脉盛。脾胃之气壮。则乳汁多而脓。衰则淡而少。所乳之子。亦弱而多病。又有屡产无乳。或大便涩滞。乃亡津液也。当滋化源。", "4138": "一子年十六。生七个月。得淋病。五七日必一作。其发则大痛。水道方行。下如漆和粟者一盏方定。脉之轻则涩。重则弦。视其形瘦而长。青而苍。意其父必服固下部药。遗热在胎。留于子之命门而然。遂以紫雪和黄柏末丸梧子大。晒极干。汤下百丸。半日。又下二百丸。食压之。又半日。痛大作。连腰腹水道。乃行下漆和粟者碗许。痛减十之八。后与陈皮一两。桔梗、木通各五钱。又下合许而安。父得燥热。尚能病子。况母得之者乎。", "4139": "景岳曰。予仲儿生未两周。初秋感寒发热。脉微紧。素知其脏气属阴。不敢清解。以芎、苏、羌、芷、细辛、生姜之属。冀散其寒。一剂下咽。不惟热不退而反大泻作。连泻二日。又加气喘。斯时也。将谓其寒气盛耶。何以用温药而反泻。将谓其火刑金耶。岂以清泻连日而尚堪寒凉。将谓其表邪之未除耶。则何以不利于疏散。束手无策。且见其表里俱剧。大喘垂危。又岂浅易之剂所能挽回。沉思良久。渐有所得。乃用人参二钱。生姜五片。煎汤。以茶匙挑与二三匙。即怀之而旋走室中。徐察其呼吸之进退。喘虽未减。亦不见增。又与三四匙。少顷。则觉其鼻息似乎少舒。遂与半小钟。更觉有应。自午及酉。完此一剂。适一医至。曰误矣。大喘如此。岂可用参。速以抱龙丸解之。余不听。复煎人参二钱五分。自酉至子尽其剂。剂完而气息遂平。齁齁大睡。泻亦止而热亦退矣。所以知其然者。观其因泻反喘。岂非中虚。设有实邪。自当喘随泻减。是可辨也。向使误听彼医。易以清利。中气一脱。即当置之死地。必仍咎余之误用参也。孰是孰非。何从辨哉。", "4140": "吕沧洲治一幼女。病嗜卧。颊赤而身不热。诸医皆以为慢惊风。屡进攻风之剂。兼旬不愈。吕切其脉。右关独滑而数。他部大小等而和。因告之曰。女无病。关滑为宿食。意乳母致之。乳母必嗜酒。酒后辄乳。故令女醉。非风也。及诘其内子。内子曰。乳母近掌酒库钥。窃饮必尽意。使人视之。卧内有数空罂。乃拘其钥。饮以枳椇子、葛花。日二三服。而起如常。", "4141": "石山治一女。六岁。病左手不能举动。三年矣。后复病痫。初用人参、半夏。或效或否。汪诊左脉浮洪。右脉颇和。曰。痰热也。令以帛勒肚。取茶子去壳三钱。挼碎。以滚汤一碗滤取汁。隔宿勿食。早晨温服。吐痰三碗许。手能举动。痫亦不作。", "4142": "方荫山治朱氏子。八九岁。寄食外家。以肉汁拌饭啖之。口含饭。未下咽。因疾走颠蹶。遂口噤。手足搐动。医治不效。延七日。甚至令人口含开关等药。合其口喷入。仅能开牙关。而四肢搐动。发热昏沉不语如故。脉洪滑。方至。以石膏、青黛、甘草、陈皮、南星、天麻、薄荷、猪苓、泽泻、白术、茯苓、兜铃、元参、黄芩。加姜一片服。是夜熟寐不动。唯起溺一度。热退身凉脉静。再进一服而愈。", "4143": "江应宿治一富家儿。病手足瘛疭。延至二十余日转笃。江后至。曰。此气虚也。当大补之。以参、术、归、耆、茯、芍、黄连、半夏、甘草。佐以肉桂。助参、耆之功。补脾泻肝。一饮遂觉少定。数服而愈。所以知儿病者。左脉滑大。右脉沉弱。似有似无。右手主于气。故曰气分大虚。经所谓土极似木。亢则害。承乃制。脾虚为肝所侮而风生焉。证似乎风。治风无风可治。治惊无惊可疗。治痰无痰可行。主治之法。所谓气行而痰自消。血荣而风自灭矣。见肝之病。知肝当传脾。故先实其脾土。治其未病。否则成慢脾风而危殆矣。", "4144": "丹溪治浦江郑君，年近六旬，奉养高粱。仲夏久患滞下，又犯房劳。一夕如厕，忽然昏仆，撒手遗溺，目上视，汗大出，喉如曳锯，呼吸甚微，其脉大而无伦次部位，（杨曰：将脱之象。）可畏之甚。此阴虚阳暴绝也。急令煎人参膏，且与灸气海穴，艾壮如小指，至十八壮，右手能动，又三壮，唇微动。参膏成，与一盏，至半夜后，尽三盏，眼能动。尽二斤，方能言而索粥。尽五斤而利止，十数斤全安。", "4145": "赵以德治陈敬初学士，因醮事跪拜间就倒仆，汗如雨。诊之，脉空大而虚。年当五十，新娶少妇，今又从跪拜之劳役，故阳气暴散，正与丹溪治郑义士之病同。急煎独参浓汤，连饮半日，汗止，神气稍定，手足俱纵，瘖而无声。遂于独参汤中加竹沥，开上涌之痰。次早，悲哭不已，以言慰之遂笑，至五七日无已时。此哭笑者，为阴虚而劳火动其精神，魂魄之藏气相并故耳。正《内经》所谓五精相并者，心火并于肺则喜，肺火并于肝则悲是也。加连、柏之属泻其火；更增荆沥开其闭。八日笑止手动，一月能步矣。", "4146": "杨曰：前证遗溺上视，已现绝象，脉又几几欲脱，较此条证为重，非灸法则不及救。此条证稍轻，故不必灸。", "4147": "雄按：脉既空大而虚，证复汗出如雨，虽无新娶少妇之事，亦当急固阳气，是中风门脱证治法。设遇闭证，虽有新娶少妇之事，不可捕风捉影，辄投补剂。（杨曰：至言，须切记。）徐悔堂《听雨轩杂纪》云：蔡辅宜中暑，一名医见其室有少妾，遂以为脱证，云：非独参汤不能救。家人不敢服，复邀邻医诊之。曰：暑闭耳。进益元散而愈。故医者须有定见，而察脉证以施治疗，不可胸怀成见而妄为揣度也。然病家畏虚喜补，不识病情，医者避湿推干，但迎人意，不分闭脱，温补妄施，重者辄亡，轻者成锢，是乃仁术，可如是夫？触目伤怀，言之可慨。", "4148": "俞按：前条脱证，脉大无伦，此条闭证，脉伏而微，非有确见，敢用此两路重药乎？须知脉与证宜合参。（杨曰：要诀。）如此条左瘫不言矣，而健又有痰，其得间在此，与浦江洪宅妇病疟无脉条相似。", "4149": "雄按：粗工每执肥白之人阳气必虚之说，不辨脉证，温补乱投，真杀人不以刃也。", "4150": "俞按：此治中寒，寒痰壅塞气道之药。肥人脉沉伏，无火象者可用之。若脉微细者，必加人参，实非中风药也。黄履素曰：三生饮，施于中风之寒证，妙矣。或有虚火冲逆，热痰壅塞，以致昏愦颠仆者，状类中风，乌、附非所宜服。立斋治王进士虚火妄动，挟痰而仆，急灌童溺，神思便爽。（案见江选。）予从弟履中，痰升遗溺，状类中风，亦灌以童溲而苏。（案见魏玉横《续名医类案》。）此等证候，皆火挟痰而作，断非三生饮可投，并姜汤亦不相宜也。（雄按：不但三生饮不可服，虽当归、枸杞之类，亦不宜用。余治顾听泉一案可参。）同一卒然昏愦，而所因不同，须细审之。《太平广记》载唐梁新见一朝士，诊之曰：风疾已深，请速归去。其朝士复见鄜州高医赵鄂诊之，言疾危，与梁说同，惟云只有一法，请啖消梨，不限多少，咀嚼不及，绞汁而饮。（杨曰：甘寒息风法。）到家旬日，依法治之而愈。此亦降火消痰之验也。（雄按：《资生经》亦云：凡中风，由心腹中多大热而作也。）", "4151": "俞东扶曰：仲景《伤寒论》，犹儒书之《大学》、《中庸》也，文词古奥，理法精深，自晋迄今，善用其书者，惟许学士一人而已。所存医案数十条，皆有发明，可为后学楷模。至《名医类案》，有内伤一门，所列病证，皆与伤寒无异，则其病之为伤寒、为内伤，惟在医者之能辨耳，非另有一种情形也。东垣《内外伤辨》殊不足凭，诸案皆以脉为辨。大抵内伤之脉，皆虚大无力，或微数无力，其药不外补中益气汤，甘温为主，有风寒加入表药，有停滞加入消导，有火亦加一二味凉药，无他奇巧。盖外感风寒者伤其形，故曰伤寒；劳役过度，饮食失节者伤其气，故曰内伤。此言受病之原也。及其为病，一般发热头疼，恶风恶寒，甚则痞闷谵妄，岂可就其述病原而作凭据。医者见得真，乃能分晰之曰彼是伤寒，此是内伤。亦如伤寒一门，为虚为实，为热为寒，头绪纷纭，听人审辨，焉能条分缕晰，而各立一门耶？", "4152": "吕沧洲治一人，伤寒十余日，身热而人静脉伏案。", "4153": "俞按：阅二案而知发斑、蓄血有脉伏之一候。然窃思斑未出而脉伏，理或有之；斑既透矣，何以必待化斑，脉始复耶？吴又可有脉厥之说，用承气微下则脉出，与此用白虎仿佛。但发斑脉伏，势亦可畏。上条妙在语言不乱，次条虽神昏如睡，由于误服真武，故皆凭证以治之。", "4154": "王宇泰治一人，伤寒七八日，服凉药太过，遂变身凉，手足厥冷，通身黑斑，惟心头尚温，诊其六脉沉细，昏沉不知人事，并不能言，状如尸厥。遂用人参三白汤加熟附子半枚，干姜二钱，服下一时许，斑色渐红，手足渐暖而苏。然黑斑有因余热不清者，又当以黄连解毒、竹叶石膏汤调之而愈。", "4155": "云间怀抱奇治一妇，夏月饮火酒，烦热面赤发斑，诊其脉绝无。怀曰：此火郁而热极，用栀豉汤加葛根、厚朴、黄连清之，斑大出而脉遂见。（此与吕沧洲案相似。雄按：葛根用得最妙，解酒透斑，一举两得。厚朴尚可商。）又治一人，伤寒过经不解，遍体黑斑，唇口焦枯，脉大，便结，以三黄石膏汤饮之痊。（此可与王宇泰案合观之。）又治一妇，热入血室后发斑点，以小柴胡汤加生地获愈。又治一人，身热发斑，胃有停滞，胀闷不堪，用枳朴消导药而斑出热退。", "4156": "俞按：阅抱奇数案，益信朱奉议所云：凡见斑不可专以斑治，须察脉之浮沉，病之虚实，而分别用药。真至言也。", "4157": "俞惺斋治叶念劬身热发斑不透，群用提斑药无效，俞见其吐涎不已，手足软不能动，脉大无力，是内伤发斑，用补中益气汤而愈。又治张素安室，身热足冷，目肿便溏，发斑不透，脉沉细无力，乃阴证发斑，用真武汤加人参而愈。此效法海藏与《准绳》之治法也。虽然，舌不燥，神不昏，故可用温补耳。若夏秋时行疫病，又多以大黄速下之而斑出者，盖内邪之壅塞得通而斑出，（雄按：初治得法，邪不壅塞则不发斑。）与虚寒之得温补以鼓舞而斑出，同一理也。（雄按：初治不误，何致发斑？不必温补鼓舞矣。杨曰：语语精当，而孟英注语尤精。）又生平见蓝斑二人，一则脉细神昏，辞不治。其蓝斑之大者如棋子，发烂而死。（雄按：此即玳瑁瘟也。）一女人蓝斑色如翠羽，咯血齿衄，舌红不干，神不昏，犹可扶而登圊，用犀角地黄汤，间以大黄微下之，后竟愈。", "4158": "俞按：此条以伤寒而变肠痈，虽不多见，亦不可不知。观其所告之言，两句出仲景《伤寒论》，两句出高阳生《脉诀》，因思自明以前皆用此诀，何近贤之痛诋不堪耶！", "4159": "怀抱奇治一人，积劳后感寒发热，医者好用古方，竟以麻黄汤进，目赤鼻衄，痰中带血，继以小柴胡汤，舌干乏津。怀诊之，脉虚数无力，乃劳倦而兼阴虚候也。（杨曰：伤寒无虚数无力之脉。）设投热药，能不动血而竭其液耶？连进地黄汤三剂，血止，神尚未清，用生脉散加当归、枣仁、茯神、远志，神虽安，舌仍不生津。乃曰：肾主五液，而肺为生化之源，滋阴益气，两不见效，何也？细思之，因悟麻黄性不内守，服之而竟无汗，徒伤其阴，口鼻虽见血，药性终未发泄，故津液不行，仍以生脉散加葛根、陈皮引之，遂得微汗，舌果津生，后以归脾汤、六味丸而痊。", "4160": "雄按：萧建廷秋月患感于归安，医进麻黄汤，汗透衣衾，奄奄一息。改用参、耆、术、附等药，汗虽止而舌燥无津，神昏沉寐。所亲顾味吾亟买棹送归，延余视之，脉来细软，睛赤唇焦，小溲全无，皮肤燥热，不食不便，懒语音低，灌以大剂西洋参、生地、麦冬、杞子、甘草、葳蕤、当归、花粉、藕汁、童溺等药，三剂神渐醒而舌润溺行，略啜稀粥。药不更方，旬日后身热始净，音亦朗爽，粥食渐加。半月后更衣而脉和，月余能下榻矣。复于方内加熟地、天冬、牛膝、仙灵脾，令熬膏服之而健。", "4161": "节庵治一壮年，夏间劳役后食冷物，夜卧遗精，遂发热痞闷，至晚头额时痛，两足不温。医不知头痛为火热上乘，足冷为脾气不下，误认外感夹阴，而与五积散汗之，则烦躁口干，目赤便秘。明日便与承气下之，但有黄水，身强如痉，烦躁转剧，腹胀喘急，舌苔黄色，已六七日矣。诊其脉六七至而弦劲。急以黄龙汤，下黑物甚多，腹胀顿宽，躁热顿减，但夜间仍热，舌苔未净。更与解毒汤合生脉散加生地，二剂热除，平调月余而安。", "4162": "慎柔和尚治薛理还仆，远行忍饥，又相殴脱力，时五月初，遂发热谵语，服过补中益气及五苓数剂不效。诊之，六脉俱无，乍有则甚细，外证则面赤口碎。一医曰：阳病见阴脉，证在死例。慎柔曰：当以阳虚从脉舍证治之。用附子理中汤冷服，二帖脉稍见，四帖则脉有神，而口碎愈矣。六帖则脉如常，但谵语未已。慎柔曰：脉气已完复，而谵语不休者，胃有燥矢。以猪胆汁导之，果下燥结，谵语遂平。", "4163": "张路玉治范求先患伤寒，恶寒三日不止，已服过发散药二剂，至第七日，躁扰不宁，六脉不至，手足厥逆。张诊之，独左寸厥厥动摇，知是欲作战汗之候，令勿服药，但与热姜汤助其作汗，若误服药，必热不止。果如其言而愈。", "4164": "雄按：温热病之谵语，尚有心阳素扰之神不安者，热邪烁营之欲逆传者，痰因热动而蒙蔽其清明者，殆不止俞氏所云之三路也。至虚实寒热之的据，古人成案皆以脉为断。然伤寒温热，不比内伤杂证，往往脉难全恃，必须详审舌苔，按其胸腹，诘其二便，汇而参之，庶可得其真谛也。此古人隐而未露之秘，学者尤宜究心焉。", "4165": "俞东扶曰：伤寒为大病，治法最繁，言之不胜言也。必熟读仲景书，再遍读后贤诸书，临证方有把握。仲景为叔和编次，或有差误，而聊摄注解殊觉稳当，续注者张卿子、王三阳、唐不严、沈亮宸、张兼善、张隐庵、林北海诸人，总不越其范围。自方、程、喻三家，各以己意布置，而仲景原文，从此遂无定局。三注互有短长，大约程不及方，方不及喻。然喻注太阳经分三大纲，以误汗、误下、结胸、蓄血、发黄等证，分隶两门，似乎界限井然，谁知以之治病，全用不著。盖病初起时，必将营卫分别，过半月后，殊难追溯。何以指其此由中风传变；此由伤寒传变；此由风寒两伤营卫传变哉？传变之证，虚实寒热，犹恐模糊，又要恰合三纲，此能言而不能行者也。（杨曰：此论甚通达。然余所见传变诸证，皆系伤寒。至中风一证，则或半月或一月仍是本证，并不传变，殆因其汗出不已，故不能郁热而传变耶。）魏柏乡、周禹载、沈目南等俱宗之，亦徒悦服于空言，而未尝以之试验耳。卢子由《疏钞金錍》，不派三纲，添出气化、形层、标本、四大等说，愈觉支离，愈入迷网。其藏结诸案，几如牛鬼蛇神。柯韵伯将两家并讥，不亦宜乎！至《伤寒论翼》，固属出奇高论，所谓读书具只眼，不蹈前人窠臼者，微嫌其论六经尽翻前案，欲立异以惊人，究属纸上谈兵也。从来注《伤寒论》者，俱是顺文注释，若遇不可通处，或敷衍混过，或穿凿文饰，（杨曰：说尽著书家通病。）既不明道理之是非，何以为临证之运用？惟程扶生经注，颇明白易晓，然亦不敢直指原文之差误。柯氏始敢放胆删改，虽觉僭妄，颇堪嘉惠后学，而以方名编次，又是一局。徐洄溪《伤寒类方》，实宗其式，简洁明净，以少许胜人多许，较之程郊倩之繁词，一可当百。沈尧封《伤寒论读》，亦以少胜多者，用六气为提纲，将平脉辨脉编入其中，别开生面。其论大青龙汤，发前入所未发，一洗风寒两伤营卫之陋说。（雄按：尤在泾已论之。）《左传》云：拔戟自成一队。此书似之。而删改本文，非其志也。予细绎柯氏删改处，万不及钦定《医宗金鉴·伤寒论》之精当，先刊仲景原文，另立正误存疑二篇，应改者注小字于旁，可删者摘诸条于后，是非判然，智愚皆晓，真苦海之慈航，昏衢之巨烛也。江西舒诏《伤寒集注》，（杨曰：舒注甚缪，专用温燥，不足为训。）大半斥为伪撰，并取数方痛加诋毁，别拟方以易之，此亦救世婆心，特未免于狂妄。以视汪琥将阴阳二候分为二编，各补后贤之方，其意均欲使初学者不泥古方以害人，而汪犹拘谨，舒则放纵矣。此外注家尚多，如钱氏《溯源集》、陈明伯《集注》，尚有发明，其余碌碌因人，殊不足道。（雄按：王坤载之经注明白，入理最深；张路玉之剔清温热，迥出诸家；又倪冲之集成聊摄、赵嗣真、虞纯一、王三阳、张兼善、王宇泰、卢子繇、张卿子、林观子、程郊倩、沈亮宸、喻嘉言、王子律、张隐庵十四家精义，为《伤寒汇言》，亦可观也。）兹举夫各立格局，各竖议论者，叙述于上，以便同志者之诵习焉。要之读书与治病，时合时离，古法与今方，有因有革，善读书斯善治病，非读死书之谓也；用古法须用今方，非执板方之谓也。专读仲景书，不读后贤书，譬之井田封建，周礼周官，不足以治汉唐之天下也，仅读后贤书，不读仲景书，譬之五言七律，昆体宫词，不可以代三百之雅颂也。故吴缓《蕴要》、节庵《六书》、王宇泰《伤寒准绳》、张石顽《伤寒绪论》，俱有裨于后人，即有功于仲景，学者诚能以所引诸书广为探索，则临证了如指掌矣。", "4166": "林北海治一人，夏月远行劳倦，归患热证。下痢脓血，身如燔炭，舌黑而燥，夜多讝语。曰：此阳明病也，不当作痢治。但脉已散乱，忽有忽无，状类虾游，殆不可治。其家固请用药。林曰：阳明热甚，当急解其毒，在古人亦必急下之以存津液。然是证之源，由于劳倦，阳邪内灼，脉已无阴，若骤下之，则毒留而阴绝，死不治矣。勉与养阴，以冀万一。用熟地一两，生地、麦冬、归、芍、甘草、枸杞佐之。戒其家曰：汗至乃活。服后热不减，而讝语益狂悖，但血痢不下，身有微汗，略出即止。林诊之，脉已接续分明，洪数鼓指。喜曰：今生矣。仍用前方，去生地加萸肉、丹皮、山药、枣仁。连服六帖，谵妄昏热不减，其家欲求更方，林执不可。又二日，诊其脉始敛而圆，乃用四顺清凉饮子，加熟地一两，大黄五钱，下黑矢而诸证顿愈。越二日，忽复狂讝发热，喘急口渴，举家惶惑，谓今必死矣。林笑曰：岂忘吾言乎？得汗即活矣。此缘下后阴气已至，而无以鼓动之，则营卫不洽，汗无从生，不汗则虚邪不得外达，故内沸而复也。病从阳入，必从阳解，遂投白术一两，归、芍、干姜各三钱，甘草一钱。尽剂汗如注，酣卧至晓，病良已。", "4167": "俞按：此证疑难在于初末。初时脉类虾游，若援景岳证实脉虚之说，而用参、术、姜、附，则必死；末后狂热复发，若引又可余邪注胃之说，而用白虎、承气，亦必危。此案见解用药俱佳，然其得生处，在于养阴而血痢顿止，脉即应指耳。中间连服六帖，讝妄昏热不减，幸不见手足厥冷，尤幸不至声瘖不语，绝谷不食也，则以脉之敛而圆故也。但白术一两，干姜三钱，以治狂热喘渴，殊难轻试。", "4168": "又云：温热病最怕发热不退，及痉厥昏蒙，更有无端而发晕，（雄按：此却不妨。）及神清而忽间以狂言者，往往变生不测。遇此等证，最能惑人，不比阳证阴脉，阳缩舌卷，撮空见鬼者，易烛其危也。要诀在辨明虚实，辨得真，方可下手，然必非刘河间、吴又可之法所能救。平素精研《伤寒论》者，庶有妙旨。至如叶氏之论温热，有邪传心包，震动君主，神明欲迷，弥漫之邪，攻之不解，清窍既蒙，络内亦痹，豁痰降火无效者，用局方至宝丹，或紫雪，或牛黄丸，宗喻氏芳香逐秽宣窍之说，真足超越前贤，且不蹈用重药者一匙偶误，覆水难收之弊也。此翁聪明，诚不可及。", "4169": "壶仙翁治张文学病时疫，他医诊其脉，两手俱伏，曰：阳证见阴不治。欲用阳毒升麻汤升提之。壶曰：此风热之极，火盛则伏，非阴脉也，升之则死矣。用连翘凉膈之剂，一服而解。", "4170": "俞按：此条是瘟疫病以证为则，勿专以脉为凭之一据。", "4171": "雄按：疫证将欲战汗之时，其脉多伏。即勘杂证，如痛厥、霍乱、食滞、痰凝，凡气道阻塞之暴病，脉亦多伏，俱宜以证为则，岂仅瘟疫不可专以脉为凭耶！粗工不知此理，乱投温补，因而致毙者多矣。", "4172": "孙文垣有仆孙安，远行途次，食面三碗，劳倦感疫，又加面伤，表里皆热，昏闷谵语，头痛身痛腹痛。医以遇仙丹下之，大便泻三四十行，邪因陷下而为挟热下利之候，舌沉香色，额疼口渴，烦闷昏愦。脉左弦数，右洪数，但不充指，知为误下坏证。以柴胡、石膏各三钱，白芍、黄芩、竹茹、葛根各一钱，花粉、甘草各五分，山栀、枳实各七分，葱白五茎，煎服。后半夜吐蛔一条，稍得睡；次早大便犹泻二次，呕吐酸水，腹犹痛。改用小柴胡加滑石、竹茹，夜热甚，（雄按：内有姜也。）与丝瓜汁一碗，饮既神顿清爽，少顷药力过时，烦热如前。再以丝瓜汁一大碗进之，即大发战。孙谓此非寒战，乃作汗之征耳。不移时，汗果出而热依然。因忆《活人书》云：再三汗下热不退，以人参白虎汤加苍术一钱如神。迹此再加元参、升麻、柴胡、白芍、黄连。饮后身上发斑，先发者紫，后发者红，中夜后乃得睡而热散，斑寻退去，腹中微痛，肠鸣口渴，右脉尚滑，左脉已和。再与竹叶石膏汤加白芍、苍术。服后睡安，腹仍微痛。用柴胡、白芍各一钱，人参、黄芩、橘皮、半夏各六分，甘草三分，乌梅一个。腹痛渐减而愈，惟两胯痛不能转动，此大病后汗多而筋失养之故。用参、耆、白芍、枸杞、薏苡、木瓜、熟地、归身、黄柏、牛膝、桑寄生调养全安。", "4173": "又治张孝廉患疫，头大如斗，不见项，唇垂及乳，（雄按：此恐言之过甚。）色如紫肝，昏愦不知人事，见者骇退。诊其脉浮弦而数。初以柴胡一两，黄芩、元参各三钱，薄荷、连翘、葛根各二钱，甘草一钱。（杨曰：何不用普济消毒饮。）服三剂，寒热退，脉转洪大，知其传于阳明也，改以贯众一两，葛根、花粉各三钱，甘草一钱，黑豆四十九粒，三剂而愈。", "4174": "丁汉奇素嗜酒，腊初醉后，夜行二里许，次日咳嗽身微热，两目肿，自用羌、芷、芎、芩等药，颐皆肿，又进一剂，肿至喉肩胸膛，咳频不爽，气息微急，喉有痰声，其肿如匏，按之热痛，目赤如鸠，而便泻足冷。医谓大头瘟，而用普济消毒饮子。药未服，沈尧封诊之，六脉细数，右更细软，略一重按即无。曰：此虚阳上攻，断勿作大头天行治。病者云：内子归宁，绝欲两月矣，何虚之有？沈曰：唇上黑痕一条，如干焦状，舌白如傅粉，舌尖亦白不赤，乃虚寒之确据，况泄泻足冷，右脉软微，断非风热之象，况无痞闷烦热，躁渴不安之候，岂有外肿如此，而内里安帖如平人者乎？其为虚证，更何疑焉？遂以菟丝、枸杞、牛膝、茯苓、益智、龙骨。一剂而肿定，二剂而肿渐退，右脉稍起，唇上黑痕亦退，但舌仍白厚，伸舌即颤掉，手亦微振。乃用六君加沉香而肿大退，目赤亦减，嗽缓痰稀，舌上白苔去大半矣。次日再诊，右脉应指不微细，重按仍觉空豁，肝气时动，两颧常赤，口反微渴。复用参、苓、杞、芍、橘红、龙骨、沙蒺，补元益肾敛肝而全愈。", "4175": "俞东扶曰：张洁古云动而得之者为中暍，为阳证；静而得之者为中暑，为阴证。以「暑」、「暍」二字析为两项，殊属不然。夫夏之暑暍，犹冬之寒冷也。若指暍为阳，指暑为阴，亦将派冷作阳，派寒作阴耶！《内经》云：先夏至日者为病温，后夏至日者为病暑。明以时令别其病名耳。病暑之有阴有阳，一如伤寒之有阴有阳，大顺散、冷香饮之类，实为纳凉饮冷，因避暑而受寒，固暑月之阴证也，非中暑也。所以罗谦甫治参政商公泄泻、完颜小将军斑衄二案，俱用热药，俱不名之曰中暑。吴球治暑月远行之人，直曰中寒，（三案俱见江选。）恐后世误以热药治暑，乃举病因以称之，诚为名正言顺。故以动静分阴阳则可，以暑暍分阴阳则不可，惟以脉证辨阴阳斯可矣。近世叶氏治暑，每用滑石、芦根、通草、白蔻仁、杏仁等药，以暑气从鼻而吸入，必先犯肺，故用轻清之药，专治上焦；其西瓜翠衣、鲜荷叶、鲜莲子、绿豆皮、丝瓜叶、竹叶、银花露等，皆取轻清以解暑邪之上蒙空窍，不犯中下二焦，殊有巧思。盖暑病必究三焦，非比伤寒，若来复丹、大顺散，案中偶一见之，又足征暑月阳证居多，阴证原少耳。", "4176": "俞东扶曰：古人治湿病案，殊无高论奇方，惟《临证指南》佳案甚多，良足私淑。其除气分之湿，用滑石、白蔻仁、杏仁、半夏、厚朴、栝蒌皮为主，有热则加竹叶、连翘、芦根等，全取轻清之品，走气道以除湿。若湿热甚而舌白目黄，口渴溺赤，用桂枝木、泽泻、猪苓、滑石、茯苓皮、寒水石、生白术、茵陈，此从桂苓甘露饮加减。湿热作痞，神识如蒙，用人参、芩、连、枳实、生干姜、生白芍，此从泻心汤加减。若脘中阻痛，大便不爽，用豆豉、枳实、黄连、姜汁、苓、半，热轻则去连加郁金、橘红、薏苡、杏仁，此湿伤气痹治法。热甚则用黄连、生术、厚朴、橘白、淡生姜渣、酒煨大黄，水法丸服，此治气阻不爽，治腑宜通法。湿伤脾阳腹膨，用五苓散、二术膏。湿热横渍脉腠腹满，用小温中丸，以及脘痞便溏之用苓桂术甘汤，吞酸形寒之用苓姜术桂汤，虽皆古人成法，而信手拈来，无不吻合。湿温身热神昏，用犀角、元参、连翘、石菖蒲、银花、赤豆皮煎送至宝丹，乃清热通窍，芳香逐秽法。更奇者，湿温之头胀耳聋，呃忒鼻衄，舌色带白，咽喉欲闭，谓邪阻上窍空虚之所，非苦寒直入胃中可治，而用连翘、牛蒡、银花、马勃、射干、金汁，此俗人梦想不到者也。不食不寐，腹痛便窒，脉迟小涩，谓由平素嗜酒少谷，湿积伤阳，寒湿浊阴，鸠聚为痛，而用炒黑生附子、炒黑川椒、生淡干姜、葱白，调入猪胆汁，此加味白通汤，亦神奇不可思议者也。更有嗜酒人胸满不饥，三焦皆闭，二便不通，用半硫丸。又有病中啖厚味者，肠胃滞，虽下而留湿未解，肛门坠痛，胃不喜食，舌上白腐，用平胃散去甘草，加人参、炮姜、炒黑生附。此二条不因酒肉认作湿热，竟以苦辛温药通阳劫湿，尤觉高超。至如阳伤痿弱，有湿麻痹，虽痔血而用姜、附、茯苓、生术。舌白身痛，足跗浮肿，太谿穴水流如注，谓湿邪伏于足少阴，而用鹿茸、淡附子、草果、茯苓、菟丝以温煦阳气，均非浅识所能步武。湿久脾阳消乏，肾真亦惫，中年未育子，用茯、菟、苍术、韭子、大茴、鹿茸、附子、芦巴、故纸、赤石脂，仿安肾丸法，治病调元，化为合璧，益有观止之叹。湿门得此诸案，方法洵云全备。", "4177": "俞按：夜热脉数，的系阴虚，因其脉伏且牢，浮取不应，故用升阳散火得效，仍以阴药收功。然阴药用六味地黄及二地、二冬必不效，妙在芎、归合知、柏，及从治之炒干姜也。", "4178": "周慎斋治一妇，五月间身凉，自言内热，水泻二月，一日数次，小水绝无，自言上热极，下冻死，腰腿足俱冷，腹痛如冰，或一时发热不欲近衣，或一时怕冷遍身尽然，面目红肿，药之不愈，六脉洪大，此伏火也。火性炎上，故上热下冷耳。用四物汤加柴、葛、升麻、甘草、芩、栀、黄柏二帖，小水行泻止，复发牙疼，三日不愈，用黄耆建中汤加附子，一服愈。", "4179": "一人七月病上辰昏晕，下午不言昏睡，一日不醒，人叫不应，身凉不食，不寒不热，皆曰阴证。议用理中、四逆。慎斋诊其脉，沉小带伏，曰：内有火邪也，故小便一二日不解，延至夜不醒。其妻曰：前日房事，如何是火？周曰：夜有房事，内虚又劳热甚。（杨曰：恐有脱遗。）夫干热从虚入，则阴气将绝，以水救之则可。取冷水一桶，饮至五碗，病者曰渴甚，饮至七碗，大汗如雨，病者曰饿，啜粥一碗，用补中益气汤加炮姜、泽泻温中，泻冷水而愈。", "4180": "一妇六月卒死，遍体俱冷，无汗，六脉俱伏，三日不醒，但气未绝耳。众用理中、四逆，亦不能纳。四日后，慎斋诊之，仍无脉，念人一二日无脉立死，今三日不死，此脉伏也，热极似寒耳。用水湿青布放身上，一时身热，遂灌冷水五六碗，反言渴，又一碗，大汗出。后用补中益气加黄柏十帖愈。", "4181": "庞从善治著作王公苹泄利，诊之曰：两手三部中得脾脉，浮而弦，浮主风，弦主湿，（杨曰：湿不能弦。）又弦为肝脉，病因风湿外伤，致肝木刑于脾土，而为洞泄，又名飧泄也。《内经》云：春伤于风，邪气留连，乃为洞泄。又云：春伤于风，夏生飧泄。其利下物主浑白而完出是也。遂以五泄丸煎服之，数服而瘥。王公曰：从善年未四十，亦医之妙选。曾撰《脉法鍖源论》一部，共二十篇，示愚观之，诚得叔和未尽之趣者也。", "4182": "俞按：《医说会编》注云：百会属督脉，居巅顶，为天之中，是主一身之气者。元气下脱，脾胃无凭，所以泄泻，是谓阁不得地。经云下者上之，所以灸百会穴愈者，使天之气复健行，而脾土得以凭之耳，《铜人经》谓百会灸脱肛，其义一也。余谓仲景《伤寒论》已言之矣。其曰：少阴病下痢，脉微涩，呕而汗出，必数更衣，反少者，当温其上灸之。「上」字即指百会穴，何待子厚始悟出耶！及读《资生经》云：旧传有人年老而颜如童子者，盖每岁以鼠粪灸脐中神阙穴一壮故也。余尝久患溏利，一夕灸三七壮，则次日不如厕，连数夕灸，则数日不如厕，足见经言主泄利不止之验，是又与灸百会穴同一捷法。", "4183": "雄按：陷者举之，不过治泄泻之一法耳。有某妇者，年三十余，嫠居数载，体素羸弱，月事按年一行，仲夏偶患泻，医知其虚也，即进六君子加味，反腹痛而下白垢，以为寒甚也，因灸之，痛利加剧，改用升阳法，遂呕吐痰嗽，不寐不饥，且利时觉腰内有冷风飒飒，于是理中、肾气、四神、乌梅等丸，及余粮、石脂，遍试不效。至季秋，乃父金某浼许某延余诊。脉甚弦涩，暮热晡寒，舌色鲜红，苔白口苦，小溲短少，吐水极酸。此由情志不舒，木乘土位，治不中窾，煽动内风。予橘、半、苓、茹、芩、连、柏、苡、木瓜、芍药为方，服后二便如火，呕嗽腹痛，腰风皆止。三剂后复诊：弦涩渐退，苔化知饥，大便犹溏，日仅一二行。病者以为遇仙，乃以养胃和肝善其后。又治高又苏令姊，年十六岁，经甫行一次，遂患泻而月事不至，形日瘦，愈疑成损，妄通其血，而痛泻益剧，饮食不思，改用滋填亦无效。余诊脉微弱略弦，曰此歇经也，泄泻乃脾弱耳。予参、耆、甘、芍、桂枝、山药而愈。", "4184": "俞东扶曰：因他病而不食者，不在此例。夫人身以胃气为本，经年累月，粥饭全废，似无不死者。然余曾见两家闺女，皆十余岁，皆无病，渐渐厌恶粥饭，每日略啖菱、栗、枣、橘、芝麻、落花生、薄脆豆腐干之类，或饮酒一二杯，或腐浆数口而止，其父母甚忧之。余视其形色不变，起居如常，六脉均平，乃许以无事，亦不处方，后皆出嫁。盖谷肉果菜均以养生，去谷而犹存三项，与绝食者原不同也。", "4185": "雄按：此案但言夏月患疟，而不详脉证，所用升散之药五种，苦寒之药三种，虽为金坛得意之作，余颇不以为然。后人不审题旨，辄钞墨卷，贻误良多。邹润安云：据金坛云：是使阴阳相离，非使邪与阴阳相离也。使邪与阴阳相离犹可言，人身阴阳，可使之相离乎？斯为先得我心。余治门人张笏山之弟，疟来痞闷欲死，以枳桔汤加柴、芩、橘、半，一饮而愈，是调其升降而使邪与阴阳相离也。", "4186": "僧慎柔治淮安客，年三旬外，季夏患瘅疟，但热不寒，连日发于午后，热躁谵语，至次日天明才退。数日后忽腹痛，昼夜无间，勺水不进，呼号欲绝，遇疟发时即厥去，医治不效，求慎柔诊之。脉弦细而软，乃谓弦细为虚为暑，而软为湿。盖暑邪成疟，湿热乘虚内陷而腹痛。用酒炒白芍一两，炙甘草一钱五分，水煎调下天水散五钱。一剂痛如失，次日疟亦不发。", "4187": "雄按：湿热乘虚内陷而腹痛，亦非戊巳所宜投。脉象弦细而软，固属暑湿，其腹痛，恐兼肝木凌脾，故此药一剂即瘳也。", "4188": "高果哉治张习可，五月间受微雨及风冷，遂患三疟，疟发于暮，热甚于夜，至九月中，诊得六脉虚数。此阴虚而暑入阴分，最难治。当先升举其阳，用生地、川芎、归、芍、炙草、知母、干姜、干葛、升、柴、姜、枣煎服。四剂后加首乌、人参。又定丸方：首乌四两，生地三两，参、术、当归、龟板、猪苓、知母、黄芩、山楂各二两，柴胡一两六钱，牛膝一两五钱，干姜、穿山甲各一两，甘草五钱，活鳖一个，入砂仁末二两，煮取鳖肉，同药捣匀烘干，其骨亦炙为末加入，荷叶汤法丸，服完全愈。", "4189": "雄按：此条脉证俱不载明，不知疟属何因，难以垂训。观其用药，似系疟久邪入厥阴经者。然老姜用至每剂一两，殊为可议。至用桃叶，则未免惑于世俗之论，尤可陋矣。", "4190": "沈尧封治一张姓少年，春间患寒热如疟，始服发散，继服养阴，已愈矣。越数日疟又作，且兼白浊不止，服小柴胡加首乌、生地、丹皮、萆薢等不应。又数日，寒热渐重，不能起坐，口渴烦躁，舌赤唇焦，服白虎汤而热益甚，发晕昏沉几死，热气冲开二三尺，两目赤肿，目眵胶闭，舌红且干，唇焦面赤，两足如烙，惟大便泄泻。沈诊之，脉虚而软。遂用人参二钱，熟附子三钱，茯苓五钱，白芍一钱五分。一剂而热少定，连服旬余，惟以牡蛎、牛膝、枸杞、生地出入加减，粥进热退，病去六七。忽然腹痛大作，连泻二三十次，烦渴又作，懊𢙐迷闷不安，举家骇泣。沈曰：无恐，此久积之寒饮，因脾得参、附之力以运动之，饮乃大下也。（雄按：所加之牛膝、枸杞、生地未尽善美，宜以薏苡、泽泻、橘、半之类佐之为妥。）复用附子五钱，干姜二钱，芩、芍、炙草，数剂而安。又用参、术平补全愈。", "4191": "俞东扶曰：古云疟疾日作者轻，间日者重，此不可拘。若日作而寒热之时短，势又不甚，则诚轻，苟势甚而时又长，反不如间日者尚有休息之一日也，何可云轻？惟疟发渐早为易痊，渐晏为末止，乃一定之局。间有不一定者，如发渐早而热退不早，则其寒热加长矣，愈长则病愈进，不得引《内经》「其气上行九日出于缺盆之中」为据也。（雄按：经文难泥，病机甚活，有疟至将愈之时，其发陡重，大寒大战，大热大渴，遂大汗而解，其疟遂已者；有一日两发或数发，而其疟遂愈者。）如发渐晏而热退不晏，则其寒热渐短矣，愈短则病愈衰，不得引昔贤自阳之阴者难愈为据也。（雄按：发渐晏、退渐早，则邪气渐衰，此疟愈之常也。）隔二日曰三阴疟，较诸疟为最重。有二三年未愈者，（雄按：皆初治之误，或口腹不慎所致也。）亦有二三月即愈者。（雄按：初治得法，何致延及二三月而始愈？俞氏之意谓二三月即愈，似是喜出望外之词，盖亦未知治疟之法也。只看其寒热之轻重短长，以辨病之浅深；然三阴疟无骤死之理，反不比日作与间日者有骤死之人也。雄按：疟有经病，有府病，有藏病，治不如法，轻者重而重者死矣。间二日而作者，藏病少而府病尤少，经病络病为多，故骤死者罕耳。）此皆就余生平所验而言之。大抵疟疾因风寒者，多初起无汗，必该发散，羌、苏、防、葛之类；若有汗，则用桂枝、白芍；兼见热象，则桂枝柴胡各半汤；深秋初冬，寒重无汗，口不渴，脉不数者，麻黄汤小剂用之，兼见热象，则加石膏，即越婢法。（雄按：此正疟之治法。虚人可用建中汤加减。能食者，饱啖羊肉酒饭，亦能汗解而愈。今人以此法概治诸疟，遂致轻者延绵，重者变证蜂起，殊可叹矣。）表证而挟里证，有痰食者加朴、半、麦芽之类，向有无痰不成疟、无食不成疟二说，皆不可废。疟疾因于暑者，必热多寒少，有汗口渴，桂枝白虎汤、竹叶石膏汤酌用。暑兼湿，则苍术白虎汤、桂苓甘露饮酌用。以上皆疟疾之表证药，而疟发每多呕逆痞闷，又须以草果、知母、藿香、枳、朴、白蔻、姜汁、干姜、竹茹、芦根等，审其寒热加入，亦统属疟疾之实证药也。（雄按：外感为疟，原不外乎风寒暑湿，里证亦不外乎「痰食」二者。）但疟疾本是感证，不过轻于伤寒耳。故伤寒有五，疟亦有五。今世正伤寒少，温热暑湿之病多，疟亦尔也。故善于治温热暑湿者，始知治疟之全体也。若素虚人，或病后、疮后、产后，不可一例论。（雄按：虽如此说，然亦未尝无实证。）古云：无汗要有汗，散邪为主；（雄按：取汗之法，不止发散一端。）有汗要无汗，扶正为先。（雄按：汗多者，不独虚也，未可专以扶正为法。）汗之一端，尚且严为分别，岂有虚证虚脉而可虚其虚乎？补中益气汤、人参养营汤、参茸归桂饮、理中、八味、真武等方，择其脉证相合者用之，盖温补温通、补脾补肾，方义微别耳。惟是大虚必挟寒，（雄按：阳分大虚必挟寒，阴分大虚必挟热，况温热之邪，尤易伤阴那。）昔贤治久疟，用补者少加附子，其效如神，故虚疟之用桂、附，与三阴疟之用丁香，俱有奇功可据也。（雄按：不可执死法以治活病，误用而致奇祸者不少也。）然或虚疟不见寒证，却有热象，脉弦数或洪数者，势难投以温药，（雄按：邪分寒热，虚别阴阳，何必虚者皆属于寒？）既见热象，而脉至弦洪且数矣，尚不知热邪伤阴，而为此无可奈何之言，曰势难投温，殊可笑也，则甘寒生津，如蔗浆、秋露水、梨、藕汁；壮水制火，如二地、二冬、阿胶以及生脉散、何人饮，又堪供我驱策矣。复有虚实参半之热证，则小柴胡原方、人参白虎汤、半夏泻心汤、黄连汤可以奏功；若虚实参半而寒者较易治，毋庸再赘。（雄按：昔贤论疟，多主风寒，今世之疟，多属时邪，故觉寒易治，而以热为难治矣。）但「寒热」二字，全在凭之以脉，纵使热多，甚至但热无寒，而脉细软者，当以虚治，不得轻用白虎汤。（雄按：脉细软者，固不得轻用白虎，然壮火食气，竟有热极而脉反沉涩细软者，盖暑伤气，脉多微弱，岂可遽认为虚乎？）寒多甚至但寒无热，而脉洪实者，当以热治，不得便用姜、桂，此妙诀也。夜疟皆云邪入血分，当用血药以提其邪，说固可通，景岳归柴饮、鼓峰香红饮，二方俱佳。然初在夜，嗣后不早不晏，始终发于夜者是也。设趱前渐近日昃，缩后已至日出，皆不得谓之夜疟矣。禁法与截法不同，禁是外为镇厌，其法甚多，效者亦多，即祝由之意也。然轻者效，重者不效，比之打仗，掠其残兵耳。设用药中綮，何借此乎？截是服药以截止，常山最有效验。截止后须谨慎调摄，否则复发增重，用砒者亦然。然砒必大吐，恐至伤人。（雄按：邪势方张，妄行劫截，虽能调摄，病必反加，不但砒恐伤人也。）轻者原不须截，欲截则露姜饮最佳，虚加人参尤妙。缪仲淳谓疟由于暑，暑得露而解也。（雄按：秋后白露降，始可取也。）若秋前露自地升，露药无谓。余考古法，露忌著火，叶氏用秋露煎药非也。（雄按：截者，劫去其病之谓也。）欲行劫截，亦须审其病属何因，露姜饮能截之疟，必有露姜饮能截之证据，并非露姜饮能截一切之疟也。今云截疟则露姜饮最佳，是囫囵吞枣矣。举世医家多犯此病，如徐宗可《金匮注》云：小儿未纳谷食者，以冰糖煎浓汤饮之极效。盖未纳谷食之儿，中虚可知，一味冰糖，即建中之意，又不苦口，胜于强灌苦汤而伤其脾胃也。世人不察，遂以冰糖为止疟之药。闻其疟久，竟不察其中之虚实，邪之盛衰，概用冰糖为引，邪衰中虚者，未始不效，设痰湿暑热之邪，失于清解而延久不愈者，服之能不更为邪气竖帜乎？露姜饮误用，其祸尤烈，叶氏《景岳发挥》详言其弊矣。故医者用方，必先辨明证因也。外有胆汁二姜丸，蒜烧醨、草果蒸参、常山炒参诸方，以及景岳云小柴胡汤加常山二钱，截疟如神，皆在乎人之善用耳。（雄按：善用无他秘诀，在乎辨证明白耳。）疟母必用鳖甲煎丸，丸中除去人参为大谬，或以参汤送之，汤力已过，丸力才行，譬如悍卒无良将统驭，步伐岂能整齐？（雄按：此论深得用药之理。）又此丸偏于寒削，若阳虚者宜用仲淳之疟母丸为妙。三疟虽属三阴，亦只要辨明寒热虚实，而应以温凉补泻。（雄按：此论极是，诸病皆宜如是。）若用阳经轻浅之方治之无益，必以仲景治三阴之法为根蒂，似属高谈，实门外汉也。总之，医者多读书，多阅历，病者能调摄，能谨慎，斯四难并，二美合矣。", "4192": "叶先生名仪，尝与丹溪俱从白云许先生学，其记病云：岁癸酉秋八月，余病滞下，痛作绝不饮食，既而困惫不能起床，乃以衽席及荐阙其中而听其自下焉。时朱彦修氏客城中，以友生之好，日过视余，饮余药，但日服而病日增，朋游哗然议之，彦修弗顾也。浃旬病益甚，痰窒咽如絮，呻吟亘昼夜。私自虞，与二子诀，二子哭，道路相传，谓余死矣。彦修闻之曰：吁！此必传者之妄也，翼日天甫明，来视余脉，煮小承气汤饮余，药下咽，觉所苦者自上下，凡一再行，意冷然。越日遂进粥，渐愈。朋游因问彦修治法，答曰：前诊气口脉虚，形虽实而面黄稍白，此由平素与人接言多，多言者中气虚。又其人务竟已事，恒失之饥而伤之饱，伤于饱其流为积，积之久为此证。夫滞下之病，谓宜去其旧而新自图，而我顾投以参、术、陈皮、芍药等补剂十余帖，安得不日以剧，然非浃旬之补，岂能当此两帖承气哉！故先补完胃气之伤，而后去其积，则一旦霍然矣。众乃敛衽而服。", "4193": "俞按：此与许学士治伤寒太阳病，因尺脉不应，用黄耆建中同法。（见江选。）彼先补而后散，此先补而后攻。但二公把握得定，故嫌疑不避。设麻黄、承气之用于后者不能愈病，则人之归咎难辞，而医之用药无路矣。", "4194": "高果哉治丁清惠公予告在籍，患痢里急后重，白积兼鲜血，昼夜十余次，饮食减少，两尺脉似有似无，两寸关弦数，小便短少，众医皆以望八高龄，当凭尺脉以投温补。高独谓禀赋素厚，宜从寸关而用清理，遂进黄芩、白芍、厚朴、槟榔、甘草、陈皮、阿胶、滑石、槐花、木香四五剂全愈。", "4195": "张路玉治春榜陈颖雍，暑月自都门归，抵家即患痢疾。半月以来，攻克不效，遂噤口，粒米不入。且因在京久食煤火，肩背发毒，不赤不疼，陷伏不起，发呃神昏，势日濒危，内外医科互相推诿，乃延石顽诊之。六脉弦细欲绝，面有戴阳之色，所下瘀晦如烂鱼肠脑，证虽危殆，幸脉无旺气，气无喘促，体无躁扰，可进温补，但得温补而痈肿焮发，便可无虞。遂疏保元汤，每服人参三钱，生耆二钱，甘草、肉桂各一钱，伏龙肝汤代水煎服。一服粥饮稍进，二服后重稍轻，三服痈毒贲起，另延疡科敷治其外，确守前方，又十余服而安。前后未尝更易一味也。", "4196": "雄按：痈毒滞下可用温补者，必见此等脉证，才为合法，然不多觏也，而医者亦不可不知有此法。设不辨其脉证，但崇景岳，动辄温补，杀人以刃与药，有以异乎？", "4197": "孙见心治张玉堂，秋间下痢脓血，昼夜百余次，里急后重，前医见脉歇止，谓因积滞所致，用槟、朴、青皮、枳壳、木香等。孙诊之，脉弦洪而数，或一二至，或三四至，或五六至辄一止，曰：毒及少阴矣，当急顾其阳明。（杨曰：用药与此语不相照顾。）用生熟地各一两，（杨曰：嫌腻滞。）归、芍、丹皮、黄连各三钱，（杨曰：得效在此。）甘草五分。群疑阴药太重，恐饱闷增剧，然服二帖，次数尚频，急重已除，脉之洪数亦减，至数相续，仍用前方，病去大半。又次日去生地、黄连，加参、术、茯苓、山药，（杨曰：加减俱不如法。）饮食大进，午后弦脉亦减，而至数复有止状，或骇曰：病退而脉复变，防其加重。孙曰：无妨也。歇止者，即古代结促之俗名耳。若冲气中绝，脏脉自见者危，今此证歇至，本以毒盛壅遏隧道，阴精不承，故一二至，或三四至，或五六至而止也。经曰：数动一代者，病在阳之脉也，泄及便脓血。今余去阴药过甚，进阳药太骤，（杨曰：自供缺失。）中脏得补，则木土和而胃气安，故饮食进而毒尚未尽者，亦随壮气而旺，故复有止状也。于方中仍加生地、黄连即平矣。果验。", "4198": "嘉善一妪常便血，时发时止，至五旬外，夏月便鲜血，里急后重，时或不禁，脉软不数，用五苓、建中转甚。因向宜凉血药，仍用四物加槐、榆、楂、曲亦无效。叶天士以用生苍术、生厚朴、炒橘皮、炙甘草、鸡膍胵、砂仁壳、丁香柄丸服全愈。又有一童子患久痢，叶亦用此方而愈。人不解其故。俞惺斋云：此方名醉乡玉屑，治小儿食瓜果致痢久不愈者，见徐春甫《医统》。", "4199": "又按：孙公原案云，实者邪气实也，故以白虎汤、益元散应之；虚者正气虚也，故以理中汤应之。今考此方分两，纯是少阴经阴盛格阳治法，若果有暑邪，岂五钱之石膏、滑石能与大剂参、术、姜、附并取其效哉？案载脉洪大，不言有力无力，亦不载口渴与否，舌苔及小便若何，何以放胆用温补？若痢兼红白，腹痛恶心，面红汗多，寒热大作诸证，确系暑邪为病，温补殊属反背。若果能取效，则的系虚寒。其些微之知母、石膏，正如白通加人溺、猪胆汁汤耳，不得牵扯「暑邪」二字以混之也。然病经二十余日，虚寒证早已亡阳矣，能待孙公用药耶！", "4200": "又治金达泉疟兼痢，日夜四十余度，小腹痛甚，每登厕汗出如雨，下迫后重，小水涩痛，头疼口渴，下午发热，天明始退。左脉浮弦而数，右软弱，中部稍滑，此内伤饮食，外感风邪所致。先与柴苓汤一剂，小便即清不痛，疟发时寒多热少。晚与人参败毒散，去羌、独，加葛根、防风、桂枝、白芍，次日头痛痢疾俱减，夜才起三次。改与补中益气汤，加酒芩、桂枝、白芍，（杨曰：先治外感，后治内伤，亦一定之序。）其夜疟止，但微热。再改胃风汤、人参、白术、桂皮各二钱，白芍四钱，酒炒芩、连各一钱，当归、茯苓、川芎佐之，炮姜、地榆为使，服后寒热殄迹，夜起一次是粪，前方去桂枝，再三剂而巾栉出户矣。", "4201": "俞按：此案用方妥当出色，可以效法。若王金坛治刘蓉川深秋患疟而洞泄不止，（雄按：洞泄与痢迥殊。）欲去其一为快，乃用《局方》双解饮子，一服而二病俱愈，更觉神妙。是得法于《澹寮》，所谓用药多一冷一热，半熟半生，分利阴阳之义也。然窃思疟痢并作，初起者专用发散，如羌、防、柴、葛等，（雄按：风寒为病，固当如是，温热暑湿，不可概用，余治曹泳之一案宜参。）佐以赤苓、神曲，见血痢参入归身、川芎，右关脉大可加厚朴，使在腑之邪提并于经而外解，最为捷法。倘或不应，审其挟寒挟热，而用表里分消之法，热者去羌、防，加芩、连、香薷、滑石、寒者去柴、葛，加桂枝、干姜。若热甚者多实证，风药不宜矣，大柴胡汤加黄连、滑石。寒甚者多虚证，风药当戒矣，真武汤加桂枝、人参，此仍表里双解之法。至如人参败毒散、补中益气汤，虚证之表药也；理中汤、八味丸，虚证之里药也。表证之虚而挟热者，小柴胡汤；里证之虚而挟热者，连理汤。表证之虚而挟寒者，麻黄附子细辛汤；里证之实而挟寒者，温脾汤。以此诸法，将脉证配合审用，无不手到成功，（雄按：皆治风寒为病之法也。）如此条右脉软弱为虚，疟发寒多热少亦为虚，（雄按：寒多热少，亦有不属虚者，总宜以脉证参看。）故第二剂即用人参，但汗出如雨，而于败毒散去羌、独加桂、芍是矣，又加葛根、防风，尚觉太过。", "4202": "周慎斋治一人，身热至六七日，医用地黄汤，遂致身体强硬，六脉沉伏，目定口呆，气喘不能吸入。周曰：能呼不能吸，病由中焦实，脾不能运耳。用远志、茯神各一钱，附子四分，橘红六钱，磁石、苏梗各一钱五分，沉香二分。一帖身和，六帖而安。盖脾者为胃行其津液者也。脾不运，则胃阳不行于肌肉，肌肉无阳，所以强耳。醒其脾，则胃阳通而身和矣。", "4203": "俞惺斋治文选金萃之，劳倦伤寒而发斑，斑出犯风遽隐，遂发痉，手足搐掉，不时跳跃，浑身震动，时欲昏晕。用牛蒡、僵蚕、土贝母、荆、防、钩藤不应，其脉细而弦劲带数，改用虎膝、归、芍、生地、钩藤、秦艽、荆芥、桑枝，痉跳减半。因思病属厥阴，当寒热兼施，乃以桂枝、羚羊角为君，仍佐血药，加竹汤、姜汁，一服而愈，盖宗丹溪治少年痘后发痉之法也。", "4204": "卢不远治陈孟杼之父，六月自山东邸中受寒起，尚淹淹未甚也，至次年二月，忽小腹与腰急痛，即令人紧挽外肾，稍松便欲死。卢曰：此小肠腑病也。经云：小肠病者，腰脊控睪而痛。乃以羌活入太阳小肠，佐黄柏、茯苓、肉桂等，并刮委中穴，痛立止，但足软。卢曰：病因六月伤寒，太阳有所未尽，故入府而痛作。原以寒邪郁火，仍需夏时则火力全而血脉通，邪始去也，果至五月天热，身发紫斑，有汗至足而始健。", "4205": "俞按：此条仍合丹溪二说同用之，非专主气虚也。惟汪公于软缓脉多以参、耆加麦冬、黄柏，不加附子，想系一生得手处。至如陈皮加作七分，气即上冲，此尤气虚之显然者，前方可操券取效也。窃忆生平治气冲证，用熟地、归、杞、牛膝、石英、胡桃、坎炁、青铅等药而愈者，不计其数，又有用肾气丸、补阴丸、三才丸而愈者，总不出丹溪之训。惟一陆姓书生，形瘦饮食如常，别无所苦，而气自脐下上冲，始仅抵胸，后渐至喉，又渐达巅顶，又渐从脑后由督脉及夹脊两旁而下，又渐至腰踝足心，仍入少腹，再复上冲。其冲甚慢，约一年而上下周到，谷食递减，肌肉愈削，凡两年半而其人方死。凡温凉补泻之药，靡不备尝，针灸祝由无不遍试。余固不能愈之，就诊于天士、一瓢两先生，亦无寸效。恨其不遇张戴人、喻西昌诸公，听其议论，以开茅塞也。", "4206": "马元仪治袁玉行，小腹厥气上冲即吐，得饮则吐愈甚，诸药不效。马诊之，两脉虚涩，右尺独见弦急，此下焦浊气上腾，则胸中阳气不布，故饮入于胃，上壅而不下达，宜通其地道，用调胃承气汤，下宿秽甚多，继渐培中气而愈。", "4207": "俞按：凡病皆有虚实，勿谓气冲证皆属阴虚气虚也。如此条可谓别开一例，然必是暴病，或便秘，乃从右尺脉印其机耳。昔年曾与杜良一先生治下焦肾虚上焦气冲者，杜用六味地黄汤合五磨饮子去木香，以汁和服而效，亦是新翻花样也。", "4208": "雄按：吴馥斋令正体腴皙，凡患恙，必延余诊，虽时感重证，投药三剂，无不愈者。惟二十八岁娩后，汛事遂绝，而别无所苦。余曰：此赋质使然，非病也。不必服药。迄今十载，形体如常。仲秋患痰嗽，气自少腹上冲至胸，即迷闷如寐，面目发黄，身热足冷，肤痛拒按。云：气冲起于上年，曾发数次，但不如是之剧耳。今则稍食荤腥，气即上冲。余脉之，软滑微弦，遂予雪羹、杏、朴、连、夏、竹茹、旋覆以开痰降逆，送下当归龙荟丸，直泄肝阳。一剂胸舒，再剂黄退，三剂便泄如火，诸恙霍然。", "4209": "俞东扶曰：眩晕有实有虚，如壮盛人实痰实火，脉滑大有力者，二陈、芩、栀，不恶心者，用酒制大黄二三钱，或加入，或为末，茶调下；如肥白人痰多气虚，脉软大或细软者，六君加耆、附。又《内经》谓：诸风掉眩，皆属肝木。故因于外风者，二陈加荆、防、钩藤、天麻；因于内风者，即类中之渐，宜虎膝、牡蛎、枸杞、首乌、桑叶、菊花、生地、人参。戴复庵曰：头脑挟风，眩晕之甚，抬头即屋转，眼常黑花，如见有物飞动，或见物为两，宜大追风散，或秘旨正元散加鹿茸，不效，一味鹿茸，每服五钱，酒煎去渣，入麝少许。盖鹿之阳气钟于头，故以类相从也。此即就风之一端，而有虚实之分也。若在夏月，有冒暑而眩晕者，又不得概从风治。夫肝为风木之脏，故《内经》以眩晕专责之肝。若肾水亏少，肝枯木动，复挟相火，上踞高巅，而眩晕者，近时最多。董载臣云：妇人患此更多，宜逍遥散为主，轻则合四物，重则合六味加黄连，极有效验。（雄按：如果肾水亏少，肝枯木动之眩晕，惟甘露饮、琼玉膏、集灵膏、固本丸等方为宜，逍遥、四物，如何有效？董氏所云，盖血虚眩晕耳。）他如晨晕属阳虚，昏晕属阴虚，亦辨证之大旨，未可据以为准也。又按：《内经》、仲景所谓厥者，手足逆冷耳，故有寒厥、热厥之辨。今人所谓厥者，乃晕厥耳，亦兼手足逆冷，而其重在神昏若死也。其证亦有数端，因怒而厥者，亦名肝厥；因瘀而厥者，亦名薄厥；虚厥之极者，即为脱厥；因痰而厥者，多兼气厥。（雄按：痛极而厥者，曰痛厥；阴虚火动者，曰煎厥。）此外更有痧厥、食厥、疟厥、风厥、寒厥、暑厥等证。又《星甫野语》云：湖州汤荣光解元，世精于医，有甲乙二人，凌晨忿争，互抱不释，故未尝斗殴也。甲忽卧地而僵，汤视之，遍体无伤，脉息未绝，胸次尚温，面色青瘦，是虫症也。空腹用力，蛔升而厥，以川椒、使君子等味，煎而急灌，须臾即苏，下蛔升许而愈。", "4210": "俞按：脉缓大重按无力，参、耆、术是矣。连柏丸何耶？盖以其微渴，大便四日一行，是缓大为虚中有热也。", "4211": "李士材治何金阳令郎患虚损，梦遗盗汗，羸顿已极，简其所服，以四物、知、柏为主，芩、连、二冬为加减，诊其脉大而数，按之极软。李曰：中气大寒，反为药苦矣。乃以归脾汤入肉桂一钱，人参五钱。当晚得熟寐，居十日而汗止精藏，更以还少丹兼进补中益气，间服而瘥。", "4212": "俞按：脉大而数，按之极软，诚宜温补矣。然用补得数脉退则愈，数脉不退，则仍不愈也。亦惟大而数，按之极软，故可温补；若细而数，按之极软，死期已近，温补何益耶！", "4213": "吴门张饮光，发热干咳，呼吸喘急，服苏子降气不应，服八味丸，喘益急，迎士材视之。两颊俱赤，六脉数大。曰：此肺肝蕴热也。以逍遥散用牡丹皮一两，苡仁五钱，兰叶三钱，进二剂而喘止。以地黄丸料，加麦冬、五味，熬膏服而痊。", "4214": "又治主政唐名必劳心太过，因食海鲜，吐血有痰，喉间如鲠，日晡烦热，喜其六脉不数，惟左寸涩而细，右关大而软，思虑伤心脾也。以归脾汤大料加丹皮、生地、麦冬。二十剂而证减六七，兼服六味丸，三月而愈。", "4215": "俞按：上条以服温纳不应，悟其病因；此条于左寸右关得其病因。上条喜脉之数大，此条喜脉之不数。盖二人俱系新病，一实一虚，尚易辨也。", "4216": "雄按：两条凭脉论证固有卓识，而用药皆未尽善也。", "4217": "叶天士治一人，年二十岁，夏月咳嗽，时带血出，常发寒热，食减形瘦，口不渴，行动时或仆地，有日轻，有日重，（雄按：因此故断其当发疟。）牙宣龈肿，晨起则血胶厚于齿龈上，脉细带数。群以弱证治，二地、二冬等滋阴药，遍尝不效。叶用芦根、滑石、杏仁、苡仁、通草、钩藤、白豆蔻，嘱云服二十帖全愈矣。若不满剂，后当疟也，其人服十帖已霍然，即停药，十月中果发疟，仍服此药而疟愈。", "4218": "雄按：虚劳因误治而成者多，余案中屡言之矣。有高某者年逾冠，于去秋完姻之前，曾患吐血，治愈之后，患疥遍身，上及耳头，至今夏仲疮愈，血复上溢，医谓虚损也。迨血止后，痰嗽不已，寒热时形，或碍左眠，或妨右卧，形消食减，左胁聚瘕，诸药备尝，不能起榻矣。延余诊之，脉虽弦数，而兼软涩，嗽必痰出而始松，舌色紫黯无津，汤饮下咽则胀，夜间不嗽，溺涩便艰，并非虚损。而病逾一载，初起必由吸受暑热，殆滋补早投，遂致血痹于络，气滞于经，升降失调，机关窒塞，亟宜通展，庶可渐瘳。予苇茎汤合雪羹，加沙参、旋覆、竹茹、冬虫夏草服之。病人云：前次所服，皆是滋润之药，下咽后，胸腹极其不舒，今服此剂，甚觉舒畅。二剂后，腹微痛，解青粪一次，嗣后每服药，必下一次，其色渐黑，甚至如胶如漆，而各恙皆减，饮食渐加。继去桃仁、雪羹，加养阴之品，调理而愈。昔袁简斋太史云：人身气血贵乎流通，否则有余者为痈疽，不足者为劳瘵。杨素园大令谓袁公真绝代聪明人，虽不知医，而此二语，已将虚实诸病因括尽无余，奈古今之以名医称者，竟未达此义也。", "4219": "天士治黄公子劳病案曰：大凡精血内夺为虚，虚不能自复为损，但须分析自上自下，从阴从阳起见为调理。是病始于饮酒劳心，营气先伤，心阳下溜，肾阴不主涵蓄，素多梦遗。上年九月先有泄泻，继发痎疟，虽暑湿热六淫外侵，然邪之所凑，本气先虚，血附于络，络凡十五，络伤血溢，莫能堵御，皆是阳气动极无制，譬诸飓风波涛矣。阳和风息，势必渐缓。但既去难追，所谓血脱益气，以无形能生有形也。必须静形体，宁神志，令阴平阳秘，以收全功。用药亦本四时生气，间有客邪标恙，惟投轻剂一二即止。（雄按：虚人受感，宜知此法，俾即解散，则本元不伤。）昧者杂以温补，遂致外邪留恋，反致戕元。冬春两季按法，入夏色脉颇安。然里真未复，长夏阳泄地升，深抱复发之忧。果以霉湿潮蒸，骤暖郁勃，遂令诸脉中之气皆泄，络中之血大沸，一损再损，脏真少藏，奇经八脉乏气支持，冲任由前而升，咳逆烘热，𫏋维失护，督脉无权，炎熇日炽，脂液日消。急固护大气以包举，渐引渐收，冀其根蒂之把握，次则调和中土，以安谷知味，百日安静，再为斟酌，其清凉治嗽，热燥刚补，一概屏弃。天暑午后服生脉散，若便溏泻则停之。每晨服一气丹丸。遗滑必用桑螵蛸散。饮食不和用异功散加炒黑神曲、炒黑麦芽。四君子汤兼参苓白术散间服。", "4220": "雄按：上损下损，皆以脾胃为扼要，固治损之大旨也。然亦此人脾胃素弱，故病前先有泄泻，而病后调理于天暑服生脉散时，独嘱云便溏则停也。设病属肝肾真阴不足，能食便艰者，亦不能舍滋濡之药为治矣。故医者治病，必先辨症而后议药，不可因俞氏之言，以为凡治虚劳，概不用滋阴补阳之药，而专以此数方，恃为返魂丹也。", "4221": "俞按：此条见识最高，用药甚巧。然幸不咳嗽，想其饮食虽少，未必大减，故以苦寒取效。（雄按：饮食大减，因于脾胃弱者，大忌苦寒。若因热郁气滞而减，则苦药开泄，病去而食自加矣。）但不知脉之数乎？大乎？有力乎？设脉至细数无力，兼见便溏食减，此方其可用乎？因思生平所见损怯证，大抵阴阳亏损者居多，如此案之可用大剂苦寒，及可用大剂热补者殊少。（杨曰：此真阅历之言。）盖阳虚易治，阴竭难治。譬之盆花，泥干根槁，日以一匙之水浇之，岂能望活？（雄按：惟根未全槁，尚有一线生气者，灌溉得宜，未尝不可转活，滋濡之法，理亦如是。）惟霖雨霡霂，庶可复生。夫雨从何来，惟地气上而为云，斯天气降而为雨。但得脾胃健旺，嗜食善化，则水谷之精华上供于肺，可拟诸云；而肺以其精华下溉百脉，可拟诸雨。（杨曰：理虽极是，无如损之重者，多不能食，殊难望其脾胃健旺也。）此虽老生常谈，实系养阴要旨也。", "4222": "雄按：此说极是。但真阴亏损之证，亦有虽能食而不可治者。曩诊闻步洲孝廉病，形虽消瘦，胃纳不减，且能肩舆出门，惟脉甚细数，而兼弦涩。坚辞不治。（杨曰：凡损症得细数脉，无不死者。）逾月其同年商华伯谓余曰：君何指下有神耶？步洲并不上床，忽于食后释箸而逝，数日前医犹谓其能食可以无虑，此曷故也？余曰：真阴亏损，能食不充饥肤者，死证耳。", "4223": "孙文垣治程道吾令眷，夜为梦魔所惊，时常晕厥，精神恍惚，一日三五发，咳嗽面色青，不思谷食，日惟啖牛肉脯数块而已。时师屡治无功，吴渤海认为寒痰作厥，投以桂、附而厥尤甚。孙诊之左脉弦，右脉滑，两寸稍短，道吾先令眷二皆卒于瘵，知其为传尸瘵证也，不易治之。乃权以壮神补养之剂消息调理，俟饮食进，胃气转，始可用正治之法。姑用参、苓、柏子仁、石菖蒲、远志、丹参、当归、石斛以补养神气，加陈皮、贝母、甘草、紫菀化痰治嗽。服半月而无进退，乃制太上混元丹，用紫河车一具，辰砂、犀角、鳖甲各一两，鹿角胶、紫石英、石斛各八钱，沉香、乳香、安息香、茯苓、紫菀、牛膝、人参各五钱，麝香五分，蜜丸赤豆大，每早晚盐汤或酒下三十六丸。又制霹雳出猎丹，用牛黄、狗宝、阿魏、安息香各一钱，虎头骨五钱，（䴕俗名啄木鸟。）一只，獭爪一枚，败鼓心破皮三钱，麝香五分，天灵盖一个酥炙，炼蜜丸，雄黄三钱为衣，每五更空心葱白汤送下五分，三五日服一次，与太上浑元丹相兼服，才服半月，精神顿异，不似前之恍惚矣。但小腹左边一点疼，前煎药中加白芍一钱，服之一月，精神大好，晕厥再不发矣。次年生一女，其宅瘵疾亦不再传。", "4224": "俞按：此论可为损怯病之秦镜，何以类案不收？（雄按：魏选已收。）又罗君治韩子玉父六十病消渴，至冬添躁热，须裸袒以冰置胸腹乃快，其脉沉细而疾。罗亦曰：人身为主，时令为客，大寒之令，其热更甚，经谓当所胜之令而不能制，名曰真强。乃孤阳绝阴必死之证也。与此条义同。", "4225": "雄按：庚戌冬卜子安少府三令郎，久患虚嗽，医用引火归元法，频投桂、附，驯致喘汗大热，不能著复衣，甚欲摇扇。延余诊之，脉洪数无序，曰：阴已竭，孤阳欲飞，天时犹不能胜，而况于药乎？辞不治。果交春而没。", "4226": "立斋治王以道元气素弱，复以考试积劳，于冬月大发热，泪出随凝，目赤露胸，气息沉沉欲绝，脉洪大鼓指，按之如无，舌干如刺，此内真寒而外假热也。令服十全大补汤，嘱曰服此药，其脉能收敛为善。少顷熟睡，觉而恶寒增衣，脉顿微细如丝，此虚寒之真象也。以人参一两，熟附三钱，煎服而安。夜间脉复脱，以人参二两，熟附五钱仍愈。后以大剂参、术、归身、炙草等药调补而痊。", "4227": "俞按：见证皆是火象，惟气息沉沉欲绝是虚象，脉洪大按之如无，则可决其内虚寒而外假热矣。（雄按：其便溺必露虚寒之真谛，惜未载明。）服温补后脉当收敛为善，此是格言，所当熟记。", "4228": "高果哉治陈几亭病身热，自卯辰以后上半身热，申酉时中半身热，亥子时下半身热，热至足底更甚，周而复始，一日一夜，循环无间，服药久而不效，展转沉重。高诊之脉微无力，右尺脉伏而不起。因思尺脉沉伏者，肾虚也；日夜之热上下循环者，肾火之浮游也；至子时而足底大热，则肾火之归就于下也。若当归下之时而能摄住其性，不使上走，则热自退矣，须效烧丹法治之。夫丹家用两个阳城罐，一盛水银丹药，填塞其中，一则空而无物，以两罐对合，其口扎住，盐泥封固，然后煅炼其上空罐，必用湿纸当烧红时搭于罐底，频以冷水润之，盖下罐丹药为火所逼，则淅淅望空罐中来矣，如升药之望上而飞也。但水银甚活，虽上入空罐，又能复入旧罐，必得凉冷之处，方能摄住其质，故用湿纸搭于罐底，丹必稳贴矣。今仿此法以制方，用童溺炙龟板一两，熟地、枸杞各七钱，麦冬五钱，萸肉四钱，此五味皆补肾滋阴之药，犹水银与丹药也；附子二钱，以从治而导火归元，犹炼丹之火也；又用黄柏七钱，以降其火，犹罐底之湿纸与水也。黄昏煎好，子时方服。从前服药，皆积于胸中而难下，服此药觉胸中易下，三剂而热除病愈。", "4229": "俞按：此案认为肾虚火不归元，大剂补肾，寒因热用，与证极合，与脉似有未合，然其讲理取譬，真堪嘉惠后人。", "4230": "孙文垣治徐三泉令郎，每下午发热，直至天明，夜热更甚，右胁胀痛，咳嗽吊疼，以疟治罔效，延及二十余日，热不退。后医谓为虚热，投以参、术，痛益增。孙诊之，左弦大，右滑大搏指。乃曰：《内经》云：左右者，阴阳之道路。据脉，肝胆之火为痰所凝，必勉强作文，过思不决，木火之性不得通达，郁而致疼。夜甚者，肝邪实也。初治只当通调肝气，一剂可瘳，误以为疟，燥动其火，补以参、术，闭塞其气，致汗不出，而舌苔如沉香色，热之极矣。乃以小陷胸汤，用大栝蒌一两，黄连三钱，半夏二钱，加前胡、青皮各一钱煎服，夜以当归龙荟丸微下之，遂痛止热退而安。", "4231": "又治族侄明之作文过劳，痰火上逆，大吐痰沫，因而呕血，一涌数碗，昏晕汗出，奄奄而卧，略不敢动，稍动即呕吐而血随出，色鲜红，饮食汤水皆不敢入，入即吐而眩晕，血即随之。医谓血涌如泉，体热脉大，眩晕而药难入，似无佳兆。孙诊之曰：无妨。凡看证要圆活，勿拘泥。经云：心主血，肝藏血。又云：怒则气上。又云：脉虚身热，得之伤暑。今左脉弦大，右脉虚大，是不独作文劳心动火，且亦被怒伤肝，抑又为暑所逼，以致木火上升，眩晕作吐。经云：诸风掉眩，皆属于肝；诸呕吐逆，皆属于火。又诸动属火，内为木火上冲，外为暑气所迫，故吐而汗多，血随吐出也。先以白丸子三钱解其暑气，清其痰饮，抑其冲逆，则吐可止，吐止气平，血自归经。服后果嗒然而睡，醒则吐止食进，眩晕寻已。继用滑石、香薷雄按：此味不妥。各三钱，黄连、扁豆各一钱五分，竹茹一钱，甘草五分，四帖而痊。", "4232": "俞按：上条胸背皆胀，服阴药胀更甚，合以两关脉之洪滑有力，尚易辨其非阴虚，况恼怒食犬，亦可问而知之。此条因作文过劳，呕血数碗，昏晕汗出，稍动即吐，而血随至，势殊危矣。况右脉虚大，不认为虚而认为暑，竟合左脉之弦大，大剂清暑清肝，真妙手也。", "4233": "雄按：关琴楚令孙少西之证，与此略同，今年三十四岁，素善饮，夏季忽患发热呕吐腹痛，伊父母以为痧也。诸色治痧丹丸遍饵之，寻即气冲咳嗽，血涌如泉，不能少动，动即气涌，血亦随之。沈某但知其阴分素亏，遽从滋补，服之益甚。延余诊之，左脉弦洪而数，右洪大，曰：虽属阴虚，但饮醇积热于内，而暑火外侵，所服治痧诸药，无不香窜燥烈，诚如火益热矣。苟不亟为清解，则邪无出路，气何能平，血何能止乎？而家素畏凉药，连服滋补不应，遂求乩方服之，药虽离奇，并木鳖、麝香，亦信而不疑。旬日后吐血已尽，气出如奔，自汗形消，热犹不退，彻夜无寐，舌绛无津，再求余治，脉已细数如丝，不能救药矣。", "4234": "俞按：两尺沉实，决其少腹有瘀，因瘀而蒸热，因蒸热而吐血，盖从脉象认得病根，故大下之而病根拔也。", "4235": "周慎斋治陈姓人，年三十五岁，性嗜酒色，忽患吐血，一日三五次，不思饮食，每日吃粥一碗，滚酒反用数杯，次日侵晨再吃粥，前粥尽行吐出，吐后反腹胀，时时作痛呕酸，昼夜不眠，饮滚酒数杯略可，来日亦如此，近七月矣。医人并无言及是积血者，俱言不可治。周诊之，六脉短数，曰吐后宜宽反胀，吃滚酒略可，此积血之证也。盖酒是邪阳，色亦邪阳，邪阳胜则正阳衰，又兼怒气伤肝，肝不藏血，思虑伤脾，脾不统血，中气大虚，血不归络，积血中焦无疑。宜吐宜利，但脾胃大虚，不使阳气升发，阴寒何由而消？先用六君子汤，白术以苍术制之，加丁香温胃，草蔻治中脘痛，三十余帖，再用良姜一两，百年陈壁土四两同煎，待土化切片，陈皮去白，草蔻、人参、白术、茯苓、甘草、胡椒、丁香各五钱，细辛四钱，共为末，空心清盐汤或酒送下二钱。此药专在扶阳，积血因阴寒凝结，阳旺而阴自化。服药后血从下行者吉，乃血从上吐，约六七碗，胸中闷乱，手足厥冷，不省人事，急煎人参五钱，炮姜八分，遂静定。后胸中闷乱，脐下火起而昏，用茯苓补心汤一剂而安。后用六味加炮姜、人参而痊。", "4236": "张路玉治陶震涵子，劳伤咳嗽失血，势如泉涌，服生地汁、墨汁不止，用热童溲二升而止。张诊其脉弦大而虚，自汗喘乏，至夜则烦扰不宁，与当归补血汤，四帖而热除。时觉左胁刺痛，按之漉漉有声，此少年喜酒负气，尝与人斗很所致。与泽术麋衔汤加生藕汁调服，大便即下累累紫黑血块，数日乃尽。后与四乌鲗一藘茹为末，分四服，入黄牝鸡腹中煮啖，留药蜜丸，尽剂而血不复来矣。", "4237": "俞按：自汗喘乏，脉弦大而虚，不混投地黄汤、生脉散，高矣。用补血汤者，以其夜间烦扰不宁耳。至因胁痛，想及斗很，则此人形色必壮实，故消瘀不补益，最为得法。", "4238": "又按：吐血一证，近日最多，有有因而患之者，亦有无因而患之者。外因六淫之邪，动血犹轻；内因酒色忧愤，动血为重。及不内外因，作劳举重，忍饥疾行，皆使失血，然尚可求其因而治之。若与诸项并不相犯，无端而吐血，此则最重。《内经》谓地居太虚之中，大气举之也。大气偶泄，即有地震山崩之患，而水不安澜，或溢或竭。人身亦然。大气厚足以包固，纵犯三因，亦成他病，不至吐血；大气衰不能担护，如堤薄而水易漏，堤塌则水必决也。世人只守血热妄行一说，误矣。至缪氏治吐血三诀，举世奉为明训，实未细绎其义耳！首条云宜行血不宜止血固是，然行血之药，惟有大黄，所谓血以下行为顺也。又须看其血证之久新，与失血之多少而去取之。盖宜下于妄行之初，不宜下于脱血之后也。今本文不注明行血者何药，但云行血则血循经络，致近日有多服山羊血而死者，安知不误于此句？至于血来汹涌，必须止之，古方花蕊石散、十灰散及童便、墨汁等，皆欲其止也。止之后或消或补，尚可缓商，任其吐而不思所以止之，何从求活？特是止血之法，贵于虚实寒热认得清，斯于补泻温凉用得当耳。本文云止之则血凝，血凝则发热恶食而病日锢，抑思今之吐血者，每多发热恶食，何尝由于血凝耶？果系血凝，则仲景大黄蟅虫丸尚可救之，只虑血去无算，阴虚则病，阴竭则死，奈之何哉！此条宜补肝，不宜伐肝，注谓养肝则肝气平，而血有所归，伐之则肝虚不能藏血，血愈不止，此说诚妙。然亦要看脉象若何，肝阴固宜养，肝阳亦宜制。设遇木火两亢，血随气逆者，则抑青丸、龙胆泻肝汤、醋制大黄、桃仁、枳壳、青铅、铁锈水等，何尝禁用。盖用得其道，则伐之即所以补之，不得其道，而徒奉熟地、当归、萸肉、枸杞等为补肝之药则谬矣。（雄按：诸病皆然，医宜识此。）末条宜降气。夫气有虚实，亦分寒热。血证之气虚者多，实者少，热者多，寒者少，惟恃强善怒之人，肝气实而吐血往往有之，抑肝清肝，宜降气，又宜降火矣。他如肺气虚而不降，则生脉散、观音应梦散；中气虚而不降，则四君子、参橘煎；肾阳虚不能纳气而不降，则八味、黑锡丹；肾阴虚不能纳气而不降，则大补阴丸、三才封髓丹。必求其所以不降之故而治之，斯为善降，乌可恃韭汁、苏子、降香为下气药耶？（雄按：凡用药之道，不论何病，皆当求其所以然之故而用之，不独此也。）至不宜降火之句，医中狡狯者藉为口实，辄称吐血服生地、麦冬必成劳病，随将假阿胶售人以代二物。（雄按：即不售假阿胶者，亦借此为口实，不问其病因，辄用人参、熟地、甘草、干姜、附、桂、黄耆等热补药以误人矣。）不知世之一见血证，概用生地、麦冬，诚应诃责，若将二特屏弃，岂非因噎废食乎？（雄按：岂但此耶，甚有凡属清凉之品，如沙参、竹茹等药，一概视同砒鸩者矣。）余生平所见血溢上窍之人，合乎丹溪所谓阳盛阴虚，有升无降者，十居八九；合乎仁斋所谓阳虚阴必走者，百中一二而已。惟虚而有火者，清补并用；虚而无火者，气血兼培。或宜降火，或不宜降火，总无一定之法也。若谓服苦寒药必死，则仲景《金匮》之泻心汤，不几为罪之魁哉！", "4239": "俞按：此条脉证，似虚似实，非寒非热，甚为难辨。观其讲病源与用药法，及药之轻重去取，俱有精义，又极平和，十年之病，半月而愈。仙乎！仙乎！", "4240": "孙东宿治陈鹿塘有肠风脏毒之证，大便燥结，数日不能一行，痛苦殊甚，百医不效，其脉两寸皆数，两关皆弦而无力，两尺洪滑而左尤甚。孙曰：东垣谓大肠喜清而恶热，脾胃喜温而恶寒，以胃属土，而大肠属金也。今此乃胃寒肠热之证，（杨曰：以脉与症合参而得之。）当以肠风脏毒之药为君主，外以养血之剂裹之，使不伤胃气。（杨曰：巧法。）盖药先入胃而后传入大肠，入胃时裹药未化，及入大肠，则裹药化而君药始见，亦假途灭虢之策也。因以大黄酒浸九蒸九晒二两，木耳二两，槐花三两，郁李仁、皂角子、象牙屑、条芩各一两，血余、升麻、荆芥各五钱，为末，炼蜜丸，外以四物汤加蒲黄各一两为衣，空心午后各以米汤下二钱，果血止而大便不燥，饮食日加矣。", "4241": "周慎斋治一人患肠风，血大下不止，头晕倒地，三四年不愈，皆曰不可治。周诊脉左手沉细，右手豁大。此因内伤寒凉太过，致阳不鼓，故左脉沉细；血不归络，火浮于中，故右脉豁大。用补中益气汤十帖，再用荆芥四两，川乌一两，醋面糊丸，空心服愈。", "4242": "嘉兴府尊王竺庐，因案牍劳神，而得便血症，服天王补心丹及玉女煎、知柏地黄丸等方，屡愈屡发，至次年三月渐剧，食减面黄形瘦，精神衰弱。无锡龚商年用补中益气汤，以醋炒升麻、当归而血止。半月后偶食青菜腐汤，血复下，龚谓寒湿伤脾，用苍术理中汤遂愈。十月中值府考阅卷过劳，血又大下，龚诊脉弦劲带数，腹胀不思食，易怒，进加味逍遥散不应，改用桃花散、归脾汤，转口干咳嗽，佐以阿胶、熟地，又溏泻肠鸣不食，困惫难支。胡灏轩自省中来诊，曰归脾须合右归，重用人参则效，定方人参五钱，山药三钱，枸杞、菟丝、枣仁各四钱，茯神、白芍、文蛤炒各钱半，炙草、炮姜各七分，地榆炭八分，乌梅、大枣各二枚。一剂而血止，递加耆、术、熟地，再去地榆、文蛤，佐以附子，而谷食渐增，病遂全愈。", "4243": "杨曰：方与脉不相证对，既以此得痊，则脉象必别有可据处。", "4244": "俞东扶曰：《内经》谓胞移热于膀胱则溺血。故溺血证属热者多，实热则脉洪数有力，宜导赤散加栀、芩、淡竹叶、鲜小蓟，调滑石末，冲生藕汁；虚热则脉洪数无力，宜生地、归、芍、栀、芩、牛膝、麦冬、黄连等，调发灰或茅根汁；若夏月有感暑热者，六一散加黄连、生地；若少年有血虚挟瘀者，阿胶、三七二味多服；若阻塞不通，并可加冬葵子、生蒲黄以化之；多怒人有肝火怫郁者，龙胆泻肝汤，甚则当归龙荟丸。惟久而不止则为虚，归脾、补中益气酌用；或老年及久病人，始虽热证，久变虚寒，并可用八味地黄丸、四味鹿茸丸等方。然用至此种药，小愈仍复发者多不救。（雄按：老年久病，有温补误投，虽至死不属虚寒者，不可不知也。）", "4245": "慎斋治一人自汗足冷，不能行动，尺脉沉大，此脾气下陷也，故肺失养而汗出；足乃脾肾经行之地，脾阳不舒，肾气亦郁，所以冷也。以起脾养肺为本，温肾为标，用参、耆、山药补脾阴，固表扶肺，稍加桂温之而愈。", "4246": "俞按：自汗而足冷不能行动，显系下焦虚寒矣。尺脉当沉细，何反沉大？粗工舍脉凭证，必将温补肝肾，而用熟地、枸杞、苁蓉、鹿茸、桂、附等药；即凭脉论证，亦将认为下焦湿热，而用二妙散、防己、黄耆等方，俱与脾气下陷隔一层也。", "4247": "周慎斋治一人，六脉涩滞，胁痛吐臭痰，恶心食不下。盖胁者，少阳之分也。清气不升，浊气郁于少阳之络，故痛；浊气上逆，故吐臭痰而恶心，浊气故臭也；食不下者，少阳清阳之气不升，则肝不能散精也。用柴胡、白蔻各二分，黑山栀、甘草各五分，白芍、丹皮各一钱，茯苓、广皮各一钱五分，归身八分，麦冬二钱。十帖全愈。", "4248": "雄按：余治一劳力男子，深秋患发热凛寒，咳嗽气逆，不能仰卧，痰出甚臭，嗽则左胁大痛，溺赤便闭，口渴苔黄，脉则弦滑而数。细询病因，其人平素嗜饮，醉饱后偏向左眠，是痰饮之积于左者，久而即臭，非内痈也。其发热谵语，胸闷不饥，是积痰因感而动也。遂予石菖蒲、旋覆、竹茹、蒌仁、冬瓜子、枇杷叶、省头草、滑石、黄芩、连翘、丝瓜络、杏仁、芦菔、海䖳，为大剂投之，痰更大吐，大便亦行，数剂而平。然舌转光红少液，脉亦弦数而劲，随用甘凉养液涵阴，而食进病痊。", "4249": "李集虚劳而无度，醉而使内，汗出多痰，服宽膈化痰之药，转觉滞闷。李士材诊其脉沉而涩，两尺尤甚，因谓其婿曰：痰得涩脉，一时难愈，况尺中涩甚，精伤之象也。在法不治，勉用补中益气加半夏、茯苓。二剂有小效，众皆喜。余曰：涩象不减，脉法无根，死期近矣。果十余日而没。", "4250": "俞按：此与立斋所治梁厚斋同一涩脉，而死生不同者。彼惟尺脉浮大，按之则涩，此是六部沉涩，两尺尤甚，轻重自别也。况又云脉法无根，想是沉而细涩，按之欲绝耳。不然，哮嗽门中顾明华案，（见喘门。）亦系涩脉，何以先补养而后吐下，仍能愈之耶？", "4251": "雄按：汗出精伤，脉法无根，固是死证，然不宜用此等药矣。", "4252": "又治秦景明素有痰饮，每岁必四五发，发即呕吐不能食，此病久结成巢囊，非大涌之弗愈也。须先进补中益气，十日后瓜蒂散频投，涌如赤豆沙者数升，已而复得水晶色升许，如是者七补之七涌之，百日而窠囊始尽，专服六君子、八味丸，经年不辍。（雄按：脉证皆未详述，不知何故。）", "4253": "雄按：黄锦芳云：铅山张敬亭患痰喘，反复颠倒，夜不能寐，不思饮食，舌苔甚滑，诊其脉洪数有力，而左独甚，医者谓其痰白为寒，进广、半、川朴，余力止之曰：凡审病须兼众证与脉并审，不可专指痰色一证为据。若痰白而见气缓不促，脉数无力，或软滑，其白应作寒看，今则六脉皆数，皆数非火而何？又痰白而胸腹不热而和，其白亦作寒看，今自脐至胸，有如火烙，非火而何？又气喘不急，痰出舒缓，其痰之白亦作寒看，今喘如雷鸣，急迫已极，非火而何？正如釜下火急，釜中之水，被火逼迫上沸，滚为白沫，宜乎其痰白如银也。遂以六味地黄汤投之，两剂而沸略减，多剂而沸始平。（雄）谓世人但以痰色辨寒热，每多误治，何氏《医砭》尝论之矣。而此案审证须兼众证与脉并审一语，尤为临证要诀，不仅为辨痰而发也。第案中未辨其溲便如何，则兼证尚欠详晰。如兼见小溲短赤者，六味汤送下滋肾丸，必奏效更捷。", "4254": "雄按：此条不但脉象属虚也，膈胀只在五更，则余时不胀，显为虚证。人参、鹿角之丸，佐以茯苓、车前，是导之下行，以敛虚气之上逆，故不用蜜丸，而送以盐汤。粟壳、诃子之方，丸之以蜜，服于枕上，是使其留恋胸膈，收敛肺化痰之积，用药之法，真丝丝入扣也。", "4255": "又治李古愚，每食后即大便，腹皮稍胀急，胸膈满闷。医与参、术则痞闷愈甚，小水清而长。孙脉之左寸涩，右寸滑，按之如黄豆大，且鼓指，关尺之脉皆弦小，左尺迢迢有神。杨曰：列脉象甚明晰。据脉，乃积痰郁滞于肺莫能出，以致大肠之气不固也。法当效丹溪治乃叔用吐以去上焦痰积，而大便自实矣。先用苦梗、芦菔子各三钱，白蔻仁、橘红、山栀各一钱，川芎五分，生姜三片，葱白三茎。煎服探吐，不能尽出。又以芦菔子一合擂浆水，加蜂蜜与半碗饮之，始吐胶痰二碗。平日每小水则大便并行，吐后小水始能独利，连行三四次，而胸腹宽舒。初亦以吐为惧，至是豁然称快，大便亦不频下矣。再以二陈汤加白术、旋覆花、麦芽调理全安。", "4256": "陈武塘曰：余长子揆，向患遗精，于天启丁卯冬，遗证大作，肾窍漏气出如烟雾，时作时止，眠食渐减，形瘁骨痿，大便艰涩，其色颇黑。用猪胆汁入大黄、皂角末导之。初用甚快利，并上部诸火亦觉清息，延至戊辰六月，则愈导愈秘。因思胆汁、大黄苦寒，皂角刮削脂膏，故求润而弥燥，乃以猪胆去汁入蜜同温水满之以为导，导久而便始不艰。然八月后不能起床，至己巳五月，肌肉愈瘦，眠食愈减，胸膈如有物踞之，腹则空虚，上则痞闷，每食少许，辄停留不下，隔六七时犹嗳，呼吸之气亦碍而不畅。以为因虚致滞，则服人参必增懑；以为稠痰蓄血，用疏快之剂，又无寸功。身常畏寒，夏令犹掩重帏，惟身不热，口不渴，声音虽轻而不变，面色白而不赤不黑，每日仅用粥饵二盏，或终日不食，旁人疑在旦暮，却已绵延两载。时名医高果哉、孙见心晨夕诊视无功，又延姑苏柯生，柯大言人也，乍闻其论不胜喜，及治罕效。乃追忆从前大肠气数不禁，遂觉胸膈痞闷，继因过防衄证，日饮童溺，及滋清药过多，大便渐润。然大便后即觉腹中虚怯，而胸膈分毫不宽，若大便所下甚多，则胸膈痞闷愈甚，于是疏上补下，茫无措手。远延镇江张承溪至，张诊二次，曰：男子久病，以太谿、冲阳脉决其死生，今六部无险，太谿、冲阳有根，必不死之脉也。其证名为下脱。凡阳气上绝，阴气不得上交于阳，则为下脱，阴窍漏气是也；阴气下绝，阳气不得下交于阴，则为上脱，耳中出气是也。方家以失血之证为错经妄行，而不知气证亦有错经妄行者。盖肾纳气，过泻成虚，则肾气不能自纳，遂错行而妄漏。经云醉饱入房，五脏反复。五脏部位宁有反复之理？正谓其气错乱也。今未能提其气复使归经，所以时漏不止，漏则气虚，气虚于下，则痰结于上，故饮食难化而成郁结痞满之证。今用药疏导郁滞，不宜误用滋阴；宜有提有降，合成疏通，不宜专用顺气，若认此为阴亏之证，遂谓虚不受补者不治，则大误也。阴虚生内热，岂有阴分大亏，卧床年半，而不发骨蒸潮热者乎？（雄按：可治之机在此。）滋阴之药，不惟无功，且于开胸膈进饮食有大碍。今但使膈间日宽一日，谷气日增一日，则阴不补而自补矣，（雄按：论证论治，句句名言。）起色可指日而待。煎方用苏子、山楂各二钱，橘红、半夏曲各一钱五分，茯苓、乌药、香附、五谷虫各一钱，升麻八分，柴胡四分，临服入韭汁二匙。此方疏郁为主，而升降互用，其旨颇精。服二十剂，虽不大效，然视向之服一药增一病者，则霄壤矣。秋初张别去，余因其疏郁大旨，为之推广通变，自定噙化丸，用人参六钱，醋制香附、橘红各四钱，贝母、桔梗各三钱，松萝茶二钱，白蓬砂、西牛黄、干蟾炙存性各一钱，薄荷叶三分，以乌梅肉二钱蒸烂，同竹沥梨膏为丸，每丸一钱。余因胸中结块，原起于午食后即卧，用噙化丸，使睡中常有药气疏通肺胃之间，彼将欲结药往疏之，新结不增，旧结渐解。卧时成病，以卧时治之，且病在膈上，不用汤之荡涤，丸之沉下，（雄按：胸膈痞塞者，坚硬之丸并不能沉下，徒增其病耳。而用噙化丸徐徐沁入，日计不足，月计有余也。）服六七十丸后，膈间渐宽。尔时医家疑气坠之证，恐深秋逾剧，以秋金主降也。余谓肺主气，气得其令，则降者自降，升者自升，各得本职，非谓有降而无升也。能使清升浊降，则气坠之病，正宜愈于深秋。（雄按：陈公因承溪之旨而推广变通，可谓善得师矣。）其噙化丸中不用升药，洵为青出于蓝。论气数言，尤推卓见。至八月病人偶伤麦粉，下以沉香丸，忽去胶痰数升，胸膈顿爽，殆药力渐到，而元气渐回，邪无所容，而乘势自下也。然气弱形羸，长卧不起如故。冬底医家又防春来木旺，脾病转剧。余曰无忧。凡脾受肝克，则畏木气来侵，今乃脾困而非脾弱，冬气闭塞，脾困所畏，幸喜及春，方藉木气疏通之，已而食果稍增，肌亦渐泽，五脏之情变化如此，执生克之常，几何而不误人。（雄按：即《内经》土得木而达也。）庚午四月，张公复至，曰胶痰去，病根拔矣。骨痿不能自行立者，湿气留伏脾经故也。投以白术煎，用白术一斤，苍术四两，作膏服之，未终剂而起。此病奇而久，约费千日之医治，竟得全生，故备识之。", "4257": "俞按：陈公以缙绅先生而讲医理，却极精深。所论噙化丸治法微妙，切合病机，虽老医见不到此。（雄按：《广笔记》庄一生曾用此法，宜参。）至于张承溪之用术煎，不认骨痿为肾虚而为脾湿，见亦高人数等矣。（雄按：张公早洞悉其病源也。盖湿痿与阴虚痿见证相似，而病源迥异，须参脉色舌苔及便溺，自有分别。）", "4258": "雄按：余治高隽生孝廉令堂，嘈杂便溏，肠鸣少纳，脉至虚弦软滑。虽肝炎火而痰饮动，然脾脏受戕，舌色淡而无液，苦燥凉润，皆不可投，与潞参、九蒸白术、甘草、木瓜、薏苡、白芍、竹茹、建兰叶、茯神、盐水炒橘红、牡蛎为方，数剂而愈。", "4259": "李士材治兵尊高元圃，久患呕吐，诊脉气口大而软，曰此药气多而谷气少也，且多犯辛剂，可以治表实，不可以治中虚；可以理气壅，不可以理气弱。用熟半夏五钱，人参三钱，陈仓米一两，白蜜五匙，甘澜水煎服，十剂而愈。", "4260": "周慎斋治一人，年五十五，胸前微痛，无休息时，六脉俱无胃气，惟胃脉略缓。盖胸中受气于丹田，时时心下微痛，乃丹田阳气不到胸中，隔气无疑。脾脉微缓，调理脾胃，犹可迁延。保元汤加山药、沉香。", "4261": "杨曰：噎膈一证，昔人皆与反胃混同立论，其实反胃乃纳而复出，与噎膈之毫不能纳者迥异，不容强合也。即噎与膈亦有辨，噎则原能纳谷而喉中梗塞，膈则全不纳谷也。至为病之源，昔人分为忧、气、恚、食、寒，又有饮膈、热膈、痰膈、虫膈，其说甚纷。叶天士则以为阴液下竭，阳气上结，食管窄隘使然。其说原本《内经》，最为有据。徐洄溪以谓瘀血顽痰逆气阻隔胃气，其已成者无法可治，其义亦精。然以为阴竭而气结，何以虚劳证阴竭致死而阳不见其结，以为阴竭而兼忧愁思虑，故阳气结而为噎，则世间患此者大抵贪饮之流，尚气之辈，乃绝不知忧者，而忧愁抑郁之人反不患此，此说之不可通者也。以为瘀血顽痰逆气阻伤胃气，似矣。然本草中行瘀化痰降气之品不一而足，何以竟无法可治，此又说之不可通者也。予乡有治此者，于赤日中缚病人于柱，以物撬其口，抑其舌，即见喉间有物如赘瘤然，正阻食管，以利刃锄而去之，出血甚多，病者亦困顿累日始愈。以其治甚险，故多不敢尝试。又有一无赖垂老患此，人皆幸其必死，其人恨极，以紫藤鞭柄探入喉以求速死，呕血数升，所患竟愈。此二人虽不可为法，然食管中的系有形之物阻扼其间，而非无故窄隘也，明矣。又河间献县人患此，临危嘱其妻剖喉取物以去其病，比死，其妻如所诫，于喉间得一物，非骨非肉，质甚坚韧，刀斧莫能伤，掷之园中树上，经年亦不损坏，一日其子偶之园中，见一物黏缀草间，栩栩摇动，审视则其父喉中物也。异而伫目半日许，物竟消化，遂采其草藏之。有病噎者，煎草与饮，三啜即愈，遂以治噎擅名，如是十余年，后其草不生始止，是世间原有专治此证之药矣。余臆度之，此证当由肝过于升，肺不能降，血之随气而升者留积不去，历久遂成有形之物，此与失血之证同源异脉。其来也暴，故脱然而出为吐血；其来也缓，故流连不出为噎膈。汤液入胃，已过病所，必不能去有形之物，故不效。其专治此证之药，必其性专入咽喉，而力能化瘀解结者也。昔金溪一书贾患此，向余乞方，余茫无以应，思韭叶上露水善治噤口痢，或可旁通其意，其人亦自知医，闻之甚悦，遂煎千金苇茎汤，加入韭露一半，时时小啜之，数日竟愈。后未尝以治他人，未知其果能累试辄验否？偶举此以告孟英，以为可存，因附录之，以质世之深于此道者。", "4262": "俞按：三条皆治舌瘖，非喉瘖也。首条化痰通窍是实证。次条伤寒五七日神昏而瘖，岂无实热证用大黄、黄连、石膏者耶？而猥云作体虚有痰治也。魏注云：恐热传少阴心经，此案未可为训，极是。但细读之，案中不载舌干、苔黑、便秘、烦躁等证，则所谓神昏者，身热人静而默默耳，岂必有欲言不能言之状也？其脉必濡滑无力也。参、耆、术服之数日，病无迸退，即可知其对证。观于十二日舌始语得一字，又半月而舌能言，热乃退，全绘一虚证情形矣。凡遇伤寒舌瘖者，宜以此条寻绎之，勿竟以陶氏热传手少阴心经，儱侗为治。第三条吐血后不食，舌不能言，是虚证无疑矣。渴饮水，脉带数，不与滋阴，而与参、术，见识岂不高哉！", "4263": "雄按：脾足太阴之脉连舌本，当云饥饱伤胃，贲门壅涩，劳倦伤脾，脾气陷而不升，不能为胃行其津液，故语言不能出。补中益气，升举脾阳，则津液行而汗出周身，瘖亦遂愈也。", "4264": "李士材治史明粦，经年咳嗽，历治无效，自谓必成虚劳。李曰：不然。脉不数不虚，惟右寸浮大而滑，是风痰未解，必多服酸收，故久而弥盛。用麻黄、杏仁、半夏、前胡、桔梗、甘草、橘红、苏子。五剂止，十剂全愈。", "4265": "孙东宿治许卓峰，多酒、多怒人也。上吐血，下溲血，咳嗽声哑，医皆以为瘵。孙诊其脉，左关弦大，右寸下半指累累如意珠。乃曰：此有余证也。病由嗜酒，酒属湿热，助火生痰，火性炎上，迫肺不降，积而生痰，壅于肺窍，以致失音，此痰壅之哑，非肺痿之哑也。性又善怒，怒气伤肝，故血妄行而不归经，以致吐血溺血。法宜清热开郁化痰，导血归源，若滋阴之药，反助其塞而益其热，声音何由而开？况血随气行，气不清，血又何得归原哉？（雄按：此与承溪之论错经妄行，可以互相发明。）乃用滑石、青蒿解酒热为君，贝母、郁金、栀子、香附开郁为臣，杏仁、桔梗、丹皮、丹参、小蓟、甘草化痰清血为佐。服十帖，血果止。又以贝母一两，童便浸一日为末，柿霜等分，时时抄舌上化下，五日而声音爽矣。", "4266": "孙文垣治凌绎泉，年已古稀，原有痰火之疾。正月初旬，因劳感冒，内热咳嗽，痰中大半是血，鼻流清水，舌苔焦黄芒刺，语言强硬不清，二便不利，喘急碍卧，亦不能仰，以高枕安桌，日惟额伏枕上而已。医治半月不效。孙诊之：两手脉浮而洪，两关脉滑大有力。知其内有积热，痰火为风邪所闭，复为怒气所加，故血上逆。议者以高年见红，脉大发热为惧。孙曰：此有余证，诸公认为阴虚而用滋阴降火，故不瘳，法当先驱中焦痰火积热，后以地黄补血等剂收功可也。乃以栝蒌、石膏各三钱，半夏曲、橘红、桑皮、前胡、杏仁、酒芩、苏子水煎，冲芦菔汁一杯。一剂而血止。次日诊之，脉仍浮而洪大，尚恶寒，此因先时不解表，竟用滋阴，又加童溺降下太速，以致风寒郁而不散，故热愈甚也。改以定喘汤，一剂而喘减，二剂而热退不恶寒。再诊之，两手浮象已无，惟两关脉鼓指，此中焦痰积胶固，不可不因其时而疏导之。以清中丸同当归龙荟丸共二钱进之，其夜下稠黏秽积甚多。余忆丹溪有云：凡哮喘火盛者，白虎加黄连有功。正此证对腔法也。与十剂，外以清中丸同双玉丸夜服，调理而安。", "4267": "俞按：此方加减最巧。上案用七气汤成方亦巧。观其论脉溯因，而细心体贴之，乃知其巧。", "4268": "俞按：所用诸方，摄纳肾阳，温通督脉，疏刷肺气，开豁浊痰，标本悉能照顾，巧更极矣，宜乎服之而宿疾全瘳也。（雄按：哮喘属虚寒者，可仿此案设法。）", "4269": "孙一奎治马二尹，年五十五，过食鳗肉卷饼，心腹胀痛。市医遽用硝、黄下之，大便不行，胀痛愈增。继至者以木香槟榔丸、大小承气汤连服十日，胀痛益甚，粒米不进，大便并不行，小水亦仅点滴。后医以硝、黄不效，杂进备急丸、白饼子、十枣汤、黑白丑之属，服数日，不惟大便不行，并小便点滴亦无矣，胀不可言。众医大叫称怪。一人为灸中脘三十壮，毫不为动。因断三日当死。孙至，观其色苍黑，神藏不露，声音亮，腹大如覆箕，不能反侧。诊其脉，两手皆滑大，两尺尤有力。询其病源，阅其前方，骇然以为未闻未见也。因思一治法：先进香砂六君子汤，参、术各用二钱。众医皆惊，谓中满胀痛，二便俱闭，如何用补？况苍黑之人，尤忌参、术乎！孙曰：此非鼓胀证，乃内伤证也，当始伤时，犹在上膈，法当用吐。经所谓在上者，因而越之也。不用吐而用下药以伤其脾，脾伤则失运动之职，是以愈下愈伤，愈伤愈胀，脾气全然不动，药亦全然不行矣。故用六君子以醒其脾，香砂以助其运动，再用吐法吐出前药，始有生机，此方非治病，乃治药也。且余非虑其大便不行，独虑行之不止耳。医谓求其行而不得，何以不止为虑？孙曰：君试思常人能服硝、黄几何？巴豆、牵牛几何？今幸其未行，药性未动，尚可为计，一行而诸药性动，譬水底漏，其中能蓄点滴否？医又云：多服下药而大便不行何也？孙曰：此易知之，始为食伤，继为药伤，所伤在上、中二焦，下元未损，故两尺脉尚有神气。《难经》曰：人之有尺，如树之有根也。《内经》曰：肾者胃之关。盖肾主二便，观其色苍黑，神藏气固，皆由根本未动，赖此犹可为耳。服药后腹中大痛，孙谓药力已动，改用参芦、防风芦、升麻、桔梗各三钱煎服，少顷用鹅翎探吐之，前服药物一涌而出数十碗。病者喜曰：目前有光矣，此已时也。孙曰：酉时大便必行，可多备人参，以防不虞。至午进至宝丹一帖，以温中气，未申间腹中汩汩有声，浊气下滚，顷刻腹中宽数寸，至晚大便行一次，小水略通。孙即用人参、白术各五钱，炮姜三钱，茯苓二钱，陈皮一钱，木香、甘草各五分。令急煎服。四鼓又大便一次，小水继至，胀痛渐减。次日大便泻十余次，因以是方煎丸并进，计泻七十二日，服人参二斤余而收功。", "4270": "俞按：金液丹、神秘汤，人所罕用，而善用之则各奏奇功。因思古方具在简策，特患寻不著对头帽子耳。又按：神秘汤乃生脉散合二陈汤，去麦冬、茯苓，加紫苏、桑皮、桔梗、槟榔，以生姜三片为引，施于此证恰好。加麻黄更好，并非八寸三分通行之帽也。", "4271": "滑伯仁治一人，病怔忡善忘，口淡舌燥多汗，四肢疲软发热，小便白而浊，众医以内伤不足，拟进茸、附等药未决。脉之虚大而数，曰：是犹思虑过度，厥阴之火为害耳！夫君火以名，相火以位，相火代君火行事者也。相火一扰，能为百病，百端之起，皆由心生。越人云：忧愁思虑则伤心。其人平生志大心高，所谋不遂，抑郁积久，致内伤也。服补中益气汤、朱砂安神丸，空心进小坎离丸，月余而安。", "4272": "高果斋治铁塞庵，怔忡不寐，心脉独虚，肝脉独旺。因述上年驿路还乡，寇盗充斥，风声鹤唳，日夜惊惧而致。遂用生地、麦冬、元参各五钱，人参三钱，龙眼肉十五枚。服数剂，又用夏枯草、羚羊角、远志、茯神、甘草、人参大效，仍以补心丹常服全愈。", "4273": "叶天士治嘉善米怀音，初患颠狂，医用清痰、清火药而愈。越三年复发，消痰清火不应，用天王补心丹而愈。越二年又发，进以前二法皆不应，用归脾汤而愈。越一年又发。发时口中哼哼叫号，手足牵掣搐掉，如线提傀儡，卧则跳起如鱼跃，或角弓反张，其喊声闻于屋外，而心却明白，但以颤掉之故，口欲语已将唇舌嚼坏，如此光景，半刻即止，止则神识昏瞀，语言谬妄，又半刻而发如前矣。吴某用人参、鹿茸、肉桂、熟地、龙齿、青铅、远、茯等药，服之甚相安，然匝月不见效。叶诊曰：渠用贵重之药，必自信为名医，但多费病家之财，与病毫无干涉，即庸医也。吾以轻淡药二十剂当减半，四十剂当全瘳矣。因叩其掣掉则心明，止则神昏之故。曰：操持太过，谋虑不决，肝阴胆汁两耗，阳𫏋阴𫏋，脉空风动，非虚寒也。用白芍、萸肉各一钱五分，白石英、小麦、南枣肉各二钱，炙草五分。病人见其方，殊不信，旁人亦以药太轻淡，并两帖为一帖，服十日，病减半，二十日果全愈。后遂不发。", "4274": "俞按：上条不用补，次条不用养阴，认证最清。设效立斋、景岳，狃于归脾汤、补中益气、六味、生脉者，必为二证之戈矛矣。", "4275": "又治李寅斋患血淋，几二年不愈，每发十余日，小水艰涩难出，窍痛不可言，将发必先面热牙疼，后则血淋。前数日饮汤水欲温和，再二日欲热，又二日非冷如冰者不可，燥渴之甚，能饮井水二三碗。其未发时，大便燥结，四五日一行，发则泻而不实。脉左寸短弱，关弦大，右寸下半指与关皆滑大，两尺俱洪大。据此中焦有痰，肝经有瘀血也。向服滋阴降火及淡渗利窍之剂皆无效，且年六十三岁，病已久，血去多，何可不兼补治？当去瘀生新，提清降浊。用四物汤加杜牛膝补新血亦祛瘀；桃仁消其瘀血；枳实、贝母以化痰；山栀仁以降火；柴胡升提清气。二十剂而诸证渐减，再以滑石、知母、黄柏各一两，琥珀、小茴、肉桂各一钱五分，元明粉三钱，海金沙、没药各五钱，茅根汁熬膏为丸。每服一钱，空心及晚茅根汤送下而愈。", "4276": "俞按：治淋如文垣诸案，经也；此案之治法，权也。经权合宜，皆审脉以为辨。庄子云：匠石觉而诊其梦。梦何以诊？诊之为言审也。向来但云诊脉，未达诊字之意。不知善诊即是善审，审得明白，病自显然。推之望、闻、问、切，素称「四诊」，可见四件都要细审也。", "4277": "李士材治袁启莘平素劳心，处事沉滞，时当二气，小便不通，用六一散不效，再用苓、泻、木通、车前等又不效。李诊脉两寸洪数，知为心火刑金，故气化不及州都也。用黄连、茯神、牛膝、人参、麦冬、五味，一剂而愈。", "4278": "孙文垣治南都大司马衷洪溪，冲暑理事，致发热燥渴，因食冰浸瓜梨新藕，（杨曰：又伤中气。）遂成泄泻，小水短少。医以胃苓汤加滑石、木通、车前子利之而泻止，（杨曰：去湿热而未照顾中气。）大便又因之结燥，艰涩不堪，乃用润肠丸，复泻不止，又进以前通利之剂，泻虽止而小水不能流通直遂，脐下胀急，立起解之，则点滴不出，卧则流之不竭。（杨曰：通利太过，则中气愈陷。）以频取溺壶，致通宵不寐。治半月余而精神削，寝食废，诸医俱不识。将认为癃，则立解时点滴不出；认为闭，则卧时涓涓而流。谓气虚下陷，心血不足，而补中益气与安神丸服皆无效。孙诊之两寸短弱，关缓大，两尺洪大。曰：此余暑未解，而素善饮，湿热流于下部也。今已下午，恐脉未准，俟明早细察定方。司马曰：望子久矣，姑求一剂，以邀夜间一睡。孙不得已，用益元散三钱，香薷汤调服，略无进退。次早复诊，六脉如昨，思之而恍然悟曰：此由溺窍不对也。（杨曰：英雄欺人语。）司马曰：名出何书？孙曰：《内经》云：膀胱者，脬之室也，脬中湿热下坠，故立解而窍不对，小水因不得出；卧则脬不下坠而溺渗出膀胱，亦以窍不对，虽涓涓而流，终不能通达直遂，故了而不了也。治惟提补上、中二焦元气，兼清下焦湿热，斯得矣。又有一法：今气虚下陷已久，一两剂未能取效，安得睡耶？但此不寐非心血不足，因著意防闲小便而不敢寐也。暂将布袋衬于席上，任其流出而不必防闲，免取溺器，自然能寐矣。方用补中益气汤加黄柏、知母，如法果愈。", "4279": "俞东扶曰：此证脉实者八正散倍大黄，或倒换散亦妙。若形弱及老人，或病后、产后有此，悉从虚秘治，润燥养阴为主，下用导引法。（雄按：未尝无实证，须以脉候参看。）若体健神旺，二便秘涩者，必脾胃气滞不转输，加以痰饮食积阻碍浊道，脉沉实者，升柴二陈二术汤。他如王中阳治一人，九日便溲俱不通，用外治法；及李濒湖治外甥柳乔案，并皆佳妙，可与东垣滋肾丸相为鼎足。", "4280": "高果哉治温体仁初谢政归，患大便燥结不通，胸膈塞闷而有食，肾脉沉小而无神，以枳壳五钱，苁蓉二两洗净，水煎服即效。后又秘结，以当归、生首乌大剂煎服，遂全愈。", "4281": "雄按：此证虽与姜宜人相似，然彼成于渐，此起于暴；彼为血枯，此为气错。病机大不同也。魏柳洲谓姜病宜用集灵膏以濡其血，而大肠之故道可通。余谓此证初宜理气，继则亦当参以濡阳明之燥。盖气错既久，则血液不能循经而下，润于大肠也。润其肠可冀大便渐通，纵不能渐通，则润药频溉，粪必稀溏，虽从溺窍而出，亦可减其痛苦。观仲圣治阴吹用猪膏发煎，其义自见。盖转矢气之由前阴而泄，实因大肠之燥，而转趋于前也，当时王、叶、薛诸公，不知用何治法，然其败也。小便顿闭，逆涌而从鼻出，则渐延枯燥可知。喻氏所谓有肺者有溺，无肺者无溺。鼻为肺窍，肺为水之上源，而大肠者，肺之府也。大肠既久闭而不用矣，府不通则藏不安，藏不安则失其肃化之权而不降，肺不降则水源绝而溺闭，遂致溃败决裂，而溺由鼻涌以死也。丁未春，一童子十余岁矣，登梯失足，堕骑梯档，扶而下，寻患小便不通，少腹渐以痛胀，多医治之，溺仅滴沥如癃。既而于肛前囊后之间，另辟一窍，溺杂脂血涓涓而漏。自此溺窍复闭，而别无痛苦，仍能饮食。惟形日尪羸，以血液杂溺而漏泄也。数月后始就诊于余，已脉细色夺，奄奄一息，不能措手矣。又阅半月而毙。此与金缝人病因相同，而见证稍别，皆由卒然震跌，经气错乱所致。张承溪所谓气亦有错经妄行者，故便溺遂失其故道也。", "4282": "孙文垣治蔡乐门令眷，头痛如破，发根稍动，则痛延满头，晕倒不省人事，逾半时乃苏，遍身亦作疼，胸膈饱闷，饮汤水停膈不下。先一日吐清水数次，蛔虫三条，原为怒起，今或恶风，或恶热，口或渴或不渴，大便闭，脉则六部皆滑大有力。孙曰：此痰厥头痛也。先以藿香正气散止其吐，继以牛黄丸、黑虎丹清其人事，头仍疼甚；又以天麻、藁本各三钱，半夏二钱，麻黄、薄荷、白芷、陈皮、生姜、葱白煎服，得少汗而头痛少止，至晚再服之，五更痛止大半，而人事未全清。孙谓此中焦痰盛，非下不可。乃用半夏五钱，巴霜一分，面糊丸，每服三十丸，生姜汤送下。午后大便行三次，皆稠黏痰积也。由此饮食少进，余证差可。惟遍身仍略疼，改用二陈汤，加前胡、藁本、薄荷、黄芩、石膏、枳壳、石菖蒲，调理而安。", "4283": "僧慎柔治一贵介，年三旬，因齿痛服石膏三钱，即满头皆肿痛，牙龈上腭肿势尤甚，天明稍退，盖得阳气故也。诊之右关细涩，左关洪，左尺亦涩。曰：此须纳气下达，方得脉和。定方名羌活散火汤。（杨曰：既欲纳气下达，何故又参入风药。）酒炒羌活五分，防风三分，酒连一分，酒芩二分，茯芩一钱，人参二钱，甘草五分，半夏一钱，破故纸一钱，枸杞一钱。二剂脉渐粗大，是阳气下行矣。头痛稍止，可见前因下焦无阳，阴火上冲而痛剧也。服至八剂，头痛全止，龈肿未退，脉则渐和。曰：将愈矣，此阳气已至恙所。果四五日出脓少许而瘳。", "4284": "俞按：《类案》谦甫治柏参谋是气虚头痛，戴人治一妇偏头痛五七年是积热头痛，立斋治刘尚宝是肝火头痛，士材治蒋恬庵是肾虚头痛，文垣案是痰厥头痛，慎柔案是阳升不降头痛。六种之外，又有因风痛者，抽掣恶风，鼻塞眼胀；因寒痛者，恶寒战栗，面惨肢冷；因湿痛者，痛而且重，天阴转甚，或四肢疼重，面目浮肿。此皆外因也。（雄按：暑热为痛，亦是外因也。）内因则气虚之外，血虚更多，积痰之外，积食亦有。丹溪云：肥人头痛，多是湿痰；瘦人头痛，多是血虚有火，斯诚要言。然因虽数端，靡不兼风，无风入，但作眩，不作痛也。（雄按：外风由于风入，内风由于火升，若内风及暑热头痛，均忌风药。）故古方中川芎茶调散、大追风散，颇易取效。痛久则成头风，其方更繁，不能缕述。真头痛乃死证，外灸百会穴，内进参附汤、黑锡丹，或冀挽回，实未试验。寻常头痛亦有死者。高阳生云，头疼短涩应须死，生平曾见之矣。头与腹俱痛有五证：臭毒、伤酒、伤湿、不伏水土、疮毒入腹也。有头痛止则腹痛，腹痛止则头痛，此属脾阴虚，胃火随气上下，芎、归、芍药、木香、香附、黄连、葱白。又有头痛诸药不效，其痛更甚者，或因督脉为病，宜用茸珠丹，或香茸八味丸。复有雷头风，另是一项，乃内郁痰火，外束风热。大头风即大头瘟，或痛或不痛，或溃或自消，死生反掌。至于眉棱骨痛，系足少阳风热与痰，最能伤目。若两耳出脓则危矣，宜以浓茶一碗探吐之，次用清上药，如选奇汤、清空膏之类。妇人注目针绣，往往眉骨酸痛，此宜滋阴养血。", "4285": "俞按：二人脉象俱是虚寒，而皆以湿热治者，上条屡服热药不效，且年久饮食无碍，大便或秘或泄，知其为停饮也。后条以胸前畏热喜凉，及脉沉细涩为据。所谓稍重则绝者，以细涩故也，与阔大而软之虚寒不同矣。故加黄连、滑石。遍观丹溪案，凡脉弦细涩者，俱不用温药，想其阅历多而认得真也。", "4286": "雄按：还当以脉象别证兼参，未可谓未申时之痛厥，即是瘀滞膀胱，而可用峻药也。读者慎毋印定眼目。", "4287": "吴人峰之室，胃脘作痛，两胁胀急，痛一阵则汗出一番，两颧红，唇口亦红，饮食入口即吐者三日夜矣。孙文垣诊之，两寸脉洪大，两尺沉微。孙以井水半碗，百沸汤半碗，名曰阴阳汤，调元明粉一钱五分服之，不惟不吐，痛减半矣。少顷大便行三次，因食豆腐及粥太早而痛复作，唇脸皆红，此必有虫，故如是也。与桂枝、白芍、甘草、乌梅、川椒、五灵脂、杏仁，水煎服，痛定大半，再以苍术、厚朴、山楂、枳实、茯苓、延胡、香附，一帖痛全止。但心背皮肤外疼，不能著席而眠，以芎、归、苓、术、橘、半、厚朴、腹皮、香附、甘草，调养全愈。", "4288": "俞按：小腹痛甚大汗，脉如循刀责责，昧者必认为真脏脉矣。否则认其病因是寒，惟用桂、附耳。丹溪连以温药下之，殊不可及。最难者，痛止复作，不改前方，陡加桃仁，迨瘀下痛止，仍不改前方，又加附子。至愈后伤食复痛，忽变前方而用建中，总由指下认得真，故攻补毫无疑惑也。虞天民治一人冬月入水网鱼案，因受寒深重，又误于寒下，故先投温补及艾灸，而后进温下之药，与此皆确切不移，彼此难换。若认脉不清，必至两误。", "4289": "俞按：尺脉沉实，则为下焦结粪。今两尺绝无而断结粪，又见取脉之巧，非出一途。若死血则脉必涩，前已历载多案矣。", "4290": "俞按：跌伤有瘀，似宜先逐瘀而后补。丹溪则以年之老，脉之散大，反先补而后逐瘀，是其学问之高也。昧者必以为补住恶血，惧不敢补，则尽力逐之，瘀终不去，而变端起矣。损伤且然，况内伤乎！观此案及叶先生痢疾案，而知补住邪气、补住恶血之为谬谈也。大抵元气果虚，则补药惟元气受之，而或邪或瘀不相干涉，或元气不虚，则补药为邪助长，为瘀增痛，诚非所宜，要在能辨其虚与不虚耳。", "4291": "李士材治方鲁儒精神困倦，腰膝异痛不可忍，皆曰肾主腰膝，而用桂、附。绵延两月，愈觉四肢痿软，腰膝寒冷，遂恣服热药，了无疑惧。李诊之，脉伏于下，极重按之，振指有力。因思阳证似阴，乃火热过极，反兼胜己之化，小便当赤，必畏热汤，询之果然。乃以黄柏三钱，龙胆草二钱，芩、连、栀子各一钱五分，加生姜七片为向导，乘热顿饮，移时便觉腰间畅快，三剂而痛若失矣。用人参固本丸，日服二两，一月而痊。", "4292": "俞按：瘀血腰痛，古人原有治法。而想到行房时肾摇血即不瘀，岂非明哲乎？然行瘀多用肉桂，此反用知、柏，岂于脉中见相火之强耶？", "4293": "汪石山治一人年逾三十，季夏日午行房多汗，晚浴又近女色，因患白浊，医用胃苓汤，加右眼作痛，用四物汤入三黄服之，睡醒口愈加苦，又加左膝肿痛，仲冬不药浊止，渐次延至背痛不能转侧，日轻夜重，嚏则如绳索撮腰胁，痛楚不堪，呵气亦应背痛，时或梦遗。次年正月，汪诊之，脉皆缓弱无力，脾虚可知，左脉滑者血热也，遂以参、耆各二钱，苓、术、归身、麦冬各一钱，牛膝、神曲、陈皮、黄柏各七分，甘草、五味各八分。煎服三十余帖，再以龟板、参、耆、黄柏各二两，熟地、萸肉、枸杞、杜仲、归、茯、牛膝各一两，丸服而愈。", "4294": "俞按：汪案养阴益气，卢案补精搜风，祝案汗下以通经，温纳以固肾，俱真实学问，非肤浅伎俩。再论背属太阳，若暴痛，则审其脉浮紧为伤寒，脉沉缓为寒湿，麻黄汤、羌活胜湿汤可酌用也。脊系督脉，若久痛，则审其热而痛为阴虚，寒而痛为阳虚，麋茸六味、鹿茸八味，可分用也。若肩背痛则兼肺经，腰背痛则兼肾经，又当各求其因而治之。更有胸与背互换作痛，项与背牵连作痛，背痛彻心，心痛彻背，散在诸书，均宜博考。", "4295": "俞按：胁下结硬如石，的系积块，若宗养正积自除之说而用参、术，何异助纣为虐耶？幸遇戴人以涌法起其沉疴，亦赖脉之沉实有力耳。因知善于切脉者，则如礼乐与干戈，俱能戡乱致治也。", "4296": "孙文垣治李悦斋夫人，胸胁大腹作痛，谵语如狂，寅卯辰三时少轻，午后及夜，痛剧咬人，昼夜不睡，饮食不进者十八日。究其故，原有痰火与头疼牙痛之疾，又因经行三日后头疼发寒热，医以疟治，因大恶热，三四人交扇之，而两手浸冷水中，口噙水而不咽，鼻有微衄，又常自悲自哭，目以多哭而肿，小水直下不固，喉梗梗吞药不下，脉则左弦数，右关洪滑。孙曰：热入血室也。误服刚燥之剂而动痰火，以致标本交作。诸人犹谓热入血室，惟夜间讝语如见鬼，何至胸胁疼剧咬人耶？孙曰：仲景云，经水适来适止，得疾皆作热入血室治。痛极咬人者，乃胃虚虫行求食而不得，故喉中梗梗然也。以小柴胡加桃仁、丹皮而讝语减，次日以安蛔汤与服，而疼止食进。", "4297": "施笠泽治张侗初患足胫痛三年矣。诊之脉沉细而涩，曰：此下焦元气不足，不能荣养筋骨，当用滋补舒筋之剂。服后微效。因劳旋作，再诊之脉兼浮数，元气愈耗矣。为制人参膏，及河车天乙丸间服，元气渐壮，独两胫作楚不能忍，因制万灵膏，去樟脑加韶粉、苏合、麝香，以软帛紧系两胫，仍令饮甘草汤，不顷刻而痛若失。此膏良验，方载《本草纲目》。后用黄耆建中汤加参、归，调理全愈。", "4298": "罗谦甫治一妇，三十余岁，忧思不已，饮食失节，脾胃有伤，面色黧黑不泽，环唇尤甚，心悬如饥，饥不欲食，气短而促。罗曰：人身心肺在上，行营卫而光泽于外，色宜显而不宜藏；肾肝在下，养筋骨而强壮于内，色当隐而不现；又必赖脾胃在中，传化精微以灌四旁，冲和而不息。若其气一伤，则四脏失所。今忧思不已，脾胃气结而不行，饮食失节，脾胃气耗而不足，故使阴气上溢于阳中，而黑色见于面。又经云：脾气通于口，其华在唇。今水反侮土，故黑色见于唇，此阴阳相反，病之逆也。「上古天真论」云：阳明脉衰于上，面始焦。可知阳明之气不足，乃用冲和顺气汤，以葛根一钱五分，升麻、防风各一钱，白芷、黄耆各八分，人参七分，甘草四分，白芍、苍术各三分，以姜枣煎，己午时前服，取天气上升之时，使人之阳气易达也。数服而愈。此阴出乘阳治法也。", "4299": "丹溪治一女子，十七八岁，发尽脱，饮食起居如常，脉微弦而涩，轻重皆同，此厚味成热，湿痰在膈间，复因多食酸梅，以致湿热之痰随上升之气至于头，熏蒸发根之血，渐成枯槁，一时脱落。治须补血升散，乃用防风通圣散去硝，其大黄酒炒三次，兼以四物合作小剂与之。月余诊其脉，知湿热渐解，乃停药，淡味二年，发长如初。", "4300": "孙真人奉旨治卫才人眼疼，前众医不能疗，或用寒药，或用补药，加之藏府不和。孙诊之，肝脉弦滑，非壅热也，乃年壮血盛，肝血并不通遂，问宫人月经已三月不通矣。用通经药，经行而愈。", "4301": "俞按：肝脉弦滑，能不误认为风痰病眼乎？因肝藏血而知其血盛不通，诚切当矣。然犹问宫人，始得停经三月之信，并不先言据脉当停经也。真人尚如此，奈何讳疾者，每不言以责其断病耶？此正犯东坡所云：我欲困医，而我病亦适为医所困耳。", "4302": "孙东宿治孙如亭令正，年过四十，眼偶赤肿，两太阳疼痛，大便不行者三日。平时汛期一月仅两日，今行四日未止。眼科治之，逾候肿赤不消，而右眼内眦突生一白疱，垂与鼻齐，大二寸余，医见而骇走，以为奇疾，莫能措剂。又见其呕吐眩晕，伏于枕上，略不敢动，稍动则眩愈甚，吐愈急，辞不治。孙诊之：两寸关脉俱滑大有力，两尺沉微。孙曰：此中焦有痰，肝胆有火，必为怒气所触而然。《内经》云：诸风掉眩皆属于木；诸逆冲上皆属于火。盖无痰不能眩也。眼眦白疱，乃火性急速，怒气加之，气乘于络，上而不行，故直胀出眼外也。古壮士一怒而目眦裂，与白疱胀出理同。肝为血海，故血亦来不止。治当抑其肝木，清镇痰火，则诸证自瘳。先用姜汁益元丸压其痰火，以止呕吐；再以二陈汤加酒连、酒芩、天麻、滑石、竹茹、枳实、吴茱萸。一帖眩吐俱定，头稍能动，改用二陈加芩、连、谷精草、夏枯草、香附、苡仁、吴茱萸。四剂目疾全愈，血海亦净。", "4303": "李昆阳治许某初起外感发热，继则左耳门生小疖溃腐，认为聤耳，敷以药，溃腐不退，通耳肿赤，延及头面皆肿赤痛极，汗大出，身热反得凉，颇能进食，似觉稍安。越三日，忽又发热，左耳前后连头面肿痛更甚，渐神昏谵语，盖因连日出门登厕，复受风邪所致。内外科皆以脉小而数，按之无力，虑其虚陷。李曰：此耳游风也，非致命之疮，重复冒风，故现险象。外敷以药，内用大剂风药散之，而肿痛身热俱退，惟神昏谵语不减，两日后昏谵更甚，汤粥入口即吐，手足厥冷，呃逆不止，势又危极。李以箸抉其口视之，则咽喉腐烂，悬雍赤紫，肿大如茄子下坠，脉仍细数，右手尤软。乃曰：连日不食，胃气大虚，故呕且呃，命以白米三升淘净，大锅煮粥，取锅面团结之粥油与食，（雄按：赵恕轩云：粥油能补人精。）遂纳而不吐；复用药搅洗喉间之腐秽，（雄按：以锡类散糁入更妙。若未腐者，诸葛行军散亦佳。）随以石膏四五两，竹叶一大把煎汤与漱且服，服之竟夜，神昏始醒，呃止厥回。又进大剂芩、连、白虎、栀、翘等药，数日而全愈矣。", "4304": "俞按：此与景岳治王蓬雀案，冰炭相反。然蓬雀能受温补，故一剂即效。亦有证如蓬雀，虽投温补而不效者，即阳证阴脉之死候也，未可谓景岳之法概能活人。况许证之脉虽软小，而病非格阳，设从景岳之言，尚待问哉。故为医者，读古人书，断不可执其一说，自以为是也。", "4305": "俞按：此案医理讲得最精。由于脉象诊得的真，而更运以巧思，斯发无不中矣。清胃散之庸，诚不足责，即泛用滋阴药，亦难应手。只此三味，诠解甚明，信乎缺一味不可，多一味不必也。余乡有患齿痛数年，诸药不效者，叶天士先生用山萸肉、五味子、女贞、旱莲各三钱，牛膝、青盐各一钱而全愈。此取酸咸下降，引肾经之火归宿肾经，可与易公之方并垂不朽，而其义各别。", "4306": "仲淳曰：顾仲恭遭鼓盆之戚，复患病在床。一医诊视，惊讶而出，谓其旦晚就木，因延余诊之，左手三部俱平和，右手寸尺亦无恙，独关部杳然不见。谛视其形色，虽尪羸而神气安静。余询之曾大怒乎？曰：然。余曰：此怒则气并于肝，而脾土受邪之证也。经云大怒则形色绝，况一部之脉乎？甚不足怪。第脾有积滞，目中微带黄色，恐成黄疸。后果遍体发黄。服茵陈利水平肝顺气药，数剂而痊。", "4307": "俞按：《金匮》云：病疸当以十八日为期，治之十日以上瘥，反剧者为难治。就余生平所验，分毫不爽。有先因他病而后发黄者，有先发黄而后现他病者，必于半月一月之内退尽其黄，则他病亦可治。设或他病先瘥而黄不能退，至一年半载仍黄者，必复现他病以致死。大抵酒伤及有郁结与胃脘痛，皆发黄之根基，而泄泻肿胀不食，乃发黄之末路。若时行病发黄，亦多死证，谚曰瘟黄也。惟元气实者，审其为瘀血，为湿热，逐之清之，得黄退热亦退乃可无虞。古人医案，俱未有说及久黄者，可为余言之一证。即如此条关脉不见，亦云数剂而痊，要知因于大怒，偶然不见耳。若并未动怒，关脉连日不见，目中微带黄色，即为脾绝之征，死无疑矣。", "4308": "俞东扶曰：麻多在于手足者，以四末道远气馁，则卫行迟而难到也。故麻不兼木，必属气虚，否则风痰。凡脉浮而软，或大而弱者，气虚也；脉浮而滑，按之不衰者，风痰也。若麻木兼作，则有寒湿、积痰、死血之殊，其脉有沉迟滑实与沉涩而芤之分矣。", "4309": "祝茹穹治闽闱典试，半月前忽腿疼，两脚筋缩，脚根缩黏至腿，寸步不能行，将一月，屡药无效，咸以此为痿痹证。祝曰：非也。察其脉左寸忽洪忽涩，迟数无定栖，因其好饮冷酒，酒新则性热燥，冷饮又犯寒湿，寒热相搏，遂有此病。乃以川乌二钱去皮脐，麻黄二钱，两股梢，一股根，苍术一钱，以甘草汁拌炒，白蒺藜一钱，去刺，酒蒸熟焙干。同为末，每服一钱二分，用老酒热服，盖被出汗。一服即能行动，三服而痊。", "4310": "叶天士治嘉善周姓，体厚色苍，患痛风，膝热而足冷，痛处皆肿，夜间痛甚，发之甚时，巅顶如芒刺，根根发孔觉火突出，遍身躁热不安，小便赤涩，口不作渴，脉沉细带数。用生黄耆五钱，生于术三钱，熟附子七分，独活五分，北细辛三分，防己一钱五分。四剂而诸证皆痊，惟肿痛久不愈，阳痿不举。接用知、柏、虎膝、龟板、苁蓉、牛膝不应。改用乌头、全蝎各一两，穿山甲、黄柏各一钱，防己一两五钱，麝香三钱，生马料豆二两，茵陈汤泛丸，每服一钱，开水下而愈。", "4311": "俞按：香为脾臭，何以蚀脾？意者香能开窍，香极则诸窍大开，脉缓筋弛，关键尽撤，故身软目瞪不食也。畀入土坎者，诸毒得土而化。且土为万物之母，四肢百骸得土气，则生气自复也。仍合治痿独取阳明之义。", "4312": "雄按：香能开窍，气太发泄，发泄既久，脾气乃虚，故曰蚀也。盖脾胃主四肢，不但脾虚四肢不用，胃实亦有之。（杨曰：凡病虚实寒热，俱有对待之证。）余治朱茂才疟愈之后，已服补剂，且能食肉，忽然卧床不起，四肢痿痹，不能自食，目瞪不语，医治四日，病如故。余诊之，脉弦细而软，苔薄微黄，大便不行，察其胸腹皆柔软，神气亦清，耳不聋，与之食亦食。此补之太骤，痰阻枢机，气郁不舒，非痿症也。予菖蒲、远志、胆星、枳实、茯苓、半夏、竹茹、橘皮、旋覆为方，芦菔汤煎服。一剂而更衣起榻，谈笑如常。故余先曾祖《随笔》中谓治痿独取阳明，不专指虚证说。由此推之，即中气不足，溲便为之变，亦不可泥不足为虚也。如湿热痰食，皆能阻滞脾胃，而中气窒碍，不足转输，致溲便变其常度，岂可概视为虚证乎？故读书必悟两面，临证庶免执一。", "4313": "俞按：此三案精妙绝伦，以药对脉，确切不移。首案连用承气，继用参汤送寒下药，皆是独取阳明治法。末案补中益气与大黄补泻不同，总归乎取阳明也。", "4314": "又按：《临证指南·痿门》首列轻清治肺二方，实宗肺热成痿之旨。第恐力薄难效，其用二妙、茵陈、萆薢、茯苓皮、蚕砂、海金沙、防己、龙胆、寒水石等，直清湿热，较之清燥汤反胜一筹，不涉虚者，允宜仿此。又有治下虚上实，而用犀角地黄汤去芍药，加元参、连翘、桑叶、钩藤，似乎专理上实，不顾下虚。然云头目如蒙，入夏阳升为甚，议清营热以息内风，想其人脉必弦数，有热甚生风之象，未可兼顾下虚，或他日再诊而后滋填下焦，亦未可知。至于滋填下焦方，有用虎潜加减者；有用四物金刚健步及地黄饮子加减者；有用熟地、苁蓉、巴戟、远志、鹿角霜、桑椹、苍术、小茴，以狗脊酒蒸，熟水熬膏为丸者；有用苁、戟、杞、膝、青盐、线胶、茯苓、沙苑、鹿筋胶、羊肉胶、牛骨髓、猪脊髓者，却元参、术补阳明法，亦无承气泻阳明法。惟脾肾双补丸有人参，然其案重在晕麻瘕泄，尚未痿厥，非以治痿也。统观之，不外清湿热、益肝肾，岂二种病情偏多耶？或案有遗逸，未能详备耶？", "4315": "张三锡治一少年，体薄弱，且咳血，左边一块，不时上攻作痛，左金、芦荟俱不应，诊其脉三部虽强，而细涩不流利，因作阴虚治，四物加知、柏、无参、丹皮。不六剂顿愈。此阴虚似肝积也。虽因部分名积，诊视之际，尤当详审，惟圆机者乃不昧此。", "4316": "俞按：此人克伐太过，换以温补，未足为奇。惟两尺脉洪盛，非此诠解，谁不面墙？至于桂、附、河车，同补肾药为善后计，则与肾气传膀胱之论，紧切不泛，非通套治痞成法可比。", "4317": "李士材治于鉴如，每酒后腹痛，渐至坚硬，得食辍痛。李诊之，脉浮大而长，曰：脾有大积矣。然两尺按之软，不可峻攻，令服四君子汤七日，投以阴阳攻积丸三钱，但微下，更以四钱服之，下积十余次，皆黑而韧者。察其形不倦，又进四钱，于是腹大痛，所下甚多。仍服四君子汤十日，又进丸药四钱，去积三次，又进二钱，下积六七碗，脉大而虚，按至关部豁如矣。以补中益气汤调补一月而痊。", "4318": "俞按：脉浮大而长，为脾有大积，较之丹溪诸案，或沉涩而小且数，或微而短涩，或虚微短涩，或脉涩而弱者，大不同矣。须于临证时，能以古人各种脉法，俱为我之正鹄，庶期中的。若两尺按之软，不可峻攻，固是正理，然亦要看得灵变。盖两尺软为虚，则喻按之两尺洪盛，宁不认为实而峻攻之耶？故又当以色形及病情参讨也。", "4319": "又治侯启东腹中嘈痛，按其左胁，手不可近，凡饮食到口，喉间若有一物接之者。然脉大而数，腹痛呕涎，面色痿黄，此虚而有湿，湿热相兼，虫乃生焉。当煎人参汤送槟黄丸以下虫积，虫若不去，虽补何益乎！病者畏不敢用，后竟不起。", "4320": "周慎斋治一妇素善怒，左胁下有块，身肥大，经将行，先一二日必吐下，此肝木乘脾，脾虚生痰不生血也；善怒胁块，肝气亢也；吐下者，脾气虚也。身肥则多痰，痰盛者中焦多湿，故经行时气血流通，冲动脾湿，且吐且下也。久而不治，必变中满。宜理脾燥湿：白术一两，半夏五钱，生姜七钱，沉香二钱，共研末，白糖和服。又一人左胁下有块，右关脉豁大。用乌药一两，以附子五钱，浓煎制透，将乌药日磨二三分，酒送下。俟积行动，乃以补中益气汤加附子服之。后用六君子丸服全愈。", "4321": "俞按：消积之方，如桃仁煎，用大黄、虻虫、芒硝；黑神丸，用生漆、熟漆；东垣五积丸，俱用川乌、巴霜；局方圣散子、三棱煎丸，俱用硇砂、干漆。此皆峻厉之剂，用而中病，固有神效；若妄试轻尝，鲜不败事。千金硝石丸，人参、硝黄并用，丹溪犹以为猛剂。治婢一案，每与补药迭进，此真善治病者也。丹溪治积聚诸案，轻重曲折，适至病所。如治方提领，用参、术、归、芍等煎汤，下保和丸二十五，龙荟丸十五。治冯氏女，先用左金丸、青六丸，复用参橘桃芍丸。治卢子裕疟后食酒肉而成块在左胁，用参、术、柴、苓、枳壳煎汤，下阿魏五、保和十、抑青十、温中五、攻块五。攻块者，青皮、三棱、桃仁、桂枝、海藻，醋调神曲为丸也。治下邳钱郎，用保和二十、温中二十、抑青十，以白术、木通、三棱汤下。此等方法，皆补药与磨积相半，而必兼清肝之药，大抵因怒成块者多也。又治陈里长男，饱食牛肉豆腐成块在右胁，脉弦而数，即明告以此人必性急，块上不可按，按则愈痛，痛则必吐酸黄苦水，而用荔核、山楂、枳实、山栀、茱萸、人参、姜汁以止痛，继用皂角煎汁制半夏合黄连、石碱，用糖球膏为丸以消块，仍是治肝为主，磨积为助。学者能逐案细绎，自有悟处。再阅叶案积聚门，只用鸡肫皮、莱菔子、蛤粉、芥子、蜣螂、蟅虫、青、朴等，并无古方狠药，其理尤可想见矣。又余目击杭州一妇患痞块，用黑神丸大效，每痛作呕胀不堪，服此即愈，数十服后，百苦皆除，半年外以他病暴亡，因思漆身为癞之言，藏府岂能常漆耶？清纯冲和之气，耗丧于此药而不觉也。再按阿魏丸方甚多，如《医林》阿魏十四味，内有石碱、风化硝；小阿魏丸七味，乃棱蓬、胡椒、青皮、木香、麝香；《心统》消积阿魏丸，共八味，内有三棱、莪术、牵牛、穿山甲；丹溪阿魏丸治肉积者只四味。又《医林》小阿魏，即丹溪治陈星长男之三味，欲无阿魏，犹之琥珀膏只大黄、朴硝各一两为末，以大蒜杵膏贴之，并无琥珀也。总须对证择用耳。", "4322": "俞按：《巢氏病源》以肾间动气为人之根本，故老年能御女，七十岁至八十岁犹生子者，其动气之禀于生初者独厚也。厚则刚，阳自不痿。亦有未老而阳即痿者，必不能至大寿，须任其自然，绝意淫欲，尚可延龄。设以兴阳药内服外洗，求为御女之事，不数年而死矣。若壮年无病而阳痿，其人多夭。少年虚损而阳痿，其死立至，皆由肾间动气早衰也。动气即命门真火，所以生长元气，煦燠元阴，故气曰阳气，精曰阳精。其盈亏俱得于先天，盈者虽斫丧而无伤，亏者虽葆养而不足，并非药石所能扩充。乃扁鹊新书载王超老淫故事，而云保命之法，灼艾第一，丹药第二，附子第三，此说荒唐，断不可信。又考宗筋聚于前阴。前阴者，足之三阴，及阳明、少阳、冲、任、督、𫏋九脉之所会。而九脉之中，阳明为之长。《内经》云：阳明者，五藏六府之海，主润宗筋。（雄按：经言有极可征者，如马之鼻黑者，阴茎亦黑；若鼻白者，阴茎必白。盖鼻虽为肺窍，而位镇中央，实阳明脉之所钟也。）所以胃强善啖之人，其于欲事必强，反是则痿而不举，或举而不坚，是胃气能为肾气之助。古云：精生于谷。又云：男子精盛则思其色。其道理可喻矣。新书之言，不过如宋人揠苗耳，况丹药之害，可胜言哉！", "4323": "俞惺斋治一人脱肛，肿痛出水，尺脉洪数，用樗根白皮、川柏、诃子肉、没石子、鳖头灰而愈。其人好酒形实，乃湿热下注，非气虚下陷也。", "4324": "俞按：饮薄粥一碗，必吐水半碗，卧不能起，将认作大虚证矣。其辨在于痞塞及经停之前，虽通而黑色也。此怒火食积，郁成湿热，上则饮停，下则瘀阻，实证似虚耳。辰时寸关脉滑有力者，辰为气血注胃之时，胃满甚而连及上焦；午后惟关脉滑，独显胃实之象矣。方主消痰消食，破气破血，加黄连、滑石以清湿热，仍兼人参以鼓舞胃气，使诸药得行其疏通之力，再佐姜汁之辛以开道路，又治呕吐，此真纪律之师，有胜无败者也。然犹有病深药浅之虑，隔三日以二丸微下，则直捣贼巢，病根可拔矣。", "4325": "俞按：人有一手无脉者颇多，若两手无脉者则少，此乃母胎中或襁褓时蹙锉其经隧，致脉不通，原非病也。石山又诊一妇，左手无脉，而动于腕臂外廉阳谿、偏历之分，是即今所谓反关脉也。汪乃曰：左脉离其部位，其病难以脉知。诚然，反关脉多洪大，且可推动，果不足以审病情。又丹溪治一妇，久疟食少经闭，两手无脉，每月以三花神祐丸十余粒，津咽之，月余食进脉出，又半月脉愈，又一月经行，此则因病而无脉，非向来无脉也。", "4326": "俞按：今人称月事为天癸者谬也。经云：女子二七而天癸至，任脉通，太冲脉盛，月事以时下。又云：男子二八而肾气盛，天癸至，精气溢泻。若天癸即月事，丈夫有之乎？顾名思义，谓之天一之真水，乃精血之源头也。盖男女皆有精，《易》云男女构精可据。然指天癸谓精亦不妥，天癸为精，不该又云精气溢泻矣。后贤讲受孕之道，有阳精阴血先至后冲等说亦谬。夫男女交接，曾见女人有血出耶？交接出血是病，岂能裹精及为精所裹哉？大约两情欢畅，百脉齐到，天癸与男女之精偕至，斯入任脉而成胎耳。男胎女胎，则由夫妇之天癸有强弱盈虚之不同也。任脉督脉，皆起于前后两阴，交之会阴穴。督总诸阳，任总诸阴。任隶足少阴，冲隶足阳明，所谓冲为血海，任主胞胎也。经云前阴总宗筋之所会，会于气街，而阳明为之长。阳明水谷之精华，变化成血，以灌输太冲，太冲脉盛，月事以时下矣。既孕则血聚以养胎，不能输入太冲，故月事不下。由此辨之，任脉通而天癸至，冲脉盛而月事下，明系两项矣。", "4327": "俞按：脉大而无力，乃气虚之确据，何可指定为血虚？况麻属气虚，先哲之成言也。气虚不能摄血则崩，参、耆在所必用。惟左脉举之略弦，似有风邪，少加荆、防亦是。第其议论拖沓，借司天运气以张大其说，反觉浮泛矣。", "4328": "孙文垣治潘敬斋媳，经水不调，医投安胎之剂，越七月经水忽大行，内有血块筋膜如手大者一二桶，昏冒困惫。其脉右关洪滑，左寸洪数，两尺皆洪大。病交夜分，咬牙乱语，手心热，口噤时手足皆冷，心头胀闷不快，面色青。诸医皆谓难治，孙曰：无恐。此浊痰流滞血海，以误服安胎之药，益加其滞，血去多故神昏无依，痰迷心窍，故神昏语乱。其发于夜半者，乃热痰在心包络与胆经，故每至其时而发。为之调气开痰，安神养血可愈也。（杨曰：识力绝高。）即以温胆汤加石菖蒲、酒芩、天麻、枣仁、丹参与服，其夜证即减半，次日再服，每帖加竹茹五钱。（雄按：此经产及诸血证要药，故宜重用，即《金匮》之竹皮也。）临睡又与黑虎丹数粒，诸证悉愈。", "4329": "俞按：此证不用脱血益气之法，其察脉审证高矣。然此时著眼在昏冒胀闷等证，非血去多而犹不止也。", "4330": "施笠泽治祁君万之内崩中，服地榆、续断等药不效。诊其脉，沉而结。曰：蓄血证也，得之汛至而怒。祁曰：然。因怒经止，半月后即患崩证，今一月矣。乃用桃仁、大黄行血破瘀。或谓失血复下，不导其势乎？施曰：血随气滞，蓄积不散，壅塞隧道，溢而妄行，决壅去滞，则血自归经矣。不然舍其本而治其末，何异随流塞水耶？服二剂果下衃血，汛亦旋至。", "4331": "雄按：治病总须察脉辨证，而后议治。设泥成说，但执暴崩宜补，必致酿成锢疾矣。", "4332": "孙文垣治侄妇戴氏，孕已五月，忽血大下，午后发战，六脉俱数，左寸滑大，右关搏指，左关软弱。予以白芍二钱，生地、阿胶、人参、蒲黄各一钱，柴胡、香附、地榆、荆芥各七分，甘草五分煎服。午后发寒热，每夜凡三次，头痛恶心，腹中硬块，所下血块甚多，心下怯力，此虚无疑也。以补中益气加阿胶、炮姜、白芍、乌梅。下午右眼白珠发一白泡，先肿下垂，而面亦肿，此虚火游行无制之证。其夜大发寒热，指爪皆黑，唇白，汗大出，腹中作痛，牵引两乳皆痛。仍以补中益气加阿胶、白芍、桂枝、五味、麦冬。服后热退汗止渴除，神气少定，乃有生意。次日咳嗽而胎坠，即以独参汤继服。其夜肠鸣，泻二次，以参、术各三钱，炙草钱半，炮姜一钱，桂心、茯苓各五分，陈皮七分，莲子、大枣煎服。后因咳嗽，以四君加炮姜、五味、紫菀，调理而愈。", "4333": "俞按：恶露不下，用参、术、归、附等药而下者，生平经手颇多，然必脉象细软，口不燥渴，内不烦热，方为合治。此案不言脉象，但曰脾失其职，谅此妇平昔怯弱，以致胎堕，且连服行血催衣之药四帖，宁不反其道以治之耶？", "4334": "孙文垣治潘大司马媳，年二十五，体素弱，语言端谨，因难产伤力，继以生女拂意，后又女死悲戚，即时晕厥，醒而神思迷昧，手足瘛疭，不可诊脉，目上视。细问之，自女落地，恶露绝无，有女医时与人参干嚼，及独参汤并粥乱进，参与粥皆壅塞膈上不下，以故神昏瘛疭不已也。孙教以手于喉中探而吐之，喜其随手吐出痰饮粥药盈碗，瘛疭方定，乃与川芎、山楂、泽兰、陈皮、半夏、茯苓、香附进之，稍得睡。不虞女医又私与补药二帖，子丑时陡然狂乱，如降神之状，汉声官话，问答如流，其声壮厉，迥异平时，其家咸谓神附，禳祷百端。孙曰：此恶露不尽，乃蓄血如见鬼之证，非真有神佛相附也。以归尾四钱，川芎一钱五分，泽兰、益母、滑石等煎，和服热童便。连投二帖，狂乱少定而未除，意其胸中必有余痰作滞，前方无佐使之品，故药力未行也。大加山楂为引，恶露稍行，神思既静，嗣后稍睡片时，手足微动，或自以手掌其面，或自以手捶其胸，昏乱不息，诊其脉近虚，早间面红而光，申酉时面色白，此血行火退，故脉虚而当补矣。与人参、川芎、泽兰各一钱，当归、山楂各二钱，茯苓、陈皮各八分，卷荷叶一片，琥珀末五分，服后嗳气二声，孙喜曰：此清阳升而浊阴降矣。自兹安静，恶露行，大便通，而索粥饮矣。", "4335": "俞按：此条前半段治法不难，盖得其参粥杂进之病情，自有消瘀及消痰食之方法，但探吐法尤捷耳。畜血如见鬼，知者亦多。后半段恶露稍行，神思即静，略睡片时，昏乱不息，仍是畜血形状，乃于轻剂消瘀之中，复用人参，并不以前曾误用而畏蹈故辄，此为高手。其讲脉与面色极是，但产后谵语昏狂，有纯因于痰者，又不可不知。（雄按：《女科辑要》论之最详。）", "4336": "程石洲室，因产难子死忧闷，小腹有块作痛，下午发热，不思饮食。文垣诊之，脉右大于左者三倍，且数，与芎归汤加山楂、泽兰、肉桂。次日下午，腰腹胀痛，诘之，晌午食龙眼一斤矣，从此小腹渐胀，大便三日未行，早晨鼻衄，夜间极热口渴，脉大无绪，势甚危急。用芎、归、红花、桃仁、青皮、槟榔、莪术、山楂，水煎，调元明粉二钱。服后下结粪二枚，安而就寝，醒后进粥稍多，又复胀痛，腹大如斗，坚如石，气促不安，势危之至，乃与五灵脂、山楂各四钱，凌霄花二钱，赤芍一钱。服后大便通，腹软气定，始可进粥，渐有生气，但脉仍鼓指，此腹中积滞尚多，不可不因其时而驱去也。用山楂、大黄各三钱，桃仁二钱，桂心、红花各五分，炙草七分，煎调元明粉一钱五分，其夜下黑粪四次，热始退，上腹虽消，脐下仍大，仍以桃仁承气加山楂、滑石、红花煎服。五更大便行，脐腹胀又减，复与积块丸调理全消。是役也，女科于初起发热腹痛之时，即以常套十全大补汤投之，岂知龙眼入腹，渐渐胀开，故腹亦因之大胀，且其味甘，尤能作滞，复加地黄、参、术，宁不塞其塞哉？由是而成大坚之证。《内经》谓中满者，泻之于内。良以此夫，彼亦泥乎丹溪产后须大补气血之误也。", "4337": "马元仪治王氏妇，产后二月，神气昏倦，胸满中痛，咳嗽喘促发热，服药反渐加重，势将治木，诊脉两手沉涩兼结，曰：此胎前已有伏邪，产后气血既虚，邪益内结，法宜表里两和，使邪从外达，气从内泄，病自愈矣。用桂枝、柴胡、苏梗、枳壳、半夏曲、菔子、杏仁、广皮透邪达滞之剂，服后病势偏安，脉亦稍舒。前医尚以气血两虚，遽投生地、归、芍敛滞之品，遂致彻夜靡宁，如丧神守，不知邪结于中，反行补法，如欲盗之出而反闭其门也。急改透邪散结法，用桂枝、炮姜、黄连、枳实、厚朴、广皮等，一剂而胸满中痛之证释。复用栝蒌实、柴胡、桂枝、半夏、枳实、杏仁、苏子、桔梗等，再剂而表热喘嗽之证平。但大便不行，此久病伤津液，肠胃失养之所致也。加生首乌一两，大便得解，余邪尽去。然正气大亏，继进滋补气血之剂而安。盖病有虚邪内结，而正气积亏者，当补正以托邪，而不知者，反治邪而伤正；有正气未伤，而邪势方张者，当去邪以安正，而不知者，反用补以滞邪，虚实莫辨，多致冤沉无诉而尚不觉也，岂不谬哉！", "4338": "戴元礼治乐元忠妻，产后病惊，身飘飘如在浮云中，举目则旋转，持身不定，四肢酸软，医以安神补虚治之转甚。戴诊左脉芤涩，神色不变，是因惊致心包络积血耳，乃下血如漆者一斗遂愈。古云大实似羸者此也。", "4339": "俞按：此证必共认为虚矣。苟不辨其左脉之芤，岂能测其心包之血积耶？人但知惊是病，不知因惊而又致病，则治病无益也，可举此案，以例其余。", "4340": "金大文治一妇，产后三日发疹，细而成粒，不稀不密，用荆芥、蝉蜕、鼠黏等药，一剂头面俱退，越一日渐有回意，忽大便溏泻数次，即神昏不宁，问其所苦，曰热日渴，语言颤怯如抖出者。脉来微细数有七至，外露但欲寐，少阴证据，曰阳脱证也，属少阴。用生附子三钱，水洗熯如炒米，炒干姜八分，炒甘草一钱，炒白芍一钱半，水煎和入人溺一杯，青鱼胆汁四小茶匙，以代猪胆汁，服毕即睡，觉来热渴皆除。续用黄耆建中汤，加丹参、苏木，二帖而安。", "4341": "俞按：此证甚危，此方甚巧。若用六君而不加犀角、失笑散则不应，用犀角、失笑散而不合六君亦不应。但意度之，不凭脉象，固由汪公熟能生巧，而其病机在痰与血交涌而上，才侧身便壅绝，显系败血随痰上升。然非血气脾胃之大虚，败血何由随痰上升耶？此方所以恰对也。闭门造车，出门合辙，先生之谓欤！", "4342": "孙文垣治查景川遍身疿痤，红而焮痒，诸人以蒺藜、荆芥、升麻、葛根、元参、甘草、石斛、酒芩与之，不愈。又谓为风热，以元参、蝉蜕、羌、防、赤芍、甘草、生地、当归、升麻、连翘、苍耳。服之饮食顿减，遍身发疮，痛痒不可言。孙诊之，两手脉皆缓弱，以六君子汤去半夏，加扁豆、砂仁、薏苡仁、山药、藿香、黄耆。一服而饮食进，四帖而痛痒除，十帖疮疥如脱。", "4343": "杨曰：俱治此证之药，而服之益甚者，以未审其脉，故与其人之体气相违也。", "4344": "王宇泰治一妇，感冒风寒，或用发表之剂，反咳嗽喘急，饮食少思，胸膈不利，大便不通，右寸关脉浮数，欲用通利之剂。王曰：此因脾土亏损，不能生肺金，若更利之，复耗精液，必患肺痈矣。不信，仍利之，虚证悉至，果吐脓。乃朝用益气汤，夕用桔梗汤，各数帖；又朝用益气汤，夕用十全大补汤，各五十帖，全愈。", "4345": "经漏百日，淋带不止，是冲、任、督、带、奇经诸脉不能固摄，病在下焦。脉左关沉微而缓，右部浮。阳升于上，阴亏于下。然先以血凝成块，决非血热妄行。况食减味少，胃气孱惫，补中益气，仅升脾营，焉得药到病所？滋阴堵塞沉腻，与胃衰少谷相背。考古崩漏不止，先用《局方》震灵丹，直达冲、任以固之。继用人参汤、震灵丹续其生气，得效再为进商。", "4346": "诊脉百至，数促而芤。劳损数年，不复寒热。大汗泄越，将及半载。卧枕嗽甚，起坐少缓。谷食大减，大便不实。由下焦损伤，冲脉之气震动，诸脉皆逆。医投清热理肺，降气消痰，益令胃气戕害。昔越人有下损过脾不治之训。此寒热汗出，二气不交所致，秋半之气不应天气，肃降乖离，已见一班。生阳不发，入冬可虑。急固散越之阳，望其寒热汗出，稍缓再商。", "4347": "稚年纯阳体质，热症最多。病偏右胸高，呼气不利，肺气不能清肃。热郁内蒸，逆传膻中，致天君震动，状若痫症。夫肺主卫，心主营，二气循环于肺胃脉中。苟营卫失和，越日触遇，乃发。翁仲仁谓扶肚抬胸，为肺热壅塞。然不及周岁，未受谷食涵养，藏府柔薄，一切苦寒沉降及腻滞阴药，俱在禁例。且肺位最高，逆行心胞络间，仍从上治，抱持勿卧，令上气下行为顺，可使营卫两和。", "4348": "脉小右弦，呼吸不利，喉中有声。入夜神迷昏倦，少腹微胀，二便不爽。自言筋骨如针刺，身重难以转侧。右环跳筋纵，不能伸屈。此皆暴寒入内，周行上下，阳气痹塞。且频年交冬痰嗽，天暖自安。老年肾真衰乏少藏纳之司。水液化痰上泛、寒中少阴，则太阳膀胱之气，无以上承而流通宣化，开合失度，枢机悉阻。浊气升，痰饮逆，最忌喘急神昏。若用发散坠降，恐致伤阳劫阴。议进仲景小青龙法，乃太阳表中之里。通营卫，不耗其阳；开痰饮，不泄其气，仍有收肺逆，通膀胱之义。", "4349": "尾闾尻骨先痛，继以溲溺淋闭，兼有血瘀。夫督脉部位，隶于太阳脉络。气坠频溺、点滴不爽，分利清热愈痛。古贤每以柔剂温药，升任督之气。按经旨以治病，谅无误矣。", "4350": "新产不满百日，天暑，汗出，气泄；加以澡浴汤蒸，更助开发。阳浮上升，阴弱莫制，遂喉痒咳逆，牵连左胁，及气街背部皆痛。盖产后肝血未充，肾液未足，奇经诸脉悉皆怯弱，阴亏阳炽，血不能荣养筋脉。法当味厚质静，流护至阴之脏，兼温奇经。仿仲景阿胶鸡子黄汤。", "4351": "再诊。考足厥阴肝经，过胃贯膈，上循喉咙。因肝阴少藏，阳气有升无降。每交暮夜，咳甚如哕。戍亥乃肝阴旺时。肝阳扰胃则阳明脉衰，四肢倦怠，面色青晦。阳化内风，掀越鼓动，为肌浮偏肿。心无液养，似嘈非嘈，似痛非痛。热酿涎沫，吐出复聚。余不以咳嗽为治，急于流护至阴，静制风阳内鼓，夜分更以胃药助之。", "4352": "据述久有胃痛，当年因痛吐蛔，服资生丸，消补相投；用八味丸，温润不合。凭脉论症，向时随发随愈。今病发一月，痛止，不纳，口味酸浊。假寐未久，忽躁热，头汗淋漓，口不渴饮。凡肝痛，必犯胃府，且攻涤寒热等药，必先入胃以分布。药不对病，更伤胃气。胃司九窍，清浊既乱于中，焉有下行为顺之理？上下不宣，状如关格，但关格乃阴枯阳结，圣贤尤以为难。今是胃伤困乏，清阳不司旋运，斯为异岐。不必以寒之不应而投热，但主伤在无形，必图清气宣通，则为善治程法。金匮大半夏汤。", "4353": "诊脉左数微弦，寸、尺、关虚数。阅五年前，病原左胁映背胀痛，不能卧席。曾吐瘀血、凝块、紫色。显然肝郁成热，热迫气逆血瘀，虽经调理全愈，而体质中肝阴不充，肝阳易动。凡人身之气，左升主肝，右降主肺。今升多降少，阴不和阳。胃中津液，乏上供涵肺之用。此燥痒咳呛，吐出水沫，合乎经旨：肝病吐涎沫矣。肝木必犯胃上，纳谷最少而肢软少力，非嗽药可以愈病。此皆肝阳逆乘，实系肝阴不足。仲景云：见肝之病，先理脾胃。俾土厚不为木克，原有生金功能。据述凡食鸡子，病必加剧，则知呆滞凝涩之药，皆与病体未合。", "4354": "病已十余日，身尚躁热，舌苔黏腻，神呆目定，脉刚而数，烦躁呓语。此暑湿久伏，与时气之秽邪凝合，酿成胶腻之痰，闭塞清明之府，神情迷昧，胃家浊液，蒸遏不宣。药食甘味，必蛔厥上冒。然《内经》有：湿位之下，燥气乘之，是以从之，湿转为燥。若无湿痰之潮气上蒸，舌苔早已燥刺矣。今先滋液，以洁烈焰之燔。", "4355": "脉沉而微，沉为里寒，微为无阳。舌白似粉，泻起口渴。身体卧著，其痛甚厉。交夏阴气在内，其病日加。寅辰少阳升动，少缓。少腹至阴部位，浊阴凝聚，是为疝瘕。若读书明理之医，凡阴邪盘踞，必以阳药通之，归、地列于四物汤，护持血液。虽佐热剂，反与阴邪树帜。当以纯刚药，直走浊阴凝结之处。调摄非片言可尽也。", "4356": "再诊。阴寒盘踞少腹，非纯阳刚剂直入坚冰之地，阴凝不解。此如亚夫之师从天而降也。医易肾气汤，阴多阳少，立见病加，反至不食，药不对症。仿通脉四逆汤法。", "4357": "五旬有四，阳气日薄。阳明脉络空乏，不能束筋骨以流利机关。肩痛、肢麻，头目如蒙，行动痿弱无力。此下虚上实，络热内风沸起，当入夏阳升为甚。渗湿利痰，必不应病。议清营热，以泄内风。", "4358": "下体痿躄，先有遗泄湿疡。频进渗利，阴阳更伤。虽有参、耆、术养脾益气，未能救下。即如长冷阳微，饭后吐食，乃胃阳顿衰，应乎卫外失职。但下焦之病，都属精血受伤。两投温通柔剂，以肾恶燥，久病宜通任督，通摄兼施，亦与古贤四斤、健步诸法互参。至于胃药，必须另用。夫胃府主乎气，气得下行为顺。东恒有升阳益胃之条，似乎相悖，然芩、连非苦降之气乎？凡吐后一二日，停止下焦血分药，即用扶阳理胃，二日俾中下两固。经旨谓阳明之脉，束筋骨以流利机关，本病即有合矣。", "4359": "再诊。长夏湿热，经脉流行气钝，兼以下元络脉已虚，痿弱不耐步趋，常似酸楚，大便或结或溏，都属肝肾为病。然益下必佐宣通脉络，乃正治之法。恐夏季后湿热还扰，预为防理。", "4360": "四诊。寝食如常，脉沉而缓，独两腿内外肉脱麻木。年逾五旬，阳脉渐衰，𫏋维不用事，非三气杂感也。温通以佐脉络之流畅，仿古圣四金刚之属。", "4361": "肾厥由腰脊而升，发时手足厥冷，口吐涎沫，喉如刀刺。盖足少阴经脉上循喉咙，挟舌本，阴浊自下犯上，必循经而至。仿许学士椒附汤，通阳以泄浊阴为主。", "4362": "疟得汗不解，近来竟夜汗出，且胸痞、不饥、形瘦、脉大、便秘。显然阴虚体质，疟邪烁液，致清阳痞结脘中。议以柔剂存阴却邪。", "4363": "脉微而迟，色衰萎黄。凡阳气不足，久利久泻，穷必伤肾。今浮肿渐起目下，是水失火而败，若非暖下，徒见泄泻有红，为脾胃湿热，必至中满败坏。", "4364": "脉左弦右浮涩，始由脘痛贯胁，继则腹大高凸，纳食减少，二便艰涩不爽。此乃有年操持，萦虑太甚，肝木怫郁，脾土自困，清浊混淆，胀势乃成。盖脏真日漓，府阳不运。考古治胀名家，以通阳为务。若滋阴柔药微加桂、附，凝阴沍浊，岂是良法？议用局方禹余粮丸，暖其水脏，攻其秽浊，俟其小效；兼进通阳刚补，是为虚症内伤胀满治法。至于攻泻劫夺，都为有形而设，与气伤之病不同也。", "4365": "脉缓弱，脘中痛胀，呕涌清涎，是脾胃阳微，得之积劳。午后病甚，阳不用事也。大凡脾阳宣通则运，温补极是；而守中及腻滞，皆非通府，勿佐用之。", "4366": "身腴体质，适值过劳，阳气受伤，呕吐食物，身热而无头痛，已非外感风寒；间日烦躁渴饮，唇焦舌黑。是内伏热气，由募原以流布三焦，亦如疟邪之分争营卫者然。然积劳既久，伏邪客病，脉来小缓，按之不鼓，可为征验。且两便颇通，略能纳谷，焉能停聚积滞？仲景以单热无寒之症，不出方药，但以饮食消息之。后贤参拟甘寒滋养胃阴，其热自解。", "4367": "脉弦数右大，舌绛色面微浮，咳呕上逆，心中热，腹中气撑，卧侧著右，暮夜内外皆热。自五月起，病百日不晓饥饱。病因忧愁嗔怒而起，诸气交逆，少火化为壮火，烦热不熄。五液皆涸，内风煽动，亦属阳化，见症肝病，十之八九。秋金主候，木尚不和。日潮加剧，病属郁劳，难以久延。议咸苦清养厥阴之阴以和阳。", "4368": "再诊。脉百至、右弦数、左细微，寒热无汗，喝饮呕逆；病中咯血，经水反多，邪热入阴，迫血妄行。平日奇经多病，已属内虚。故邪乘虚陷，竟属厥阴之热炽，以犯阳明；故为呕为闷，目胞紫暗羞明，咽中窒塞，头痛。由厥阴热邪通胃贯膈，上及面目诸窍。先寒后热，饥不能食，消渴，气上冲心呕哕，仲景皆例厥阴篇中。此伏邪在至阴之中，必熬至枯涸而后已。表之则伤阳，攻之则劫阴。惟咸味直走阴分，参入苦寒以清伏热。清邪之中，仍护阴气，俾邪退一分，便存得一分之阴，望其少苏。", "4369": "右脉平和，左寸关弦动甚锐，面色带赤，体质清癯，得木火之形。禀多动之性，加以操持烦虑，五志之阳无有不炽；宜乎寤多寐少，内风不熄，眩晕自生。经云：阳气下入阴中，阴𫏋满乃得寐。谋虑不决，则火动伤阴，肝阳独行，乏阴和协而魂不藏，则寐不安。总以益阴、和阳为主治，议加味补心丹兼和肝阳。", "4370": "脉弦数，腹膨便泄，目自泪出。经来身体掣痛，今秋冬两月不至。据说两年患病，医药不效。缘情怀抑郁，热自内起，厥阴风木化火，阳明侵削日迫，气血内蒸，血海无贮，渐渐延及干血劳症。凡调经诸法，须论在气在血。今久郁热胜，经阻有年，正气已亏；补药固宜，而气血偏滞，非徒补可以治病。议厥阴、阳明同治，酸苦泄热为先，和补胃气为佐。", "4371": "少年面色青黄，脉小无神，自幼频有呕吐之症，明是饮食寒暄不调，以致中气不足。咳嗽非外感，不宜疏泄。小建中汤主之。", "4372": "任脉、督脉分行乎身之前后。自觉热蒸，不梦自遗，皆奇经虚也。辛温药颇效。六味加五味子不应，方药仅仅达下，未能约束奇经。议用聚精固摄之法。", "4373": "望色萎黄，少膏泽，按脉弦促而芤，纳谷不旺，病已数年。每春夏阳升气泄，偶加烦冗，情志不适，血必溢出上窍，中气非少壮阴火相同。夫心主血，脾统血，肝藏血。脏阴内虚，阳动乃溢，常服归脾汤，去耆、术、木香，加白芍，以和肝脾之阴。所谓王道养正，善药不计骤功。", "4374": "再诊。浊阴蔽塞，舍通阳再无别法，服白通加人尿、猪胆汁汤，脉不微续，仍三五参差，尚非稳保。议用四逆通脉方。", "4375": "凡疟久邪结，必成疟母，其邪深客于阴络，道路深远，肌肤无汗，能食不运，便溺通调，病不在府，从腹下升逆，贯及两胁腰中，推及八脉中病。理固有之，然立方无据。捉摸忆读仲景，转旋下焦痹阻例以通阳。", "4376": "再诊。昔人云：吐中有散，谓多呕多吐，诸气升腾而散。《内经》以阳明经脉主束筋骨，以利机关。今为厥阴风木久侵，中虚困穷，清空溃散，致浊蒙蟠聚，不徒胸腹胀满，腰痹肌膜亦令浮肿。左金泻肝止呕吐，谓肝家郁勃上冲，大苦寒降其逆，大辛热泄其气。丹溪制方之义，以相火内寄于肝胆，上升之气皆从肝出，气有余便是火。此非有余，因数日不食，阳明胃土伤疲已极，中无砥柱，木横浊攻。历考治胀诸贤，河间分消三焦，戴人必攻六府，此皆有余治法。今乃虚症，若呆钝补阳，适助其胀。议通阳明，兼泄厥阴法。", "4377": "眼胞上下，脾肾之脉循行。倦于开合，太阴脾脉已钝，甘补用为宜。", "4378": "脉弦右大，弦则为饮，大则胃阳已虚。缘操持萦思，积劳伤阳，致不饥不食，勉纳食物不运。嗔怒，兼以夜卧不安，多寤少寐，恍惚，中心懊𢙐。忽尔腹鸣气震，四肢筋骱痿弱无力。起病时晨必寒痉，足跗微冷。按是脉症有年，阳虚为本，而痰饮气逆，因虚而聚。夫虚则生寒，实则生热。寝食不安，将及半载，已交四之气中。长夏湿土乘侮脾胃，虑及肌肿腹胀，故周身束筋利机。阳明胃脉，是积阅医药，气血淆混，寒热互投，不以阴阳偏著，调理宜乎不应。议通补理胃阳为主，疏肝为辅。气宣阳苏，何虑痰浊之蒙昧。以茯苓饮法减术，合薛氏星附六君子意。", "4379": "舌色白晦，脉得右大，来去不整，左部小促。耳聋身热不寐，语言謇涩。非是少阳伤寒，良由小产，阴气不复，阳气上冒。恐有牵搐暴厥之忧，无以轻浅视之。", "4380": "秋暑失血，初春再发，脉右大，能纳食。《金匮》云：男子脉大为劳，极虚亦为劳。要知脉大为劳，是烦劳气伤；脉虚为劳，是情欲致损；安静一年可愈。", "4381": "咳嗽从肺治者，以外邪必由皮毛而入，内合乎肺。然六气皆令火化，散之未解，清之润之即愈。若内因之嗽，由别经干连及肺，当明其因，徒治肺无益。夫肾为先天，坎中真阳内藏，而主封蛰。奇经得司其间，冲阳由前直起，且少阴脉循喉咙，挟舌本，阴乏上承，阳独自灼，故阴上阳下则寿，反则死。八味丸阴中之阳，似乎有理。然肉消形瘦，桂、附仍属刚燥。宜温养柔剂，取乎血肉有形之品。议用斑龙，峻补玉堂关下，但鹿角入督升顶，有过升之弊，加以青盐，引入下元，斯为合法。", "4382": "由夏季目黄神倦，渐至中焦胀满，延至霜降，上吐瘀血，下便污浊。按脉弱细不调，视色神采不振，兼以呼吸带喘。素有寒疾气逆，其宿饮之蓄已非一日。当夏三月，脾胃主令，天气热，地气升，人身气泄，加以饥饱劳疫，而遂减食胀满，是皆病于中，绵延上下矣。夫六府以通为用，不但府不用事其间，经脉络中，气血皆令不行，气壅血瘀，胀势愈加。古人以胀病专以宣通为法而有阴阳之殊，后之攻劫宣通，如神佑、舟车、禹功等方。值此久病淹淹，何敢轻试。议以专通三焦之阳气，驱其锢蔽之浊阴，温补兼进。若不阳气渐苏，难以拟投。引用仲景白通汤。", "4383": "再诊。脉神如昨，胸满胀更急，不思纳食，鼻尖冷甚，热汗出，自吐瘀，便垢至今，神衰吸短。古人谓上下交征，当理其中，但阳微浊僭，格拒不通，理中守剂，不能理烦治剧。此护阳通阳，仍参苦寒，俾浊阴泄得一分，其阳复得一分。安谷之理在焉，不及缕述。", "4384": "经来渐迟，色淡而少，当期必暮夜腹痛䐜胀，腰髀酸楚，经络牵掣少舒。脉数右小左大。此乃奇经冲任二脉为他经之气所束，以致气机日钝，血少贮蓄。若加暴怒，须防经漏沸溢。用药须择入奇经者为宜，血海固阳明隶属奇经肝肾为多。议两和气血、宣通奇脉方。", "4385": "寒入厥阴之脉，结为气疝，痛则胀升，气消绝无踪迹。老年下元已亏，不可破气攻疝，尿管痛，或阻溺。温养下元，佐以通窍。", "4386": "再诊。寒少热多，即先后厥之谓热甚。胎攻冲心痛，盖胎在冲，疟邪从四末渐归胃，冲脉属阳明胃脉管辖。上呕青黑涎沫，胎受邪迫，上攻冲心，总是邪热无由发泄，内陷不已，势必坠胎。且协热自利，外邪从里而出，有不死不休之戒。方书保胎，必固阴益气。今热炽壅塞，人参、胶、地反为热邪树帜。前以纯苦气寒，急取固上焦，阳明胃、厥阴肝两治。今则用酸苦辛，泄两经之热邪，外以井泥护胎。", "4387": "经云：谋虑在肝，决断在胆。操持思虑，五志阳气有升无降。肝脉循环，绕乎阴器。气逆拂乱，不司疏泄之权。似疝如淋病象，其实内系肝脏。但治淋治疝，不越子和辛香流气，即从丹溪分消泄热。今形脉已衰，当以虚论。肝病三法，曰辛曰酸曰甘缓。经云食酸令人癃，小便不爽，大忌酸味。", "4388": "诊脉尺垂，据述冲气上冲，肝脉必搏大无偏。视面色赤亮，肌肉瘦削。乃肾精肝血内耗，阴不和阳，致冲任不主把持，固摄壮水。正谓助阴抑阳。然久损不复，当与味厚质静或血肉有情，填实精髓。考古海藏、可久辈，咸遵是制。内损精血，务宜静养，使其加餐壮胃，所谓精生于谷也。且肝肾久伤，累及八脉，阴伤渐干及阳，岂一法网罗者。", "4389": "闺中室女，忽然神志时惑，遂月事不来，正《内经》谓二阳之病发心脾也。盖气逆血菀，经纬紊乱，日加郁痹，焉得聪明清旷？情怀致病，草木药饵都属无情，所以不易奏功。议以上清心窍以通神，下调奇脉以通经。", "4390": "复脉汤去姜、桂。", "4391": "冒暑远行，热气由口鼻吸入，先犯上中，分走营卫，故为寒热。疟疾当淡泊饮食滋味，清疏胃气。投剂或以凉解芳香，或以甘寒生津，皆可治疗。奈何发散不效、复肆行滋补、致肺气壅闭、胃中凝滞、自上及下一身气机不通、变成肿胀？矫其非而欲与攻逐，无如病久形消，又虑正气垂寂。不得已用保和丸缓疏中焦，渐渐升降得宜，六府转达。府气先通，经脉之气无有不通者矣。", "4392": "女科肝病，为多产后必及八脉。即如少腹瘕聚，冲气攻心，必呕吐逆上，则喉间闭塞。经水半年不来，越日常有寒热。凡下焦多属血病，症属气聚，瘕为血痹，病在冲脉。阴维阳维，混混施治，焉得为奇经？", "4393": "脉缓，按之濡弱。谷少不食，厚味运化最迟，饮食不适，即如痛泻。肤腠麻木，骨软筋痛。凡遇暴风骤冷，体中更觉不安。上年肛红，入夏方愈。种种脉症，是气弱阳微，脾胃少于运化，湿郁生痰，致气机不能灵动。法当健阳佐运，即治痰驱湿之本。", "4394": "女子四十九，天癸当止，谓阳明脉衰，冲脉力怯，不能招集诸络之血聚于血海，按月行经，此向老皆然。今秋热致伤，客邪不重，已见带淋，肌麻血阻，内伤之势已露。况所患，甚于腰腹，是必脏阴内损，及于八脉。有形之血既去，无形之气掀旋。诸窍百骸，攻迫肆虐，即身中之阳气独行不得，真阴眷恋耳。熟地、五味滋收，固不甚谬，然不入奇经。法当介用潜阳，咸味下引，酸味内收，或佐微苦微润。盖肝恶刚喜凉，肾恶燥喜暖，古人之制然矣。", "4395": "三诊。自前方固摄之后五、六日，精神颇觉向安。但寒在四肢背部，热在心前腹中，即《内经》阳虚外寒，阴虚心热之旨。然产后气虚，必自阴分伤及阳位。张景岳云：气因精而虚者，当补精以化气。况产后八脉空虚，填补方中必佐以收拾奇经之散亡也。", "4396": "诊脉右弦左濡，久痔注血，致纳食不易运化。此脾营先伤，胃阳继困，府气不能宣畅，大便不爽，温补不能通调。府气疏滞，更损脾胃生阳。东垣每以治土必先达木，不宜过投燥剂。仿古治中汤法，佐以疏肝解郁。", "4397": "诊脉百至，左小涩结，右部弦大。缘高年中焦清阳已微，浊阴渐阻，致脘中窒塞日盛，物不能纳。下焦阴液枯槁，肠中气痹，溺少便涩。虞花溪云：噎膈反胃，阴枯阳结为多。衰老之象，最难调理，诚情志偏胜，无形之伤也。若夫痰气瘀血积聚，亦有是病，有形有象即易为力矣；惟无形致伤，以有形之药饵施治，鲜有奏效。当以阴阳二气推求，在上为阳，在下为阴，通则流通，守则呆钝，古人成法，宜遵其言。居恒颐养，不在药饵中矣。议宣通之味，以冀小效。", "4398": "脉右弦左濡，秋凉宿饮，上泛咳呛，入夜著枕欲寐，气冲胃脘，心悸震动，必欲起坐。仲景「论脉篇」，弦为饮，背寒为饮，当治饮，不当治咳。饮属阴邪，乘暮夜窃发。《金匮》法中，每以通阳涤饮，与世俗仅以肺药疏降迥异，用小青龙减麻、辛法。", "4399": "频因小产，奇脉不固，经来甚多，经过带下。早晨大便溏滑，纳谷日少。时觉心悸震动。始养血滋腻，即脘闷不思纳谷。此皆自下焦损伤，渐及中焦，致脾胃不能转运。近日拟用王荆公妙香散，宣通补中，仍兼顾下。虽似相投，然于调和经带，其力未专。再议两法分治，中宫宣通，下焦固摄。", "4400": "产育致虚，病情多歧，不能缕分。思产后八脉皆空，损伤非在一脏一腑，所以诸恙并起。稍涉情志不适，药饵便少功效，沉痼宿恙骤难奏功。阅病原，再诊脉，知内因虚损，小效病复，实由于此。姑拟迩日再急，在腹胀洞泄，胁腹㽲痛，冀得少缓一二，为进商之步。", "4401": "病久反复，精气损伤，遂成虚怯。据说脐下闪闪升触，逆干咳嗽，兼痰多咽痹。明明元海无根，冲脉气震，无以把握，阴精内枯，阳乏眷恋。非静处山林，屏绝世扰，望其生生复聚。问医便投草木汤液，恐难久持。", "4402": "诸动属阳，烦劳则损气；肝司藏血，怫郁则血菀于上；午后则气并于血，升降混淆为厥。脉来浮数，退而细涩，面黄唇白。热势稍轻，神昏如故。胸膈隐痛，必非停滞，谅有瘀聚所致。目𥉂、舌缩，为肾水竭绝之征，瘛疭不止乃肝虚风动之象，病名暴厥。赵养葵所谓薄厥、煎厥之类。开心窍不应，勉以蒲黄散去瘀舒郁，续进滋养天一之水，以冀风宁火熄。", "4403": "情志郁勃，气逆多升，络血上冒。连次小产，冲、任已怯。心嘈震悸，目珠痛，头胀。肝胆厥阳动极。必须怀抱宽舒，可望病痊，否则成痼疾矣。用复脉汤去姜、桂、参，加淮小麦、天冬，石决明。经来后期两旬，牙宣吐血，防其倒经。议养肝阴，兼通冲脉。", "4404": "质瘦脉弱，交夏天暖，真气发泄，心热口喝，头痛胁疼，食下如噎，右耳气闭少聪，语言过多，齿戛寒噤，或巅胀面浮。皆津液因热而伤，致令浮阳动搏。议用甘凉生津和阳法。", "4405": "时令温邪内迫，经水不应期至，淋淋不断。二便不通。唇舌俱白，不喜冷饮。神呆恍惚，言语支离。诊脉细小欲绝。当芒种、夏至，阳极泄越，阴未来复，神魂不摄，是谓亡阳昏谵，最属危脱之象。拟用仲景救逆法以扼其危。", "4406": "经停两月，恰值嗔怒，阳气升降失和，血随气行，冲、任脉络不固，遂为崩漏。且血凝成大块，非血热宜凉。从来血脱，必须益气。但冲、任、奇经在下焦，又非东垣归、耆、升、柴升举诸法所宜。须固摄奇经之药，乃能按经循络耳。", "4407": "今年风木司天。春夏阳升之候。兼因平昔怒劳忧思。以致五志气火交并于上。肝胆内风鼓动盘旋。上盛则下虚。故足膝无力。肝木内风壮火。乘袭胃土。胃主肌肉。脉络应肢。绕出环口。故唇舌麻木。肢节如痿。固为中厥之萌。观河间内火召风之论。都以苦降辛泄。少佐微酸。最合经旨。折其上腾之威。使清空诸窍。毋使浊痰壮火蒙蔽。乃用药之权衡也。至于颐养工夫。寒暄保摄。尤当加意于药饵之先。", "4408": "立冬后三日。诊得左脉小弦动数。右手和平略虚。问得春夏平安。交秋后有头晕。左目流泪。足痿无力。不能行走。舌生红剌。微咳有痰。此皆今年天气大热已久。热则真气泄越。虚则内风再旋。经言痿生大热。热耗津液。而舌剌咳嗽流泪者。风阳升于上也。上则下焦无气矣。故补肝肾以摄纳肾气为要。而清上安下。其在甘凉不伤脾胃者宜之。", "4409": "离愁菀结。都系情志中自病。恰逢冬温。阳气不潜。初交春令。阳已勃然变化。内风游行扰络。阳但上冒。阴不下吸。清窍为蒙。状如中厥。舌喑不言。刘河间谓将息失宜。火盛水衰。风自内起。其实阴虚阳亢为病也。既不按法论病设治。至惊蛰雷鸣。身即汗泄。春分气暖。而昼夜寤不肯寐。甚至焦烦。迥异于平时。何一非阳气独激使然耶。夫肝风内扰。阳明最当其冲犯。病中暴食。以内风消烁。求助于食。今胃脉不复。气愈不振。不司束筋骨以利机关。致鼻准光亮。肌肉浮肿。考古人虚风。首推侯氏黑散。务以填实肠胃空隙。庶几内风可息。奈何医者不曰清火豁痰。即曰腻补。或杂风药。内因之恙。岂有形质可攻。偏寒偏热。皆非至理。", "4410": "嗔怒动阳。恰值春木司升。厥阴内风乘阳明脉络之虚。上凌咽喉。环绕耳后清空之地。升腾太过。脂液无以营养四末。而指节为之麻木。是皆痱中根萌。所谓下虚上实。多致巅顶之疾。夫情志变蒸之热。阅方书无芩连苦降。羌防辛散之理。肝为刚脏。非柔润不能调和也。", "4411": "脉濡无热。厥后右肢偏痿。口㖞舌歪。声音不出。此阴风湿晦中于脾络。加以寒滞汤药。蔽其清阳。致清气无由展舒。法宗古人星附六君子汤。益气仍能攻风祛痰。若曰风中廉泉。乃任脉为病。与太阴脾络有间矣。", "4412": "痛从腿肢筋骨。上又腰腹。贯于心胸。若平日经来带下。其症亦至。此素禀阴亏。冲任奇脉空旷。凡春交。地中阳气升举。虚人气动随升。络血失养。诸气横逆。面赤如赭。饥不欲食。耳失聪。寤不成寐。阳浮脉络交空显然。先和阳治络。", "4413": "脉弦小数。形体日瘦。口舌麋碎。肩背掣痛。肢节麻木。肤腠瘙痒。目眩晕。耳鸣。已有数年。此属操持积劳。阳升内风旋动。烁筋损液。古谓壮火食气。皆阳气之化。先拟清血分中热。继当养血。熄其内风。安静勿劳。不致痿厥。", "4414": "年岁壮盛。腕有气瘕。嗳噫震动。气降乃平。流痰未愈。睪丸肿硬。今人夜将寐。少腹气冲至心。竟夕但寤不寐。头眩目花。耳内风雷。四肢麻痹。肌腠如剌如虫行。此属操持怒劳。内损乎肝。致少阳上聚为瘕。厥阴下结为疝。冲脉不静。脉中气逆混扰。气燥热化。风阳交动。营液日耗。变乱种种。总是肝风之害。非攻消温补能治。惟以静养。勿加怒势。半年可望有成。", "4415": "平昔肠红。阴络久伤。左胁下宿瘕。肝家风气易结。形瘦面青。阴虚阳气易冒。血络不得凝静。诸阳一并。遂为厥。冲气自下犯胃为呃。症似蓄血为狂。奈脉细劲。咽喉皆痛。真阴枯槁之象。水液无有。风木大震。此刚剂强镇。不能息其厥冒耳。", "4416": "脉上左部稍振。水亏。木中风动。左牙痛。盖风从内旋。乃阳之化风。只以春深地气上升之候。多升少降。无非下元不司收纳。虚症何疑。况因目恙。频用韭子烟熏。查本草药性。辛辣升腾助阳。孙真人于遗浊用之。藉其升阳以涵阴。更无漏泄耳。今痱中八日。声音渐振者。乃精气略有宁静。里窍略有灵机。是顺境也。乃不明此理。仍用辛以泄气。加人参亦是清散上焦之药。以肝肾藏虚在于至阴。若再投辛以伤其阴。必致虚症峰起。焉望其向安。倘必以上有火热。古称实火宜清。虚火宜补。温养柔和。与温热刚燥迥异。幸勿疑讶。", "4417": "脉左细数而劲。右数大而虚。此肾精肝血内亏。水不涵木。阳挟内风。暴起莫制。指臂拘挛。口目㖞邪在左。盖肝风阳气从左而升。冲气撞心。消渴晕厥。仲景列于厥阴篇中。凡肝属阴木。必犯胃之阳土。饮食热气入胃。引动肝肠。即病发矣。此恙已六七年。阴损已极。必屏绝俗扰。怡悦情怀。然后滋养堪固其阴。必有小效。无期速功。", "4418": "右痪。舌喑。足痱。头重。面载阳。呵欠。微呃。诊脉小濡而缓。此肾纳失司。肝风震突。但病起耳后暴肿。必兼温热客气。清上轻扬。肿势颇减。七日以来。当阴阳经气一小周天。不必以时邪引病为惑。昔河间宣明方论中。谓舌强难言。其咎在乎舌下经脉不主流动。以肾脉萦及舌本耳。其主地黄饮子。取意浊药清投。机关渐灵。并无碍乎上气痰热。仿此法。", "4419": "年前肝风眩晕。主以凉血分利阳熄风。一年未发。今岁正月春寒。非比天暖开绁。此番病发。必因劳恐触动情志。至于呕逆。微冷倏热。交丑寅。渐作耳鸣咽痹。食纳久留脘中。想少阳木火盛于寅。胆脉贯耳。犯逆之威。必向阳明。而后上凭诸窍。脉右涩大。胃逆不降。食味不甘。而脘中逆乱。熏蒸日炽。营血内耗。无以养心。斯寝不肯寐。心摇荡漾。有难以鸣状之象。今头重脘痹。全是上为木火升腾。阻遏清阳。前方滋清。血药居多。必不奏功。今议汤剂。方以苦降其逆。辛通其痹。然汤宜小其制度。以久病体虚。初春若此。冬藏未为坚固可知。其丸剂。界以局方龙荟丸。暂服半月再议。", "4420": "张石顽治春榜赵明远。平时六脉微弱。己酉九月。患类中风。经岁不痊。邀石顽诊之。其左手三部。弦大而坚。知为肾藏阴伤。壮火食气之候。且人迎斜内向寸。又谓三阳经满溢入阳维之脉。是不能无颠仆不仁之虑。右手三部浮缓。而气口以上微滑。乃痰沫壅塞于鬲之象。以清阳之位。而为痰气占据。未免侵及心主。是以神识不清。语言错误也。或者以其神识不清。言语错误。口角常有微涎。目晴恒不易转。以为邪滞经络。而用祛风导痰之药。殊不知此本肾气不能上通于心。心藏虚热生风之症。良非燥药所宜。或者以其小便清利倍常。以为肾虚而用八味壮火之剂。殊不知此症虽虚。而虚阳伏于肝藏。所以阳事易举。饮食易饥。又非益火补阴药所宜。或者以其向患休息久痢。大便后。常有痰红渍沫。而用补中益气。殊不知脾气陷于下焦者。可用升举之法。此阴血久利之余疾。有何清气在可升发乎。若用升柴升动肝肾虚阳。鼓激鬲上痰饮。能保其不为喘胀逆满之患乎。是升举药不宜轻服也。今举河间地黄饮子。助其肾。通其心。一举而两得之。但不能薄滋味。远房室。则药虽应病。终无益于治疗也。惟智者善为调摄为第一义。", "4421": "今年长夏久热。伤损真阴。深秋天气收肃。奈身中泄越已甚。吸短精浊。消渴眩晕。见症都是肝肾。脉由阴渐损及阳明胃络。纳谷减。肢无力。越人所云。阴伤及阳。最难充复。诚治病易。治损难耳。", "4422": "脉数垂入尺泽穴中。此阴精未充早泄。阳失潜藏。汗出吸短。龙相内灼。升腾面目。肺受熏蒸。嚏涕交作。兼之胃弱少谷。精浊下注。溺管疼痛。肝阳吸其肾阴。善怒多郁。显然肾虚如绘。议有情之属以填精。仿古滑涩互施法。", "4423": "此少壮精气未旺。致奇脉网维失护。经云形不足者。温之以气。精不足者。补之以味。今纳谷如昔。血肉充养。补之以味。莫若以饮食补之。", "4424": "有形血液。从破伤而损。神气无以拥护。当此冬令藏阳。阳微畏寒。奇脉少津。乏气贯布。行步欹斜。健忘若愦。何一非精气内夺之征。将交大雪。纯阴无阳。冬至一阳来复也。见此离散之态。平素不受暖补。是气元长旺。今乃精衰气竭之象。又不拘乎此例也。", "4425": "阴精走泄于下。阳气郁冒于上。太冲脉衰。厥气上冲。陡然痫厥。阴阳既失交偶。因随阳掀旋。阳从汗泄矣。宜远房帷。独居静室。医治之法。从阴引阳。大封大固。以蛰藏为要。百日可效。经年可以复元。", "4426": "虚劳三年。形神大衰。食减无味。大便溏泻。寒起背肢。热从心炽。每咳。必百脉动掣。间或胁肋攻触。种种见症。都是病深传遍。前议四君子汤以养脾胃冲和。加入桑叶丹皮。利少阳木火。使土少侵。服已不应。想人身中二气致偏则病。今脉症乃损伤已极。草木焉得振顿。见病治病。谅元裨益。益气少灵。理从营议。食少滑泄。非滋腻所宜。暂用景岳理阴煎法。参入镇逆固摄。若不胃苏知味。实难拟法。", "4427": "脉左小右虚。背微寒。肌微冷。痰多微呕。食减不甘。此胃阳已弱。卫气不得拥护。时作微寒微热之状。小便短赤。大便微溏。非实邪矣。当建立中气以维营卫。东垣云。骨为卫之本。营乃脾之源。偏热偏寒。犹非正治。", "4428": "诊脉数。左略大。右腰牵绊。足痿。五更盗汗即醒。有梦情欲则遗。自病半年。脊椎六七节骨形凸出。自述书斋坐卧受湿。若六淫致病。新邪自解。验色脉推病。是先天禀赋原怯。未经充旺。肝血肾精受戕。致奇经八脉中乏运用之力。乃筋骨间病。内应精血之损伤也。", "4429": "脉右劲。因疥疮频以热汤沐浴。卫疏易伤冷热。皮毛内应乎肺。咳嗽气塞痰多。久则食不甘。便燥结。胃津日耗。不司供肺。况秋冬天降。燥气上加。渐至老年痰火之象。此清气热以润燥。理势宜然。倘畏虚。日投滞补。益就枯燥矣。", "4430": "久咳三年。痰多食少。身动必息鸣如喘。诊脉左搏数。右小数。自觉内火燔燎。乃五液内耗。阳少制伏。非实火也。常以琼玉膏滋水益气。暂用汤药。总以勿损胃为上。治嗽之药。谅无益于体病。", "4431": "寡居烦劳。脉右搏左涩。气燥在上。血液暗亏。由思郁致五志烦煎。固非温热补涩之症。晨咳吐涎。姑从胃治。以血海亦隶阳明耳。", "4432": "脉左弱右搏。久有虚损。交春不复。夜卧著枕。气冲咳甚。即行走亦气短喘促。此乃下元根蒂已薄。冬藏不固。春升生气浅少。急当固纳摄下。世俗每以辛凉理嗽。每致不救矣。", "4433": "肾精下损。致阴气上乘。浮阳上灼。咽喉痛痹。有喉宣发现。咳嗽喘促。是下焦元海不司收纳。冲脉之气上冲所致。故日进润剂。望其咳减。为庸医之良法。实酿病之祸阶。现在胃弱便溏。则非治嗽可疗矣。劳怯不复。当以固真纳气。培扶胃口。希冀加谷则吉。", "4434": "凡忧愁思虑之内伤不足。必先上损心肺。心主营。肺主卫。二气既亏。不耐烦劳。易于受邪。惟养正则邪自除。无麻桂大劫散之理。故内伤必取法乎东垣。今血止脉耎。形倦不食。呛咳不已。吐痰若黏涎。皆土败金枯之象。急与甘缓补法。", "4435": "溃疡流脓经年。脉细色夺。声嘶食减。咳嗽喉中梗痛。皆漏损脂液。阴失内守。阳失外卫。肺痿之疴。谅难全好。", "4436": "脉微弱。面亮载阳。呃逆胁痛。自利。先曾寒热下利。加以劳烦伤阳。高年岂宜反复。乃欲脱之象。三焦俱有见症。议从中治。", "4437": "食伤肠胃。复病呕吐。发呃下利。诊两脉微涩。是阳气欲尽。浊阴冲逆。阅方虽有姜附之理阳。反杂入耆归。呆钝牵制。后方代赭重坠。又混表药。总属不解。今事危至急。舍理阳驱阴无别法。", "4438": "脉搏劲。舌干赤。嗳气不展。状如呃忒。缘频吐胃伤。诸经之气上逆。填胸聚脘。出入机逆。周行脉痹。肌肉著席而痛转加。平昔辛香燥药不受。先议治肺经。以肺主一身之气化耳。", "4439": "以毒药熏疮。火气逼射肺金。遂令咳呛痰血。咽干胸闷。诊脉尺浮。下焦阴气不藏。最虑病延及下。即有虚损之患。姑以轻药。暂渐清上焦。以解火气。", "4440": "脉数涩小结。痰血经年屡发。仍能纳食应酬。此非精血损怯。由乎五志过动。相火内起肝胆。操持郁勃。皆令动灼。致络血上渗混痰火。必静养数月方安。否则木火劫烁。胃伤减食。病由是日加矣。", "4441": "虚不肯复谓之损。纳食不充肌肤。卧眠不能著左。遇节令痰必带血。脉左细右劲数。是从肝肾阴血之伤。延及气分。倘能节劳安逸。仅能带病永年。损症五六年。无攻病之理。脏属阴。议平补足三阴法。", "4442": "向有失血。是真阴不旺。夏至阴生。伏天阳越于表。阴伏于里。理宜然矣。无如心神易动。暗吸肾阴。络脉聚血。阳触乃溢。阴伏不固。随阳奔腾。自述下有冲突逆气。血涌如泉。盖任脉为担任之职。失其担任。冲阳上冲莫制。皆肾精肝血不主内守。阳翔为血溢。阳坠为阴遗。腰痛足胫畏冷。何一非精夺下损现症。经言精不足者。补之以味。药味宜取质静填补。重著归下。莫见血以投凉。勿因嗽以理肺。若此治法。元海得以立基。冲阳不来犯上。然损非旬日可复。须寒暑更迁。凝然不动。自日遂安适。调摄未暇缕悉也。", "4443": "操持怫郁。五志中阳动极。失血咳呛有年。皆由性情内起之病。草木难以奏安。今形色与脉。日现衰惫。系乎生气克削。虑春半以后。地气升。阳气泄。久病伤损。里真少聚。冬春天冷主藏。总以摄补足三阴脏。扶持带病延年。就是人工克尽矣。", "4444": "脉坚。形瘦久咳。失血有年。食物厌恶。夜寝不适。固以培本为要。所服七味八味汤丸。乃肝肾从阴引阳法。服之不效。此液亏不受桂附之刚。当温养摄纳其下。兼与益胃津以供肺。", "4445": "半月前恰春分。阳气正升。因情志之动。厥阳上燔。致咳震动络中。遂令失血。虽得血止。诊右脉长大透寸部。食物不欲纳。寐中呻吟呓语。由至阴损及阳明。精气神不相交合矣。议敛摄神气法。", "4446": "血大去。则络脉皆空。其伤损已非一腑一脏之间矣。秋分寒露。天气令降。身中气反升越。明明里不肯收摄。虚象何疑。今诊脉弱濡涩。肢节微冷。气伤上逆。若烟雾迷离。熏灼喉底。故作呛逆。大旨以上焦宜降宜通。下焦宜封宜固。得安谷崇土。再商后法。", "4447": "忧思怫郁。五志气火内燔。加以烟辛泄肺。酒热戕胃。精华营液。为热蒸化败浊。经云。阳络伤则血外溢。盖胃络受伤。阳明气血颇富。犹勉强延磨岁月。至于阳明脉络日衰。斯背先发冷。右胁酸痛。而咳吐不已。胃土愈惫。肝木益横。厥阳愈逆。秽浊气味。无有非自下泛上。大凡左升属肝。右降属肺。由中焦胃土既困。致有升无降。壅阻交迫。所以著左卧眠。遏其升逆之威。且烦蒸热灼。并无口渴饮水之状。病情全在血络。清热滋阴之治。力量不能入络。兹定清养胃阴为主另进通络之方。肝胆厥阳少和。冀其涎少胁通。积久沉疴。调之非易。", "4448": "有年冬藏失司。似乎外感热炽。辛散苦寒。是有余实症治法。自春入夏。大气开泄。日见恹恹衰倦。呼吸喉息有声。胁肋窒板欲痛。咯呛紫血。络脉不和。议以辛补通调。不致寒凝燥结。冀免关格上下交阻之累。", "4449": "脉数左坚。当夏四月。阳气方张。陡然嗔怒。肝阳勃升。络血上涌。虽得血止。而咳逆欲呕。眠卧不得欹左。此肝阳左升太过。木失水涵。阴亏则生热。是皆本体阴阳迭偏。非客邪实火可清可降之比。最宜恬澹无为。安静幽闲。经年不反。可望转偏就和。但图药治。难减损怯矣。经云。胃咳之状。咳逆而呕。木犯胃土贯膈。即至冲咽入肺。肺衰。木反刑金。从内经甘缓以制其急。", "4450": "脉左弦。右小濡。据病源起于忧郁。郁勃久而化热。蒸迫脉络。血为上溢。凝结成块者。离络留而为瘀也。血后纳食如昔。是腑络所贮颇富。况腑以通为用。血逆气亦上并。漉漉有声。皆火气旋动。非有形质之物。凡血病五脏六腑皆有。是症当清阳之络为要。致于病发。当治其因。又不必拘执其常也。", "4451": "诊脉左手平和。尺中微动。右手三部。关前动数。尺脉带数。夜卧不寐。咳呛有血。昼日咳呛无血。但行走微微喘促。夫阴阳互为枢纽。隆冬天气藏纳。缘心烦劳神。五志皆动。阳不潜伏。当欲寐之时。气机下潜。触其阳气之升。冲脉升动。络中之血未得宁静。随咳呛溢于上窍。至于步趋言谈。亦助其动搏气火。此咳呛喘息失血。同是一原之恙。当静以制动。投药益水生金以制君相之火。然食味宜远辛辣热燥。凡上实者必下虚。薄味清肃上焦。正谓安下。令其藏纳也。愚见约方。参末俟裁。", "4452": "脉细小如无。素多郁怒。经来即病。冬患胃痛。随有咯血不止。寒战面赤。惊惕头摇。显是肝阳变风。络血沸起。四肢逆冷。真气衰微。内经有肝病暴变之文。势岂轻渺。议用景岳镇阴煎法。制其阳逆。仍是就下之义。", "4453": "胁膈左右。懊𢙐不舒。呕逆带血。凡人脏腑之外。必有脉络拘绊。络中乃聚血之地。中年操持。皆令耗血。血不和气。气攻入络。病状难以自明。宣通血分以和络。俾不致瘀著。可免噎膈反胃。", "4454": "频年发失血症。嗽甚痰出。继以呕嗳。日晡寒热。夜深汗泄。据述医见血。投以郁金姜黄韭汁制大黄逐瘀下走。希图血止。此是有余治法。夫人禀阴阳。偏则致病。自内损伤。即是不足。脉左动数。尺不附骨。明明肾精肝血内夺。弱阴无能交恋其阳。冲阳上逆。吸气不入。是以咳嗽气升。旋必呕嗳浊涎黏沫。内经谓五脏六腑皆令人咳。奈何今人以咳治肺。见痰降浊清热。损者更损。殆不复藏阴府阳消长之机。杂药徒伐胃气。经年累月。已非暴病。填实下隙。须藉有情之属。", "4455": "诊脉左数微弦。寸尺关虚数。阅五年前病原。左胁映背胀痛。不能卧席。曾吐瘀血。凝块紫色。显然肝郁成热。热迫气逆血瘀。虽经调理全愈。而体质中肝阴不充。肝阳已动。凡人身之气。左升主肝。右降主肺。今升多降少。阴不和阳。胃中津液。乏上供涵肺之用。此燥痒咳呛。吐出水沫。合乎经旨肝病吐涎沫矣。肝木必犯胃土。纳谷最少。而肢软少力。非嗽药可以愈病。此皆肝阳逆乘。实系肝阴不足。仲圣云。见肝之病。先理脾胃。俾土厚不为木克。原有生金功能。据述凡食鸡子。病必加剧。则知呆滞凝涩之药。皆与病体未合。", "4456": "脉右弦左濡。秋凉宿饮。上泛咳呛。入夜著枕欲寐。气冲胃脘。心悸震动。必欲起坐。仲景论脉篇。弦为饮。背寒为饮。当治饮。不当治咳。饮属阴邪。乘暮夜窃发。金匮法中每以通阳涤饮。与世俗仅以肺药疏降迥异。用小青龙减麻辛法。", "4457": "脉左虚涩。右缓大。尾闾痛连脊骨。便后有血。自觉惶惶欲晕。兼之纳谷最少。明是中下交损。八脉全亏。早进青囊斑龙丸。峻补玉堂关元。暮服归脾膏。涵养营阴。守之经年。形体自固。", "4458": "脉小。泻血有二十年。经云。阴络伤。血内溢。自病起十六载。不得孕育。述心中痛坠血下。不论粪前粪后。且脊椎腰尻酸楚。而经水仍至。跗膝常冷。而骨髓热灼。由阴液损伤。伤及阳不固密。阅频年服药。归耆杂入凉肝。焉是遵古治病。议从奇经升固一法。", "4459": "脉小左数。便实下血。乃肝络热腾。血不自宁。医投参耆归桂。甘辛温暖。昧于相火寄藏肝胆。火焰风翔。上蒙清空。鼻塞头晕。呛咳不已。一误再误。遗患中厥。夫下虚则上实。阴伤阳浮。此乃一定至理。", "4460": "又下血阴伤走泄。虚阳上升。头为清窍。参耆术桂。辛甘助上。致鼻塞耳聋。用清上五六日。右脉已小。左仍细数。乃阴亏本象。下愈虚则上愈实。议以滋水制火之方。", "4461": "脉缓濡弱。阳气不足。过饮湿胜。大便溏滑。似乎不禁。便后血色红紫。兼有成块而下。论理是少阴肾脏失司固摄。而阳明胃脉。但开无合矣。从来治腑。以通为补。与治脏补法迥异。先拟暖胃通阳一法。", "4462": "寒热如疟。便血不已。左胁有块。攻逆不已而作痛。脉弦数兼涩。弦则为风。数则为热。涩则气结。此肝脾之气悒郁不宣。胸中阳和抑而成火。故神明不清。肝之应为风。肝气动则风从之。故表见寒热也。人身左半。肝肾主之。肝风自逆。故左胁攻楚有块也。肝为藏血之地。肝伤则血不守。且以风淫热胜。盖为亡血之由也。", "4463": "患溺血症。已三月矣。前用升补法不应。右脉涩无神。左关独弦。茎中作痛。下多血块形色憔悴。又多嗳气。据脉论症。乃肝脾积热也。肝热则阴火不宁。而阴血自动。以血为肝脏所藏。而三焦之火。又寄养于肝也。故溺血。茎中作痛。脾热则湿气内壅。而生气不伸。以脾为湿土之化。而三焦之气。又运行于脾也。故时时嗳气。形色憔悴。法当益肝之阴。则火自平。利脾之湿。则气自和。", "4464": "先寒后热。不饥不食。继浮肿喘呛。俯不能仰。仰卧不安。古人以先喘后胀治肺。先胀后喘治脾。今由气分𪱥郁。以致水道阻塞。大便溏泻。仍不爽利。其肺气不降。二肠交阻。水谷蒸腐之湿横趋脉络。肿由渐加。岂乱医可效。粗述大略。与高明论证。至肺位最高。主气。为手太阴脏。其脏体恶寒喜热。宣辛则通。微苦则降。若药气味重浊。直入中下。非宣肺方法矣。故手经与足经大异。当世不分手足经混治者。特表及之。", "4465": "色痿腠疏阳虚体质。平昔喜进膏粱。上焦易壅。中宫少运。厚味凝聚蒸痰。频年咳嗽。但内伤失和。薄味自可清肃。医用皂荚搜攒。肺伤气泄。喷嚏不已。而沉锢胶浊。仍处胸背募俞之间。玉屏风散之固卫。六君子汤之健脾理痰。多是守剂。不令宣通。独小青龙汤。彻饮以就太阳。初服喘缓。得宣通之意。夫太阳但开。所欠通补阳明一段工夫。不得其阖。暂开复痹矣。且喘病之因。在肺为实。在肾为虚。此病细诊色脉。是上实下虚。以致耳聋鸣响。治下之法。壮水源以熄内风为主。而胸次清阳少旋。浊痰阻气妨食。于卧时继以清肃上中二焦。小剂守常调理。百日图功。至于接应世务。自宜节省。勿在药理中也。", "4466": "脉细尺垂。形瘦食少。身动即气促喘急。大凡气出不爽而喘为肺病。客感居多。今动则阳化。由乎阴弱失纳。乃吸气入而为喘。肾病何辞。治法惟以收摄固真。上病当实下焦。宗肾气方法意。", "4467": "望八大年。因冬温内侵。遂至痰嗽暮甚。诊脉大而动搏。察色形枯汗泄。吸音颇促。似属痰阻。此乃元海根微。不司藏纳。神衰呓语。阳从汗出。最有昏脱之变。古人老年痰嗽喘症。都从脾肾主治。今温邪扰攘。上中二焦留热。虽无温之理。然摄固下真以治根本。所谓阳根于阴。岂可不为讲究。", "4468": "昔肥今瘦为饮。仲景云。脉沉而弦。是为饮家。男子向老。下元先亏。气不收摄。则痰饮上泛。饮与气涌。斯为咳矣。今医见嗽。辄以清肺降气消痰。久而不效。更与滋阴。不明痰饮。皆属浊阴之化。滋则堆砌。助浊滞气。试述著枕咳呛一端。知身体卧著。上气不平。必下冲上逆。其痰饮伏于至阴之界。肾脏络病无疑。形寒畏风。阳气微弱。而藩篱疏撤。仲景有要言不烦。曰。饮邪必用温药和之。更分外饮治脾。内饮治肾。不读圣经。焉知此理。", "4469": "脉弦右濡。阳微恶寒。饮浊上干。咳吐涎沫。且食减胃衰。寒疝窃踞。阴浊见症。岂止一端。喻嘉言谓浊阴上加于天。非离照当空。氛雾焉得退避。反以地黄五味。阴药附和其阴。阴霾冲逆肆虐。饮邪滔天莫制。议以仲景熟附配生姜法。扫群阴以驱饮邪。维阳气以立基本。况尊年尤宜急护真阳为主。", "4470": "十二月间。诊得阳微浊饮。上干为咳。不能卧。曾用小青龙汤。减去麻黄细辛。服后已得著枕而卧。想更医接用。不明治饮方法。交惊蛰阳气发泄。病势更炽。顷诊脉来濡弱无神。痰饮咳逆未已。谅非前法可效。宗仲景真武汤法。以熟附配生姜。通阳逐饮立法。", "4471": "脉弦右涩。面亮舌白。口干不喜饮。头重岑岑然。胸脘痹塞而痛。得嗳气稍舒。酒客谷少中虚。痰饮聚蓄。当此夏令。地气上升。饮邪挟气。上阻清空。遂令前症之来。金匮云。脉弦为饮。色鲜明者为留饮。口干不欲饮水者。此为饮邪未去故也。况漐漐汗出。岂是风寒。春夏温邪。辛温发散为大禁。自云身体空飘。年已六旬有四。辛散以泄其阳。不亦左乎。", "4472": "远客路途。风寒外受。热气内蒸。痰饮日聚于脏之外。脉络之中。凡遇风冷。或曝烈日。或劳碌身体。心事不宁。扰动络中宿饮。饮泛气逆咳嗽。气塞喉底。胸膈不思食物。著枕呛吐稠痰。气降自愈。病名哮喘伏饮。治当得宜。除根不速。到老年仍受其累耳。", "4473": "冬温。阳不潜伏。伏饮上泛。仲景云。脉沉属饮。面色鲜明为饮。饮家咳甚。当治其饮。不当治咳。缘年高下焦根蒂已虚。因温暖气泄。不主收藏。饮邪上扰乘肺。肺气不降。一身之气交阻。熏灼不休。络血上涌。经云。不得卧。卧则喘甚痹塞。乃肺气之逆乱也。若以见病图病。昧于色诊候气。必致由咳变幻。腹肿胀满。渐不可挽。明眼医者。勿得忽为泛泛可也。兹就管见。略述大意。议开太阳。以使饮浊下趋。仍无碍于冬温。从仲景小青龙越脾合法。", "4474": "夏至节。两关脉弦长。五火燔燎。而肝阳胃阳尤甚。动怒抽掣为肝病。食辛香厚味。即病至。胃病使然。痰火根深。非顷刻可除。惟静养勿恚忿。薄味以清里。此病发之势必缓。由渐加功议药。乃近理治法。", "4475": "面垢油亮。目眦黄。头胀如束。胸脘痞闷。此暑湿热气内伏。因劳倦正气泄越而发。既非暴受风寒。发散取汗。徒伤阳气。按胀形濡涩。岂是表症。凡伤寒必究六经。伏气须明三焦。论症参脉。壮年已非有余之质。当以劳倦损伤伏邪例诊治。", "4476": "按七疝治法。最详子和。其旨辛香以泄肝。得气疏泄。而病缓矣。按法调理不愈。七味导引。纳肾益气。升举脾阳。而坠气仍然。艾灸蒸脐。原得小安。内经任脉为病。男子内结七疝。女子带下瘕聚。同为奇经主之。故疏泄诸方。能治气实。参术升补。仅治中虚下陷。与元海奇经中病无补。壮岁至老。病根不辍。下焦日衰。可知升阳一法。体症颇合。衰年仅可撑持。勿使病加可矣。", "4477": "脉右弦左涩。当脐痛连少腹。已属凝聚有形。呕吐黄浊。大便欲解不通。若患处有漉漉声。痛势稍减。惟外著体不转移。其痛更加。此属肝气疝瘕。辛香流气。所称通则不痛耳。", "4478": "七疝在肝。内经谓冲脉为病。但冲脉隶于阳明。肝木必乘克胃土。胃翻涌逆。致吐蛔呕吐。汤饮不入。呃忒不止。皆逆乱无已。为脏厥危疴矣。肝体本刚。相火内寄。一派热燥药饵。以刚济刚。竟有缺折之虞。欲泄其浊。拟用朱南阳法。", "4479": "痛自肾囊。渐踞少腹之左。夫厥阴之脉绕乎阴器。操持谋虑。都主伤肝。一气结聚。变幻形象而痛。病名曰疝。疝分有七暴疝多寒。久疝多热。泄气痛缓。宣通可以却病。只因下焦乃深远之乡。气热湿郁。概可知矣。", "4480": "疟母十年。沉痼宿疴。药不能效。夫疟邪既久。邪与气血两凝。结聚络脉。药难入络耳。疟不离乎肝胆。疝不外乎肝病。七疝子和分部大著。虚质不可专以辛香。下坠为甚。议有情温通。以培生气。", "4481": "脉沉痰多。手体赤疮。宿疝在下。右胁气坠少腹。前议控涎丹逐痹未应。想久聚湿热沉痼。非皮膜经脉之壅。用浚川丸四十粒。匀二服。间日一进。竟通腑聚。惟通腑宣壅。黏痰既下。其疝仍聚于右。且盛于寒天冬月。卧安必有声。自能行走。劳动必有形。直坠阴囊。久病急攻无效。议辛甘化风方法。古人以疝为肝病。十居八九。", "4482": "据述泻血五日。血止即患咳呛。左胁下有形如梗。身动行走。必眩晕欲仆。春夏减食。秋冬稍加。交冬人迎脉络结瘿。诊脉虚。左关尺数。此肝肾精血。因惊恐忧劳所伤。阳失阴恋。络中空隙。阳化内风。鼓动不息。日就消烁。不肯复。为郁劳之症。四旬以外生气已浅。非治病可却。春夏。身中真气。不耐发泄可知。屏绝家务。关怀颐养。望其病缓。", "4483": "病始足胫。乃自下焦肝肾起病。其形不肿。则非六气湿邪。当从内损门痿躄推求。萸地滋滞。久服胃伤。食减呕逆。皆因浊味滞气而然。经年不复。损者愈损。脏真不能充沛。奇经八脉不司其用。经云。冲脉为病。男子内结七疝。女子带下瘕聚。夫冲脉即血海。男子藏精。女子系胞。今精沥内结有形。是精窒气结。亦犹女子之瘕聚也。凡七疝治法。后人每宗张子和。但彼悉用辛热。与今之精窒气结迥殊。久病形消肉脱。议以精血有情。涵养生气。", "4484": "病者长夏霉天奔走。内踝重坠发斑。下焦痛起。继而筋掣。及于腰窝左臂。经云。伤于湿者。下先受之。夫下焦奇脉不流行。内踝重著。阴维受邪。久必化热烁血。风动内舍乎肝胆。所谓少阳行身之侧也。诊得右脉缓。左脉实。湿热混处血络之中。搜逐甚难。此由湿痹之症。失治。延为痿废沉疴矣。三年病根。非仓猝迅攻。姑进先通营络。参之奇经为治。考古圣治痿痹独取阳明。惟通则溜邪可拔耳。", "4485": "从来痹症。每以风寒湿三气杂感主治。召恙之不同。由乎暑暍外加之湿热。水谷内蕴之湿热。外来之邪。著于经络。内受之邪。著于腑络。故辛解汗出。热痛不减。余以急清阳明。而致小愈。病中复反者。口鼻复吸暑热也。是病后宜薄味。使阳明气爽。斯清阳流行不息。肢节脉络舒通。而痿痹之根尽拔。至若温补而图速效。又非壮盛所宜。", "4486": "左脉弦大。面赤痰多。大便不爽。此劳怒动肝。令阳气不交于阴。阳维阳𫏋二脉无血营养。内风烁筋。跗⿰⻊廉痹痛。暮夜为甚者。厥阴旺时也。病在脉络。", "4487": "烦劳郁勃之阳。变现热气内风。内经以热淫风消。必用甘寒。前议谓酒客不喜甘味。且痰多食少。亦忌甘腻滋滞。用清少阳胆热者。酒气先入肝胆也。酒汁湿著。肠胃受之。理肠以通胃。胃肠气机流行。食加。滑泄颇腻。今者气热。当午上冒。经络痹痛。亦减于平日主以和阳甘寒。宣通经脉佐之。", "4488": "用养肝血熄风方。右指仍麻。行走则屈伸不舒。戌亥必心热烦蒸。想前法不效。杞归辛温。阳动风亦动矣。议去辛用咸。若疑虑途次疟邪未尽。致脉络留滞。兼以通逐。缓攻亦妙。", "4489": "脉弦右大。弦则为饮。大则胃阳已虚。缘操持萦思。积劳阳虚。致不饥不食。勉纳食物不运。瞋怒兼以夜卧不安。多寤少寐恍惚中心𢙐懊。忽而腹鸣气震。四肢筋骱。痿弱无力。起病时晨必寒痉。足跗微冷。按是脉症有年。阳虚为本。而痰饮气逆。因虚而聚。夫虚则生寒。实则生热寝食不安。将及半载。已交四之气中。长夏湿土乘侮脾胃。虑及肌肿腹胀。故周身束筋利机。阳明胃脉是赖。阅医药。气血淆混。寒热互投。不以阴阳偏著。调理宜乎不应。议通补理胃阳为主。疏肝为辅。气宣阳苏。何虑痰浊之蒙昧。以茯苓饮法减术。合薛氏星附六君子意。", "4490": "周身掣痛。头不可转。手不能握。足不能运。两脉浮虚。浮虽风象。而内虚者。脉亦浮而无力。以脉参症。当是劳倦伤中。阳明不治之候。阳明者。五脏六腑之海。主束筋骨而利机关。阳明不治。则气血不荣。十二经络无所禀受而不用矣。卫中空虚。营行不利。相搏而痛。有由然也。法当大补阳明气血。不与风寒湿所致成痹者同治。", "4491": "长夏湿痹。经脉流行气钝。兼以下元脉络已虚。痿弱不能走趋。脊膂常似酸楚。大便或结或溏。都属肝肾奇经为病。盖必佐宣通脉络为正治法。倘徒呆补。夏季后必滋湿扰。须为预理。", "4492": "脉微而涩。微为阳气虚。涩为阴血伤。去冬已下肢独冷。步趋无力。高年内乏藏纳之司。入夏身动加喘。肉腠麻痹若虫行。此真阳失蛰。胃阳失护。生生意少。岂攻病药石所宜。喻嘉言先生所谓大封大固。莫令真阳泄尽而暴脱。皆为此也。录严氏三因方。", "4493": "血伤骤加惊恐。气郁热升风旋。清神受蒙为厥。凡厥皆隶厥阴。今左股麻痹。忽爽忽迷。皆肝胆中相火内风。未得宁静。病延数日。左脉小濡。热胜。津液暗伤。不宜纯与攻涤苦寒。经旨以肝为刚脏。与胃腑对待。柔缓濡润。阳和液复。可免痫症。", "4494": "下焦痿躄。先有遗泄湿疡。频进渗利。阴阳更伤。虽有参耆术。养脾肺以益气。未能救下。即如畏冷阳微。几日饭后吐食。乃胃阳顿衰。应乎外阳失职。但下焦之病。多属精血受伤。两投柔剂温通之补。以肾脏恶燥。久病宜通任瞀。通摄兼施。亦与古贤四斤金刚健步诸法互参。至于胃药。必须另用。夫胃腑主乎气。气得下行为顺。东垣有升阳益胃之条。似乎相悖。然芩连非苦降之气味乎。凡吐后一二日。暂停下焦血分药。即用扶阳理胃二日。俾中下两固。经旨谓阳明之脉。束筋骨以利机关。谅本病必有合矣。", "4495": "长夏湿热。经脉流行气钝。兼以下元络脉已虚。痿弱不耐步趋。常似酸楚。大便或结或溏。都属肝肾为病。然益下必佐宣通脉络。乃正治之法。徜徒呆补。恐季夏后湿热还扰。须为预理。", "4496": "色苍脉实。体质坚壮。虽年逾四旬。气元充旺。询知平日喜啖酒醴甘肥。此酿成湿火。蕴结下焦。今少腹微肿硬。二便带涩。自觉少腹气胀下冲。两足沉重。艰于步履。腿股皮中甚热。即内经所云。湿热不攘。大筋緛短。小筋弛长。緛短为拘。弛长为痿也。更述曾因熬炼膏药。中有䗪虫蜈蚣等物。吸受秽浊毒气。未始非与湿热纠蓄。沉伏下焦。前议苦辛寒燥。兹再佐以搜逐络隧。然此病从口而入。必茹素戒饮一二年之久。", "4497": "金疮去血。乃经脉营络之伤。若损及脏腑。倏忽莫救。后此嗔怒动肝。属五志中阳气逆。迸与客邪化火两途。苦辛泄气。频服既多。阳遂发泄。形虽若丰盈。而收藏固摄失职。少腹约束。阳道不举。背脊喜靠。步履无力。皆是痿弱症端。渐至痿废。议以通纳之法。专事涵养生真。冀下元之阳。八脉之气。收者收。通者通。庶乎近理。", "4498": "五旬又四。阳气日薄。阳明脉络空乏。不司束筋骨。以流利机关。肩痛痹麻。头目如蒙。行动痿弱无力。此下虚上实。络热内风沸起。当入夏阳升为甚。燥湿利痰。必不应病。议清营热。以熄内风。", "4499": "勉强摇精。致阳缩囊纵。不但形质伛偻。肛门脐窍。皆为收引。咽喉牵绊。自此食物渐渐减少。由精血之伤有形。最难自复。少厥两阴。脉循喉咙。开窍于二阴。既遭损伤。其气不及充注于八脉。见症皆拘束之状。上年进柔剂阳药。服后头巅经脉皆胀。耳窍愈鸣。想是藏阴宜静。试以乘舆身怖。必加局促不安。宜乎升阳之动药不灵矣。夫少阴内藏。原有温蒸诸法。厥阴相火内寄。恶寒喜凉。仿丹溪潜阳法。仍候高明定议。", "4500": "当夏季反复变幻。因天地气机大泄。体气久虚。无以主持。故见病治病则无功。而安中纳下。每每获效。入秋常服附子七味丸颇安。秋分节。天气降。地气收。缘火热气伤。虚体未能收肃。是以肢节时寒。头巅欲冷。无非病久诸气皆馁。斯外卫之阳少护。液髓暗枯。则血脉不营。而阴乏内守。凡此皆生气之渐鲜也。急当温养益气。填补元形。使秋令助其收藏。预为来春生发之用。按内经有四气调神法。即今投药。亦当宗此旨。", "4501": "高年液涸风动。酒湿气蒸。足趾曾经腐疡。经年来或麻痹。或牵掣。不能转侧。已成筋骨之痿。兼之火升眩晕。头面清窍。常似不爽。大便艰涩。四五日始一更衣。阳气不能潜伏。阴液日就枯槁。老来痿躄。原无复元之法。诊得脉数动疾。温燥之补。无益反害。仿丹溪虎潜之制。稍为加减。冀得津液少存。亦安闲永年之算。非攻病也。", "4502": "肾厥。由背脊而升。发时手足逆冷。口吐涎沫。喉如刀刺。盖足少阴经脉上循喉咙。挟舌本。阴浊自下上犯。必循经而至。仿许学士椒附意。通阳以泄浊阴耳。", "4503": "厥属肝病。几番病发。都因经水适来。夫血海贮聚既下。斯冲脉空乏。而风阳交动。厥之暴至之因由也。咸寒濡润。亦和阳泄内风之义。治之未应。下焦独冷。喉呛胸痹。思冲脉乃阳明所属。阳明虚则失阖。厥气上犯莫遏。内经治肝不应。当取阳明。制其侮也。暂用通补入腑。取乎腑以通为补。", "4504": "脉左动如数。右小濡弱。病起嗔怒。即寒热汗出心悸。继而神魂自觉散越。夫肝脏藏魂。因怒则诸阳皆动。所见病源。无非阳动变化内风为厥。故凡属厥症。多隶厥阴肝病。考内经治肝。不外辛以理之酸以治之。甘以缓急。今精采散失。镇固收摄。犹虑弗及。而方书泄肝平肝抑肝方法尽多。至于补法。多以子母相生为治。此病全以肝肾下焦主治为正。所服医药。并无师古之方。未识何见。", "4505": "冷自足上贯于心。初起周身麻木。今则口鼻皆是冷气。病起惊恐。内伤肝肾为厥。冲脉隶于肝肾。二脏失藏。冲气沸乱。其脉由至阴而上。故多冷耳。", "4506": "平昔操持。身心皆动。悲忧惊恐。情志内伤。渐渐神志恍惚。有似癫痫。其病不在一脏矣。医药中七情致损。二千年来。从未有一方包罗者。然约旨总以阴阳迭偏为定评。凡动皆阳。当宗静以生阴是议。阳乘于络。阴脉不安。敛镇摄固。久进可效。家务见闻。必宜屏绝。百日为期。", "4507": "肌肉瘦减。善饥渴饮。此久久烦劳。壮盛不觉。体衰病发。皆内因之症。自心营肺卫之伤。渐损及乎中下。按脉。偏于左搏。营络虚热。故苦寒莫制其热。甘补无济其虚。是中上消之病。", "4508": "病起忧虑上损。两年调理。几经反复。今夏胸心右胁之间。常有不舒之象。此气血内郁少展。支脉中必有痰食气阻。是宣通流畅脉络。夏季宜进商矣。", "4509": "诊脉右大而缓。左手小数促。冬季寒热身痛。汗出即解。自劳役饥饱嗔怒之后。病势日加。面浮足肿。呼吸皆喘。目泪鼻衄。卧著气冲欲起。食纳留中不运。时序交夏。脾胃主候。睹色脉情形。中满胀病日来矣。盖此症属劳倦致损。初病即在脾胃。东垣云。胃为卫之本。脾乃营之源。脏腑受病。营卫二气。昼夜循环失度。为寒为热。原非疟邪半表半里之症。斯时若有明眼。必投建中而愈。经言。劳者温之。损者益之。建中甘温。令脾胃清阳自立。中原砥定。无事更迁。仲景亦谓男子脉大为劳。则知内经东垣仲景垂训。真规矩准绳至法。且汗泄积劳。都是阳伤。医药辛走劫阳。苦寒败胃。病人自述。饮蔗即中脘不舒。顷之少腹急痛。便稀。其胃阳为辛苦大伤。明甚。又述咳频冲气。必自下上逆。夫冲脉隶于阳明。胃阳伤极。中乏坐镇之真气冲脉动则诸脉皆动。浊阴散漫上布。此卧著欲起矣。愚非遥指其脉。正合内经浊气在上。则生䐜胀。太阴所至。为腹胀相符也。有昔见痰休治痰。见血休治血。当以病因传变推求。故辨论若此。", "4510": "壮盛年岁。形消色夺。诊脉右小促。左小弦劲。病起上年秋季。脘中卒痛。有形梗突。病后陡遇惊触。渐次食减不适。食入不运。停留上脘。腹形胀满。甚则胁肋皆胀。四肢不暖。暮夜渐温。大便旬日始通。便后必带血出。清早未食。自按脐上气海。有瘕形甚小。按之微痛。身动饮水。寂然无踪。天气稍冷。爪甲色紫。细推病属肝脾。气血不通。则为郁遏。久则阳微痹结。上下不行。有若否卦之义。阅医药或消或补。总不见效者。未知通阳之奥耳。", "4511": "平昔湿痰阻气为喘。兹因过食停滞。阴脏之阳不运。阳腑之气不通。二便不爽。跗肿腹满。诊脉沉弦是由水寒痰滞。阻遏气分。上下皆不通调。当从三焦分治。顷见案头一方。用菟丝子升少阴。吴茱萸泄厥阴。不知作何解释。不敢附和。仍用河间分消定议。", "4512": "两年初秋发疡。脉络气血。不为流行。而腹满重坠。卧则颇安。脐左动气。卧则尤甚。吐冷沫。常觉冷气。身麻语塞。肝风日炽。疏泄失职。经以肝病吐涎沫。木侮土位。自多䐜胀。丹溪云。自觉冷者。非真冷也。两次溃疡之后。刚燥热药。似难进商。议以宣通肝胃为治。有年久恙。贵乎平淡矣。", "4513": "脉微而迟。色衰萎黄。蟹为介属。咸寒沉降。凡阳气不足者。食之损阳。其致病之由。自试二次矣。久利久泄。古云无不伤肾。今浮肿渐起自下。是水失火而败。若非暖下。徒见泻泄有红。为脾胃湿热。必致中满败坏。", "4514": "脉左弦右浮涩。始因脘痛贯胁。继则腹大高凸。纳食减少难进。二便艰涩不爽。此乃有年操持。萦虑太甚。肝木怫郁。脾土自困。清浊混淆。胀势乃成。盖脏真日纳。腑阳不运。考古治胀名家。必以通阳为务。若滋阴柔药。微加桂附。凝阴沍浊。岂是良法。议用局方禹粮丸。暖其水脏。攻其秽浊。俟有小效。兼进通阳刚补。是为虚症内伤。胀满治法。至于攻泻劫夺。都为有形而设。与无形气伤之症不同也。", "4515": "向有宿痞。夏至节一阴来复。连次梦遗。遂腹形坚大。二便或通或闭。是时右膝痈肿溃疡。未必非湿热留阻经络所致。诊脉左小弱。右缓大。面色清减。鼻准明亮。纳食必腹胀愈加。四肢恶冷。热自里升。甚则衄血牙宣。全是身中气血交结。固非积聚停水之胀。考古人于胀症以分清气血为主。止痛务在宣通。要知攻下皆为通腑。温补乃护阳以宣通。今者单单腹胀。当以脾胃为病薮。太阴不运。阳明愈钝。议以缓攻一法。", "4516": "患风三月。周身流走作肿。手不能握。足不能履。诊其脉。浮大而数。发热口干。此阴虚生内热。热胜则风生。况风性善行。火热得之。愈增其势。伤于筋脉。则纵缓不收。逆于肉理。则攻肿为楚也。", "4517": "由夏季目黄神倦。渐至中焦胀满。延至霜降。上吐瘀血。下便污浊。按脉弱细不调。视色神采不振。兼以呼吸带喘。素有寒疾气逆。其宿饮之蓄。已非一日。当夏三月。脾胃主令。天气热。地气升。人身气泄。加以饥饱劳役。而遂减食胀满。是皆病于中。绵延上下矣。夫六腑以通为用。不但腑不用事。其间经脉络脉中。气血皆令不行。气壅血瘀。胀势愈加。古人治胀病专以宣通为法。而有阴阳之殊。后之攻劫宣通。如神佑舟车禹功等方。值此久病淹淹。何敢轻试。议以专通三焦之阳气。驱其锢蔽之浊阴。温补兼进。若不阳气渐苏。难以拟投。引用仲景白通汤。", "4518": "一月来。虽经反复。参脉症色形。生阳颇有根蒂。近食蚕豆滞气。腹中微膨。食后口味酸浊。是久卧重著。脾阳运动之机尚少而火升心烦。动气汗出。遗精虽减于昔。未得平复。总是内损已深。若调治合宜。只要精气复得一分。便减一分病象。长夏脾胃主令。培土助纳为要。而精气散越。乃兼摄固之法。刻下味酸微膨。补脾少佐疏胃。宜晚进。其早上另制补摄丸剂。益脏真以招纳散失之气。", "4519": "肌肉松柔。脉小如数。常有梦遗。阴精不固。上年冬令过温。温则腠理反疏。阳动不藏。诸气皆升。络血随气上溢。见症如头面热。目下肉𥆧。心悸怔忡。四肢汗出。两足附肿。常冷不温。走动数武。即吸短欲喘。何一非少阴肾气失纳。阳浮不肯潜伏之征。况多梦纷扰。由精伤及神气。法当味厚填精。质重镇神。佐酸以收之。甘以缓之。勿因血以投凉。莫见下寒。辄进燥热。恪守禁忌以安之。经年冀有成功。所虑壮年志虑未纯。贻忧反复。", "4520": "遗泄。有梦属心。无梦属肾。据述气火下溜。即如溺出之状。茎管中痛。热气上冲。咽喉巅顶掀胀。语言皆怯。此任脉不摄。冲脉气逆。治法。引之导之。摄以固之。现在便溏食少。勿投沉阴腻滞之药。", "4521": "案牍神耗。过动天君。阳隧直升直降。水火不交。阴精变为腐浊。精浊与便浊异路。故宣利清解无功。数月久延。其病伤已在任督。凡八脉奇经。医每弃置不论。考孙真人九法专究其事。欲涵阴精不漏。意在升固八脉之气。录法参末。", "4522": "用甘露饮。淋浊已止。而头晕左肢麻木。胃脘腹中饥则欲痛。咽喉中似有物黏著。咳咯咽痛不解。诊脉左劲右濡。据症是水弱木失滋涵。肝阳化风。过膈绕咽达巅。木乘胃土。阳明脉衰。不司束筋骨以利机关。脘腹中痛。得食则缓者。胃虚求助也。今壮年有此。已属痱中根萌。养肝肾之液以熄虚风。补胃土以充络脉。务在守常。勿图速效。可望全好。", "4523": "肝主筋。肾主骨。阴器者。宗筋之所聚。男子天癸未至。强通其精。异时必有难名之病。今患腰酸痛。宗筋短缩。大便结涩。小便淋沥。足腿消烁。饬肉拘挛。无非肝亏肾损所致。按脉沉细而兼微数。乃精不营筋。又有伏火。内经所谓发为筋痿。及为白淫者是也。治宜滋肾舒肝。使精血渐充。则筋骨亦渐和柔。但幻症日久。非一朝一夕之功。幸弗期速效。", "4524": "浊腻膏淋日下。最易损人津液。络脉遂槁。况八脉隧道纡远。泛然补剂药力罔效。难经谓十二经属通渠。旋转循环无端。惟奇经如沟渠满溢。流入深河。不与十二经并行者也。树根草皮。此症亦难奏效。须用血肉填补固涩。庶可希其获效。", "4525": "勉强攻胎。气血受伤。而为寒热。经脉乏气。而为身痛。乃奇经冲任受病。而阳维脉不用事也。内经以阳维为病。苦寒热。维者。一身之网维也。既非外感。羌苏柴葛三阳之药。及芩栀枳朴之属。辛酸继以苦寒。未能中病。胃口屡伤。致汤饮皆哕出无余。大便不通。已经半月。其吐出形色青绿涎沫。显然肝风大动。将胃口翻空。而肠中污水得风。翔如浪决。东西荡漾矣。熄风镇胃。固是定理。但危笃若。此明理以邀天眷耳。", "4526": "未病先有耳鸣眩晕。恰值二气之交。是冬藏根蒂未固。春升之气泄越。无以制伏。更属产后。精气未复。又自乳耗血。血去液亏。真阴日损。阳气不交于阴。变化内风。上巅犯窍。冲逆肆横。胃掀吐食。攻肠为泻。袭走脉络。肌肉皆肿。譬如诸门户尽撤。遂致暴风飘漾之状。医者辛酸苦降重坠。不但病未曾理。致阳更泄。阴愈涸。烦则震动即厥。由二气不能自主之义。阅王先生安胃一法。最为卓识。所参拙见。按以两脉。右手涩弱。虚象昭然。左脉空大。按之不实。亦非肝气肝火有余。皆因气味过辛散越。致二气造偏。兹以病因大旨。兼以经义酌方。", "4527": "凡论病。先论体质形色脉象。以病乃外加于身也。夫肌肉微白属气虚。外似丰溢。里真大怯。盖阳虚之体。为多湿多痰。肌疏汗淋。唇舌俱白。干呕胸痞。烦渴引饮。由乎脾胃之阳伤残。邪得僭居于中。留蓄不解。正衰邪炽。试以脉之短涩无神论之。阳衰邪伏显然。况寒凉不能攻热。清邪便是伤及胃阳之药。今杳不纳谷。大便渐涩。若不急和胃气。无成法可遵。所谓攻入之病。虑虚其阳。参拟一方。仍候明眼采择。", "4528": "脉濡弱。左胁下久有聚气。纳食酿积于胃脘之中。两三日呕逆吞酸。积物上涌吐出。此皆怫怒动肝。肝木犯胃。胃中阳伤。不能传及小肠。遂变化失司。每七八日。始一更衣。为胃气不主下行故也。法当温胃阳制肝逆。宿病久缠。恐多反复。致成反胃之症。", "4529": "壮年形伟。脉小濡。恶闻秽气。食入呕哕。缘阳气微弱。浊阴类聚。口鼻受污浊异气。先入募原。募原是胃络分布。以上逆而为呕吐。此病理标者。用芳香辟秽扶正气。治本以温上通阳。", "4530": "少腹属肝。肝厥必犯阳明胃腑。故作痛呕。二年来病人已不知因何起病。医徒见病图治。想肝肾必自内伤为病。久则奇经诸脉交伤。经谓冲脉动。而诸脉交动也。议温通柔润剂。从下焦虚损主治。", "4531": "脉弦而小涩。食入脘痛格拒。必吐清涎。然后再纳。视色苍。眼筋红黄。昔肥今瘦。云是郁怒之伤。少火皆变壮火。气滞痰聚日拥。清阳莫展。脘管窄隘。不能食物。噎膈渐至矣。法当苦以降之。辛以通之。佐以利痰清膈。莫以豆蔻沉香劫津可也。", "4532": "凡蛔虫上下出者。皆属厥阴乘犯阳明。内食入胃。呕吐痰涎浊沫。如仲景厥阴篇中。先厥后热同例。试论寒热后。全无汗解。谓至阴伏邪既深。焉能隔越诸经。以达阳分。阅医药方初用治肺胃。后用温胆茯苓饮。但和胃治痰。致深伏厥阴之邪未达。前进泻心汤。苦可去湿。辛以通痞。仍在上中。服后胸中稍舒。逾时稍寐。寐后呕吐浊痰。有黄黑之形。大凡色带青黑。必系胃底肠中逆涌而出。老年冲脉既衰。所谓冲脉动。则诸脉皆逆。自述呕吐之时。周身牵引。直至足心。其阴阳跷维。不得自固。断断然矣。仲景于半表半里之邪。必用柴芩。今上下格拒。当以桂枝黄连汤为法。参以厥阴引经。为通理之使。俾冲得缓。继进通补阳明。此为治厥阴章旨也。", "4533": "脉沉弦。腹痛呕吐。鼻煤舌绛。面带青晦色。夏秋伏暑发热。非冬月。乃误表禁食。胃气受伤。致肝木上干胃土。蛔虫上出。遂成重病。常而厥逆之虑。拟进泄肝和胃。得痛止呕缓。冀有转机。", "4534": "经几年宿病。病必在络。痛非虚症。因久延体质气馁。遇食物不适。或情怀郁勃。痰因气滞。气阻血瘀。诸脉逆乱。频吐污浊。而大便反秘。医见身体肢冷。认为虚脱。以理中和附子温里护阳。夫阳气皆属无形。况乎病发有因。决非阳微欲脱。忆当年病来。宛是肝病。凡疏通气血皆效。其病之未得全好。由乎性情食物居多。夏季专以太阴阳明通剂。今痛处在脘。久则瘀浊复聚。宜淡味薄味清养。初三竹沥泛丸。仍用。早上。另立通瘀方法。", "4535": "胃痛久而屡发。必有凝痰聚瘀。老年气衰。病发日重。乃邪正势不两立也。今纳物呕吐甚多。味带酸苦。脉得左大右小。盖肝木必侮胃土。胃阳虚。完谷而出。且呃逆沃以热汤不减。其胃气掀腾如沸。不嗜汤饮。饮浊弥留脘底。用药之理。远柔用刚。嘉言谓能变胃而不受胃变。开得上关。再商治法。", "4536": "产后三年。经水不转。胃痛。得食必呕。汗出形寒。腰左动气闪烁。大便七八日始通。脉细弦右涩。舌白稍渴。脘中响动。下行痛缓。病属厥阴。顺承阳明。胃土久伤。肝木愈横。法当辛酸。两和厥阴体用。仍参通补阳明之阳。俾浊少上僭。痛有缓期。", "4537": "天癸当绝仍来。昔壮年已有头晕。七年前秋起。胃痛若嘈。今春悲哀。先麻木头眩。痛发下部。膝胫冷三日。病属肝厥胃痛。述痛引背胁。是久病络脉空隙。厥阳热气。因情志郁勃拂逆。气攻乘络。内风旋动。袭阳明。致呕逆不能进食。", "4538": "痛在胁肋游走不一。渐至痰多。手足少力。初病两年。寝食如常。今年入夏病甚。此非脏腑之病。乃由经脉。继及络脉。大凡经主气络主血。久病血瘀。瘀从便下。诸家不分经络。但忽寒忽热。宜乎无效。试服新绛一方。小效。乃络方耳。议通少阳阳明之络。通则不痛矣。", "4539": "诊脉动而虚。左部小弱。左胁疼痛。痛势上引。得食稍安。此皆操持太甚。损及营络。五志之阳动扰不息。咽干舌燥。心悸久痛。津液致伤也。症固属虚。但参术归耆诸方。未能治及络病。内经肝病不越三法。辛散以理肝。酸泄以润肝。甘缓以益肝。宜辛甘润温之补。盖肝为刚脏。必柔以济之。自臻效验耳。", "4540": "古人治胁痛。法有五。或犯寒血滞。或血虚络痛。或血著不通。或肝火抑郁。或暴怒气逆。皆可致痛。今是症脉细。弦数不舒。此由肝火抑郁。火郁者络自燥。治法必当清润通络。", "4541": "诊脉右弦。左小弱涩。病起积劳伤阳。操持索思。五志皆逆。而肝为将军之官。谋虑出焉。故先胁痛。晡暮阳不用事。其病渐剧。是内伤症。乃本气不足。日饵辛燥。气泄血耗。六味滋柔腻药。原非止痛之方。不过矫前药之谬而已。内经肝病三法。治虚亦主甘缓。盖病既久。必及阳明胃络。渐归及右。肝胃同病。人卧魂藏于肝。梦寐纷纭。伤及无形矣。议用甘药。少佐摄镇。", "4542": "小便自利。大便黑色。当脐腹痛。十五年渐发日甚。脉来沉而结涩。此郁勃伤及肝脾之络。致血败瘀留。劳役动怒。宿疴乃发。目今冬深闭藏。忌用攻下。议以辛通润血。所谓通则不痛矣。", "4543": "脉小涩。久因悒郁。脘痛引及背胁。病入血络。经年延绵。更兼茹素数载。阳明虚馁。肩臂不举。仓猝难于奏效。是缓调为宜。议通血络润补。勿投燥热劫液。", "4544": "劳倦嗔怒。是七情内伤。而温邪感触。气从口鼻直自膜原中道。盖伤寒阳症。邪自太阳次第传及。至于春温夏热。则鼻受气。肺受病。口入之气。竟由脘中。所以原有手经见症。不比伤寒足六经之病也。其原不同。治法亦异。仲景论温邪不可发汗。汗则劫津伤阴。身必灼热。一逆尚引日。再逆促命期。又云。鼻息鼾。语言难出。剧则惊痫瘛疭。无非重劫津液所致。今病发热。原不是太阳客邪见症。所投羌防。辛温表汗。此误即为逆矣。上窍不纳。下窍不便。亦属常事。必以攻下希图泄热。殊不知强汗劫津而伤阳。妄下劫液更亡阴。顷诊脉。两手如搐而战。舌干燥而无苔。前板齿干。目欲瞑。口欲开。周身灯照而淡晦。斑纹隐隐约约。几日来时有呃逆。因胃乏谷气而中空。肝阳冲突。上冒肆虐耳。为今返正。先与糜粥。使胃中得濡。厥阳不致上冒。而神昏之累可已。进药之理。甘温可以生津除热。即斑疹亦不足虑。观仲景论中。邪少虚多。阴液阳津并涸者。复脉汤主之。谨仿此义。", "4545": "仲景云。阴气先伤。阳气独发。不寒瘅热。令人消烁肌肉。条例下不注方。但曰。以饮食消息之。后贤谓甘寒生津。解烦热。是矣。今脉数。舌紫渴饮。气分热邪未去。渐次转入血分。斯甘寒清气药中。必佐存阴。为法中之法。", "4546": "腹满已久。非是暴症。近日面颔肿胀。牙关紧闭。先有寒热。随现是象。诊脉右搏数。左小。乃温邪触自口鼻。上焦先受。气血与热胶固。致清窍不利。倏有痹塞之变。理当先治新邪。况头面咽喉结邪。必辛凉轻剂以宣通。若药味重浊。徒攻肠胃矣。仿东垣普济消毒意。", "4547": "脉左数。右缓弱。阳根未固。阴液渐涸。舌赤微渴。喘促自利。溲数。晡刻自热。神烦呓语。夫温邪久伏少阴。古人立法。全以育阴祛热。但今见症。阴分固有伏邪。真阳亦不肯收纳。拟仿刘河间浊药轻投。不为上焦热阻。下焦根蒂自立。冀其烦躁热蒸渐缓。", "4548": "丰腴体质。适值过劳。阳气受伤。呕吐食物。无头痛身热。已非外感风寒。而间日烦躁。渴饮。唇焦。舌黑。是内伏热气。由募原以流布三焦。亦如疟邪分争营卫者然。然有年积劳既久。伏邪客病本轻。脉小缓。按之不无鼓击。可为征验。且二便颇通。略能纳谷。焉有停滞积聚。仲景于瘅热无寒之条。不出药方。但曰。以饮食消息。后贤参圣意。甘寒以养胃阴。其热自解。要知表散之辛温。消滞之苦温。以及苦寒沉降。多犯圣训戒律矣。", "4549": "又诊脉后。腹胸肌腠。登现瘾疹。气分湿热。原有暗泄之机。早间所谈余邪遗热。必兼解毒者为此。下午进药后。诊脉较大于早晨。神识亦如前。但舌赤。中心甚干燥。身体扪之。热甚于早间。此阴分亦被热气蒸伤。瘦人虑其液涸。然痰咯不清。养阴药无往而非腻滞。议得早进清膈一剂。而三焦热秽之蓄。当用紫雪丹二三匙。藉其芳香。宣窍逐秽。斯涸热可解。浊痰不黏。继此调理之方。清营分。滋胃汁。始可瞻顾。其宿垢欲去。犹在旬日之外。古人谓下不嫌迟。非臆说也。", "4550": "又经月时邪。脉形小数。小为病退。数为余热。故皮腠麸脱。气血有流行之义。思食欲餐。胃中有醒豁之机。皆佳兆也。第舌赤而中心黄苔。热蒸既久。胃津与阴液俱伤。致咽物咽中若阻。溺溲尖管犹痛。咯痰浓厚。宿垢未下。若急遽攻夺。恐真阴再涸矣。此存阴为主。而清腑兼之。故乳进食物。便是助热。惟清淡之味。与病不悖。自来热病。最怕食后劳复。举世共闻。非臆说也。", "4551": "又脉神颇安。昨午发疹。先有寒战。盖此病起于湿热。当此无汗。肌腠气窒至肤间。皮脱如麸。犹未能全泄其邪。风疹再发。乃湿因战栗为解。一月以来病魔。而肌无膏泽。瘦削枯槁。古谓瘦人之病。虑涸其阴。阴液不充。补之以味。然腥膻浊味。徒助上焦热痰。无益培阴养液。况宿滞未去。肠胃气尚窒钝。必淡薄调理。上气清爽。痰热不至复聚。从来三时热病。怕反复于病后之覆。当此九仞。幸加意留神为上。", "4552": "病几一月。犹然耳聋。神识不慧。嗽甚痰黏。呼吸喉间有音。此非伤寒暴感。皆夏秋间暑湿热气内郁。新凉引动内伏之邪。当以轻剂清解三焦。奈何医者。不晓伏气为病。但以发散消食寒凉清火为事。致胃汁消亡。真阴尽灼。舌边赤。齿板燥裂。乃邪留营中。有内闭瘛疭厥逆之变。况右脉小数。左脉涩弱。热固在里。当此阴伤日下。久之再犯亡阴之戒。从来头面。皆是清窍。既为邪蒙。精华气血不肯流行。诸窍失司聪明矣。此轻清清解。断断然也。议清上焦气血之壅为先。不投重剂苦寒。正仿古人肥人之病。虑虚其阳耳。", "4553": "又脉右缓大。左弱。面垢色已减。痰嗽不爽。良由胃中津液。为辛散温燥所伤。心营肺卫。悉受热焰蒸迫。致神呆喘急耳聋。清阳阻痹。九窍不利。首方宣解气血继方芳香通窍。无形令其转旋。三焦自有专司。岂与俗医但晓邪滞攻击而已。今已获效。当与清养胃阴肺气。体素丰厚。阳弱不耐沉寒。然深秋冬交天气降。则上焦先受。试观霜露下垂。草木皆改异色。人在气交。法乎天地。兼参体质施治。", "4554": "右脉空大。左脉小芤。寒热麻痹。腰痛冷汗。平素积劳内虚。秋暑客邪遂干脏阴。致神迷心热。烦躁。刮痧似乎略爽。病不肯解。此非经络间病。颇虑热深劫阴。而为痉厥。张司农集诸贤论暑病。谓入肝则麻痹。入肾为消渴。此其明征。议清阴分之邪。仍以养正补之。", "4555": "病已十余日。身尚躁热。舌苔黏腻。神呆目定。脉刚而数。烦躁呓语。此暑湿久伏。与时气之秽邪凝合。酿成胶腻之痰。闭塞清明之府。神情迷昧。胃家浊液蒸遏不宣。药食甘味。必蛔厥上冒。然内经有湿位之下。燥气乘之。是以从之。湿转为燥。若无湿痰之潮气上蒸。舌苔早已燥剌矣。今先滋液。以清烈焰之燔。", "4556": "厥阴为病。必错杂不一。疟痢之后。肝脏必虚。发症。左胁有痞。腹中块儡外坚。胁下每常汨汨有声。恶虚就实。常有寒热。胃中不知饥。而又𩠎杂吞酸。脉长而数。显然厥阴阳明。湿热下渗。前阴阳缩。而为湿热症也。议用升发阳明胃气。渗泄厥阴湿热。其症自愈。", "4557": "脉弦缓。面目肌肤皆黄。舌白滑腻。胸脘膈间胀闭。病名湿温。由濒海潮湿气入口鼻。至募原分布三焦。此为外因。仍食水谷腥物。与外入秽浊之邪。两相交混。湿甚热郁。三焦隧道。气血不通。遂变黄色。发汗不愈者。湿家本有汗也。清热消导不愈者。热从湿中而起。湿不去。则热不除也。夫湿邪无形质。攻滞乃有形治法。其不效宜矣。昔河间治湿热。必取乎苦辛气寒。盖苦降以逐湿辛香以祛秽。寒取乎气。藉气行。不闭塞于内也。当世医者混以伤寒表里为治。殊不知秽湿气入口鼻。游行三焦。不与伤寒同治。", "4558": "中年冲气。痰升喘急。随发随止。从肝肾本病治。固是地黄饮子。用意在浊药轻投。勿以味厚凝滞痰气。但以质能引导至下。变饮为丸。纯是浊药柔温。若归脾汤。甘温守中。养脾之营。更与痰饮冲逆相背。自七月间反复。必有暑湿客气。从呼吸而受。据述肌肤间发丹疹。浮肿甚速。腠膜映红。若但内症。未必有此。思夏秋口鼻受气。上焦先伤。与肝肾本病两途。上焦失解。理必漫延中下。而三焦皆为病薮矣。此胀在乎脉络。不在腑肠。水谷无碍者缘此。况久病大虚。温补不受。必当推其至理。伏邪引动宿病。仲景论必先理其邪。且口渴便实。岂温热相宜。自言怀抱郁结。相火内寄肝胆。如茎肿囊纵。湿壅水渍。勉以三焦气分宣通方。仿古二虚一实。偏治其实。开其一面也。", "4559": "望色。萎瘁晦黯。闻声。呼吸不利。语音若在瓮中。诊脉右缓左急。问初病忽热忽温。头中如裹。腰痛欲拊扪。神识呆钝。昏昏欲寐。肢节瘛痉。咳痰映红。溺溲短缩。便溏带血。不饥不渴。环口微肿。唇干不红。舌白糜腐。此水谷酒腥湿热相并郁蒸。阻挠清气之游行。致周身气机。皆令痹塞。夫热邪湿邪皆气也。由募原分布三焦营卫。循环升降。清浊失司。邪属无形。先著气分。时师横议表邪宜汗。里滞宜消。见热投凉。殊不知热由湿郁。气行热走。仲景于痉暍从湿化忌汗忌下。明示后人勿伤阴阳耳。但无形之邪。久延必致有形。由气入血。一定理也。据色脉症参之。未见或可采用。", "4560": "心下痛。年余屡发。痛缓能食。渐渐目黄溺赤。此络脉中凝瘀蕴热。与水谷之气。交蒸所致。若攻之过急。必变胀满。此温燥须忌。议用河间金铃子散。合无择谷芽枳实小柴胡汤法。", "4561": "面目悉黄。微见黑滞。烦渴腹满。左脉弦数。右脉空大。此内伤发黄。为厥阴肝木太阴脾土二脏交伤之候也。夫肝为风脏。其性喜伸而恶屈。郁则木不得伸而屈矣。郁极则其气盛而风乃发。风发必挟其势以贼脾。脾为湿土之司。土受克而气不行。则湿胜矣。风性虽善行。遇湿以留之。反壅滞经络而不解。由是湿停阳瘀而烦渴有加。其发黄也必矣。虽曰风湿所致。实由木亢而不宁。土困而不舒。非外来风湿之比。况黑色见于面。则知并伤其肾。以脾病不行。胃中谷气入肾。反将脾中浊气下流。故于黄中见黑滞耳。即其腹满。亦是中气不行。虚热内壅。非结热当下之比。若误下之。则藏气空虚。风从内生矣。若误汗之。则阳气外解。湿愈不能行矣。为商治法。平肝之亢。扶土之虚。兼解郁热以清气道。除湿蒸而和中气。", "4562": "脉数。目眦黄。舌心干白黄胎。口中黏腻。脘中痞闷。不思纳谷。由于途次暑风客邪内侵。募原营卫不和。致发疟疾。夫暑必兼湿。湿也。热也。皆气也。气与邪博。则清浊交混。升降自阻。古称湿遏必热自生矣。圣帝论病。本乎四气。其论药方推气味。理必苦降辛通。斯热气痞结可开。消导攻滞。香燥泄气。置暑热致病之因于不治。不识何解。", "4563": "湿热与水谷交蒸。全在气分。尝称三焦。分消清解。既成间日疟疾。邪正互争。原无大害。初误于混指伤寒六经。再谬于参术守补。致邪弥漫。神昏喘急。妄谵痉搐。皆邪无出路。内闭则外脱。求其协热下利。已不可得。诊脉细涩。按腹膨满。夫脾满属气。燥实在血。今洞利后。而加腹满。诸气皆结。岂须闭塞而然。溃败决裂至此。难望挽救。", "4564": "脉小涩。病起疟后。食物不和。仍诵读烦劳。遂至左胁连及少腹。常有厥气。或攻胃脘。或聚腹中。凝著䐜胀。古语云。胀不离乎肝胆。亦犹咳不离乎肺也。盖肝得邪助。木势张扬。中土必然受侮。本气自怯。运纳之权自灭。清阳既少展舒。浊阴日踞。渐为痞满。上年温养。辛甘久进。未见病去。其治体之法。谅不能却。自述静处病加。烦动小安。其为气血久阻为郁。议用通络法。以病根由疟久。邪留络中耳。", "4565": "前议劳伤阳气。当知内损邪陷之理。凡女人天癸既绝之后。其阴经空乏。岂但营卫造偏之寒热而已。故温脾胃。及露姜治中宫营虚。但畏寒不知热。为牝疟。盖牝为阴。身体重著。亦是阴象。此辛甘理阳。鹿茸自督脉以煦提。非比姜附但走气分之刚暴。驱邪益虚。却在营分。难经曰阳维脉。为病发寒热也。", "4566": "脉沉舌白呃忒。时时烦躁。向系阳虚痰饮。疟发三次即止。此邪窒不能宣越。并非邪去病解。今已变病阴冱。痰浊阻塞于中。致上下气机。不相维续。症势险笃。舍通阳一法。无方可拟。必得中阳流运。疟症复作。庶有愈机。", "4567": "伏暑冒凉。发疟。以羌防苏葱辛温大汗。汗多卫阳大伤。胃津亦被劫干。致渴饮。心烦。无寐。诊脉左弱右促目微黄。嗜酒必中虚谷少。易于聚湿蕴热。勿谓阳伤骤补。仿内经辛散太过。当食甘以缓之。", "4568": "脉微弱而细。鼻准独明。昼日形冷汗泄。不饥少纳。脘腹常痞。泄气自舒。此阳气失护卫。而寒栗汗出。阳失鼓运。而脾胃气钝。前进养营。亦主中宫。想因血药柔耎。阳不骤苏。初进甚投。接用则力疲矣。询其不喜饮汤。舌颇明润。非邪结客热之比。议用理中汤法。专以脾胃阳气是理。不独治病。兼可转运日前之药昔贤以疟称为脾寒。重培生阳。使中州默运。实治法之要旨。", "4569": "疟有十二经。然不离少阳厥阴。此论客邪之伤。若挟怫郁嗔怒。致厥阳肝气横逆。其势必锐。经言肝脉贯膈入胃。上循喉咙。而疟邪亦由四末扰中。故不饥不食。胃受困也。夫治病先分气血。久发频发之恙。必伤及络。络乃聚血之所。久病必瘀闭。香燥破血。凝滞滋血。皆是症之禁忌也。切宜凛之。", "4570": "疟后耳窍流脓。是窍闭失聪。留邪与气血。混为扭结。七八年之久。清散不能速效。当忌荤酒浊味。卧时服茶调散一钱。患耳中。以甘遂削尖。插入耳内。衔甘草半寸许。两年前晨泄。食入呕吐。此非有年体质之脾肾虚泻。可以二神四神治也。盖幼冲阳虚。百中仅一耳。今泻泄仍然。寒热咳嗽失血。月事不来。脉得弦数。形色消夺。全是冲年阴不生长。劳怯大著。无见病治病之理。保其胃口。以冀经通。务以情怀开爽为要。勿恃医药却病。", "4571": "脉右数左细数。面垢舌燥。白苔点点。肌肤甲错。左胁动气。伏暑当秋凉而发。初病如疟。当从苦辛寒法。里邪炽烈。变为下痢。胃津液劫。阴液大耗。昔贤于热病受涸。急以救阴为务。苟胃关得苏。渐以冀安。否则犯喻氏所指客邪内陷。液枯致危之戒矣。", "4572": "泻痢起于长夏。医谓时令湿热。胃苓汤芩芍法。固非谬讹。因高年肾阳肝阴先亏。使客气内扰。阻遏中流。乏砥柱坐镇。致狂澜滔天耳。病经两旬不减。重阴无阳。验诸神识甚清。其外邪为少。而内损为多。八脉无权。下无收摄。漏卮不已。理必生阳泄。下焦冷。此皆阴阳二气绝微。治病则夯。治本则宜。非置之不理。实究天人而已。", "4573": "初起无寒热。即泻痢呕恶不食。乃噤口痢重病。夫暑邪之伤。由口鼻吸气而入。邪与水谷交混。蒸变湿热。酿为积滞脓血。肠胃气窒。欲解不能通爽。遂致里急后重。香连苦辛。理气导湿清热。初用颇是。皆缘劳碌之人。非膏粱温养之质。淡薄积劳。中气易伤。四十日来。积少痛缓。医称病解。而食不下咽。不知饥饱。诊得脉弦形衰。舌白。不渴饮水。日泻数行。全是胃倒气夺。中宫损极。下关不摄。谷不能咽。焉能承受汤药。药味气劣。胃衰必恶。久痢久泻。务在能食。古人非醒脾胃。即安肾摄纳。再询粉浆下咽。或呛或噎。议以上脘宜通其清阳。下焦当固其滑脱。仿古方中参苓白术散末。当以米饮日服二次。间以不腻滑之物。食些少勿多。以示胃之所喜为补。必须胃气渐苏。方可转危为安。", "4574": "平素操持积劳。五志之火易燃。上则鼻窍堵塞。下有肛痔漏红。冬春温邪是阳气发越。邪气乘虚内伏。夫所伏之邪。非比暴感发散可解。况兼劳倦内伤之体。病经九十日来。足跗日肿。大便日行五六次。其形黏滞。其色黄赤紫腻。小便不利。必随大便而稍通。此肾关枢机已废。二肠阳腑失司。所进水谷脾胃。不主运行。酿湿坠下。转为瘀腐之形。正当土旺。入夏脾胃主气。此湿气内淫。由乎脾肾日伤。不得明理之医。一误再误。必致变现腹满矣。夫左脉之缓涩。是久病阴阳之损。是合理也。而右脉弦大。岂是有余形质之滞。即仲景所云。弦为胃减。大则病进。亦由阳明脉络渐弛。肿自下而上之义。守中治中。有妨食滋满之弊。大旨中宜运通。下宜分利。必得小溲自利。腑气开阖。始有转机。若再绵延月余。夏至阴生。便难力挽矣。", "4575": "脉沉缓。肌肉丰盛。是水土禀质。阳气少于运行。水谷聚湿。布及经络。下焦每有重著病痛。食稍不运。便易泄泻。经水色淡。水湿交混。总以太阴脾脏。调理若不中窍。恐防胀病。", "4576": "脾宜升则健。胃宜降则和。盖太阴之土。得阳始运。阳明之土。得阴自安。以脾喜刚燥。胃喜柔润。仲景急下存津。治在胃也。东垣大升阳气。治在脾也今能食不运。医家悉指脾弱是病。但诊脉较诸冬春。盛大兼弦。据经论病。独大独小。斯为病脉。脾脏属阴。胃肺属阳。脉见弦大。非脏阴见病之象。久病少餐。犹勉强支撑。兼以大便窒塞。泄气不爽。坐谈片刻。嗳气频频。平素痔疮肠红。未尝安适。此脉症全是胃气不降。肠中不通。腑失传导变化之司。古人云。九窍不和。都属胃病六腑为病以通为补。经年调摄。不越参术桂附。而毫乏应效。不必再进汤药。议仿丹溪小温中丸。服至七日。俾三阴三阳一周。再议治之。", "4577": "汤食下咽。嗳噫不已。不饥不食。大便干坚若弹丸。大凡受纳饮食。全在胃口。已经胃逆为病。加以嗔怒。其肝木之气。贯膈犯胃。斯病加剧。况平昔常似有形骨梗脉得左部弦实。气郁血结甚肖。进商辛润方法。", "4578": "阳明脉大。环跳尻骨筋掣而痛。痛甚足筋皆缩。大便燥艰常秘。此老年血枯。内燥风生。由春升上僭。下失滋养。昔喻氏上燥治肺。下燥治肝。盖肝风木横。胃土必衰。阳明诸脉。不主束筋骨。流利机关也。用微咸微苦。以入阴方法。", "4579": "因大声喊叫。至右耳失聪。想外触惊气。内应肝胆。胆脉络耳。震动其火风之威。亦能郁而阻窍。治在少阳。忌食腥浊", "4580": "肾窍开耳。胆络脉亦附于耳。凡本虚失聪。治在肾。邪干窍闭。治在胆。乃定例也。今年已六旬。脉形细数。皆是肾阴久亏。肝阳内风上旋蒙窍。五行有声。多动真气火风。然非苦寒直降可效。填阴重镇。滋水制木。佐以咸味入阴酸以和阳。药理当如是议。", "4581": "高年。目暗已久。血络空虚。气热乘其空隙。攻触脉络。液尽而痛。当夜而甚。乃热气由阴而上。想外科用酒调末药。必系温散攻坚。因此而痛。虚症可知。", "4582": "（案6）左脉空搏，阳不潜伏。咳吐涎沫。", "4583": "（案12）脉大，咽干，痰多，咳甚，食下腹闷。此风温日久，劳倦内热，津伤液燥也。", "4584": "（案13）风温入肺。咳嗽，脉坚搏，夜卧汗出。阴分先亏，兼多失血。大忌发散苦辛，从温邪当甘润而解治。", "4585": "（案27）风温入太阴，气郁热聚。咳喘，口渴。营卫失和，周身掣痛。脉右搏，防失血。", "4586": "（案31）积劳、饥饱、惊恐，全是内伤。当春仲大气发泄，腰痛足冷，已现下虚本病。辛散苦降，阴阳再伤，致白利口渴，神呆不语，脉细促，容晦暗。少阴真气重损，有昏谵厥脱之虑，非忽视之证也。", "4587": "（案32）左脉脉坚数甚，舌喑不语，得饮微呛、微呃。此温邪内伏，少阴水亏液燥，热气上冒，乃中厥之象。老年最怕面赤神昏，为衰脱耳。", "4588": "（案6）暑风，头胀，口渴，身热，呕痰，脉弦。防疟。", "4589": "（案15）潮热，耳聋，汗出，神识昏冒，脉细数，下垂入尺。壮年热病，脉神若是之衰，怕其昏厥在迩，以上实下虚故也。拟复脉法。", "4590": "（案16）脉右弦，中痞。暑邪入里，三焦俱病，况发汗后热不解，其病不在表可知矣。进苦胜于辛方法。", "4591": "（案19）暑热多日，深入血中，所以衄血，热泄身凉，顷诊脉弦左搏。连日呕逆，胃气受戕，而发散、消食多是劫耗胃汁之物，几日伤触为霍然之理，意者变疟，或旬日不晓饥饿，竟有诸也。", "4592": "（案21）脉左数，下重，热入血中，恐胎元难保。暮夜热烦无寐，亦是阴伤。太仆经云：寒之不寒，是无水也，当益其阴。今衄血又来，应减气辛耗散之剂，仿苦寒佐以咸寒为法。", "4593": "（案22）脉形细小搏数，舌刺，肌燥，津液告涸，呕逆烦冤，食粥乃定。胃气已虚，虑有变症。清热安胎为主，而养胃兼之。", "4594": "（案27）脉形略起，按之短涩。进温中下气，似乎闪烁欲动，知阳微气结有形，非真食滞重著之物。愚见不用寒凉犯胃，以肥人之病，虑虚其阳，矧夏月阴气在里，里之有形，便是浊阴。《内经》云：诸痛为寒内客。今暑热交迫，理无外寒，然口食凉茶瓜果，此水寒人脘，未能即为热。素因脾胃阳弱，以致津液不运，自有烦渴。再验舌色，未必定以实热。但以辛香开气分之属，可以醒阳，可以宣浊，上下分布，病机自减。高明采取如何？", "4595": "（案29）脉微，阴浊上潜。与真武汤治之。", "4596": "（案32）表热势和，腹痛，泻下白积。明是湿热内侵肠胃，真气不主宣畅。诊得脉坚搏，睡卧露睛，神已先怯。稚年久延，虑有风搐之变。既微微呕恶，胃气亦弱。议酸苦泄热之中佐以辅正为治。候高明体认裁之。", "4597": "（案35）潮热，耳聋，有似阳邪。诊得脉空大，自利不渴，舌上粉苔，形枯色槁，岂是实症？议劳倦挟湿，从脾胃病治。", "4598": "（案36）脉左搏大，右缓。夏秋热气从口鼻入，由膜原以分布脉络。是时水谷腥腻助热聚湿，《经》谓：湿胜则肿，热烁为痛。所患著右脉反左盛，病久其邪深入于血分矣。《经》云：阳明之脉束筋骨以利机关。今躁痛夜剧，便秘未爽，且有渴饮，古称九窍不和，多属胃病，水谷气内蒸，暑湿外侮，内外相搏，痹而不通。当思苦辛寒以宣之，宗河间法以俟备考。", "4599": "（案37）脉沉，目黄，气喘，呛呕，脘闷，肢冷，潮热，汗出略缓，少顷复热，病九日不解，口干，自利。此湿邪内胜为热，三焦不通，夏伏至霜降而发，其病为重。", "4600": "（案38）夏令伏邪至秋深而发，发汗不解，继又泄泻。此伏里之证，与暴感不同，所以表散、和解不能见效。病有四旬，脉细，搏如刃，面色削夺，里热口渴，舌白，病中遗泄。此久热迫蒸，阴伤失守，苦药燥损，津液日枯。因热致病，医不以河间三时法则，分三焦以逐邪，昧于从事陶节庵陋习，宜乎淹淹不已。若不急为调治，久延虚损一途，古人所谓「因病致损」也，慎之！", "4601": "（案41）夏令伏热，至秋而发，即仲景「阴气先伤，阳气独发」之谓也。脉右搏数，胃汁受戕。暂忌厚味，进甘药养胃，内热自罢。", "4602": "（案46）脉短无神，并不口渴思饮，得食欲呕、欲哕，下利黄水八日，身热，汗出不解，时时谵语。防其昏厥瘛疭，以湿热深陷入里也。议用桂苓甘露饮。", "4603": "（案52）夏秋内伏暑湿皆是阴邪。久疮，渐至痞满，形寒，脉小。当温中醒阳，莫以清凉治疮。", "4604": "（案1）先因冬温，真气发泄，继而骤冷，气弱不收。此温邪入肺为咳，肺失降也，《经》谓：右降之气肺主之。而冬令温暖失藏，水源自乏，无以生木，肝为风藏，气升则内风鼓动，乘胃入膈，冲咽上巅。阳明中虚，其脉不立束筋骨、利关节之用。暗风闪烁，右肢肿痛不举，《经》言「风胜为肿」也。经后冲气愈加，血液大耗，所以空动之地，虚风由是而旋。风而曰虚，则非辛散寒燥偏剂矣，是身中左升之气都属肝也。夫人身左右，阴阳之道路，倏升倏降，左右倾欹，不以阴阳造偏为理，则茫无头绪矣。", "4605": "（案8）容色稍夺，脉形渐细，不知饥，不欲食，扪之不为热，而自云热，并不渴饮，间有寒栗之状。此营卫不振，当治中焦。", "4606": "（案11）冬温失藏，肝木反泄，阳明脉虚，血海不按期而经下，乃体不足、用太过之象。法当辛酸甘剂而和肝之阴阳，苦降走泄不但妨胃，更劫耗矣。", "4607": "（案12）肾虚，温邪内侵，形神消烁，废食忘寝，临晚寒热得汗而解。议用复脉法。", "4608": "复脉汤去姜，加芍", "4609": "（案13）脉左搏右细，颧赤，气喘，昨夜大便后汗泄，竟夕不安。冬温伏热，阴衰阳冒之象，最为重症。", "4610": "（案1）冬月伏邪，至春发为温疟。汗出不解，非新感可知。脉虚，先有遗症，最忌耗散真气，和正解邪为稳。", "4611": "（案3）阴疟，脉沉，微背寒，肢冷，食入则脘中痞满。此阳气伤极，春深木旺，恐变肿胀。药宜理中兼理下焦，毋得祛疟治邪。", "4612": "（案15）脉弦如刃，烦渴，脘痞，呕吐，蛔虫上越。此胃气已虚，暑热复入三焦，浊气乘逆，况病后调养失宜，本虚标实。姑进安胃降逆，冀得呕逆缓而气道稍顺，再适。", "4613": "（案20）脉弦迟，形寒，神倦。得之忧思惊恐，卫外阳气暴折，阴寒不正之气得以外袭，将有痎疟病机。宜静摄护阳，庶不致外邪深入为害。", "4614": "（案21）形色脉诊俱虚，寒热劫耗胃汁，脘中不知饥饿，二便皆觉不爽。徒进清凉克消，中宫更加坐困。考古暑病，凡旬日不解，必当酸泄以苏胃汁。元虚之体，恐滋变病。", "4615": "（案22）脉弦，口渴。少阳寒热乘胃，劫津。可与小柴胡汤和以解邪。", "4616": "（案23）脉左弦右软，寒热渐早，渴喜热饮。此胃津日损，木火尚炽。生津养胃，和以达邪。", "4617": "（案25）脉虚，暴热气衰，元无归依，为浮热。知饥甘谷，里无留滞。病后调理，两摄阴阳为主。", "4618": "（案27）暑热远行，热由口鼻而入，犯之上中，分布营卫，故为寒热疟疾。当淡薄食物，清肃胃气。药投凉解芳香，或甘寒生津，皆可疗此。奈何发散以祛寒，不知口鼻受热与皮肤受寒发汗迥别。治之不效，肆行滋补，参、术、耆、地，黏腻中宫，肺气壅闭，胃中滞凝，肿胀自上至下，一身气机不通，张戴人所谓邪得补而热盛，如养寇殃良之比。但病久形寒，而再为攻逐，又虑正气之垂绝。故改汤为丸，丸者缓也，使中焦得疏，渐渐转运，升降得宣，六腑有再通之理，腑通则经脉之气无有不通者矣。每日进丹溪保和丸。", "4619": "二诊：阳气发泄，寒热，脉大。", "4620": "八诊：从来通则不痛。通者，非流气下夺之谓，作通阴、通阳训则可。阅《内经》论痛，都因寒客。今脉左搏而大，气坠便不爽，究是肝气不疏泄。议用辛甘酸甘缓，两和体用。", "4621": "（案29）面赤，口渴，脉大而空。劳倦挟痰，不可纯作时感治。", "4622": "（案30）脉空搏，面赤，舌白，消渴，汗出，昼夜不已，两足畏冷，寒热渐迟。此积劳阳虚，外邪易陷，本虚表热，复加柴、葛，加消导，谓之劫津。仍宜和营主治。", "4623": "（案35）脉虚，寒热，食少，色夺。乃夏秋暑热为疟，久延阴伤，木火内灼，喉痛。", "4624": "（案42）产后下虚，痢止为疟，是营卫交损，况色脉并非外感，补剂并进不应，由治错乱。《经》云：「阳维为病苦寒热。」", "4625": "（案44）脉如平人，但热不寒，烦渴，身疼，时呕。此温疟也。仲景有桂枝白虎一法，一剂知，二剂已也。", "4626": "（案46）痰哮触外邪而发，坐不得卧，肾病为多，以风寒必客太阳，体弱内侵少阴矣。若夫暑湿热气触自口鼻，背部疡疖乃鼻窍应肺，是手太阴经受邪，辛凉气清之药可解。以肺欲辛，其象上悬，气味沉重则药力下走，而肺邪不解。然夏病入冬，气候迭更，热邪久而深入，气血日被损伤。滋清如胶、地，搜逐如鳖甲煎丸无如。不独阴亏，八脉气衰，为寒为热，病形渐延损怯。火升喉痛，上热缓必下热炽，此刚药难投，柔温之养佐通奇脉定议。", "4627": "（案48）久疟，针挑汗出乃止。经脉邪去，络脉邪留，胁下遂结疟母，按之坚，形高突。四年带病，仍然能食、便通，其结聚不在肠胃，药下咽入肠、入胃不效，盖络脉附于腑之外廓耳。", "4628": "（案3）下痢十三日，右关前按之实大，肌表畏冷，卧则神混，转多恶梦，且不欲食，喉舌干涸。脉症不符。思夏至后，阴不克复，阳欲散越，谬议守阴固摄，以护阳根。", "4629": "（案13）脉迟，下利，腹痛，喜热饮，食下则痞胀。平昔饮酒，中宫必有湿滞也。", "4630": "（案23）疟痢并作。经邪入里，色脉已属不足。清邪即当和血。", "4631": "（案24）脉涩，舌绛，耳聋，口渴，下利垢水七日，利后反有喘急。此乃阴气走泄，阳独上冒，有昏厥之危。就腹满一证，亦是热入之征，非轻谈易易可知。", "4632": "（案44）脉虚濡，寒热后咽干，少腹微痛，微痢。因劳碌饮食失节，中气已虚，风木自动，心中苦饥。药宜甘缓熄风。", "4633": "（案49）脉弦，虚劳久咳，肠垢自利。", "4634": "（案50）形损脉垂，咳嗽经月，下痢白腻。此上下交病，当治其中。用建中法。", "4635": "（案1）泄泻食减，由脾胃虚弱，但产后本乎下损，古人云：肾司二便，主乎闭藏；又云：久泻无有不伤肾者。左脉坚搏，肾阴不固，反多疏泄之象。先议摄固守阴法。", "4636": "（案13）脉弦甚于数。因操持萦虑，肝胆阳气久动，内风鼓烁不已，乘胃攻触如饥，不能运食，甚至腹鸣泻水，即《内经》久风飧泻之谓。治法以补阳明之虚，泄厥阴之阳。以形体清瘦，禀乎木火而受刭烁，以耗劫脂液耳。", "4637": "（案21）右脉弦迟，胃脘痛至少腹，得泄泻则痛缓，小溲不利。中下阳衰，不主运化，以膀胱腑气失职。进济生法，通腑纳下，佐以建中理阳，冀免单胀之苦。", "4638": "（案22）脉虚数，上咳下泄，食减形夺。大忌寒凉治嗽，当平补足三阴，以崇生气。若失治延绵，恐成劳怯。", "4639": "三诊：脉数。", "4640": "（案24）霜降节，脉大空搏，久泻。中下失固也。", "4641": "（案1）脉沉弦，是属饮，饮为阴类，偏于夜分、上午冲逆，不得卧。胃气纳谷，脾失散布，水湿渐渐旁渍，不得循经入腑，由肿为胀，因胀成喘，其理甚悉。仲景云：饮家而咳，当治饮，勿治咳。议以青龙之制，先开足太阳为第一。", "4642": "（案3）脉沉弦，留饮久咳，乃清阳失司旋转，渐至气机窒塞。此腻滞补阳无益，仲景云：饮家，当治饮，勿治咳。", "4643": "（案6）怀妊八月，久咳，背冷，脉沉，气冲不得眠。此因抑郁，阳失旋转，浊凝饮结。当治饮不治咳。", "4644": "（案10）饮泛浊壅，经脉不通。", "4645": "（案13）脉虚饮泛，喘咳浮肿。肾气丸以涤饮。", "4646": "（案14）此水结聚，壅遏经隧，致呼吸有阻为噫，而其声在咽底。况任脉行于身前，女子经行必关冲任。今气痹水畜，血亦化水为肿胀，胸高腹大，水性就下搏激，可使过颡，下窍久闭，状如瓮底，曷不师神禹治平之功？徒执寒热补泻为法，宜乎久药无功矣！", "4647": "（案15）冬至一阳初复，骤有肢麻、火升，其失藏已属下虚。月余，值黄昏，气塞心痛，喘逆，戌刻阴时冲逆，下起肝藏，厥逆直将犯上，至于坐不得卧，直至产后下虚更极，水谷湿气未能循腑，分流旁渍，渗入经脉，从前厥逆，肝气、肝风油然沸腾，搏激似湍水，东西可使过颡之喻。究竟病根全在平昔抑郁，《内经》惊恐明指肝肾，今既失司，腑气不司宣化，至阴之藏，调之非易。议以专走足太阳表中之里，冀得阴阳渐分，《经》旨谓「太阳司开」立法。", "4648": "（案19）脉沉实，风水浮肿，四肢不得屈伸，二便不利，中脘喘急。三焦经络阻塞，不得流行。宜先通膀胱经腑，以足太阳司开故也。", "4649": "（案23）从咳嗽继以肿胀，自上焦起，即风水、皮水之证，治节不行，一身气痹。《金匮》谓：脉浮，初病在表。经年正馁，脉沉，里受伤矣。议进越婢法。", "4650": "（案29）脉弦为饮，年高下虚，天冷真气少纳，气冲为咳。乃哮嗽之症，最难除根，天暖自安。", "4651": "（案40）面赤，足冷，脉沉弦细，吸短有声，昏昏欲寐，下焦淋带不断。此下虚不摄，饮浊上泛，咳无止期。从来饮家咳逆，当治其饮，仲景谓：饮家短气倚息，以外饮属脾，用苓桂术甘理脾阳以运行；内饮属肾，进肾气以收摄固纳。", "4652": "（案42）脉数，形寒肢冷，先以大汗淋漓，渐渐不思纳谷。酒客阳微痰咳，清气不得旋转，昔肥今瘦者为饮。宜理其阳，用苓桂术甘汤主之。", "4653": "（案44）脉小促，舌黄，语塞，口渴，喘息，下利黑水。此伏邪在里，当新凉雨湿而发。十日来寒热不止，汗泄甚多。已非暴感见症，全属里邪久伏，客气必从热化。故外郁之喘属肺，里热肾气不纳，亦多喘急，况胸满微呕，不思谷食，咳呛频频，寤而不寐，里气上逆，热迫下利何疑？法以古人越婢兼小青龙合剂，使太阳得开，冀肾气缓、上逆平耳。", "4654": "（案45）色痿腠疏，阳虚体质，平昔喜进膏粱，上焦易壅，中宫少运，厚味凝气蒸痰，频频咳呛。但内伤失和，自可薄味清肃。医用皂荚丸搜攒，肺伤气泄，喷嚏不已，而沉固胶浊仍处胸臆膜俞之间。玉屏风散之固卫，六君子汤之健脾理痰，都是守剂，不令宣通，独小青龙取饮以就太阳，初服喘缓，得宣通之意耳。夫太阳但开，所欠通补阳明一段工夫，即不得其合，斯暂开复痹矣。且喘病之因，在肺为实，在肾为虚。此病细诊色脉，是上实下虚，以致耳聋鸣响。治下之法，以壮水源冀熄内风为主。而胸次清阳少旋，浊痰阻气，有妨于食。至卧时，继清肃上中二焦，小剂静守。常理百日图功，至于应接事务烦劳，自宜省究，勿在药间也。", "4655": "（案46）交深秋暴冷，哮喘并频嗽。虽有新凉外束致病，然色脉素昔遗患，乃肾虚气少藏纳，况曾有失血之症。议用固摄。", "4656": "（案49）幼年哮喘，是寒热失和，食味不调，致饮邪聚络。凡有内外感触，必喘逆填喘噫，夜坐不得卧息，昼日稍可舒展，浊沫稀涎，必变浓痰，斯病势稍缓。今发于秋深冬初，其饮邪为阴邪乘，天气下降，地中一阳未生，人身藏阳未旺，所伏饮邪外凉相召而窃发矣。然伏于络脉之中，发散攻表、涤痰逐里、温补与邪无干。久药无效，为此治法：夏月阴气在内时候，艾火灸肺俞等穴，更安静护养百日，一交秋分，暖护背部，勿得懈弛。病发之日，暂用汤药三四日即止。平昔食物尤宜谨慎。再经寒暑陶熔，可冀宿恙之安。发时背冷气寒，宜开太阳逐饮，用青龙法。", "4657": "（案6）酒客中虚，湿热内阻，经脉之气不主流通，兼长夏地中湿气升腾，蒸郁发黄。虽六淫气侵为外感，而脾胃不和已属内伤，本虚标实，徒以渗利治黄，自然无效。直待秋凉，湿热气衰，痿黄势减，但所伤正气未复，仪容日损，食少便溏，不堪任劳耐烦。况五旬以外，阳气日薄，冬月不复，即为失藏。议以脾肾两治，重培先后天生气，守常填摄，冀免单胀痞满之变。", "4658": "（案7）久病脉弦，脾胃大困，水谷失运，气道壅塞，渐生胀满，前曾发黄。都属肝脾郁结。数月内损不复，长夏恐致增剧。处方聊以参末议，未必顿可却病。", "4659": "（案4）溃疡未合，频进培补，反昼夜微寒、潮热，食物日减，形神日损。近日热甚衄血，口干舌绛，肉腠麻木。乃大虚之体，夹杂暑热客气，深虑液涸昏厥。议复脉汤。", "4660": "复脉汤（即炙甘草汤）", "4661": "（案7）阴分果虚，经脉有湿热阻塞，所以下焦发疡，津液不得上涵，遂久咳不止。幸得不致伤及中宫，薄味静养图安。", "4662": "（案9）督脉虚，腰背痛，神倦，痔血。", "4663": "五朝：神识颇清，全赖苦降之力。论年长出痘，人事已晓，肝中相火、肾藏龙火皆得升腾，少阴脉循咽挟舌，厥阴脉贯膈绕咽，一水不能制二火，恐其阻塞咽喉，阳气燔灼。涌吐涎沫，如漆如胶，原在难治之条。《经》云：火淫于内，治以苦寒，佐以咸寒。咸能润下，直入至阴，不但痘门，通套法也。", "4664": "（案5）湿有五。肥人之湿多起于脾，脾主湿，又主土，土气不旺，湿邪无路可出，则变而为痰，化而为热，所谓湿生痰、痰生热是也。湿热痰体亦既有年，姑置勿论，且说（俗惟）病经两候，痛泻起因，继以寒热往来，一日两三度发，其间呃忒频频七日，显系冷风外感，内从少阳而入，里气不纳，上逆冲激，出入无定使然。当时汗出太多，虽有口苦、呕恶等症，却难和以小柴胡汤。现在汗已不少，吐亦未除，下又通矣，三法自行而疟疾仍作，胸前痞闷，脉右软滑，左觉空弦，神情困倦，语言无力，饮食不思。中气大虚，邪气尚盛，汗、吐三法，既不可施，惟以和寒温之例，尚可以行。常念丹田有热，胸中有寒，白苔滑者，仲景曾出黄连汤一方，喻氏师之，以为和上下法之计。又念汗、吐、下三法之后，胸前作痞，噫气不舒者，仲景用代赭旋覆汤，通其阳，镇其逆，俾得呃不再呃，想亦未始不合。如此治法不独为新病而设，即旧时之湿热生痰亦与焉。和方之制，和其不和者也。不和于已虚之后，窃恐虚波暗起，未可忽略。", "4665": "复诊：今晨寒热又作，来势颇轻，呕亦稍定，苔又渐薄。所受风寒湿热却有暗化之机，似属佳兆，无奈脉之弦滑，多带空象，元气阳气实已内虚，而有邪不得不以扶正化邪为法，恐邪未尽而正先尽矣。", "4666": "又诊：细绎此病，风邪外感，内蒸湿热浊痰，古人所谓夹病。此等症也，何以见之？风入少阳则为寒热往来，半在表，半在里，出而与阳争则寒，寒宜不饮；入而与阴争则热，热宜发渴。此乃寒喜热饮，热反不渴，若无湿热浊，何以如是之故（难解）。白苔满布，面色晦滞，脉弦右滑，尽带空濡之象。欲去其风，必须化湿、化热、化痰，以除兼夹之气邪，则风邪寻路而出，不被兼夹所持矣（再解）。然热自痰生，痰从湿化，即欲化痰、化热，必须化尽湿邪（主脑乃解）。西昌云：舍助阳外，无驱湿之法，明示人以温通为主。将来附子理中汤、连理辈，一定章程，其中损益，尤须临病斟酌，活法在诸高明也。设使兼夹之邪，日化一日，而疟机未脱，仍可用小柴胡汤和之（原）。或寒热渐轻，但师其意不取其方，亦无不可（再原）。诸高明自有洞见，何庸多议？此不过主人之意，聊以应命而已。", "4667": "（案6）此伏暑晚发之病也。暑邪者何？天之热气下，地之湿气上。人在气交之中，无隙可避，感而受者，遂病为暑。假使发于当日，其邪易达，其气未深耳。惟深伏三焦，直至秋晚而发，道远气深，自内达外，焉得一病便轻？所以病经十有三日，日重一日矣！然伏邪仅在三焦，不过寒热分争之下，所见者无非胸前痞闷，口中甜腻，二便失调而已。兹乃肢麻不已，更见厥逆，显系所患之邪不从三焦而出，反入于肝脾。肝者，将军之官，其性横逆，上犯肺经则为厥，旁流中土则为麻，麻厥并至，不惟邪盛，早见肝阳逆矣！然肝阳之逆，暑气之侵，亦非无故而作，必由风喜伤肝，未病之前，先招风气，引动伏邪，加以阴气素虚，肝失所养，所谓最虚之处，便是容邪之地。三焦之病，累及乎肝，最为恶候，能不虑其虚不化邪、厥逆频频乎？所幸者胆亦受暑，胆属少阳，其机为枢，有出入之意焉，是以寒热之势变为寒热往来，间日而作，俾得病情从此渐轻。不独肝脏可以外传于腑，即留在三焦者，亦可望其归并也。但少阴本虚，脉弦而芤，最恐欲化不能，亦防半途而废。邪实正虚，用药最难，权就寤言不寐、多梦纷纭、邪在胆经为甚者立方，候正。", "4668": "（案7）喘出于肾，关于肺，标本同病。始而邪盛，继以正衰，大非久病所宜。「热在上焦者，因咳为肺痿」，仲景早已言之，非无意也。肺之一脏，外为热火所烁，内被肝火上燔，金不生水，水不涵木，木反侮金，其畏如虎。专与复脉汤治其下，苇茎汤治其上，以冀弋获。", "4669": "（案8）夏间伏暑，至秋末而发，亦云晚矣。晚则其道远，其气深，横连于膜原，外发于阳明。所以初发之时，仅见蒸热，虽得汗泄而不能解，今已二十日矣。曾经化火发渴、发干，阴分必伤。伤阴化燥，本属暑邪见症，而况阳明中土，万物所归，尤易化火伤津者乎？然阳明化火伤津，不过清之、养之而已，尚可有为，无如所患之火，内挟饮食之积，结而不开，盘踞小肠，上升则口糜，下注则便泄，泄还不已，转而为痢，其色黄而带灰，红而带白，便则多痛，以昭邪盛则实之意焉。设使胃家气旺，肾脏不虚，而用攻克之剂，尚可以胜其任者，原为幸事。而饮食不思，神情困倦，面白带青，肌肉暗削，小便不利，少阴、阳明之生气索然，津液告竭。急急补助，已恐鞭长莫及，岂能再用攻克？诊得右脉弦数，左脉细小，细小为虚，弦数为实，虚中有实，用药两难，惟有猪苓汤一法，最为痢后伤阴所宜。然下焦可治，而中焦之结者，肝阴之亏者，仍未得以兼治，参入青六一方，佐以芍药甘草汤一方，而三法备焉，以冀弋获，否则悠悠忽忽而脱矣。", "4670": "次诊：进猪苓汤后，所见下痢已减其半，所化之邪亦减其半，所以唇之肿者已消，齿之垢者能清，以及右脉之弦数者能缓、能和，似属佳兆。然左脉细小，按之仍属无神，且兼关部带弦。弦主乎肝，细小无神又主真阴不足，惟以不足之真阴难以涵养肝木，肝木顺乘中土，尤为易事。如中土尚属有权，往往于病邪消化之后，胃口渐开，生机可望焉。乃胃中之津液早被热气所伤，又为下痢所劫，一伤一劫，杳不思纳，干哕、恶心，所谓劫津病至，津竭祸来，此等症是也。若论小肠盘踞之邪，痛势仍然按之未减，而其位置则已近乎少腹，而不连于胁部，势欲下行，还未归并大肠，即使贻患将来，不过为痈为血，尚可徐图。惟此虚态百出，变生眉睫，能勿惧乎？然则阴尽痢止，最为危候，不得不宗「七虚三实，扶正为先」之训，而回元气于无何有之乡，再图侥幸。", "4671": "（案9）红疹属血，白痦属气，气血同病，疹㾦并发，发则为病易解矣，神必清矣。兹乃既发白㾦，又发红疹，而神反昏沉，身热不退，气息短促，加以舌缩质红，其苔灰白，遍身自汗，足肿逆冷，甚至下唇震动，两手亦然，昨日多喜笑，小便自遗，本来咳呛，今反寥然，水饮与之则咽，不与亦不思。诊得右寸脉形滑数，关部濡软，左手皆细小，按之模糊，想是风邪外感，引动温邪，又被湿痰所阻，元气受伤，走入手足厥阴也。势已危笃，每易悠悠忽忽而脱，邪从汗出，元气亦与之俱出，正在势不两立之时，最为棘手。勉从「虚羸少气」例治，以冀邪尽而正不与之俱尽。", "4672": "（案10）胃脘当心而痛，继以形寒发热，如疟而作，甚至呃忒频频。此系温邪外感，秽浊内踞，加以湿痰食滞，交结中宫也。设使中宫之阳气内旺，所受之邪容易化达。兹乃元气本虚，诸邪又伤，后无力消除，病延多日，所以脉象空弦，神情困倦，非补不可时也。但舌苔白腻，干欲热饮，下体先痹，今更作麻，哕逆恶心。邪恋肺胃，而肾气亦衰，用药极难兼顾。然温养中宫，佐以上下分治之品，俾得一举而三善备焉，以冀即日见长为幸。否则气息易喘，恐增额汗，伊可畏也。", "4673": "次诊：进前剂麻痹得和，四肢得暖，且有吐出陈腐酸苦，其色若尘，此皆得温而通也。然呃忒频频、气息短促、呻吟不绝、哕逆呕恶之象，仍不克除，神情困倦，左脉空细，右脉弦急，大便溏黑，喜饮热汤。湿痰邪滞之外，又有瘀血在里，邪从上出，不自下行，已为逆症，而况呕吐之时曾经额汗，能不虑其虚波暗起而脱乎？哕逆呕吐，无不由于气之所载，气若不平，诸症何能化解乎？再将前方加减，先使气平为安。", "4674": "三诊：呃忒日轻，呕恶日重，此即陈腐之邪内阻气机。为呃者多从呕出，所以一则见轻，一则见重也。然病根欲拔，其所出之路逆而不顺，上而不下，颇失「胃气下行为顺」之理，却为累焉。昨夜额虽无汗，今朝脉尚弦急，呻吟未绝，所留陈腐之邪尚在中宫，犯肺为咳，犯胃为呕，直从中道而立，犹带呃忒。必须去尽宿邪，庶几有望。", "4675": "四诊：荡涤宿邪之下，呕恶大减，呃忒日缓，脉象稍和，呻吟渐除，大便叠通。夫乃胃有下行为顺之兆乎？去疾莫如尽，尚须磨荡下行，继之于后，可卜其旋元吉。", "4676": "（案11）阳络伤、血外溢之后，脉宜静。此乃脉细而数，数则为动，细则阴虚，所以气急喘促，胸闷胁痛，面色萎黄，语言无力，小溲清白，大便漆黑，心悸少寐，气逆闷。动则火升，倦则阳举，无一而非虚阳上扰、阴血下虚、气不归元之象。先哲云：「气有余便是火」，气不足即是寒，不足之气反见有余，此非真火，乃是虚寒，阴不变阳，血不配气，以致此也。欲降其气，必先补阴，理固然耳。", "4677": "生脉散冬瓜子石决明葳蕤枇杷叶川贝母薏苡仁广橘红白茯苓燕窝", "4678": "（案12）太翁之病，肝肾素虚，肺胃新感之病也。花甲之年，即使不病新邪，筋骨间早已空虚，何堪再经磨耐？因病致虚，因虚益病也，乃又经食消克之剂，在所必需。幸而外热递减，内热不清，咳嗽痰黏，咯吐不爽，气促形倦，纳少胃呆，舌苔或黄或白，现在又多剥象，左胁曾痛，两膝常屈，卧床不起，小溲乃黄，加之音不能扬，睡中言语，显系肺胃两经之热。既不能从外而泄，又不能从上而清，邪无出路，断无中道而立之理，势已逼入下焦，两伤肝肾。邪之所凑，其气必虚；留而不去，其病为实。实则泻之，虚则补之。以使补不碍其邪，泻不伤其正，一举两得，方合实必顾虚之计。此等立法，似乎从症，而未及脉，然所诊之脉，亦无不合之理。右寸关部弦而且滑，左关尺部细而且数，数则为热，滑则为痰，弦主乎肝，细主乎肾，岂非肺胃两经之热痰正盛、肝肾两经之虚气大昭乎？无怪乎其气从左逆，卧不能侧，更著上实下虚之症焉。为日已久，肺失清肃之司，相傅无权；肾失封藏之本，作强无主，而来此喘息，标本都伤，何恃不恐？必得药随病转，首能呼吸调和，庶几循循而治。否则气不归元，难卜其旋元吉矣。", "4679": "（案14）肝者，将军之官，女子以此为先天，与男子不同。大病后先天未经复元，肝血内亏，不能涵养肝木，肝性刚强，入营则吐血，入胃则脘疼，上升则头眩，肝经之病，可云甚矣！设使脾土内旺，尚可生金，金来制木，不足虑也。无如此际健运失常，湿从下走，五更溏泄；甚至湿郁中脘，腹中雷鸣；湿又郁而为热，其气上行，耳中嘈嘈，出脓、出汁，今更失其聪矣！脾经之弱，自顾不暇，岂有生金制木之功哉？然肝为刚藏，顺乘中土（克土），本属易事；横逆肺金（侮金），亦不为难。以不难侮金之木，偏遇肺失清降，木寡于畏，咳嗽数月，时见鼻衄，左脉过弦，右寸上溢于鱼际，甚至少腹有形之气从左而起，从下而止，或攻于左胁，或逆于右胁，或塞于中，或作呕恶，竟有骤变为厥、缓变为臌之形，岂容渺视？然肝属乎阴，阴中木火存焉，不左其金，无以为治。但面色萎黄，肢体无力，饮食不多，喜饮热汤，中下之阳气式微，不得不兼顾而治之也。至于得后与气，则快然如衰者，不外是病，亦不外是治乎！", "4680": "（案15）先痛而后肿者，气伤形也。究之所以伤形者，热胜则肿，火甚则痛，此等见症不足以泄其邪，又挟身中之白积，下走肠间，似属寻路而出矣。然脾气不升，反从下陷，四肢浮而阴囊肿，小水不利，满症作焉。实则泻之，未始不美，而不知所存之湿归入腹中，以昭「诸腹胀大，皆属于热」。幸得五苓已分其势，然犹未也。午后发热，鼻准色赤，虽曰脾经伏热，而咽之时痛、喉之干燥、舌之光红、苔之剥落，又有热伤阴气之象。泄热之中，兼以存阴，尚为可治。今乃望得形枯色滞，闻得气短言微，问得不纳、便溏，脉之切得者，右关弦数而大，至数模糊，左部寸短、关尺细弦，按之俱属无情，无一而非阴枯阳竭，土受木乘，势欲悠悠忽忽而脱。偏补阴阳皆有所碍，惟以培补元气一法，以冀一息之气，既可助阳，亦可生阴耳。", "4681": "生脉散粉丹皮左牡蛎陈香橼鲜藿斛白芍药抱茯神伏龙肝藕汁", "4682": "次诊：肿胀一症，大忌气喘、便溏，上下交征，以使气血阴阳立尽而脱，深可虑也。进前方，溏泄已止，气喘已平。肾本肺标，自有相生之兆，病属转机，是以色之滞者能开，形之枯者得润，本实之拨，固然因补而挽回，而枝叶之害，亦因清而兼化。化则口舌之干、咽喉之燥、咳嗽之作，无一不因而愈，所愈者过半矣，可称佳事。无如大肠之泻虽减，不意未食之前不知饥饿，既食以后又多饱胀，盖以「阳明中土，万物所归」，而阳明胃府，更有食积痰滞，交结于中，无怪短脉虽长，弦数未罢，且兼滑大，午后微热，鼻色微红，阳缩虽伸，囊肿亦消，四肢之浮肿不能尽退，且右臑肩背久偏为患者竟不能消，尚属病根未除之候。虚则补之，热则清之，积之一字，惟有磨荡而已。一方而三法备焉，未知其能弋获否？", "4683": "生脉散左牡蛎陈香橼伏龙肝鲜藿斛粉丹皮炙鸡金鲜藕汁白芍药福泽泻抱茯神雪羹饮子", "4684": "（案16）头为空谷，气本内清，耳为听官，声由外纳。兹乃是望得舌苔黄浊，闻得气急喘促，问得心神恍惚、胁背胀逆，诊得左脉细长、右关弦数，数则为热，弦则为湿，细为阴分之细，长为寿命之长，长命者元阳必旺，阴分自虚。偏以湿蒸热郁，窃踞阳明，阳明之脉盛于头面，头面诸经暗被湿热上熏，何怪乎昏昏不爽于头里、嘈嘈反起于耳中？而心神之所、肝胁之部、肺气之息，凡在中上二焦者，莫不深受其累焉！补阴以配其阳，化湿兼清其热，在所必需。", "4685": "（案19）肝者，将军之官，谋虑出焉；胆者，中正之官，决断出焉。二者失其所出之常，郁结不解，以致右胁下痛。盖肝脉布胁，胆附于肝，一脏一府，表里同病耳。然所病之痛又因下积而除，显系肝胆两经虽因本病，而实湿热久伤附和其间所致。后来温补燥烈，既伤营血，又滞浊痰，气分日窒，右降不及，无怪乎右胁之下窒碍不通，舌上生苔，大便燥结，吐痰反少，面黄色带滞，脉象弦涩，增出一番清浊混淆见症也。据述下积之后，精神稍爽，似欲以通为补之象，未知是否？", "4686": "次诊：脉之涩象稍和，弦则未改。积下之后，胁部稍能活动，想是痰血两邪尚有盘踞之意，而未解散也。", "4687": "（案20）据述五更泄泻，迭进温通而罔效，病亦奇矣。诊得左关脉弦，弦主乎湿，亦主乎肝，右关一部，内主乎脾。脾为土，肝为木，木乘土位，湿自不消，不消则脾为湿所浸淫，为重滞，为中宫痞，为少纳多痰。脾气被湿所累，既不散津上归于肺，口舌常干，而但运湿下入于肠，大便自泄。病在肝脾而不在肾明矣！拟治中，连理辈，佐以缩脾法，俾得土中泻木，以使两和。", "4688": "（案23）久痢未有不伤肾，肾虚则气不归元，呼多吸少，喘自作焉。纳气归元最为要著。然龙雷之火亦已随气上逆，口干、鼻燥、咽痛、脉冲，反见有余之象，引火归元更不可少。此亦不过因病治病，竭力以图之计，鞭长莫及，未免致叹于崇朝。", "4689": "（案25）知柏之性，本属迅扫荡扬，据云服之者多而且久，以致浊阴用事，真阳上越，烦躁眩晕，尺脉微细，小便不举。幸得大温大补之剂，尚可支持。为今之计，舍此温补，别无苟安之法。病发时少腹作痛，际此冬至之时，身中之一阳未必即生。急以来复法生阳于下，佐以真武汤坐镇北方，俾得阴阳不散，最为第一要著。", "4690": "（案26）脾脉络舌本，又主四末。脾经素有之痰，为寒所遏，上行舌本则不言，下注四末则痛痹，内阻心胞则形神呆钝，外阻阳气则四肢冷清。现在脉象小滑，寒痰正盛，必得温通经络，以使痰消寒化乃妥。", "4691": "（案27）鼻衄上流，白浊下注，脉象弦数。中宫之湿火分头而病也。", "4692": "（案28）寒热之下，下痢、胸痞，脉促、气短。此即太阳之邪不传阳明之经，即入阳明之府也。", "4693": "（案32）北方黑色，入通于肾，开窍于二阴，藏质于腰间。欲通大便精窍，先开腰间苦痛。脉来尺细关弦，肾家之虚也，不言而喻矣。", "4694": "（案34）肺气通于鼻，肺和则鼻能知臭香矣。兹乃反是，肺之不和也无疑，然肺脉固涩，而脾胃两脉何得亦然？加之白苔满布，想是中焦湿土先病，累及肺金。欲清肺金，必先崇土化湿，以绝病根，若在枝叶上求治无益也。", "4695": "（案37）病起下焦，后艮于背。夫背为阳，艮为山，设使背阳充足，何至重若艮山？惟督脉内空，不能统领诸阳，敷布于背，以致脾经之湿痰，下随肾家之夹背而上，上而不致于眼突，即艮其背，有似山之重焉。背重于上，囊肿于下，上下各病其病，而实一以贯之。古语云：「生病之处，即阳气不到之处」，此等症是也。下气通阳，最为入手要著。", "4696": "（案38）语言艰涩，口角流涎，肢麻气短，脉息沉弦。此系内风习习，感召外风，以成类中也。七日内小心骤变，先理风痰，随后大补。", "4697": "复诊：进奇方，火衰大半，药对病矣。然舌红无津，左脉弦数，水不足，火有余，不言可喻。泻南补北法主之。", "4698": "（案41）痢疾古称「滞下」，滞下者，暑邪积滞，下走肠间也。幸得大黄荡涤，未成重候。然迁延不已，已经一月有余，脉形弦细，肢体无力，溺色清，利色红门，中脘不舒，舌苔湿白，想是脾肾两经之阳气暗伤，所有余邪不能化净也。理中者理中焦，此症已及下焦，不独补脾，尤宜补肾，盖久痢未有不伤肾耳。", "4699": "（案42）脉象浮弦，弦则为痰，浮则为风，风邪因外而成，痰饮自内而起，内外合邪，咳嗽并作。安内攘外，似属一定章程，然所言弦脉固在，而浮之一字，见于左者甚微，见于右者独著，想是风之所感本轻，痰之所上实重，其在脉论云：「浮弦痰饮」，此之谓也。如是则治痰之品宜重于驱风不言而喻。", "4700": "（案44）脉见两弦，非痰即败。今所呕者，幸有痰涎，尚非败症，然久吐不已，究恐成败，断不敢以痰涎上泛小恙目之。惟治痰饮者，多用温法，而此间肝阴不足，其火本旺，舌红且绉，用药最难，况酒客中湿热又胜，刚柔相济之品难矣！拟连理汤合戊己法加减。", "4701": "次诊：进「少阴不足、阳明有余」法，身热渐缓，大便亦通，岂非「寒之不寒，责在无水」之一验乎？然病虽衰，而阴亏留热尚不能平，脉数、溺疼、苔黄、口燥、自汗、神疲，多所反复时也，岂容渺视？仍宜昨法守之。", "4702": "（案46）风寒湿三气杂至，合而为痹。本宜温药和之，无如痹日经久，三气之邪亦已郁热，正在「经热则疼，络热则痹」之时，又与风寒湿初起见症甚不相同，所以脉象弦数、口舌干腻、小溲带黄继之于后也。拟蠲痹法加减。", "4703": "（案49）陡然失血之下，气升则头痛、目红，气降则阳举、梦遗，身之肥瘦亦随气换形，加以筋惕肉𥆧，指甲色变，肢体或痿，脉息弦细。此系肝经伏热袭入肾经，水中火发，虽非真火，亦可畏也。法当清热，佐以潜阳，即仿乙癸同源例治之。", "4704": "（案51）病分气血，不病于血，即病于气，然亦有气血同病者，未必各有所分也。即如此病，胃脘当心而痛，起于受饿之余，得食则缓，此非气分病乎？然独气分为痛，既然得食则缓，宜乎即刻向安，而此痛能虽得食而缓，而午前则剧，黄昏尤甚，属在阳中之阴、阴中之阴之候，其为血病无疑，况但头汗出，便下色紫，脉形弦涩而数，更属血分之见症，但此血又非气虚不能摄血之血，乃酒热所瘀者。瘀者宜消，气虚宜补，消补兼施，庶几各得其所。", "4705": "（案53）阴枯于下，阳结于上，阳明素有之瘀血浊痰亦阻膈间，以致饮食之下，为噎为噫，经年不愈，其病更剧，所以胸中窒塞，尚吐白沫，脉象细涩，左关带弦，又兼食后作胀，大便坚结，势欲成臌。臌之用药最难，必须循循渐进，以冀弋获。然噎是神思间病，尤要内观静养，俾得怀抱放开，庶几有得。", "4706": "次诊：进前法，胸中之窒塞稍和，白沫上泛亦缓，显系上焦阳气暂得温通之品，结者能开。然虽暂用，尚未生生不息，加之阴血仍枯，是以饮食之下，不惟为噫为嗳，且兼胀逆不舒，大便坚结，脉象细涩，左关带弦，病情正剧时也。悦耳目、娱情志，当在药先也。", "4707": "次诊：足之厥冷、肤之寒象转热，脉息之小者，又能转大，且数且弦，寒郁之热颇有开泄之机。然其所开所泄，独在大筋小络，而肺之脏、胃之腑皆不能通，气分、阴分仍属无力以托其邪，无怪口干苔黑，舌强难言，牙关不开，鼻衄嚏出，胸闷气粗，呼吸有声，神情不振，且兼无慧，昏昏默默而睡，其热尚在险途。搜索枯肠，以尽医力。", "4708": "（案55）舌为心之苗，苗本于心，心为君火，其舌宜温。兹何反是？左寸脉沉而缓，舌色淡白，据云口唇早已先寒，然后及之于舌。因阳明胃脉环于唇口，唇口之先寒，阳明胃府久被寒痰所阻，累及于心，良以胃土之生，生于心火，子病及母，势所必然。", "4709": "次诊：进前方，音之不扬者已扬，肢之无力者有力，所称「肺热叶焦，则生痿躄」之状可以免矣！得之于心，应之于手，在医者本宜如此。第身热之象夜重日轻，首还如裹，背尚独疼，二便失调于下，口苦不和于上，恶心痞闷于中，三焦正病，暑气日多，所以脉形弦细，不见缓和，用药最难著手。然河间论暑，每以三焦为训，观其三焦之邪，孰轻孰重，则药即随之而进退。因思此间上下两焦见症轻于中焦，中焦痞闷恶心一减，则上下之见症亦可轻松。痞闷于内，恶心于外，最为现在所苦，急宜和解。当以泻心汤法，参入枇杷叶散方中，以作「结者开之」之计。如能取效，庶免风波。", "4710": "三诊：所言三焦见症：旨如裹，背之疼，口舌之不和，二便之不调，以及胃脘之恶心哕逆，无一而非随药向安，岂非美事？然美中不足，独有身上之热、胸中之痞依然不改。因思痞者，否也，否而不泰之谓也。无形之热，有形之湿，结而不开，变而为痿。苟非阳气得转，清浊混淆，痞无虚日，热无退时。久病如此，能不虑起风波乎？就脉数芤细而论，邪留一半，正已大虚。虚则补之，邪则化之，酌于二者之间，出一半夏泻心汤，专开其痞。痞若得开，热亦可退，否则徒退其热而亦不能退也。", "4711": "（案58）营行脉中，卫行脉外。脉为血脉，血脉盛则营卫流行，血脉衰则营卫不通，不通则痛。痛之为日已久，病必在络，不独气之为患可知。然则通其络、破其气，以使营卫渐和，不致有窒碍之痹，岂非快事？而不知五脏内亏，气血不充，阴阳之道路久已难宣，急急补之，还恐精神不旺，气滞血凝而痛，焉能受得攻方？夫营即卫，血即气，二者肺所主也，其用在右之胁部，痛则肺之治节不出，相傅无权。必得培土生金，补火生土，则真火上腾，肺气自旺，旺则燥金当令，金自不病矣。", "4712": "三诊：胁部不疼，背脊生胀，两腿作酸，无一而非三阴之略也。三阴之阴气内旺，阳气必衰，衰则浊阴用事，为胀为酸，以昭火土不能合德。气息自短，脉形软弱，嗽痰少寐，浊阴之气已加阳位，无怪乎中下两焦自病矣！若非温通阳气，窃恐白露横江，旧病复发。", "4713": "四诊：温通后痛已不作，诸恙大愈。药之力耶，魔之退耶，姑置勿论。脉为血脉，五至为平，六至为数，三至为迟。诊得脉来四至，既不为数，亦难为迟，即以平脉断之，似未妥贴，何也？盖以未至太息，不见五至者，亦属迟脉。迟则为寒，又属阳虚，若不以阳和之品，日进一日，犹恐真火难生，浊阴窃发。", "4714": "五诊：脉已五至，气血之平也可知。平则营卫调和，阴阳和协，以免「亢则为害」之机，且有「承则乃制」之力焉。然皆药力之偏见长也，而不知久而久之，药力又增气。气宜少，不宜壮，「壮火食气，少火生气」耳。", "4715": "十诊：营卫者，阴阳之道路也。营为阴，卫为阳，卫之为言护卫也，全在阳气之护卫。兹乃阳气久虚，护卫失职，凉风暴感，外从皮毛渐入于卫，以致形寒，脉紧，苔白，背腿仍旧胀酸，脘胁苦痛亦不肯罢。急须解表，以使凉风外达，不使郁久发热为要。", "4716": "十一诊：营行脉中，卫行脉外。既得桂枝汤，一调营卫，则脉之中外自得和谐，病有向安之处矣。然时病时安，还在正气之盛衰无定。所以新感之凉风，久积之阴寒，未能一时化尽，推其原究，属阳气内亏，不敷布使然耳。", "4717": "十四诊：逍遥之下，胁之疼暂止一夜，今又移入下胁，且及中脘，连及背胀。显系肝郁暂开，而其浊阴之气归并中宫，中宫之阳气前不能通，后不能运，所以脉反弦也。斩关直入，开通阳气，驱逐浊阴，非雄烈之品不足以有为。", "4718": "（案60）湿之见于下者，热湿也。热湿交蒸，邪从大便而泄，似属美事，而不知身中元气即于泄泻而伤，伤则所蒸之邪又从内踞，大腹胀满，足跗浮肿，小溲短赤，饮食减少，精神困倦，脉象芤数，口舌干燥，病势有加无已，每易喘脱。进以桂苓甘露饮。", "4719": "（案61）望得色萎肉削，闻得气怯言微，问得右乳肿痛，切得脉数弦急。就此四者而论，是脱营之症也，是脱将成之兆也。夫脱营之候载在《内经》，有其论，实未定其所。毓仁先生仅以耳之前后定其结肿，幸得张氏驳之，以为膺乳等部随处可生，所谓「始如痰核，久则渐大如石」是也。初起不肿不疼，似属平安无事，惟溃则血水一流，即不可问矣。然肿痛之象，其质已热，其色已红，颇有内溃之情。当此饮食减少，神情困倦，腰脊苦疼，口舌干燥，寤寐失常，少腹下坠，气火上炎，气血大亏，肝脾更病，窃恐不胜其任矣。本宜益气养营汤法，惟嫌腻滞不灵，姑以十味温胆汤加减。", "4720": "次诊：进前法，寤言已寐，眼亦有神，即结肿之处，红色减而热象缓，有病随药转之机，岂不美哉？但脉之急者虽除，而弦数之象依然。弦主肝，又主痰；数主肿，又主火。痰火交煽，肝郁内结，所以坚硬如石，有似乳岩、乳癖，而实不同者，还未能开，加之食少、腰疼、口燥、言微、腹坠，种种虚象，不一而足，正在「营既内伤，瘕复外形」之候。攻补两难，尚须养化以和之也。如能日渐向安，然后可以正方，庶乎近理。", "4721": "（案62）病经旬日，恶寒身热而起，本多头痛，现尚体疼，红疹难发，未能透达，少汗多烦，牙关紧闭，舌强难言，苔色灰白，唇干齿燥，胸闷脘痞，小便常转矢气，曾经厥逆，至今气塞，诊得脉象皆数，右寸关部弦而且滑。此系燥风外感，引动伏暑，已经化热，且兼痰食中结，互相为患也。结而不开，往往津液暗伤，变为实在痉厥矣。速以凉膈法，清其无形之邪火，导其有质之痰食，以使三焦通利为要。", "4722": "（案64）肺为姣脏，不耐邪侵，一伤于悲哀，二伤于发散，从此相傅无权，清肃失职。木寡于畏，怒则为哮，毛窍常开，寒则亦发。当发之时，肺经本贮之痰、脾经所生之痰无不上归于窍，呀呷有声，卧难著枕，如是数数矣。现在不发之时，脉静而细弦。元阳不足，非补不可，非温亦不可。", "4723": "（案65）中虚湿热，生痰生饮，为咳为嗽，甚至为喘。喘出于肺，关于肾。水失金之生养，如此日虚一日，而所患之湿热郁蒸于内，化热伤阴，溺黄、口干、味苦、苔白、脘痞、头昏、耳闭、小有寒热等症继之于后，更觉无力以消，所以右脉虽空，其形弦大且数，左部虽沉，反见弦急不静。从肺肾立法，本属堂堂正正，无如湿热反蒸何？", "4724": "（案66）咳嗽于前，风也；痛痹于后，湿也。风湿一病于外，伏暑内动于中，以致寒热如疟，八日不退。诊得右脉弦中带数，左部虽数，偏见濡象。数之一脉，诚属暑气所形；而弦且濡者，又属风少湿多。因思汗出已多，而暑之不能速化者，原被湿气所遏，难以因风而达。然则面色黄滞，舌苔满白，小溲短赤，从未发渴，岂非「热处湿中」之谓乎？若欲暑邪透达，非先化去其湿则不能也。然迟之又久，往往暑不外达，反从内走，增出一番险症，不可不防。盖以邪无中立，不出则进耳。", "4725": "次诊：面之滞色已开，湿邪亦暗化之机矣。是以右脉弦象稍和，左之濡象略弦。脉之转移，病之化动，自然相应，惟数象仍然，寒热稍轻，舌苔渐薄，小便觉长，明系暑风尚留、湿还内胜无他。暑必夹湿，湿去则暑亦自消，若非此理，古人之「消暑在消湿」何以言之？宗消暑法，参入苓术汤中，以使再减。然体质素虚，不得以一甘一寒之法佐之。", "4726": "三诊：湿从温燥而减，病情已缓。然湿为黏滞之邪，最难骤愈，无怪乎暑气还郁，小有寒热，似疟而作，舌苔虽薄，口尚不浊，面色虽开，其色未亮，加以小溲不利，肢体不松，脉弦带滞，所谓「脾为湿所浸淫而重滞」其在斯乎？转以缩脾饮，佐以五苓散。", "4727": "四诊：湿虽去大半，诸恙轻减，所嫌但热不寒，一日两度，有似瘅疟，而并不烦渴作呕，脉弦带数。无他，暑湿之邪尚留于脾，兼涉少阳，是以白苔之外，咽干带苦，每见于清晨也。古语云「舍助阳，别无驱湿之法」，又云「治湿不利小便，非其治也」。宗此两条，而出一清脾饮，仍佐五苓散，以使脾阳渐运，邪从小便而出，不再入于少阳，恰合现在病机。", "4728": "五诊：白苔化为黄色，湿邪退矣，暑犹在也。暑之所在，布于三焦，脉来濡数，今日知干，小便未利，胸次时痞，发热两度。正须透达之时，法宜提化。但苔有剥处，阴被暑伤，际此秋气平分，虽难滋补，亦不可不顾其阴。", "4729": "六诊：诊得脉数。数者，热也。内由暑邪所化，暑必夹湿，起于伤风，是以午后发热，夜半而衰；尚有如疟之状，中土之邪客涉少阳，近来之口苦咽干实出于此；至于疹块外发，风之余气亦属透达。所嫌大便溏热，腹中隐痛，肠间不无暑滞；舌苔剥落，阴分已亏。当此虚中留实之时，治宜扶正化邪，而出一小柴胡汤加减。", "4730": "七诊：大汗之下，身热竟退，暑邪解矣。解则余邪未尽，阴气必伤，自然午后微热，尚如疟状，舌苔之剥落、小便之浑浊、饮食之少进未尝不为此也。脉来濡中带数，正宜清养兼施。", "4731": "（案67）先生之病，素体湿热，又挟阴虚之症也。湿者何？地之生也；热者何？天之气也，湿热生焉。地天交泰，𬘡缊生焉，生生不见之机，妙合于其间，禀而受者，湿热元气混合一家，出自先天，牢不可破，较诸外感、内伤之湿热，属在后天者一扫而尽，岂可同日而语哉？设使薄滋味、远房帏，不过生疮动血，幼年所患之症而已；惟从事膏粱，更多嗜欲，外增湿热，内耗阴精，则脏腑营卫常有春夏之情，而无秋冬之气，无怪乎亥年之风火相煽，耳苦于鸣，岂非万物盛上而跃之一验乎？当斯时也，静以养之，则脐冷、齿痛以下见症之外，犹可相安于无事，何如火上添油，喜功生事，陡然头昏目赤，一派炎炎之势，甚至火极如水，阳不成其阳，势不成其势，肝经之火、督脉之阳亦从而犯上，失其本来之面目矣。近闻引火归原，以为甘温能除大热，嗟乎！未闻道也。甘温能除大热者，良以下极阴寒，真阳上越，引其火归其源，则坎离交媾，太极自安。若夫阴虚湿热蒸动而上者，投以清滋尚难相持，断不可以火伤火，明犯「一误不可再误」之戒。然清已有法，滋亦频投，饮食能增，身躯能胖，外有余矣。而色色不能久立、久坐，则病机中「阴阳不定，未有主也」之条。际此外盛中空、下虚上实，用药实难，常见东垣之清燥汤、丹溪之虎潜丸润燥合宜，刚柔相济，张氏每赞此两方始克有赖，何乐而不即用之耶？无如药力之所以载行者，胃气也。胃属阳明，阳明中土，万物所归。湿热窃踞，亦久已熏蒸，传为吐血、鼻塞、噫气、二便失调，正见「九窍不和，都属胃病」。欲安内藏，必先清其外府，又为第一要著。至于秋末冬初病甚者，十月坤卦纯阴，天已静矣，而湿热反为之动；肾欲藏矣，而湿热仍为之露，致邪失政，能不令其更进一层乎？附方谨覆。", "4732": "（案68）承示病原，阳分比阴分更亏，显有明征。阴亏而用十全养营等法，责重乎阴，寓以阳药。本属和平之剂，良以秋分在即，燥气加临，不敢责重乎阳，以燥就燥，反增燥病焉耳。然于膏方下云「日后可加附桂，斟酌用之」一语，早已言之，非不见到也。盖天地之气，半月一更；人身之气，亦半月一更。八月而至九月，气已两更，病势不解，饮食反减，明明阴得膏滋而无病，阳得膏滋而更衰。一月之间，阴阳偏胜；一膏之内，功过相抵。可叹补偏救弊，因时制宜，应接不暇也。所言廿七、廿九两日，霜降始寒，寒气外侵，痰饮内动，动见青黄绿水，尚属阳明胃府，至于黑色，已自胃底而来，肾虚水泛、脾虚积饮可见一斑。然神气困顿，面色青浮，脉气双弦，以昭阳气不充、痰饮内聚宜矣。而反忽然牙齿浮疼，加以口舌酸甘，呃忒于胃，冲逆于胁，变出一番火气者，肝火也，肝气也。气火之横逆，不外肾虚无以涵木，木旺顺乘脾土，此等「气不足即是寒」之根蒂，反见「气有余便是火」之情状，所谓本寒标热是也。夫惟本寒标热，岂非阳气较之阴气更进一层耶？此时论治，离照当空，始可阴霾四散，宗「风虚则炽，痰寒则壅」之训，而出一星附散法，以助脾阳，俾虚风寒痰不相互结，非独分解病情，而且土旺用事，更合机宜。如一立冬，又不可以纯阳无阴之品施于久病阴血本亏之体。冬月宜藏之令，即以此方分两三分之，一日进一服，参入前定膏滋方。口中只须五钱，清晨服下，傍晚再服水泛《金匮》肾气丸钱半，淡盐汤下，以占冬至阳生，弗药有喜。至于黑锡丹、控涎丹，本来同式，因病处方，随机应变，相时而动可也。须候尊处高明权之。", "4733": "（案70）松江朱逢辰次诊：左升太过，右降不及，何经之病？左属肝，右属肺，肺肝同病，自然升降失常。然肺为五脏华盖，肝脉布于两胁，此左升仅属于肝，右降仅属于肺，何也？概肝体在旁，肺体在上，只就位置而言；若论其作用，《内经》又曰「肝居人左，肺居人右」，右之不降，肺正失其清肃之用也；左之过升，肝反多所横逆之用也。横逆之邪加于清肃之所，木寡于畏，反侮于金，无怪乎身半以左之气旋之于右，既不能透彻于上，亦不能归缩于下，有如邪正相争，盘旋胁部，直至得后与气，则快然如衰者，木究不能上克于金，而仍下泄于土也。夫土曰稼穑，作甘者也；木曰曲直，作酸者也。口甘带酸，痰吐亦然，何莫非土受木乘之过，土亦太剧矣哉！谁能柔之？惟有左金一方，以为克木之制，则木正其体，金正其用，何患升降之不得其常耶？", "4734": "覆朱逢辰书：接读手示，荷蒙锦念，谢谢！所论气火益炽等症，而古人云「气有余便是火」，气从左边起者，肝火也，左金丸主之，当归龙荟丸亦主之。今既以左金一丸，如水投石，自宜以当归龙荟丸继之于后，未尝不可为法。惟我先生有「为痈为血，不可预防」一语，出自高明，定有灼见。弟始而骇然，继且茫然，几不知笔从何处著矣！吾先生如饥如渴，以望一方，惟速为贵。而弟刻无暇晷，夜以继日，有者求之，无者求之，必得一左之右之、无不宜之之法，然后可以覆书，非敢缓也，盖有待也。端日下问者，少徒辈聚在一室讲论，百问皆生于气，遂有「九气不同」之说。气本一也，因所触而为九。夫怒与思，为九气中之二焉。「思则气结」，《内经》自为注脚云：「思则心有所存，神有所归，正气留而不行，故气结。」先生有之。至于怒则气上，甚则呕血；怒则气逆筋缓，发于外为痈疽，古人亦载于「气门」，以昭邪郁必变，久病入络，非无意也。先生亦有焉。弟即从此领悟曰：怒有形于外者，亦有不形于外者。形于外，暴怒伤阴；不形于外，郁怒伤肝。惟其郁也，木则不克畅茂条达，反来横逆，则气郁于中者，势必火炎于上，金受火刑，有升无降，痰血热辣。一病于肺，痞满闷塞；再病于脾，脾肺同病，则胃家之痰食无力以消。胆经之木火从而和之，将来血溢于上，痈肿于经络，增出一番新风，诚不能不未雨绸缪也。然为痈为血之枝叶，仍不外乎气郁为火之根蒂。治病必求其本，因思「气从左边起者」条，内有「久病气结，诸药不效者，先服沉香化气丸以开其结」之文，不独将来之病变可以预防，即现在之气火升腾亦为合剂，而况右脉弦强，即「土郁夺之」之法耶？惟沉香化气丸重剂也，权宜用之而已。元虚久病之体，于病不能不用，而亦不可多用。清晨宜服八分，晚服逍遥、六君辈，调之补之，以为实必顾虚之计。未知是否，请正！", "4735": "（案1）右半身不遂，脉来虚软。元气不足也。法当温补。", "4736": "（案3）症属偏枯，内热，脉数。", "4737": "（案6）右肢偏废，六脉模糊。阳虚湿痰内阻。", "4738": "（案7）肢麻言塞，脉来无力。阳虚痰滞脉络。防中。", "4739": "（案2）膈胀呕恶，饮食顿减。肝风犯胃也。诊脉象弦大，暂拟苦泄一法。", "4740": "（案3）头晕心悸，六脉不静。虚风内动也。", "4741": "（案5）头晕多痰，诊脉滑大。肝风内煽。理宜柔肝熄风。", "4742": "（案1）失血后，气喘咳呛，脉来细数。水弱火旺，延久成怯。", "4743": "（案4）积劳内伤，咳血，延至气喘，脉来软弱。阴损及阳。防其虚脱。", "4744": "（案5）咳血便溏，六脉无力。怯症之渐。当用培土生金。", "4745": "（案6）失血后，咳呛便溏，六脉少力。不但阴络受伤，而且阳分大亏。宜扶阳而生阴。", "4746": "（案7）遗精咳血，脉络空虚，腰背作痛，神色㿠白。怯症之根。当以甘温补养。", "4747": "（案10）便溏下血，脾肾两虚，兼之气逆自汗，六脉无力。颇有衰脱之险，甚为棘手。", "4748": "（案2）风温于肺化热，气急咳呛，痰多色黄，脉来右寸浮大。转用泻白法。", "4749": "（案4）血溢后，咳呛不止，咽痛失音，六脉弦数。肺络伤而津不上承，殊非小恙。", "4750": "（案5）七情郁结，燥火内燃，咳逆咽干，左脉弦大。治以仲景法。", "4751": "（案6）久咳不已，畏风，脉数。腠理疏，津液亏。固表育阴。", "4752": "（案7）咳呛膈痛，脉来弦数。肝热射肺。防络伤咯血。", "4753": "（案10）脾气虚而津不上承。久咳不已，色脉少神。补土生金。", "4754": "（案11）久咳形衰，脉来无力。肺肾并亏。仿金水六君法。", "4755": "（案12）痰嗽不爽，六脉弦大。肝火刑金，恐络伤动血。", "4756": "（案14）远年久咳，色脉少神。肝肾虚，水泛为痰。急宜培补。", "4757": "（案17）久嗽咽痛，脉来细数。肝肾阴亏。甚为棘手。", "4758": "（案19）久嗽脉弱。先后二天均虚。若过投寒凉，必致胃损减食。", "4759": "（案21）久咳不已，咽干作痛。乃肝风炽，肺阴伤也。诊六脉弦数，惟恐络伤动血。仿嘉言清燥法。", "4760": "（案22）久嗽失音，舌红脉弦。邪郁肺金，外寒内热所致。仿仲景法。", "4761": "（案1）咳痰带血，六脉洪大。温邪伤肺，不宜早进补。", "4762": "（案2）咳频震络，络伤，痰中带血，脉来弦大。只宜薄味，以清上焦。", "4763": "（案3）咳逆见红，脉象弦大。肺胃之火迫血妄行。治以甘寒。", "4764": "（案4）畜血妄行，胸膈作痛，脉弦大。阳络伤也。此必杂络之瘀未净，不宜早投滋腻。暂用通络一法。", "4765": "（案5）咳逆伤络，失血，胸膈作痛。病久脉虚，刻难取效。", "4766": "（案6）热逼阳络，血溢颇多，脉来数大。适意静养。", "4767": "（案7）上焦郁热，咳血多痰，六脉弦紧。治以清润。", "4768": "（案8）久嗽见红，脉来细数。肺络伤也。殊非轻恙。", "4769": "（案10）阴不恋阳，咳血脉数。乃劳怯之见端，切勿轻视。", "4770": "（案11）内伤失血，血虚则气喘、脉数。阴不恋阳也。以致下午潮热，饮食日减。乃下损及中，最难向愈。", "4771": "（案18）大血失后，阴损及阳，以致色脉少神。近乎怯候。宜甘温纳补。", "4772": "（案23）骤然咳血，膈闷顿痛，举动气促，脉来洪数。此温邪震络也。恐有留瘀未净，不必急于止涩。", "4773": "（案2）心悸遗精，脉虚无力。由阴不恋阳所致。惟清心固肾，俾得水火交合，病当渐减。", "4774": "（案1）便浊脉数，湿热下注也。法当分利。", "4775": "（案3）久浊元虚，脉来无力。法当建中，佐以升清。", "4776": "（案5）尿血作痛，小腹坚，大便秘，脉来紧大。下焦郁热所致。恐有瘀滞。", "4777": "（案6）血淋茎痛，脉来弦大。湿热下注。法当分利。", "4778": "（案1）寒湿内阻气分，统体浮，脉不应指。法当温解分清。", "4779": "（案5）中虚湿困，统体浮肿，六脉模糊。法当分利。", "4780": "（案7）足胀浮肿，六脉沉微。真火衰而湿浊用事。宜乎通阳分利。", "4781": "（案9）腹胀脉软，阳微挟湿。法当分利。", "4782": "（案12）腹膨泄泻，六脉模糊。阳虚湿困，恐其中端。", "4783": "（案15）腹胀气喘，脉不应指。脾肾阳衰。仿《金匮》肾气法。", "4784": "（案17）失血过多，阴伤及阳，腹中膨胀，脉来细数。宗补火生土法，以图寸效。", "4785": "（案20）腹鸣作胀，脉来虚软。脾肾阳衰。法当温补。", "4786": "（案2）脾肾阳衰，纳谷不运，脉来沉细。近乎膈候。", "4787": "（案3）朝食暮吐，六脉沉弱。中土阳衰，腐谷无权也。法当补土通阳。", "4788": "（案4）纳食哽塞，大便艰难，脉来软弱无力。积劳内伤，阳结于上，阴衰于下，是为关格之渐。姑拟温通一法，以图幸功。", "4789": "（案5）食阻便艰，脉来弦数。操劳阳亢，肺津胃液日渐消耗，是为关格之见端。须身心安逸，病可渐却，慎勿徒恃药功。", "4790": "（案1）中虚挟湿，结痞渐大，脉细模糊。久防满腹。", "4791": "（案3）左胁下结痞作痛，饮食减少，形衰脉弱。此属木邪侮土，症势不轻。", "4792": "（案4）肋痞胀满，右脉弦滑。恐有停饮。燥土分消。", "4793": "（案5）宿痞为患，延至腹满，食减便溏，脉软无力。脾土阳衰也，殊非轻恙。", "4794": "（案2）膈痛吐沫，脉象模糊。中虚积饮。燥土通阳。", "4795": "（案3）寒湿僭踞，呕逆自汗，六脉不扬。殊非轻恙。拟平胃理中法。", "4796": "（案4）纳食呕吐，脉来细软。土衰木乘。宗仲景法。", "4797": "（案1）胸次作痛，六脉模糊。湿、热、痰阻气，清阳不运也。仿平胃法。", "4798": "（案2）胸闷作痛，短气脉沉。清阳失展，气机不利也。宗《金匮》法。", "4799": "（案3）膈痛频发，色脉少神。络不通也。防失血。", "4800": "（案3）喘逆自汗，脉数无力。阴涸阳浮，气散失纳。法当收摄固元。", "4801": "（案5）脉沉气喘，背冷腰痛。肺肾虚寒。法当温补。", "4802": "（案6）举动喘促，脉来细。元海根微，气逆上泛。理当补纳。", "4803": "（案7）喘急多痰，右脉弦滑。中气虚而停饮上逆。法当燥土祛邪。", "4804": "（案9）气喘咳逆，脉来少力。可见此火无根。必须补纳。", "4805": "（案10）金水两虚，易感痰喘，脉来细软。理当进补。", "4806": "（案2）肝火挟痰，肢麻头晕，左脉弦数。惟恐仆跌。", "4807": "（案5）风温伤肺，肺气不通。痰唾如胶，脉细弦滑。议与微辛微苦之属。", "4808": "（案6）头晕不寐，六脉紧数。乃肝火挟痰。防其仆中。", "4809": "（案3）痰饮挟气，木火上逆。膈胀脉弦。腻补不合。", "4810": "（案4）痰饮上泛，纳食艰运，中下两焦阳微也。脉象沉弱不扬。治以通阳涤饮。", "4811": "（案5）久嗽中虚，痰饮内聚，形衰脉弱。症势非轻。", "4812": "（案3）久疟不已，咳逆盗汗，色脉少神。殊非轻恙。", "4813": "（案5）暑湿伤气，寒热腹痛且胀，脉不条达。太阴疟也。", "4814": "（案2）久泻不止，色脉少神。脾肾阳虚，殊非轻恙。", "4815": "（案7）久痢延至腹胀，六脉细软。阴阳两伤也。必须温补。", "4816": "（案8）久痢脉微，命门阳衰也。若不急进温补，惟恐延成肿胀。", "4817": "（案11）疟后下痢，纳食艰运，六脉沉弱无力。此属命火衰微，必须温补。", "4818": "（案12）湿热内侵，痛泻脉数。", "4819": "（案1）阴虚内热，肠红脉数。", "4820": "（案1）两足酸软，六脉浮数无力。证属骨痿，由阴虚内热所致。宗虎潜法。", "4821": "（案2）此筋痿候也，由厥阴郁热所致。诊左脉弦数。宜清营热以舒筋。", "4822": "（案5）四肢不用，脉沉少力。脾肾虚寒。急宜温补。", "4823": "（案6）足膝痿软，六脉无力。肝肾虚而挟湿也。须标本两顾。", "4824": "（案3）阳虚挟湿，两膝肿痛，六脉弦数。症势不轻。", "4825": "（案5）下体痹痛，脉来细软。水中无火。法当温补。", "4826": "（案7）四肢酸痛，间发寒热。由风入脉络使然。先宜解散。", "4827": "（案1）阳不交阴，寤不成寐，饮食日减，脉来弦数。暂用半夏泻心法。", "4828": "（案3）心烦头晕，寤不成寐。五火内炽也。左脉弦大，治以苦泄。", "4829": "（案1）厥频发，心悸脉数。由肝郁气乱使然。先清后补。", "4830": "（案2）肝胆郁热，膈胀神昏，六脉弦紧。惟恐痫厥。", "4831": "半夏干姜延胡蒌皮陈皮郁金白芍茯苓也。当此形衰脉弱，必须温补。", "4832": "（案5）胃痛食减，脉来细软。中阳失运也。治以温通。", "4833": "（案2）腹胀脉微，阳气积衰也。法当温理。", "4834": "（案2）腰痛脉虚，肾阳不足也。法当温补。", "4835": "（案1）头晕脉滑，内风挟痰也。从肝胃调治。", "4836": "（案3）头晕耳鸣，六脉弦滑。乃肝火挟痰为患。清先补后。", "4837": "（案6）头晕自汗，六脉细软。此阳不恋阴也。法宜培补。", "4838": "（案7）烦劳头晕，六脉细软。此属水不涵木，厥阳化风。当从肝肾同治。", "4839": "（案3）头晕鼻衄，脉来细数。水亏火动也。治以育阴潜阳。", "4840": "（案5）鼻衄大发，六脉弦数。由阴虚阳亢所致。", "4841": "（案6）胆热移脑，鼻流秽涕，脉象弦数。治以辛散。", "4842": "（案1）咽痛失音，咳痰不爽，左脉弦紧。木火刑金也。仿仲景法。", "4843": "（案2）大便闭结，脉来沉迟。下焦阳气失运。治以温润。", "4844": "（案3）经下颇多，心烦口渴，阴亏阳亢也。六脉不静，治以滋补。", "4845": "（案5）肝强脾弱，胸痛作胀，癸水不行，脉来细软。理宜调气和血。", "4846": "（案7）阴虚内热，经漏淋漓。仿仲景复脉法。", "4847": "（案8）产后结瘕，少腹胀痛。此属肝胃络虚，非有形所阻。况自汗屡泄，六脉无力，岂可投以攻剂？理宜温通为要。", "4848": "（案10）带下腹痛，脉来细软。阴虚及阳。法当温补。", "4849": "（案11）经漏后，脉络空虚，以致心悸头晕，筋骨酸软，及足跗浮肿。非轻候也。必须进补。", "4850": "（案16）中虚肝郁，腹胀食减，色脉神少。仿逍遥法。", "4851": "（案2）恶寒发热，头痛身疼，脘闷无汗，脉来弦紧。乃卫阳疏而风寒外袭。例用辛温解散。", "4852": "（案4）邪伤阳经，形寒身热，头痛脘闷，舌白脉紧。先宜汗散。", "4853": "（案5）春温发热，头胀脘闷，舌布白苔，脉来弦劲。邪势郁于气分，不得从汗化达。拟解肌法。", "4854": "次诊：得汗后热象不减，烦渴少寐，脉数舌干。伏邪未化，津液先伤。法当清解为要。", "4855": "（案6）湿热伤阴，舌红脉数。仿玉女煎法。", "4856": "（案8）温热内陷，四肢厥冷，热深厥亦深也。顷诊六脉沉数，谵语神昏，大便三候不解。乃病久元虚，邪归胃腑，甚为棘手重候。勉拟陶氏黄龙法，以图幸效。", "4857": "（案9）冬温乘阴虚而发，身热不得汗解，脘闷咳逆，舌白脉弦。郁气分尚未施张。法当治以辛散。", "4858": "（案10）暑湿伤其气分，脘闷腹痛，上吐下泻，四肢厥冷，舌腻脉数。此霍乱候也。例用正气法。", "4859": "（案12）暑风伤肺，发热汗少，头胀咳呛，舌布白苔，脉左弦数。此属闭暑之候，变幻莫测。姑拟辛解。", "4860": "（案14）左脉弦数，朝凉暮热，汗解渴饮。治从少阳。", "4861": "精气神为人身之至宝，医能保人所宝，则医书真宝书也。轩岐而下，惟仲景称圣，为制方之祖。嗣后英贤辈出，各抒心得，立法以启后人，方书充栋。后之用法者，能得古人法中之意，而不泥于法，则因病定方，不执方以治病可也。所难者在认症耳！昔嘉言喻氏谓，医不难于用药，而难于认症，故先议病后议药。丹溪朱氏著《脉因证治》一书，亦以认症为先，施治为后。若但执某方治某病，而至于何脉何因何症，辨之不真，焉能用之无误？寒热虚实，疑似甚多，见病治病，十无一效，曷足怪哉？吴中精于医者，代不乏人，自叶香岩先生，治称神术，百余年来，无有继其传者。惜其生平济人，事殷无暇，著述如《临证指南》一书，为门人所采辑，久已风行海内。今复见《医案存真》三卷，系其哲嗣讷人先生汇集家藏方案成编。观其施治之妙，实由辨症之的。其不惑于症之疑似，治不违于法，而又不泥于法者，苟非根柢《内经》，博涉诸家，其乌能洞彻阴阳标本，随症立方，神明于规矩若是哉？至马、祁、王三家医案，各抒精义，制方附刊于后，亦足资后人采择。此书诚可宝也！书既成，先生济世之业，与其哲嗣济世之心并传不朽，而流泽孔长矣，是为序。", "4862": "脉涩小数，质弱，平昔喜饮。酒性先入肝胆，故易生嗔怒，且涂次侍亲，烦劳郁热，自情怀而升。病属郁劳，惟怡悦为上，用药不易奏功。", "4863": "脉弦，舌白，吐涎，食入膈上即涌出。自述由动怒得之，春病至霜降不愈，心中反痛。以肝病犯胃治法。", "4864": "孕育已十一胎，未到七七，天癸已绝，八脉不司约束，脊腰酸痛，足跗骨中麻痹，间有带淋畏热。此属阴虚。虎潜法治之。", "4865": "用白虎法，渴烦少减，略饥，必形神软倦，津液既遭热迫，阳明脉络自怯。当以清燥法，清气热以涵液。", "4866": "痘后四肢疡毒，延绵日久，聚集环跳膝跗，以至不能行走，乃沉疴难愈之疾。据述筋粗强硬，不司舒展。《内经·病能篇》筋纵筋弛，分寒湿、湿热之异。但痘浆未化之毒，混处血脉络间两年之久，攻之决不应病。夫四肢血少气多，初患当取阳明，今已流入阴分，遇风冷辄痛，温通逐邪，理亦可通。然男子未通精之岁，必以生阴为要务。调理方法，宗钱仲阳麋茸六味，壮阴通阳，可以常进。", "4867": "二十日来，以甘温、益气、养阴，治脾营胃卫后天，渐得知饥纳食。思疟、痢致伤下焦，奇经八脉皆损，是以倏起寒热，背部畏冷，遇风必嗽痰。阳维脉无以维持护卫，卫疏则汗泄矣。从虚损门治。", "4868": "因嗔怒心胸痞胀三年，左胁下坚凝有形，偶触劳忿，则寒热无汗。此属郁痹气血，延成肥气。治当宣通营卫，流行脉络，佐入攻坚，俾寒热得止再议。", "4869": "疟伤真阴，七八年来每交春季，即脊背肩胛胀痛，入夏更甚，冬寒乃瘥。凡春夏之时，天地大气发泄，至秋冬方始敛藏。脏真既少，升泄病来。督脉行身之背，自阴而及于阳，但内伤不复，未易见功，惟养静断欲，用药可希渐效。", "4870": "三阴疟，是阴分伏邪。汗之、清之不解，但与腻滞补药，邪无出路，遂致吐衄，寒自背起，督脉应乎太阳。", "4871": "食下脘中噎阻，背胁气逆而痛，脉右寸独大。据述由嗔怒致病，当与清金制木，形瘦津少，勿用破气燥血。", "4872": "凡忧愁思虑之内伤不足，必先上损心肺。心主营，肺主卫，二气既亏，不耐烦劳，易于受邪。惟养正则邪自除，无麻、桂大劫散之理，故内伤必取法乎东垣。今血止脉软，形倦不食，仍呛咳不已，痰若黏涎，皆土败金枯之象，急与甘缓补法。", "4873": "脉弦缓，面目肌肤皆黄，舌白滑腻，胸脘膈间胀闭，病名湿温。由濒海潮湿，气入口鼻至募原，分布三焦，此为外因。仍食水谷腥物，与外入秽浊之邪，两相交混，湿甚热郁，三焦隧道气血不通，遂变黄色。发汗不愈者，湿家本有汗也。清热消导不愈者，热从湿中而起，湿不去则热不除也。夫湿邪无形质，攻滞乃有形治法，其不效宜矣。昔河间治湿热，必取乎苦辛气寒。盖苦降以逐湿，辛香以祛秽，寒取乎气，借气行不闭寒于内也。当世医者，混以伤寒表里为治，殊不知秽湿气入口鼻，游走三焦，不与伤寒同治。", "4874": "下利皆令伤阴，值冲年，情念正萌，遂患梦遗，劳烦饥馁更甚，以精血有形，必从水谷入胃，资其生长也。诊脉数，面亮，茎举则精出，溺后亦淋沥，是阴虚精窍不固，因阳气下坠所致，议固下阴以和阳。", "4875": "疟后耳窍流脓，是窍闭失聪，留邪与气血混为扭结，七八年之久。清散不能速效，当忌荤酒浊味，卧时服茶调散一钱，患耳中以甘遂削尖，插入，口内衔甘草半寸许。两年前晨泄，食入呕吐，此非有年体质之脾肾虚泻，可以二神、四神治也。盖幼冲阳虚，百中仅一耳。今泄泻仍然寒热，咳嗽失血，天癸不来，脉得弦数，形色消夺，全是冲年阴不生长，劳怯大著。无见病治病之理，保其胃口，以冀经通，务以情怀开爽为要，勿恃医药却病。", "4876": "脉细，右濡左数。少年形瘦肌槁，遗泄，是知识太早，致精血难充，脐左动气，食减易饥，阴伤于下，渐延中宫。沉阴恐妨胃，刚补虑劫阴。男子精伤补阴，参入柔剂温药，取坎中寓阳之意。", "4877": "脉数，左促右小，咳嗽已一年，喉痒火升食减，经水仍来，从未生育。凡女人以肝为先天，肝阴不充，相火上燔莫制，嗽久痰带红丝，皆劳怯势成，日见消烁，清肺凉药不效，根本先亏也。急养肝肾之阴，不失延久之计。", "4878": "遗泄有梦属心，无梦属肾。据述气火下溜，即如溺出之状，茎管中痛，热气上冲咽喉，巅顶掀胀，语言皆怯。此任脉不摄，冲脉气逆。", "4879": "形劳悒郁之伤，脉得左部弦劲，肝血胆汁已少，目翳红赤。治以凉肝滋液。", "4880": "病始足胫，乃自下焦肝肾起病，其形不肿，则非六气湿邪，当从内损门痿躄推求。萸、地滋滞，久服胃伤，食减呕逆，皆因浊味滞气而然。经年不复，损者愈损，脏真不能充沛，奇经八脉不司其用。经云：冲脉为病，男子内结七疝，女子带下瘕聚。夫冲脉即血海，男子藏精，女子系胞。今精沥内结有形，是精空气结，亦犹女子之瘕聚也。凡七疝治法，后人每宗张子和，但彼悉用辛热，与今之精空气结迥殊。久病形消肉脱，议以精血有情，涵养生气。", "4881": "堕胎十八次，冲任奇脉血液无存。厥气入络，为胀为痛，或时冲逆犯膈，八脉皆不为用，淹淹渐成损怯，徒欲止痛宽胀，乃不明之论，俗医皆然。", "4882": "产后腹坚有形，气聚不通，渐成胀满，乃冲脉为病。其大便秘阻，血药润滑不应，柔腻气愈凝滞。考徐之才云：肾恶燥，以辛润之。", "4883": "精腐瘀血，阻闭溺窍为痛。似淋非淋，久则阳维脉伤，寒热起，五液枯耗为便难，乃虚症也。", "4884": "肢冷涌涎，脐上痛坠，泄泻而脉缓，此为脾厥。以辛香醒中，兼解少阳之郁。", "4885": "疟发三日，三月不止。邪留在阴，热解无汗，气冲胸闷，痰涎甚多。问寒起腰髀及背部，议从督脉升阳。", "4886": "血伤骤加惊恐，气郁热升风旋，清神受蒙为厥。凡厥皆隶厥阴，今左股麻痹，忽爽忽迷，皆肝胆中相火、内风未得宁静。病延数日，左脉小濡。热胜津液暗伤，不宜纯与攻涤苦寒，经旨以肝为刚脏，与胃腑对待。柔缓濡润，阳和液复，可免痫症。", "4887": "脉左细数而劲，右数大而虚，此肾精肝血内亏，水不涵木，阳夹内风，暴起莫制，指臂拘挛，口目㖞斜在左。盖肝风阳气从左而升，冲气撞心，消渴晕厥，仲景列于「厥阴篇」中。凡肝属阴木，必犯胃之阳土，饮食热气入胃，引动肝阳，即病发矣。此恙已六七年，阴损已极，必屏绝俗扰，怡悦情怀，然后滋养，堪固其阴，必有小效，无骤期速功。", "4888": "形充脉弦，饮食如常。述左胁久胀，上年肿突肌溃，收结已来，胁中痛胀仍发，入夜更甚，仅仅仰卧，不可转侧，此支脉结饮，阻其周行气机，病根非外非内，宜通其脉络为是。", "4889": "凡经脉直行，络脉横行，经气注络，络气还经，是其常度。今络脉窒塞，闪烁为痛，但在云门上焦，犹是清气流行之所，务取轻扬宣气，亦可无碍，湿痰便血。《灵枢》所谓：上焦如雾。", "4890": "中年饱食，虚里穴痛胀，引之吐出，痛胀势减，必起寒热，旬日乃已。夫脾主营，胃主卫。因吐动中，营卫造偏周行，脉中脉外参差，遂致寒热。且纳物主胃，运化在脾，皆因阳健失司，法当暖中，用火生土意，再以脉沉弦细参论，都系阴象，有年反胃格胀，清阳渐弱，浊阴僭窃为多。症脉属虚，温补宜佐宣通，守中非法。", "4891": "久痢肛坠，诊脉左坚沉，温剂不受，阴伤不司收纳，前用桃花汤少减，当与甘酸柔缓。", "4892": "肩背肢末，皆阳气游行之所，牵制不和是络脉中病。首用东垣舒经，接用参、耆、术、附，两法不应，必客气袭入脉中。灸刺无功，议用酒醴通和血脉。", "4893": "伏邪留于少阴、厥阴之间，为三日疟，百日不愈，邪伤真阴，梦遗盗汗，津液日枯，肠燥便难。养阴虽似有理，但深沉疟邪，何以追拔扫除？议以早服仲景鳖甲煎丸三十粒，开水送，午后服养阴通阳药，用复脉汤加减。", "4894": "脉沉而迟，向有寒疝瘕泄，继而肠血不已，渐渐跗臁麻木无力，此因膏粱酒醴，酿湿内著。中年肾阳日衰，肝风肆横，阳明胃络空乏，无以束筋，流利机关，日加委顿，乃阳虚也。仿古劫胃水法。", "4895": "脉虚涩，咽中时痹，不妨食物，大便干燥，此肺中气不下降，不主运行。消渴心热，皆气郁为热，非实火也。", "4896": "疟发六七十候，寒热邪聚，必交会于中宫。脾胃阳气消乏，致痞胀不能纳食运化，三年不愈，正气未复。诊脉沉微，阳伤必浊阴盘踞，但以泄气宽胀，中州愈困愈剧。必温通，浊走阳回，是久病治法。", "4897": "脉大弦缓，目黄，纳食后中脘滞痛，腹鸣泄泻。夏病至深冬未安，缘濒海潮湿久蒸，兼以怀抱少畅，脾胃之阳日困，所受水谷之气少运，清浊升降失度，外因六气未去，留连脾胃内伤。法当辛香调气醒中，阳气流行，湿郁可去，腥膻重味宜忌。", "4898": "肾精下损乏阴，气上乘，浮阳上灼，咽喉痛痹，有喉宣发现，咳嗽喘促，是下焦元海不司收纳，冲脉之气上冲所致。故日进润剂，望其咳减，为庸医之良法，实酿病之祸阶，现在胃弱便溏，则非治嗽可疗矣。劳怯不复，当以固真纳气，培扶胃口，希冀加谷则吉。", "4899": "向来经水不调，冲任脉病，医未明奇经脉络，久治无功。后患阴疟延虚，经来色淡淋漓，少腹攻触㽲痛，晨必瘕泄。当通阳摄阴，非破泄真气，偏寒偏热之治。", "4900": "便后纯血，食减力疲，脉左坚，是中年阴亏。", "4901": "据述泻血五日，血止即患咳呛，左胁下有形如梗，身动行走，必眩晕欲仆。春夏减食，秋冬稍加。交冬，人迎脉络结瘿，诊脉虚，左关尺数。此肝肾精血因惊恐忧劳所伤，阳失阴恋，络中空隙，阳化内风，鼓动不息，日就消烁不肯复，为郁劳之症。四旬以外，生气已浅，非治病可却。春夏，身中真气不耐发泄可知，屏绝家务，开怀颐养，望其病缓。", "4902": "阳明之脉，主束筋骨而利机关。今行走皆艰，纳谷甚少，腹中气攻，头痛，自悲忧五年，日加衰惫。如《灵枢经》论痿云：意伤忧悲愁则肢废也。", "4903": "蓐劳下损，损及八脉，医投清内热滋阴，致胃伤食减，寒热，下焦冲气上逆，而咳嗽药惟治肺，与下虚内损，并无干涉。带淋骨热，髓竭液枯，蓐损较平常损怯更难。寒暑更迁不复，草木焉能奏功？勉与血肉有情，望其加谷，望其悠久。", "4904": "怒伤肝，恐伤肾，二志交并，真脏内损。烦劳则阳气扰动，值春木之令，络血随气上溢，失血过多，阴气下空，阳无所附，上触清府，致木反乘金，咳呛气促，肺俞恶寒，脉弦数，乃下损之疾。", "4905": "舌喑强缩，干涸无津，邪气已入膻中，神识昏蒙，积劳心血及虚，致热竟入矣。诊脉虚小无力。俱补则热闭，今晚以至宝丹三分，凉开水调化，匀五六次铫服，明日再议。", "4906": "又吸短欲躁，午后至更深为甚，热入阴中，子后清阳用事稍和。自云心中不舒，热熏脚楚。仿邪少虚多例，用仲景复脉汤。", "4907": "脉微弱而细，鼻准独明，昼日形冷汗泄，不饥少纳，脘腹常痞，泄气自舒。此阳气失护卫，而寒栗汗出，阳失鼓运，而脾胃气钝。前进养营，亦主中宫，想因血药柔软，阳不骤苏，初进甚投，接用则力疲矣。询其不喜饮汤，舌颇明润，非邪结客热之比。议用理中汤法，专以脾胃阳气是理。不独冶病，兼可转运日前之药。昔贤以疟称谓脾寒，重培生阳，使中州默运，实治法之要旨。", "4908": "劳倦伏邪，初起即用柴胡、紫苏，三阳混散，津液被劫。热邪上结，胸中懊𢙐，神烦谵语，渴欲冷饮，诊得脉无神，舌色白，病在上焦气分。阅医药不分上下气血，况冬温聘泄，老人积劳，七日未见病退机关，此属重症。岂可藐视轻谈。", "4909": "此厥症也，缘情怀失旷，肝胆郁勃，阳气直上无制。夫肝脉贯膈入胃，循绕咽喉。今病发由脘至咽，四肢逆冷。所云上升之气，自肝而出，中夹相火，其病为甚。法以苦降、辛宣、酸泄之治，使阳和气平之后，接续峻补阳明，此病必发稀。以胃土久受木戕，土虚则木易乘克也。", "4910": "此肝风夹阳，上逆为厥，得之恼怒惊忧，属七情之病。厥阴肝脉，贯膈乘胃，是以脘中不饥，不思纳谷，木犯土位也。其头晕目眩，亦肝风独行至高之地，而精华之血不得营矣。前用苦降、酸泄、辛宣，病有半月不愈，议兼重镇主之。", "4911": "形弱脉小，腰痹酸软，足跟痛，是下元精血暗亏，未老先衰，防致痿痹。温养宜柔，勿以桂、附刚愎。", "4912": "壮年形体充壮，时见眩晕，目泪暗出。前议脉濡大，便久溏，用白术益土，桑叶泄木。入冬尻骨跟痛，耳鸣。皆下少摄纳，当固其下虚，不致内风自动。", "4913": "太阳开，小水自利。阳明伤，则失其阖，浊上逆。四肢冷汗，气喘，胸腹胀闷，都是阳微欲脱，脉绝厥逆，勉与通脉四逆汤，回阳驱阴以挽之。", "4914": "服药后，脉微继者生，暴出者死。", "4915": "劳复，虚寒泄下，加以绝谷胃损，络血洞下，昏乱无神。脉诊三五参差，阴阳已属脱根，恐坏于子丑二时，真气不相维续。勉用大封固一法。", "4916": "望色萎瘁晦黯，闻声呼吸不利，语音若在瓮中，诊脉右缓左急。问初病，忽热忽温，头中如裹，腰痛欲拊扪，神识呆钝，昏昏欲寐，肢节瘛痉，咳痰映红，溺溲短缩，便溏带血，不饥不渴，环口微肿。唇干不红，舌白糜腐。此水谷酒腥，湿热相并郁蒸，阻挠清气之游行，致周身气机皆令痹塞。夫热邪、湿邪，皆气也。由募原分布三焦，营卫不主循环，升降清浊失司。邪属无形，先著气分。时师横议表邪宜汗，里滞宜消，见热投凉，殊不知热由湿郁，气行热走。仲景痉暍从湿化，忌汗、忌下，明示后人，勿伤阴阳耳！但无形之邪，久延必致有形，由气入血，一定理也。据色脉症参之，未见或可采用。", "4917": "疟有十二经，然不离少阳、厥阴。此论客邪之伤，若夹怫郁嗔怒，致厥阴肝气横逆，其势必锐。经言：肝脉贯膈入胃，上循喉咙，而疟邪亦由四末扰中，故不饥不食，胃受困也。夫治病先分气血，久发频发之恙，必伤及络，络乃聚血之所，久病血必瘀闭，香燥破血，凝滞滋血，皆是症之禁忌也，切宜凛之。", "4918": "脉左数，上热下冷，淋带不止，此内热湿郁，久则元虚。", "4919": "关格者，经言脉数俱盛四倍，阴阳结邪相离，而不复相管，羸不及于天地之精气则危矣，极言关格之不可治。前贤拟方，亦皆未尽善。愚意离愁郁结，病属七情，果难措手。今此症由甘肥积热，酒性慓悍，致伤脏腑津液，治以清通清滋，或尚可希冀。", "4920": "自失血半年以来，心悸怔忡，胁左时动。络脉空隙，营液暗伤，议甘缓平补。", "4921": "古人治胁痛法有五，或犯寒血滞，或血虚络痛，或血著不通，或肝火抑郁，或暴怒气逆，皆可致痛。今是症脉细弦数不舒，此由肝火抑郁。火郁者络自燥，治法必当清润通络。", "4922": "脉转劲，舌干赤，嗳气不展，状如呃忒。缘频吐胃伤，诸经之气上逆，填胸聚脘，出入机逆。周行脉痹，肌肉著席而痛，转加平昔辛香燥药不受，先议治肺经，以肺主一身之气化耳。", "4923": "厥者，脉动而身静谓之尸厥。此气闭于外，气血未乱，通其阳则生。今厥而脉乱，气血并走于上，如天地之郁，则沙飞水涌，莫之可当，为之大厥。此人身之根蒂空虚，三阳并羸，俟其气返则生，不返则危矣。", "4924": "汪天植脉数如浮，重按无力，发热自利，神识烦倦，咳呛痰声如嘶，渴喜热饮，此非足三阳实热之症，乃体属阴虚，冬月失藏，久伏寒邪，已经蕴遏化热。春令阳升，伏邪随气发泄，而病未及一旬，即现虚靡不振之象，因津液先暗耗于未病时也。今宗春温下利治。", "4925": "朱先生劳倦嗔怒，是七情内伤，而温邪感触，气从口鼻直自膜原中道。盖伤寒阳症，邪自太阳，次第传及，至于春温夏热，则鼻受气，肺受病，口入之气，竟由脘中，所以原有手经见症，不比伤寒足六经之病也。其原不同，治法亦异。仲景论温邪不可发汗，汗则劫津伤阳，身必灼热，一逆尚引日，再逆促命期。又云：鼻息鼾，语言难出，剧则惊痫瘛疭，无非重劫津液所致。今病发热，原不是太阳客邪见症，所投羌、防辛温表汗，此误即为逆矣。上窍不纳，下窍不便，亦属常事。必以攻下，希图泄热。殊不知强汗劫津而伤阳，妄下劫液更亡阴。顷诊脉，两手如搐而战，舌干燥而无苔，前板齿干，目欲瞑，口欲开，周身灯照，而淡晦斑纹隐隐约约，几日来时有呃逆。因胃乏谷气而中空，肝阳冲突上冒肆虐耳。为今返正，先与糜粥，使胃中得濡，厥阳不致上冒，而神昏之累可已。进药之理，甘温可以生津除热，即斑疹亦不足虑。观仲景论中，邪少虚多，阴液阳津并涸者，复脉汤主之，谨仿此义。", "4926": "起自热病，热伤阴络，血大泻，自当宗血脱益气之旨。今脉左大急疾，右小微弱，脐旁动气，肌肤枯燥，阴分大耗。正当暑月，何以堪此？拟进九龙法，通补兼施。若得动气稍减，病可平和矣。", "4927": "素有浊阴上干之症，近因湿气淫蒸，新旧合而为一，壮热吐苦水，哕，上逆，舌色微白，脉小弦。木气欲升，而复为湿遏之象也。当用苦辛以劫湿邪为主，即仲景先治新，后治痼之意也。", "4928": "脉来和静，舌苔已退，但时或烦热，胸中未适，此皆燥邪未尽之征，是以神识尚未全复，究竟必以滋燥为先。", "4929": "邪脉悉退，微迟和缓，用平调营卫，胃气自复，复脉汤主之。", "4930": "五十七岁，丰腴体质，适值过劳，阳气受伤，呕吐食物，无头痛身热，已非外感风寒，而间日烦躁渴饮，唇焦舌黑，是内伏热气，由募原以流布三焦，亦如疟邪分争营卫者然。然有年积劳既久，伏邪客病本轻，脉小缓，按之不为鼓击，可为征验，且二便颇通，略能纳谷，焉有停滞积聚？仲景于瘅热无寒之条，不出药方，但曰以饮食消息。后贤参圣意，甘寒以养胃阴，其热自解。要知表散之辛温，消滞之苦温，以及苦寒沉降，多犯圣训戒律矣。", "4931": "舌心黄边白，渴饮水浆，停胃脘欲吐，微微冷呃，自利稀水，小便不利，诊脉坚劲不和。八旬又二，暑热湿邪内著。必脾胃气苏，始可磨耐，以尊年不敢过用清消矣。议用清暑益气方。", "4932": "脉弦呕吐，心中懊𢙐，不纳水谷，倏冷忽热，虽因嗔怒七情，兼有客邪伏气，汗多不宜表散，清暑和中为正治。", "4933": "诊脉左虚大，右涩小弱。症见：目瞑短气，遗尿肢掉，神识渐迷，渴不欲饮，侵早稍安，晡时烦躁，此乃积劳元伤，热气内迫，劫烁脏液，致内风欲扰，有痉厥之虑。仲景谓：元气受伤致病，当与甘药。就暑热伤气，亦属发泄所致，东垣发明内伤暑病益气诸法，足为炳据。若动攻表里，是速其散越耳。", "4934": "脉转数，舌红。面肿消，肤痛，汗减，耳鸣，咽呛，肛痔。湿中化热乘窍，仍清气邪，佐通营卫，桂枝白虎汤主之。", "4935": "脉细数舌绛，烦渴时热，病九日，邪气稍衰，正气已亏，不宜再作有余治。", "4936": "脉软咳痰欲呕，饥时甚。虽是时邪未清，高年正虚，理宜养胃阴，金匮麦冬汤。", "4937": "先厥后热，邪气蕴伏亦久，从传染而得。今脉数舌红，头疼干呕，脘闷多痰，皆是热蒸营卫，虑其再厥。", "4938": "脉缓舌色灰黄，头疼，周身掣痛，发热不止，乃时疫湿温之症。最忌辛温重药，拟进渗湿之法。", "4939": "脉左数右缓，舌白发热，自汗，小溲溺痛，身半以上皮肤骨节掣痛。皆是湿邪有痹，虑其清窍蒙蔽，有神昏厥逆变幻，拟用轻清渗湿方。", "4940": "脉细舌灰白，渴不能多饮，膨闷不知饥。湿温半月有余，病邪虽解，余湿未尽，良由中宫阳气郁遏，失宣畅机关，故舌喜得香味。理宜护持胃阳，佐以宣浊驱湿，未可再作有余攻伐，虽取快一时，贻祸非轻小也。", "4941": "脉促神倦，目上视，咳痰欲喘，唇燥舌红，温邪发热，半月外不解，所拟发散消导之药，病不少减，正气反伤。内风乘虚上扰，虑有痉厥变幻，非轻小之恙，姑与甘缓法。", "4942": "脉虚细无力，热止后汗多，心悸头晕，寐多惊恐，舌红营阴受伤，理宜和阳存阴。", "4943": "陈诊脉左带微数，右关微弦，胸脘痞闷，右眼角赤，皆是肝木乘坤土。经旨有肾藏志，脾藏意。今梦寐惊惕，是见不藏之象。倘调养失宜，内有七情之扰，外有六淫之侮，再经反复药饵，无过树根草皮，焉能有济。故重言以申其说。", "4944": "第二案六脉略和，舌胎已退，胸脘稍宽，渴饮至胃，微觉呆滞，大便干燥。势见阴枯阳结，通阳之中，佐以润燥，亦属至理。至于调养静摄工夫，不必再赘。", "4945": "第三案立夏日诊脉，气和病情减。清晨微觉气闷，阳气尚未全振。再论人身中，阴阳二气每相眷顾，阳病久必伤阴，阴病久必伤阳，故病久之体，调养失慎，必至反复。谆谆至嘱，进苓桂术甘汤以宣上鬲之阳。", "4946": "第六案脉神俱安，大便艰涩不爽，脐间隐隐作痛。高年肾阴暗亏，血液不能灌溉四旁，肠中枯燥，更衣颇觉费力。拟进通幽汤方法以润之。", "4947": "第二案身体稍稍转动，语謇神呆，犹气机未为灵转，色脉非是有余，而湿为阴邪，不徒偏寒热已也。", "4948": "徐方鹤脉缓舌白带灰黑色，心中烦热，汗多渴饮，嘈杂如饥，肛中气坠，如欲大便。平昔苦于脱肛，病虽夹湿热，寒凉清湿热之药味难投，拟进和中法。", "4949": "徐左脉数，舌白目黄，遍身发黄，左腰胁间痹痛。卧则气逆，或嗳气，或咳呛则痛不可忍。湿热著于络中，气机阻遏不宣。况时邪一、九日，正邪势方张之候，故攻病药饵，往往难投，轻药为稳。", "4950": "潘毓翁中年冲气痰升，喘急随发随止，从肝肾本病治，固是地黄饮子，用意在浊药轻投，勿以味厚凝滞痰气，但以质能引导至下，变饮为丸，纯是浊药柔温。若归脾汤甘温守中，养脾之营，更与痰饮冲逆相背。自七月间，反复必有暑湿客气，从呼吸而受。据述肌肤间发丹疹，浮肿甚速，腠膜映红，若但内症，未必有此。思夏秋口鼻受气，上焦先伤，与肝肾本病两途。上焦失解，理必延漫中下，而三焦皆为病薮矣。此胀在乎脉络，不在腑肠，水谷无碍者缘此。况久病大虚，温补不受，必当推其至理。伏邪引动宿病，仲景论必先理其邪，且口渴便实，岂温热相宜？自言怀抱郁结，相火内寄肝胆，如茎肿囊纵，湿壅水渍。勉以三焦气分宣通方，仿古二虚一实，偏治其实，开其一面也。", "4951": "积劳伏热，值初冬温暖，天地气不收降，伏邪因之而发，是为冬温。实非暴感，表散无谓。其痰喘气促，左胁刺痛，系身中左升不已，右降失职。高年五液已衰，炎上之威莫制，脉现左细右搏，尤属阴气先伤。烦劳兼以嗔怒，亦主七情动阳。从来内伤兼症，不与外感同法。苦辛劫烁胃津，阴液日就枯槁。故仲景凡于老人虚体，必以甘药调之。夫喘咳之来，固是肺热，以诊脉、面色论之，为下虚正气不主摄纳，肾病何疑？即初起热利，亦是阴不固。拟用复脉汤。", "4952": "口中干燥，小水全无，泉源已竭，阴液无以上承，利症噤口，都是湿热壅于胃口。下元衰惫，冲脉气震高突，此攻病保真，理难捉摸。", "4953": "痢止咳频，脉虚形寒，多悸。进甘缓法，小建中去姜，加玉竹。", "4954": "稚年频频伤风咳嗽，汗出痰多，不嗜谷菜，乃卫外不固，肺易偏伤冷热。当春升气泄，忽然指握无力，走动足疲，语言或謇，常有呕恶。盖卫应乎胃，胃属阳明，其脉主司束筋骨，以流利九窍，而四肢原属脾胃，舌为心苗，脾窍通焉。此皆久伤气分，乘气泄而病，乃虚症也。治法以充脾胃脉络，疏窍诸药皆当屏绝，百日可期其效。", "4955": "脉虚数，喉干舌燥欲咳，乃阴亏于下，燥烁于上，非客病也。", "4956": "脉细咳逆，不得侧眠，肌消色夺，经水已闭，食减便溏。久病损及三阴，渐至胃气欲败，药饵难挽。拟进建中法，冀得胃旺纳谷，庶几带疾延年。", "4957": "王公美脉沉而咳，不能著枕而卧，此老年下元虚，气不摄纳。浊气痰饮，皆为阴象，乘暮夜阴时寐发。发散清润皆非，当以小青龙法，开太阳经，撤饮下趋。", "4958": "徐（十四岁）幼冲多六气之扰，少七情之伤，痛在下焦肢末，初痛必系寒湿痹阻于经络之中，方书谓为寒为痛，为湿为肿。砭刺疏通，引动脉中之气血，原得小效。寒湿邪气属阴，久蓄不得解散，蒸腐血液，变热成脓，附骨痈疡，久而精神日惫，理必延为漏卮矣。三年宿疴，寒暑迭更，邪必涣解，此为损症。凡女子二七而天癸至，谓体阴用阳也。昔因客气而致病，再因痛伤，已损及真气，诸症所称难状痼疾矣。今倐热蒸蒸，喉燥呛咳，纳食日减，乃损至精髓，草木攻邪，日加剥斫。参苓养气，难充形质。投药必不见长，无治病成法可遵。盖以有情之虚，养非气味之乘，强望胃纳扶持，至春回寒谷，再议丸方。身体热蒸多呛火升，用糯稻根须，漂、洗洁，阴干，两许煎汤。服此能退阴分燔灼之热。种植以来，不见天日，得水土之养，清而不克之药。人参非助热之药，《本草》云：阴中之阳，其气主升，故不宜单用。食少易热，咳呛，耆术归地，皆为壅滞。以人乳旋成粉，和参末捏作钱许小丸，俾濡养血中之气。藉人身之生气，胃气略好，当与景岳一气丹，制膏与服，中有红铅一味，世间无有真者，以真坎气二十四枚代之，合乎二十四气以默运耳。", "4959": "酒客伏湿，脉数，汗多，咳嗽，食不易运，病在手足太阴。", "4960": "脉细软涩，气冲失血，寐欲遗精，今纳谷不运，神思日倦，缘操持太过，上下失交，当治中焦，心脾之营自旺，诸症可冀渐复。偏热偏寒，都是斫丧真元。", "4961": "稚年吐衄，热伤为多。今脉小肌松，食少胃虚，阳升已露一斑。进甘凉益胃方。", "4962": "秋暑失血，初春再发，脉右大，颇能纳食。《金匮》云：男子脉大为劳，极虚亦为劳。要知脉大为劳，是烦劳伤气。脉虚为劳，是情欲致损。大旨病根驱尽，安静一年可愈。", "4963": "右寸浮数，余脉虚涩，失血，寒热已止，但喉中作痒咳嗽，大便又不坚固。此脾肺俱亏，正在润肺碍脾，补脾碍肺之时，清心静气，病可渐却，至嘱。", "4964": "肝主筋，肾主骨，阴器者，宗筋之所聚。男子天癸未至，强通其精，异时必有难名之病。今患腰膝酸疼，宗筋短缩，大便结涩，小便淋沥，足腿消烁，筋肉拘挛，无非肝亏肾损所致。按脉沉细而兼微数，乃精不营筋，又有伏火。《内经》所谓：发为筋痿，及为白淫者是也。治宜滋肾舒肝，使精血渐充，则筋骨亦渐和柔，但幻症日久，非一朝一夕之功，幸弗期速效。", "4965": "当夏季反复变幻，因天地气机大泄，身气久虚，无以主持，故见病治病无功，而安中纳下，每每获效，入秋常进附子七味丸颇合。今秋分节，天气降，地气收，缘久热气伤，虚体未能收肃，是以肢节时寒，头巅欲冷。无非病久诸气交馁，斯外卫之阳少护，液髓暗耗，则血脉不营，而阴乏内守。凡此皆生气之浅鲜也，急当温养益气，填补充形，使秋冬助其收藏，预为来春生发之用。《内经》有四季调神之训，今投药亦当宗此旨。", "4966": "音哑者，阳邪搏于三阴。少阴之脉循喉咙，太阴之脉连舌本，厥阴之脉出咽喉故也。然阳邪搏阴之候，正未易治。", "4967": "未交四九，天癸先绝，今年五十有二，初冬脊骨痛连腰胯，膝跗无力，动则气喘，立则伛偻，耳鸣头晕，上热下冷，呼吸必经脉闪痛，时有寒热，谷食日减少味，溺短便艰枯涩。此奇经脉病，渐成痿痹废弃之疴。夫督脉行于身后；带脉横束于腰；维、𫏋主一身之纲维。今气血索然，八脉失养。经谓：阳维为病，苦寒热，而诸脉隶肝肾，阳明之间，故所患不专一所。交冬大地气藏，天气主降，为失藏失固，反现泄越之象。治病当法古人。如云：痛则不通，痛无补法。此论邪壅气血之谓，今以络脉失养，是用补方中宣通八脉为正。冬至小寒，阳当生复，病势反加，调之得宜，天暖温煦，可冀痛止。然阳药若桂、附刚猛，风药若灵仙、狗脊之走窜，总皆劫夺耗散，用柔阳辛润通补方妥。", "4968": "肠澼下白沫者，肺气下移。经言：气并于阴，犹云阳下陷也。又云：脉沉则生，浮则危者，恐虚阳欲撒之象，而真气欲离耳。", "4969": "勉强摇精，致阳缩囊纵，不但形弱伛偻，肛门脐窍皆为收引，咽喉牵绊，自此食物渐渐减少，由精血之伤有形，最难自复。少厥两阴脉，循喉咙，开窍于二阴，既遭损伤，其气不及充注于八脉，见症皆拘束之状。上年进柔剂阳药，服后头巅经脉皆胀，耳窍愈鸣，想是藏阴宜静，试以乘舆身怖，必加局促不安，宜乎升阳之动，药不灵矣。夫少阴内藏，原有温蒸诸法，厥阴相火内寄，恶寒喜凉。仿丹溪潜阳法，仍候高明定义。", "4970": "又常夏季反复变幻，因天地气机大泄，体气久虚，无以主持，故见病治病，则无功，而安中纳下每每获效，人秋常服附子七味丸颇安。秋分节天气降，地气收，缘火热气伤，虚体未能收肃，是以肢节时寒，头巅欲冷，无非病久诸气皆馁，斯外卫之阳少护，液髓暗枯，则血脉不营，而阴乏内守，凡此皆生气之渐鲜也。急当温养益气，填补充形，使秋令助其收藏，预为来春生发之用。按《内经》有四气调神法，即今投药亦当宗此旨。", "4971": "浊腻膏淋日下，最易损人津液，络脉遂槁。况八脉隧道纡远，泛然补剂，药力罔效。《难经》谓十二经属通渠，旋转循环无端，惟奇经如沟渠，满溢流入深河，不与十二经并行者也，树根草皮，此症亦难奏效，须用血肉填补固涩，庶可希其获效。", "4972": "瓜果水寒，暴凉迅风，内外两因，舌白，渴不能饮，脘中胀满，烦不肯寐，身无热，头不疼，微呕，此足太阴中寒。已经冷汗肢厥，脉弱濡伏，医犹以疲敝方药，正如隔靴搔痒矣。", "4973": "脉缓，身痛汗出，热解复热。此水谷之气，与湿并阻于气分，郁而成热。治宜利湿宣通，气分湿去，热自解矣，徒进清热不应。", "4974": "脉右虚左弦，身麻肢冷，胎中胀闷，不饥吞酸，由中虚肝气内动之因，五六月当脾胃司胎，又体质不受苦寒，非清火酸泄气分之法所宜。", "4975": "阳明脉衰，厥阴风动，经络交亏，麻木痛痹，肢节重著，久而成痿，当以护阳之剂。", "4976": "脉濡数，中暑。暑为阳邪，昼属阳分，故张其势而烦渴。夜静属阴，邪逼于内，则多言呓语，皆由体虚邪甚致此。经谓：暑伤气。原属虚症，未敢以凝寒苦清，侵伐元气。", "4977": "脉浮缓，身热不止，汗出不为汗衰。此风湿郁表，瘀热为黄。拟麻黄连翘赤小豆汤。", "4978": "热邪入里，脘痞，按之痛，脉浮滑者，此邪结阳分，拟仲景小陷胸汤。", "4979": "脉濡涩数，至暮昏乱，身热未尽，腹痛便黑。阳明蓄血，拟仲景桃仁承气以逐其邪。", "4980": "身重，汗出，疼痛，脉浮缓。此风湿相搏于太阳之表，阳虚邪客。当通营卫以固表，拟桂枝附子汤。", "4981": "脉沉微，下利，呕逆，身痛，四肢厥冷，少阴中寒。应四逆汤，急救其里。", "4982": "脉微，下利厥逆，烦躁，面赤戴阳，显然少阴症，格阳于上也。用白通去猪胆汁，以胆汁亦损真阳也。", "4983": "脉濡，懒倦，多汗，口渴，体气素薄，炎暑烁金。当益气，保水之源。", "4984": "寒热而呕，罢则汗出，四日一发，牝疟也。「疟论」云：邪气客于六腑而有时，与卫气相失，不能相得，故休四、五日，或数日乃作也。今脉沉弦迟，发必大吐、大汗。阳气与中气乏竭，应扶阳补中，以固元气。", "4985": "脉洪大，烦渴，汗出，阳明中暍，的系白虎汤候也。", "4986": "脉沉微，腹痛，吐利，汗出，太阴寒伤，拟冷香饮子。", "4987": "凡久病必入络脉，医但写药凑方，不明入络之理，药由咽入，过胃至肠而已。此症由肝络而来，过膈入胃，胃翻呕吐。致吐致胀之由，从肝而出也。偏胜病起，务以急攻。用药如用兵，直捣中坚，使病溃散，然非入络之方，弗能效矣。议于病发之时，疏理肝木。病缓再安胃土。", "4988": "正当生旺之年，须苍色变，按：人身发属心火而炎上，眉主肝木而曲直，侧生须应肾水。内不足而色不向荣，且脉象弱芤，男子精气衰薄，不为生育之征。法当宁心神以处静，寡欲养精，妙选无病瘦弱女质，经调怡悦，无拘虑愁烦，遵三十时辰两日半之旨，庶几望其毓麟耳。", "4989": "滞痰阻经脉之气，瘀浊阻络脉之血，病甚难治。每每经水将至之候，必腹痛坚胀，上年用乌骨鸡丸，坚胀势缓痛减，不时举发。今议治法：经水来时，用回生丹三四日。经过用后方，但主宣通络血中气，可免胀满之累。", "4990": "咳呛频多，必呕吐涎沫。明理者，当知咳呛自冲脉气冲，不司收摄，为肝肾阴气不足。咽喉久痛者，缘少阴、厥阴脉循喉，阳气刻刻扰动无制，多属阴亏。脉形细动，不受温补肺药，久进必伤胃口。", "4991": "问生产频多，经水失期，此冲脉厥气直攻心下，引胁环及少腹，呕吐黑水。黑为胃底之水，便出稀黑，乃肠中之水。经年累月，病伤胃惫，何暇见病治病，务在安眠进食为议，仿仲景胃虚上逆例。", "4992": "据述布痘，调理少和，四五年来，不分冬夏，两膝骨痛，暮夜甚，必越日乃解，更述暖熨少安。知寒湿阴，气从下而受。但痘后几更寒暑不愈，经脉必有留邪之气，因新邪举发，论病名曰痹。痹者气血凝滞之义。古方活络逐邪，每施于新感则效，久则邪兴气血混处，取效颇迟，当此长夏，发泄司令，按图针刺，每五日、七日一举，经络气血流行，邪气难以容留，徒药无益，遵古方服活络丹，即再造丸，国朝喻氏谓：酒热先入肝胆，谨慎者饮之，可以壮胆。好饮多以致发疮。其酒毒颇得外泄，以分其势。疮愈，痫搐厥逆，全归肝胆矣。用药以大苦大寒，直清其下。", "4993": "瘰疬从情志易怒而来，久郁气火燔灼，值产育频经，奇经八脉不固，阳乘脉动，经来如崩，《内经》谓：阴络伤则内溢。脉来虚数，肌肉易热，阴乏不主内守，浮阳扰越外翔，形症及脉，难用温暖之药，平昔饮酒，不喜甘味滋腻，徒然参、苓，仅到中宫。凡经水于由血海而下，血海即冲脉。自述腰髀酸楚，其损已入奇经。考宋元明诸贤人，凡不受热药体质，必用震灵丹以固下，更佐能入诸经之品，通摄兼进。", "4994": "渴热向愈，自更衣用力，阴囊忽大，此宿疝举发。明明阴虚气坠，非子和七疝同法。身前陷坠，任脉失其担任。小便通调，酸甘定议。", "4995": "向来下部赤疥，湿热下注，本乎质薄肾虚，秋冬微感外邪，肺气失降，气隧为壅。水谷气蒸，变湿气阻，横渍经脉，膀胱气痹，小溲不爽，不司分别清浊，湿坠大肠便稀，痹塞自下，壅逆及上，喘息气冲，坐不得卧，俯不喜仰，甚于夜者。湿与水皆阴邪，暮夜阴用事也。夫膀胱为肾腑宜开，则水通浊泄。初因外感，太阳先受。治不得其要领。孟子谓：水搏激过颡，在人身逆而犯上射肺，则肺痹喘息矣。仲圣凡治外邪致动水寒上逆，必用小青龙汤为主。方与《内经》肿胀开鬼门取汗，洁净腑利水相符。宗是议治。", "4996": "夏至阴气不生，乃损不能复矣。今当大热，气泄愈甚，百脉诸气皆空，脂液尽耗，难望再醒，为寒为热，无非身中阴阳互乘，阳由阴上越，则顶巅痛。风木之火入中。则呕逆呛咳，总之液涸神竭。进两仪煎、琼玉膏，扶至稍凉，再为斟酌。", "4997": "初春脉动而不鼓，亦收藏之司浅矣。壮年未育，晨吐黑痰，皆水亏火炎，精气不充之象，胃旺能纳谷，当专理下焦，不必以痰为虑。", "4998": "胡朴庵脉动于右，气热易升，阴不上承，能食不能充津液，入春嗽血不止，养少阴之阴，勿苦降碍胃。", "4999": "脉涩无神，便溏食少，肛有疮疡，两月未合，已成漏症，延绵竟有痼疾之虞。近日嗔怒气扰，中焦隐痛。至于耗气劫夺，万难再饵，议进东垣益气汤减黄耆，加木瓜、白芍，用姜、南枣以制肝木。"});